pub const NativeContext = struct {
    allocator: Allocator,
    arrays: *std.ArrayListUnmanaged(*PhpArray),
    strings: *std.ArrayListUnmanaged([]const u8),
    vm: *VM,
    call_name: ?[]const u8 = null,
    // set by a native that turns down its input (intl's UTF-8 conversion)
    // while returning an error, so its wrapper answers php's failure value
    input_rejected: bool = false,
    // named arguments past the declared parameters, for a native that
    // accepts them (natives.acceptsNamedExtras)
    named_args: ?*PhpArray = null,

    pub fn createArray(self: *NativeContext) !*PhpArray {
        return self.vm.allocArray();
    }

    pub fn createString(self: *NativeContext, data: []const u8) ![]const u8 {
        const owned = try self.allocator.dupe(u8, data);
        try self.strings.append(self.allocator, owned);
        return owned;
    }

    pub fn createResource(self: *NativeContext, class_name: []const u8) !*PhpObject {
        return self.vm.newResource(class_name);
    }

    pub fn createObject(self: *NativeContext, class_name: []const u8) !*PhpObject {
        const obj = try self.vm.allocUserObject(class_name);
        try self.vm.initObjectProperties(obj, class_name);
        return obj;
    }

    pub fn callFunction(self: *NativeContext, name: []const u8, args: []const Value) RuntimeError!Value {
        return self.vm.callByName(name, args);
    }

    pub fn callMethod(self: *NativeContext, obj: *PhpObject, method: []const u8, args: []const Value) RuntimeError!Value {
        return self.vm.callMethod(obj, method, args);
    }

    pub fn setCallerVar(self: *NativeContext, arg_index: usize, arg_count: usize, value: Value) void {
        const vm = self.vm;
        if (vm.pending_ref_args) |args| {
            if (arg_index < args.len) args[arg_index] = value;
        }
        if (vm.frame_count == 0) return;
        const arg_sources = vm.callerArgSources(arg_count);
        if (arg_index >= arg_sources.len) return;
        const caller = if (vm.inNativeMethodFrame()) &vm.frames[vm.frame_count - 2] else vm.currentFrame();

        switch (arg_sources[arg_index]) {
            .cell => |c| {
                // a reference typed properties hold refuses what they can't
                // take; the TypeError stays pending for the call to raise
                const stored = if (cellOf(c.value).typed) vm.verifyRefAssignable(c.value, value) catch return vm.refuseRefWrite() else value;
                vm.setCell(c.value, stored);
                vm.propagateCellWrite(c.value, stored) catch {};
            },
            .simple => |var_name_in| {
                const var_name = var_name_in;
                if (VM.isSuperglobal(var_name)) {
                    vm.putRequestVar(var_name, value) catch {};
                    return;
                }
                if (caller.ref_slots.get(var_name)) |cell| if (cellOf(cell).typed) {
                    const stored = vm.verifyRefAssignable(cell, value) catch return vm.refuseRefWrite();
                    if (@intFromEnum(stored) != @intFromEnum(value) or !Value.identical(stored, value)) return self.setCallerVar(arg_index, arg_count, stored);
                };
                // the caller's variable is a durable holder: a named local and
                // its vars entry share one reference, so retain once and drop
                // the single reference the slot held before
                const old_var = caller.vars.get(var_name);
                var old_local: ?Value = null;
                VM.retainValue(value);
                const sn = if (caller.func) |func| func.slot_names else vm.global_slot_names;
                var slotted = false;
                for (sn, 0..) |sn_name, si| {
                    if (std.mem.eql(u8, sn_name, var_name)) {
                        if (si < caller.locals.len) {
                            old_local = caller.locals[si];
                            caller.locals[si] = value;
                            slotted = true;
                        }
                        break;
                    }
                }
                // a locals-only frame without a named mirror keeps the value
                // in its slot alone, as its own writes do
                const names_in_slots = if (caller.func) |func| func.locals_only and caller.vars.count() == 0 else false;
                if (!slotted or !names_in_slots) vm.putFrameVar(&caller.vars, var_name, value) catch return;
                // if the caller's param itself is a reference (e.g. function
                // wrap(&$r) { parse_str(..., $r); }) propagate the write
                // through the ref binding so the outer scope's variable
                // updates too. without this, native by-ref writes stop at
                // the first wrapping function
                if (caller.ref_slots.get(var_name)) |cell| {
                    vm.setCell(cell, value);
                    vm.propagateCellWrite(cell, value) catch {};
                } else if (old_var) |old| {
                    vm.releaseValue(old);
                } else if (old_local) |old| {
                    vm.releaseValue(old);
                }
            },
            .none => {},
        }
    }

    // an array's values as call arguments: in buf when they fit, else in an
    // allocation freeArgs releases
    pub fn argsFromArray(self: *NativeContext, arr: *const PhpArray, buf: []Value) ![]Value {
        const n = arr.entries.items.len;
        const out = if (n <= buf.len) buf[0..n] else try self.allocator.alloc(Value, n);
        for (arr.entries.items, 0..) |e, i| out[i] = e.value;
        return out;
    }

    pub fn freeArgs(self: *NativeContext, args: []Value, buf: []Value) void {
        if (args.len > buf.len) self.allocator.free(args);
    }

    pub fn invokeCallable(self: *NativeContext, callable: Value, args: []const Value) RuntimeError!Value {
        const outer = self.vm.native_caller;
        self.vm.native_caller = .{ .name = self.call_name, .frames = self.vm.frame_count };
        defer self.vm.native_caller = outer;
        return self.invokeCallableAsCaller(callable, args);
    }

    fn invokeCallableAsCaller(self: *NativeContext, callable: Value, args: []const Value) RuntimeError!Value {
        const callee = try self.vm.callbackCallee(callable);
        try self.warnValuesForReferences(callee, args.len);
        // an internal function that changes its array argument in place gets
        // its own copy of a value (php wraps the value in a temporary reference)
        if (callee == .function and args.len > 0 and args.len <= 16 and args[0] == .array and args[0].array.refcount > 1 and
            self.vm.native_fns.get(callee.function) != null and @import("../stdlib/byref_args.zig").arg0IsByRef(callee.function))
        {
            var copy: [16]Value = undefined;
            @memcpy(copy[0..args.len], args);
            const own = try self.vm.cloneArray(args[0].array);
            copy[0] = .{ .array = own };
            VM.retainValue(copy[0]);
            defer self.vm.releaseValue(copy[0]);
            return callables.invoke(self.vm, callee, copy[0..args.len]);
        }
        return callables.invoke(self.vm, callee, args);
    }

    // zend_call_function: an internal function hands values, so a callback
    // parameter declared by reference warns and gets a temporary instead
    fn warnValuesForReferences(self: *NativeContext, callee: callables.Callee, count: usize) RuntimeError!void {
        return self.warnValuesForReferencesMask(callee, count, &.{});
    }

    fn warnValuesForReferencesMask(self: *NativeContext, callee: callables.Callee, count: usize, is_ref: []const bool) RuntimeError!void {
        // an internal function's by-reference parameter warns the same way
        if (callee == .function and self.vm.native_fns.get(callee.function) != null) {
            const byref = @import("../stdlib/byref_args.zig");
            const name = callee.function;
            for (0..count) |i| {
                if (i < is_ref.len and is_ref[i]) continue;
                if (!byref.isByRef(name, i)) continue;
                // array_multisort and extract take values quietly
                if (std.ascii.eqlIgnoreCase(name, "array_multisort") or std.ascii.eqlIgnoreCase(name, "extract")) continue;
                const msg = try self.vm.cannotPassByReference(name, @intCast(@min(i, 255)));
                defer self.allocator.free(msg);
                // the same parameter naming as "could not be passed by reference"
                const suffix = " could not be passed by reference";
                const head = if (std.mem.endsWith(u8, msg, suffix)) msg[0 .. msg.len - suffix.len] else msg;
                const warning = try std.fmt.allocPrint(self.allocator, "{s} must be passed by reference, value given", .{head});
                defer self.allocator.free(warning);
                try self.vm.emitWarning(warning);
            }
            return;
        }
        const name: []const u8 = switch (callee) {
            .function => |n| n,
            .closure => |obj| blk: {
                if (obj.closureName()) |instance| break :blk instance;
                const inner = obj.fakeCallable();
                break :blk if (inner == .string) inner.string.bytes() else return;
            },
            else => return,
        };
        const func = self.vm.functions.get(name) orelse return;
        if (func.ref_params.len == 0) return;
        for (0..@min(count, func.ref_params.len)) |i| {
            if (i < is_ref.len and is_ref[i]) continue;
            if (!func.ref_params[i] or i >= func.params.len) continue;
            const shown = try self.vm.callableDisplayName(name, func);
            const param = func.params[i];
            const param_name = if (param.len > 0 and param[0] == '$') param[1..] else param;
            const msg = try std.fmt.allocPrint(self.allocator, "{s}(): Argument #{d} (${s}) must be passed by reference, value given", .{ shown, i + 1, param_name });
            defer self.allocator.free(msg);
            try self.vm.emitWarning(msg);
        }
    }

    // a callable called with an argument array whose string keys name
    // parameters (call_user_func_array)
    pub fn invokeCallableArgArray(self: *NativeContext, callable: Value, arr: *PhpArray) RuntimeError!Value {
        const outer = self.vm.native_caller;
        self.vm.native_caller = .{ .name = self.call_name, .frames = self.vm.frame_count };
        defer self.vm.native_caller = outer;
        return callables.invokeArgArrayFrom(self.vm, try self.vm.callbackCallee(callable), arr, true);
    }

    // positional arguments and named ones (call_user_func(f, 1, b: 2))
    pub fn invokeCallableNamed(self: *NativeContext, callable: Value, positional: []const Value, named: *PhpArray) RuntimeError!Value {
        const arr = try self.vm.argArray(positional, named);
        VM.arrayRetain(arr);
        defer {
            VM.arrayUnpin(arr);
            if (arr.refcount == 0) self.vm.queueArrayRelease(arr);
        }
        return self.invokeCallableArgArray(callable, arr);
    }

    pub fn invokeCallableRef(self: *NativeContext, callable: Value, args: []Value) RuntimeError!Value {
        const outer = self.vm.native_caller;
        self.vm.native_caller = .{ .name = self.call_name, .frames = self.vm.frame_count };
        defer self.vm.native_caller = outer;
        return self.invokeCallableRefAsCaller(callable, args);
    }

    fn invokeCallableRefAsCaller(self: *NativeContext, callable: Value, args: []Value) RuntimeError!Value {
        return callables.invokeRef(self.vm, try self.vm.callbackCallee(callable), args);
    }

    // invokeCallableRef where only args before `values_from` are references:
    // the rest are values, so a callback taking one by reference warns as
    // zend_call_function does
    pub fn invokeCallableRefWarned(self: *NativeContext, callable: Value, args: []Value, values_from: usize) RuntimeError!Value {
        var refs: [16]bool = @splat(false);
        for (0..@min(values_from, refs.len)) |i| refs[i] = true;
        return self.invokeCallableRefMask(callable, args, refs[0..@min(args.len, refs.len)]);
    }

    // invokeCallableRef where is_ref says which args are references; a
    // by-reference parameter given one of the others warns
    pub fn invokeCallableRefMask(self: *NativeContext, callable: Value, args: []Value, is_ref: []const bool) RuntimeError!Value {
        const outer = self.vm.native_caller;
        self.vm.native_caller = .{ .name = self.call_name, .frames = self.vm.frame_count };
        defer self.vm.native_caller = outer;
        const callee = try self.vm.callbackCallee(callable);
        try self.warnValuesForReferencesMask(callee, args.len, is_ref);
        return callables.invokeRef(self.vm, callee, args);
    }

    // whether the user function a callable names takes parameter i by reference
    pub fn callableParamIsRef(self: *NativeContext, callable: Value, i: usize) RuntimeError!bool {
        const callee = self.vm.callbackCallee(callable) catch {
            self.vm.discardPending();
            return true;
        };
        const func = self.calleeFunction(callee) orelse return true;
        return i < func.ref_params.len and func.ref_params[i];
    }

    fn calleeFunction(self: *NativeContext, callee: callables.Callee) ?*const ObjFunction {
        const name: []const u8 = switch (callee) {
            .function => |n| n,
            .closure => |obj| blk: {
                if (obj.closureName()) |instance| break :blk instance;
                const inner = obj.fakeCallable();
                break :blk if (inner == .string) inner.string.bytes() else return null;
            },
            .method => |m| m.registered orelse return null,
            .static_method => |m| m.registered,
            else => return null,
        };
        return self.vm.functions.get(name);
    }
};

pub const NativeResult = @import("native_result.zig").NativeResult;
const extension = @import("../extension.zig");
pub const NativeFn = *const fn (*NativeContext, []const Value) RuntimeError!NativeResult;
const natives_mod = @import("natives.zig");
pub const NativeTable = natives_mod.Table(NativeFn);
pub const Native = NativeTable.Native;
pub const NativeBinop = enum { add, sub, mul, div, mod, pow, compare, negate, bit_and, bit_or, bit_xor, bit_not, shl, shr };

pub const CaptureEntry = struct {
    closure_name: []const u8,
    var_name: []const u8,
    value: Value,
    ref_cell: ?*Value = null,
};

// where an evaluated argument came from, recorded only when the call it
// feeds may bind that position by reference. `simple` names a caller
// variable; `cell` is the canonical reference cell of a property or array
// element, carrying the error text if the current scope may not write it
// PHP_BINARY: the absolute path of the running executable, resolved once
// per process so a re-launched child (pcntl_exec, proc_open) finds it
var executable_path: []const u8 = "zphp";
var executable_path_once = sync.once(resolveExecutablePath);

fn resolveExecutablePath() void {
    executable_path = platform.selfExePathAlloc(std.heap.page_allocator) catch return;
}

pub fn executablePath() []const u8 {
    executable_path_once.call();
    return executable_path;
}

