    // is freed the VM releases this range (releaseClosureInstance)
    object: ?*PhpObject = null,
    has_statics: bool = false,
    // RefIndex owner of this instance's by-ref capture bindings
    ref_owner: RefIndex.OwnerId = 0,
};

