};

pub const ClassDef = struct {
    name: []const u8,
    methods: class_names.MethodMap(MethodInfo) = .{},
    method_order: std.ArrayListUnmanaged([]const u8) = .empty,
    properties: std.ArrayListUnmanaged(PropertyDef) = .empty,
    static_props: std.StringArrayHashMapUnmanaged(Value) = .{},
    static_prop_types: std.StringHashMapUnmanaged([]const u8) = .{},
    file_path: []const u8 = "",
    start_line: u32 = 0,
    end_line: u32 = 0,
    doc_comment: []const u8 = "",
    parent: ?[]const u8 = null,
    interfaces: std.ArrayListUnmanaged([]const u8) = .empty,
    is_enum: bool = false,
    is_internal: bool = true,
    // its hidden initializer still has to install some instance defaults
    defaults_pending: bool = false,
    // constants whose expression waits for first access hold `.undef`
    lazy_constants: bool = false,
    // a user backed enum whose case values are checked (backing type,
    // duplicates) when its constants are first updated, as php builds its
    // backed enum table
    enum_table_pending: bool = false,
    // this class or an ancestor declares a private method, so a subclass
    // redeclaring one has to look for it
    hides_methods: bool = false,
    is_abstract: bool = false,
    is_final: bool = false,
    is_readonly: bool = false,
    // an internal class whose objects take no dynamic properties, like a
    // readonly class (Directory)
    no_dynamic_properties: bool = false,
    // an internal class php refuses to clone though it holds no native handle
    uncloneable: bool = false,
    native_cleanup: ?*const fn (*PhpObject) bool = null,
    // completes `clone` after the properties are copied: a native handle, or
    // state a built-in class keeps in its properties. a class with a handle
    // and no hook is uncloneable, like php's handle classes
    native_clone: ?*const fn (*VM, *PhpObject, *PhpObject) bool = null,
    // arithmetic and comparison on instances of a native class (BcMath\Number).
    // null result means the operand pair is not supported and the ordinary
    // TypeError path runs
    native_binop: ?*const fn (*NativeContext, NativeBinop, Value, Value) RuntimeError!?Value = null,
    // the table an instance shows for an output purpose in place of its
    // properties (object_properties.zig), the way php's internal classes
    // build one
    native_properties: ?object_properties.Hook = null,
    // php's unset_dimension handler: `unset($obj[$key])` handled without
    // offsetUnset() when it returns true (SplObjectStorage's, which keeps
    // the iteration position)
    native_unset_dimension: ?*const fn (*NativeContext, *PhpObject, Value) RuntimeError!bool = null,
    // (int), (float), (bool), and the numeric conversion array_sum uses, for a
    // class whose value lives in its native handle (GMP)
    native_cast: ?*const fn (*PhpObject, @import("value.zig").NumericCast) ?Value = null,
    // set when any property-hook method ($hook_get/$hook_set) is registered on
    // this class. lets hasPropHook skip the per-access bufPrint + method lookup
    // for the >99% of classes that declare no hooks (PHP 8.4 feature). does not
    // account for inherited hooks - hasPropHook walks the parent chain
    has_prop_hooks: bool = false,
    backed_type: enum(u8) { none = 0, int_type = 1, string_type = 2 } = .none,
    case_order: std.ArrayListUnmanaged([]const u8) = .empty,
    // #[\Deprecated] constants and enum cases: what follows "is deprecated"
    // in the warning (" since 2.0, use X", or "")
    deprecated_constants: std.StringHashMapUnmanaged([]const u8) = .{},
    slot_layout: ?*PhpObject.SlotLayout = null,
    used_traits: std.ArrayListUnmanaged([]const u8) = .empty,
    attributes: std.ArrayListUnmanaged(AttributeDef) = .empty,
    method_attributes: std.StringHashMapUnmanaged([]const AttributeDef) = .{},
    property_attributes: std.StringHashMapUnmanaged([]const AttributeDef) = .{},
    // properties the class took from a trait, and which trait: their
    // attributes stay in the trait's tables
    trait_property_origins: std.StringHashMapUnmanaged([]const u8) = .{},
    param_attributes: std.StringHashMapUnmanaged([]const AttributeDef) = .{},
    // class constants and enum cases, a namespace of their own: php lets
    // `const X` and `static $X` coexist on one class
    constants: std.StringHashMapUnmanaged(Value) = .{},
    constant_order: std.ArrayListUnmanaged([]const u8) = .empty,
    constant_docs: std.StringHashMapUnmanaged([]const u8) = .{},
    static_prop_docs: std.StringHashMapUnmanaged([]const u8) = .{},
    static_prop_final: std.StringHashMapUnmanaged(void) = .{},
    const_visibility: std.StringHashMapUnmanaged(Visibility) = .{},
    constant_types: std.StringHashMapUnmanaged([]const u8) = .{},
    static_prop_visibility: std.StringHashMapUnmanaged(Visibility) = .{},
    // set visibility of static properties declared with an asymmetric one
    static_prop_set_visibility: std.StringHashMapUnmanaged(Visibility) = .{},
    const_final: std.StringHashMapUnmanaged(void) = .{},
    constant_attributes: std.StringHashMapUnmanaged([]const AttributeDef) = .{},

    pub const Visibility = enum(u8) { public = 0, protected = 1, private = 2 };

    pub const MethodInfo = struct {
        name: []const u8,
        arity: u8,
        is_static: bool = false,
        is_abstract: bool = false,
        is_final: bool = false,
        visibility: Visibility = .public,
        // ZEND_ACC_CHANGED: an ancestor has a private (or changed) method of
        // this name, so a call from that ancestor's scope may run its own
        changed: bool = false,
    };

    pub fn addMethod(self: *ClassDef, allocator: Allocator, info: MethodInfo) !void {
        const existed = self.methods.contains(info.name);
        try self.methods.put(allocator, info.name, info);
        if (!existed) try self.method_order.append(allocator, info.name);
        if (!self.has_prop_hooks and std.mem.indexOf(u8, info.name, "$hook_") != null) {
            self.has_prop_hooks = true;
        }
    }

    pub const PropertyDef = struct {
        name: []const u8,
        default: Value,
        has_default: bool = false,
        visibility: Visibility = .public,
        set_visibility: Visibility = .public,
        has_set_visibility: bool = false,
        is_readonly: bool = false,
        // enforced as readonly but declared plainly, so reflection doesn't
        // report it (DatePeriod's properties)
        readonly_undeclared: bool = false,
        is_final: bool = false,
        is_promoted: bool = false,
        is_virtual: bool = false,
        // a property with hooks, for a trait's property
        is_hooked: bool = false,
        // the trait a composed property came from
        trait_origin: []const u8 = "",
        type_str: []const u8 = "",
        doc_comment: []const u8 = "",
    };

    fn freeAttributeDefs(allocator: Allocator, attrs: []const AttributeDef) void {
        for (attrs) |a| {
            if (a.args.len > 0) allocator.free(a.args);
            if (a.arg_names.len > 0) allocator.free(a.arg_names);
        }
        allocator.free(attrs);
    }

    fn freeFunctionAttributeValue(allocator: Allocator, value: Value) void {
        if (value != .array or Value.isEmptyArrayDefault(value)) return;
        for (value.array.entries.items) |entry| freeFunctionAttributeValue(allocator, if (entry.ref) |ref| ref.* else entry.value);
        value.array.deinit(allocator);
        allocator.destroy(value.array);
    }

    pub fn freeFunctionAttributeDefs(allocator: Allocator, attrs: []const AttributeDef) void {
        for (attrs) |a| {
            for (a.args) |arg| freeFunctionAttributeValue(allocator, arg);
            if (a.args.len > 0) allocator.free(a.args);
            if (a.arg_names.len > 0) allocator.free(a.arg_names);
        }
        allocator.free(attrs);
    }

    fn deinit(self: *ClassDef, allocator: Allocator) void {
        self.methods.deinit(allocator);
        self.method_order.deinit(allocator);
        self.const_final.deinit(allocator);
        self.properties.deinit(allocator);
        self.static_props.deinit(allocator);
        self.static_prop_types.deinit(allocator);
        self.interfaces.deinit(allocator);
        self.used_traits.deinit(allocator);
        self.case_order.deinit(allocator);
        self.deprecated_constants.deinit(allocator);
        for (self.attributes.items) |a| {
            if (a.args.len > 0) allocator.free(a.args);
            if (a.arg_names.len > 0) allocator.free(a.arg_names);
        }
        self.attributes.deinit(allocator);
        var ma_iter = self.method_attributes.valueIterator();
        while (ma_iter.next()) |attrs| freeAttributeDefs(allocator, attrs.*);
        self.method_attributes.deinit(allocator);
        var pa_iter = self.property_attributes.valueIterator();
        while (pa_iter.next()) |attrs| freeAttributeDefs(allocator, attrs.*);
        self.property_attributes.deinit(allocator);
        self.trait_property_origins.deinit(allocator);
        var pra_it = self.param_attributes.iterator();
        while (pra_it.next()) |entry| {
            allocator.free(entry.key_ptr.*);
            freeAttributeDefs(allocator, entry.value_ptr.*);
        }
        self.param_attributes.deinit(allocator);
        self.constants.deinit(allocator);
        self.constant_order.deinit(allocator);
        self.const_visibility.deinit(allocator);
        self.constant_types.deinit(allocator);
        self.static_prop_visibility.deinit(allocator);
        self.static_prop_set_visibility.deinit(allocator);
        var ca_iter = self.constant_attributes.valueIterator();
        while (ca_iter.next()) |attrs| freeAttributeDefs(allocator, attrs.*);
        self.constant_attributes.deinit(allocator);
        self.constant_docs.deinit(allocator);
        self.static_prop_docs.deinit(allocator);
        self.static_prop_final.deinit(allocator);
        if (self.slot_layout) |layout| {
            allocator.free(layout.names);
            allocator.free(layout.defaults);
            allocator.free(layout.declaring_classes);
            allocator.free(layout.is_private);
            allocator.destroy(layout);
        }
    }
};

const TraitStaticProp = struct {
    name: []const u8,
    value: Value,
    doc_comment: []const u8 = "",
    // a constant's bits 0-1 visibility and bit 4 final, and its type
    flags: u8 = 0,
    type_str: []const u8 = "",
};

// where a class-like was declared, for reflection
pub const DeclSite = struct { file: []const u8 = "", start_line: u32 = 0, end_line: u32 = 0, doc_comment: []const u8 = "" };

fn declaresToString(methods: []const []const u8) bool {
    for (methods) |m| if (std.ascii.eqlIgnoreCase(m, "__toString")) return true;
    return false;
}

pub const InterfaceDef = struct {
    name: []const u8,
    methods: std.ArrayListUnmanaged([]const u8) = .empty,
    parent: ?[]const u8 = null,
    // PHP allows `interface C extends A, B` - all extended interfaces. the
    // single `parent` field is kept for code that walks one parent at a time;
    // new code should iterate `parents` so multi-extension is honored
    parents: std.ArrayListUnmanaged([]const u8) = .empty,

    fn deinit(self: *InterfaceDef, allocator: Allocator) void {
        self.methods.deinit(allocator);
        self.parents.deinit(allocator);
    }
};

// a native function or method while it runs, linked through the zig stack
// from the innermost call outward; traces show each one where php's frame
// chain would
pub const NativeCall = struct {
    // "name" or "Class::method"
    label: []const u8,
    args: []const Value,
    // the frame count when the call started, its caller being the frame below
    depth: usize,
    instance: bool,
    outer: ?*const NativeCall,
    // called by the running native itself, which a trace shows as
    // "[internal function]"
    from_native: bool = false,
};

pub const NativeInvocation = struct {
    args: []const Value,
    // what natives and by-reference bindings key off; null skips them
    name: ?[]const u8 = null,
    // php's ZEND_CALL_DYNAMIC: `$f()` or a callback, which the scope
    // introspection functions refuse
    dynamic: bool = false,
    // how a trace names the call when name is null
    label: ?[]const u8 = null,
    instance: bool = false,
};

// one message of a date parse, keyed by its byte position like php's arrays.
// messages are static strings
pub const DtMsg = struct { pos: u32 = 0, msg: []const u8 = "" };

// the messages are the date parser's static texts; timelib keeps at most
// 1000 of each kind
pub const DtLastErrors = struct {
    set: bool = false,
    warning_count: u32 = 0,
    error_count: u32 = 0,
    warnings: std.ArrayListUnmanaged(DtMsg) = .empty,
    errors: std.ArrayListUnmanaged(DtMsg) = .empty,

    pub fn clear(self: *DtLastErrors) void {
        self.set = false;
        self.warning_count = 0;
        self.error_count = 0;
        self.warnings.clearRetainingCapacity();
        self.errors.clearRetainingCapacity();
    }

    pub fn addWarning(self: *DtLastErrors, a: Allocator, pos: usize, msg: []const u8) !void {
        self.warning_count += 1;
        try self.warnings.append(a, .{ .pos = @intCast(@min(pos, std.math.maxInt(u32))), .msg = msg });
    }

    pub fn addError(self: *DtLastErrors, a: Allocator, pos: usize, msg: []const u8) !void {
        self.error_count += 1;
        try self.errors.append(a, .{ .pos = @intCast(@min(pos, std.math.maxInt(u32))), .msg = msg });
    }

    pub fn deinit(self: *DtLastErrors, a: Allocator) void {
        self.warnings.deinit(a);
        self.errors.deinit(a);
        self.* = .{};
    }
};

pub const VM = struct {
    // frames and the operand stack live in reserved regions that commit as
    // calls go deeper (ensureCallRoom), so their addresses never move
    frames: []CallFrame = &.{},
    frame_room: Region(CallFrame) = .{},
    // counts what `allocator` hands out and enforces memory_limit; the VM
    // allocates through it and it wraps the allocator the VM was built with
    memory: ?*MemoryAccount = null,
    frame_count: usize = 0,
    frame_high_water: usize = 0,
    stack: []Value = &.{},
    stack_room: Region(Value) = .{},
    sp: usize = 0,
    functions: std.StringHashMapUnmanaged(*const ObjFunction) = .{},
    function_attributes: std.StringHashMapUnmanaged([]const AttributeDef) = .{},
    // per function, the parameters marked #[\SensitiveParameter] (bit i for
    // parameter i), worked out when a trace first shows the function
    sensitive_params: std.AutoHashMapUnmanaged(usize, u64) = .{},
    native_fns: NativeTable = .{},
    // natives disable_functions removed: php code no longer sees them, but
    // internal code that calls one directly in php still can
    disabled_natives: std.StringHashMapUnmanaged(NativeTable.Native) = .{},
    // a default stored as a bare global constant failed to resolve
    bare_default_failed: bool = false,
    output: std.ArrayListUnmanaged(u8) = .empty,
    strings: std.ArrayListUnmanaged([]const u8) = .empty,
    // persistent_strings are heap-allocated keys whose lifetime must outlive
    // a serve-mode reset. anything stored as a key in native_fns (or any
    // other table that survives reset) must be allocated here, NOT in
    // self.strings (which is cleared at reset and would leave dangling
    // pointers behind in the surviving tables)
    persistent_strings: std.ArrayListUnmanaged([]const u8) = .empty,
    arrays: std.ArrayListUnmanaged(*PhpArray) = .empty,
    free_arrays: std.ArrayListUnmanaged(*PhpArray) = .empty,
    released_arrays: std.ArrayListUnmanaged(*PhpArray) = .empty,
    objects: std.ArrayListUnmanaged(*PhpObject) = .empty,
    free_objects: std.ArrayListUnmanaged(*PhpObject) = .empty,
    released_objects: std.ArrayListUnmanaged(*PhpObject) = .empty,
    next_object_id: u32 = 0,
    // handles of destroyed objects, the most recently freed last: php's
    // object store hands that one out first
    free_handles: std.ArrayListUnmanaged(u32) = .empty,
    // while a release drain destroys a value: what that destruction drops
    release_log: ?*std.ArrayListUnmanaged(ReleasedItem) = null,
    release_depth: u32 = 0,
    // the innermost running native call; a user call made at its depth comes
    // from the native itself
    native_call: ?*const NativeCall = null,
    // the frame depth a running call_user_func(_array) was called at: a
    // native it calls is called by an internal function, never strictly
    forwarding_depth: usize = std.math.maxInt(usize),
    // set once a #[\Deprecated] constant is declared: reads check for it only then
    has_deprecated_constants: bool = false,
    // #[\Deprecated] global constants: what follows "is deprecated"
    deprecated_globals: std.StringHashMapUnmanaged([]const u8) = .{},
    // php resource ids: STDIN, STDOUT and STDERR take 1-3 at init
    next_resource_id: u32 = 0,
    // php's default stream context, made on first use; it takes the next
    // resource id at that moment, which shifts the ids of later resources
    default_stream_context: ?*PhpObject = null,
    // what readdir() and friends act on when called with no handle; holds a
    // reference, as php's default directory does
    last_directory: ?*PhpObject = null,
    // serve-mode builtin persistence: stdlib classes / native methods / their
    // objects are immutable, registered once at init. reset() frees only the
    // request-scoped heap (items beyond these high-water marks) and keeps the
    // builtin classes (those in builtin_classes/_interfaces) instead of tearing
    // down + re-registering all 22 stdlib modules every request
    builtin_obj_hw: usize = 0,
    builtin_arr_hw: usize = 0,
    builtin_str_hw: usize = 0,
    builtins_recorded: bool = false,
    builtin_classes: std.StringHashMapUnmanaged(void) = .{},
    builtin_interfaces: std.StringHashMapUnmanaged(void) = .{},
    // object refcounting (Stage 1): objects whose refcount has hit 0 and are
    // awaiting __destruct. drained at statement boundaries / run end so the
    // destructor never runs while the just-released handle is still in use
    pending_destruct: std.ArrayListUnmanaged(*PhpObject) = .empty,
    destruct_cursor: usize = 0,
    draining_destructors: bool = false,
    // parameter defaults an initializer computed, held until the call's
    // frame takes them: the next default's initializer may drain releases,
    // and a call result's release is pending until then (depth: frame_count
    // when evaluated, so a nested call's loop leaves the outer ones alone)
    default_holds: std.ArrayListUnmanaged(DefaultHold) = .empty,
    // refcounting Stage 2: arrays whose refcount reached 0, awaiting element
    // release. drained alongside pending_destruct at statement boundaries
    pending_array_release: std.ArrayListUnmanaged(*PhpArray) = .empty,
    array_release_cursor: usize = 0,
    pending_string_release: std.ArrayListUnmanaged(*Value.String.Owner) = .empty,
    // Stage 2 finer generator/fiber lifetime: gen/fiber handles dropped to
    // refcount 0 are queued for closeGenerator + releaseGeneratorVars /
    // cleanupFiberFrames at the next drain. queueing (not inline close) lets
    // a transient drop-then-re-retain through a pop-then-store pattern
    // survive - the drain re-checks refcount before closing
    pending_gen_release: std.ArrayListUnmanaged(*@import("value.zig").Generator) = .empty,
    gen_release_cursor: usize = 0,
    pending_fiber_release: std.ArrayListUnmanaged(*@import("value.zig").Fiber) = .empty,
    fiber_release_cursor: usize = 0,
    // registered WeakMap instances. each WeakMap's wmConstruct appends self
    // here; on object destruct we walk this list to remove entries whose key
    // is the just-destructed object (weak semantics)
    weakmaps: std.ArrayListUnmanaged(*PhpObject) = .empty,
    // each object's WeakReference, which php creates once per target
    weak_references: std.AutoHashMapUnmanaged(*PhpObject, *PhpObject) = .{},
    // cycle collector candidate roots whose refcount decremented without
    // hitting 0. arrays need their own roots so pure array cycles are visible
    cycle_candidates: std.ArrayListUnmanaged(*PhpObject) = .empty,
    cycle_array_candidates: std.ArrayListUnmanaged(*PhpArray) = .empty,
    gc_enabled: bool = true,
    gc_runs: usize = 0,
    gc_collected: usize = 0,
    gc_threshold: usize = gc_threshold_default,
    // ref-returning function call mechanism: a `&function` sets these on
    // return_ref - the cell it's returning a reference to + the bindings
    // that propagate writes through the cell back to underlying storage
    // (array elem / object prop / static prop). caller's bind_ref_from_return
    // consumes + clears them
    last_return_ref: ?*Value = null,
    // vm-level array-element ref bindings, used for the cases where the bound
    // array OUTLIVES the binding frame: clone-propagated refs (`$d = $c` where
    // an element is a ref) and the `$arr[$k] = &$var` direction. frame-scoped
    // ref_array_bindings still cover the call-scoped paths (bindRefParams) and
    // the existing `$v = &$arr[$k]` local. propagateCellWrite scans BOTH; an
    // entry is bound in exactly one list. cleared at reset (request lifetime)
    array_ref_bindings: std.ArrayListUnmanaged(ArrayRefBinding) = .empty,
    persistent_ref_owner: RefIndex.OwnerId = 0,
    last_return_ref_owner: RefIndex.OwnerId = 0,
    // pointer to the $GLOBALS PhpArray for the current run, used so writes
    // to $GLOBALS[key] = val also propagate to the top frame's variable
    // table (matching PHP's superglobal semantics)
    globals_array: ?*PhpArray = null,
    rng_seeded: bool = false,
    rng_state: std.Random.DefaultPrng = std.Random.DefaultPrng.init(0),
    mt19937: @import("../stdlib/mt19937.zig").Mt19937 = .{},
    obj_id_base: usize = 0,
    generators: std.ArrayListUnmanaged(*Generator) = .empty,
    free_generators: std.ArrayListUnmanaged(*Generator) = .empty,
    fibers: std.ArrayListUnmanaged(*Fiber) = .empty,
    free_fibers: std.ArrayListUnmanaged(*Fiber) = .empty,
    ref_cells: std.ArrayListUnmanaged(*RefCell) = .empty,
    free_cells: std.ArrayListUnmanaged(*RefCell) = .empty,
    current_fiber: ?*Fiber = null,
    fiber_suspend_pending: bool = false,
    // destructors run from the release drain, a zig call that can't be
    // suspended across: a Fiber::suspend in one would lose the drain and
    // resume in the destructor's frame, so it throws instead (php can).
    // a fiber started inside the destructor suspends within itself, so
    // each fiber run starts unblocked
    fiber_switch_blocked: u32 = 0,
    // php's GC_G(dtor_fiber): garbage found while a fiber runs has its
    // destructors called in a fiber of their own, so one may suspend. the
    // fiber is kept for the next collection until a destructor suspends it
    gc_dtor_fiber: ?*Fiber = null,
    gc_dtors_in_fiber: bool = false,
    // objects the destructors of the current collection revived
    gc_revived: usize = 0,
    fiber_suspend_value: Value = .null,
    // what unwinds a destroyed generator through its finally blocks: no
    // catch matches it and nothing chains it, as php jumps straight to the
    // finally blocks (zend_generator_dtor_storage). never a script value
    unwind_marker: ?*PhpObject = null,
    // a destructor or a destroyed generator's finally block run by a release
    // drain left its exception pending, for the code that released the
    // value to raise (php's zend_objects_destroy_object)
    drain_raised: bool = false,
    // the cli runs the shutdown destructors itself, after the shutdown
    // functions and the report of an uncaught exception, in php's order
    destructors_after_shutdown: bool = false,
    // the script ended on a fatal error (php's unclean shutdown): the
    // shutdown destructors are skipped
    unclean_shutdown: bool = false,
    // the name the last bind_ref_from_return bound a copy of the value to,
    // the call having returned no reference
    ref_bind_degraded: ?[*]const u8 = null,
    // last_return_ref is what the call whose reference is being bound handed
    // back: a return_ref set it since reset_return_ref ran before the call
    return_ref_fresh: bool = false,
    // where the caller of a function returning by reference resumes when
    // that function returned no variable (php still hands back a reference)
    return_ref_value_at: ?struct { frame: usize, ip: usize } = null,
    // the destructors php's request shutdown runs, with no script running
    shutdown_destructors: bool = false,
    captures: std.ArrayListUnmanaged(CaptureEntry) = .empty,
    capture_index: std.StringHashMapUnmanaged(CaptureRange) = .{},
    interned_names: std.StringHashMapUnmanaged(void) = .{},
    // generators and fibers are collector nodes too (php's get_gc handlers):
    // what a waiting one holds is part of the graph. the candidates are the
    // ones a release left referenced, as php's root buffer has them
    cycle_gens: std.AutoArrayHashMapUnmanaged(*Generator, i64) = .{},
    cycle_fibers: std.AutoArrayHashMapUnmanaged(*Fiber, i64) = .{},
    cycle_gen_candidates: std.ArrayListUnmanaged(*Generator) = .empty,
    cycle_fiber_candidates: std.ArrayListUnmanaged(*Fiber) = .empty,
    // the cycle collector's walk stack, kept for its capacity
    cycle_work: std.ArrayListUnmanaged(CycleWork) = .empty,
    collecting_cycles: bool = false,
    closure_instance_count: u32 = 0,
    // the closure instances self.functions holds: no call site names one, so
    // creating or freeing one leaves every call site's callee as it was
    live_closure_instances: usize = 0,
    captures_dead: usize = 0,
    debug_no_pool: bool = false,
    debug_gc_verify: bool = false,
    stat_deferred_stack: usize = 0,
    gc_zero_sites: std.AutoHashMapUnmanaged(*PhpArray, GcZeroSite) = .{},
    stat_deferred_container: usize = 0,
    debug_trace_class: ?[]const u8 = null,
    // set while freeHeapItems bulk-frees the heap: the deferred queues then
    // reference structures that are already gone, so drains must not run
    heap_teardown: bool = false,
    // the caller frame's called class before a static call to a native
    // replaced it with the class the call named: a native that resolves a
    // callback in its caller's scope (Closure::fromCallable) reads this one
    static_native_outer_called: ?[]const u8 = null,
    // named arguments a variadic user function's frame adds to its variadic
    // (callables.invokeArgArray sets them for the call it makes)
    pending_named_extras: ?*PhpArray = null,
    // named arguments a native that accepts them (call_user_func) gets past
    // its declared parameters; invokeNative hands them to the native's context
    native_named_args: ?*PhpArray = null,
    // the next callNamedFunction is a dynamic call (`$f()`)
    pending_dynamic_call: bool = false,
    // php's IS_PROP_REINITABLE: while __clone runs on a clone, and while
    // clone() assigns its properties, each initialized readonly property of
    // the clone may be written once more. a window per clone in progress,
    // with the properties already written again
    reinit_windows: std.ArrayListUnmanaged(ReinitWindow) = .empty,
    // classes whose declaration is loading their parent: php's unlinked
    // classes, which variance checks see (ZEND_FETCH_CLASS_ALLOW_UNLINKED)
    // while nothing else does. used: a check depended on one, so its
    // declaration can no longer fail with an exception
    linking: std.ArrayListUnmanaged(Linking) = .empty,
    // CG(delayed_autoloads): classes method checks needed and didn't load,
    // loaded when a class with obligations is registered
    delayed_autoloads: std.ArrayListUnmanaged([]const u8) = .empty,
    // classes registered while their obligations resolve (php's nearly
    // linked): a subclass declared meanwhile loads the delayed classes too
    nearly_linked: std.ArrayListUnmanaged(NearlyLinked) = .empty,
    // obligations the trait method checks of the class being declared began
    trait_deferred: std.ArrayListUnmanaged(*inheritance.Deferred) = .empty,
    free_closure_names: std.ArrayListUnmanaged(struct { compile_name: []const u8, name: []const u8 }) = .empty,
    php_constants: std.StringHashMapUnmanaged(Value) = .{},
    user_constants: std.StringHashMapUnmanaged(void) = .{},
    // traits declared #[\Deprecated], with what the warning adds after
    // "is deprecated"
    deprecated_traits: std.StringHashMapUnmanaged([]const u8) = .{},
    // the constant whose #[\Deprecated] message is being evaluated: reading
    // it there doesn't warn again
    describing_deprecated: ?struct { class: []const u8, name: []const u8 } = null,
    // a global constant's attribute entry in function_attributes, set when
    // the `const` declaring it defines it
    constant_attributes: std.StringHashMapUnmanaged([]const u8) = .{},
    ini_settings: std.StringHashMapUnmanaged([]const u8) = .{},
    ini_callbacks: std.StringHashMapUnmanaged(Value) = .{},
    // register_shutdown_function's callables with the arguments they get
    shutdown_callbacks: std.ArrayListUnmanaged(ShutdownCallback) = .empty,
    // register_tick_function's callbacks, run by declare(ticks) code
    tick_functions: std.ArrayListUnmanaged(TickFunction) = .empty,
    ticks_count: u32 = 0,
    tick_function_ids: u64 = 0,
    strtok_state: ?[]const u8 = null,
    strtok_pos: usize = 0,
    classes: class_names.AliasMap(ClassDef) = .{},
    interfaces: class_names.AliasMap(InterfaceDef) = .{},
    traits: class_names.AliasMap(void) = .{},
    trait_uses: std.StringHashMapUnmanaged([]const []const u8) = .{},
    trait_rules: std.StringHashMapUnmanaged(TraitRules) = .{},
    trait_props: std.StringHashMapUnmanaged([]const ClassDef.PropertyDef) = .{},
    trait_static_props: std.StringHashMapUnmanaged([]const TraitStaticProp) = .{},
    // trait_name -> its methods. applyTrait otherwise scans the ENTIRE
    // self.functions table (every method in the program) on every trait-use to
    // find `Trait::method` entries - O(total_functions) per use, the dominant
    // cost re-bootstrapping a trait-heavy framework (Laravel) each serve request.
    // persistent across reset: serve caches bytecode so the trait-method func
    // pointers are stable, and a trait's method set doesn't change between
    // requests (eval-redefining a trait mid-run is the only staleness case)
    trait_method_cache: std.StringHashMapUnmanaged([]TraitMethodEntry) = .{},
    trait_constants: std.StringHashMapUnmanaged([]const TraitStaticProp) = .{},
    statics: std.StringHashMapUnmanaged(Value) = .{},
    statics_cells: std.StringHashMapUnmanaged(*Value) = .{},
    // shared heap cell per global variable name. allocated on first `global $x`
    // declaration so every function frame referencing the same global gets a
    // pointer to the same value. lets writes propagate live to recursive calls
    globals_cells: std.StringHashMapUnmanaged(*Value) = .{},
    pending_call_name: ?[]const u8 = null,
    // set while $closure->__invoke() enters the closure: php calls it from
    // the internal Closure::__invoke, so its argument errors name no call
    // site and are never strict
    invoking_closure: bool = false,
    // the native whose callback is being called (array_map, usort, ...) and
    // the frame depth it called from; a deeper frame means php code calls
    native_caller: struct { name: ?[]const u8 = null, frames: usize = 0 } = .{},
    // late-static-binding class for the next executeFunction frame. set by
    // callMethod (the native-side method dispatch used by reflection
    // newInstance, __toString, etc.) so static::class inside the called method
