    // consumed (and cleared) by the executeFunction* frame setup
    pending_called_class: ?[]const u8 = null,
    // args slice for invocations driven from native code (callByName-style).
    // executeFunction consumes this to seed fga_buf so func_get_args inside
    // the called function sees the real args, not stale data from whatever
    // last used this frame slot
    pending_invoke_args: ?[]const Value = null,
    pending_ref_args: ?[]Value = null,
    static_vars: std.ArrayListUnmanaged(StaticEntry) = .empty,
    global_vars: std.ArrayListUnmanaged(StaticEntry) = .empty,
    file_loader: ?*const FileLoader = null,
    // canonical directory paths keyed by the spelling a require used, so a
    // file load costs one lstat instead of a realpath per file
    realdir_cache: std.StringHashMapUnmanaged([]const u8) = .{},
    // the url wrappers in php's registration order: builtins (class null)
    // and user classes from stream_wrapper_register; filled on first use
    stream_wrappers: std.StringArrayHashMapUnmanaged(StreamWrapperEntry) = .{},
    stream_wrappers_ready: bool = false,
    // filter name -> user filter class registered via stream_filter_register,
    // in registration order (stream_get_filters lists them)
    stream_filters_user: std.StringArrayHashMapUnmanaged([]const u8) = .{},
    compile_results: std.ArrayListUnmanaged(*CompileResult) = .empty,
    error_msg: ?[]const u8 = null,
    exit_requested: bool = false,
    // php keeps a C int; posix keeps its low byte, windows all 32 bits
    exit_code: i32 = 0,
    source: []const u8 = "",
    file_path: []const u8 = "",
    autoload_callbacks: std.ArrayListUnmanaged(Value) = .empty,
    // spl_autoload_extensions(), null for php's default ".inc,.php"
    spl_autoload_extensions: ?[]u8 = null,
    autoload_depth: u8 = 0,
    // when a required script does an early `return X` at top level, the
    // return op pops its frame before the require handler runs the merge.
    // require sets this to the about-to-be-popped frame depth before
    // runUntilFrame; popFrame skips deinit and leaves the slot intact so
    // the require handler can read the include frame's locals/vars
    require_merge_depth: usize = 0,
    // php's property guards: the property magic methods running for an
    // object and property name, which aren't entered again for the same pair
    magic_guards: std.ArrayListUnmanaged(MagicGuard) = .empty,
    magic_call_guard: std.ArrayListUnmanaged(struct { obj_ptr: usize, method_name: []const u8 }) = .empty,
    prop_hook_guard: std.ArrayListUnmanaged(struct { obj_ptr: usize, prop_name: []const u8 }) = .empty,
    user_error_handler: ?Value = null,
    user_error_handler_mask: i64 = -1,
    user_exception_handler: ?Value = null,
    // stack of previously-installed exception handlers. set_exception_handler
    // pushes, restore_exception_handler pops - PHP exposes a real LIFO of
    // installed handlers (mirrors the older error_handler_stack)
    exception_handler_stack: std.ArrayListUnmanaged(?Value) = .empty,
    // pool of frame.vars hashmaps. each entry's buckets stay allocated; on
    // recycle we clear() instead of deinit() so the next acquisition skips
    // the initial bucket alloc. recursive-call heavy workloads previously
    // mmap'd a fresh bucket array per call - this turns it into a pop()
    vars_pool: std.ArrayListUnmanaged(std.StringHashMapUnmanaged(Value)) = .empty,
    error_handler_stack: std.ArrayListUnmanaged(ErrorHandlerEntry) = .empty,
    error_silenced_depth: u32 = 0,
    // php's EH_THROW error handling, which some internal methods switch on
    // while they run: a warning becomes an exception of this class instead
    // of being reported, and no user error handler sees any diagnostic.
    // `from` is the message prefix of the function a native delegates to,
    // rewritten to `to`, the method php's active function is
    eh_throw: ?EhThrow = null,
    // the frame depth a native offsetGet/offsetSet runs at when the vm calls
    // it for `$obj[]`, which it passes as a null offset; SplFixedArray
    // refuses the append where it would refuse `$obj[null]` otherwise
    dim_append_depth: usize = std.math.maxInt(usize),
    last_error_type: i64 = 0,
    last_error_message: []const u8 = "",
    last_error_file: []const u8 = "",
    last_error_line: i64 = 0,
    prev_error_handler: ?Value = null,
    error_reporting_level: i64 = 30719,
    ob_stack: std.ArrayListUnmanaged(OutputBufferLevel) = .empty,
    // the level whose handler is running, output buffering refused meanwhile
    ob_running: ?usize = null,
    // set once a handler misused output buffering: no buffer starts again
    ob_deactivated: bool = false,
    // some level has a chunk size, so an echo checks whether it filled
    ob_chunk_watch: bool = false,
    ob_next_id: u64 = 0,
    request_vars: std.StringHashMapUnmanaged(Value) = .{},
    profile_calls: std.StringHashMapUnmanaged(u64) = .{},
    // ZPHP_DBG_PROFILE env check cached at init. previously each native and
    // method dispatch called posix.getenv. macOS appears to cache getenv
    // internally so end-to-end perf didn't move measurably, but the call
    // showed up in profiles as a stable mid-tier hot spot and the cached
    // bool is strictly cheaper plus removes a syscall surface
    dbg_profile_enabled: bool = false,
    // maps a phar alias (the name registered via Phar::mapPhar) to the on-disk
    // archive path. populated by Phar::mapPhar()/Phar::loadPhar() and read by
    // the phar:// stream wrapper to resolve `phar://alias/internal/path`
    phar_aliases: std.StringHashMapUnmanaged([]const u8) = .{},
    // chunk-ptr → all registered function names whose chunk lives at that
    // pointer. populated at every self.functions.put site (registerFunction,
    // trait flattening, closure-instance/bound creation). lets
    // currentDefiningClass / closureScopeForFrame / parentResolvingClass
    // resolve a frame's class scope in O(K) (K = small) instead of O(N)
    // iterating self.functions (grows large in framework-heavy workloads).
    chunk_to_func_names: std.AutoHashMapUnmanaged(usize, std.ArrayListUnmanaged([]const u8)) = .{},
    // the lowercased short names (after "::" or the namespace) of every
    // registered user function or method with a by-reference parameter. a
    // call site whose name isn't here takes its arguments by value, which
    // spares the argument guards a full resolution of the callee
    ref_param_names: std.StringHashMapUnmanaged(void) = .{},
    // class or trait name -> its "Name::method" keys in self.functions, kept
    // beside chunk_to_func_names, so a trait's methods are found without
    // scanning every function
    method_names_by_class: std.StringHashMapUnmanaged(std.ArrayListUnmanaged([]const u8)) = .{},
    // chunk-ptr → owning CompileResult, for every main chunk and function
    // chunk. declare_fn resolves its conditionally-declared function through
    // the executing frame's chunk here. entries are overwritten on
    // re-registration so stale pointers from freed results are never read by
    // a live chunk
    chunk_to_result: std.AutoHashMapUnmanaged(usize, *const CompileResult) = .{},
    // cache of parsed phars by archive path so each require_once doesn't
    // re-read + re-parse the entire archive (large phars with many internal
    // entries can pile up GBs of redundant reads otherwise)
    phar_cache: std.StringHashMapUnmanaged(*PharCacheEntry) = .{},
    exception_handlers: []ExceptionHandler = &.{},
    // exceptions finally blocks are running for: one that unwinds out of the
    // block becomes the previous of the exception unwinding it (php's
    // cleanup_live_vars). each sits at `slot` on the operand stack of frame
    // `frame` until the block rethrows it
    held_exceptions: std.ArrayListUnmanaged(HeldException) = .empty,
    // classes whose constant expressions are being evaluated, innermost
    // last: php evaluates them in the class's scope
    initializer_scopes: std.ArrayListUnmanaged(InitializerScope) = .empty,
    // class constants being evaluated by another constant's expression
    // (php's IS_CONSTANT_VISITED), and how deep evaluation is nested
    constants_visited: std.ArrayListUnmanaged([2][]const u8) = .empty,
    constant_eval_depth: u32 = 0,
    // trait constants waiting for the using class's own value
    trait_constant_checks: std.ArrayListUnmanaged(struct { class: []const u8, name: []const u8, trait: []const u8, value: Value }) = .empty,
    // a trait property's default waiting for the class's own to be installed
    // (set_prop_default), as trait_constant_checks
    trait_property_checks: std.ArrayListUnmanaged(struct { class: []const u8, name: []const u8, trait: []const u8, value: Value }) = .empty,
    // while traits compose into a class, which trait first gave each
    // constant it didn't declare itself
    trait_constant_sources: std.StringHashMapUnmanaged([]const u8) = .{},
    // ReflectionClass::newLazyProxy is running (for its errors' wording)
    lazy_proxy_request: bool = false,
    // each trait's function table with its own `use` bound (traitTable)
    trait_tables: std.StringHashMapUnmanaged([]TraitMethod) = .{},
    trait_tables_retired: std.ArrayListUnmanaged([]TraitMethod) = .empty,
    // the copies of trait methods classes were given (traitMethodCopy), by
    // "Class::method"
    trait_method_copies: std.StringHashMapUnmanaged(*ObjFunction) = .{},
    trait_method_stale: std.ArrayListUnmanaged(*ObjFunction) = .empty,
    // classes marked lazy_constants
    lazy_constant_classes: usize = 0,
    // the class a class constant fetch names, as written: php's
    // self-reference error quotes it
    class_const_written: []const u8 = "",
    handler_room: Region(ExceptionHandler) = .{},
    handler_count: usize = 0,
    handler_floor: usize = 0,
    pending_exception: ?Value = null,
    // set while attribute arguments are resolved at declaration: php
    // evaluates them only when reflection asks, so nothing may run or throw
    // then, and an argument that needs either stays deferred
    resolving_quietly: bool = false,
    // when true, the current pending_exception is a fatal that cannot be caught
    // by user try/catch. used for execution-deadline timeouts; PHP's
    // `Maximum execution time exceeded` is an uncatchable fatal there too
    uncatchable_fatal: bool = false,
    run_base_frame: usize = 0,
    allocator: Allocator,
    string_pool: @import("string_pool.zig") = .{ .backing = undefined },
    global_slot_names: []const []const u8 = &.{},
    script_strict_types: bool = false,
    // most recent ICU UErrorCode from any intl native call. reset to 0 on entry
    // to each intl call (except intl_get_error_*/intl_is_failure/intl_error_name)
    // and bumped to the failing status when an op fails
    last_intl_error_code: i32 = 0,
    // the slot_names of the top script frame (frame[0]). global_slot_names
    // is temporarily overridden during require/include to point at the inner
    // file's slot_names; writebacks to frame[0]'s locals must use the top
    // script's layout, not the most-recently-required file's
    top_slot_names: []const []const u8 = &.{},
    global_vars_dirty: bool = false,
    // hasMethod single-entry cache. method dispatch repeatedly probes the
    // same (class, method) pair per call site (decide method-call vs __call
    // fallback) - this skips the bufPrint("{s}::{s}") cost on hits
    has_method_cache_class_storage: [256]u8 = undefined,
    has_method_cache_method_storage: [256]u8 = undefined,
    has_method_cache_class: []const u8 = "",
    has_method_cache_method: []const u8 = "",
    has_method_cache_result: bool = false,
    // snapshot of total registered function/class count when has_method_cache
    // was last populated. used to detect when a new func/class registration
    // could invalidate a previous cache hit
    has_method_cache_fn_count: usize = 0,
    has_method_cache_cls_count: usize = 0,
    // hasPropHook single-entry cache. saves bufPrint('{prop}$hook_{kind}')
    // before delegating to hasMethod. kind packed into low bit of the cls
    // count snapshot
    has_hook_cache_class: []const u8 = "",
    has_hook_cache_prop: []const u8 = "",
    has_hook_cache_kind: u2 = 0,
    has_hook_cache_result: bool = false,
    // a user class with a property hook exists; until one does, no property
    // access needs a hook lookup
    any_prop_hooks: bool = false,
    has_hook_cache_fn_count: usize = 0,
    has_hook_cache_cls_count: usize = 0,
    ic: ?*InlineCache = null,
    serve_mode: bool = false,
    // deadline enforcement for set_time_limit / max_execution_time. 0 means
    // unlimited (PHP CLI default). non-zero is a monotonic-clock nanosecond
    // wall (after which any backwards jump or function entry throws a fatal
    // Error). polling is gated by deadline_tick_counter to keep overhead low
    execution_deadline_ns: i64 = 0,
    execution_limit_seconds: i64 = 0,
    deadline_tick_counter: u32 = 0,
    serve_compile_cache: std.StringHashMapUnmanaged(*CompileResult) = .{},
    serve_cache_keys: std.ArrayListUnmanaged([]const u8) = .empty,
    response_code: i64 = 200,
    response_headers: ?*PhpArray = null,
    last_http_response_headers: ?*PhpArray = null,
    headers_sent: bool = false,
    default_tz_name: []const u8 = "UTC",
    // backing for a zone set by date_default_timezone_set(); zone ids are short
    default_tz_buf: [64]u8 = undefined,
    // warnings and errors of the last DateTime parse (constructor, modify,
    // createFromFormat), for DateTime::getLastErrors(), which returns false
    // when that parse had none
    last_dt: DtLastErrors = .{},
    default_tz_offset: i32 = 0,
    // set true once any `$r = &$obj->prop` / `&Class::$static` reference binding
    // is created. lets writes to a prop/static-prop skip the ref-cell sync walk
    // entirely in the common case (no such reference exists). reset() clears it
    obj_ref_active: bool = false,
    // set true once any `$arr[$k] = &$var` / `$v = &$arr[$k]` array-element
    // reference binding exists. lets array reads/writes/clones/foreach skip the
    // per-entry `ref` check in the common case. reset() clears it
    array_ref_active: bool = false,
    // set by an argument guard whose callee takes that position by reference
    // or cannot be resolved yet; consumed by the fetch opcode right after it
    arg_capture_pending: bool = false,
    // exclusive high-water mark of provenance writes in ic.arg_stack,
    // independent of sp: fastLoop pops values without visiting the transport
    arg_source_end: usize = 0,
    // cell-keyed reference-binding registry (O(1) propagateCellWrite + prop sync).
    // lazily allocated on first ref binding so non-ref programs pay one nullable
    // pointer and nothing else. coexists with the legacy frame/vm binding lists
    // during the phased migration; the guards above gate access. freed at deinit,
    // cleared at reset
    ref_index: ?*RefIndex = null,

    // live proc_open children, keyed by their ProcessResource object. lazily
    // allocated (a single nullable pointer, fib-neutral like ref_index above) the
    // first time proc_open spawns. each *Child outlives its native call so
    // proc_close can wait() it; reapProcChildren SIGKILL+wait+frees any that the
    // script opened but never closed, so serve mode doesn't leak fds or zombies
    proc_children: ?*ProcChildMap = null,

    fn procChildren(self: *VM) RuntimeError!*ProcChildMap {
        if (self.proc_children) |pc| return pc;
        const pc = try self.allocator.create(ProcChildMap);
        pc.* = .{};
        self.proc_children = pc;
        return pc;
    }

    // proc_close: every pipe closed and its stream released. reap only closes,
    // since it runs where the heap is about to be freed wholesale
    pub fn closeProcChild(self: *VM, proc: *PhpObject) void {
        const pc = self.lookupProcChild(proc) orelse return;
        for (pc.pipe_fds.items) |*pipe| {
            pipe.close();
            if (pipe.handle) |handle| self.objRelease(handle);
            pipe.handle = null;
        }
        pc.pipe_fds.deinit(self.allocator);
        self.removeProcChild(proc);
    }

    // hands the $pipes stream for a role to the child entry, which owns it
    pub fn adoptProcPipe(self: *VM, proc: *PhpObject, role: i64, handle: *PhpObject) void {
        const pc = self.lookupProcChild(proc) orelse return;
        for (pc.pipe_fds.items) |*pipe| if (pipe.role == role) {
            handle.retain();
            pipe.handle = handle;
            return;
        };
    }

    pub fn registerProcChild(self: *VM, proc: *PhpObject, pid: platform.Pid, pipe_fds: std.ArrayListUnmanaged(ProcPipe)) RuntimeError!void {
        try (try self.procChildren()).put(self.allocator, proc, .{ .pid = pid, .reaped = false, .pipe_fds = pipe_fds });
    }

    // returns a pointer into the map (valid until the next put). callers read
    // .child/.reaped and may set .reaped, but must copy out .child before any
    // removeProcChild (which invalidates the pointer)
    pub fn lookupProcChild(self: *VM, proc: *PhpObject) ?*ProcChild {
        const pc = self.proc_children orelse return null;
        return pc.getPtr(proc);
    }

    pub fn removeProcChild(self: *VM, proc: *PhpObject) void {
        const pc = self.proc_children orelse return;
        _ = pc.remove(proc);
    }

    // reap every still-live child. an un-reaped pid is SIGKILL'd + waited (one
    // waitpid per pid - again would ECHILD->unreachable); on windows the
    // process handle is terminated, waited, and closed. then any parent-side
    // pipe fd the script never fclose'd is closed. runs at reset (before
    // freeHeapItems) and deinit; clears the map after
    fn reapProcChildren(self: *VM) void {
        const pc = self.proc_children orelse return;
        var it = pc.valueIterator();
        while (it.next()) |entry| {
            if (platform.is_windows) {
                reapWindowsChild(entry);
            } else {
                if (!entry.reaped) {
                    std.posix.kill(entry.pid, std.posix.SIG.KILL) catch {};
                    _ = sys.waitpid(entry.pid, 0);
                }
                for (entry.pipe_fds.items) |*pipe| pipe.close();
            }
            entry.pipe_fds.deinit(self.allocator);
        }
        pc.clearRetainingCapacity();
    }

    fn reapWindowsChild(entry: *ProcChild) void {
        const win32 = @import("../win32.zig");
        if (entry.process != 0) {
            const handle: win32.HANDLE = @ptrFromInt(entry.process);
            if (!entry.reaped) {
                _ = win32.TerminateProcess(handle, 255);
                _ = win32.WaitForSingleObject(handle, win32.INFINITE);
            }
            _ = win32.CloseHandle(handle);
            entry.process = 0;
        }
        for (entry.pipe_fds.items) |*pipe| pipe.close();
    }

    fn newRefCell(self: *VM) RuntimeError!*Value {
        const cell = self.free_cells.pop() orelse blk: {
            const c = try self.allocator.create(RefCell);
            errdefer self.allocator.destroy(c);
            try self.ref_cells.append(self.allocator, c);
            break :blk c;
        };
        cell.* = .{};
        return &cell.value;
    }

    fn bindCell(_: *VM, value: *Value) void {
        const cell = cellOf(value);
        std.debug.assert(!cell.dead);
        cell.binders += 1;
    }

    fn cellUnbindHook(ctx: *anyopaque, value: *Value) void {
        const self: *VM = @ptrCast(@alignCast(ctx));
        self.unbindCell(value);
    }

    fn unbindCell(self: *VM, value: *Value) void {
        if (self.heap_teardown) return;
        const cell = cellOf(value);
        if (cell.dead) return;
        std.debug.assert(cell.binders > 0);
        cell.binders -= 1;
        if (cell.binders != 0) return;
        cell.dead = true;
        const old = cell.value;
        cell.value = .null;
        if (self.ref_index) |ri| ri.removeCell(self.allocator, value);
        if (self.array_ref_active) {
            var i: usize = 0;
            while (i < self.array_ref_bindings.items.len) {
                if (self.array_ref_bindings.items[i].cell == value) _ = self.array_ref_bindings.swapRemove(i) else i += 1;
            }
        }
        if (self.debug_gc_verify) self.gcVerifyDeadCell(value);
        self.releaseValue(old);
        self.free_cells.append(self.allocator, cell) catch {};
    }

    fn gcVerifyDeadCell(self: *VM, cell: *Value) void {
        var holders: usize = 0;
        for (self.frames[0..self.frame_count]) |*frame| holders += countCellMap(&frame.ref_slots, cell);
        for (self.generators.items) |g| if (!g.pooled) {
            holders += countCellMap(&g.ref_slots, cell);
        };
        for (self.fibers.items) |f| if (!f.pooled) {
            for (f.saved_frames.items) |*frame| holders += countCellMap(&frame.ref_slots, cell);
        };
        holders += countCellMap(&self.globals_cells, cell);
        holders += countCellMap(&self.statics_cells, cell);
        for (self.captures.items) |capture| if (capture.ref_cell == cell) {
            holders += 1;
        };
        for (self.arrays.items) |arr| if (!arr.pooled) {
            for (arr.entries.items) |entry| if (entry.ref == cell) {
                holders += 1;
            };
        };
        if (self.last_return_ref == cell) holders += 1;
        if (self.ref_index) |ri| if (ri.fwd.contains(cell)) {
            holders += 1;
        };
        if (holders != 0) {
            std.debug.print("gc-verify: dead ref cell {*} still has {d} binders\n", .{ cell, holders });
            @panic("reference cell binder accounting");
        }
    }

    fn countCellMap(map: *std.StringHashMapUnmanaged(*Value), cell: *Value) usize {
        var count: usize = 0;
        var it = map.valueIterator();
        while (it.next()) |c| if (c.* == cell) {
            count += 1;
        };
        return count;
    }

    const superglobal_names = [_][]const u8{ "$_SERVER", "$_GET", "$_POST", "$_FILES", "$_COOKIE", "$_SESSION", "$_ENV", "$_REQUEST" };

    fn isSuperglobal(name: []const u8) bool {
        for (superglobal_names) |candidate| if (std.mem.eql(u8, name, candidate)) return true;
        return false;
    }

    fn superglobalCell(self: *VM, name: []const u8) RuntimeError!*Value {
        if (self.globals_cells.get(name)) |cell| return cell;
        const cell = try self.newRefCell();
        try self.bindRefSlot(&self.globals_cells, name, cell);
        try self.request_vars.put(self.allocator, name, .null);
        return cell;
    }

    fn unsetSuperglobal(self: *VM, name: []const u8) void {
        if (self.globals_array) |ga| ga.remove(.{ .string = Value.String.borrowed(name[1..]) });
        if (self.request_vars.fetchRemove(name)) |old| self.releaseValue(old.value);
        self.unbindRefSlot(&self.globals_cells, name);
    }

    fn bindRefSlot(self: *VM, map: *std.StringHashMapUnmanaged(*Value), name: []const u8, cell: *Value) !void {
        const old = try map.fetchPut(self.allocator, name, cell);
        self.bindCell(cell);
        if (old) |entry| self.unbindCell(entry.value);
    }

    fn unbindRefSlot(self: *VM, map: *std.StringHashMapUnmanaged(*Value), name: []const u8) void {
        if (map.fetchRemove(name)) |entry| self.unbindCell(entry.value);
    }

    fn deinitRefSlots(self: *VM, map: *std.StringHashMapUnmanaged(*Value)) void {
        var old = map.*;
        map.* = .{};
        var it = old.valueIterator();
        while (it.next()) |cell| self.unbindCell(cell.*);
        old.deinit(self.allocator);
    }

    // extract(EXTR_REFS): the variable named `$name` in frame becomes a
    // reference to arr[key]
    pub fn bindVariableToElement(self: *VM, frame: *CallFrame, name: []const u8, arr: *PhpArray, key: PhpArray.Key) RuntimeError!void {
        // the variable's old value goes only once everything names the
        // element, so a destructor it runs sees the new binding
        const old = self.frameVariable(frame, name) orelse Value.undef;
        retainValue(old);
        defer self.releaseValue(old);
        try self.bindSlotToElement(frame, name, arr, key);
        const entry = arr.getPtr(key) orelse return;
        const val = if (entry.ref) |cell| cell.* else entry.value;
        try self.setVariableByName(frame, name, val);
    }

    // `$v = &$arr[$k]`: an element another name already references shares
    // that cell, anything else gets a fresh one
    fn bindSlotToElement(self: *VM, frame: *CallFrame, name: []const u8, arr: *PhpArray, key: PhpArray.Key) RuntimeError!void {
        if (arr.getPtr(key)) |entry| if (entry.ref) |cell| if (cellOf(cell).binders > 1) {
            return self.bindRefSlot(&frame.ref_slots, name, cell);
        };
        const cell = try self.newRefCell();
        var elem = arr.get(key);
        // a referenced element can't stay COW-shared, so a shared array
        // element is separated first (php separates at each `&` level)
        if (elem == .array and elem.array.refcount > 1) {
            elem = .{ .array = try self.shallowCloneCow(elem.array) };
            try self.arraySetOwned(arr, key, elem);
        }
        self.setCell(cell, elem);
        try self.bindRefSlot(&frame.ref_slots, name, cell);
        try self.regRefArray(try self.ensureRefOwner(frame), cell, arr, key);
        if (arr.getPtr(key)) |ep| self.setEntryRef(ep, cell);
        self.array_ref_active = true;
    }

    pub fn setEntryRef(self: *VM, entry: *PhpArray.Entry, cell: ?*Value) void {
        const old = entry.ref;
        entry.ref = cell;
        if (cell) |c| self.bindCell(c);
        if (old) |c| self.unbindCell(c);
    }

    fn setReturnRef(self: *VM, cell: ?*Value) void {
        const old = self.last_return_ref;
        self.last_return_ref = cell;
        if (cell) |c| self.bindCell(c);
        if (old) |c| self.unbindCell(c);
    }

    fn refIndex(self: *VM) RuntimeError!*RefIndex {
        if (self.ref_index) |ri| return ri;
        const ri = try self.allocator.create(RefIndex);
        ri.* = .{};
        self.ref_index = ri;
        return ri;
    }

    fn ensureRefOwner(self: *VM, frame: *CallFrame) RuntimeError!RefIndex.OwnerId {
        if (frame.ref_owner == 0) frame.ref_owner = (try self.refIndex()).createOwner();
        return frame.ref_owner;
    }

    fn persistentRefOwner(self: *VM) RuntimeError!RefIndex.OwnerId {
        if (self.persistent_ref_owner == 0) self.persistent_ref_owner = (try self.refIndex()).createOwner();
        return self.persistent_ref_owner;
    }

    fn regRefArray(self: *VM, owner: RefIndex.OwnerId, cell: *Value, arr: *PhpArray, key: PhpArray.Key) RuntimeError!void {
        const entry = arr.getPtr(key) orelse return;
        try (try self.refIndex()).addOwned(self.allocator, owner, cell, .{ .array = .{ .array = arr, .key = entry.key } });
    }
    fn regRefObject(self: *VM, owner: RefIndex.OwnerId, cell: *Value, obj: *PhpObject, prop_name: []const u8) RuntimeError!void {
        const target: BindingTarget = .{ .object = .{ .object = obj, .prop_name = prop_name } };
        try (try self.refIndex()).addOwned(self.allocator, owner, cell, target);
        obj.ref_mirrored = true;
        self.markTypedSource(cell, target);
    }
    fn regRefStatic(self: *VM, owner: RefIndex.OwnerId, cell: *Value, class_name: []const u8, prop_name: []const u8) RuntimeError!void {
        const target: BindingTarget = .{ .static = .{ .class_name = class_name, .prop_name = prop_name } };
        try (try self.refIndex()).addOwned(self.allocator, owner, cell, target);
        self.markTypedSource(cell, target);
    }

    // is `obj->prop_name` the target of a live reference (`$r = &$obj->prop`)?
    // if so, its array value is shared storage on purpose and an in-place inner
    // write must NOT cowSeparate it (every alias must see the mutation)
    // how many holders of a cell's value are aliases of the same reference set:
    // the cell itself, each mirror registered in the reference index, and each
    // frame slot bound to the cell. a refcount above this means a value copy
    // shares the array and a write through the reference must separate
    // counted holders inside a reference set: the cell, each registered
    // mirror, and each bound frame binding that actually holds the value (a
    // slot bound by `$r = &$x` reads through the cell and holds nothing)
    fn referenceAliasCount(self: *VM, cell: *Value) u32 {
        var aliases: u32 = 1;
        if (cell.* == .array) for (superglobal_names) |name| {
            if (self.globals_cells.get(name) == cell) {
                if (self.request_vars.get(name)) |v| {
                    if (v == .array and v.array == cell.array) aliases += 1;
                }
            }
        };
        if (self.ref_index) |ri| if (ri.fwd.get(cell)) |list| {
            aliases += @intCast(list.items.len);
        };
        for (self.frames[0..self.frame_count]) |*fr| {
            var it = fr.ref_slots.iterator();
            while (it.next()) |entry| {
                if (entry.value_ptr.* != cell) continue;
                if (self.frameBindingHolds(fr, entry.key_ptr.*, cell.*)) aliases += 1;
            }
        }
        return aliases;
    }

    fn frameBindingHolds(self: *VM, fr: *CallFrame, name: []const u8, value: Value) bool {
        _ = self;
        const held = fr.vars.get(name) orelse blk: {
            const names = if (fr.func) |func| func.slot_names else fr.slot_names;
            for (names, 0..) |candidate, si| {
                if (std.mem.eql(u8, candidate, name)) break :blk if (si < fr.locals.len) fr.locals[si] else Value.null;
            }
            break :blk Value.null;
        };
        return switch (value) {
            .array => |arr| held == .array and held.array == arr,
            .object => |obj| held == .object and held.object == obj,
            else => true,
        };
    }

    fn staticPropIsReferenced(self: *VM, class_name: []const u8, prop_name: []const u8) bool {
        const ri = self.ref_index orelse return false;
        if (ri.prop_rev.get(.{ .object = null, .class_name = class_name, .prop_name = prop_name })) |list| {
            return list.items.len > 0;
        }
        return false;
    }

    fn propIsReferenced(self: *VM, obj: *PhpObject, prop_name: []const u8) bool {
        const ri = self.ref_index orelse return false;
        if (ri.prop_rev.get(.{ .object = obj, .class_name = "", .prop_name = prop_name })) |list| {
            return list.items.len > 0;
        }
        return false;
    }

    // for by-ref foreach advancing past an element: if $name's current cell has
    // ONLY the foreach's own array binding (nothing captured it via `$r = &$v` /
    // `$x[] = &$v`), revert that element to a non-reference - clear its entry.ref
    // and drop the binding. matches PHP (an element stays is_ref after the loop
    // only when something else still references it)
    fn revertUncapturedForeachCell(self: *VM, name: []const u8) void {
        const ri = self.ref_index orelse return;
        const frame = self.currentFrame();
        const c_old = frame.ref_slots.get(name) orelse return;
        // bound by the element and the loop variable alone; a third binder
        // (a variable the element was a reference to before the loop, or one
        // that took a reference since) keeps it a reference
        if (cellOf(c_old).binders > 2) return;
        const list = ri.fwd.getPtr(c_old) orelse return;
        if (list.items.len != 1) return; // captured (>1) -> leave is_ref
        const t = list.items[0];
        if (t != .array) return;
        const arr = t.array.array;
        const key = t.array.key;
        if (arr.getPtr(key)) |ep| {
            if (ep.ref == c_old) self.setEntryRef(ep, null);
        }
        ri.removeOwnedTarget(self.allocator, frame.ref_owner, c_old, t);
    }

    // unbinding a ref VARIABLE (unset($r) where $r came from `$r = &$a[k]` /
    // `$r = &$o->p` / foreach-by-ref): if the cell's only remaining mirror is a
    // single binding and no other live variable aliases the cell, the reference
    // set has collapsed to one holder - revert the target to a plain value
    // (clear the element's entry.ref / the prop_rev entry) so later writes COW-
    // separate normally instead of leaking through a dead reference. matches
    // PHP (is_ref drops when the last alias goes away). conservative: any doubt
    // (extra mirrors, another alias anywhere) leaves the binding in place
    fn revertUncapturedCell(self: *VM, cell: *Value) void {
        const ri = self.ref_index orelse return;
        const list = ri.fwd.getPtr(cell) orelse return;
        if (list.items.len != 1) return;
        var fi: usize = 0;
        while (fi < self.frame_count) : (fi += 1) {
            var it = self.frames[fi].ref_slots.valueIterator();
            while (it.next()) |c| if (c.* == cell) return;
        }
        var git = self.globals_cells.valueIterator();
        while (git.next()) |c| if (c.* == cell) return;
        const t = list.items[0];
        switch (t) {
            .array => |ab| {
                if (ab.array.getPtr(ab.key)) |ep| {
                    if (ep.ref == cell) self.setEntryRef(ep, null);
                }
                var i: usize = 0;
                while (i < self.array_ref_bindings.items.len) {
                    const b = self.array_ref_bindings.items[i];
                    if (b.cell == cell and b.array == ab.array and b.key.eql(ab.key)) {
                        _ = self.array_ref_bindings.swapRemove(i);
                    } else i += 1;
                }
            },
            .object, .static, .capture => {},
        }
        ri.removeTargetAllOwners(self.allocator, cell, t);
    }

    fn unregFrameBindings(self: *VM, frame: anytype) void {
        if (frame.ref_owner == 0) return;
        if (self.ref_index) |ri| ri.releaseOwner(self.allocator, frame.ref_owner);
        self.releaseBoundArgSources(frame.ref_owner);
    }

    const ArgEntry = struct { array: *PhpArray, key: PhpArray.Key, source: RefSource };

    // how the fast loop object enters this object's vm for anything beyond
    // its own hot paths. it compiles the runtime a second time, and a direct
    // call would run that copy against its own module globals (type table,
    // gc state, sentinels). function pointers resolve here
    pub const SlowPaths = struct {
        // error values are numbered per compilation, so a path that can fail
        // reports a status (see Status) and returns results through pointers
        drain_pending_destruct: *const fn (*VM) void,
        check_param_types: *const fn (*VM, []const u8, u8, *bool) u8,
        resolve_default: *const fn (*VM, *const ObjFunction, usize, *Value, *bool) u8,
        array_set_owned: *const fn (*VM, *PhpArray, PhpArray.Key, Value) u8,
        copy_value: *const fn (*VM, Value, *Value) u8,
        retain_frame_objects: *const fn (*VM, usize) void,
        expire_execution: *const fn (*VM) u8,
        param_types: *const fn (*VM, []const u8) []const []const u8,
        set_local_global: *const fn (*VM, u16, Value) u8,
        grow_call_room: *const fn (*VM, *bool) u8,

        pub const Status = struct {
            pub const ok: u8 = 0;
            pub const runtime_error: u8 = 1;
            pub const out_of_memory: u8 = 2;
        };

        const main: SlowPaths = .{
            .drain_pending_destruct = drainEntry,
            .check_param_types = checkParamTypesEntry,
            .resolve_default = resolveDefaultEntry,
            .array_set_owned = arraySetOwnedEntry,
            .copy_value = copyValueEntry,
            .retain_frame_objects = VM.retainFrameObjects,
            .expire_execution = expireExecutionEntry,
            .param_types = VM.declaredParamTypes,
            .set_local_global = setLocalGlobalEntry,
            .grow_call_room = growCallRoomEntry,
        };

        fn growCallRoomEntry(vm: *VM, grown: *bool) u8 {
            grown.* = vm.growCallRoom(1) catch |err| return statusOf(err);
            return Status.ok;
        }

        fn drainEntry(vm: *VM) void {
            vm.flushTopWrites();
            vm.drainPendingDestruct();
            // the releases may have filled the collector's root buffer, which
            // php collects as the root that fills it is added
            vm.collectCyclesIfNeeded();
        }

        fn statusOf(err: anyerror) u8 {
            return if (err == error.OutOfMemory) Status.out_of_memory else Status.runtime_error;
        }

        fn checkParamTypesEntry(vm: *VM, name: []const u8, arg_count: u8, dispatched: *bool) u8 {
            vm.flushTopWrites();
            dispatched.* = vm.checkParamTypes(name, arg_count) catch |err| return statusOf(err);
            return Status.ok;
        }

        // an error a default raises lands in the fast loop's nearest catch,
        // as a type check's does; `dispatched` tells the fast loop to return
        fn resolveDefaultEntry(vm: *VM, func: *const ObjFunction, index: usize, out: *Value, dispatched: *bool) u8 {
            vm.flushTopWrites();
            // the fast loop fills the defaults up to the last parameter
            defer if (index + 1 >= func.arity) vm.releaseDefaultHolds();
            out.* = vm.resolveParamDefaultHeld(func, index) catch |err| {
                vm.releaseDefaultHolds();
                const pending = vm.pending_exception orelse return statusOf(err);
                if (pending != .object) return statusOf(err);
                vm.pending_exception = null;
                defer vm.stackRelease(pending);
                if (vm.throwObject(pending.object)) {
                    dispatched.* = true;
                    return Status.ok;
                }
                return statusOf(error.RuntimeError);
            };
            return Status.ok;
        }

        fn arraySetOwnedEntry(vm: *VM, array: *PhpArray, key: PhpArray.Key, value: Value) u8 {
            vm.flushTopWrites();
            vm.arraySetOwned(array, key, value) catch |err| return statusOf(err);
            return Status.ok;
        }

        // a global-scope write already stored in the frame's locals
        fn setLocalGlobalEntry(vm: *VM, slot: u16, val: Value) u8 {
            vm.setLocalGlobal(slot, val, vm.currentFrame()) catch |err| return statusOf(err);
            return Status.ok;
        }

        fn copyValueEntry(vm: *VM, val: Value, out: *Value) u8 {
            vm.flushTopWrites();
            out.* = vm.copyValue(val) catch |err| return statusOf(err);
            return Status.ok;
        }

        fn expireExecutionEntry(vm: *VM) u8 {
            vm.flushTopWrites();
            vm.expireExecution() catch |err| return statusOf(err);
            return Status.ok;
        }
    };

    pub const StepOverflow = struct { up: ?bool = null, frame: usize = 0, ip: usize = 0 };

    pub const InlineCache = struct {
        // argument guard sites: keyed by (chunk_ptr ^ guard ip); `guard` is the
        // identity of the receiver/callable read from the stack and
        // `generation` the function+class registry size, so a site re-resolves
        // when a different class arrives or new code is declared
        intent: []IntentIC = &.{},
        arg_stack: []RefSource = &.{},
        arg_stack_room: Region(RefSource) = .{},
        // third-party extension state lives here, off the VM struct, so the
        // VM's field offsets stay put (see GOTCHAS on codegen perturbation):
        // one slot per loaded extension, an arena for the value handles a
        // call hands out, and whether request_init has run
        ext_slots: []extension.VmSlot = &.{},
        ext_request_active: bool = false,
        // an int ++/-- that overflowed to float, and where: the write that
        // follows it reports php's "past its maximal value" for a typed
        // property or reference (zend_incdec_typed_prop / _ref)
        step_overflow: StepOverflow = .{},
        // a native's write through a by-reference argument was refused by a
        // typed reference: the TypeError is pending and the call raises it
        // once the native returns (ZEND_TRY_ASSIGN_REF_*)
        ref_write_refused: bool = false,
        // where warnings raised while checking a call's arguments are
        // reported: php coerces them in the callee's RECV, at its declaration
        arg_check_site: ?SourcePosition = null,
        // classes whose deferred property defaults have not run yet; while it
        // is zero a static access skips the resolution check
        pending_defaults: u32 = 0,
        // provenance of the call family opcode being executed, saved across a
        // nested call so a native callback's own calls cannot clobber it
        saved_sources: std.ArrayListUnmanaged(RefSource) = .empty,
        arg_arrays: std.ArrayListUnmanaged(ArgEntry) = .empty,
        bound_arg_sources: std.ArrayListUnmanaged(struct { owner: RefIndex.OwnerId, source: RefSource }) = .empty,
        active_args: []RefSource = &.{},
        active_frame: usize = 0,
        active_arg_count: usize = 0,

        // property access: keyed by (chunk_ptr ^ ip), stores class_ptr for visibility skip
        prop: [128]PropIC = @splat(.{}),
        // method call: keyed by (chunk_ptr ^ ip), stores class_ptr + resolved func
        method: [128]MethodIC = @splat(.{}),
        // class constant read: keyed by (chunk_ptr ^ ip), for the class the
        // site resolved to. cleared whenever a registered class's constant
        // is written, so a cached value is always the stored one
        class_const: [128]ClassConstIC = @splat(.{}),
        // top script slots the fast loop wrote without reaching $GLOBALS,
        // vars and global cells; flushed whenever control leaves the fast loop
        top_dirty: std.DynamicBitSetUnmanaged = .{},
        top_dirty_any: bool = false,
        // statement ends (chunk_ptr ^ ip) where handing the frame back to
        // the fast loop bailed without progress; runLoop stops retrying them
        fast_stalls: [256]usize = @splat(0),
        // stack-allocated locals for callLocalsOnly - avoids heap alloc/free per call
        locals_buf: [*]Value = undefined,
        locals_sp: usize = 0,
        locals_cap: usize = 0,
        fn_cache_name: []const u8 = "",
        fn_cache_func: ?*const ObjFunction = null,
        // php matches function names case-insensitively. an exact hit never
        // looks here; a miss consults these lowercase indexes (user functions
        // kept at registration, natives built on the first miss) and caches
        // the name a call resolved to, namespace fallback included
        fn_lower: std.StringHashMapUnmanaged([]const u8) = .{},
        native_lower: std.StringHashMapUnmanaged([]const u8) = .{},
        resolved_calls: std.StringHashMapUnmanaged([]const u8) = .{},
        // the registered name a (class, method) call resolves to, valid while
        // the function and class counts match the ones it was filled under
        resolved_methods: std.HashMapUnmanaged(MethodKey, []const u8, MethodKey.Context, std.hash_map.default_max_load_percentage) = .{},
        resolved_methods_fn_count: usize = 0,
        resolved_methods_cls_count: usize = 0,
        // the function whose parameter default is being resolved, for the
        // location of the error an unresolvable default raises
        default_site: ?*const ObjFunction = null,
        // the arguments the call passed, which its trace entry shows
        default_args: []const Value = &.{},
        // values ini_set and friends stored in ini_settings, owned here by
        // directive name; the file's and extensions' values are borrowed
        ini_values: std.StringHashMapUnmanaged([]u8) = .{},
        // the object a foreach snapshot stands in for, released with the snapshot
        foreach_pins: std.AutoHashMapUnmanaged(*PhpArray, Value) = .{},
        // canonical paths of files include resolution found, owned here
        include_paths: std.StringHashMapUnmanaged(void) = .{},
        // the files this run included, main script first, keyed by canonical
        // path (interned in include_paths)
        included: std.StringArrayHashMapUnmanaged(void) = .{},
        // the syntax error that made the file loader refuse an include, for
        // the include opcode to raise as ParseError
        include_parse_error: ?SourcePositionMessage = null,
        // the compile-time fatal that made the file loader refuse an include
        include_compile_error: ?SourcePositionMessage = null,
        // class names whose autoload is in progress, innermost last
        autoloading: std.ArrayListUnmanaged([]const u8) = .empty,
        // set by initVm, never defaulted: a default would compile these paths
        // into the fast loop object as well
        slow: SlowPaths = undefined,
        // declaration sites of traits, which have no ClassDef of their own
        trait_sites: std.StringHashMapUnmanaged(DeclSite) = .{},
        // the last typed callee the fast loop checked and its declared types
        typed_func: ?*const ObjFunction = null,
        typed_params: []const []const u8 = &.{},
        // per-frame sp save for inline call/ret in fastLoop
        sp_save: []usize = &.{},
        sp_save_room: Region(usize) = .{},
        // per-frame actual arg count for func_get_args
        arg_counts: []u32 = &.{},
        arg_counts_room: Region(u32) = .{},
        // per-frame saved arg values for func_get_args (flat buffer indexed by frame)
        fga_buf: []Value = &.{},
        fga_room: Region(Value) = .{},
        fga_offsets: []u32 = &.{},
        fga_offsets_room: Region(u32) = .{},
        fga_sp: u32 = 0,
        // set before pushing a frame, consumed by executeFunction et al
        pending_arg_count: u32 = unknown_arg_count,

        const PropIC = struct {
            key: usize = 0,
            chunk_key: usize = 0,
            class_ptr: usize = 0,
            slot_index: u16 = 0xFFFF,
            // non-empty when the cached property is typed - the fast path must
            // then run the declared-type check/coercion before the slot write
            prop_type: []const u8 = "",
            decl_class: []const u8 = "",
        };

        const ClassConstIC = struct {
            key: usize = 0,
            chunk_key: usize = 0,
            class_ptr: usize = 0,
            value: Value = .null,
        };

        const MethodIC = struct {
            key: usize = 0,
            chunk_key: usize = 0,
            class_ptr: usize = 0,
            func: ?*const ObjFunction = null,
            native: ?Native = null,
            full_name: []const u8 = "",
        };

        const IntentIC = struct {
            key: usize = 0,
            chunk_key: usize = 0,
            guard: usize = 0,
            generation: usize = 0,
            // which stack slots below the arguments identify the callee
            slots: u8 = 0,
            capture: bool = true,
        };

        pub const intent_bits = 11;

        // the product's high bits mix every bit of the chunk and the ip
        pub fn intentIndex(chunk_ptr: usize, ip: usize) u11 {
            return @intCast(((chunk_ptr ^ ip) *% 0x517CC1B727220A95) >> (64 - intent_bits));
        }

        pub fn propIndex(chunk_ptr: usize, ip: usize) u7 {
            return @truncate((chunk_ptr ^ ip) *% 0x517CC1B727220A95);
        }

        pub fn methodIndex(chunk_ptr: usize, ip: usize) u7 {
            return @truncate((chunk_ptr ^ ip) *% 0x517CC1B727220A95);
        }
    };

    const StaticEntry = struct {
        var_name: []const u8,
        frame_depth: usize,
    };

    const HeldException = struct { frame: usize, slot: usize, exception: *PhpObject };
    // `handlers` is how many exception handlers were in place, so entering
    // one of those leaves the scope
    const InitializerScope = struct { class: ?[]const u8, frame: usize, handlers: usize };

    const ExceptionHandler = struct {
        catch_ip: usize, // absolute IP to jump to on throw
        frame_count: usize, // frame count when handler was pushed
        sp: usize, // stack pointer when handler was pushed
        chunk: *const Chunk, // chunk the handler belongs to
        // the @ nesting when the try began: an exception leaving an @
        // expression ends its silence, as php's live-range cleanup does
        silenced_depth: u32,
    };

    const CallFrame = struct {
        chunk: *const Chunk,
        ip: usize,
        vars: std.StringHashMapUnmanaged(Value),
        locals: []Value = &.{},
        func: ?*const ObjFunction = null,
        generator: ?*Generator = null,
        ref_slots: std.StringHashMapUnmanaged(*Value) = .{},
        ref_owner: RefIndex.OwnerId = 0,
        // Parameter slots whose vars entries already own an array edge. Fixed
        // storage avoids lifecycle coupling to fast-pop frame-slot reuse.
        owned_array_args: [4]u64 = @splat(0),
        called_class: ?[]const u8 = null,
        // name the function was looked up by - distinguishes closure instances
        // (which all share the same ObjFunction) for per-instance static state.
        call_name: ?[]const u8 = null,
        entry_sp: usize = 0,
        // the script file currently executing in this frame. used by class/
        // function declarations inside required files so ReflectionClass::
        // getFileName reports the *declaring* file rather than vm.file_path
        // (which only tracks the top-level script)
        script_path: []const u8 = "",
        // slot layout for this frame's slot-backed locals. only meaningful for
        // global-scope frames (func == null): the top script and require-include
        // frames. lets `global $x` scan every global-scope frame on the stack -
        // a file required at global scope IS the global scope, so a var it set
        // at top level must be visible to `global` even before the require
        // returns. function frames leave this empty (they use func.slot_names)
        slot_names: []const []const u8 = &.{},
        // Includes execute in their caller's variable scope. The execution
        // frame remains separate for bytecode and return handling, while this
        // index identifies the scope whose bindings receive include changes.
        include_parent: ?usize = null,
        // the frame a native method runs in: no code of its own, only $this
        native: bool = false,
    };

    fn allocGenerator(self: *VM, initial: Generator) RuntimeError!*Generator {
        // a generator function's body only runs once it is iterated, so its
        // call attributes are checked here, while the caller is current
        try self.checkGeneratorCall(initial.func);
        const gen = if (!self.serve_mode) self.free_generators.pop() orelse blk: {
            const created = try self.allocator.create(Generator);
            errdefer self.allocator.destroy(created);
            try self.generators.append(self.allocator, created);
            break :blk created;
        } else blk: {
            const created = try self.allocator.create(Generator);
            errdefer self.allocator.destroy(created);
            try self.generators.append(self.allocator, created);
            break :blk created;
        };
        gen.* = initial;
        gen.handle = try self.allocHandle();
        return gen;
    }

    // the state behind a php resource. ids come from their own counter, as
    // php's resource list does, so resources never shift object ids.
    // class_name must outlive the vm (a literal)
    pub fn newResource(self: *VM, class_name: []const u8) RuntimeError!*PhpObject {
        const obj = try self.allocResource(class_name);
        self.numberResource(obj);
        return obj;
    }

    // a resource shell without an id yet, for a resource php numbers after
    // others it creates alongside it (a process after its pipes)
    pub fn allocResource(self: *VM, class_name: []const u8) RuntimeError!*PhpObject {
        const obj = try self.allocObjectShell();
        obj.* = .{ .class_name = class_name, .resource = true };
        return obj;
    }

    // a resource php makes and frees inside one call still takes an id
    pub fn skipResourceId(self: *VM) void {
        self.next_resource_id += 1;
    }

    pub fn numberResource(self: *VM, obj: *PhpObject) void {
        self.next_resource_id += 1;
        obj.id = self.next_resource_id;
    }

    pub fn rememberLastDirectory(self: *VM, dir: *PhpObject) void {
        self.forgetLastDirectory();
        objRetain(dir);
        self.last_directory = dir;
    }

    pub fn forgetLastDirectory(self: *VM) void {
        const dir = self.last_directory orelse return;
        self.last_directory = null;
        self.objRelease(dir);
    }

    fn allocUserObject(self: *VM, class_name: []const u8) RuntimeError!*PhpObject {
        return self.allocUserObjectHandle(class_name, 0);
    }

    // handle 0 takes the next free one
    fn allocUserObjectHandle(self: *VM, class_name: []const u8, handle: u32) RuntimeError!*PhpObject {
        const stable_class_name = try self.stableClassName(class_name);
        const obj = try self.allocObject(.{ .class_name = stable_class_name, .id = handle });
        if (self.debug_trace_class) |trace_class| if (std.mem.eql(u8, trace_class, class_name)) {
            @import("value.zig").hooks().trace_obj = obj;
            @import("value.zig").hooks().trace_rc_verbose = true;
        };
        return obj;
    }

    // the bytes an object keeps for its class name: the registered name, or
    // an interned copy for a class that is not declared (yet)
    pub fn stableClassName(self: *VM, class_name: []const u8) ![]const u8 {
        if (self.classes.getKey(class_name)) |registered| return registered;
        return self.internName(class_name);
    }

    // a new object with the next free handle, the number var_dump shows and
    // spl_object_id returns
    pub fn allocObject(self: *VM, fields: PhpObject) RuntimeError!*PhpObject {
        const obj = try self.allocObjectShell();
        obj.* = fields;
        if (obj.id == 0) obj.id = try self.allocHandle();
        return obj;
    }

    pub fn allocHandle(self: *VM) RuntimeError!u32 {
        if (self.free_handles.pop()) |handle| return handle;
        self.next_object_id += 1;
        return self.next_object_id;
    }

    fn freeHandle(self: *VM, obj: *PhpObject) void {
        if (obj.resource or obj.id == 0) return;
        self.free_handles.append(self.allocator, obj.id) catch {};
        obj.id = 0;
    }

    fn allocObjectShell(self: *VM) RuntimeError!*PhpObject {
        if (self.free_objects.pop()) |obj| return obj;
        const created = try self.allocator.create(PhpObject);
        errdefer self.allocator.destroy(created);
        try self.objects.append(self.allocator, created);
        return created;
    }

    fn nativeCleanup(self: *VM, class_name: []const u8) ?*const fn (*PhpObject) bool {
        var current: ?[]const u8 = class_name;
        while (current) |name| {
            const class = self.classes.get(name) orelse return null;
            if (class.native_cleanup) |cleanup| return cleanup;
            current = class.parent;
        }
        return null;
    }

    // releases what a dead object holds outside the heap; false when some
    // native state has no cleanup and must stay put until teardown, which
    // keeps the object out of the pool
    fn releaseNativeState(self: *VM, obj: *PhpObject) bool {
        if (obj.native.kind == .closure) {
            self.releaseClosureInstance(obj);
            return true;
        }
        if (obj.fakeClosure()) |state| {
            obj.native = .{};
            const callable = state.callable;
            self.allocator.destroy(state);
            self.releaseValue(callable);
            return true;
        }
        if (self.nativeCleanup(obj.class_name)) |cleanup| return cleanup(obj);
        return obj.native.kind == .none;
    }

    pub fn allocArray(self: *VM) RuntimeError!*PhpArray {
        if (self.free_arrays.pop()) |arr| {
            arr.* = .{};
            return arr;
        }
        const arr = try self.allocator.create(PhpArray);
        errdefer self.allocator.destroy(arr);
        arr.* = .{};
        try self.arrays.append(self.allocator, arr);
        return arr;
    }

    pub fn init(allocator: Allocator) RuntimeError!VM {
        return initInPlace(allocator);
    }

    // every field defaults to an empty container, so a VM whose init failed
    // part way can be torn down with the ordinary deinit
    pub fn initInPlace(allocator: Allocator) RuntimeError!VM {
        var vm = VM{ .allocator = allocator };
        errdefer vm.deinit();
        try initVm(&vm, allocator);
        return vm;
    }

    pub fn initOnHeap(allocator: Allocator) RuntimeError!*VM {
        const vm = try allocator.create(VM);
        errdefer allocator.destroy(vm);
        vm.* = .{ .allocator = allocator };
        errdefer vm.deinit();
        try initVm(vm, allocator);
        return vm;
    }

    pub fn stringAllocator(self: *VM) Allocator {
        return self.string_pool.allocator();
    }

    fn initVm(vm: *VM, parent: Allocator) RuntimeError!void {
        const account = try parent.create(MemoryAccount);
        account.* = .{ .parent = parent };
        vm.memory = account;
        vm.allocator = account.allocator();
        const allocator = vm.allocator;
        vm.string_pool.backing = allocator;
        if (platform.getenv("ZPHP_NO_POOL") != null) vm.debug_no_pool = true;
        if (platform.getenv("ZPHP_GC_VERIFY") != null) vm.debug_gc_verify = true;
        vm.debug_trace_class = platform.getenv("ZPHP_TRACE_OBJ_CLASS");
        vm.default_tz_name = "UTC";
        vm.dbg_profile_enabled = platform.getenv("ZPHP_DBG_PROFILE") != null;
        try @import("../stdlib/registry.zig").register(&vm.native_fns, allocator);
        try initConstants(&vm.php_constants, allocator);
        try registerStdlibClasses(vm, allocator);
        vm.error_reporting_level = 30719;
        vm.ic = try allocator.create(InlineCache);
        vm.ic.?.* = .{};
        vm.ic.?.slow = SlowPaths.main;
        try vm.reserveCallRegions();
        vm.ic.?.active_args = try allocator.alloc(RefSource, 256);
        @memset(vm.ic.?.active_args, .none);
        vm.ic.?.intent = try allocator.alloc(InlineCache.IntentIC, 1 << InlineCache.intent_bits);
        @memset(vm.ic.?.intent, .{});
        const locals_buf = try allocator.alloc(Value, 8192);
        vm.ic.?.locals_buf = locals_buf.ptr;
        vm.ic.?.locals_cap = 8192;
        try extension.vmInit(vm);
        // snapshot the builtin heap + class registration so serve-mode reset can
        // keep it instead of rebuilding every request (registry native fns are
        // never cleared; stdlib classes + their enum-case objects ARE the churn)
        vm.builtin_obj_hw = vm.objects.items.len;
        vm.builtin_arr_hw = vm.arrays.items.len;
        vm.builtin_str_hw = vm.strings.items.len;
        // a shell pooled during init lies below the marks, where a serve reset
        // never tears down what it holds; request code must not be handed one
        vm.free_objects.clearRetainingCapacity();
        vm.free_arrays.clearRetainingCapacity();
        vm.free_generators.clearRetainingCapacity();
        vm.free_fibers.clearRetainingCapacity();
        var ci = vm.classes.keyIterator();
        while (ci.next()) |k| try vm.builtin_classes.put(allocator, k.*, {});
        var ii = vm.interfaces.keyIterator();
        while (ii.next()) |k| try vm.builtin_interfaces.put(allocator, k.*, {});
        vm.builtins_recorded = true;
        vm.applyConfiguredMemoryLimit(true);
        // OnUpdateAutoDetectLineEndings at startup
        if (@import("../ini_config.zig").get("auto_detect_line_endings")) |v| {
            if (std.ascii.eqlIgnoreCase(v, "on") or std.ascii.eqlIgnoreCase(v, "true") or std.ascii.eqlIgnoreCase(v, "yes") or (std.fmt.parseInt(i64, v, 10) catch 0) != 0)
                vm.raiseErrorAt(E_DEPRECATED, "auto_detect_line_endings is deprecated", .{ .file = "Unknown", .line = 0 }) catch {};
        }
        // php_module_startup's check of the configured directives
        if (@import("../ini_config.zig").get("allow_url_include")) |v| {
            if (!(v.len == 0 or std.mem.eql(u8, v, "0") or std.ascii.eqlIgnoreCase(v, "off") or std.ascii.eqlIgnoreCase(v, "false") or std.ascii.eqlIgnoreCase(v, "no")))
                vm.raiseErrorAt(E_DEPRECATED, "Directive 'allow_url_include' is deprecated", .{ .file = "Unknown", .line = 0 }) catch {};
        }
        account.rebase();
    }

    // stdlib class/interface/trait registration. callable both at VM init time
    // and after a serve-mode reset (which clears the class table to drop the
    // user's request-scoped class definitions). idempotent for each stdlib
    // module since the maps overwrite on duplicate keys
    fn registerStdlibClasses(vm: *VM, allocator: Allocator) RuntimeError!void {
        try @import("../stdlib/exceptions.zig").register(vm, allocator);
        try @import("../stdlib/datetime.zig").register(vm, allocator);
        try @import("../stdlib/spl.zig").register(vm, allocator);
        try @import("../stdlib/spl_iterators.zig").register(vm, allocator);
        try @import("../stdlib/spl_directory.zig").register(vm, allocator);
        try @import("../stdlib/spl_dllist.zig").register(vm, allocator);
        try @import("../stdlib/spl_heap.zig").register(vm, allocator);
        try @import("../stdlib/spl_fixedarray.zig").register(vm, allocator);
        try @import("../stdlib/spl_observer.zig").register(vm, allocator);
        try @import("../stdlib/pdo.zig").register(vm, allocator);
        try @import("../stdlib/websocket.zig").register(vm, allocator);
        try @import("../stdlib/filesystem.zig").register(vm, allocator);
        try @import("../stdlib/stream_filters.zig").register(vm, allocator);
        try @import("../stdlib/reflection.zig").register(vm, allocator);
        try @import("../stdlib/curl.zig").register(vm, allocator);
        try @import("../stdlib/phar_class.zig").register(vm, allocator);
        try @import("../stdlib/random.zig").register(vm, allocator);
        try @import("../stdlib/dom.zig").register(vm, allocator);
        try @import("../stdlib/simplexml.zig").register(vm, allocator);
        try @import("../stdlib/xmlreader.zig").register(vm, allocator);
        try @import("../stdlib/xmlwriter.zig").register(vm, allocator);
        try @import("../stdlib/xml_parser.zig").register(vm, allocator);
        try @import("../stdlib/intl.zig").register(vm, allocator);
        try @import("../stdlib/gmp.zig").register(vm, allocator);
        try @import("../stdlib/workers.zig").register(vm, allocator);
        try @import("../stdlib/channel.zig").register(vm, allocator);
        try @import("../stdlib/buffer.zig").register(vm, allocator);
        try @import("../stdlib/select.zig").register(vm, allocator);
        try @import("../stdlib/bcmath.zig").register(vm, allocator);
        try @import("../stdlib/gd.zig").register(vm, allocator);
        try @import("../stdlib/soap.zig").register(vm, allocator);
        try @import("../stdlib/mysqli.zig").register(vm, allocator);
        try @import("../stdlib/ldap.zig").register(vm, allocator);
        try @import("../stdlib/tokenizer.zig").register(vm, allocator);

        try @import("../stdlib/hash.zig").register(vm, allocator);

        // tidy and tidyNode - stub classes for the deprecated tidy ext. zphp
        // doesn't link libtidy but class_exists checks still need to pass
        const tidy_def = ClassDef{ .name = "tidy" };
        try vm.classes.put(allocator, "tidy", tidy_def);
        const tidynode_def = ClassDef{ .name = "tidyNode" };
        try vm.classes.put(allocator, "tidyNode", tidynode_def);

        // PHP 8.4 RoundingMode enum. registered as a unit (unbacked) enum to
        // match PHP's exposed surface - the cases have a `name` property only,
        // and the internal mapping from case -> mode int happens inside round()
        var rm_def = ClassDef{ .name = "RoundingMode", .is_enum = true };
        const rm_cases = [_][]const u8{
            "HalfAwayFromZero",
            "HalfTowardsZero",
            "HalfEven",
            "HalfOdd",
            "TowardsZero",
            "AwayFromZero",
            "NegativeInfinity",
            "PositiveInfinity",
        };
        for (rm_cases) |name| {
            const case_obj = try allocator.create(PhpObject);
            case_obj.* = .{ .class_name = "RoundingMode", .enum_case = true };
            try vm.objects.append(allocator, case_obj);
            try case_obj.set(allocator, "name", .{ .string = Value.String.borrowed(name) });
            objRetain(case_obj);
            try rm_def.constants.put(allocator, name, .{ .object = case_obj });
            try rm_def.constant_order.append(allocator, name);
            try rm_def.case_order.append(allocator, name);
        }
        try rm_def.interfaces.append(allocator, "UnitEnum");
        try vm.classes.put(allocator, "RoundingMode", rm_def);
        try vm.registerEnumMethods("RoundingMode", 0);

        // the internal classes whose objects refuse dynamic properties in php
        // (Error "Cannot create dynamic property"), where others only deprecate
        for ([_][]const u8{
            "CurlHandle",                       "CurlMultiHandle",      "CurlShareHandle",      "CurlSharePersistentHandle",
            "GdImage",                          "GdFont",               "IntlListFormatter",    "XMLParser",
            "Directory",                        "WeakMap",              "WeakReference",        "Closure",
            "Fiber",                            "Random\\Randomizer", "OpenSSLAsymmetricKey", "OpenSSLCertificate",
            "OpenSSLCertificateSigningRequest", "Socket",               "AddressInfo",          "Shmop",
            "SysvMessageQueue",                 "SysvSemaphore",        "SysvSharedMemory",     "FTP\\Connection",
            "LDAP\\Connection",               "LDAP\\Result",       "LDAP\\ResultEntry",  "PgSql\\Connection",
            "PgSql\\Result",                  "PgSql\\Lob",
        }) |name| {
            if (vm.classes.getPtr(name)) |cls| cls.no_dynamic_properties = true;
        }
    }

    fn initConstants(c: *std.StringHashMapUnmanaged(Value), a: Allocator) !void {
        try c.put(a, "TRUE", .{ .bool = true });
        try c.put(a, "FALSE", .{ .bool = false });
        try c.put(a, "NULL", .null);
        try c.put(a, "PHP_EOL", .{ .string = Value.String.borrowed(if (platform.is_windows) "\r\n" else "\n") });
        try c.put(a, "PHP_INT_MAX", .{ .int = std.math.maxInt(i64) });
        try c.put(a, "PHP_INT_MIN", .{ .int = std.math.minInt(i64) });
        try c.put(a, "PHP_INT_SIZE", .{ .int = 8 });
        try c.put(a, "PHP_MAJOR_VERSION", .{ .int = php_version.major });
        try c.put(a, "PHP_MINOR_VERSION", .{ .int = php_version.minor });
        try c.put(a, "PHP_RELEASE_VERSION", .{ .int = php_version.release });
        try c.put(a, "PHP_SESSION_DISABLED", .{ .int = 0 });
        try c.put(a, "PHP_SESSION_NONE", .{ .int = 1 });
        try c.put(a, "PHP_SESSION_ACTIVE", .{ .int = 2 });
        try c.put(a, "PHP_VERSION", .{ .string = Value.String.borrowed(php_version.string) });
        try c.put(a, "PHP_VERSION_ID", .{ .int = php_version.id });
        try c.put(a, "PHP_EXTRA_VERSION", .{ .string = Value.String.borrowed("") });
        try c.put(a, "PHP_BUILD_DATE", .{ .string = Value.String.borrowed(php_version.build_date) });
        // true in a debug build, as in php's own
        try c.put(a, "PHP_DEBUG", .{ .bool = @import("builtin").mode == .debug });
        try c.put(a, "PHP_ZTS", .{ .bool = false });
        try c.put(a, "ZEND_THREAD_SAFE", .{ .bool = false });
        try c.put(a, "ZEND_DEBUG_BUILD", .{ .bool = @import("builtin").mode == .debug });
        try c.put(a, "PHP_MAXPATHLEN", .{ .int = 1024 });
        try c.put(a, "ICONV_VERSION", .{ .string = Value.String.borrowed("1.11") });
        try c.put(a, "OPENSSL_VERSION_TEXT", .{ .string = Value.String.borrowed("OpenSSL 3") });
        try c.put(a, "OPENSSL_VERSION_NUMBER", .{ .int = 0x30000000 });
        try c.put(a, "GD_VERSION", .{ .string = Value.String.borrowed("2.3.3") });
        try c.put(a, "GMP_VERSION", .{ .string = Value.String.borrowed("6.3.0") });
        try c.put(a, "INTL_ICU_VERSION", .{ .string = Value.String.borrowed("77.1") });
        try c.put(a, "LIBXML_DOTTED_VERSION", .{ .string = Value.String.borrowed("2.9.13") });
        try c.put(a, "SODIUM_LIBRARY_VERSION", .{ .string = Value.String.borrowed("1.0.21") });
        try c.put(a, "ZLIB_VERSION", .{ .string = Value.String.borrowed("1.2.12") });
        {
            // PCRE_VERSION / _MAJOR / _MINOR from the linked libpcre2. vendor
            // polyfills (symfony/polyfill-intl-grapheme) reference PCRE_VERSION
            // at load time; an undefined constant throws and breaks the polyfill
            const pv = @import("../stdlib/pcre.zig").libVersion();
            if (pv.len > 0) {
                try c.put(a, "PCRE_VERSION", .{ .string = Value.String.borrowed(pv) });
                var major: i64 = 0;
                var minor: i64 = 0;
                if (std.mem.indexOfScalar(u8, pv, '.')) |dot| {
                    major = std.fmt.parseInt(i64, pv[0..dot], 10) catch 0;
                    const rest = pv[dot + 1 ..];
                    const end = std.mem.indexOfAny(u8, rest, " .") orelse rest.len;
                    minor = std.fmt.parseInt(i64, rest[0..end], 10) catch 0;
                }
                try c.put(a, "PCRE_VERSION_MAJOR", .{ .int = major });
                try c.put(a, "PCRE_VERSION_MINOR", .{ .int = minor });
            }
        }
        try c.put(a, "PHP_SAPI", .{ .string = Value.String.borrowed("cli") });
        try c.put(a, "PHP_OS", .{ .string = Value.String.borrowed(if (platform.is_windows) "WINNT" else if (platform.is_macos) "Darwin" else "Linux") });
        try c.put(a, "DIRECTORY_SEPARATOR", .{ .string = Value.String.borrowed(if (platform.is_windows) "\\" else "/") });
        try c.put(a, "PATH_SEPARATOR", .{ .string = Value.String.borrowed(if (platform.is_windows) ";" else ":") });
        // syslog priority + facility constants (zphp lacks a real syslog
        // backend, but vendor code references these constants at config time)
        try c.put(a, "LOG_EMERG", .{ .int = 0 });
        try c.put(a, "LOG_ALERT", .{ .int = 1 });
        try c.put(a, "LOG_CRIT", .{ .int = 2 });
        try c.put(a, "LOG_ERR", .{ .int = 3 });
        try c.put(a, "LOG_WARNING", .{ .int = 4 });
        try c.put(a, "LOG_NOTICE", .{ .int = 5 });
        try c.put(a, "LOG_INFO", .{ .int = 6 });
        try c.put(a, "LOG_DEBUG", .{ .int = 7 });
        try c.put(a, "LOG_KERN", .{ .int = 0 });
