    // free_all=true frees the whole heap (deinit). free_all=false (serve-mode
    // reset) keeps the immutable builtin prefix [0..builtin_*_hw] of each list so
    // stdlib classes' enum-case objects survive and don't need re-creating
    // diagnostic for bounded-memory work: live vs pooled heap structures at
    // the end of a run. a loop that leaks shows up as a live count that grows
    // with the iteration count instead of plateauing
    fn printHeapStats(self: *VM) void {
        var live_objects: usize = 0;
        for (self.objects.items) |o| if (!o.pooled) {
            live_objects += 1;
        };
        var live_arrays: usize = 0;
        for (self.arrays.items) |a| if (!a.pooled) {
            live_arrays += 1;
        };
        var live_gens: usize = 0;
        for (self.generators.items) |g| if (!g.pooled) {
            live_gens += 1;
        };
        std.debug.print("drain: arrays deferred by stack root {d}, by container owner {d}\n", .{ self.stat_deferred_stack, self.stat_deferred_container });
        std.debug.print("heap: objects {d} live / {d} allocated, arrays {d} live / {d} allocated, generators {d} live / {d} allocated, strings arena {d}, captures {d} live entries / {d} slots, pending strings {d}\n", .{
            live_objects,            self.objects.items.len,
            live_arrays,             self.arrays.items.len,
            live_gens,               self.generators.items.len,
            self.strings.items.len,  self.capture_index.count(),
            self.captures.items.len, self.pending_string_release.items.len,
        });
        std.debug.print("heap: ref cells {d} live / {d} allocated, {d} recycled\n", .{ self.ref_cells.items.len - self.free_cells.items.len, self.ref_cells.items.len, self.free_cells.items.len });
    }

    fn freeHeapItems(self: *VM, free_all: bool) void {
        const str_start: usize = if (free_all) 0 else self.builtin_str_hw;
        const arr_start: usize = if (free_all) 0 else self.builtin_arr_hw;
        const obj_start: usize = if (free_all) 0 else self.builtin_obj_hw;
        self.heap_teardown = true;
        self.last_return_ref = null;
        defer self.heap_teardown = false;
        // static state (class static props, function statics, superglobals)
        // holds owned values that no frame releases
        var constant_it = self.php_constants.valueIterator();
        while (constant_it.next()) |value| {
            if (value.* == .string) {
                self.releaseValue(value.*);
                value.* = .null;
            }
        }
        // builtin classes survive a serve reset with their constants, enum
        // cases, and property defaults intact; only user classes are torn down
        var class_it = self.classes.iterator();
        while (class_it.next()) |class_entry| {
            if (!free_all and self.builtin_classes.contains(class_entry.key_ptr.*)) continue;
            const class = class_entry.value_ptr;
            for (class.properties.items) |*property| {
                if (property.default == .string) {
                    self.releaseValue(property.default);
                    property.default = .null;
                }
            }
            for (class.static_props.values()) |*value| {
                self.releaseValue(value.*);
                value.* = .null;
            }
            var const_it = class.constants.valueIterator();
            while (const_it.next()) |value| {
                self.releaseValue(value.*);
                value.* = .null;
            }
        }
        var static_cells = self.statics_cells.valueIterator();
        while (static_cells.next()) |cell| {
            self.releaseValue(cell.*.*);
            cell.*.* = .null;
        }
        var rv_it = self.request_vars.valueIterator();
        while (rv_it.next()) |value| {
            self.releaseValue(value.*);
            value.* = .null;
        }
        // reference cells own their values; drop them while the heap is intact
        for (self.ref_cells.items) |cell| {
            self.releaseValue(cell.value);
            cell.value = .null;
            cell.dead = true;
        }
        var global_cells = self.globals_cells.valueIterator();
        while (global_cells.next()) |cell| {
            self.releaseValue(cell.*.*);
            cell.*.* = .null;
        }
        // suspended generators and fibers hold values (locals, stacks, current
        // values, callables); release them while the heap and the capture
        // registry are still intact, since their frames release closures by name
        for (self.generators.items) |g| if (!g.pooled) {
            self.releaseGeneratorVars(g);
            self.releaseGeneratorCurrent(g);
            self.releaseValue(g.return_value);
            g.return_value = .null;
            self.releaseGeneratorClosure(g);
        };
        for (self.fibers.items) |f| if (!f.pooled) {
            self.cleanupFiberFrames(f);
            for (f.saved_stack.items) |value| self.stackRelease(value);
            f.saved_stack.clearRetainingCapacity();
            self.releaseValue(f.callable);
            self.releaseValue(f.suspend_value);
            self.releaseValue(f.return_value);
            f.callable = .null;
            f.suspend_value = .null;
            f.return_value = .null;
        };
        @import("../stdlib/pdo.zig").cleanupResources(self.objects);
        self.teardownCaptures();
        // cleanup subsystem resources before freeing strings, because cleanup
        // reads class_name from each object and those names may live in self.strings
        // (e.g. when created by unserialize via ctx.createString)
        @import("../stdlib/curl.zig").cleanupResources(self.objects);
        @import("../stdlib/filesystem.zig").cleanupHandles(self.objects);
        @import("../stdlib/dom.zig").cleanupResources(self.objects);
        @import("../stdlib/simplexml.zig").cleanupResources(self.objects);
        @import("../stdlib/xmlreader.zig").cleanupResources(self.objects);
        @import("../stdlib/xmlwriter.zig").cleanupResources(self.objects);
        @import("../stdlib/intl.zig").cleanupResources(self.objects);
        @import("../stdlib/gmp.zig").cleanupResources(self.objects);
        @import("../stdlib/hash.zig").cleanupResources(self.objects);
        @import("../stdlib/workers.zig").cleanupResources(self.objects);
        @import("../stdlib/channel.zig").cleanupResources(self.objects);
        @import("../stdlib/buffer.zig").cleanupResources(self.objects);
        extension.cleanupResources(self.objects);
        @import("../stdlib/gd.zig").cleanupResources(self.objects);
        @import("../stdlib/ftp.zig").cleanupResources(self.objects);
        @import("../stdlib/ldap.zig").cleanupResources(self.objects);
        @import("../stdlib/mysqli.zig").cleanupConnections(self.objects);
        // clean up fiber frames before strings/arrays/objects since fiber frames
        // may reference values that get freed by those passes
        for (self.fibers.items) |f| if (!f.pooled) self.cleanupFiberFrames(f);
        for (self.strings.items[str_start..]) |s| self.allocator.free(s);
        for (self.arrays.items[arr_start..]) |a| {
            if (!a.pooled) {
                if (self.globals_array == null or a != self.globals_array.?) {
                    for (a.entries.items) |*entry| {
                        if (entry.value == .string) {
                            self.releaseValue(entry.value);
                            entry.value = .null;
                        }
                    }
                }
                a.deinit(self.allocator);
            }
            self.allocator.destroy(a);
        }
        for (self.objects.items[obj_start..]) |o| {
            if (!o.pooled) {
                if (o.lazyInitializer() == .string) {
                    self.releaseValue(o.lazyInitializer());
                    o.lazy.?.initializer = .null;
                }
                if (o.fakeClosure()) |state| {
                    if (state.callable == .string) self.releaseValue(state.callable);
                    o.native = .{};
                    self.allocator.destroy(state);
                }
                if (o.slots) |slots| {
                    for (slots) |*slot| {
                        if (slot.* == .string) {
                            self.releaseValue(slot.*);
                            slot.* = .null;
                        }
                    }
                }
                var prop_it = o.properties.iterator();
                while (prop_it.next()) |entry| {
                    if (entry.value_ptr.* == .string) {
                        self.releaseValue(entry.value_ptr.*);
                        entry.value_ptr.* = .null;
                    }
                }
                o.deinit(self.allocator);
            }
            self.allocator.destroy(o);
        }
        self.drainPendingStringReleases();
        for (self.generators.items) |g| {
            if (!g.pooled) g.deinit(self.allocator);
            self.allocator.destroy(g);
        }
        for (self.fibers.items) |f| {
            if (!f.pooled) f.deinit(self.allocator);
            self.allocator.destroy(f);
        }
        for (self.ref_cells.items) |c| self.allocator.destroy(c);
        var statics_iter = self.statics.keyIterator();
        while (statics_iter.next()) |k| self.allocator.free(k.*);
        if (!self.serve_mode) {
            for (self.compile_results.items) |r| {
                var result = r;
                result.deinit();
                self.allocator.destroy(result);
            }
        }
    }

    // deinit + remove every entry whose key is NOT in the builtin set. keys are
    // persistent (chunk constants or static literals) so this is safe after the
    // request heap has been freed. value type must have deinit(allocator)
    fn removeNonBuiltin(self: *VM, map: anytype, builtin: *const std.StringHashMapUnmanaged(void)) void {
        var to_remove: std.ArrayListUnmanaged([]const u8) = .empty;
        defer to_remove.deinit(self.allocator);
        var it = map.iterator();
        while (it.next()) |e| {
            if (!builtin.contains(e.key_ptr.*)) to_remove.append(self.allocator, e.key_ptr.*) catch {};
        }
        for (to_remove.items) |k| {
            if (map.fetchRemove(k)) |kv| {
                var v = kv.value;
                v.deinit(self.allocator);
            }
        }
    }

    fn freeClassState(self: *VM) void {
        self.any_prop_hooks = false;
        if (self.builtins_recorded) {
            // keep the immutable builtin classes/interfaces registered at init;
            // deinit + remove only the request-scoped (user) ones. names are chunk
            // constants (persistent CompileResult) or static literals, so they're
            // valid here even though freeHeapItems already ran
            self.removeNonBuiltin(&self.classes, &self.builtin_classes);
            self.removeNonBuiltin(&self.interfaces, &self.builtin_interfaces);
            self.classes.clearAliases();
            self.interfaces.clearAliases();
        } else {
            var class_iter = self.classes.valueIterator();
            while (class_iter.next()) |c| c.deinit(self.allocator);
            self.classes.clearRetainingCapacity();
            var iface_iter = self.interfaces.valueIterator();
            while (iface_iter.next()) |i| i.deinit(self.allocator);
            self.interfaces.clearRetainingCapacity();
        }
        self.traits.clearRetainingCapacity();
        self.ic.?.trait_sites.clearRetainingCapacity();
        var tu_iter = self.trait_uses.valueIterator();
        while (tu_iter.next()) |subs| self.allocator.free(subs.*);
        self.trait_uses.clearRetainingCapacity();
        {
            var tr_iter = self.trait_rules.valueIterator();
            while (tr_iter.next()) |r| r.deinit(self.allocator);
            self.trait_rules.clearRetainingCapacity();
        }
        var tp_iter = self.trait_props.valueIterator();
        while (tp_iter.next()) |props| self.allocator.free(props.*);
        self.trait_props.clearRetainingCapacity();
        var tsp_iter = self.trait_static_props.valueIterator();
        while (tsp_iter.next()) |props| self.allocator.free(props.*);
        self.trait_static_props.clearRetainingCapacity();
        var tc_iter = self.trait_constants.valueIterator();
        while (tc_iter.next()) |props| self.allocator.free(props.*);
        self.trait_constants.clearRetainingCapacity();
    }

    fn releaseFrames(self: *VM) void {
        for (0..self.frame_count) |i| self.deinitFrameSlot(i);
        // sweep any maps left in slots above frame_count from non-popFrame
        // paths (fast pops, exception unwinds, generator suspends).
        // do not touch locals/vars - those are owned by the call path or
        // already freed; only the ref_* maps can persist past pop.
        if (self.frame_high_water > self.frame_count) {
            for (self.frame_count..self.frame_high_water) |i| {
                self.deinitRefSlots(&self.frames[i].ref_slots);
                self.unregFrameBindings(&self.frames[i]);
                self.frames[i].ref_slots = .{};
                self.frames[i].ref_owner = 0;
            }
        }
    }

    pub fn deinit(self: *VM) void {
        self.sensitive_params.deinit(self.allocator);
        if (self.unwind_marker) |marker| {
            self.allocator.destroy(marker);
            self.unwind_marker = null;
        }
        self.setStrtokState(null);
        self.clearLastError();
        extension.vmDeinit(self);
        if (self.ic) |ic| for (ic.arg_stack[0..ic.arg_stack_room.committed]) |*source| self.releaseArgSource(source);
        self.clearActiveArgSources();
        self.clearArgArraySources(null);
        self.releaseBoundArgSources(null);
        if (platform.getenv("ZPHP_HEAP_STATS") != null) self.printHeapStats();
        self.releaseFrames();
        self.releaseCallbackRegistries();
        output_control.releaseAll(self);
        self.freeHeapItems(true);
        self.gc_zero_sites.deinit(self.allocator);
        self.builtin_classes.deinit(self.allocator);
        self.builtin_interfaces.deinit(self.allocator);
        self.frame_room.deinit();
        self.stack_room.deinit();
        self.handler_room.deinit();
        if (self.ic) |ic_ptr| {
            ic_ptr.arg_arrays.deinit(self.allocator);
            ic_ptr.bound_arg_sources.deinit(self.allocator);
            ic_ptr.saved_sources.deinit(self.allocator);
            ic_ptr.arg_stack_room.deinit();
            ic_ptr.sp_save_room.deinit();
            ic_ptr.arg_counts_room.deinit();
            ic_ptr.fga_room.deinit();
            ic_ptr.fga_offsets_room.deinit();
            self.allocator.free(ic_ptr.active_args);
            self.allocator.free(ic_ptr.intent);
            ic_ptr.autoloading.deinit(self.allocator);
            ic_ptr.trait_sites.deinit(self.allocator);
            ic_ptr.included.deinit(self.allocator);
            self.dropIncludeError(&ic_ptr.include_parse_error);
            self.dropIncludeError(&ic_ptr.include_compile_error);
            ic_ptr.foreach_pins.deinit(self.allocator);
            self.freeIniValues(ic_ptr);
            ic_ptr.ini_values.deinit(self.allocator);
            freeOwnedKeys(self.allocator, &ic_ptr.include_paths);
            ic_ptr.include_paths.deinit(self.allocator);
            freeOwnedKeys(self.allocator, &ic_ptr.fn_lower);
            freeOwnedKeys(self.allocator, &ic_ptr.native_lower);
            freeOwnedKeys(self.allocator, &ic_ptr.resolved_calls);
            ic_ptr.fn_lower.deinit(self.allocator);
            ic_ptr.native_lower.deinit(self.allocator);
            ic_ptr.resolved_calls.deinit(self.allocator);
            self.clearResolvedMethods(ic_ptr);
            ic_ptr.resolved_methods.deinit(self.allocator);
            ic_ptr.top_dirty.deinit(self.allocator);
            if (ic_ptr.locals_cap > 0) self.allocator.free(ic_ptr.locals_buf[0..ic_ptr.locals_cap]);
            self.allocator.destroy(ic_ptr);
        }
        g_type_info.deinit(self.allocator);
        g_type_info = .{};
        self.functions.deinit(self.allocator);
        var ctfn_iter = self.chunk_to_func_names.iterator();
        while (ctfn_iter.next()) |e| e.value_ptr.*.deinit(self.allocator);
        self.chunk_to_func_names.deinit(self.allocator);
        var rpn_iter = self.ref_param_names.keyIterator();
        while (rpn_iter.next()) |k| self.allocator.free(k.*);
        self.ref_param_names.deinit(self.allocator);
        self.clearMethodNameIndex();
        self.method_names_by_class.deinit(self.allocator);
        self.chunk_to_result.deinit(self.allocator);
        self.clearPharAliases();
        self.phar_aliases.deinit(self.allocator);
        self.exception_handler_stack.deinit(self.allocator);
        for (self.vars_pool.items) |*hm| {
            var m = hm.*;
            m.deinit(self.allocator);
        }
        self.vars_pool.deinit(self.allocator);
        var pc_iter = self.phar_cache.iterator();
        while (pc_iter.next()) |e| {
            self.allocator.free(e.value_ptr.*.bytes);
            e.value_ptr.*.parsed.deinit(self.allocator);
            self.allocator.destroy(e.value_ptr.*);
            self.allocator.free(e.key_ptr.*);
        }
        self.phar_cache.deinit(self.allocator);
        self.profile_calls.deinit(self.allocator);
        // the compile results own the attributes
        self.function_attributes.deinit(self.allocator);
        self.last_dt.deinit(self.allocator);
        self.native_fns.deinit(self.allocator);
        self.output.deinit(self.allocator);
        self.strings.deinit(self.allocator);
        for (self.persistent_strings.items) |s| self.allocator.free(s);
        self.persistent_strings.deinit(self.allocator);
        self.captures.deinit(self.allocator);
        self.capture_index.deinit(self.allocator);
        self.interned_names.deinit(self.allocator);
        self.free_closure_names.deinit(self.allocator);
        self.php_constants.deinit(self.allocator);
        self.user_constants.deinit(self.allocator);
        self.deprecated_traits.deinit(self.allocator);
        self.constant_attributes.deinit(self.allocator);
        self.deprecated_globals.deinit(self.allocator);
        self.ini_settings.deinit(self.allocator);
        self.ini_callbacks.deinit(self.allocator);
        for (self.shutdown_callbacks.items) |cb| self.allocator.free(cb.args);
        self.shutdown_callbacks.deinit(self.allocator);
        self.tick_functions.deinit(self.allocator);
        self.error_handler_stack.deinit(self.allocator);
        self.arrays.deinit(self.allocator);
        self.free_arrays.deinit(self.allocator);
        self.released_arrays.deinit(self.allocator);
        self.objects.deinit(self.allocator);
        self.free_generators.deinit(self.allocator);
        self.free_fibers.deinit(self.allocator);
        self.free_objects.deinit(self.allocator);
        self.free_handles.deinit(self.allocator);
        self.released_objects.deinit(self.allocator);
        self.pending_destruct.deinit(self.allocator);
        self.default_holds.deinit(self.allocator);
        self.pending_array_release.deinit(self.allocator);
        self.pending_string_release.deinit(self.allocator);
        self.string_pool.deinit();
        self.pending_gen_release.deinit(self.allocator);
        self.pending_fiber_release.deinit(self.allocator);
        self.weakmaps.deinit(self.allocator);
        self.disabled_natives.deinit(self.allocator);
        self.weak_references.deinit(self.allocator);
        self.held_exceptions.deinit(self.allocator);
        self.initializer_scopes.deinit(self.allocator);
        self.constants_visited.deinit(self.allocator);
        self.trait_constant_checks.deinit(self.allocator);
        self.trait_property_checks.deinit(self.allocator);
        self.trait_constant_sources.deinit(self.allocator);
        self.clearTraitTables();
        self.trait_tables.deinit(self.allocator);
        self.trait_tables_retired.deinit(self.allocator);
        var copies = self.trait_method_copies.valueIterator();
        while (copies.next()) |copy| self.allocator.destroy(copy.*);
        self.trait_method_copies.deinit(self.allocator);
        for (self.trait_method_stale.items) |copy| self.allocator.destroy(copy);
        self.trait_method_stale.deinit(self.allocator);
        self.cycle_candidates.deinit(self.allocator);
        self.cycle_array_candidates.deinit(self.allocator);
        self.cycle_gen_candidates.deinit(self.allocator);
        self.cycle_fiber_candidates.deinit(self.allocator);
        self.cycle_work.deinit(self.allocator);
        self.array_ref_bindings.deinit(self.allocator);
        if (self.ref_index) |ri| {
            ri.deinit(self.allocator);
            self.allocator.destroy(ri);
            self.ref_index = null;
        }
        if (self.proc_children) |pc| {
            self.reapProcChildren();
            pc.deinit(self.allocator);
            self.allocator.destroy(pc);
            self.proc_children = null;
        }
        self.generators.deinit(self.allocator);
        self.fibers.deinit(self.allocator);
        self.ref_cells.deinit(self.allocator);
        self.free_cells.deinit(self.allocator);
        var class_iter = self.classes.valueIterator();
        while (class_iter.next()) |c| c.deinit(self.allocator);
        self.classes.deinit(self.allocator);
        var iface_iter = self.interfaces.valueIterator();
        while (iface_iter.next()) |i| i.deinit(self.allocator);
        self.interfaces.deinit(self.allocator);
        self.traits.deinit(self.allocator);
        var tu_iter = self.trait_uses.valueIterator();
        while (tu_iter.next()) |subs| self.allocator.free(subs.*);
        self.trait_uses.deinit(self.allocator);
        {
            var tr_iter = self.trait_rules.valueIterator();
            while (tr_iter.next()) |r| r.deinit(self.allocator);
            self.trait_rules.deinit(self.allocator);
        }
        var tmc_iter = self.trait_method_cache.valueIterator();
        while (tmc_iter.next()) |m| self.allocator.free(m.*);
        self.trait_method_cache.deinit(self.allocator);
        var tp_iter = self.trait_props.valueIterator();
        while (tp_iter.next()) |props| self.allocator.free(props.*);
        self.trait_props.deinit(self.allocator);
        var tsp_iter = self.trait_static_props.valueIterator();
        while (tsp_iter.next()) |props| self.allocator.free(props.*);
        self.trait_static_props.deinit(self.allocator);
        var tc_iter = self.trait_constants.valueIterator();
        while (tc_iter.next()) |props| self.allocator.free(props.*);
        self.trait_constants.deinit(self.allocator);
        self.statics.deinit(self.allocator);
        self.statics_cells.deinit(self.allocator);
        self.globals_cells.deinit(self.allocator);
        self.static_vars.deinit(self.allocator);
        self.global_vars.deinit(self.allocator);
        self.clearRealDirCache();
        self.realdir_cache.deinit(self.allocator);
        self.clearStreamWrappers();
        self.stream_wrappers.deinit(self.allocator);
        self.stream_filters_user.deinit(self.allocator);
        if (self.serve_mode) {
            for (self.compile_results.items) |r| {
                var result = r;
                result.deinit();
                self.allocator.destroy(result);
            }
        }
        self.compile_results.deinit(self.allocator);
        self.ob_stack.deinit(self.allocator);
        self.request_vars.deinit(self.allocator);
        self.autoload_callbacks.deinit(self.allocator);
        if (self.spl_autoload_extensions) |exts| self.allocator.free(exts);
        self.magic_guards.deinit(self.allocator);
        self.magic_call_guard.deinit(self.allocator);
        for (self.reinit_windows.items) |*window| window.written.deinit(self.allocator);
        self.reinit_windows.deinit(self.allocator);
        self.linking.deinit(self.allocator);
        self.delayed_autoloads.deinit(self.allocator);
        self.nearly_linked.deinit(self.allocator);
        for (self.trait_deferred.items) |d| inheritance.discardDeferred(self, d);
        self.trait_deferred.deinit(self.allocator);
        self.prop_hook_guard.deinit(self.allocator);
        for (self.serve_cache_keys.items) |k| self.allocator.free(k);
        self.serve_cache_keys.deinit(self.allocator);
        self.serve_compile_cache.deinit(self.allocator);
        // last: everything above freed through it
        if (self.memory) |account| {
            self.memory = null;
            account.parent.destroy(account);
        }
    }

    pub fn clearRealDirCache(self: *VM) void {
        var it = self.realdir_cache.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
            self.allocator.free(entry.value_ptr.*);
        }
        self.realdir_cache.clearRetainingCapacity();
    }

    pub fn reset(self: *VM) void {
        self.sensitive_params.clearRetainingCapacity();
        @import("../stdlib/locale.zig").resetAfterRequest();
        if (self.ic) |ic| {
            for (ic.arg_stack[0..ic.arg_stack_room.committed]) |*source| self.releaseArgSource(source);
            self.clearActiveArgSources();
            self.clearArgArraySources(null);
            self.releaseBoundArgSources(null);
            ic.active_frame = 0;
            self.arg_source_end = 0;
            ic.arg_arrays.clearRetainingCapacity();
        }
        self.installHooks();
        self.releaseFrames();
        self.releaseCallbackRegistries();
        output_control.releaseAll(self);
        self.ob_deactivated = false;
        // reap before freeHeapItems frees the proc objects (the map keys)
        self.reapProcChildren();
        extension.endRequest(self);
        // a request's resources are freed with its heap; ids restart after
        // the three std streams, which live with the builtins
        self.default_stream_context = null;
        self.last_directory = null;
        self.next_resource_id = 3;
        self.frame_high_water = 0;
        self.obj_ref_active = false;
        self.array_ref_active = false;
        self.array_ref_bindings.clearRetainingCapacity();
        self.persistent_ref_owner = 0;
        self.last_return_ref_owner = 0;
        if (self.ref_index) |ri| ri.clear(self.allocator);
        // serve mode keeps the builtin heap + class registration across requests
        self.freeHeapItems(!self.serve_mode);
        if (self.serve_mode) self.freeClassState();
        self.frame_count = 0;
        self.sp = 0;
        self.handler_count = 0;
        self.handler_floor = 0;
        // pending_exception holds a *PhpObject into the arena freeHeapItems
        // above just freed. leaving it set means the next request's native-call
        // error path (which reads pending_exception before deciding it threw)
        // dereferences a dangling exception object
        // -> intermittent segfault (the freed pages are sometimes still mapped).
        // exception_handler_stack holds set_exception_handler callables (closures
        // / array callables) that are likewise per-request and dangle after free
        self.pending_exception = null;
        self.exception_handler_stack.clearRetainingCapacity();
        self.clearPharAliases();
        self.current_fiber = null;
        self.fiber_suspend_pending = false;
        self.fiber_suspend_value = .null;
        self.error_msg = null;
        self.exit_requested = false;
        self.output.clearRetainingCapacity();
        // serve mode keeps the builtin heap prefix (freeHeapItems freed only the
        // request items beyond the high-water marks); shrink the tracking lists
        // back to those marks instead of clearing them entirely
        self.free_arrays.clearRetainingCapacity();
        self.released_arrays.clearRetainingCapacity();
        self.free_objects.clearRetainingCapacity();
        self.released_objects.clearRetainingCapacity();
        self.free_handles.clearRetainingCapacity();
        self.free_generators.clearRetainingCapacity();
        if (self.serve_mode and self.builtins_recorded) {
            self.strings.shrinkRetainingCapacity(self.builtin_str_hw);
            self.arrays.shrinkRetainingCapacity(self.builtin_arr_hw);
            self.objects.shrinkRetainingCapacity(self.builtin_obj_hw);
        } else {
            self.strings.clearRetainingCapacity();
            self.arrays.clearRetainingCapacity();
            self.objects.clearRetainingCapacity();
        }
        self.generators.clearRetainingCapacity();
        self.fibers.clearRetainingCapacity();
        self.gc_dtor_fiber = null;
        self.ref_cells.clearRetainingCapacity();
        self.free_cells.clearRetainingCapacity();
        self.last_return_ref = null;
        // pending_destruct / pending_array_release hold *PhpObject / *PhpArray
        // pointers that freeHeapItems above just freed - they MUST be cleared
        // before the next request runs or drainPendingDestruct will walk
        // dangling pointers (the cursors also need resetting, otherwise
        // even a re-cleared list would skip-via-cursor and re-add then walk)
        self.pending_destruct.clearRetainingCapacity();
        self.destruct_cursor = 0;
        self.pending_array_release.clearRetainingCapacity();
        self.array_release_cursor = 0;
        self.drainPendingStringReleases();
        self.pending_gen_release.clearRetainingCapacity();
        self.gen_release_cursor = 0;
        self.pending_fiber_release.clearRetainingCapacity();
        self.fiber_release_cursor = 0;
        self.weakmaps.clearRetainingCapacity();
        self.weak_references.clearRetainingCapacity();
        self.held_exceptions.clearRetainingCapacity();
        self.initializer_scopes.clearRetainingCapacity();
        self.constants_visited.clearRetainingCapacity();
        self.trait_constant_checks.clearRetainingCapacity();
        self.trait_property_checks.clearRetainingCapacity();
        self.trait_constant_sources.clearRetainingCapacity();
        self.clearTraitTables();
        self.constant_eval_depth = 0;
        self.lazy_constant_classes = 0;
        for (self.shutdown_callbacks.items) |cb| self.allocator.free(cb.args);
        self.shutdown_callbacks.clearRetainingCapacity();
        self.cycle_candidates.clearRetainingCapacity();
        self.cycle_array_candidates.clearRetainingCapacity();
        // the request's generators and fibers are freed by now: the lists are
        // dropped without reading them
        self.cycle_gen_candidates.clearRetainingCapacity();
        self.cycle_fiber_candidates.clearRetainingCapacity();
        self.captures.clearRetainingCapacity();
        self.capture_index.clearRetainingCapacity();
        self.interned_names.clearRetainingCapacity();
        self.ob_stack.clearRetainingCapacity();
        self.request_vars.clearRetainingCapacity();
        self.response_code = 200;
        self.response_headers = null;
        self.last_http_response_headers = null;
        self.headers_sent = false;
        self.default_tz_name = "UTC";
        self.default_tz_offset = 0;
        // per-request runtime settings and last-error state; the strings
        // below live in the request arena that this reset frees
        self.error_reporting_level = 30719;
        // ini_set stores keys and values in the request arena freed below;
        // a stale entry would compare freed bytes on the next put
        self.ini_settings.clearRetainingCapacity();
        if (self.ic) |ic_ptr| self.freeIniValues(ic_ptr);
        self.rng_seeded = false;
        self.setStrtokState(null);
        self.strtok_pos = 0;
        self.clearLastError();
        self.last_dt.deinit(self.allocator);
        self.last_intl_error_code = 0;
        self.exit_code = 0;
        self.statics.clearRetainingCapacity();
        self.statics_cells.clearRetainingCapacity();
        self.globals_cells.clearRetainingCapacity();
        self.globals_array = null;
        self.static_vars.clearRetainingCapacity();
        self.global_vars.clearRetainingCapacity();
        if (self.ic) |ic_ptr| {
            ic_ptr.included.clearRetainingCapacity();
            ic_ptr.pending_defaults = 0;
            self.dropIncludeError(&ic_ptr.include_parse_error);
            self.dropIncludeError(&ic_ptr.include_compile_error);
            ic_ptr.foreach_pins.clearRetainingCapacity();
        }
        self.clearRealDirCache();
        self.clearStreamWrappers();
        self.magic_guards.clearRetainingCapacity();
        self.magic_call_guard.clearRetainingCapacity();
        if (self.serve_mode) {
            self.functions.clearRetainingCapacity();
            if (self.ic) |ic_ptr| {
                freeOwnedKeys(self.allocator, &ic_ptr.fn_lower);
                freeOwnedKeys(self.allocator, &ic_ptr.resolved_calls);
                ic_ptr.fn_lower.clearRetainingCapacity();
                ic_ptr.resolved_calls.clearRetainingCapacity();
                self.clearResolvedMethods(ic_ptr);
                ic_ptr.class_const = @splat(.{});
            }
            // chunk_to_func_names indexes per-chunk name lists - many entries
            // are closure instance names (`__closure_N_inst_M`, `__closure_bound_N`)
            // allocated into self.strings and freed by the clearRetainingCapacity
            // above. the chunk pointers themselves stay valid (cached compile
            // results persist across requests) so request 2's registerFunction
            // will rebuild the index. but if we leave the old entries in place
            // the indexFunctionByChunk dedup walk std.mem.eql's against dangling
            // slices and segfaults
            var ctfn_it = self.chunk_to_func_names.iterator();
            while (ctfn_it.next()) |e| e.value_ptr.*.deinit(self.allocator);
            self.chunk_to_func_names.clearRetainingCapacity();
            self.clearMethodNameIndex();
            self.php_constants.clearRetainingCapacity();
            self.user_constants.clearRetainingCapacity();
            self.deprecated_traits.clearRetainingCapacity();
            self.constant_attributes.clearRetainingCapacity();
            self.deprecated_globals.clearRetainingCapacity();
            initConstants(&self.php_constants, self.allocator) catch {};
            extension.applyConstants(self) catch {};
            // builtins persist across reset now (freeClassState kept them), so the
            // stdlib classes + their native methods + enum objects DON'T need
            // rebuilding every request - that re-registration was the dominant
            // warm-request cost (native_fns put/grow/hash churn). only re-seed when
            // builtins weren't snapshotted (shouldn't happen in serve mode)
            if (!self.builtins_recorded) registerStdlibClasses(self, self.allocator) catch {};
            self.closure_instance_count = 0;
        } else {
            self.compile_results.clearRetainingCapacity();
            self.chunk_to_result.clearRetainingCapacity();
        }
        // each request starts its memory count and limit afresh
        if (self.memory) |account| {
            self.applyConfiguredMemoryLimit(false);
            account.rebase();
        }
    }

    fn releaseHookFn(ctx: *anyopaque, value: Value) void {
        const vm: *VM = @ptrCast(@alignCast(ctx));
        vm.releaseValue(value);
    }

    // container stores release the value they replace through this hook.
    // it is thread-local and worker VMs are built on the main thread but run
    // on their own, so every execution entry point re-installs it
    pub fn installHooks(self: *VM) void {
        const hooks = @import("value.zig").hooks();
        hooks.release = .{ .ctx = self, .call = releaseHookFn };
        hooks.cell_unbind = .{ .ctx = self, .call = cellUnbindHook };
        hooks.object = .{ .ctx = self, .cast = objectCastHook, .compare = objectCompareHook };
    }

    fn objectCastHook(ctx: *anyopaque, obj: *PhpObject, target: @import("value.zig").NumericCast) ?Value {
        const self: *VM = @ptrCast(@alignCast(ctx));
        var name: ?[]const u8 = obj.class_name;
        while (name) |n| {
            const def = self.classes.get(n) orelse return null;
            if (def.native_cast) |cast| return cast(obj, target);
            name = def.parent;
        }
        return null;
    }

    // natives compare without a way to raise, so an operand the class
    // rejects falls back to the ordinary object comparison
    fn objectCompareHook(ctx: *anyopaque, a: Value, b: Value) ?i64 {
        const self: *VM = @ptrCast(@alignCast(ctx));
        const order = self.objectBinop(.compare, a, b) catch {
            self.discardPending();
            return null;
        };
        return if (order) |v| v.int else null;
    }

    pub fn interpret(self: *VM, result: *const CompileResult) RuntimeError!void {
        self.installHooks();
        try @import("../ini_config.zig").applyToVm(self);
        try extension.beginRequest(self);
        if (std.fs.path.isAbsolute(result.file_path)) {
            if (try includes.canonical(self, result.file_path)) |main| try self.ic.?.included.put(self.allocator, main, {});
        }
        try self.registerResultFunctions(result);
        for (result.type_hints.items) |th| {
            try g_type_info.put(self.allocator, th.name, .{ .param_types = th.param_types, .return_type = th.return_type });
        }
        var vars: std.StringHashMapUnmanaged(Value) = .{};
        var it = self.request_vars.iterator();
        while (it.next()) |entry| {
            if (!isSuperglobal(entry.key_ptr.*)) try vars.put(self.allocator, entry.key_ptr.*, entry.value_ptr.*);
        }
        if (!vars.contains("$GLOBALS")) {
            const globals_arr = try self.allocArray();
            // $GLOBALS is a non-owning live view of the global variables
            globals_arr.* = .{ .weak = true };
            try vars.put(self.allocator, "$GLOBALS", .{ .array = globals_arr });
            self.globals_array = globals_arr;
            // self.globals_array is a durable VM-wide root - it must hold a
            // refcount, or once every frame that has $GLOBALS in its vars
            // exits, the array drops to 0 and is freed while still live
            // (refcounting Stage 2)
            arrayRetain(globals_arr);
        } else {
            const gv = vars.get("$GLOBALS").?;
            if (gv == .array) {
                self.globals_array = gv.array;
                gv.array.weak = true;
                arrayRetain(gv.array);
            }
        }
        var locals: []Value = &.{};
        if (result.local_count > 0) {
            locals = try self.allocator.alloc(Value, result.local_count);
            @memset(locals, .undef);
            for (result.slot_names, 0..) |sn, i| {
                if (sn.len > 0) {
                    if (vars.get(sn)) |val| locals[i] = val;
                }
            }
        }
        self.global_slot_names = result.slot_names;
        self.top_slot_names = result.slot_names;
        if (self.ic) |ic| {
            try ic.top_dirty.resize(self.allocator, result.slot_names.len, false);
            ic.top_dirty.unsetAll();
            ic.top_dirty_any = false;
        }
        self.source = result.source;
        self.file_path = result.file_path;
        self.script_strict_types = result.strict_types;
        self.frames[0] = .{ .chunk = &result.chunk, .ip = 0, .vars = vars, .locals = locals, .slot_names = result.slot_names };
        self.frame_count = 1;
        // Slots and vars mirror one owning binding.
        self.retainFrameObjects(0);
        self.obj_id_base = self.objects.items.len;
        // reset the per-allocation id counter so user-visible '#N' starts at 1
        // matching PHP. internal stdlib-init objects keep the ids they already
        // got (some of those are case singletons we hold references to)
        self.next_object_id = 0;
        self.free_handles.clearRetainingCapacity();
        // at script end run every still-live object's __destruct (PHP's
        // shutdown guarantee), then drain - on success or error
        defer if (!self.destructors_after_shutdown) self.runShutdownDestructors();
        try self.raiseCompileWarnings(result);
        self.run() catch |err| return self.reportMemoryExhausted(err);
    }

    // an allocation memory_limit refused surfaces as OutOfMemory wherever it
    // happened; raise php's fatal for it once the script has stopped
    pub fn reportMemoryExhausted(self: *VM, err: RuntimeError) RuntimeError {
        const account = self.memory orelse return err;
        const refused = account.refused orelse return err;
        if (account.reporting) return err;
        account.reporting = true;
        var buf: [160]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "Allowed memory size of {d} bytes exhausted (tried to allocate {d} bytes)", .{ account.limit, refused }) catch unreachable;
        // php drops every output buffer before reporting it, unless a
        // handler is running; their handlers are not run here
        if (self.ob_running == null) {
            if (self.ob_stack.items.len > 0) self.output.shrinkRetainingCapacity(@min(self.ob_stack.items[0].start, self.output.items.len));
            output_control.releaseAll(self);
        }
        self.raiseError(1, msg) catch |raised| return raised;
        return error.RuntimeError;
    }

    // memory_limit as configured: php.ini or -d, else php's default
    // warn: report a configured limit above max_memory_limit (startup only,
    // not again for each serve request)
    pub fn applyConfiguredMemoryLimit(self: *VM, warn: bool) void {
        var text = @import("../ini_config.zig").get("memory_limit") orelse "128M";
        var bytes = @import("memory.zig").parseQuantity(text).value;
        if (self.memoryLimitCap(bytes)) |cap| {
            if (warn and bytes >= 0) {
                var buf: [192]u8 = undefined;
                const msg = std.fmt.bufPrint(&buf, "Failed to set memory_limit to {d} bytes. Setting to max_memory_limit instead (currently: {d} bytes)", .{ bytes, cap.bytes }) catch "";
                self.raiseErrorAt(E_WARNING, msg, .{ .file = "Unknown", .line = 0 }) catch {};
            }
            text = cap.text;
            bytes = cap.bytes;
        }
        if (bytes != 0) self.memory.?.limit = if (bytes < 0) 0 else @intCast(bytes);
    }

    // php 8.5's max_memory_limit (a startup setting, -1 by default) caps
    // memory_limit: a larger or unlimited request is lowered to it. the cap's
    // text and bytes when the request exceeds it
    pub fn memoryLimitCap(self: *VM, requested: i64) ?struct { text: []const u8, bytes: i64 } {
        _ = self;
        const text = @import("../ini_config.zig").get("max_memory_limit") orelse return null;
        const max = @import("memory.zig").parseQuantity(text).value;
        if (max < 0 or (requested >= 0 and requested <= max)) return null;
        return .{ .text = text, .bytes = max };
    }

    // memory_get_usage(true): php reports memory in 2MB chunks
    pub fn realMemoryUsage(bytes: usize) usize {
        const chunk: usize = 2 * 1024 * 1024;
        return @max(chunk, std.mem.alignForward(usize, bytes, chunk));
    }

    // PHP guarantees every object still alive at request end has its
    // __destruct run during shutdown. refcounting fires most destructors at
    // the right time during the run; this sweep catches whatever is still
    // live (globals, refcount-inflated leftovers). walk newest-first; mark
    // destructed before calling so a destructor that touches the object does
    // not re-enter; drain afterwards so cascades fire
    // pooled object structs are reused out of creation order, so order the
    // final sweep by object id (creation order) rather than list position
    // php's zend_call_destructors: global variables holding the only
    // reference to an object are destroyed, last declared first, until a
    // pass destroys none; then every object left gets its destructor in
    // handle order
    pub fn runShutdownDestructors(self: *VM) void {
        self.shutdown_destructors = true;
        defer self.shutdown_destructors = false;
        // what shutdown runs is called by the engine: no user frame calls it
        var engine = self.engineCall();
        self.native_call = &engine;
        defer self.native_call = engine.outer;
        // where nothing reports what the destructors throw (serve, workers,
        // embedding), the script's own exception stays the one pending
        const prior = if (self.destructors_after_shutdown) null else self.takePending();
        defer if (!self.destructors_after_shutdown) {
            self.discardPending();
            if (prior) |exception| self.setPendingOwned(exception);
        };
        self.destroyGlobalsAtShutdown();
        var live: std.ArrayListUnmanaged(*PhpObject) = .empty;
        defer self.drain_raised = false;
        defer live.deinit(self.allocator);
        for (self.objects.items) |obj| {
            if (obj.destructed or obj.pooled or obj.resource) continue;
            live.append(self.allocator, obj) catch return;
        }
        std.mem.sort(*PhpObject, live.items, {}, struct {
            fn lessThan(_: void, a: *PhpObject, b: *PhpObject) bool {
                return a.id < b.id;
            }
        }.lessThan);
        // generators and fibers are objects to php: a suspended one is
        // destroyed in handle order with the rest (its finally blocks run)
        var waiting: std.ArrayListUnmanaged(Value) = .empty;
        defer waiting.deinit(self.allocator);
        for (self.generators.items) |g| {
            if (g.pooled or g.refcount == 0 or g.state != .suspended) continue;
            waiting.append(self.allocator, .{ .generator = g }) catch return;
        }
        for (self.fibers.items) |f| {
            if (f.pooled or f.refcount == 0 or f.state != .suspended or f == self.gc_dtor_fiber) continue;
            waiting.append(self.allocator, .{ .fiber = f }) catch return;
        }
        std.mem.sort(Value, waiting.items, {}, struct {
            fn handle(v: Value) u32 {
                return if (v == .generator) v.generator.handle else v.fiber.handle;
            }
            fn lessThan(_: void, a: Value, b: Value) bool {
                return handle(a) < handle(b);
            }
        }.lessThan);
        var next_waiting: usize = 0;
        for (live.items) |obj| {
            // generators and fibers with lower handles go first
            while (next_waiting < waiting.items.len) : (next_waiting += 1) {
                const w = waiting.items[next_waiting];
                const h = if (w == .generator) w.generator.handle else w.fiber.handle;
                if (h > obj.id) break;
                self.destroyAtShutdown(w);
            }
            if (self.pending_exception != null and self.destructors_after_shutdown) break;
            if (obj.destructed) continue;
            if (self.pendingExceptionIs(obj)) continue;
            obj.destructed = true;
            if (obj.ownsDestructor() and !obj.destructor_called and self.hasMethod(obj.class_name, "__destruct")) {
                if (self.destructorRefused(obj) catch true) continue;
                _ = self.callMethod(obj, "__destruct", &.{}) catch {
                    // php's uncaught exception ends the destructors: the
                    // objects left are freed without theirs
                    if (self.pending_exception == null or !self.destructors_after_shutdown) self.discardPending();
                };
            }
        }
        while (next_waiting < waiting.items.len) : (next_waiting += 1) self.destroyAtShutdown(waiting.items[next_waiting]);
        self.drain_raised = false;
        if (self.pending_exception != null and self.destructors_after_shutdown) {
            for (live.items) |obj| obj.destructor_called = true;
            return;
        }
        self.drainPendingDestruct();
        self.drain_raised = false;
    }

    // php_run_ticks: every tick function with its arguments, in the order
    // they were registered (one may register or unregister others)
    fn runTickFunctions(self: *VM) RuntimeError!void {
        var i: usize = 0;
        while (i < self.tick_functions.items.len) : (i += 1) {
            const entry = self.tick_functions.items[i];
            if (entry.calling) continue;
            self.tick_functions.items[i].calling = true;
            retainValue(entry.callable);
            defer self.releaseValue(entry.callable);
            var ctx = self.makeContext(null);
            // no fiber switch inside a tick function (zend_fiber_switch_block)
            self.fiber_switch_blocked += 1;
            const result = ctx.invokeCallable(entry.callable, entry.args);
            self.fiber_switch_blocked -= 1;
            // the list may have changed while it ran
            for (self.tick_functions.items, 0..) |*e, at| if (e.id == entry.id) {
                e.calling = false;
                i = at;
                break;
            };
            self.releaseValue(try result);
        }
    }

    pub fn releaseTickFunctions(self: *VM) void {
        for (self.tick_functions.items) |cb| {
            self.releaseValue(cb.callable);
            for (cb.args) |v| self.releaseValue(v);
            self.allocator.free(cb.args);
        }
        self.tick_functions.clearRetainingCapacity();
    }

    // zend_objects_destroy_object: a destructor the releasing scope can't
    // call isn't run. during the script that is an Error; once it ended, a
    // warning. true when it is refused
    fn destructorRefused(self: *VM, obj: *PhpObject) RuntimeError!bool {
        const found = self.findMethodInfo(obj.class_name, "__destruct") orelse return false;
        const vis = found.info.visibility;
        if (vis == .public) return false;
        if (self.shutdown_destructors) {
            const msg = try std.fmt.allocPrint(self.allocator, "Call to {s} {s}::__destruct() from global scope during shutdown ignored", .{ @tagName(vis), obj.class_name });
            defer self.allocator.free(msg);
            try self.raiseErrorAt(E_WARNING, msg, .{ .file = "Unknown", .line = 0 });
            return true;
        }
        const scope = self.currentDefiningClass();
        const allowed = if (vis == .private)
            (if (scope) |sc| std.ascii.eqlIgnoreCase(sc, obj.class_name) else false)
        else
            self.checkVisibility(found.defining, .protected) or self.protectedRootVisible(found.defining, "__destruct", .protected);
        if (allowed) return false;
        const msg = try std.fmt.allocPrint(self.allocator, "Call to {s} {s}::__destruct() from {s}{s}", .{ @tagName(vis), obj.class_name, if (scope != null) "scope " else "global scope", scope orelse "" });
        defer self.allocator.free(msg);
        try self.setPendingException("Error", msg);
        return true;
    }

    // a generator's or fiber's dtor at shutdown; an exception it throws
    // takes the one already pending as its previous
    fn destroyAtShutdown(self: *VM, v: Value) void {
        switch (v) {
            .generator => |g| {
                if (g.pooled or g.refcount == 0 or g.state != .suspended) return;
                genRetain(g);
                defer self.genRelease(g);
                const in_flight = self.takePending();
                self.closeGenerator(g, self.frame_count) catch {};
                self.settleDrainException(in_flight);
            },
            .fiber => |f| {
                if (f.pooled or f.refcount == 0 or f.state != .suspended) return;
                fiberRetain(f);
                defer self.fiberRelease(f);
                self.destroyFiber(f);
            },
            else => {},
        }
        if (self.hasPendingReleases()) self.drainPendingDestruct();
    }

    // php's zval_call_destructor: a global holding the only reference to
    // an object (a generator or fiber included) goes first
    fn soleShutdownReference(value: Value) bool {
        return switch (value) {
            .object => |o| o.refcount == 1 and !o.destructed,
            .generator => |g| g.refcount == 1,
            .fiber => |f| f.refcount == 1,
            else => false,
        };
    }

    fn destroyGlobalsAtShutdown(self: *VM) void {
        if (self.frame_count == 0) return;
        const frame = &self.frames[0];
        const names = self.global_slot_names;
        while (true) {
            var destroyed = false;
            // variables made at run time come after the compiled ones in
            // php's table; $GLOBALS keeps their order
            if (self.globals_array) |ga| {
                var gi = ga.entries.items.len;
                while (gi > 0) {
                    gi -= 1;
                    if (gi >= ga.entries.items.len) continue;
                    const entry = ga.entries.items[gi];
                    if (entry.key != .string) continue;
                    var buf: [256]u8 = undefined;
                    const key = entry.key.string.bytes();
                    if (key.len + 1 > buf.len) continue;
                    buf[0] = '$';
                    @memcpy(buf[1 .. key.len + 1], key);
                    const name = buf[0 .. key.len + 1];
                    var compiled = false;
                    for (names) |n| if (std.mem.eql(u8, n, name)) {
                        compiled = true;
                        break;
                    };
                    if (compiled or frame.ref_slots.contains(name)) continue;
                    const value = frame.vars.get(name) orelse continue;
                    if (!soleShutdownReference(value)) continue;
                    const removed = frame.vars.fetchRemove(name).?;
                    ga.remove(.{ .string = Value.String.borrowed(key) });
                    self.releaseValue(removed.value);
                    self.drainPendingDestruct();
                    if (self.pending_exception != null) return;
                    destroyed = true;
                }
            }
            var si = @min(names.len, frame.locals.len);
            while (si > 0) {
                si -= 1;
                const name = names[si];
                if (name.len == 0 or frame.ref_slots.contains(name)) continue;
                const value = if (frame.vars.get(name)) |v| v else frame.locals[si];
                if (!soleShutdownReference(value)) continue;
                if (frame.vars.fetchRemove(name)) |removed| {
                    self.releaseValue(removed.value);
                } else self.releaseValue(frame.locals[si]);
                frame.locals[si] = .undef;
                if (name.len > 1 and name[0] == '$') {
                    if (self.globals_array) |ga| ga.remove(.{ .string = Value.String.borrowed(name[1..]) });
                    if (self.globals_cells.get(name)) |cell| self.setCell(cell, .null);
                }
                self.drainPendingDestruct();
                if (self.pending_exception != null) return;
                destroyed = true;
            }
            if (!destroyed) break;
        }
    }

    // tracked allocPrint into self.error_msg. the underlying string is
    // appended to self.strings so it gets freed at vm.deinit/reset rather
    // than leaking when the error is recovered (e.g. caught by user code)
    pub fn setErrorMsg(self: *VM, comptime fmt: []const u8, args: anytype) void {
        const msg = std.fmt.allocPrint(self.allocator, fmt, args) catch {
            self.error_msg = null;
            return;
        };
        self.strings.append(self.allocator, msg) catch {
            self.allocator.free(msg);
            self.error_msg = null;
            return;
        };
        self.error_msg = msg;
    }

    pub fn registerFunction(self: *VM, func: *const ObjFunction) RuntimeError!void {
        if (self.functions.get(func.name)) |existing| if (existing == func) return;
        if (try self.functionRedeclarationMessage(func.name)) |msg| {
            defer self.allocator.free(msg);
            return self.raiseCompileFatal(msg, .{ .file = func.file_path, .line = func.start_line });
        }
        try self.noteFunctionName(func.name);
        try self.functions.put(self.allocator, func.name, func);
        try self.noteRefParams(func.name, func);
        try self.indexFunctionByChunk(func.name, &func.chunk);
    }

    fn freeOwnedKeys(a: std.mem.Allocator, map: anytype) void {
        if (@hasDecl(@TypeOf(map.*), "keys")) {
            for (map.keys()) |k| a.free(k);
            return;
        }
        var it = map.keyIterator();
        while (it.next()) |k| a.free(k.*);
    }

    fn isFreeFunctionName(name: []const u8) bool {
        return !std.mem.startsWith(u8, name, "__closure") and std.mem.indexOf(u8, name, "::") == null;
    }

    // a free function about to be declared: refuses a name that differs from
    // an existing one only by case, indexes its lowercase form, and forgets
    // cached resolutions it could now win
    // the short name a call site names its callee by: the method after
    // "::", the function after its namespace
    fn calleeShortName(name: []const u8) []const u8 {
        if (std.mem.lastIndexOf(u8, name, "::")) |sep| return name[sep + 2 ..];
        if (std.mem.lastIndexOfScalar(u8, name, '\\')) |sep| return name[sep + 1 ..];
        return name;
    }

    fn noteRefParams(self: *VM, name: []const u8, func: *const ObjFunction) !void {
        if (std.mem.indexOfScalar(bool, func.ref_params, true) == null) return;
        const lower = try std.ascii.allocLowerString(self.allocator, calleeShortName(name));
        const gop = self.ref_param_names.getOrPut(self.allocator, lower) catch |err| {
            self.allocator.free(lower);
            return err;
        };
        if (gop.found_existing) self.allocator.free(lower);
    }

    // true when no callee by this name can take a reference: no user function
    // or method with a by-reference parameter is registered under it, and no
    // native by it takes one
    fn nameTakesNoRef(self: *VM, raw: []const u8) bool {
        const short = calleeShortName(raw);
        var buf: [64]u8 = undefined;
        if (short.len > buf.len) return false;
        const lower = std.ascii.lowerString(buf[0..short.len], short);
        if (self.ref_param_names.contains(lower)) return false;
        return !byref_args.hasByRefParams(lower);
    }

    // true when the name a call site gives its callee shows every argument
    // goes by value
    fn callSiteNamesNoRef(self: *VM, chunk: *const Chunk, call_ip: usize) bool {
        const code = chunk.code.items;
        const consts = chunk.constants.items;
        const call_op = std.enums.fromInt(OpCode, code[call_ip]) orelse return false;
        return switch (call_op) {
            .call, .call_spread => self.nameTakesNoRef(consts[callOpU16(code, call_ip + 1)].string.bytes()),
            .method_call, .method_call_spread => blk: {
                // a closure's __invoke is registered under the closure's name
                const name = consts[callOpU16(code, call_ip + 1)].string.bytes();
                if (std.ascii.eqlIgnoreCase(name, "__invoke")) break :blk false;
                break :blk self.nameTakesNoRef(name);
            },
            .static_call, .static_call_spread => self.nameTakesNoRef(consts[callOpU16(code, call_ip + 3)].string.bytes()),
            .new_obj, .new_obj_dynamic => self.nameTakesNoRef("__construct"),
            else => false,
        };
    }

    fn noteFunctionName(self: *VM, name: []const u8) RuntimeError!void {
        if (!isFreeFunctionName(name)) return;
        const ic = self.ic.?;
        const lower = try std.ascii.allocLowerString(self.allocator, name);
        errdefer self.allocator.free(lower);
        try ic.fn_lower.put(self.allocator, lower, name);
        if (std.mem.indexOfScalar(u8, name, '\\') == null) return;
        var stale: std.ArrayListUnmanaged([]const u8) = .empty;
        defer stale.deinit(self.allocator);
        var it = ic.resolved_calls.keyIterator();
        while (it.next()) |k| if (std.ascii.eqlIgnoreCase(k.*, name)) try stale.append(self.allocator, k.*);
        for (stale.items) |k| {
            _ = ic.resolved_calls.remove(k);
            self.allocator.free(k);
        }
    }

    // the native registered under a lowercase name, whatever its case
    fn nativeNamed(self: *VM, lower: []const u8) ?[]const u8 {
        const ic = self.ic.?;
        if (ic.native_lower.count() == 0) {
            var it = self.native_fns.keyIterator();
            while (it.next()) |k| {
                const key = std.ascii.allocLowerString(self.allocator, k.*) catch return self.native_fns.getKey(lower);
                const gop = ic.native_lower.getOrPut(self.allocator, key) catch {
                    self.allocator.free(key);
                    return self.native_fns.getKey(lower);
                };
                if (gop.found_existing) self.allocator.free(key) else gop.value_ptr.* = k.*;
            }
        }
        return ic.native_lower.get(lower);
    }

    pub fn functionNamedIgnoringCase(self: *VM, name: []const u8) ?[]const u8 {
        var buf: [256]u8 = undefined;
        if (name.len > buf.len) return null;
        const lower = std.ascii.lowerString(buf[0..name.len], name);
        if (self.ic.?.fn_lower.get(lower)) |registered| return registered;
        return self.nativeNamed(lower);
    }

    // the registered name a call to `name` reaches when no function has exactly
    // that name: php matches function names case-insensitively, and a call
    // inside a namespace falls back to the global function of the same name
    pub fn resolveFunctionName(self: *VM, name: []const u8) ?[]const u8 {
        const ic = self.ic.?;
        if (ic.resolved_calls.get(name)) |hit| return hit;
        const target = self.functionNamedIgnoringCase(name) orelse fallback: {
            const pos = std.mem.lastIndexOfScalar(u8, name, '\\') orelse return null;
            const base = name[pos + 1 ..];
            if (base.len == 0) return null;
            break :fallback self.native_fns.getKey(base) orelse self.functions.getKey(base) orelse self.functionNamedIgnoringCase(base) orelse return null;
        };
        const key = self.allocator.dupe(u8, name) catch return target;
        ic.resolved_calls.put(self.allocator, key, target) catch self.allocator.free(key);
        return target;
    }

    // the registered name of the function a callable string names, matched
    // case-insensitively; a string never falls back to the global namespace
    pub fn canonicalFunctionName(self: *VM, raw_name: []const u8) ?[]const u8 {
        const name = if (raw_name.len > 0 and raw_name[0] == '\\') raw_name[1..] else raw_name;
        return self.native_fns.getKey(name) orelse self.functions.getKey(name) orelse self.functionNamedIgnoringCase(name);
    }

    pub fn functionExists(self: *VM, raw_name: []const u8) bool {
        return self.canonicalFunctionName(raw_name) != null;
    }

    // a chunk's line offsets index into its own compile result's source; a
    // result loaded from bytecode has no source and stores line numbers
    pub fn chunkSource(self: *const VM, chunk: *const Chunk) []const u8 {
        const result = self.chunk_to_result.get(@intFromPtr(chunk)) orelse return self.source;
        return result.source;
    }

    pub fn sourceLocation(self: *const VM, chunk: *const Chunk, ip: usize) ?bytecode.SourceLocation {
        return chunk.getSourceLocation(ip, self.chunkSource(chunk));
    }

    // register a compile result's functions: unconditional declarations are
    // hoisted (PHP early binding); conditional ones (cond_id != 0) wait for
    // their declare_fn opcode. every chunk is mapped to the result so
    // declare_fn can find its function from the executing frame's chunk
    pub fn registerResultFunctions(self: *VM, result: *const CompileResult) RuntimeError!void {
        try self.chunk_to_result.put(self.allocator, @intFromPtr(&result.chunk), result);
        // a script compiled again (an include run twice) brings the same
        // attributes; reflection may hold the first copy's arguments
        for (result.function_attrs.items) |fa| {
            const entry = try self.function_attributes.getOrPut(self.allocator, fa.name);
            if (!entry.found_existing) entry.value_ptr.* = fa.attrs;
        }
        for (result.functions.items) |*func| {
            try self.chunk_to_result.put(self.allocator, @intFromPtr(&func.chunk), result);
            if (func.cond_id == 0) try self.registerFunction(func);
        }
    }

    pub fn indexFunctionByChunk(self: *VM, name: []const u8, chunk: *const Chunk) RuntimeError!void {
        const gop = try self.chunk_to_func_names.getOrPut(self.allocator, @intFromPtr(chunk));
        if (!gop.found_existing) gop.value_ptr.* = .empty;
        for (gop.value_ptr.*.items) |existing| if (std.mem.eql(u8, existing, name)) return;
        try gop.value_ptr.*.append(self.allocator, name);
        if (std.mem.startsWith(u8, name, "__closure")) return;
        const sep = std.mem.indexOf(u8, name, "::") orelse return;
        const by_class = try self.method_names_by_class.getOrPut(self.allocator, name[0..sep]);
        if (!by_class.found_existing) by_class.value_ptr.* = .empty;
        try by_class.value_ptr.append(self.allocator, name);
    }

    fn clearMethodNameIndex(self: *VM) void {
        var it = self.method_names_by_class.valueIterator();
        while (it.next()) |names| names.deinit(self.allocator);
        self.method_names_by_class.clearRetainingCapacity();
    }

    // minimal PHP eval(): parses+compiles a code string and runs it as a
    // nested frame. class/function/const declarations land in the VM tables
    // naturally so no scope merging is needed. local variables in the eval'd
    // code do NOT leak into the caller's scope (PHP eval merges in both
    // directions; this implementation is forward-only - sufficient for
    // mock/template generators that eval class declarations at runtime).
    // returns null on success, throws ParseError on syntax error
    // token_get_all(..., TOKEN_PARSE) parses the code and raises the syntax
    // error, located in no file, the way php's parser would
    pub fn checkSyntax(self: *VM, source: []const u8) RuntimeError!void {
        var ast = parser_mod.parse(self.allocator, source) catch return error.OutOfMemory;
        defer ast.deinit();
        if (ast.errors.len == 0) return;
        const found = try @import("../error_format.zig").syntaxError(self.allocator, &ast);
        defer self.allocator.free(found.message);
        try self.setPendingException("ParseError", found.message);
        if (self.pending_exception) |exc| if (exc == .object) {
            try exc.object.set(self.allocator, "file", .{ .string = Value.String.borrowed("") });
            try exc.object.set(self.allocator, "line", .{ .int = found.line });
        };
        return error.RuntimeError;
    }

    pub fn evalSource(self: *VM, source: []const u8) RuntimeError!Value {
        // prepend <?php so the lexer enters PHP mode. dupe so the source
        // slice can be owned by the heap CompileResult's string_allocs
        const wrapped = std.fmt.allocPrint(self.allocator, "<?php {s}", .{source}) catch return error.OutOfMemory;
        var ast = parser_mod.parse(self.allocator, wrapped) catch {
            self.allocator.free(wrapped);
            return error.OutOfMemory;
        };
        if (ast.errors.len > 0) {
            const found = @import("../error_format.zig").syntaxError(self.allocator, &ast) catch |err| {
                ast.deinit();
                self.allocator.free(wrapped);
                return err;
            };
            const error_line = found.line;
            ast.deinit();
            self.allocator.free(wrapped);
            defer self.allocator.free(found.message);
            try self.setPendingException("ParseError", found.message);
            // php places the error in the evaluated code: "<file>(<line>) : eval()'d code"
            if (self.pending_exception) |exc| if (exc == .object) {
                const caller = self.currentSourcePosition();
                const where = try std.fmt.allocPrint(self.allocator, "{s}({d}) : eval()'d code", .{ caller.file, caller.line });
                defer self.allocator.free(where);
                try exc.object.setCopiedString(self.allocator, "file", where);
                try exc.object.set(self.allocator, "line", .{ .int = error_line });
            };
            return error.RuntimeError;
        }
        // php names evaluated code after where eval ran
        const eval_site = self.currentSourcePosition();
        const display_path = std.fmt.allocPrint(self.allocator, "{s}({d}) : eval()'d code", .{ eval_site.file, eval_site.line }) catch {
            ast.deinit();
            self.allocator.free(wrapped);
            return error.OutOfMemory;
        };
        var diag: ?compiler_mod.Diagnostic = null;
        var result = compiler_mod.compileWithOrigin(&ast, self.allocator, .{ .file_path = display_path, .diagnostic = &diag }) catch {
            const line = if (diag) |d| @import("../error_format.zig").compileErrorLine(&ast, d) else 0;
            ast.deinit();
            self.allocator.free(wrapped);
            self.allocator.free(display_path);
            if (diag) |d| {
                const caller = self.currentSourcePosition();
                const where = try std.fmt.allocPrint(self.allocator, "{s}({d}) : eval()'d code", .{ caller.file, caller.line });
                defer self.allocator.free(where);
                // eval is an opcode to php: a compile fatal's trace has no
                // frame for it
                const outer_call = self.native_call;
                defer self.native_call = outer_call;
                if (outer_call) |n| if (std.mem.eql(u8, n.label, "eval")) {
                    self.native_call = n.outer;
                };
                const raised = self.raiseCompileFatal(d.message(), .{ .file = where, .line = line });
                if (!d.trace) if (self.pending_exception) |exc| if (exc == .object) try exc.object.set(self.allocator, "__no_trace", .{ .bool = true });
                return raised;
            }
            self.setErrorMsg("eval(): compile error", .{});
            return error.RuntimeError;
        };
        ast.deinit();

        const heap_result = self.allocator.create(CompileResult) catch {
            result.deinit();
            self.allocator.free(wrapped);
            self.allocator.free(display_path);
            return error.OutOfMemory;
        };
        heap_result.* = result;
        // source and display_path slices are referenced by compiled bytecode
        try heap_result.string_allocs.append(self.allocator, wrapped);
        try heap_result.string_allocs.append(self.allocator, display_path);
        try self.compile_results.append(self.allocator, heap_result);

        try self.registerResultFunctions(heap_result);
        for (heap_result.type_hints.items) |th| {
            try g_type_info.put(self.allocator, th.name, .{ .param_types = th.param_types, .return_type = th.return_type });
        }
        try self.raiseCompileWarnings(heap_result);

        try self.ensureCallRoom();
        const return_frame = self.frame_count;
        const caller_idx = self.frame_count - 1;
        const caller = self.currentFrame();
        const caller_slot_names = if (caller.func) |func| func.slot_names else caller.slot_names;
        var eval_locals: []Value = &.{};
        if (heap_result.local_count > 0) {
            eval_locals = try self.allocator.alloc(Value, heap_result.local_count);
            @memset(eval_locals, .undef);
        }
        var inherited_vars: @TypeOf(self.frames[0].vars) = .{};
        var inherited_refs: @TypeOf(self.frames[0].ref_slots) = .{};
        for (heap_result.slot_names, 0..) |name, eval_slot| {
            if (name.len == 0 or eval_slot >= eval_locals.len) continue;
            if (caller.ref_slots.get(name)) |cell| {
                eval_locals[eval_slot] = cell.*;
                continue;
            }
            var found = false;
            for (caller_slot_names, 0..) |caller_name, caller_slot| {
                if (std.mem.eql(u8, caller_name, name) and caller_slot < caller.locals.len) {
                    eval_locals[eval_slot] = caller.locals[caller_slot];
                    found = true;
                    break;
                }
            }
            if (!found) {
                if (caller.vars.get(name)) |value| eval_locals[eval_slot] = value;
            }
        }
        if (caller.vars.count() > 0) {
            var vars_iter = caller.vars.iterator();
            while (vars_iter.next()) |entry| {
                try inherited_vars.put(self.allocator, entry.key_ptr.*, entry.value_ptr.*);
            }
        }
        if (caller.ref_slots.count() > 0) {
            var refs_iter = caller.ref_slots.iterator();
            while (refs_iter.next()) |entry| {
                try self.bindRefSlot(&inherited_refs, entry.key_ptr.*, entry.value_ptr.*);
            }
        }
        // a caller variable that holds nothing isn't passed on: it isn't defined
        for (caller_slot_names, 0..) |name, caller_slot| {
            if (name.len == 0 or caller_slot >= caller.locals.len or caller.locals[caller_slot] == .undef) continue;
            try inherited_vars.put(self.allocator, name, caller.locals[caller_slot]);
        }
        const saved_slot_names = self.global_slot_names;
        self.global_slot_names = heap_result.slot_names;
        const saved_strict = self.script_strict_types;
        self.script_strict_types = heap_result.strict_types;
        try self.ensureCallRoom();
        self.frames[self.frame_count] = .{
            .chunk = &heap_result.chunk,
            .ip = 0,
            .vars = inherited_vars,
            .locals = eval_locals,
            .ref_slots = inherited_refs,
            .script_path = heap_result.file_path,
            .slot_names = heap_result.slot_names,
            .include_parent = caller_idx,
        };
        self.frames[self.frame_count].entry_sp = self.sp;
        self.frame_count += 1;
        self.retainFrameObjects(self.frame_count - 1);
        if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;

        const sp_before_eval = self.sp;
        self.runUntilFrame(return_frame) catch {
            try self.mergeIncludeScope(return_frame, caller_idx, heap_result.slot_names);
            while (self.frame_count > return_frame) {
                self.frame_count -= 1;
                self.deinitFrameSlot(self.frame_count);
            }
            self.global_slot_names = saved_slot_names;
            self.script_strict_types = saved_strict;
            self.clearArgStackFrom(sp_before_eval);
            self.sp = sp_before_eval;
            return error.RuntimeError;
        };
        try self.mergeIncludeScope(return_frame, caller_idx, heap_result.slot_names);
        while (self.frame_count > return_frame) {
            self.frame_count -= 1;
            self.deinitFrameSlot(self.frame_count);
        }
        self.global_slot_names = saved_slot_names;
        self.script_strict_types = saved_strict;
        // return_val from the eval frame pushed the returned value to the
        // caller's stack; pop it so eval() callers see the actual value
        // instead of null. when the eval'd code didn't return anything the
        // stack is unchanged
        if (self.sp > sp_before_eval) {
            const r = self.stack[self.sp - 1];
            self.clearArgStackFrom(sp_before_eval);
            self.sp = sp_before_eval;
            return r;
        }
        return .null;
    }

    // runs the frames above base_frame to completion. an exception one of
    // those frames catches resumes at its handler; any other leaves with the
    // error, for the loop that owns the handler
    fn runUntilFrame(self: *VM, base_frame: usize) RuntimeError!void {
        if (stack_limit.overflowed()) {
            try self.raiseStackLimit();
            if (!self.dispatchPendingException(base_frame)) return error.RuntimeError;
        }
        while (self.frame_count > base_frame) {
            self.runLoop(base_frame) catch |err| {
                if (self.pending_exception != null and self.dispatchPendingException(base_frame)) continue;
                return self.runFailure(err);
            };
            return;
        }
    }

    // a nested call that failed leaves its frames and operands to be
    // unwound by whichever loop's handler takes the exception. a caller that
    // carries on instead (a destructor's exception discarded, a callback's
    // swallowed) would resume in the dead frame, so the call drops them as
    // it fails. a suspending fiber keeps its frames to resume later, and
    // exit() unwinds by itself
    fn unwindFailedCall(self: *VM, base_frame: usize) void {
        if (self.fiber_suspend_pending or self.exit_requested) return;
        if (self.frame_count <= base_frame) return;
        const entry_sp = self.frames[base_frame].entry_sp;
        if (self.pending_exception) |exc| self.chainHeldExceptions(exc, base_frame, entry_sp);
        while (self.frame_count > base_frame) {
            self.frame_count -= 1;
            self.deinitFrameSlot(self.frame_count);
        }
        if (entry_sp < self.sp) {
            self.discardArgTransport(entry_sp);
            self.sp = entry_sp;
        }
    }

    // php's zend_call_stack_size_error, raised where php code would be entered
    // again with too little native stack left. as in php's execute_ex, the
    // frame being entered is already pushed and is where the Error is raised
    pub fn raiseStackLimit(self: *VM) RuntimeError!void {
        var buf: [192]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, stack_limit.message_format, .{stack_limit.allowedSize()}) catch unreachable;
        try self.setPendingException("Error", msg);
    }

    fn runFailure(self: *VM, err: RuntimeError) RuntimeError {
        // exit() / die() unwinds with error.RuntimeError + exit_requested
        // set - that's an orderly script exit, not an internal error.
        // surface the err but don't decorate with a fake "Fatal error"
        // diagnostic that callers print to users
        if (self.exit_requested) return err;
        // surface the Zig error in error_msg so callers (e.g. require's
        // catch block) don't replace it with a generic "Failed opening"
        // message. captures the current function name and IP so the user
        // gets a real diagnostic instead of a bare RuntimeError
        if (self.error_msg == null and self.pending_exception == null) {
            // ZPHP_DBG_PANIC_INTERNAL=1 prints the Zig error-return trace
            // so we can find which native raised error.RuntimeError
            // without setting an exception or error_msg. invaluable when
            // bisecting an 'internal RuntimeError' to its source
            if (platform.getenv("ZPHP_DBG_PANIC_INTERNAL") != null) {
                std.debug.print("\n[ZPHP_DBG_PANIC_INTERNAL] uncontexted {s}\n", .{@errorName(err)});
                if (@errorReturnTrace()) |trace| {
                    const st: std.debug.StackTrace = .{ .return_addresses = trace.instruction_addresses[0..@min(trace.index, trace.instruction_addresses.len)], .skipped = .none };
                    std.debug.dumpStackTrace(&st);
                }
            }
            const cur_frame = if (self.frame_count > 0) &self.frames[self.frame_count - 1] else null;
            const ip: usize = if (cur_frame) |f| f.ip else 0;
            const func_name: []const u8 = if (cur_frame) |f|
                if (f.func) |fn_def| fn_def.name else "<top>"
            else
                "<no frame>";
            self.setErrorMsg("Fatal error: internal {s} in {s} at ip {d}", .{ @errorName(err), func_name, ip });
        }
        return error.RuntimeError;
    }

    // A constructor is a nested execution boundary: its caller's handlers
    // must not resume PHP while the new opcode still owns cleanup state.
    fn runConstructor(self: *VM, base_frame: usize, fast: bool, obj: *PhpObject) RuntimeError!void {
        // zend_object_store_ctor_failed: an object whose constructor threw
        // never has its destructor called
        errdefer if (self.pending_exception != null) {
            obj.destructor_called = true;
        };
        const saved_handlers = self.handler_count;
        const saved_floor = self.handler_floor;
        self.handler_floor = saved_handlers;
        defer {
            self.handler_count = saved_handlers;
            self.handler_floor = saved_floor;
        }
        if (fast and !stack_limit.overflowed()) try self.fastLoop();
        // fastLoop may bail in a descendant, not just the constructor frame.
        if (self.frame_count > base_frame) try self.runUntilFrame(base_frame);
        _ = self.pop(); // only a normally returned constructor has a result
    }

    // the script's own loop: an exception any frame catches resumes there,
    // whichever opcode raised it
    pub fn run(self: *VM) RuntimeError!void {
        self.installHooks();
        while (true) {
            self.runLoop(0) catch |err| {
                if (!self.exit_requested and self.pending_exception != null and self.dispatchPendingException(0)) continue;
                return err;
            };
            return;
        }
    }

    fn runLoop(self: *VM, base_frame: usize) RuntimeError!void {
        // the dispatch body inlines readByte/readU16/push at thousands of sites
        @setEvalBranchQuota(100000);
        const prev_base_frame = self.run_base_frame;
        self.run_base_frame = base_frame;
        defer self.run_base_frame = prev_base_frame;
        while (true) {
            const op: OpCode = @enumFromInt(self.readByte());
            switch (op) {
                .constant => {
                    const idx = self.readU16();
                    self.push(self.currentChunk().constants.items[idx]);
                },
                .op_null => self.push(.null),
                .op_true => self.push(.{ .bool = true }),
                .op_false => self.push(.{ .bool = false }),
                .defer_class_const => {
                    const class_name = self.currentChunk().constants.items[self.readU16()].string.bytes();
                    const const_name = self.currentChunk().constants.items[self.readU16()].string.bytes();
                    if (self.classes.getPtr(class_name)) |cls| {
                        if (!cls.constants.contains(const_name)) try cls.constant_order.append(self.allocator, const_name);
                        if (try cls.constants.fetchPut(self.allocator, const_name, .undef)) |old| self.releaseValue(old.value);
                        self.markLazyConstants(cls);
                    }
                    // php evaluates a constant to compare it with a trait's
                    if (self.trait_constant_checks.items.len > 0) {
                        for (self.trait_constant_checks.items) |check| {
                            if (std.mem.eql(u8, check.class, class_name) and std.mem.eql(u8, check.name, const_name)) {
                                const value = self.evaluateClassConstant(class_name, const_name) catch {
                                    if (self.pending_exception != null and self.dispatchPendingException(base_frame)) continue;
                                    return error.RuntimeError;
                                };
                                try self.settleTraitConstantChecks(class_name, const_name, value);
                                break;
                            }
                        }
                    }
                },
                .enter_class_scope => {
                    const class = self.currentChunk().constants.items[self.readU16()].string.bytes();
                    try self.initializer_scopes.append(self.allocator, .{ .class = self.declaredClassName(class), .frame = self.frame_count - 1, .handlers = self.handler_count });
                },
                .enter_class_scope_arg => {
                    const frame = self.currentFrame();
                    const arg = frame.locals[0];
                    const class: ?[]const u8 = if (arg == .string and arg.string.len > 0) self.declaredClassName(arg.string.bytes()) else null;
                    try self.initializer_scopes.append(self.allocator, .{ .class = class, .frame = self.frame_count - 1, .handlers = self.handler_count });
                },
                .leave_class_scope => {
                    _ = self.initializer_scopes.pop();
                },
                .hold_exception => {
                    const held = self.stack[self.sp - 1];
                    if (held == .object) try self.held_exceptions.append(self.allocator, .{ .frame = self.frame_count - 1, .slot = self.sp - 1, .exception = held.object });
                },
                .pop, .pop_boundary => {
                    // run any destructors queued by the discarded value's
                    // expression
                    _ = self.pop();
                    if (self.hasPendingReleases()) self.drainPendingDestruct();
                    if (self.drainRaised()) {
                        if (self.dispatchPendingException(base_frame)) continue;
                        return error.RuntimeError;
                    }
                    // only a statement end leaves nothing of an expression in
                    // flight, so only there does the frame go back to the
                    // fast loop. a generator's frame shares its variables with
                    // the generator and stays here
                    // a collection the releases call for runs at the statement
                    // that made them, before the fast loop takes over
                    self.collectCyclesIfNeeded();
                    if (self.drainRaised()) {
                        if (self.dispatchPendingException(base_frame)) continue;
                        return error.RuntimeError;
                    }
                    if (op == .pop_boundary and self.frame_count > base_frame and !self.arg_capture_pending and self.currentFrame().locals.len > 0 and self.currentFrame().generator == null) {
                        if (try self.resumeFastLoop(base_frame)) return;
                    }
                },
                .dup => self.push(self.stack[self.sp - 1]),
                .dup2 => {
                    self.push(self.stack[self.sp - 2]);
                    self.push(self.stack[self.sp - 2]);
                },
                .bury => {
                    const n = self.readByte();
                    const top = self.stack[self.sp - 1];
                    const dest = self.sp - 1 - n;
                    std.mem.copyBackwards(Value, self.stack[dest + 1 .. self.sp], self.stack[dest .. self.sp - 1]);
                    self.stack[dest] = top;
                },
                .swap => {
                    const tmp = self.stack[self.sp - 1];
                    self.stack[self.sp - 1] = self.stack[self.sp - 2];
                    self.stack[self.sp - 2] = tmp;
                },

                .get_var, .get_var_quiet => {
                    const idx = self.readU16();
                    const name = self.currentChunk().constants.items[idx].string.bytes();
                    if (isSuperglobal(name)) {
                        const sv: Value = if (self.globals_cells.get(name)) |cell| cell.* else .undef;
                        // an unset superglobal (or $_SESSION before a session
                        // starts) is php's undefined global
                        if (sv == .undef) {
                            if (op == .get_var) {
                                const msg = try std.fmt.allocPrint(self.allocator, "Undefined global variable {s}", .{name});
                                defer self.allocator.free(msg);
                                self.emitWarning(msg) catch if (try self.resumeRaised()) continue;
                            }
                            self.push(.null);
                            continue;
                        }
                        self.push(sv);
                        continue;
                    }
                    // $GLOBALS is a true superglobal: always resolve to the
                    // single shared array on the VM, regardless of frame scope
                    if (std.mem.eql(u8, name, "$GLOBALS")) {
                        if (self.globals_array) |ga| {
                            var cells = self.globals_cells.iterator();
                            while (cells.next()) |entry| {
                                const global_name = entry.key_ptr.*;
                                if (global_name.len > 1 and global_name[0] == '$') {
                                    try ga.set(self.allocator, .{ .string = Value.String.borrowed(global_name[1..]) }, entry.value_ptr.*.*);
                                }
                            }
                            self.push(.{ .array = ga });
                            continue;
                        }
                    }
                    if (self.currentFrame().ref_slots.get(name)) |cell| {
                        self.push(cell.*);
                    } else if (self.frameVariable(self.currentFrame(), name)) |val| {
                        // a read compiled before the variable's first write still
                        // reads the slot that write fills
                        self.push(val);
                    } else if (self.php_constants.get(name)) |val| {
                        self.warnDeprecatedConstant(name) catch if (try self.resumeRaised()) continue;
                        self.push(val);
                    } else if (std.mem.lastIndexOfScalar(u8, name, '\\')) |sep| blk: {
                        // PHP fallback: bare constants in a namespace try
                        // <ns>\<name> first, then fall back to the global <name>
                        const bare = name[sep + 1 ..];
                        if (self.php_constants.get(bare)) |val| {
                            self.warnDeprecatedConstant(bare) catch if (try self.resumeRaised()) continue;
                            self.push(val);
                            break :blk;
                        }
                        // an undefined bare constant is a fatal Error in PHP 8,
                        // not a silent null
                        const msg = try std.fmt.allocPrint(self.allocator, "Undefined constant \"{s}\"", .{name});
                        defer self.allocator.free(msg);
                        if (bareDefaultRunning(self.currentFrame())) self.bare_default_failed = true;
                        if (try self.throwBuiltinException("Error", msg)) continue;
                        return error.RuntimeError;
                    } else if (name.len > 2 and name[0] == '$' and name[1] == '_') {
                        self.push(self.request_vars.get(name) orelse .null);
                    } else if (self.request_vars.get(name)) |rv| {
                        self.push(rv);
                    } else if (name.len > 0 and name[0] != '$') {
                        // bare identifier that resolved to neither a variable
                        // nor a constant - undefined constant, fatal in PHP 8
                        const msg = try std.fmt.allocPrint(self.allocator, "Undefined constant \"{s}\"", .{name});
                        defer self.allocator.free(msg);
                        if (bareDefaultRunning(self.currentFrame())) self.bare_default_failed = true;
                        if (try self.throwBuiltinException("Error", msg)) continue;
                        return error.RuntimeError;
                    } else {
                        if (op == .get_var) self.undefinedVariableRead(name) catch if (try self.resumeRaised()) continue;
                        self.push(.null);
                    }
                },
                .set_var => {
                    const idx = self.readU16();
                    const name = self.currentChunk().constants.items[idx].string.bytes();
                    try self.checkTypedNameWrite(self.currentFrame(), name);
                    const val = try self.copyValue(self.peek());
                    if (isSuperglobal(name)) {
                        const cell = try self.superglobalCell(name);
                        self.setCell(cell, val);
                        try self.propagateCellWrite(cell, val);
                        self.releaseValue(val);
                        continue;
                    }
                    if (self.currentFrame().ref_slots.get(name)) |cell| {
                        self.setCell(cell, val);
                        try self.propagateCellWrite(cell, val);
                    } else {
                        const svf = self.currentFrame();
                        // overwrite-release: drop the object the variable held
                        // before this store (Stage 1) - this destructs the old
                        // object on reassignment
                        if (svf.vars.get(name)) |old| self.releaseValue(old);
                        try self.putFrameVar(&svf.vars, name, val);
                    }
                    const sv_sn = if (self.currentFrame().func) |func| func.slot_names else self.global_slot_names;
                    for (sv_sn, 0..) |sn, si| {
                        if (std.mem.eql(u8, sn, name)) {
                            if (si < self.currentFrame().locals.len) self.currentFrame().locals[si] = val;
                            break;
                        }
                    }
                },

                .get_var_var, .get_var_var_quiet => {
                    const name_val = self.pop();
                    var text_buf: [32]u8 = undefined;
                    const raw_name = varVarText(name_val, &text_buf);
                    if (raw_name.len == 0) {
                        if (op == .get_var_var) self.undefinedVariableRead("$") catch if (try self.resumeRaised()) continue;
                        self.push(.null);
                    } else {
                        var buf: [256]u8 = undefined;
                        const dollar_name = varVarName(raw_name, &buf);
                        if (isSuperglobal(dollar_name) and self.frameInGlobalScope(self.currentFrame())) {
                            self.push(if (self.globals_cells.get(dollar_name)) |cell| cell.* else .null);
                            continue;
                        }
                        if (self.frameVariable(self.currentFrame(), dollar_name)) |val| {
                            self.push(val);
                        } else if (isSuperglobal(dollar_name) and self.frameInGlobalScope(self.currentFrame())) {
                            self.push(if (self.globals_cells.get(dollar_name)) |cell| cell.* else .null);
                        } else {
                            if (op == .get_var_var) self.undefinedVariableRead(dollar_name) catch if (try self.resumeRaised()) continue;
                            self.push(.null);
                        }
                    }
                },
                .ensure_array_var_var => {
                    // the variable a ${...}[k] write lands in: made an array when
                    // it holds nothing, separated from co-holders, written back
                    const name_val = self.pop();
                    var buf: [256]u8 = undefined;
                    const dollar_name = varVarName(if (name_val == .string) name_val.string.bytes() else "", &buf);
                    const frame = self.currentFrame();
                    const cur = self.frameVariable(frame, dollar_name) orelse .null;
                    if (cur == .int or cur == .float or (cur == .bool and cur.bool)) {
                        if (try self.throwBuiltinException("Error", "Cannot use a scalar value as an array")) continue;
                        return error.RuntimeError;
                    }
                    if (cur == .array) {
                        // a reference's separation rebinds every alias itself
                        const cell = frame.ref_slots.get(dollar_name);
                        const sep = if (cell) |c|
                            (try self.separateReferencedArray(frame, dollar_name, c, cur.array)) orelse cur.array
                        else
                            try self.cowSeparate(cur.array);
                        if (sep != cur.array and cell == null) try self.setVariableByName(frame, try self.internName(dollar_name), .{ .array = sep });
                        self.push(.{ .array = sep });
                        continue;
                    }
                    if (cur != .null and !(cur == .bool and !cur.bool)) {
                        self.push(cur);
                        continue;
                    }
                    if (cur == .bool) self.falseToArrayDeprecated() catch if (try self.resumeRaised()) continue;
                    const arr: Value = .{ .array = try self.allocArray() };
                    retainValue(arr);
                    try self.setVariableByName(frame, try self.internName(dollar_name), arr);
                    self.push(arr);
                },
                .set_var_var => {
                    const name_val = self.pop();
                    var text_buf: [32]u8 = undefined;
                    const raw_name = varVarText(name_val, &text_buf);
                    if (raw_name.len > 0) {
                        var check_buf: [256]u8 = undefined;
                        try self.checkTypedNameWrite(self.currentFrame(), varVarName(raw_name, &check_buf));
                    }
                    const val = try self.copyValue(self.peek());
                    if (raw_name.len > 0) {
                        var buf: [256]u8 = undefined;
                        const dollar_name = varVarName(raw_name, &buf);
                        if (isSuperglobal(dollar_name) and self.frameInGlobalScope(self.currentFrame())) {
                            try self.putRequestVar(try self.internName(dollar_name), val);
                            self.releaseValue(val);
                            continue;
                        }
                        if (self.currentFrame().ref_slots.get(dollar_name)) |cell| {
                            self.setCell(cell, val);
                            try self.propagateCellWrite(cell, val);
                        } else {
                            const sn = if (self.currentFrame().func) |func| func.slot_names else self.global_slot_names;
                            var found_slot = false;
                            for (sn, 0..) |s, si| {
                                if (std.mem.eql(u8, s, dollar_name)) {
                                    if (si < self.currentFrame().locals.len) {
                                        // Stage 2 overwrite-release on the slot
                                        const old_lv = self.currentFrame().locals[si];
                                        self.releaseValue(old_lv);
                                        self.currentFrame().locals[si] = val;
                                    }
                                    found_slot = true;
                                    break;
                                }
                            }
                            if (!found_slot) {
                                const stable_key = try self.internName(dollar_name);
                                // Stage 2 overwrite-release on the vars map
                                if (self.currentFrame().vars.get(stable_key)) |old| {
                                    self.releaseValue(old);
                                }
                                try self.putFrameVar(&self.currentFrame().vars, stable_key, val);
                            }
                        }
                    }
                },

                .add => {
                    const b = self.pop();
                    const a = self.pop();
                    if (a == .array and b == .array) {
                        self.push(.{ .array = try self.arrayUnion(a.array, b.array) });
                    } else {
                        const handlers_before = self.handler_count;
                        const overloaded = self.objectBinop(.add, a, b) catch {
                            if (self.resumeAfterThrow(base_frame, handlers_before)) continue;
                            return error.RuntimeError;
                        };
                        if (overloaded) |r| {
                            self.push(r);
                            continue;
                        }
                        if (try self.checkArithOperands(a, b, "+")) continue;
                        self.push(Value.add(a, b));
                    }
                },
                .subtract => {
                    const b = self.pop();
                    const a = self.pop();
                    const handlers_before = self.handler_count;
                    const overloaded = self.objectBinop(.sub, a, b) catch {
                        if (self.resumeAfterThrow(base_frame, handlers_before)) continue;
                        return error.RuntimeError;
                    };
                    if (overloaded) |r| {
                        self.push(r);
                        continue;
                    }
                    if (try self.checkArithOperands(a, b, "-")) continue;
                    self.push(Value.subtract(a, b));
                },
                .multiply => {
                    const b = self.pop();
                    const a = self.pop();
                    const handlers_before = self.handler_count;
                    const overloaded = self.objectBinop(.mul, a, b) catch {
                        if (self.resumeAfterThrow(base_frame, handlers_before)) continue;
                        return error.RuntimeError;
                    };
                    if (overloaded) |r| {
                        self.push(r);
                        continue;
                    }
                    if (try self.checkArithOperands(a, b, "*")) continue;
                    self.push(Value.multiply(a, b));
                },
                .inc_value, .dec_value => {
                    const v = self.pop();
                    const stepped = try self.stepValue(v, op == .inc_value) orelse continue;
                    self.push(stepped);
                    if (stepped == .string and stepped.string.owner != null) self.releaseValue(stepped);
                },
                .divide => {
                    const b = self.pop();
                    const a = self.pop();
                    const handlers_before = self.handler_count;
                    const overloaded = self.objectBinop(.div, a, b) catch {
                        if (self.resumeAfterThrow(base_frame, handlers_before)) continue;
                        return error.RuntimeError;
                    };
                    if (overloaded) |r| {
                        self.push(r);
                        continue;
                    }
                    if (try self.checkArithOperands(a, b, "/")) continue;
                    const bv = Value.toFloat(b);
                    if (bv == 0.0) {
                        if (try self.throwBuiltinException("DivisionByZeroError", "Division by zero")) continue;
                        return error.RuntimeError;
                    }
                    self.push(Value.divide(a, b));
                },
                .modulo => {
                    const b = self.pop();
                    const a = self.pop();
                    const handlers_before = self.handler_count;
                    const overloaded = self.objectBinop(.mod, a, b) catch {
                        if (self.resumeAfterThrow(base_frame, handlers_before)) continue;
                        return error.RuntimeError;
                    };
                    if (overloaded) |r| {
                        self.push(r);
                        continue;
                    }
                    if (try self.checkArithOperands(a, b, "%")) continue;
                    self.warnIntOperands(a, b) catch if (try self.resumeRaised()) continue;
                    const bi = Value.toInt(b);
                    if (bi == 0) {
                        if (try self.throwBuiltinException("DivisionByZeroError", "Modulo by zero")) continue;
                        return error.RuntimeError;
                    }
                    self.push(Value.modulo(a, b));
                },
                .power => {
                    const b = self.pop();
                    const a = self.pop();
                    const handlers_before = self.handler_count;
                    const overloaded = self.objectBinop(.pow, a, b) catch {
                        if (self.resumeAfterThrow(base_frame, handlers_before)) continue;
                        return error.RuntimeError;
                    };
                    if (overloaded) |r| {
                        self.push(r);
                        continue;
                    }
                    if (try self.checkArithOperands(a, b, "**")) continue;
                    if (Value.powerOfZeroBase(a, b)) self.raiseError(E_DEPRECATED, "Power of base 0 and negative exponent is deprecated") catch {
                        if (try self.resumeRaised()) continue;
                        return error.RuntimeError;
                    };
                    self.push(Value.power(a, b));
                },
                .negate => {
                    const v = self.pop();
                    const handlers_before = self.handler_count;
                    const overloaded = self.objectBinop(.negate, v, .null) catch {
                        if (self.resumeAfterThrow(base_frame, handlers_before)) continue;
                        return error.RuntimeError;
                    };
                    if (overloaded) |r| {
                        self.push(r);
                        continue;
                    }
                    if (!isArithOperand(v)) {
                        // php compiles -$a as $a * -1
                        const tn = if (v == .object) v.object.class_name else Value.typeName(v);
                        const msg = try std.fmt.allocPrint(self.allocator, "Unsupported operand types: {s} * int", .{tn});
                        defer self.allocator.free(msg);
                        if (try self.throwBuiltinException("TypeError", msg)) continue;
                        return error.RuntimeError;
                    }
                    if (v == .string and isPartialNumericString(v.string.bytes())) self.emitNonNumericWarning() catch if (try self.resumeRaised()) continue;
                    self.push(v.negate());
                },
                .concat => {
                    const b = self.pop();
