                .set_static => {},

                .require => {
                    const kind: IncludeKind = @enumFromInt(self.readByte());
                    const path_val = self.pop();
                    VM.retainValue(path_val);
                    defer self.releaseValue(path_val);
                    const target = self.includeTarget(kind, path_val) catch {
                        _ = try self.resumeRaised();
                        continue;
                    };
                    {
                        const is_require = kind.required();
                        const path = target orelse {
                            self.push(.{ .bool = false });
                            continue;
                        };

                        if (kind.once() and self.ic.?.included.contains(path)) {
                            self.push(.{ .bool = true });
                        } else {
                            const from_cache = self.serve_mode and self.serve_compile_cache.contains(path);
                            const result: ?*CompileResult = if (from_cache)
                                self.serve_compile_cache.get(path).?
                            else if (self.file_loader) |loader| blk: {
                                const fs_mod = @import("../stdlib/filesystem.zig");
                                fs_mod.current_include = @tagName(kind);
                                defer fs_mod.current_include = null;
                                break :blk loader(path, self.allocator, self);
                            } else null;

                            if (result) |r| {
                                if (self.serve_mode and !from_cache) {
                                    const duped = try self.allocator.dupe(u8, path);
                                    try self.serve_cache_keys.append(self.allocator, duped);
                                    try self.serve_compile_cache.put(self.allocator, duped, r);
                                }
                                try self.ic.?.included.put(self.allocator, path, {});
                                if (!from_cache) {
                                    try self.compile_results.append(self.allocator, r);
                                }

                                try self.registerResultFunctions(r);
                                for (r.type_hints.items) |th| {
                                    try g_type_info.put(self.allocator, th.name, .{ .param_types = th.param_types, .return_type = th.return_type });
                                }
                                self.raiseCompileWarnings(r) catch if (try self.resumeRaised()) continue;

                                const return_frame = self.frame_count;
                                try self.ensureCallRoom();
                                const sp_before = self.sp;
                                var req_locals: []Value = &.{};
                                if (r.local_count > 0) {
                                    req_locals = try self.allocator.alloc(Value, r.local_count);
                                    @memset(req_locals, .undef);
                                }
                                var inherited_vars: @TypeOf(self.frames[0].vars) = .{};
                                var inherited_refs: @TypeOf(self.frames[0].ref_slots) = .{};
                                const caller_idx = self.frame_count - 1;
                                const caller = self.currentFrame();
                                const caller_sn = if (caller.func) |func| func.slot_names else caller.slot_names;
                                for (r.slot_names, 0..) |name, ri| {
                                    if (name.len == 0 or ri >= req_locals.len) continue;
                                    if (caller.ref_slots.get(name)) |cell| {
                                        req_locals[ri] = cell.*;
                                        continue;
                                    }
                                    var found = false;
                                    for (caller_sn, 0..) |caller_name, ci| {
                                        if (std.mem.eql(u8, caller_name, name) and ci < caller.locals.len) {
                                            req_locals[ri] = caller.locals[ci];
                                            found = true;
                                            break;
                                        }
                                    }
                                    if (!found) {
                                        if (caller.vars.get(name)) |value| req_locals[ri] = value;
                                    }
                                }
                                if (caller.vars.count() > 0) {
                                    var vit = caller.vars.iterator();
                                    while (vit.next()) |entry| {
                                        try inherited_vars.put(self.allocator, entry.key_ptr.*, entry.value_ptr.*);
                                    }
                                }
                                if (caller.ref_slots.count() > 0) {
                                    var rit = caller.ref_slots.iterator();
                                    while (rit.next()) |entry| {
                                        try self.bindRefSlot(&inherited_refs, entry.key_ptr.*, entry.value_ptr.*);
                                    }
                                }
                                for (caller_sn, 0..) |name, ci| {
                                    if (name.len == 0 or ci >= caller.locals.len or inherited_vars.contains(name) or caller.locals[ci] == .undef) continue;
                                    try inherited_vars.put(self.allocator, name, caller.locals[ci]);
                                }
                                const saved_slot_names = self.global_slot_names;
                                self.global_slot_names = r.slot_names;
                                const saved_strict = self.script_strict_types;
                                self.script_strict_types = r.strict_types;
                                try self.ensureCallRoom();
                                self.frames[self.frame_count] = .{
                                    .chunk = &r.chunk,
                                    .ip = 0,
                                    .vars = inherited_vars,
                                    .locals = req_locals,
                                    .ref_slots = inherited_refs,
                                    .script_path = r.file_path,
                                    .slot_names = r.slot_names,
                                    .include_parent = caller_idx,
                                };
                                self.frames[self.frame_count].entry_sp = self.sp;
                                self.frame_count += 1;
                                self.retainFrameObjects(self.frame_count - 1);
                                if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;
                                const saved_merge_depth = self.require_merge_depth;
                                self.require_merge_depth = self.frame_count;
                                self.runUntilFrame(return_frame) catch {
                                    self.require_merge_depth = saved_merge_depth;
                                    try self.mergeIncludeScope(return_frame, caller_idx, r.slot_names);
                                    while (self.frame_count > return_frame) {
                                        self.frame_count -= 1;
                                        self.deinitFrameSlot(self.frame_count);
                                    }
                                    self.global_slot_names = saved_slot_names;
                                    self.script_strict_types = saved_strict;

                                    if (self.pending_exception) |exc| {
                                        if (self.handler_count > self.handler_floor and !self.uncatchable_fatal) {
                                            const handler = self.exception_handlers[self.handler_count - 1];
                                            if (handler.frame_count > base_frame or base_frame == 0) {
                                                self.pending_exception = null;
                                                self.enterHandler(handler, exc, .owned);
                                                continue;
                                            }
                                        }
                                    }

                                    // an error inside the file ends include as it ends require
                                    if (is_require and self.error_msg == null and self.pending_exception == null) {
                                        self.setErrorMsg("Fatal error: require(): Failed opening required '{s}'", .{path});
                                    }
                                    return error.RuntimeError;
                                };
                                try self.mergeIncludeScope(return_frame, caller_idx, r.slot_names);
                                while (self.frame_count > return_frame) {
                                    self.frame_count -= 1;
                                    self.deinitFrameSlot(self.frame_count);
                                }
                                // popFrame at require_merge_depth left this slot
                                // intact for the merge above; deinit it now
                                self.deinitFrameSlot(return_frame);
                                self.require_merge_depth = saved_merge_depth;
                                self.global_slot_names = saved_slot_names;
                                self.script_strict_types = saved_strict;
                                if (self.sp <= sp_before) self.push(.{ .int = 1 });
                            } else if (self.ic.?.include_parse_error) |parse_error| {
                                defer self.dropIncludeError(&self.ic.?.include_parse_error);
                                if (try self.throwBuiltinExceptionAt("ParseError", parse_error.message, parse_error.at)) continue;
                                return error.RuntimeError;
                            } else if (self.ic.?.include_compile_error) |compile_error| {
                                defer self.dropIncludeError(&self.ic.?.include_compile_error);
                                const raised = self.raiseCompileFatal(compile_error.message, compile_error.at);
                                if (!compile_error.trace) if (self.pending_exception) |exc| if (exc == .object) try exc.object.set(self.allocator, "__no_trace", .{ .bool = true });
                                return raised;
                            } else if (self.pending_exception != null) {
                                // the stream that was to supply the source threw
                                if (try self.resumeRaised()) continue;
                                return error.RuntimeError;
                            } else if (@import("../stdlib/filesystem.zig").includeThroughStream(self, path)) {
                                // the stream's own warnings said why
                                self.includeFailedOpening(kind, path) catch if (try self.resumeRaised()) continue;
                                self.push(.{ .bool = false });
                            } else {
                                self.includeNotOpened(kind, path, "Permission denied") catch if (try self.resumeRaised()) continue;
                                self.push(.{ .bool = false });
                            }
                        }
                    }
                },

                .array_spread => {
                    var src = self.pop();
                    const target = self.peek();
                    if (target != .array) continue;

                    if (src == .object and self.hasMethod(src.object.class_name, "getIterator")) {
                        src = self.callMethod(src.object, "getIterator", &.{}) catch {
                            if (self.pending_exception != null and self.dispatchPendingException(base_frame)) continue;
                            return error.RuntimeError;
                        };
                    }

                    // an integer-keyed element appended past maxInt is php's
                    // "next element is already occupied" Error
                    var occupied = false;
                    if (src == .array) {
                        for (src.array.entries.items) |entry| {
                            if (entry.key == .int and target.array.nextElementOccupied()) {
                                occupied = true;
                                break;
                            }
                            if (entry.key == .string) {
                                try self.arraySetOwned(target.array, entry.key, if (entry.ref) |ref| ref.* else entry.value);
                            } else if (entry.ref) |ref| {
                                const key: PhpArray.Key = .{ .int = target.array.next_int_key };
                                try target.array.append(self.allocator, ref.*);
                                if (target.array.getPtr(key)) |ep| self.setEntryRef(ep, ref);
                                try self.array_ref_bindings.append(self.allocator, .{ .cell = ref, .array = target.array, .key = key });
                                try self.regRefArray(try self.persistentRefOwner(), ref, target.array, key);
                                self.array_ref_active = true;
                            } else {
                                try target.array.append(self.allocator, entry.value);
                            }
                        }
                    } else if (src == .generator) {
                        const gen = src.generator;
                        genRetain(gen);
                        defer self.genRelease(gen);
                        if (gen.state == .created) {
                            self.resumeGenerator(gen, .null) catch {
                                if (self.dispatchPendingException(base_frame)) continue;
                                return error.RuntimeError;
                            };
                        }
                        while (gen.state != .completed) {
                            if (gen.current_key == .string) {
                                try self.arraySetOwned(target.array, .{ .string = gen.current_key.string }, gen.current_value);
                            } else if (!try target.array.appendNew(self.allocator, gen.current_value)) {
                                occupied = true;
                                break;
                            }
                            self.resumeGenerator(gen, .null) catch {
                                if (self.dispatchPendingException(base_frame)) continue;
                                return error.RuntimeError;
                            };
                        }
                    } else if (src == .object and self.hasMethod(src.object.class_name, "current")) {
                        // an exception from any Iterator method ends the spread
                        const failed = iterate: {
                            if (self.hasMethod(src.object.class_name, "rewind")) {
                                _ = self.callMethod(src.object, "rewind", &.{}) catch break :iterate true;
                            }
                            while (true) {
                                const valid = self.callMethod(src.object, "valid", &.{}) catch break :iterate true;
                                if (!valid.isTruthy()) break;
                                const key = self.callMethod(src.object, "key", &.{}) catch break :iterate true;
                                const val = self.callMethod(src.object, "current", &.{}) catch break :iterate true;
                                if (key == .string) {
                                    try self.arraySetOwned(target.array, .{ .string = key.string }, val);
                                } else if (!try target.array.appendNew(self.allocator, val)) {
                                    occupied = true;
                                    break;
                                }
                                _ = self.callMethod(src.object, "next", &.{}) catch break :iterate true;
                            }
                            break :iterate false;
                        };
                        if (failed) {
                            if (self.pending_exception != null and self.dispatchPendingException(base_frame)) continue;
                            return error.RuntimeError;
                        }
                    }
                    if (occupied) {
                        if (try self.throwNextElementOccupied()) continue;
                        return error.RuntimeError;
                    }
                },
                .splat_call => {},

                .instance_check => {
                    const class_name_val = self.pop();
                    const obj_val = self.pop();
                    if (self.isUnwindMarker(obj_val)) {
                        self.push(.{ .bool = false });
                    } else if (obj_val == .object and class_name_val == .string) {
                        // self/static/parent stay symbolic where the compiler
                        // cannot know the class (inside a trait)
                        const target = self.resolveRelativeClassName(class_name_val.string.bytes());
                        self.push(.{ .bool = self.isInstanceOf(obj_val.object.class_name, target) });
                    } else if (obj_val == .object and class_name_val == .object) {
                        // `$a instanceof $b` with an object on the right tests its class
                        self.push(.{ .bool = self.isInstanceOf(obj_val.object.class_name, class_name_val.object.class_name) });
                    } else if (obj_val == .generator and class_name_val == .string) {
                        const t = class_name_val.string.bytes();
                        const matches = std.mem.eql(u8, t, "Generator") or
                            std.mem.eql(u8, t, "Iterator") or
                            std.mem.eql(u8, t, "Traversable");
                        self.push(.{ .bool = matches });
                    } else if (obj_val == .fiber and class_name_val == .string) {
                        self.push(.{ .bool = std.mem.eql(u8, class_name_val.string.bytes(), "Fiber") });
                    } else {
                        self.push(.{ .bool = false });
                    }
                },

                .class_decl => try self.handleClassDecl(),

                .interface_decl => {
                    const name_idx = self.readU16();
                    const iface_name = self.currentChunk().constants.items[name_idx].string.bytes();
                    try self.refuseRedeclaration(iface_name);
                    const iface_site = self.readDeclSite();
                    const method_count = self.readU16();

                    var idef = InterfaceDef{ .name = iface_name };
                    for (0..method_count) |_| {
                        const mname_idx = self.readU16();
                        const method_name = self.currentChunk().constants.items[mname_idx].string.bytes();
                        try idef.methods.append(self.allocator, method_name);
                    }

                    const parent_count = self.readByte();
                    var parent_names: [16][]const u8 = undefined;
                    for (0..parent_count) |pi| {
                        const pidx = self.readU16();
                        parent_names[pi] = self.declaredClassName(self.currentChunk().constants.items[pidx].string.bytes());
                        try idef.parents.append(self.allocator, parent_names[pi]);
                    }
                    if (parent_count > 0) {
                        idef.parent = parent_names[0];
