                    // php makes an interface that declares __toString extend Stringable
                    const adds_stringable = declaresToString(idef.methods.items) and !self.listedInterfacesInclude(idef.parents.items, "Stringable");
                    if (adds_stringable) {
                        try idef.parents.append(self.allocator, "Stringable");
                        if (idef.parent == null) idef.parent = "Stringable";
                    }

                    const const_count = self.readByte();
                    var def = ClassDef{ .name = iface_name, .is_internal = false, .file_path = iface_site.file, .start_line = iface_site.start_line, .end_line = iface_site.end_line, .doc_comment = iface_site.doc_comment };
                    if (const_count > 0) {
                        var ci: usize = const_count;
                        while (ci > 0) : (ci -= 1) {
                            const cname_idx = self.readU16();
                            const cname = self.currentChunk().constants.items[cname_idx].string.bytes();
                            const doc_idx = self.readU16();
                            if (doc_idx != 0xffff) try def.constant_docs.put(self.allocator, cname, self.currentChunk().constants.items[doc_idx].string.bytes());
                            const const_flags = self.readByte();
                            const type_idx = self.readU16();
                            const cval = self.stack[self.sp - ci];
                            // copyValue: the constant value is owned by the
                            // ClassDef and must be refcounted
                            if (!def.constants.contains(cname)) try def.constant_order.append(self.allocator, cname);
                            try def.constants.put(self.allocator, cname, try self.copyDefault(cval));
                            if (const_flags & 0x10 != 0) try def.const_final.put(self.allocator, cname, {});
                            if (type_idx != 0xffff) try def.constant_types.put(self.allocator, cname, self.currentChunk().constants.items[type_idx].string.bytes());
                        }
                        self.clearArgStackFrom(self.sp - const_count);
                        self.sp -= const_count;
                    } else {
                        // read const names even when 0 (shouldn't have any)
                    }
                    for (0..parent_count) |pi| {
                        try def.interfaces.append(self.allocator, parent_names[pi]);
                    }
                    if (adds_stringable) try def.interfaces.append(self.allocator, "Stringable");

                    const iface_attrs = try self.readAttributeDefs();
                    for (iface_attrs) |a| try def.attributes.append(self.allocator, a);
                    if (iface_attrs.len > 0) self.allocator.free(iface_attrs);

                    const iface_method_attr_count = self.readByte();
                    for (0..iface_method_attr_count) |_| {
                        const ma_name_idx = self.readU16();
                        const ma_name = self.currentChunk().constants.items[ma_name_idx].string.bytes();
                        const ma_attrs = try self.readAttributeDefs();
                        try def.method_attributes.put(self.allocator, ma_name, ma_attrs);
                    }

                    const property_count = self.readU16();
                    for (0..property_count) |_| {
                        const prop_name = self.currentChunk().constants.items[self.readU16()].string.bytes();
                        const type_idx = self.readU16();
                        const doc_idx = self.readU16();
                        try def.properties.append(self.allocator, .{
                            .name = prop_name,
                            .default = .null,
                            .is_virtual = true,
                            .type_str = if (type_idx == 0xffff) "" else self.currentChunk().constants.items[type_idx].string.bytes(),
                            .doc_comment = if (doc_idx == 0xffff) "" else self.currentChunk().constants.items[doc_idx].string.bytes(),
                        });
                        const mask = self.readByte();
                        for (0..2) |i| {
                            if (mask & (@as(u8, 1) << @intCast(i)) == 0) continue;
                            const hook = self.currentChunk().constants.items[self.readU16()].string.bytes();
                            try idef.methods.append(self.allocator, hook);
                            try def.methods.put(self.allocator, hook, .{ .name = hook, .arity = @intCast(i), .is_abstract = true });
                        }
                        const attrs = try self.readAttributeDefs();
                        if (attrs.len > 0) try def.property_attributes.put(self.allocator, prop_name, attrs);
                    }
                    const iface_const_attr_count = self.readByte();
                    for (0..iface_const_attr_count) |_| {
                        const ca_name = self.currentChunk().constants.items[self.readU16()].string.bytes();
                        const ca_attrs = try self.readAttributeDefs();
                        try def.constant_attributes.put(self.allocator, ca_name, ca_attrs);
                        if (try self.deprecationOf(ca_attrs)) |suffix| {
                            try def.deprecated_constants.put(self.allocator, ca_name, suffix);
                            self.has_deprecated_constants = true;
                        }
                    }
                    // Interfaces inherit contracts from every parent, including
                    // diamonds. Keep local declarations authoritative.
                    // a parent has to exist when the interface is declared,
                    // which is also what stops an interface extending itself
                    const missing_parent: ?[]const u8 = for (idef.parents.items) |parent| {
                        if (!self.interfaces.contains(parent)) try self.tryAutoload(parent);
                        if (!self.interfaces.contains(parent)) break parent;
