                    } else if (std.mem.eql(u8, class_name, "self")) {
                        if (self.currentDefiningClass()) |dc| class_name = dc;
                    } else if (std.mem.eql(u8, class_name, "parent")) {
                        if (self.parentResolvingClass()) |dc| {
