                .defer_prop_defaults => {
                    const class_idx = self.readU16();
                    const class_name = self.currentChunk().constants.items[class_idx].string.bytes();
                    if (self.classes.getPtr(class_name)) |cls| {
                        if (!cls.defaults_pending) self.ic.?.pending_defaults += 1;
                        cls.defaults_pending = true;
                        if (cls.slot_layout) |layout| layout.defaults_ready = false;
                    }
                },

                .set_prop_default => {
                    // install an instance property's real default on the now-
                    // registered class. emitted after class_decl so a default
                    // expression like `self::CONST` resolves
                    const class_idx = self.readU16();
                    const prop_idx = self.readU16();
                    const class_name = self.currentChunk().constants.items[class_idx].string.bytes();
                    const prop_name = self.currentChunk().constants.items[prop_idx].string.bytes();
                    var val = try self.copyValue(self.peek());
                    if (self.classes.getPtr(class_name)) |cls| {
                        for (cls.properties.items) |*p| {
                            if (std.mem.eql(u8, p.name, prop_name)) {
                                val = self.widenIntDefault(val, p.type_str, class_name, prop_name) catch |err| {
                                    self.releaseValue(val);
                                    return err;
                                };
                                p.default = val;
                                p.has_default = true;
                                try self.settleTraitPropertyChecks(class_name, prop_name, val);
                                break;
                            }
                        }
                        // the slot layout snapshots prop defaults at class_decl
                        // time (still null placeholders here) - keep it in sync.
                        // with per-class private slots, there can be multiple
                        // entries with the same name from different declaring
                        // classes - match on (name AND declaring_class) so the
                        // correct one is patched
                        if (cls.slot_layout) |layout| {
                            for (layout.names, 0..) |n, i| {
                                if (std.mem.eql(u8, n, prop_name) and std.mem.eql(u8, layout.declaring_classes[i], class_name)) {
                                    layout.defaults[i] = val;
                                    break;
                                }
                            }
                        }
                    }
                },

                .set_static_prop_dyn => {
                    // stack: class name, property name, value (top)
                    const rhs_val = self.popTransfer();
                    const name_v = self.pop();
                    const class_v = self.pop();
                    const prop_name: []const u8 = if (name_v == .string) name_v.string.bytes() else "";
                    var class_name: []const u8 = switch (class_v) {
                        .string => |s| s.bytes(),
                        .object => |o| o.class_name,
                        else => "",
                    };
                    class_name = self.resolveStaticClassName(class_name);
                    if (class_name.len > 0 and prop_name.len > 0) {
                        self.resolveStaticDefaults(class_name) catch {
                            self.stackRelease(rhs_val);
                            if (self.pending_exception != null and self.dispatchPendingException(base_frame)) continue;
                            return error.RuntimeError;
                        };
                        const cls = self.staticPropTarget(class_name, prop_name, .write) catch {
                            self.stackRelease(rhs_val);
                            if (self.pending_exception != null and self.dispatchPendingException(base_frame)) continue;
                            return error.RuntimeError;
                        };
                        self.pushTransfer(rhs_val);
                        if (try self.checkStaticPropWrite(cls, class_name, prop_name)) continue;
                        const checked = self.popTransfer();
                        const stored = try self.copyValue(checked);
                        const old = try cls.static_props.fetchPut(self.allocator, prop_name, stored);
                        if (old) |kv| self.releaseValue(kv.value);
                        self.syncStaticPropRefs(class_name, prop_name, stored);
                        self.pushTransfer(checked);
                        continue;
                    }
                    self.pushTransfer(rhs_val);
                },
            }
        }
    }

    fn resolveRelativeClassName(self: *VM, name: []const u8) []const u8 {
        const relative = std.mem.eql(u8, name, "self") or std.mem.eql(u8, name, "static") or std.mem.eql(u8, name, "parent");
        return if (relative) self.resolveStaticClassName(name) else name;
    }

    // why php won't run a foreach by reference over this iterable, if it
    // won't: an iterator can't hand out references, except an ArrayIterator
    // whose current() is its own, and a generator only if it yields by
    // reference
    fn foreachByRefRefusal(self: *VM, iterable: Value) ?struct { class: []const u8, message: []const u8 } {
        switch (iterable) {
            .generator => |gen| if (!gen.func.returns_ref) return .{ .class = "Exception", .message = "You can only iterate a generator by-reference if it declared that it yields by-reference" },
            .object => |obj| if (self.isInstanceOf(obj.class_name, "Traversable")) {
                const own_current = self.isInstanceOf(obj.class_name, "ArrayIterator") and
                    self.native_fns.contains(self.resolveMethod(obj.class_name, "current") catch "");
                if (!own_current) return .{ .class = "Error", .message = "An iterator cannot be used with foreach by reference" };
            },
            else => {},
        }
        return null;
    }

    // a static call site and its inline cache entry
    const StaticCallSite = struct { entry: *InlineCache.MethodIC, key: usize, chunk_key: usize };

    // Class::method() with its arguments on the stack and the class resolved
    // (dynamicStaticTarget). a site's resolution is fixed per target class;
    // static targets never forward $this, so a cache hit enters directly
    fn callStaticMethod(self: *VM, class_name: []const u8, method_name: []const u8, arg_count: u32, effective_called: []const u8, site: ?StaticCallSite) RuntimeError!void {
        // self::, parent:: or static:: with no class scope to name
        if (class_name.len >= 4 and class_name.len <= 6) {
            inline for (.{ "self", "parent", "static" }) |word| {
                if (std.ascii.eqlIgnoreCase(class_name, word) and !self.classes.contains(class_name)) {
                    self.dropN(arg_count);
                    const msg = try self.classNotFoundMessage(class_name);
                    defer self.allocator.free(msg);
                    if (try self.throwBuiltinException("Error", msg)) return;
                    return error.RuntimeError;
                }
            }
        }
        if (site) |st| {
            const entry = st.entry;
            if (entry.key == st.key and entry.chunk_key == st.chunk_key and entry.class_ptr == @intFromPtr(class_name.ptr)) {
                if (entry.func) |func| {
                    if (!self.dbg_profile_enabled) {
                        try self.callStaticUserFunction(func, entry.full_name, arg_count, effective_called);
                        return;
                    }
                }
            }
        }

        const full_name = self.resolveMethod(class_name, method_name) catch {
            if (try self.refuseInterfaceStaticCall(class_name, method_name, arg_count)) return;
            // a class that isn't there (after the autoloaders) is "not found"
            if (!self.classes.contains(class_name) and !self.interfaces.contains(class_name)) {
                if (self.pending_exception != null) return error.RuntimeError;
                self.dropN(arg_count);
                const missing = try self.classNotFoundMessage(class_name);
                defer self.allocator.free(missing);
                if (try self.throwBuiltinException("Error", missing)) return;
                return error.RuntimeError;
            }
            if (try self.staticCallFallback(class_name, method_name, arg_count, effective_called)) return;
            const msg = std.fmt.allocPrint(self.allocator, "Call to undefined method {s}::{s}()", .{ self.declaredClassName(class_name), method_name }) catch return error.OutOfMemory;
            defer self.allocator.free(msg);
            if (try self.throwBuiltinException("Error", msg)) return;
            self.setErrorMsg("Fatal error: Uncaught Error: {s}", .{msg});
            return error.RuntimeError;
        };
        // a method the calling scope can't see: $this's __call or the
        // class's __callStatic, else php's Error
        const found = self.methodInfoOf(full_name, class_name, method_name);
        // an interface's method resolves to no class's declaration
        if (found == null and try self.refuseInterfaceStaticCall(class_name, method_name, arg_count)) return;
        // ZEND_INIT_STATIC_METHOD_CALL for a constructor: a private one runs
        // only on an object of its own class
        if (found) |f| if (f.info.visibility == .private and std.ascii.eqlIgnoreCase(method_name, "__construct")) if (self.currentThis()) |this| if (this == .object and !std.ascii.eqlIgnoreCase(this.object.class_name, f.defining)) {
            self.dropN(arg_count);
            const msg = try std.fmt.allocPrint(self.allocator, "Cannot call private {s}::__construct()", .{self.declaredClassName(class_name)});
            defer self.allocator.free(msg);
            if (try self.throwBuiltinException("Error", msg)) return;
            return error.RuntimeError;
        };
        if (found) |f| if (f.info.visibility != .public and !self.checkVisibility(f.defining, f.info.visibility) and !self.protectedRootVisible(f.defining, method_name, f.info.visibility)) {
            if (try self.staticCallFallback(class_name, method_name, arg_count, effective_called)) return;
            self.dropN(arg_count);
            const msg = try std.fmt.allocPrint(self.allocator, "Call to {s} method {s}(){s}", .{ @tagName(f.info.visibility), full_name, self.visScopeSuffix() });
            defer self.allocator.free(msg);
            if (try self.throwBuiltinException("Error", msg)) return;
            return error.RuntimeError;
        };
        if (found) |f| if (f.info.is_abstract) {
            self.dropN(arg_count);
            const msg = try std.fmt.allocPrint(self.allocator, "Cannot call abstract method {s}()", .{full_name});
            defer self.allocator.free(msg);
            if (try self.throwBuiltinException("Error", msg)) return;
            return error.RuntimeError;
        };

        // PHP forwards $this into a Class::method() call only when
        // the target is a non-static method (a scoped instance
        // call). a static target gets no $this - forwarding the
        // caller's $this corrupts late-static-binding inside it
        const this_val = self.currentFrame().vars.get("$this") orelse blk: {
            const f = self.currentFrame();
            if (f.func) |fn_info| {
                if (fn_info.locals_only) {
                    for (fn_info.slot_names, 0..) |sn, si| {
                        if (std.mem.eql(u8, sn, "$this") and si < f.locals.len and f.locals[si] == .object) {
                            break :blk f.locals[si];
                        }
                    }
                }
            }
            break :blk null;
        };
        const sc_target = self.functions.get(full_name);
        const sc_target_is_static = if (sc_target) |scf| scf.is_static else if (found) |f| f.info.is_static else false;
        // an internal method php declares non-static (zphp's own classes
        // aren't in php's signatures)
        const native_instance_method = sc_target == null and self.native_fns.contains(full_name) and
            if (@import("../stdlib/native_params_generated.zig").map.get(full_name)) |sig| !sig.is_static else false;
        if (site) |st| {
            if (sc_target) |func| {
                const public = if (found) |f| f.info.visibility == .public else true;
                if (func.is_static and public) st.entry.* = .{ .key = st.key, .chunk_key = st.chunk_key, .class_ptr = @intFromPtr(class_name.ptr), .func = func, .full_name = full_name };
            }
        }
        // an instance method called statically runs on $this when $this is
        // an instance of the class, and is an Error otherwise
        const this_fits = if (this_val) |tv| tv == .object and self.isInstanceOf(tv.object.class_name, class_name) else false;
        if ((native_instance_method or (sc_target != null and !sc_target_is_static)) and !this_fits) {
            self.dropN(arg_count);
            const msg = try std.fmt.allocPrint(self.allocator, "Non-static method {s}() cannot be called statically", .{full_name});
            defer self.allocator.free(msg);
            if (try self.throwBuiltinException("Error", msg)) return;
            return error.RuntimeError;
        }
        if (this_val) |tv| {
            if (tv == .object and !sc_target_is_static) {
                if (self.functions.get(full_name)) |func| {
                    if (func.is_generator) {
                        try self.callStaticFunction(full_name, arg_count, effective_called);
                    } else {
                        const ac: usize = arg_count;
                        var new_vars = self.acquireFrameVars();
                        try new_vars.put(self.allocator, "$this", tv);
                        if (func.is_variadic) {
                            const fixed: usize = func.arity - 1;
                            for (0..@min(ac, fixed)) |i| {
                                const is_ref = i < func.ref_params.len and func.ref_params[i];
                                const sv = self.stack[self.sp - ac + i];
                                try new_vars.put(self.allocator, func.params[i], if (is_ref) sv else try self.bindFrameArg(sv));
                            }
                            const rest_arr = try self.allocArray();
                            if (ac > fixed) {
                                for (fixed..ac) |i| {
                                    try rest_arr.append(self.allocator, try self.bindFrameArg(self.stack[self.sp - ac + i]));
                                }
                            }
                            try new_vars.put(self.allocator, func.params[fixed], .{ .array = rest_arr });
                        } else {
                            for (0..@min(ac, func.arity)) |i| {
                                const is_ref = i < func.ref_params.len and func.ref_params[i];
                                const sv = self.stack[self.sp - ac + i];
                                try new_vars.put(self.allocator, func.params[i], if (is_ref) sv else try self.bindFrameArg(sv));
                            }
                        }
                        if (!self.hasCallRoom(1) and !(try self.growCallRoom(1))) {
                            self.dropN(ac);
                            new_vars.deinit(self.allocator);
                            const msg = std.fmt.allocPrint(self.allocator, "Fatal error: maximum call stack depth exceeded in {s}::{s}()", .{ class_name, method_name }) catch return error.OutOfMemory;
                            defer self.allocator.free(msg);
                            if (try self.throwBuiltinException("Error", msg)) return;
                            self.setErrorMsg("{s}", .{msg});
                            return error.RuntimeError;
                        }
                        self.saveFrameArgs(arg_count);
                        self.dropN(ac);
                        try self.fillDefaults(&new_vars, func, ac);
                        try self.ensureCallRoom();
                        self.frames[self.frame_count] = .{ .chunk = &func.chunk, .ip = 0, .vars = new_vars, .locals = try self.allocLocals(func, &new_vars), .func = func, .called_class = effective_called };
                        self.setFrameArgCount(arg_count);
                        self.frames[self.frame_count].entry_sp = self.sp;
                        self.frame_count += 1;
                        self.retainFrameObjects(self.frame_count - 1);
                        if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;
                    }
                } else if (self.native_fns.get(full_name)) |native| {
                    const ac: usize = arg_count;
                    var args_buf: [16]Value = undefined;
                    const args_buf_s = try self.copyStackArgs(&args_buf, self.stack[self.sp - ac ..][0..ac]);
                    defer self.freeStackArgs(args_buf_s, &args_buf);
                    self.saveFrameArgs(arg_count);
                    self.dropN(ac);
                    var tmp_vars: std.StringHashMapUnmanaged(Value) = .{};
                    try tmp_vars.put(self.allocator, "$this", tv);
                    try self.ensureCallRoom();
                    self.frames[self.frame_count] = .{ .chunk = self.currentChunk(), .ip = self.currentFrame().ip, .vars = tmp_vars, .native = true, .called_class = effective_called };
                    self.setFrameArgCount(arg_count);
                    const sc_saved_fc = self.frame_count;
                    self.frames[self.frame_count].entry_sp = self.sp;
                    self.frame_count += 1;
                    self.retainFrameObjects(self.frame_count - 1);
                    if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;
                    var ctx = self.makeContext(full_name);
                    const pre_handlers = self.handler_count;
                    const result = self.invokeNative(native, &ctx, .{ .args = args_buf_s, .name = full_name, .instance = true }) catch {
                        if (self.frame_count > sc_saved_fc) {
                            self.frame_count -= 1;
                            self.deinitFrameSlot(self.frame_count);
                        }
                        if (self.pending_exception) |exc| {
                            self.pending_exception = null;
                            if (self.handler_count > self.handler_floor and !self.uncatchable_fatal) {
                                const handler = self.exception_handlers[self.handler_count - 1];
                                self.enterHandler(handler, exc, .owned);
                                return;
                            }
                            self.pending_exception = exc;
                        } else if (self.handler_count < pre_handlers) {
                            // the native threw and a handler already took the exception
                            return;
                        }
                        return error.RuntimeError;
                    };
                    self.frame_count -= 1;
                    self.deinitFrameSlot(self.frame_count);
                    self.pushNativeResult(result);
                } else {
                    const msg = std.fmt.allocPrint(self.allocator, "Call to undefined method {s}::{s}()", .{ self.declaredClassName(class_name), method_name }) catch return error.OutOfMemory;
                    defer self.allocator.free(msg);
                    if (try self.throwBuiltinException("Error", msg)) return;
                    self.setErrorMsg("Fatal error: Uncaught Error: {s}", .{msg});
                    return error.RuntimeError;
                }
            } else {
                try self.callStaticFunction(full_name, arg_count, effective_called);
            }
        } else {
            try self.callStaticFunction(full_name, arg_count, effective_called);
        }
    }

    // zend_fetch_class: self, parent and static with no class scope are
    // their own error; any other missing class is "not found"
    pub fn classNotFoundMessage(self: *VM, class_name: []const u8) ![]u8 {
        if (std.ascii.eqlIgnoreCase(class_name, "parent") and self.currentDefiningClass() != null)
            return std.fmt.allocPrint(self.allocator, "Cannot access \"parent\" when current class scope has no parent", .{});
        inline for (.{ "self", "parent", "static" }) |word| {
            if (std.ascii.eqlIgnoreCase(class_name, word)) return std.fmt.allocPrint(self.allocator, "Cannot access \"" ++ word ++ "\" when no class scope is active", .{});
        }
        return std.fmt.allocPrint(self.allocator, "Class \"{s}\" not found", .{class_name});
    }

    // a method's declaration as the class or an ancestor makes it, or an
    // interface's (abstract) one
    // zend_ast_evaluate's checks on a first-class callable in a constant
    // expression, before the closure is made: a fully qualified function
    // name doesn't fall back to the global one, a method that would reach
    // __callStatic is refused, an abstract one is an Error, and a trait's
    // static method is deprecated. true with the Error pending
    fn constExprCallableRefused(self: *VM, callable: Value, fully_qualified: bool) RuntimeError!bool {
        switch (callable) {
            .string => |s| {
                const name = s.bytes();
                if (self.functionKnown(name)) return false;
                if (!fully_qualified) if (std.mem.lastIndexOfScalar(u8, name, '\\')) |sep| {
                    if (self.functionKnown(name[sep + 1 ..])) return false;
                };
                const msg = try std.fmt.allocPrint(self.allocator, "Call to undefined function {s}()", .{name});
                defer self.allocator.free(msg);
                try self.setPendingException("Error", msg);
                return true;
            },
            .array => |pair| {
                if (pair.entries.items.len != 2) return false;
                const class_val = pair.entries.items[0].value;
                const method_val = pair.entries.items[1].value;
                if (class_val != .string or method_val != .string) return false;
                const class_name = class_val.string.bytes();
                const method_name = method_val.string.bytes();
                const magic = "Creating a callable for the magic __callStatic() method is not supported in constant expressions";
                const found = self.findMethodInfo(class_name, method_name) orelse {
                    if (self.classes.contains(class_name) and self.hasMethod(class_name, "__callStatic")) {
                        try self.setPendingException("Error", magic);
                        return true;
                    }
                    return false;
                };
                if (found.info.visibility != .public and self.hasMethod(class_name, "__callStatic")) {
                    const scope = self.currentDefiningClass();
                    const visible = if (scope) |sc| (if (found.info.visibility == .private) std.ascii.eqlIgnoreCase(sc, found.defining) else self.isInstanceOf(sc, found.defining) or self.isInstanceOf(found.defining, sc)) else false;
                    if (!visible) {
                        try self.setPendingException("Error", magic);
                        return true;
                    }
                }
                if (!found.info.is_static) return false;
                if (found.info.is_abstract) {
                    const msg = try std.fmt.allocPrint(self.allocator, "Cannot call abstract method {s}::{s}()", .{ found.defining, found.info.name });
                    defer self.allocator.free(msg);
                    try self.setPendingException("Error", msg);
                    return true;
                }
                if (self.traits.contains(found.defining)) {
                    const msg = try std.fmt.allocPrint(self.allocator, "Calling static trait method {s}::{s} is deprecated, it should only be called on a class using the trait", .{ found.defining, found.info.name });
                    defer self.allocator.free(msg);
                    try self.raiseError(E_DEPRECATED, msg);
                }
                return false;
            },
            else => return false,
        }
    }

    fn functionKnown(self: *VM, name: []const u8) bool {
        return self.functions.contains(name) or self.native_fns.contains(name) or self.functionNamedIgnoringCase(name) != null;
    }

    fn findMethodInfo(self: *VM, class_name: []const u8, method_name: []const u8) ?struct { info: ClassDef.MethodInfo, defining: []const u8 } {
        var current: ?[]const u8 = class_name;
        while (current) |cn| {
            const entry = self.classes.getEntry(cn) orelse break;
            if (entry.value_ptr.methods.get(method_name)) |info| return .{ .info = info, .defining = entry.key_ptr.* };
            current = entry.value_ptr.parent;
        }
        return null;
    }

    // every method an interface declares is abstract, __callStatic too:
    // a static call on an interface is php's Error. false when class_name
    // names no interface
    fn refuseInterfaceStaticCall(self: *VM, class_name: []const u8, method_name: []const u8, arg_count: u32) RuntimeError!bool {
        const ie = self.interfaces.getEntry(class_name) orelse return false;
        var declared: ?[]const u8 = null;
        var magic = false;
        for (ie.value_ptr.methods.items) |m| {
            if (std.ascii.eqlIgnoreCase(m, method_name)) declared = m;
            if (std.ascii.eqlIgnoreCase(m, "__callStatic")) magic = true;
        }
        self.dropN(arg_count);
        const msg = if (declared != null or magic)
            try std.fmt.allocPrint(self.allocator, "Cannot call abstract method {s}::{s}()", .{ ie.key_ptr.*, declared orelse method_name })
        else
            try std.fmt.allocPrint(self.allocator, "Call to undefined method {s}::{s}()", .{ ie.key_ptr.*, method_name });
        defer self.allocator.free(msg);
        if (try self.throwBuiltinException("Error", msg)) return true;
        return error.RuntimeError;
    }

    // the declaration behind a resolved "Class::method", else by a walk
    fn methodInfoOf(self: *VM, full_name: []const u8, class_name: []const u8, method_name: []const u8) ?struct { info: ClassDef.MethodInfo, defining: []const u8 } {
        if (std.mem.indexOf(u8, full_name, "::")) |sep| {
            if (self.classes.getEntry(full_name[0..sep])) |entry| {
                if (entry.value_ptr.methods.get(method_name)) |info| return .{ .info = info, .defining = entry.key_ptr.* };
            }
        }
        const walked = self.findMethodInfo(class_name, method_name) orelse return null;
        return .{ .info = walked.info, .defining = walked.defining };
    }

    // get_static_method_fallback: $this's __call when $this is an instance
    // of the class, else the class's __callStatic. false when neither exists
    fn staticCallFallback(self: *VM, class_name: []const u8, method_name: []const u8, arg_count: u32, effective_called: []const u8) RuntimeError!bool {
        const ac: usize = arg_count;
        const this_val = self.currentThis();
        if (this_val) |tv| if (tv == .object and self.hasMethod(class_name, "__call") and self.isInstanceOf(tv.object.class_name, class_name)) {
            var args_arr = try self.allocArray();
            for (0..ac) |i| try args_arr.append(self.allocator, self.stack[self.sp - ac + i]);
            self.dropN(ac);
            const result = try self.callMethod(tv.object, "__call", &.{ .{ .string = Value.String.borrowed(method_name) }, .{ .array = args_arr } });
            self.push(result);
            return true;
        };
        if (!self.hasMethod(class_name, "__callStatic")) return false;
        const cs_name = try self.resolveMethod(class_name, "__callStatic");
        if (self.findMethodInfo(class_name, "__callStatic")) |f| if (f.info.is_abstract) {
            self.dropN(ac);
            const msg = try std.fmt.allocPrint(self.allocator, "Cannot call abstract method {s}::{s}()", .{ f.defining, method_name });
            defer self.allocator.free(msg);
            if (try self.throwBuiltinException("Error", msg)) return true;
            return error.RuntimeError;
        };
        var args_arr = try self.allocArray();
        for (0..ac) |i| try args_arr.append(self.allocator, self.stack[self.sp - ac + i]);
        self.dropN(ac);
        self.push(.{ .string = Value.String.borrowed(method_name) });
        self.push(.{ .array = args_arr });
        try self.callStaticFunction(cs_name, 2, effective_called);
        return true;
    }

    // $this in the running frame, a local slot or the frame's vars
    pub fn currentThis(self: *VM) ?Value {
        const f = self.currentFrame();
        if (f.vars.get("$this")) |v| return v;
        if (f.func) |fn_info| if (fn_info.locals_only) {
            for (fn_info.slot_names, 0..) |sn, si| {
                if (std.mem.eql(u8, sn, "$this") and si < f.locals.len and f.locals[si] == .object) return f.locals[si];
            }
        };
        return null;
    }

    // the class a `$class::method()` call looks the method up in, and the
    // class static:: names inside it: self and parent keep the caller's late
    // static binding, as does a call to an ancestor of it
    fn dynamicStaticTarget(self: *VM, raw_class: []const u8) struct { class_name: []const u8, called_class: []const u8 } {
        var class_name = raw_class;
        var lsb_class: ?[]const u8 = null;
        if (std.mem.eql(u8, class_name, "static")) {
            class_name = self.resolveStaticClassName(class_name);
        } else if (std.mem.eql(u8, class_name, "parent") or std.mem.eql(u8, class_name, "self")) {
            if (std.mem.eql(u8, class_name, "parent")) {
                const dc = self.parentResolvingClass();
                if (dc) |defining| {
                    if (self.classes.get(defining)) |cls| {
                        if (cls.parent) |p| class_name = p;
                    }
                    lsb_class = self.currentFrame().called_class orelse defining;
                }
            } else {
                // self:: resolves to defining class for method lookup,
                // but propagates called_class for LSB
                lsb_class = self.currentFrame().called_class;
                if (self.currentDefiningClass()) |dc| class_name = dc;
            }
        } else {
            if (class_name.len > 0 and class_name[0] == '\\') class_name = class_name[1..];
            // a class_alias() name calls the class it names
            class_name = self.classes.aliasTarget(class_name) orelse class_name;
            if (self.currentFrame().called_class) |cc| {
                if (self.isAncestor(class_name, cc)) lsb_class = cc;
            }
        }
        return .{ .class_name = class_name, .called_class = lsb_class orelse class_name };
    }

    fn resolveStaticClassName(self: *VM, name: []const u8) []const u8 {
        if (name.len > 0 and name[0] == '$') {
            const local_val = self.getLocalByName(name);
            if (local_val == .string) {
                const s = local_val.string.bytes();
                return if (s.len > 0 and s[0] == '\\') s[1..] else s;
            }
            if (self.currentFrame().vars.get(name)) |val| {
                if (val == .string) {
                    const s = val.string.bytes();
                    return if (s.len > 0 and s[0] == '\\') s[1..] else s;
                }
            }
            return name;
        }
        if (name.len > 0 and name[0] == '\\') return name[1..];
        if (std.mem.eql(u8, name, "static")) {
            const f = self.currentFrame();
            // called_class takes priority - set by explicit static calls like Base::get()
            if (f.called_class) |cc| return cc;
            if (f.func) |fn_info| {
                if (fn_info.locals_only) {
                    for (fn_info.slot_names, 0..) |sn, si| {
                        if (std.mem.eql(u8, sn, "$this") and si < f.locals.len and f.locals[si] == .object) {
                            return f.locals[si].object.class_name;
                        }
                    }
                }
            }
            if (f.vars.get("$this")) |this_val| {
                if (this_val == .object) return this_val.object.class_name;
            }
            if (self.currentDefiningClass()) |dc| return dc;
        } else if (std.mem.eql(u8, name, "self")) {
            // the class whose method is running: a class's copy of a trait
            // method is its own (traitMethodCopy). a trait method called on
            // the trait itself takes the class it was called through
            const defining = self.currentDefiningClass();
            if (defining) |dc| if (!self.traits.contains(dc)) return dc;
            if (self.currentFrame().called_class) |cc| return cc;
            if (defining) |dc| return dc;
        } else if (std.mem.eql(u8, name, "parent")) {
            if (self.parentResolvingClass()) |dc| {
                if (self.classes.get(dc)) |cls| {
                    if (cls.parent) |p| return p;
                }
            }
        }
        return name;
    }

    // the error ZEND_FETCH_CLASS_NAME throws for a relative class name that
    // resolved to nothing
    fn classNameFetchError(written: []const u8, resolved: []const u8, has_scope: bool) ?[]const u8 {
        if (!std.mem.eql(u8, written, resolved)) return null;
        if (std.ascii.eqlIgnoreCase(written, "self")) return "Cannot use \"self\" in the global scope";
        if (std.ascii.eqlIgnoreCase(written, "static")) return "Cannot use \"static\" in the global scope";
        if (std.ascii.eqlIgnoreCase(written, "parent")) {
            return if (has_scope) "Cannot use \"parent\" when current class scope has no parent" else "Cannot use \"parent\" in the global scope";
        }
        return null;
    }

    // an uninitialized typed static property reads as null here
    pub fn getStaticProp(self: *VM, class_name: []const u8, prop_name: []const u8) ?Value {
        const v = self.getStaticPropRaw(class_name, prop_name) orelse return null;
        return if (v == .undef) .null else v;
    }

    pub fn getStaticPropRaw(self: *VM, class_name: []const u8, prop_name: []const u8) ?Value {
        var current: ?[]const u8 = class_name;
        while (current) |cn| {
            if (self.classes.contains(cn)) {
                if (self.staticPropStep(cn, prop_name)) |step| {
                    if (step.found) |val| return val;
                    current = step.parent;
                } else break;
            } else {
                self.tryAutoload(cn) catch {};
                if (self.staticPropStep(cn, prop_name)) |step| {
                    if (step.found) |val| return val;
                    current = step.parent;
                } else break;
            }
        }
        return null;
    }

    // an enum case as the script reaches it: php creates a case object on
    // first access, so that is when it takes a handle
    pub fn enumCase(self: *VM, value: Value) Value {
        if (value == .object and value.object.id == 0 and !value.object.resource) {
            value.object.id = self.allocHandle() catch 0;
        }
        return value;
    }

    // a class constant or enum case, inherited through parents and
    // interfaces, autoloading ancestors on the way like getStaticProp
    pub fn getClassConstant(self: *VM, class_name: []const u8, const_name: []const u8) ?Value {
        var current: ?[]const u8 = class_name;
        while (current) |cn| {
            if (!self.classes.contains(cn) and !self.resolving_quietly) self.tryAutoload(cn) catch {};
            const step = self.classConstStep(cn, const_name) orelse break;
            if (step.found) |val| return val;
            current = step.parent;
        }
        return null;
    }

    fn classConstStep(self: *VM, cn: []const u8, const_name: []const u8) ?StaticPropStep {
        var ifaces: [64][]const u8 = undefined;
        var n: usize = 0;
        var parent: ?[]const u8 = null;
        {
            var cls = self.classes.getPtr(cn) orelse return null;
            // as php's FETCH_CLASS_CONSTANT does; a constant expression
            // reads the case without it (zend_get_class_constant_ex)
            if (cls.enum_table_pending and !self.resolving_quietly and self.constant_eval_depth == 0) {
                self.updateClassConstants(cn) catch return .{ .found = null, .parent = null };
                cls = self.classes.getPtr(cn) orelse return null;
            }
            if (cls.constants.get(const_name)) |val| {
                if (val == .undef) {
                    if (self.resolving_quietly) return .{ .found = null, .parent = null };
                    return .{ .found = self.evaluateClassConstant(cn, const_name) catch null, .parent = null };
                }
                return .{ .found = self.enumCase(val), .parent = null };
            }
            n = @min(cls.interfaces.items.len, ifaces.len);
            @memcpy(ifaces[0..n], cls.interfaces.items[0..n]);
            parent = cls.parent;
        }
        for (ifaces[0..n]) |iface| {
            if (self.getClassConstant(iface, const_name)) |val| return .{ .found = val, .parent = null };
        }
        return .{ .found = null, .parent = parent };
    }

    // Class::CONST in any of its forms: a missing constant on an existing
    // class is an Error; an unknown class (a default evaluated before its
    // class is declared) reads null. true when an exception was dispatched
    fn pushClassConstant(self: *VM, class_name: []const u8, const_name: []const u8) RuntimeError!bool {
        if (std.mem.eql(u8, const_name, "class")) {
            self.push(.{ .string = Value.String.borrowed(class_name) });
            return false;
        }
        // self, parent or static left unresolved: there is no class to name
        for ([_][]const u8{ "self", "parent", "static" }) |relative| {
            if (!std.mem.eql(u8, class_name, relative)) continue;
            const msg = if (self.currentDefiningClass() != null)
                try std.fmt.allocPrint(self.allocator, "Cannot access \"{s}\" when current class scope has no parent", .{relative})
            else
                try std.fmt.allocPrint(self.allocator, "Cannot access \"{s}\" when no class scope is active", .{relative});
            defer self.allocator.free(msg);
            try self.setPendingException("Error", msg);
            if (self.dispatchPendingException(self.run_base_frame)) return true;
            return error.RuntimeError;
        }
        // a trait's constants exist only in the classes using it
        if (self.traits.contains(class_name)) {
            const declared = self.declaredClassName(class_name);
            const has = if (self.trait_constants.get(declared)) |consts| for (consts) |c| {
                if (std.mem.eql(u8, c.name, const_name)) break true;
            } else false else false;
            const msg = if (has)
                try std.fmt.allocPrint(self.allocator, "Cannot access trait constant {s}::{s} directly", .{ declared, const_name })
            else
                try std.fmt.allocPrint(self.allocator, "Undefined constant {s}::{s}", .{ if (self.inInitializer() and self.class_const_written.len > 0) self.class_const_written else declared, const_name });
            defer self.allocator.free(msg);
            if (try self.throwBuiltinException("Error", msg)) return true;
            return error.RuntimeError;
        }
        const found = self.getClassConstant(class_name, const_name);
        if (found == null and self.pending_exception != null) {
            if (self.dispatchPendingException(self.run_base_frame)) return true;
            return error.RuntimeError;
        }
        const inherited_private = if (found != null) blk: {
            const visibility = self.classConstantVisibility(class_name, const_name);
            if (visibility.denied and !visibility.missing) return self.refuseClassConstant(class_name, const_name, visibility.level);
            break :blk visibility.missing;
        } else false;
        if (found) |val| if (!inherited_private) {
            _ = try self.warnDeprecatedClassConstant(class_name, const_name);
            self.push(val);
            return false;
        };
        const msg = if (!self.classes.contains(class_name) and !self.interfaces.contains(class_name))
            try self.classNotFoundMessage(class_name)
        else
            try std.fmt.allocPrint(self.allocator, "Undefined constant {s}::{s}", .{ if (self.inInitializer() and self.class_const_written.len > 0) self.class_const_written else class_name, const_name });
        defer self.allocator.free(msg);
        if (try self.throwBuiltinException("Error", msg)) return true;
        return error.RuntimeError;
    }

    // the executing get_class_const site now reads `value` for `class_name`
    // php's zend_verify_const_access: a private constant is readable in the
    // class that declares it, a protected one in a class of the same
    // inheritance chain
    pub fn classConstantVisibility(self: *VM, class_name: []const u8, const_name: []const u8) struct { level: ClassDef.Visibility, denied: bool, missing: bool = false } {
        var current: ?[]const u8 = class_name;
        var inherited = false;
        const declarer: *const ClassDef = while (current) |cn| {
            const cls = self.classes.getPtr(cn) orelse return .{ .level = .public, .denied = false };
            if (cls.constants.contains(const_name)) break cls;
            current = cls.parent;
            inherited = true;
        } else return .{ .level = .public, .denied = false };
        const level = declarer.const_visibility.get(const_name) orelse .public;
        if (level == .public) return .{ .level = level, .denied = false };
        // do_inherit_constant: a private constant isn't inherited, so a
        // subclass has none of that name
        if (level == .private and inherited) return .{ .level = level, .denied = true, .missing = true };
        const scope = self.currentDefiningClass() orelse return .{ .level = level, .denied = true };
        const allowed = switch (level) {
            .public => true,
            .private => std.ascii.eqlIgnoreCase(scope, declarer.name),
            .protected => self.isInstanceOf(scope, declarer.name) or self.isInstanceOf(declarer.name, scope),
        };
        return .{ .level = level, .denied = !allowed };
    }

    // for natives (constant()): a constant the calling scope can't see is
    // the pending Error
    pub fn checkClassConstantAccess(self: *VM, class_name: []const u8, const_name: []const u8) RuntimeError!void {
        const visibility = self.classConstantVisibility(class_name, const_name);
        if (!visibility.denied) return;
        if (visibility.missing) {
            const msg = try std.fmt.allocPrint(self.allocator, "Undefined constant {s}::{s}", .{ self.declaredClassName(class_name), const_name });
            defer self.allocator.free(msg);
            try self.setPendingException("Error", msg);
            return error.RuntimeError;
        }
        const msg = try std.fmt.allocPrint(self.allocator, "Cannot access {s} constant {s}::{s}", .{ @tagName(visibility.level), self.declaredClassName(class_name), const_name });
        defer self.allocator.free(msg);
        try self.setPendingException("Error", msg);
        return error.RuntimeError;
    }

    fn refuseClassConstant(self: *VM, class_name: []const u8, const_name: []const u8, level: ClassDef.Visibility) RuntimeError!bool {
        const msg = try std.fmt.allocPrint(self.allocator, "Cannot access {s} constant {s}::{s}", .{ @tagName(level), self.declaredClassName(class_name), const_name });
        defer self.allocator.free(msg);
        if (try self.throwBuiltinException("Error", msg)) return true;
        return error.RuntimeError;
    }

    fn rememberClassConstant(self: *VM, class_name: []const u8, value: Value) void {
        const ic = self.ic orelse return;
        const site = self.currentFrame().ip - 5;
        const chunk_key = @intFromPtr(self.currentChunk());
        ic.class_const[InlineCache.propIndex(chunk_key, site)] = .{ .key = site, .chunk_key = chunk_key, .class_ptr = @intFromPtr(class_name.ptr), .value = value };
    }

    fn forgetClassConstants(self: *VM) void {
        if (self.ic) |ic| ic.class_const = @splat(.{});
    }

    fn classNameOf(v: Value) []const u8 {
        return switch (v) {
            .string => |str| str.bytes(),
            .object => |o| o.class_name,
            else => "",
        };
    }

    const StaticPropStep = struct { found: ?Value, parent: ?[]const u8 };

    // one class of the lookup chain. the interface walk can autoload, which
    // rehashes `classes`, so the class entry is never held across that
    // recursion: names are copied out first and only they are used after
    fn staticPropStep(self: *VM, cn: []const u8, prop_name: []const u8) ?StaticPropStep {
        var ifaces: [64][]const u8 = undefined;
        var n: usize = 0;
        var parent: ?[]const u8 = null;
        {
            const cls = self.classes.getPtr(cn) orelse return null;
            if (cls.static_props.get(prop_name)) |val| return .{ .found = val, .parent = null };
            n = @min(cls.interfaces.items.len, ifaces.len);
            @memcpy(ifaces[0..n], cls.interfaces.items[0..n]);
            parent = cls.parent;
        }
        for (ifaces[0..n]) |iface| {
            if (self.getStaticProp(iface, prop_name)) |val| return .{ .found = val, .parent = null };
        }
        return .{ .found = null, .parent = parent };
    }

    // like getStaticProp but returns a pointer to the storage slot (walking the
    // inheritance chain) so the COW separation can write the unshared array back
    pub fn getStaticPropPtr(self: *VM, class_name: []const u8, prop_name: []const u8) ?*Value {
        var current: ?[]const u8 = class_name;
        while (current) |cn| {
            if (self.classes.getPtr(cn)) |cls| {
                if (cls.static_props.getPtr(prop_name)) |p| return p;
                for (cls.interfaces.items) |iface| {
                    if (self.getStaticPropPtr(iface, prop_name)) |p| return p;
                }
                current = cls.parent;
            } else break;
        }
        return null;
    }

    // poll the execution deadline. backed by a tick counter so the actual
    // monotonic-clock read only happens once every ~4096 backwards jumps -
    // overhead under a percent of a tight loop but still well under a
    // millisecond of slop on the deadline
    pub inline fn pollExecutionDeadline(self: *VM) !void {
        if (self.deadlineReached()) return self.expireExecution();
    }

    pub inline fn deadlineReached(self: *VM) bool {
        if (self.execution_deadline_ns == 0) return false;
        self.deadline_tick_counter +%= 1;
        if (self.deadline_tick_counter & 0xFFF != 0) return false;
        return platform.nanoTimestamp() >= self.execution_deadline_ns;
    }

    fn expireExecution(self: *VM) RuntimeError!void {
        const unit: []const u8 = if (self.execution_limit_seconds == 1) "second" else "seconds";
        const msg = try std.fmt.allocPrint(self.allocator, "Maximum execution time of {d} {s} exceeded", .{ self.execution_limit_seconds, unit });
        defer self.allocator.free(msg);
        try self.setPendingException("Error", msg);
        // PHP makes this fatal uncatchable: even user try/catch around an
        // infinite loop won't keep the script alive past the deadline
        self.uncatchable_fatal = true;
        // disarm so a single overrun isn't reported repeatedly while the
        // stack unwinds toward the run-loop boundary
        self.execution_deadline_ns = 0;
        return error.RuntimeError;
    }

    pub fn setExecutionLimit(self: *VM, seconds: i64) void {
        self.execution_limit_seconds = seconds;
        if (seconds <= 0) {
            self.execution_deadline_ns = 0;
            return;
        }
        const now_ns = platform.nanoTimestamp();
        self.execution_deadline_ns = @intCast(now_ns + @as(i128, seconds) * std.time.ns_per_s);
        self.deadline_tick_counter = 0;
    }

    // resolve the source file the given frame is currently executing in -
    // for function frames the function's declared file, for top-level /
    // require-include frames the per-frame script_path, falling back to the
    // VM-wide file_path. (Without this, traces through require'd files all
    // report the entry script's path instead of the actual file per frame.)
    // return the function's display name for traces / __FUNCTION__-style
    // output. closures (internal name `__closure_N`) become PHP's
    // `{closure:file:line}` form so user code that reads $trace[N]['function']
    // sees the same shape as native PHP
    pub fn funcDisplayName(self: *VM, f: *const ObjFunction) ![]const u8 {
        if (f.display_name.len > 0) return f.display_name;
        if (!std.mem.startsWith(u8, f.name, "__closure_")) return f.name;
        const s = try std.fmt.allocPrint(self.allocator, "{{closure:{s}:{d}}}", .{ f.file_path, f.start_line });
        defer self.allocator.free(s);
        return self.internName(s);
    }

    // how a TypeError names the called function: a closure by its php name,
    // prefixed with the class it is scoped to (`K::{closure:K::s():3}`)
    pub fn callableDisplayName(self: *VM, name: []const u8, func: ?*const ObjFunction) ![]const u8 {
        const f = func orelse return name;
        if (f.display_name.len == 0) return name;
        const class = self.closureDefClassByName(name) orelse return f.display_name;
        const s = try std.fmt.allocPrint(self.allocator, "{s}::{s}", .{ class, f.display_name });
        defer self.allocator.free(s);
        return self.internName(s);
    }

    pub fn frameFile(self: *const VM, frame_idx: usize) []const u8 {
        if (frame_idx >= self.frame_count) return self.file_path;
        const frame = self.frames[frame_idx];
        if (frame.func) |f| if (f.file_path.len > 0) return f.file_path;
        if (frame.script_path.len > 0) return frame.script_path;
        return self.file_path;
    }

    // if frame_idx is a require'd file's top-level frame, append a synthesized
    // trace entry for the bridging require/include call - PHP shows these
    // as `#N caller.php(L): require` in the backtrace. detected by looking
    // at the requirer's (frame_idx-1) ip: when the required file is mid-
    // execution it sits just past the 2-byte `require` opcode (op + variant).
    // skipped silently if the shape does not match (defensive)
    pub fn tryAppendRequireFrame(self: *VM, arr: *PhpArray, frame_idx: usize) !void {
        if (frame_idx == 0 or frame_idx >= self.frame_count) return;
        const frame = self.frames[frame_idx];
        if (frame.func != null) return;
        if (frame.script_path.len == 0) return;
        const requirer = self.frames[frame_idx - 1];
        if (requirer.ip < 2) return;
        const op_byte = requirer.chunk.code.items[requirer.ip - 2];
        if (op_byte != @intFromEnum(OpCode.require)) return;
        const variant = requirer.chunk.code.items[requirer.ip - 1];
        const fn_name: []const u8 = switch (variant) {
            1 => "require_once",
            2 => "include",
            3 => "include_once",
            else => "require",
        };
        const entry = try self.allocArray();
        try entry.set(self.allocator, .{ .string = Value.String.borrowed("function") }, .{ .string = Value.String.borrowed(fn_name) });
        try entry.set(self.allocator, .{ .string = Value.String.borrowed("file") }, .{ .string = Value.String.borrowed(self.frameFile(frame_idx - 1)) });
        if (self.sourceLocation(requirer.chunk, requirer.ip - 2)) |loc| {
            try entry.set(self.allocator, .{ .string = Value.String.borrowed("line") }, .{ .int = @as(i64, @intCast(loc.line)) });
        }
        // php names the included file only when the trace has an entry from
        // inside it
        if (arr.entries.items.len > 0) {
            const args_arr = try self.allocArray();
            try args_arr.append(self.allocator, .{ .string = Value.String.borrowed(frame.script_path) });
            try entry.set(self.allocator, .{ .string = Value.String.borrowed("args") }, .{ .array = args_arr });
        }
        try arr.append(self.allocator, .{ .array = entry });
    }

    // capture the current user call stack as an exception trace array. one
    // entry per active user frame (top-down), each carrying the function name
    // and the call site's line/file - so an exception thrown by a native
    // function still reports the user functions that led to it
    fn buildExceptionTrace(self: *VM) !*PhpArray {
        return self.traceBelow(self.frame_count);
    }

    // the trace of the frames below `top`
    fn traceBelow(self: *VM, top: usize) !*PhpArray {
        const arr = try self.allocArray();
        if (top == 0) return arr;
        // the running natives called from frames below top, innermost first
        var natives: [64]*const NativeCall = undefined;
        var native_count: usize = 0;
        var call = self.native_call;
        while (call) |c| : (call = c.outer) {
            if (c.depth > top) continue;
            if (native_count == natives.len) break;
            natives[native_count] = c;
            native_count += 1;
        }
        var next_native: usize = 0;
        var i: usize = top - 1;
        while (true) : (i -= 1) {
            // natives frame i called, innermost first: the outermost of them
            // was called from frame i's code, each other one by the native
            // outside it
            while (next_native < native_count and natives[next_native].depth == i + 1) : (next_native += 1) {
                if (natives[next_native].label.len == 0) continue;
                const outermost = next_native + 1 == native_count or natives[next_native + 1].depth != i + 1;
                const site = if (outermost and !natives[next_native].from_native) self.framePosition(i) else null;
                try arr.append(self.allocator, .{ .array = try self.nativeTraceEntry(natives[next_native], site, true) });
            }
            if (self.frames[i].func) |f| if (f.name.len > 0) {
                const called_by_native = next_native < native_count and natives[next_native].depth == i;
                const call_site: ?SourcePosition = if (i > 0 and !called_by_native) self.framePosition(i - 1) else null;
                // a generator running as a delegate was reached through the
                // generators waiting in yield from, which php lists between
                // it and the frame that resumed them
                const delegator = if (self.frames[i].generator) |g| g.delegator else null;
                const entry = try self.newTraceEntry(f, if (delegator) |d| self.generatorPosition(d) else call_site);
                // a closure's frame names the class of its scope, with the
                // object it is bound to or statically
                if (std.mem.startsWith(u8, f.name, "__closure_")) if (self.frames[i].call_name) |cn| {
                    if (self.closureScopeByName(cn) orelse self.closureDefClassByName(cn)) |scope| {
                        try entry.set(self.allocator, .{ .string = Value.String.borrowed("class") }, .{ .string = Value.String.borrowed(scope) });
                        try entry.set(self.allocator, .{ .string = Value.String.borrowed("type") }, .{ .string = Value.String.borrowed(if (self.closureThisByName(cn) == .object) "->" else "::") });
                    }
                };
                const entry_args = try self.traceArgs(entry);
                if (self.frames[i].generator != null) {
                    // a resumed generator's frame has no saved arguments: its
                    // parameters hold them
                    const declared = if (f.is_variadic) f.params.len - 1 else f.params.len;
                    for (f.params[0..declared]) |pname| try entry_args.append(self.allocator, frameParamValue(&self.frames[i], f, pname));
                } else try self.appendPassedArgs(entry_args, i, f);
                try arr.append(self.allocator, .{ .array = entry });
                var waiting = delegator;
                while (waiting) |g| : (waiting = g.delegator) {
                    const waiting_entry = try self.newTraceEntry(g.func, if (g.delegator) |d| self.generatorPosition(d) else call_site);
                    const args = try self.traceArgs(waiting_entry);
                    const declared = if (g.func.is_variadic) g.func.params.len - 1 else g.func.params.len;
                    for (g.func.params[0..declared]) |pname| try args.append(self.allocator, generatorParamValue(g, pname));
                    try arr.append(self.allocator, .{ .array = waiting_entry });
                }
            };
            try self.tryAppendRequireFrame(arr, i);
            if (i == 0) break;
        }
        return arr;
    }

    // what a trace shows as a frame's arguments: the ones the call passed, as
    // the parameters hold them now, a variadic parameter spread out, and
    // arguments past the declared ones as they were passed
    fn appendPassedArgs(self: *VM, args: *PhpArray, frame_idx: usize, f: *const ObjFunction) !void {
        const frame = &self.frames[frame_idx];
        const declared = if (f.is_variadic) f.params.len - 1 else f.params.len;
        const passed: ?usize = if (self.ic) |ic| (if (ic.arg_counts[frame_idx] == unknown_arg_count) null else ic.arg_counts[frame_idx]) else null;
        const sensitive = try self.sensitiveParamMask(f);
        for (f.params[0..@min(passed orelse declared, declared)], 0..) |pname, i| try args.append(self.allocator, try self.traceArgValue(frameParamValue(frame, f, pname), sensitive, i));
        if (f.is_variadic) {
            const rest = frameParamValue(frame, f, f.params[declared]);
            if (rest == .array) for (rest.array.entries.items) |e| try args.append(self.allocator, try self.traceArgValue(e.value, sensitive, declared));
            return;
        }
        const count = passed orelse return;
        if (count <= declared) return;
        const saved = self.passedArgs(frame_idx, count) orelse return;
        for (saved[declared..]) |v| try args.append(self.allocator, v);
    }

    // zend_fetch_debug_backtrace: an argument of a #[\SensitiveParameter]
    // parameter shows as a SensitiveParameterValue holding it
    pub fn traceArgValue(self: *VM, v: Value, sensitive: u64, index: usize) !Value {
        if (sensitive == 0 or index >= 64 or sensitive & (@as(u64, 1) << @intCast(index)) == 0) return v;
        const obj = try self.allocUserObject("SensitiveParameterValue");
        try self.initObjectProperties(obj, "SensitiveParameterValue");
        try obj.set(self.allocator, "__value", v);
        return .{ .object = obj };
    }

    pub fn sensitiveParamMask(self: *VM, f: *const ObjFunction) !u64 {
        if (f.params.len == 0) return 0;
        if (self.sensitive_params.get(@intFromPtr(f))) |mask| return mask;
        var mask: u64 = 0;
        const sep = std.mem.indexOf(u8, f.name, "::");
        for (f.params, 0..) |raw, i| {
            if (i >= 64) break;
            const pname = if (raw.len > 0 and raw[0] == '$') raw[1..] else raw;
            const attrs: ?[]const AttributeDef = blk: {
                if (sep) |at| {
                    var key_buf: [256]u8 = undefined;
                    const key = std.fmt.bufPrint(&key_buf, "{s}:{s}", .{ f.name[at + 2 ..], pname }) catch break :blk null;
                    if (self.classes.get(f.name[0..at])) |cls| if (cls.param_attributes.get(key)) |found| break :blk found;
                }
                const owner = if (f.trait_origin.len > 0) f.trait_origin else f.name;
                const key = try bytecode.paramAttributesName(self.allocator, owner, pname);
                defer self.allocator.free(key);
                break :blk self.function_attributes.get(key);
            };
            for (attrs orelse continue) |attr| {
                const name = if (attr.name.len > 0 and attr.name[0] == '\\') attr.name[1..] else attr.name;
                if (std.ascii.eqlIgnoreCase(name, "SensitiveParameter")) mask |= @as(u64, 1) << @intCast(i);
            }
        }
        try self.sensitive_params.put(self.allocator, @intFromPtr(f), mask);
        return mask;
    }

    // the arguments saved for a frame's func_get_args, when they were
    fn passedArgs(self: *VM, frame_idx: usize, count: usize) ?[]const Value {
        const ic = self.ic orelse return null;
        if (frame_idx >= ic.fga_offsets_room.committed or ic.fga_offsets[frame_idx] == fga_unsaved) return null;
        const offset: usize = ic.fga_offsets[frame_idx];
        if (offset + count > ic.fga_room.committed) return null;
        return ic.fga_buf[offset .. offset + count];
    }

    pub fn nativeTraceEntry(self: *VM, call: *const NativeCall, call_site: ?SourcePosition, with_args: bool) !*PhpArray {
        const entry = try self.allocArray();
        if (call_site) |site| {
            try entry.set(self.allocator, .{ .string = Value.String.borrowed("file") }, .{ .string = Value.String.borrowed(site.file) });
            try entry.set(self.allocator, .{ .string = Value.String.borrowed("line") }, .{ .int = site.line });
        }
        if (std.mem.indexOf(u8, call.label, "::")) |sep| {
            try entry.set(self.allocator, .{ .string = Value.String.borrowed("function") }, .{ .string = Value.String.borrowed(call.label[sep + 2 ..]) });
            try entry.set(self.allocator, .{ .string = Value.String.borrowed("class") }, .{ .string = Value.String.borrowed(call.label[0..sep]) });
            try entry.set(self.allocator, .{ .string = Value.String.borrowed("type") }, .{ .string = Value.String.borrowed(if (call.instance) "->" else "::") });
        } else {
            try entry.set(self.allocator, .{ .string = Value.String.borrowed("function") }, .{ .string = Value.String.borrowed(call.label) });
        }
        if (!with_args) return entry;
        const args = try self.traceArgs(entry);
        // the parameters php's stubs mark #[\SensitiveParameter]
        const sensitive = deprecations.sensitive_parameters.get(call.label) orelse 0;
        for (call.args, 0..) |a, i| try args.append(self.allocator, try self.traceArgValue(a, sensitive, i));
        return entry;
    }

    const AbstractCandidate = struct { name: []const u8, scope: []const u8 };

    // php's zend_verify_abstract_class: a class that isn't abstract implements
    // every abstract method its parents and interfaces leave it, property
    // hooks included. the error counts what is missing and names the first
    // three in php's order (the class's method table, then its hooks)
    fn verifyAbstractClass(self: *VM, class_name: []const u8, def: *const ClassDef) RuntimeError!void {
        var candidates = std.ArrayListUnmanaged(AbstractCandidate).empty;
        defer candidates.deinit(self.allocator);
        var seen = std.StringHashMapUnmanaged(void){};
        defer seen.deinit(self.allocator);
        for (def.method_order.items) |m| {
            const info = def.methods.get(m) orelse continue;
            try seen.put(self.allocator, m, {});
            if (info.is_abstract) try candidates.append(self.allocator, .{ .name = m, .scope = class_name });
        }
        var current_parent: ?[]const u8 = def.parent;
        while (current_parent) |pn| {
            const pc = self.classes.getPtr(pn) orelse break;
            for (pc.method_order.items) |m| {
                const info = pc.methods.get(m) orelse continue;
                if (!info.is_abstract or seen.contains(m)) continue;
                try seen.put(self.allocator, m, {});
                try candidates.append(self.allocator, .{ .name = m, .scope = pn });
            }
            current_parent = pc.parent;
        }
        // the interfaces of the class and of its parents
        var walk: ?*const ClassDef = def;
        while (walk) |cd| {
            // a built-in class satisfies its own interfaces even when zphp
            // registers no method entry for some of them
            if (cd.is_internal) break;
            for (cd.interfaces.items) |iname| try self.collectInterfaceMethods(iname, &candidates, &seen, 0);
            walk = if (cd.parent) |p| self.classes.getPtr(p) else null;
        }

        var missing = std.ArrayListUnmanaged(AbstractCandidate).empty;
        defer missing.deinit(self.allocator);
        var hooks = std.ArrayListUnmanaged(AbstractCandidate).empty;
        defer hooks.deinit(self.allocator);
        for (candidates.items) |c| {
            if (try self.implementsAbstract(def, c.name)) continue;
            try (if (std.mem.indexOf(u8, c.name, "$hook_") != null) &hooks else &missing).append(self.allocator, c);
        }
        try missing.appendSlice(self.allocator, hooks.items);
        if (missing.items.len == 0) return;

        var names = std.ArrayListUnmanaged(u8).empty;
        defer names.deinit(self.allocator);
        for (missing.items[0..@min(missing.items.len, 3)], 0..) |c, i| {
            if (i > 0) try names.appendSlice(self.allocator, ", ");
            try names.print(self.allocator, "{s}::{s}", .{ c.scope, try self.phpMethodName(c.name) });
        }
        if (missing.items.len > 3) try names.appendSlice(self.allocator, ", ...");
        const plural: []const u8 = if (missing.items.len > 1) "s" else "";
        // an anonymous class or an enum cannot be declared abstract, so php
        // does not suggest it
        const msg = if (class_names.isAnonymous(class_name) or def.is_enum)
            try std.fmt.allocPrint(self.allocator, "{s} {s} must implement {d} abstract method{s} ({s})", .{ if (def.is_enum) "Enum" else "Class", class_name, missing.items.len, plural, names.items })
        else
            try std.fmt.allocPrint(self.allocator, "Class {s} contains {d} abstract method{s} and must therefore be declared abstract or implement the remaining method{s} ({s})", .{ class_name, missing.items.len, plural, plural, names.items });
        defer self.allocator.free(msg);
        return self.raiseFatal(msg);
    }

    fn collectInterfaceMethods(self: *VM, iface: []const u8, out: *std.ArrayListUnmanaged(AbstractCandidate), seen: *std.StringHashMapUnmanaged(void), depth: u8) RuntimeError!void {
        if (depth > 64) return;
        const idef = self.interfaces.getPtr(iface) orelse return;
        for (idef.methods.items) |m| {
            if (seen.contains(m)) continue;
            try seen.put(self.allocator, m, {});
            try out.append(self.allocator, .{ .name = m, .scope = idef.name });
        }
        if (idef.parent) |p| try self.collectInterfaceMethods(p, out, seen, depth + 1);
        for (idef.parents.items) |p| try self.collectInterfaceMethods(p, out, seen, depth + 1);
    }

    // whether the class (or a parent) has a concrete method for an abstract
    // one; a hook contract may also be met by a plain public property
    fn implementsAbstract(self: *VM, def: *const ClassDef, name: []const u8) RuntimeError!bool {
        if (std.mem.indexOf(u8, name, "$hook_")) |split| {
            if (self.resolvePropertyHook(def, name)) |hook| {
                if (!hook.info.is_abstract) return true;
            } else {
                var current: ?*const ClassDef = def;
                while (current) |cls| {
                    for (cls.properties.items) |prop| {
                        if (!std.mem.eql(u8, prop.name, name[0..split])) continue;
                        if (!prop.is_virtual and
                            !(std.mem.endsWith(u8, name, "$hook_set") and prop.is_readonly)) return true;
                    }
                    current = if (cls.parent) |parent| self.classes.getPtr(parent) else null;
                }
            }
        }
        // native methods need not have entries in ClassDef.methods, so check
        // their registry at each level, but never skip an abstract
        // redeclaration to reach a concrete implementation further up
        var cls: ?*const ClassDef = def;
        while (cls) |c| {
            if (c.methods.get(name)) |method| return !method.is_abstract;
            const full = try std.fmt.allocPrint(self.allocator, "{s}::{s}", .{ c.name, name });
            defer self.allocator.free(full);
            if (self.native_fns.contains(full)) return true;
            cls = if (c.parent) |parent| self.classes.getPtr(parent) else null;
        }
        return false;
    }

    // the name php gives a method: a property hook zphp registers as
    // "prop$hook_get" is "$prop::get"
    pub fn phpMethodName(self: *VM, method: []const u8) ![]const u8 {
        const hook = std.mem.indexOf(u8, method, "$hook_") orelse return method;
        const s = try std.fmt.allocPrint(self.allocator, "${s}::{s}", .{ method[0..hook], method[hook + "$hook_".len ..] });
        defer self.allocator.free(s);
        return self.internName(s);
    }

    // keys in php's order: file, line, function, class, type, then args
    fn newTraceEntry(self: *VM, f: *const ObjFunction, call_site: ?SourcePosition) !*PhpArray {
        const entry = try self.allocArray();
        if (call_site) |site| {
            try entry.set(self.allocator, .{ .string = Value.String.borrowed("file") }, .{ .string = Value.String.borrowed(site.file) });
            try entry.set(self.allocator, .{ .string = Value.String.borrowed("line") }, .{ .int = site.line });
        }
        if (std.mem.indexOf(u8, f.name, "::")) |sep| {
            try entry.set(self.allocator, .{ .string = Value.String.borrowed("function") }, .{ .string = Value.String.borrowed(try self.phpMethodName(f.name[sep + 2 ..])) });
            try entry.set(self.allocator, .{ .string = Value.String.borrowed("class") }, .{ .string = Value.String.borrowed(f.name[0..sep]) });
            try entry.set(self.allocator, .{ .string = Value.String.borrowed("type") }, .{ .string = Value.String.borrowed(if (f.is_static) "::" else "->") });
        } else {
            try entry.set(self.allocator, .{ .string = Value.String.borrowed("function") }, .{ .string = Value.String.borrowed(try self.funcDisplayName(f)) });
        }
        return entry;
    }

    // zend.exception_ignore_args: an exception's trace has no "args"
    // (zend_fetch_debug_backtrace with DEBUG_BACKTRACE_IGNORE_ARGS)
    fn dropExceptionTraceArgs(self: *VM, trace: *PhpArray) void {
        if (!self.iniFlagOn("zend.exception_ignore_args", "0")) return;
        const key: PhpArray.Key = .{ .string = Value.String.borrowed("args") };
        for (trace.entries.items) |e| {
            if (e.value != .array) continue;
            const args = e.value.array.get(key);
            if (args == .null) continue;
            e.value.array.remove(key);
            self.releaseValue(args);
        }
    }

    fn traceArgs(self: *VM, entry: *PhpArray) !*PhpArray {
        const args = try self.allocArray();
        try entry.set(self.allocator, .{ .string = Value.String.borrowed("args") }, .{ .array = args });
        return args;
    }

    // the file and line a frame is executing
    pub fn framePosition(self: *VM, frame_idx: usize) ?SourcePosition {
        const frame = &self.frames[frame_idx];
        const ip = if (frame.ip > 0) frame.ip - 1 else 0;
        const loc = self.sourceLocation(frame.chunk, ip) orelse return null;
        return .{ .file = self.frameFile(frame_idx), .line = @intCast(loc.line) };
    }

    // a call rejected before its frame exists still appears first in the trace
    fn prependCallToTrace(self: *VM, exc: *PhpObject, f: *const ObjFunction, args: []const Value) !void {
        const scope = self.exceptionTraceScope(exc);
        const old = exc.getForScope("trace", scope);
        const trace = try self.allocArray();
        const entry = try self.newTraceEntry(f, if (self.frame_count > 0 and !self.calledFromNative()) self.framePosition(self.frame_count - 1) else null);
        const entry_args = try self.traceArgs(entry);
        const sensitive = try self.sensitiveParamMask(f);
        for (args, 0..) |a, i| try entry_args.append(self.allocator, try self.traceArgValue(a, sensitive, @min(i, if (f.is_variadic and f.params.len > 0) f.params.len - 1 else i)));
        try trace.append(self.allocator, .{ .array = entry });
        if (old == .array) for (old.array.entries.items) |e| try trace.append(self.allocator, e.value);
        // an include the call is made from now has an entry from inside the
        // included file, so it names that file
        if (old == .array and old.array.entries.items.len > 0) if (self.frame_count > 0) {
            const next = old.array.entries.items[0].value;
            if (next == .array and next.array.get(.{ .string = Value.String.borrowed("args") }) == .null) {
                const func_name = next.array.get(.{ .string = Value.String.borrowed("function") });
                const included = func_name == .string and (std.mem.eql(u8, func_name.string.bytes(), "require") or std.mem.eql(u8, func_name.string.bytes(), "require_once") or std.mem.eql(u8, func_name.string.bytes(), "include") or std.mem.eql(u8, func_name.string.bytes(), "include_once"));
                const path = self.frames[self.frame_count - 1].script_path;
                if (included and path.len > 0) {
                    const args_arr = try self.allocArray();
                    try args_arr.append(self.allocator, .{ .string = Value.String.borrowed(path) });
                    try next.array.set(self.allocator, .{ .string = Value.String.borrowed("args") }, .{ .array = args_arr });
                }
            }
        };
        self.dropExceptionTraceArgs(trace);
        try exc.setForScope(self.allocator, "trace", .{ .array = trace }, scope);
    }

    // where a suspended generator waits: the instruction it last ran
    pub fn generatorPosition(self: *VM, g: *const Generator) ?SourcePosition {
        const loc = self.sourceLocation(&g.func.chunk, if (g.ip > 0) g.ip - 1 else 0) orelse return null;
        return .{ .file = if (g.func.file_path.len > 0) g.func.file_path else self.file_path, .line = @intCast(loc.line) };
    }

    pub fn generatorParamValue(g: *const Generator, param_name: []const u8) Value {
        if (g.vars.get(param_name)) |v| return v;
        for (g.func.slot_names, 0..) |sn, si| {
            if (!std.mem.eql(u8, sn, param_name)) continue;
            return if (si < g.locals.items.len) g.locals.items[si] else .null;
        }
        return .null;
    }

    // a live frame's bound parameter: the vars map first, then the locals
    // that locals-only frames keep parameters in
    pub fn frameParamValue(frame: *const CallFrame, f: *const ObjFunction, param_name: []const u8) Value {
        if (frame.vars.get(param_name)) |v| return v;
        for (f.slot_names, 0..) |sn, si| {
            if (!std.mem.eql(u8, sn, param_name)) continue;
            return if (si < frame.locals.len) frame.locals[si] else .null;
        }
        return .null;
    }

    // Native throwable access must use the root declaring class, never a
    // subclass's unrelated same-name property.
    pub fn exceptionTraceScope(self: *const VM, obj: *const PhpObject) []const u8 {
        var name = obj.class_name;
        while (true) {
            if (std.mem.eql(u8, name, "Error")) return "Error";
            if (std.mem.eql(u8, name, "Exception")) return "Exception";
            const cls = self.classes.get(name) orelse break;
            name = cls.parent orelse break;
        }
        return "Exception";
    }

    // strtok's string, a copy the VM owns
    pub fn setStrtokState(self: *VM, state: ?[]const u8) void {
        if (self.strtok_state) |old| self.allocator.free(old);
        self.strtok_state = state;
    }

    pub fn setPendingException(self: *VM, class_name: []const u8, message: []const u8) !void {
        const obj = try self.allocUserObject(class_name);
        try self.initObjectProperties(obj, class_name);
        const owned_message = try self.engineMessage(message);
        defer owned_message.release();
        try obj.set(self.allocator, "message", .{ .string = owned_message });
        try obj.set(self.allocator, "code", .{ .int = 0 });
        self.raise(.{ .object = obj });
    }

    // pending_exception owns one reference to the throwable it holds. raise
    // takes a reference of its own; setPendingOwned stores one the caller
    // hands over; takePending hands it back to a caller that moves it on;
    // discardPending drops it
    pub fn raise(self: *VM, exc: Value) void {
        stackRetain(exc);
        self.setPendingOwned(exc);
    }

    pub fn setPendingOwned(self: *VM, exc: Value) void {
        if (self.pending_exception) |old| self.stackRelease(old);
        self.pending_exception = exc;
    }

    pub fn takePending(self: *VM) ?Value {
        const exc = self.pending_exception orelse return null;
        self.pending_exception = null;
        return exc;
    }

    pub fn discardPending(self: *VM) void {
        const exc = self.takePending() orelse return;
        self.stackRelease(exc);
    }

    // php keys an array by a resource's id, with a warning
    // destructuring something that isn't an array
    fn warnListFromScalar(self: *VM, container: Value) RuntimeError!void {
        const type_name: []const u8 = switch (container) {
            .bool => "bool",
            .int => "int",
            .float => "float",
            .string => "string",
            .resource => "resource",
            else => return,
        };
        const msg = std.fmt.allocPrint(self.allocator, "Cannot use {s} as array", .{type_name}) catch return error.OutOfMemory;
        defer self.allocator.free(msg);
        try self.emitWarning(msg);
    }

    // `$a[k] = $a`: php reads the right side into a temporary before it
    // fetches the container for writing, so the element gets the array as it
    // was rather than the array being written
    fn selfStoreCopy(self: *VM, target: *PhpArray, val: Value) RuntimeError!Value {
        if (val == .array and val.array == target) return .{ .array = try self.cloneArray(target) };
        return val;
    }

    pub const StringAssign = struct { string: Value, result: Value };

    // zend_assign_to_string_offset: the string with the byte at key replaced
    // by the first byte of val (padding with spaces past the end) and the
    // one-byte string the assignment yields; null when it failed (an
    // exception is pending or the warning left the result null)
    pub fn assignStringOffset(self: *VM, s: []const u8, key: Value, val: Value) RuntimeError!?StringAssign {
        const offset: i64 = switch (key) {
            .int => |i| i,
            .string => |str| blk: {
                const parsed = offsetStringKey(str.bytes());
                switch (parsed.kind) {
                    .integer => break :blk parsed.value,
                    .trailing => {
                        const msg = try std.fmt.allocPrint(self.allocator, "Illegal string offset \"{s}\"", .{str.bytes()});
                        defer self.allocator.free(msg);
                        try self.emitWarning(msg);
                        break :blk parsed.value;
                    },
                    .other => {
                        try self.setPendingException("TypeError", "Cannot access offset of type string on string");
                        return null;
                    },
                }
            },
            .null, .undef, .bool, .float => blk: {
                try self.emitWarning("String offset cast occurred");
                break :blk Value.toInt(key);
            },
            else => {
                const msg = try std.fmt.allocPrint(self.allocator, "Cannot access offset of type {s} on string", .{if (key == .object) key.object.class_name else key.valueName()});
                defer self.allocator.free(msg);
                try self.setPendingException("TypeError", msg);
                return null;
            },
        };
        const len: i64 = @intCast(s.len);
        if (offset < -len) {
            const msg = try std.fmt.allocPrint(self.allocator, "Illegal string offset {d}", .{offset});
            defer self.allocator.free(msg);
            try self.emitWarning(msg);
            return null;
        }
        const at: usize = @intCast(if (offset < 0) offset + len else offset);
        var tmp: std.ArrayListUnmanaged(u8) = .empty;
        defer tmp.deinit(self.allocator);
        const text: []const u8 = if (val == .string) val.string.bytes() else blk: {
            if (val == .object) {
                try tmp.appendSlice(self.allocator, try self.objectToString(val.object));
            } else {
                if (val == .array) try self.emitWarning("Array to string conversion");
                try val.format(&tmp, self.allocator);
            }
            break :blk tmp.items;
        };
        if (text.len != 1) {
            if (text.len == 0) {
                try self.setPendingException("Error", "Cannot assign an empty string to a string offset");
                return null;
            }
            try self.emitWarning("Only the first byte will be assigned to the string offset");
        }
        const byte = text[0];
        const buf = try self.allocator.alloc(u8, @max(s.len, at + 1));
        @memcpy(buf[0..s.len], s);
        if (at >= s.len) @memset(buf[s.len..at], ' ');
        buf[at] = byte;
        const new_str = Value{ .string = try Value.String.adopt(self.allocator, buf) };
        const one = try self.allocator.dupe(u8, &.{byte});
        return .{ .string = new_str, .result = .{ .string = try Value.String.adopt(self.allocator, one) } };
    }

    pub const StringOffsetMode = enum { read, coalesce, isset };
    pub const StringOffset = union(enum) { at: usize, none, resumed };

    // the byte a string offset names, as zend_fetch_dimension_str and
    // zend_isset_dim_slow resolve it: an integer-numeric string names its
    // number (one with trailing data warns "Illegal string offset"), other
    // scalars are cast (a read warns), anything else is a TypeError except
    // under isset. a read past the end warns "Uninitialized string offset"
    fn stringOffset(self: *VM, len: usize, key: Value, mode: StringOffsetMode) RuntimeError!StringOffset {
        const index: i64 = switch (key) {
            .int => |i| i,
            .string => |str| blk: {
                const parsed = offsetStringKey(str.bytes());
                switch (parsed.kind) {
                    .integer => break :blk parsed.value,
                    .trailing => {
                        if (mode == .isset) return .none;
                        const msg = try std.fmt.allocPrint(self.allocator, "Illegal string offset \"{s}\"", .{str.bytes()});
                        defer self.allocator.free(msg);
                        self.emitWarning(msg) catch return if (try self.resumeRaised()) .resumed else error.RuntimeError;
                        break :blk parsed.value;
                    },
                    .other => {
                        if (mode != .read) return .none;
                        if (try self.throwBuiltinException("TypeError", "Cannot access offset of type string on string")) return .resumed;
                        return error.RuntimeError;
                    },
                }
            },
            .null, .undef, .bool, .float => blk: {
                if (mode == .read) self.emitWarning("String offset cast occurred") catch return if (try self.resumeRaised()) .resumed else error.RuntimeError;
                break :blk Value.toInt(key);
            },
            else => {
                if (mode == .isset) return .none;
                const msg = try std.fmt.allocPrint(self.allocator, "Cannot access offset of type {s} on string", .{if (key == .object) key.object.class_name else key.valueName()});
                defer self.allocator.free(msg);
                if (try self.throwBuiltinException("TypeError", msg)) return .resumed;
                return error.RuntimeError;
            },
        };
        const in_range = if (index >= 0) index < len else index != std.math.minInt(i64) and @as(usize, @intCast(-index)) <= len;
        if (in_range) return .{ .at = if (index >= 0) @intCast(index) else len - @as(usize, @intCast(-index)) };
        if (mode == .read) {
            const msg = try std.fmt.allocPrint(self.allocator, "Uninitialized string offset {d}", .{index});
            defer self.allocator.free(msg);
            self.emitWarning(msg) catch return if (try self.resumeRaised()) .resumed else error.RuntimeError;
        }
        return .none;
    }

    const OffsetStringKey = struct { kind: enum { integer, trailing, other }, value: i64 = 0 };

    // php's is_numeric_string as a string offset reads it: whitespace around
    // an integer is allowed, a float or an overflow is not an integer, and
    // an integer followed by anything else is one with trailing data
    fn offsetStringKey(s: []const u8) OffsetStringKey {
        const space = " \t\n\r\x0b\x0c";
        var i: usize = 0;
        while (i < s.len and std.mem.indexOfScalar(u8, space, s[i]) != null) i += 1;
        const start = i;
        if (i < s.len and (s[i] == '-' or s[i] == '+')) i += 1;
        const digits_start = i;
        while (i < s.len and std.ascii.isDigit(s[i])) i += 1;
        if (i == digits_start) return .{ .kind = .other };
        const value = std.fmt.parseInt(i64, s[start..i], 10) catch return .{ .kind = .other };
        if (i < s.len and s[i] == '.') return .{ .kind = .other };
        if (i < s.len and (s[i] == 'e' or s[i] == 'E')) {
            var j = i + 1;
            if (j < s.len and (s[j] == '-' or s[j] == '+')) j += 1;
            if (j < s.len and std.ascii.isDigit(s[j])) return .{ .kind = .other };
        }
        var end = i;
        while (end < s.len and std.mem.indexOfScalar(u8, space, s[end]) != null) end += 1;
        return .{ .kind = if (end == s.len) .integer else .trailing, .value = value };
    }

    // reading an element of something that holds no elements
    fn warnScalarOffsetRead(self: *VM, container: Value) RuntimeError!void {
        const type_name: []const u8 = switch (container) {
            .null, .undef => "null",
            .bool => |b| if (b) "true" else "false",
            .int => "int",
            .float => "float",
            .resource => "resource",
            else => return,
        };
        const msg = std.fmt.allocPrint(self.allocator, "Trying to access array offset on {s}", .{type_name}) catch return error.OutOfMemory;
        defer self.allocator.free(msg);
        try self.emitWarning(msg);
    }

    // an array offset php converts with a diagnostic: a resource, or a float
    // (zend_dval_to_lval_safe: past the int range warns, a fraction is
    // deprecated)
    pub fn warnOffsetKey(self: *VM, key: Value) RuntimeError!void {
        switch (key) {
            .resource => return self.warnResourceOffset(key),
            // php 8.5: null names the "" key, deprecated
            .null => return self.raiseError(E_DEPRECATED, "Using null as an array offset is deprecated, use an empty string instead"),
            .float => |f| {
                if (!(f >= -9.2233720368547758e18 and f < 9.2233720368547758e18)) {
                    var tmp: [64]u8 = undefined;
                    const m = try std.fmt.allocPrint(self.allocator, "The float {s} is not representable as an int, cast occurred", .{formatted_print.gcvt(f, -1, '.', 'E', &tmp)});
                    defer self.allocator.free(m);
                    return self.emitWarning(m);
                }
                if (f != @trunc(f)) try self.warnLossyIntConversion(f, null);
            },
            else => {},
        }
    }

    // zend_false_to_array_deprecated: a write made false an array
    pub fn falseToArrayDeprecated(self: *VM) RuntimeError!void {
        return self.raiseError(E_DEPRECATED, "Automatic conversion of false to array is deprecated");
    }

    // warnOffsetKey while the array it indexes is pinned: an error handler
    // may drop the last reference to it (php's GC_TRY_ADDREF around the
    // notice). false when it did, and the access must leave the array alone
    fn warnOffsetKeyOn(self: *VM, key: Value, arr: *PhpArray, keep: Value) RuntimeError!bool {
        const before = arr.refcount;
        arrayRetain(arr);
        // the value being written is off the stack and counted nowhere; the
        // handler's statements would free it
        retainValue(keep);
        defer self.releaseValue(keep);
        self.warnOffsetKey(key) catch |err| {
            arrayUnpin(arr);
            if (arr.refcount < before and arr.refcount == 0) self.queueArrayRelease(arr);
            return err;
        };
        const kept = arr.refcount > before;
        arrayUnpin(arr);
        // a temporary nothing counted stays as it was; one whose holders
        // went away goes now
        if (!kept and arr.refcount == 0) self.queueArrayRelease(arr);
        return kept;
    }

    pub fn warnResourceOffset(self: *VM, key: Value) RuntimeError!void {
        const msg = std.fmt.allocPrint(self.allocator, "Resource ID#{d} used as offset, casting to integer ({d})", .{ key.resource.id, key.resource.id }) catch return error.OutOfMemory;
        defer self.allocator.free(msg);
        try self.emitWarning(msg);
    }

    pub const OffsetOp = enum { access, isset_or_empty, unset };

    pub fn throwOffsetKeyType(self: *VM, key: Value, op: OffsetOp) RuntimeError!bool {
        const tn: []const u8 = if (key == .object) key.object.class_name else "array";
        const msg = switch (op) {
            .access => std.fmt.allocPrint(self.allocator, "Cannot access offset of type {s} on array", .{tn}),
            .isset_or_empty => std.fmt.allocPrint(self.allocator, "Cannot access offset of type {s} in isset or empty", .{tn}),
            .unset => std.fmt.allocPrint(self.allocator, "Cannot unset offset of type {s} on array", .{tn}),
        } catch return error.RuntimeError;
        defer self.allocator.free(msg);
        return self.throwBuiltinException("TypeError", msg);
    }

    // the unwind marker: pinned, so the operand stack's counting never
    // frees it
    pub fn unwindMarker(self: *VM) RuntimeError!*PhpObject {
        if (self.unwind_marker) |marker| return marker;
        const marker = try self.allocator.create(PhpObject);
        marker.* = .{ .class_name = "\x00unwind", .id = std.math.maxInt(u32), .refcount = 1 << 30 };
        self.unwind_marker = marker;
        return marker;
    }

    pub fn isUnwindMarker(self: *const VM, v: Value) bool {
        const marker = self.unwind_marker orelse return false;
        return v == .object and v.object == marker;
    }

    // php's zend_generator_dtor_storage: a generator destroyed before it
    // finished leaves the yield from it waits in (the delegate is not
    // touched) and runs the finally blocks around where it waits. a yield
    // in one is an Error. an exception one throws reaches the code that
    // destroyed the generator, taking an exception already in flight as its
    // previous
    pub fn closeGenerator(self: *VM, gen: *Generator, base_frame: usize) RuntimeError!void {
        _ = base_frame;
        if (gen.state == .completed or gen.state == .running) return;
        self.dropGeneratorDelegate(gen);
        // no try block around where it waits: nothing to run
        if (gen.state == .created or gen.saved_handlers.items.len == 0) return;
        const marker = try self.unwindMarker();
        const in_flight = self.takePending();
        defer self.settleDrainException(in_flight);
        gen.forced_close = true;
        stackRetain(.{ .object = marker });
        if (gen.pending_throw) |old| self.stackRelease(old);
        gen.pending_throw = .{ .object = marker };
        genRetain(gen);
        defer self.genRelease(gen);
        self.resumeGeneratorWithValue(gen, .null) catch |err| {
            if (err != error.RuntimeError) return err;
        };
        if (self.pending_exception) |ex| {
            if (self.isUnwindMarker(ex)) self.discardPending();
        }
    }

    // release the generator's persistent locals (Stage 2 finer generator
    // lifetime). before this, a generator's vars were retained on init via
    // retainVarsObjects and only released at end-of-request; explicit close
    // (unset of $gen, foreach-break) OR natural completion (yield-then-return)
    // can drop the resources now. idempotent - clears the map so a later call
    // from the same completion path is a no-op
    // a generator owns its current key/value and return value: yields hand
    // over the popped (transferred) values, delegation copies the inner
    // generator's or array's values and must add its own reference
    fn setGeneratorCurrent(self: *VM, gen: *Generator, key: Value, value: Value, comptime owned: bool) void {
        if (!owned) {
            retainValue(key);
            retainValue(value);
        } else {
            // the operand stack never counts arrays, so a transferred array
            // carries no reference: the generator takes one now
            if (key == .array) arrayRetain(key.array);
            if (value == .array) arrayRetain(value.array);
        }
        self.releaseValue(gen.current_key);
        self.releaseValue(gen.current_value);
        gen.current_key = key;
        gen.current_value = value;
        gen.current_ref = null;
        gen.has_value = true;
    }

    pub fn releaseGeneratorVars(self: *VM, gen: *@import("value.zig").Generator) void {
        gen.current_ref = null;
        for (gen.extra_args.items) |arg| self.releaseValue(arg);
        gen.extra_args.clearRetainingCapacity();
        self.deinitRefSlots(&gen.ref_slots);
        self.releaseGeneratorBindings(gen);
        // release the inner gen the outer was delegating to (yield from path)
        self.dropGeneratorDelegate(gen);
        var vit = gen.vars.valueIterator();
        while (vit.next()) |v| self.releaseValue(v.*);
        // suspended state the generator carried: its frame locals, operand
        // stack, and the values it currently exposes. a named local mirrored
        // in vars shares that entry's reference (see releaseFrameObjects)
        const vars_populated = gen.vars.count() > 0;
        for (gen.locals.items, 0..) |v, i| {
            if (vars_populated and i < gen.func.slot_names.len and gen.func.slot_names[i].len > 0 and gen.vars.contains(gen.func.slot_names[i])) continue;
            self.releaseValue(v);
        }
        gen.vars.clearRetainingCapacity();
        gen.locals.clearRetainingCapacity();
        // saved operand-stack slots follow stack ownership (arrays uncounted)
        for (gen.stack.items) |v| self.stackRelease(v);
        gen.stack.clearRetainingCapacity();
        // the last value it yielded stays until it is freed: a generator
        // that delegated to this one takes it when it reads its current
        // value (php's zend_generator_update_current)
        // PHP fires the destructors at the generator-completion boundary, not
        // at the next statement; drain now so end-of-foreach + reassign order
        // matches. safe to call inline - drainPendingDestruct is reentrancy-
        // guarded
        if (self.hasPendingReleases()) self.drainPendingDestruct();
    }

    /// PHP 8 rejects non-numeric strings, arrays (except for +), and objects
    /// without __toString as arithmetic operands with TypeError. returns true
    /// when the throw was caught in-frame and the caller should `continue`
    const PushedArgs = union(enum) { count: usize, thrown };

    // a `new` whose arguments arrived as one array (named or spread): pushes
    // them in the constructor's parameter order, with defaults for skipped
    // user parameters; `thrown` when a misplaced name raised in this frame
    fn pushConstructorArgs(self: *VM, class_name: []const u8, arr: *PhpArray) RuntimeError!PushedArgs {
        const entries = arr.entries.items;
        const has_named = for (entries) |entry| {
            if (entry.key == .string) break true;
        } else false;
        if (!has_named) {
            try self.pushArgEntries(arr, entries);
            return .{ .count = entries.len };
        }
        if (!self.classes.contains(class_name)) try self.tryAutoload(class_name);
        const ctn = (self.resolveMethod(class_name, "__construct") catch null) orelse {
            try self.pushArgEntries(arr, entries);
            return .{ .count = entries.len };
        };
        if (self.functions.get(ctn)) |func| {
            var resolved_buf: [256]Value = undefined;
            var sources_buf: [256]RefSource = undefined;
            var assigned_buf: [256]bool = undefined;
            const slots = try self.argSlots(&resolved_buf, &sources_buf, &assigned_buf, func.params.len + entries.len);
            defer self.freeArgSlots(slots, &resolved_buf);
            const resolved = slots.values;
            const resolved_sources = slots.sources;
            var pos: usize = 0;
            for (entries) |entry| {
                if (entry.key == .string) {
                    const matched = for (func.params, 0..) |p, pi| {
                        const pname = if (p.len > 0 and p[0] == '$') p[1..] else p;
                        if (std.mem.eql(u8, pname, entry.key.string.bytes()) or std.mem.eql(u8, p, entry.key.string.bytes())) {
                            resolved[pi] = entry.value;
                            resolved_sources[pi] = self.argArraySource(arr, entry.key);
                            if (pi >= pos) pos = pi + 1;
                            break true;
                        }
                    } else false;
                    if (!matched and !func.is_variadic) {
                        const msg = try std.fmt.allocPrint(self.allocator, "Unknown named parameter ${s}", .{entry.key.string.bytes()});
                        defer self.allocator.free(msg);
                        if (try self.throwBuiltinException("Error", msg)) return .thrown;
                        return error.RuntimeError;
                    }
                } else {
                    resolved[pos] = entry.value;
                    resolved_sources[pos] = self.argArraySource(arr, entry.key);
                    pos += 1;
                }
            }
            const count = @max(pos, func.required_params);
            for (0..count) |i| {
                if (resolved[i] == .null and i < func.defaults.len) {
                    resolved[i] = try self.resolveParamDefault(func, i);
                }
            }
            for (0..count) |i| {
                self.push(resolved[i]);
                self.setArgSource(self.sp - 1, resolved_sources[i]);
            }
            return .{ .count = count };
        }
        if (native_params.get(ctn)) |signature| {
            const params = signature.params;
            var resolved: [256]Value = undefined;
            var resolved_sources: [256]RefSource = undefined;
            const placed = try self.placeNativeNamedArgs(arr, params, &resolved, &resolved_sources, natives_mod.acceptsNamedExtras(ctn));
            if (placed.problem) |problem| {
                if (try self.throwNamedArgProblem(ctn, params, problem)) return .thrown;
                return error.RuntimeError;
            }
            for (0..placed.count) |i| {
                self.push(resolved[i]);
                self.setArgSource(self.sp - 1, resolved_sources[i]);
            }
            return .{ .count = placed.count };
        }
        try self.pushArgEntries(arr, entries);
        return .{ .count = entries.len };
    }

    // an operator on an instance of a native class that overloads it
    fn objectBinop(self: *VM, op: NativeBinop, a: Value, b: Value) RuntimeError!?Value {
        if (a != .object and b != .object) return null;
        const hook = blk: {
            if (a == .object) if (self.nativeBinopHook(a.object.class_name)) |h| break :blk h;
            if (b == .object) if (self.nativeBinopHook(b.object.class_name)) |h| break :blk h;
            return null;
        };
        var ctx = self.makeContext(null);
        return hook(&ctx, op, a, b);
    }

    // an opcode that ran a helper which threw: true when the exception reached
    // a catch block in this run, whether the thrower dispatched it in place or
    // left it pending, so the handler resumes there
    fn resumeAfterThrow(self: *VM, base_frame: usize, handlers_before: usize) bool {
        if (self.handler_count < handlers_before) return true;
        return self.pending_exception != null and self.dispatchPendingException(base_frame);
    }

    // php's pow_function for pow(): an object's do_operation, the operand
    // checks of **, and safe_pow's deprecation; errors are left pending
    pub fn powFunction(self: *VM, a: Value, b: Value) RuntimeError!Value {
        if (try self.objectBinop(.pow, a, b)) |r| return r;
        if (!isArithOperand(a) or !isArithOperand(b)) {
            const msg = try std.fmt.allocPrint(self.allocator, "Unsupported operand types: {s} ** {s}", .{ Value.typeName(a), Value.typeName(b) });
            defer self.allocator.free(msg);
            try self.setPendingException("TypeError", msg);
            return error.RuntimeError;
        }
        if (a == .string and isPartialNumericString(a.string.bytes())) try self.emitNonNumericWarning();
        if (b == .string and isPartialNumericString(b.string.bytes())) try self.emitNonNumericWarning();
        if (Value.powerOfZeroBase(a, b)) try self.raiseError(E_DEPRECATED, "Power of base 0 and negative exponent is deprecated");
        return Value.power(a, b);
    }

    pub fn checkArithOperands(self: *VM, a: Value, b: Value, comptime op: []const u8) RuntimeError!bool {
        if (isArithOperand(a) and isArithOperand(b)) {
            if (a == .string and isPartialNumericString(a.string.bytes())) self.emitNonNumericWarning() catch return self.resumeRaised();
            if (b == .string and isPartialNumericString(b.string.bytes())) self.emitNonNumericWarning() catch return self.resumeRaised();
            return false;
        }
        const tn_a = Value.typeName(a);
        const tn_b = Value.typeName(b);
        const msg = try std.fmt.allocPrint(self.allocator, "Unsupported operand types: {s} " ++ op ++ " {s}", .{ tn_a, tn_b });
        defer self.allocator.free(msg);
        if (try self.throwBuiltinException("TypeError", msg)) return true;
        return error.RuntimeError;
    }

    fn bitwiseStrings(self: *VM, a: []const u8, b: []const u8, comptime op: enum { and_op, or_op, xor_op }) !Value.String {
        // PHP byte-wise op on two strings: AND and XOR stop at the shorter
        // string, OR pads it with NUL bytes
        const len = switch (op) {
            .and_op, .xor_op => @min(a.len, b.len),
            .or_op => @max(a.len, b.len),
        };
        const out = try self.stringAllocator().alloc(u8, len);
        for (0..len) |i| {
            const ca: u8 = if (i < a.len) a[i] else 0;
            const cb: u8 = if (i < b.len) b[i] else 0;
            out[i] = switch (op) {
                .and_op => ca & cb,
                .or_op => ca | cb,
                .xor_op => ca ^ cb,
            };
        }
        return Value.String.adopt(self.stringAllocator(), out);
    }

    fn isArithOperand(v: Value) bool {
        return switch (v) {
            .int, .float, .bool, .null => true,
            // PHP throws TypeError only for strings with no leading-numeric
            // prefix. '5abc' / '  5  ' / '0xFF' all pass (PHP emits a warning
            // and uses the numeric prefix, which is 0 for '0xFF'). truly
            // alphabetic strings like 'abc' do not pass
            .string => |s| stringHasLeadingNumericish(s.bytes()),
            else => false,
        };
    }

    fn isPartialNumericString(s: []const u8) bool {
        // string with a leading numeric prefix followed by non-numeric garbage
        // (PHP emits "A non-numeric value encountered" when arithmetic uses
        // such a string). pure-numeric and pure-non-numeric strings don't qualify
        var i: usize = 0;
        while (i < s.len and (s[i] == ' ' or s[i] == '\t' or s[i] == '\n' or s[i] == '\r' or s[i] == '\x0b' or s[i] == '\x0c')) i += 1;
        if (i >= s.len) return false;
        if (s[i] == '+' or s[i] == '-') i += 1;
        if (i >= s.len) return false;
        var saw_digit = false;
        while (i < s.len and s[i] >= '0' and s[i] <= '9') : (i += 1) saw_digit = true;
        if (i < s.len and s[i] == '.') {
            i += 1;
            while (i < s.len and s[i] >= '0' and s[i] <= '9') : (i += 1) saw_digit = true;
        }
        if (!saw_digit) return false;
        if (i < s.len and (s[i] == 'e' or s[i] == 'E')) {
            const save = i;
            i += 1;
            if (i < s.len and (s[i] == '+' or s[i] == '-')) i += 1;
            const exp_start = i;
            while (i < s.len and s[i] >= '0' and s[i] <= '9') : (i += 1) {}
            if (i == exp_start) i = save; // no exponent digits, roll back so 'e' is trailing garbage
        }
        // skip trailing whitespace (PHP treats "  5  " as fully numeric)
        while (i < s.len and (s[i] == ' ' or s[i] == '\t' or s[i] == '\n' or s[i] == '\r' or s[i] == '\x0b' or s[i] == '\x0c')) i += 1;
        return i < s.len;
    }

    fn emitNonNumericWarning(self: *VM) RuntimeError!void {
        return self.emitWarning("A non-numeric value encountered");
    }

    pub fn emitUndefinedKeyWarning(self: *VM, key: PhpArray.Key) RuntimeError!void {
        const msg = switch (key) {
            .int => |n| try std.fmt.allocPrint(self.allocator, "Undefined array key {d}", .{n}),
            .string => |s| try std.fmt.allocPrint(self.allocator, "Undefined array key \"{s}\"", .{s.bytes()}),
        };
        defer self.allocator.free(msg);
        // ZPHP_DBG_UKW=1 dumps the frame stack on each warning - invaluable
        // for tracking down false-positives where zphp warns but PHP doesn't
        if (platform.getenv("ZPHP_DBG_UKW") != null) {
            std.debug.print("[UKW] {s} frames:\n", .{msg});
            var fi: usize = self.frame_count;
            while (fi > 0) {
                fi -= 1;
                const f = &self.frames[fi];
                const name: []const u8 = if (f.func) |fd| fd.name else "<top>";
                var line_raw: u32 = 0;
                if (f.ip > 0 and f.ip - 1 < f.chunk.lines.items.len) line_raw = f.chunk.lines.items[f.ip - 1];
                std.debug.print("  #{d} {s} ip={d} src_off={d}\n", .{ fi, name, f.ip, line_raw });
            }
        }
        try self.emitWarning(msg);
    }

    const IncludeKind = enum(u8) {
        require,
        require_once,
        include,
        include_once,

        fn once(kind: IncludeKind) bool {
            return kind == .require_once or kind == .include_once;
        }

        fn required(kind: IncludeKind) bool {
            return kind == .require or kind == .require_once;
        }
    };

    // the canonical path an include names, or null once php's diagnostics
    // for a file it cannot find have been raised
    fn includeTarget(self: *VM, kind: IncludeKind, value: Value) RuntimeError!?[]const u8 {
        var buf: std.ArrayListUnmanaged(u8) = .empty;
        defer buf.deinit(self.allocator);
        const path = switch (value) {
            .string => |s| s.bytes(),
            .object => |o| try self.objectToString(o),
            else => blk: {
                try value.format(&buf, self.allocator);
                break :blk buf.items;
            },
        };
        if (path.len == 0) {
            try self.setPendingException("ValueError", "Path must not be empty");
            return error.RuntimeError;
        }
        if (try includes.resolve(self, path)) |found| {
            // the plain files opener checks open_basedir on the resolved path
            if (open_basedir.setting(self) != null and !includes.hasScheme(found) and !try open_basedir.allows(self, @tagName(kind), found)) {
                try self.includeNotOpenedAs(kind, path, found, "Operation not permitted");
                return null;
            }
            return found;
        }
        try self.includeNotOpened(kind, path, "No such file or directory");
        return null;
    }

    // an include warns and evaluates to false; a require throws
    fn includeNotOpened(self: *VM, kind: IncludeKind, path: []const u8, reason: []const u8) RuntimeError!void {
        return self.includeNotOpenedAs(kind, path, path, reason);
    }

    // the include's own failure after the stream reported why it failed
    fn includeFailedOpening(self: *VM, kind: IncludeKind, path: []const u8) RuntimeError!void {
        if (kind.required()) {
            const msg = try std.fmt.allocPrint(self.allocator, "Failed opening required '{s}' (include_path='{s}')", .{ path, includes.includePath(self) });
            defer self.allocator.free(msg);
            try self.setPendingException("Error", msg);
            return error.RuntimeError;
        }
        const msg = try std.fmt.allocPrint(self.allocator, "{s}(): Failed opening '{s}' for inclusion (include_path='{s}')", .{ @tagName(kind), path, includes.includePath(self) });
        defer self.allocator.free(msg);
        try self.emitWarning(msg);
    }

    // `opened` is the path the open failed on, which the stream warning names
    fn includeNotOpenedAs(self: *VM, kind: IncludeKind, path: []const u8, opened: []const u8, reason: []const u8) RuntimeError!void {
        const nul = std.mem.indexOfScalar(u8, path, 0);
        const shown = path[0 .. nul orelse path.len];
        if (nul == null) {
            const msg = try std.fmt.allocPrint(self.allocator, "{s}({s}): Failed to open stream: {s}", .{ @tagName(kind), opened, reason });
            defer self.allocator.free(msg);
            try self.emitWarning(msg);
        }
        if (kind.required()) {
            const msg = try std.fmt.allocPrint(self.allocator, "Failed opening required '{s}' (include_path='{s}')", .{ shown, includes.includePath(self) });
            defer self.allocator.free(msg);
            try self.setPendingException("Error", msg);
            return error.RuntimeError;
        }
        const msg = try std.fmt.allocPrint(self.allocator, "{s}(): Failed opening '{s}' for inclusion (include_path='{s}')", .{ @tagName(kind), shown, includes.includePath(self) });
        defer self.allocator.free(msg);
        try self.emitWarning(msg);
    }

    pub const E_WARNING: i64 = 2;
    pub const E_USER_DEPRECATED: i64 = 16384;
    pub const E_DEPRECATED: i64 = 8192;

    // defines a global constant (`const`, define()); one already defined
    // keeps its value, with php's warning. takes a reference to the value
    // only when it defines
    pub fn defineConstant(self: *VM, name: []const u8, value: Value) RuntimeError!bool {
        if (self.php_constants.contains(name)) {
            const msg = try std.fmt.allocPrint(self.allocator, "Constant {s} already defined, this will be an error in PHP 9", .{name});
            defer self.allocator.free(msg);
            try self.emitWarning(msg);
            return false;
        }
        retainValue(value);
        try self.php_constants.put(self.allocator, name, value);
        return true;
    }

    pub fn emitWarning(self: *VM, msg: []const u8) RuntimeError!void {
        return self.raiseError(E_WARNING, msg);
    }

    // a php diagnostic. the user handler sees it first unless its mask
    // excludes the level; otherwise, or when the handler returns false, it is
    // recorded for error_get_last and printed if error_reporting allows. an
    // exception thrown by the handler is left pending as error.RuntimeError
    // the text a #[\Deprecated] among attrs adds after "is deprecated"
    // (" since 2.0, use X", or ""), null without the attribute. kept for the
    // vm's lifetime
    fn deprecationOf(self: *VM, attrs: []const AttributeDef) RuntimeError!?[]const u8 {
        for (attrs) |attr| {
            const name = if (attr.name.len > 0 and attr.name[0] == '\\') attr.name[1..] else attr.name;
            if (!std.ascii.eqlIgnoreCase(name, "Deprecated")) continue;
            var message: []const u8 = "";
            var since: []const u8 = "";
            for (attr.args) |stored| {
                // anything but a plain string is evaluated when the
                // deprecation fires
                const plain = stored == .null or (stored == .string and (stored.string.len == 0 or stored.string.bytes()[0] != 0));
                if (!plain) return bytecode.deferred_deprecation;
            }
            for (attr.args, 0..) |arg, i| {
                const arg_name: ?[]const u8 = if (i < attr.arg_names.len) attr.arg_names[i] else null;
                if (arg != .string) continue;
                const is_since = if (arg_name) |n| std.mem.eql(u8, n, "since") else i == 1;
                if (is_since) since = arg.string.bytes() else message = arg.string.bytes();
            }
            const text = try std.fmt.allocPrint(self.allocator, "{s}{s}{s}{s}", .{ if (since.len > 0) " since " else "", since, if (message.len > 0) ", " else "", message });
            try self.strings.append(self.allocator, text);
            return text;
        }
        return null;
    }

    // what a deprecation adds after "is deprecated": the text known at
    // compile time, or, for deferred_deprecation, the #[\Deprecated] among
    // attrs built now as php does, its message and since read back. caller
    // frees
    fn deprecationText(self: *VM, suffix: []const u8, attrs: ?[]const AttributeDef, scope: []const u8) RuntimeError![]u8 {
        if (!std.mem.eql(u8, suffix, bytecode.deferred_deprecation)) return self.allocator.dupe(u8, suffix);
        const attr = for (attrs orelse &.{}) |a| {
            const name = if (a.name.len > 0 and a.name[0] == '\\') a.name[1..] else a.name;
            if (std.ascii.eqlIgnoreCase(name, "Deprecated")) break a;
        } else return self.allocator.dupe(u8, "");
        var placed: [2]Value = .{ .null, .null };
        for (attr.args, 0..) |stored, i| {
            const arg_name: ?[]const u8 = if (i < attr.arg_names.len) attr.arg_names[i] else null;
            const slot: usize = if (arg_name) |n| (if (std.mem.eql(u8, n, "message")) 0 else if (std.mem.eql(u8, n, "since")) 1 else {
                const msg = try std.fmt.allocPrint(self.allocator, "Unknown named parameter ${s}", .{n});
                defer self.allocator.free(msg);
                try self.setPendingException("Error", msg);
                return error.RuntimeError;
            }) else i;
            if (slot >= placed.len) continue;
            placed[slot] = try self.attributeArgumentValue(stored, scope);
        }
        const obj = try self.allocObject(.{ .class_name = try self.stableClassName("Deprecated") });
        defer self.releaseValue(.{ .object = obj });
        try self.initObjectProperties(obj, "Deprecated");
        _ = try self.callMethod(obj, "__construct", &placed);
        const message = obj.get("message");
        const since = obj.get("since");
        const m = if (message == .string) message.string.bytes() else "";
        const s = if (since == .string) since.string.bytes() else "";
        return std.fmt.allocPrint(self.allocator, "{s}{s}{s}{s}", .{ if (s.len > 0) " since " else "", s, if (m.len > 0) ", " else "", m });
    }

    // the attributes declared on a compiled function or method, and the
    // class its expressions are evaluated in
    fn functionAttributesOf(self: *VM, func: *const ObjFunction) struct { attrs: ?[]const AttributeDef, scope: []const u8 } {
        if (self.function_attributes.get(func.name)) |attrs| return .{ .attrs = attrs, .scope = "" };
        // a trait method's attributes stay with the trait
        const name = if (func.trait_origin.len > 0) func.trait_origin else func.name;
        const sep = std.mem.indexOf(u8, name, "::") orelse return .{ .attrs = null, .scope = "" };
        const class = name[0..sep];
        const cls = self.classes.get(class) orelse return .{ .attrs = null, .scope = class };
        return .{ .attrs = cls.method_attributes.get(name[sep + 2 ..]), .scope = class };
    }

    // php's ZEND_INIT_PARENT_PROPERTY_HOOK_CALL: the parent's hook for the
    // property when it has one, else the parent property's own storage
    // through the get_prop/set_prop the compiler put after this op (the
    // running hook's guard makes it reach the backing value)
    fn parentHookCall(self: *VM, prop: []const u8, is_set: bool, argc: u8, skip: u16) RuntimeError!void {
        const kind: []const u8 = if (is_set) "set" else "get";
        const scope = self.currentDefiningClass() orelse {
            try self.setPendingException("Error", "Cannot use \"parent\" when no class scope is active");
            return error.RuntimeError;
        };
        const parent = (if (self.classes.get(scope)) |c| c.parent else null) orelse {
            try self.setPendingException("Error", "Cannot use \"parent\" when current class scope has no parent");
            return error.RuntimeError;
        };
        const decl = self.propertyDeclaration(parent, prop);
        if (!decl.declared) {
            const msg = try std.fmt.allocPrint(self.allocator, "Undefined property {s}::${s}", .{ parent, prop });
            defer self.allocator.free(msg);
            try self.setPendingException("Error", msg);
            return error.RuntimeError;
        }
        if (decl.visibility == .private) {
            const msg = try std.fmt.allocPrint(self.allocator, "Cannot access private property {s}::${s}", .{ decl.defining_class, prop });
            defer self.allocator.free(msg);
            try self.setPendingException("Error", msg);
            return error.RuntimeError;
        }
        const this = self.getLocalByName("$this");
        if (this != .object) {
            try self.setPendingException("Error", "Using $this when not in object context");
            return error.RuntimeError;
        }
        const hook = try self.propHookName(prop, if (is_set) .set else .get);
        const parent_def = self.classes.getPtr(parent) orelse return error.RuntimeError;
        if (self.resolvePropertyHook(parent_def, hook)) |found| if (!found.info.is_abstract) {
            const registered = try std.fmt.allocPrint(self.allocator, "{s}::{s}", .{ found.declaring, hook });
            defer self.allocator.free(registered);
            const args = try self.allocator.dupe(Value, self.stack[self.sp - argc .. self.sp]);
            defer self.allocator.free(args);
            const result = try self.callMethodAs(this.object, hook, try self.internName(registered), args);
            self.dropN(argc);
            self.push(result);
            self.currentFrame().ip += skip;
            return;
        };
        // the implicit hook is an internal function and checks its arguments
        const expected: u8 = if (is_set) 1 else 0;
        if (argc != expected) {
            const msg = try std.fmt.allocPrint(self.allocator, "{s}::${s}::{s}() expects exactly {d} argument{s}, {d} given", .{ decl.defining_class, prop, kind, expected, if (expected == 1) "" else "s", argc });
            defer self.allocator.free(msg);
            try self.setPendingException("ArgumentCountError", msg);
            return error.RuntimeError;
        }
        if (is_set) {
            const value = self.pop();
            stackRetain(this);
            self.push(this);
            self.push(value);
        } else {
            stackRetain(this);
            self.push(this);
        }
    }

    // an int default of a property typed float (and not int) is a float, as
    // php converts it when it declares the property
    // a property default as the class stores it: an int default of a float
    // property becomes a float, and a default evaluated at run time must
    // fit the type strictly (zend_update_class_constants)
    fn widenIntDefault(self: *VM, val: Value, type_str: []const u8, class_name: []const u8, prop_name: []const u8) RuntimeError!Value {
        if (type_str.len == 0) return val;
        if (try self.propertyTypeAccepts(val, type_str, class_name, true)) |accepted| return accepted;
        const msg = try std.fmt.allocPrint(self.allocator, "Cannot assign {s} to property {s}::${s} of type {s}", .{ valueTypeName(val), class_name, prop_name, try self.propertyTypeText(type_str, class_name) });
        defer self.allocator.free(msg);
        try self.setPendingException("TypeError", msg);
        return error.RuntimeError;
    }

    fn warnDeprecatedTraitUse(self: *VM, trait: []const u8, user: []const u8) RuntimeError!void {
        const declared = self.traits.getKey(trait) orelse return;
        const raw = self.deprecated_traits.get(declared) orelse return;
        const suffix = try self.deprecationText(raw, if (self.classes.get(declared)) |c| c.attributes.items else null, declared);
        defer self.allocator.free(suffix);
        const msg = try std.fmt.allocPrint(self.allocator, "Trait {s} used by {s} is deprecated{s}", .{ declared, user, suffix });
        defer self.allocator.free(msg);
        try self.raiseError(E_USER_DEPRECATED, msg);
    }

    // #[\Deprecated] and #[\NoDiscard] on a generator function, at its call
    fn checkGeneratorCall(self: *VM, func: *const ObjFunction) RuntimeError!void {
        if (func.deprecated == null and func.no_discard == null) return;
        const is_method = std.mem.indexOf(u8, func.name, "::") != null;
        const shown = if (func.display_name.len > 0) func.display_name else func.name;
        if (func.deprecated) |raw| {
            const declared = self.functionAttributesOf(func);
            const suffix = try self.deprecationText(raw, declared.attrs, declared.scope);
            defer self.allocator.free(suffix);
            const msg = try std.fmt.allocPrint(self.allocator, "{s} {s}() is deprecated{s}", .{ if (is_method) "Method" else "Function", shown, suffix });
            defer self.allocator.free(msg);
            try self.raiseError(E_USER_DEPRECATED, msg);
        }
        if (func.no_discard) |reason| {
            if (self.frame_count == 0 or self.calledFromNative()) return;
            const frame = self.currentFrame();
            const code = frame.chunk.code.items;
            if (frame.ip >= code.len or code[frame.ip] != @intFromEnum(OpCode.pop_boundary)) return;
            const msg = try std.fmt.allocPrint(self.allocator, "The return value of {s} {s}() should either be used or intentionally ignored by casting it as (void){s}{s}", .{ if (is_method) "method" else "function", shown, if (reason.len > 0) ", " else "", reason });
            defer self.allocator.free(msg);
            try self.raiseError(E_WARNING, msg);
        }
    }

    // warns, as php does on each read, when the global constant is #[\Deprecated]
    pub fn warnDeprecatedConstant(self: *VM, name: []const u8) RuntimeError!void {
        if (deprecations.constants.get(name)) |suffix| {
            const msg = try std.fmt.allocPrint(self.allocator, "Constant {s} is deprecated{s}", .{ name, suffix });
            defer self.allocator.free(msg);
            return self.raiseError(E_DEPRECATED, msg);
        }
        // ext/hash registers these at startup, outside its stub
        if (name.len > 6 and name[0] == 'M' and @import("../stdlib/hash.zig").isMhashConstant(name)) {
            const msg = try std.fmt.allocPrint(self.allocator, "Constant {s} is deprecated since 8.5, as the mhash*() functions were deprecated", .{name});
            defer self.allocator.free(msg);
            return self.raiseError(E_DEPRECATED, msg);
        }
        if (!self.has_deprecated_constants) return;
        const raw = self.deprecated_globals.get(name) orelse return;
        if (self.describing_deprecated) |d| if (d.class.len == 0 and std.mem.eql(u8, d.name, name)) return;
        const attrs = if (self.constant_attributes.get(name)) |key| self.function_attributes.get(key) else null;
        const outer = self.describing_deprecated;
        self.describing_deprecated = .{ .class = "", .name = name };
        const suffix = self.deprecationText(raw, attrs, "") catch |err| {
            self.describing_deprecated = outer;
            return err;
        };
        self.describing_deprecated = outer;
        defer self.allocator.free(suffix);
        const msg = try std.fmt.allocPrint(self.allocator, "Constant {s} is deprecated{s}", .{ name, suffix });
        defer self.allocator.free(msg);
        try self.raiseError(E_USER_DEPRECATED, msg);
    }

    // warns, as php does on each read, when class_name::const_name is a
    // #[\Deprecated] constant or enum case. returns whether it is one
    // warns, as php does on each read, when class_name::const_name is a
    // #[\Deprecated] constant or enum case, naming the class or interface that
    // declares it. returns whether it is one
    pub fn warnDeprecatedClassConstant(self: *VM, class_name: []const u8, const_name: []const u8) RuntimeError!bool {
        const found = self.constantDeprecation(class_name, const_name, 0) orelse return false;
        const kind: []const u8 = if (found.is_case) "Enum case" else "Constant";
        if (self.describing_deprecated) |d| if (std.mem.eql(u8, d.class, found.owner) and std.mem.eql(u8, d.name, const_name)) return true;
        const attrs = if (self.classes.get(found.owner)) |c| c.constant_attributes.get(const_name) else null;
        const outer = self.describing_deprecated;
        self.describing_deprecated = .{ .class = found.owner, .name = const_name };
        const suffix = self.deprecationText(found.suffix, attrs, found.owner) catch |err| {
            self.describing_deprecated = outer;
            return err;
        };
        self.describing_deprecated = outer;
        defer self.allocator.free(suffix);
        const msg = try std.fmt.allocPrint(self.allocator, "{s} {s}::{s} is deprecated{s}", .{ kind, found.owner, const_name, suffix });
        defer self.allocator.free(msg);
        try self.raiseError(if (found.internal) E_DEPRECATED else E_USER_DEPRECATED, msg);
        return true;
    }

    const ConstantDeprecation = struct { owner: []const u8, suffix: []const u8, internal: bool, is_case: bool };

    // the class, parent or interface whose declaration of the constant is
    // deprecated: php's for an internal one, the attribute's for a user one
    fn constantDeprecation(self: *VM, class_name: []const u8, const_name: []const u8, depth: u8) ?ConstantDeprecation {
        if (depth > 32) return null;
        var current: ?[]const u8 = class_name;
        while (current) |name| {
            const entry = self.classes.getEntry(name) orelse return null;
            const cls = entry.value_ptr;
            if (!cls.constants.contains(const_name)) {
                // inherited from an interface or parent the lookup reached
            } else if (cls.is_internal) {
                var buf: [256]u8 = undefined;
                if (std.fmt.bufPrint(&buf, "{s}::{s}", .{ entry.key_ptr.*, const_name })) |key| {
                    if (deprecations.class_constants.get(key)) |suffix| return .{ .owner = entry.key_ptr.*, .suffix = suffix, .internal = true, .is_case = false };
                } else |_| {}
            } else if (self.has_deprecated_constants) {
                if (cls.deprecated_constants.get(const_name)) |suffix| {
                    var is_case = false;
                    if (cls.is_enum) for (cls.case_order.items) |case_name| {
                        if (std.mem.eql(u8, case_name, const_name)) is_case = true;
                    };
                    return .{ .owner = entry.key_ptr.*, .suffix = suffix, .internal = false, .is_case = is_case };
                }
            }
            for (cls.interfaces.items) |iface| {
                if (self.constantDeprecation(iface, const_name, depth + 1)) |found| return found;
            }
            current = cls.parent;
        }
        return null;
    }

    pub fn raiseError(self: *VM, level: i64, msg: []const u8) RuntimeError!void {
        return self.raiseErrorAt(level, msg, self.currentSourcePosition());
    }

    // raiseError at a given source position, for a diagnostic about a frame
    // other than the running one
    // whether interfaces named in a declaration are, or extend, `target`
    fn listedInterfacesInclude(self: *VM, names: []const []const u8, target: []const u8) bool {
        for (names) |name| {
            if (std.ascii.eqlIgnoreCase(name, target)) return true;
            const iface = self.interfaces.getPtr(name) orelse continue;
            if (iface.parent) |parent| if (self.listedInterfacesInclude(&.{parent}, target)) return true;
            if (self.listedInterfacesInclude(iface.parents.items, target)) return true;
        }
        return false;
    }

    // whether a class being declared implements `target` through its own
    // interface list or its parents'
    fn classImplements(self: *VM, def: *const ClassDef, target: []const u8) bool {
        if (self.listedInterfacesInclude(def.interfaces.items, target)) return true;
        var parent = def.parent;
        while (parent) |name| {
            const pdef = self.classes.getPtr(name) orelse return false;
            if (self.listedInterfacesInclude(pdef.interfaces.items, target)) return true;
            parent = pdef.parent;
        }
        return false;
    }

    // php's do_bind_function_error for a free function name already taken:
    // a script's function is named with where it was declared. null when
    // the name is free
    fn functionRedeclarationMessage(self: *VM, name: []const u8) RuntimeError!?[]u8 {
        if (!isFreeFunctionName(name)) return null;
        var buf: [256]u8 = undefined;
        const lower = if (name.len <= buf.len) std.ascii.lowerString(&buf, name) else return null;
        if (self.ic.?.fn_lower.get(lower)) |existing_name| {
            if (self.functions.get(existing_name)) |existing| if (existing.file_path.len > 0) {
                return try std.fmt.allocPrint(self.allocator, "Cannot redeclare function {s}() (previously declared in {s}:{d})", .{ name, existing.file_path, existing.start_line });
            };
            return try std.fmt.allocPrint(self.allocator, "Cannot redeclare function {s}()", .{name});
        }
        if (self.nativeNamed(lower) != null) return try std.fmt.allocPrint(self.allocator, "Cannot redeclare function {s}()", .{name});
        return null;
    }

    // php's zend_class_redeclaration_error for a name already declared: the
    // class, interface, trait or enum that has it, and where a script
    // declared it. null when the name is free
    pub fn redeclarationMessage(self: *VM, name: []const u8) RuntimeError!?[]u8 {
        return self.redeclarationMessageAs(name, null);
    }

    // zend_class_redeclaration_error_ex: described as `existing`, but named
    // `shown` (class_alias reports the alias with the aliased class's kind
    // and declaration)
    pub fn redeclarationMessageAs(self: *VM, existing: []const u8, shown: ?[]const u8) RuntimeError!?[]u8 {
        const name = existing;
        var kind: []const u8 = "class";
        var declared: []const u8 = name;
        var file: []const u8 = "";
        var line: u32 = 0;
        if (self.traits.getKey(name)) |key| {
            kind = "trait";
            declared = key;
            if (self.ic.?.trait_sites.get(key)) |site| {
                file = site.file;
                line = site.start_line;
            }
        } else if (self.classes.getPtr(name)) |found| {
            const def = found;
            declared = def.name;
            if (self.interfaces.contains(def.name)) kind = "interface" else if (def.is_enum) kind = "enum";
            if (!def.is_internal) {
                file = def.file_path;
                line = def.start_line;
            }
        } else if (self.interfaces.getKey(name)) |key| {
            kind = "interface";
            declared = key;
        } else return null;
        if (shown) |s| declared = s;
        if (file.len == 0) return try std.fmt.allocPrint(self.allocator, "Cannot redeclare {s} {s}", .{ kind, declared });
        return try std.fmt.allocPrint(self.allocator, "Cannot redeclare {s} {s} (previously declared in {s}:{d})", .{ kind, declared, file, line });
    }

    fn refuseRedeclaration(self: *VM, name: []const u8) RuntimeError!void {
        const msg = try self.redeclarationMessage(name) orelse return;
        defer self.allocator.free(msg);
        return self.raiseFatal(msg);
    }

    // `global $name`: the variable becomes a reference to the global of that
    // name, created when it doesn't exist. `name` must outlive the frame
    fn bindGlobalVariable(self: *VM, name: []const u8) RuntimeError!void {
        const cell = try self.globalVariableCell(name);
        // bind the local name to the cell so set_var/get_var on this
        // frame routes through ref_slots and stays in sync across
        // recursive calls
        try self.bindRefSlot(&self.currentFrame().ref_slots, name, cell);
        // vars/locals are one owning mirror, even for a cell.
        retainValue(cell.*);
        try self.setVariableByName(self.currentFrame(), name, cell.*);
    }

    // the cell a global variable lives in, made shared with the top frame
    // (so top-level reads of $name pick up writes through it)
    fn globalVariableCell(self: *VM, name: []const u8) RuntimeError!*Value {
        // resolve or allocate the shared cell. picks up the current
        // value from the top-frame's view (locals + ref_slots + vars
        // + constants) so this is the first read after a value was
        // set there
        var cell = self.globals_cells.get(name);
        if (isSuperglobal(name) and cell == null) cell = try self.superglobalCell(name);
        if (cell == null) {
            if (self.frames[0].ref_slots.get(name)) |top_cell| {
                try self.bindRefSlot(&self.globals_cells, try self.internName(name), top_cell);
                cell = top_cell;
            }
        }
        if (cell == null) {
            const initial: Value = blk: {
                // a file required at global scope IS the global
                // scope, so scan every global-scope frame on the
                // stack (func == null: the top script + nested
                // require-include frames), innermost first. this
                // lets `global $x` see a var a still-executing
                // required file set at its top level
                var fi: usize = self.frame_count;
                while (fi > 0) {
                    fi -= 1;
                    const gf = &self.frames[fi];
                    if (gf.func != null) continue;
                    if (gf.ref_slots.get(name)) |c| break :blk c.*;
                    for (gf.slot_names, 0..) |sn, i| {
                        if (std.mem.eql(u8, sn, name) and i < gf.locals.len) {
                            const v = gf.locals[i];
                            if (v != .null and v != .undef) break :blk v;
                        }
                    }
                    if (gf.vars.get(name)) |v| {
                        if (v != .null) break :blk v;
                    }
                }
                if (self.frames[0].ref_slots.get(name)) |c| break :blk c.*;
                if (self.frames[0].vars.get(name)) |v| break :blk v;
                if (self.php_constants.get(name)) |v| break :blk v;
                break :blk .null;
            };
            const c = try self.newRefCell();
            self.setCell(c, initial);
            try self.bindRefSlot(&self.globals_cells, try self.internName(name), c);
            cell = c;
        }
        if (self.frame_count > 1) {
            try self.bindRefSlot(&self.frames[0].ref_slots, name, cell.?);
        }
        return cell.?;
    }

    // the reference cell a static property is bound through, made on first
    // use; raises what php raises for an indirect write the property refuses
    fn staticPropRefCell(self: *VM, class_name: []const u8, prop_name: []const u8) RuntimeError!*Value {
        try self.resolveStaticDefaults(class_name);
        _ = try self.staticPropTarget(class_name, prop_name, .indirect);
        return blk: {
            if (self.ref_index) |ri| {
                if (ri.prop_rev.get(.{ .object = null, .class_name = class_name, .prop_name = prop_name })) |cells| {
                    if (cells.items.len > 0) {
                        const existing = cells.items[0];
                        if (existing.* == .array and existing.array.refcount > 1) {
                            const separated: Value = .{ .array = try self.shallowCloneCow(existing.array) };
                            self.setCell(existing, separated);
                            try self.propagateCellWrite(existing, separated);
                        }
                        break :blk existing;
                    }
                }
            }
            var value = self.getStaticProp(class_name, prop_name) orelse .null;
            if (value == .array and value.array.refcount > 1) {
                value = .{ .array = try self.shallowCloneCow(value.array) };
                if (self.getStaticPropPtr(class_name, prop_name)) |slot| {
                    VM.retainValue(value);
                    self.releaseValue(slot.*);
                    slot.* = value;
                }
            }
            const fresh = try self.newRefCell();
            self.setCell(fresh, value);
            break :blk fresh;
        };
    }

    // a class constant's expression evaluated on its first access, as php's
    // zval_update_constant_ex does: the value is type checked and kept. a
    // constant read again while another constant's expression evaluates it
    // is php's self-reference error. on failure the error is pending and the
    // constant stays unevaluated
    pub fn evaluateClassConstant(self: *VM, class_name: []const u8, const_name: []const u8) RuntimeError!Value {
        const declared = self.declaredClassName(class_name);
        const written = if (self.class_const_written.len > 0) self.class_const_written else declared;
        self.class_const_written = "";
        const nested = self.constant_eval_depth > 0;
        if (nested) {
            for (self.constants_visited.items) |v| {
                if (std.mem.eql(u8, v[0], declared) and std.mem.eql(u8, v[1], const_name)) {
                    const msg = try std.fmt.allocPrint(self.allocator, "Cannot declare self-referencing constant {s}::{s}", .{ written, const_name });
                    defer self.allocator.free(msg);
                    try self.setPendingException("Error", msg);
                    return error.RuntimeError;
                }
            }
            try self.constants_visited.append(self.allocator, .{ declared, const_name });
        }
        defer if (nested) {
            _ = self.constants_visited.pop();
        };
        self.constant_eval_depth += 1;
        defer self.constant_eval_depth -= 1;
        const name = try bytecode.constInitializerName(self.allocator, declared, const_name);
        defer self.allocator.free(name);
        const floor = self.handler_floor;
        self.handler_floor = self.handler_count;
        defer self.handler_floor = floor;
        const evaluating = self.frame_count;
        var value = self.callByName(name, &.{}) catch |err| {
            // the expression belongs to the access, not a frame of its own
            if (self.pending_exception) |exc| if (exc == .object) {
                const bare = if (self.functions.get(name)) |f| isBareConstantInitializer(f) else false;
                try (if (bare) self.stampThrowableBelow(exc.object, evaluating) else self.stampConstExprThrowable(exc.object, evaluating));
            };
            return err;
        };
        const cls = self.classes.getPtr(declared) orelse return value;
        if (cls.constant_types.get(const_name)) |type_text| {
            const t = php_types.parse(self.allocator, type_text, declared, cls.parent) catch return error.OutOfMemory;
            defer t.deinit(self.allocator);
            value = (try self.constantValueFits(value, t, declared)) orelse {
                const shown = php_types.format(self.allocator, t) catch return error.OutOfMemory;
                defer self.allocator.free(shown);
                const given: []const u8 = switch (value) {
                    .object => |o| o.class_name,
                    .null => "null",
                    .bool => "bool",
                    .int => "int",
                    .float => "float",
                    .string => "string",
                    .array => "array",
                    else => "mixed",
                };
                const msg = try std.fmt.allocPrint(self.allocator, "Cannot assign {s} to class constant {s}::{s} of type {s}", .{ given, declared, const_name, shown });
                defer self.allocator.free(msg);
                try self.setPendingException("TypeError", msg);
                return error.RuntimeError;
            };
        }
        const kept = try self.copyDefault(value);
        try cls.constants.put(self.allocator, const_name, kept);
        return self.enumCase(kept);
    }

    // a class constant's value against its declared type, as php checks it:
    // strictly, an int widening to float. null when it doesn't fit
    fn constantValueFits(self: *VM, value: Value, t: php_types.Type, class_name: []const u8) RuntimeError!?Value {
        const fits = switch (value) {
            .null => t.mask & php_types.NULL != 0,
            .bool => |b| t.mask & (if (b) php_types.TRUE else php_types.FALSE) != 0,
            .int => |i| if (t.mask & php_types.LONG != 0) true else if (t.mask & php_types.DOUBLE != 0) return Value{ .float = @floatFromInt(i) } else false,
            .float => t.mask & php_types.DOUBLE != 0,
            .string => t.mask & php_types.STRING != 0,
            .array => t.mask & php_types.ARRAY != 0,
            .object => |o| blk: {
                if (t.mask & php_types.OBJECT != 0) break :blk true;
                // `static` on a constant is the class declaring it
                if (t.mask & php_types.STATIC != 0 and self.isInstanceOf(o.class_name, class_name)) break :blk true;
                if (t.iterable and self.isInstanceOf(o.class_name, "Traversable")) break :blk true;
                for (t.names) |n| if (self.isInstanceOf(o.class_name, n)) break :blk true;
                for (t.intersections) |group| {
                    var all = true;
                    for (group) |n| if (!self.isInstanceOf(o.class_name, n)) {
                        all = false;
                        break;
                    };
                    if (all) break :blk true;
                }
                break :blk false;
            },
            else => false,
        };
        return if (fits) value else null;
    }

    // a class whose constants (its own or a parent's) wait for evaluation:
    // its first instantiation or static access evaluates them
    fn markLazyConstants(self: *VM, cls: *ClassDef) void {
        if (cls.lazy_constants) return;
        cls.lazy_constants = true;
        self.lazy_constant_classes += 1;
        if (cls.slot_layout) |layout| layout.defaults_ready = false;
    }

    // php's zend_update_class_constants on a class's first use: every
    // constant still waiting is evaluated
    pub fn updateClassConstants(self: *VM, class_name: []const u8) RuntimeError!void {
        const cls = self.classes.getPtr(class_name) orelse return;
        if (!cls.lazy_constants) return;
        if (cls.parent) |parent| try self.updateClassConstants(parent);
        var i: usize = 0;
        while (true) : (i += 1) {
            const def = self.classes.getPtr(class_name) orelse return;
            if (i >= def.constant_order.items.len) break;
            const name = def.constant_order.items[i];
            if (def.constants.get(name)) |v| if (v == .undef) {
                _ = try self.evaluateClassConstant(class_name, name);
            };
        }
        if (self.classes.getPtr(class_name)) |def| if (def.enum_table_pending) try self.buildBackedEnumTable(def);
        if (self.classes.getPtr(class_name)) |def| if (def.lazy_constants) {
            def.lazy_constants = false;
            self.lazy_constant_classes -= 1;
        };
    }

    // zend_enum_build_backed_enum_table: every case's value has the backing
    // type and no two share one. a failure leaves the enum waiting, so the
    // next use raises it again
    fn buildBackedEnumTable(self: *VM, def: *ClassDef) RuntimeError!void {
        const want: []const u8 = if (def.backed_type == .int_type) "int" else "string";
        for (def.case_order.items, 0..) |name, i| {
            const case_obj = def.constants.get(name) orelse continue;
            if (case_obj != .object) continue;
            const value = case_obj.object.get("value");
            const fits = if (def.backed_type == .int_type) value == .int else value == .string;
            if (!fits) {
                const msg = try std.fmt.allocPrint(self.allocator, "Enum case type {s} does not match enum backing type {s}", .{ value.typeName(), want });
                defer self.allocator.free(msg);
                try self.setPendingException("TypeError", msg);
                return error.RuntimeError;
            }
            for (def.case_order.items[0..i]) |earlier| {
                const other = def.constants.get(earlier) orelse continue;
                if (other != .object) continue;
                if (!Value.identical(other.object.get("value"), value)) continue;
                const msg = try std.fmt.allocPrint(self.allocator, "Duplicate value in enum {s} for cases {s} and {s}", .{ def.name, earlier, name });
                defer self.allocator.free(msg);
                try self.setPendingException("Error", msg);
                return error.RuntimeError;
            }
        }
        def.enum_table_pending = false;
    }

    // what php reported while compiling a file, raised before the file runs
    pub fn raiseCompileWarnings(self: *VM, result: *const CompileResult) RuntimeError!void {
        for (result.warnings.items) |w| try self.raiseErrorAt(w.level, w.message, .{ .file = result.file_path, .line = w.line });
    }

    pub fn raiseErrorAt(self: *VM, level: i64, raw_msg: []const u8, at: SourcePosition) RuntimeError!void {
        // an engine message names classes with %s, which stops at an
        // anonymous class's NUL
        const stripped = try class_names.stripAnonymous(self.allocator, raw_msg);
        defer if (stripped) |s| self.allocator.free(s);
        return self.raiseMessageAt(level, stripped orelse raw_msg, at);
    }

    // raiseErrorAt for a message written by the script, which trigger_error
    // passes on whole
    pub fn raiseMessageAt(self: *VM, level: i64, msg: []const u8, at: SourcePosition) RuntimeError!void {
        if (self.eh_throw) |eh| {
            switch (level) {
                E_WARNING, 32, 128, 512 => {
                    // a pending exception is never replaced
                    if (self.pending_exception != null) return;
                    if (eh.from.len > 0 and std.mem.startsWith(u8, msg, eh.from)) {
                        const renamed = try std.fmt.allocPrint(self.allocator, "{s}{s}", .{ eh.to, msg[eh.from.len..] });
                        defer self.allocator.free(renamed);
                        try self.setPendingException(eh.class, renamed);
                    } else try self.setPendingException(eh.class, msg);
                    return;
                },
                else => {},
            }
        } else if (try self.callUserErrorHandler(level, msg, at)) return;
        self.recordLastError(level, msg, at);
        const shown = self.error_silenced_depth == 0 and (self.error_reporting_level & level) != 0;
        if (shown) self.printError(level, msg, at);
        if (!isFatalLevel(level)) return;
        self.exit_code = 255;
        self.exit_requested = true;
        self.unclean_shutdown = true;
        return error.RuntimeError;
    }

    fn isFatalLevel(level: i64) bool {
        return switch (level) {
            1, 16, 64, 256, 4096 => true,
            else => false,
        };
    }

    // a raised error whose handler threw mid-opcode lands in this loop's
    // catch the way throwBuiltinException does, or propagates
    fn resumeRaised(self: *VM) RuntimeError!bool {
        if (self.pending_exception != null and self.dispatchPendingException(self.run_base_frame)) return true;
        return error.RuntimeError;
    }

    fn callUserErrorHandler(self: *VM, level: i64, msg: []const u8, at: SourcePosition) RuntimeError!bool {
        const handler = self.user_error_handler orelse return false;
        if ((self.user_error_handler_mask & level) == 0) return false;
        const message = Value{ .string = try Value.String.create(self.allocator, msg) };
        defer message.string.release();
        // errors raised inside the handler take the default path
        self.user_error_handler = null;
        defer self.reinstateErrorHandler(handler);
        // code the handler runs reports its own positions
        const saved_site = self.ic.?.arg_check_site;
        self.ic.?.arg_check_site = null;
        defer self.ic.?.arg_check_site = saved_site;
        var ctx = self.makeContext(null);
        const result = ctx.invokeCallable(handler, &.{ .{ .int = level }, message, .{ .string = Value.String.borrowed(at.file) }, .{ .int = at.line } }) catch |err| {
            if (self.pending_exception != null) return err;
            return false;
        };
        return !(result == .bool and !result.bool);
    }

    // the handler that ran comes back unless it installed another one
    fn reinstateErrorHandler(self: *VM, handler: Value) void {
        if (self.user_error_handler == null) self.user_error_handler = handler else self.releaseValue(handler);
    }

    fn recordLastError(self: *VM, level: i64, msg: []const u8, at: SourcePosition) void {
        const kept = self.allocator.dupe(u8, msg) catch return;
        self.clearLastError();
        self.last_error_type = level;
        self.last_error_message = kept;
        self.last_error_file = at.file;
        self.last_error_line = at.line;
    }

    pub fn clearLastError(self: *VM) void {
        if (self.last_error_message.len > 0) self.allocator.free(self.last_error_message);
        self.last_error_type = 0;
        self.last_error_message = "";
        self.last_error_file = "";
        self.last_error_line = 0;
    }

    fn printError(self: *VM, level: i64, msg: []const u8, at: SourcePosition) void {
        const label = errorLabel(level);
        self.flushOutputToStdout();
        if (self.logErrorsEnabled()) {
            const log_text = std.fmt.allocPrint(self.allocator, "PHP {s}:  {s} in {s} on line {d}\n", .{ label, class_names.display(msg), at.file, at.line }) catch return;
            defer self.allocator.free(log_text);
            self.writeLog(log_text);
        }
        switch (self.displayTarget()) {
            .none => {},
            .stdout => {
                const display_text = std.fmt.allocPrint(self.allocator, "\n{s}: {s} in {s} on line {d}\n", .{ label, msg, at.file, at.line }) catch return;
                defer self.allocator.free(display_text);
                self.output.appendSlice(self.allocator, display_text) catch {};
            },
            .stderr => {
                const display_text = std.fmt.allocPrint(self.allocator, "{s}: {s} in {s} on line {d}\n", .{ label, msg, at.file, at.line }) catch return;
                defer self.allocator.free(display_text);
                _ = platform.write(std.Io.File.stderr(), display_text) catch {};
            },
        }
    }

    pub fn errorLabel(level: i64) []const u8 {
        return switch (level) {
            // php_error_cb's labels
            1, 16, 64, 256 => "Fatal error",
            2, 32, 128, 512 => "Warning",
            4 => "Parse error",
            8, 1024 => "Notice",
            2048 => "Strict Standards",
            4096 => "Recoverable fatal error",
            8192, 16384 => "Deprecated",
            else => "Notice",
        };
    }

    pub fn iniFlagOn(self: *const VM, name: []const u8, default: []const u8) bool {
        const val = self.ini_settings.get(name) orelse @import("../ini_config.zig").get(name) orelse default;
        if (val.len == 0) return false;
        if (std.mem.eql(u8, val, "0")) return false;
        return !(std.ascii.eqlIgnoreCase(val, "off") or std.ascii.eqlIgnoreCase(val, "false") or std.ascii.eqlIgnoreCase(val, "no"));
    }

    // gc_enabled mirrors zend.enable_gc, which gc_enable()/gc_disable() set too
    pub fn syncGcEnabled(self: *VM) void {
        self.gc_enabled = self.iniFlagOn("zend.enable_gc", "1");
    }

    // float text follows precision and serialize_precision
    pub fn syncFloatPrecision(self: *VM) void {
        const h = value_mod.hooks();
        h.precision = self.iniInt("precision", 14);
        h.serialize_precision = self.iniInt("serialize_precision", -1);
    }

    // zend.exception_string_param_max_len, read where traces are printed
    pub fn syncStringParamMaxLen(self: *VM) void {
        @import("../error_format.zig").string_param_max_len = @intCast(std.math.clamp(self.iniInt("zend.exception_string_param_max_len", 15), 0, 1000000));
    }

    fn iniInt(self: *const VM, name: []const u8, default: i32) i32 {
        const val = self.ini_settings.get(name) orelse @import("../ini_config.zig").get(name) orelse return default;
        return std.fmt.parseInt(i32, std.mem.trim(u8, val, " \t\r\n"), 10) catch default;
    }

    pub fn logErrorsEnabled(self: *const VM) bool {
        return self.iniFlagOn("log_errors", "1");
    }

    // php 8.5 follows a fatal error with the stack it happened on
    pub fn fatalErrorBacktraces(self: *const VM) bool {
        return self.iniFlagOn("fatal_error_backtraces", "1");
    }

    // php's error log: the error_log file when one is set, each line stamped
    // with the date in the default timezone, else stderr
    pub fn writeLog(self: *VM, line: []const u8) void {
        const path = self.ini_settings.get("error_log") orelse @import("../ini_config.zig").get("error_log") orelse "";
        if (path.len == 0) {
            _ = platform.write(std.Io.File.stderr(), line) catch {};
            return;
        }
        var ctx = self.makeContext(null);
        const stamp = @import("../stdlib/datetime.zig").formatTimestamp(&ctx, platform.timestamp(), "d-M-Y H:i:s e") catch {
            _ = platform.write(std.Io.File.stderr(), line) catch {};
            return;
        };
        defer if (stamp.value == .string) stamp.value.string.release();
        const file = std.Io.Dir.cwd().createFile(platform.io, path, .{ .truncate = false }) catch {
            _ = platform.write(std.Io.File.stderr(), line) catch {};
            return;
        };
        defer file.close(platform.io);
        platform.seekFromEnd(file, 0) catch {};
        const text = if (stamp.value == .string) stamp.value.string.bytes() else "";
        // php ends each logged entry with PHP_EOL
        const body = std.mem.trimEnd(u8, line, "\n");
        const eol = if (platform.is_windows) "\r\n" else "\n";
        const entry = std.fmt.allocPrint(self.allocator, "[{s}] {s}{s}", .{ text, body, eol }) catch return;
        defer self.allocator.free(entry);
        platform.writeAll(file, entry) catch {};
    }

    // stdout carries a CLI script's output, so what is buffered goes out
    // before anything else reaches the terminal or a child process inherits
    // the stream. in serve the buffer is the response body and stays put
    pub fn flushOutputToStdout(self: *VM) void {
        if (self.serve_mode or self.output.items.len == 0) return;
        // what output buffering holds stays in its buffers
        if (self.ob_stack.items.len > 0) {
            const sent = self.ob_stack.items[0].start;
            if (sent == 0) return;
            platform.writeStdout(self.output.items[0..sent]);
            std.mem.copyForwards(u8, self.output.items, self.output.items[sent..]);
            self.output.shrinkRetainingCapacity(self.output.items.len - sent);
            for (self.ob_stack.items) |*level| level.start -= sent;
            return;
        }
        platform.writeStdout(self.output.items);
        self.output.clearRetainingCapacity();
    }

    pub const DisplayTarget = enum { none, stdout, stderr };

    // php's display_errors: the display copy of a diagnostic goes to stdout
    // (1, On, stdout), to stderr (stderr), or nowhere
    pub fn displayTarget(self: *const VM) DisplayTarget {
        const val = self.ini_settings.get("display_errors") orelse @import("../ini_config.zig").get("display_errors") orelse "0";
        if (std.ascii.eqlIgnoreCase(val, "stderr")) return .stderr;
        return if (self.iniFlagOn("display_errors", "0")) .stdout else .none;
    }

    pub fn displayErrorsEnabled(self: *const VM) bool {
        return self.displayTarget() != .none;
    }

    fn stringHasLeadingNumericish(s: []const u8) bool {
        var i: usize = 0;
        while (i < s.len and (s[i] == ' ' or s[i] == '\t' or s[i] == '\n' or s[i] == '\r')) i += 1;
        if (i >= s.len) return false;
        if (s[i] == '+' or s[i] == '-') i += 1;
        if (i >= s.len) return false;
        return s[i] >= '0' and s[i] <= '9' or s[i] == '.';
    }

    // the hook sits on the builtin class; a user subclass inherits it
    fn nativeBinopHook(self: *VM, class_name: []const u8) ?*const fn (*NativeContext, NativeBinop, Value, Value) RuntimeError!?Value {
        var name: ?[]const u8 = class_name;
        var depth: usize = 0;
        while (name) |n| : (depth += 1) {
            if (depth > 64) return null;
            const def = self.classes.get(n) orelse return null;
            if (def.native_binop) |hook| return hook;
            name = def.parent;
        }
        return null;
    }

    // the hook sits on the builtin class; a user subclass inherits it
    fn nativeCloneHook(self: *VM, class_name: []const u8) ?*const fn (*VM, *PhpObject, *PhpObject) bool {
        var name: ?[]const u8 = class_name;
        while (name) |n| {
            const def = self.classes.get(n) orelse return null;
            if (def.native_clone) |hook| return hook;
            name = def.parent;
        }
        return null;
    }

    // php keeps clone_obj NULL for a class's subclasses too
    fn classUncloneable(self: *VM, class_name: []const u8) bool {
        var current: ?[]const u8 = class_name;
        var depth: usize = 0;
        while (current) |name| : (depth += 1) {
            if (depth > 64) return false;
            const cls = self.classes.getPtr(name) orelse return false;
            if (cls.uncloneable or cls.is_enum) return true;
            current = cls.parent;
        }
        return false;
    }

    // ZEND_CLONE: a copy of the object (refcount taken) with __clone run on
    // it, in the running scope; an error is left pending
    pub fn cloneValue(self: *VM, val: Value) RuntimeError!Value {
        // PHP rejects cloning of generators and fibers with Error
        if (val == .generator) {
            try self.setPendingException("Error", "Trying to clone an uncloneable object of class Generator");
            return error.RuntimeError;
        }
        if (val == .fiber) {
            try self.setPendingException("Error", "Trying to clone an uncloneable object of class Fiber");
            return error.RuntimeError;
        }
        if (val.closureName()) |name| {
            // a cloned closure is a new instance with the same
            // captures, $this and scope
            return self.copyClosureInstance(name, self.closureThisByName(name), self.closureDefClassByName(name), self.closureScopeByName(name));
        } else if (val == .object and val.object.fakeClosure() != null) {
            const state = val.object.fakeClosure().?;
            const copy = try self.newFakeClosure(state.callable, state.called_class);
            copy.retain();
            return .{ .object = copy };
        } else if (val == .object) {
            var src = val.object;
            try self.triggerLazyInit(src);
            src = src.storage();
            const native_clone = self.nativeCloneHook(src.class_name);
            const uncloneable = self.classUncloneable(src.class_name);
            if ((src.native.kind != .none and native_clone == null) or uncloneable) {
                try self.setUncloneable(src.class_name);
                return error.RuntimeError;
            }
            // ZEND_CLONE: a __clone the scope can't call refuses the clone
            if (self.findMethodInfo(src.class_name, "__clone")) |f| if (f.info.visibility != .public and !self.checkVisibility(f.defining, f.info.visibility) and !self.protectedRootVisible(f.defining, "__clone", f.info.visibility)) {
                const msg = try std.fmt.allocPrint(self.allocator, "Call to {s} method {s}::__clone(){s}", .{ @tagName(f.info.visibility), f.defining, self.visScopeSuffix() });
                defer self.allocator.free(msg);
                try self.setPendingException("Error", msg);
                return error.RuntimeError;
            };
            const copy = try self.allocObject(.{ .class_name = src.class_name });
            if (src.slots) |src_slots| {
                const new_slots = try self.allocator.alloc(Value, src_slots.len);
                for (src_slots, 0..) |sv, i| {
                    new_slots[i] = try self.copyValue(sv);
                }
                copy.slots = new_slots;
                copy.slot_layout = src.slot_layout;
            }
            var it = src.properties.iterator();
            while (it.next()) |entry| {
                try copy.putProperty(self.allocator, entry.key_ptr.*, try self.copyObjectCloneValue(entry.value_ptr.*));
            }
            if (native_clone) |hook| if (!hook(self, src, copy)) {
                // a hook may refuse with its class's own error
                if (self.pending_exception == null) try self.setUncloneable(src.class_name);
                return error.RuntimeError;
            };
            if (src.ref_mirrored) {
                if (src.slot_layout) |layout| {
                    for (layout.names) |name| {
                        if (self.ref_index) |ri| {
                            if (ri.prop_rev.get(.{ .object = src, .class_name = "", .prop_name = name })) |cells| {
                                if (cells.items.len > 0) {
                                    const cell = cells.items[0];
                                    try self.regRefObject(try self.persistentRefOwner(), cell, copy, name);
                                }
                            }
                        }
                    }
                }
            }
            if (self.hasMethod(src.class_name, "__clone")) {
                // the clone is freed when __clone throws
                copy.retain();
                try self.openReinitWindow(copy);
                defer self.closeReinitWindow();
                _ = self.callMethod(copy, "__clone", &.{}) catch |err| {
                    // zend_object_store_ctor_failed: no destructor for it
                    copy.destructor_called = true;
                    self.objRelease(copy);
                    return err;
                };
                copy.refcount -= 1;
            }
            if (val.object.backingValue() != .null) {
                const proxy = try self.allocObject(.{ .class_name = val.object.class_name, .slot_layout = val.object.slot_layout });
                const state = try self.allocator.create(PhpObject.LazyState);
                state.* = .{ .initializer = .null, .proxy = true, .pending = try self.allocator.alloc(bool, 0), .backing = copy };
                proxy.lazy = state;
                copy.retain();
                proxy.retain();
                return .{ .object = proxy };
            }
            copy.retain();
            return .{ .object = copy };
        } else {
            const msg = try std.fmt.allocPrint(self.allocator, "clone(): Argument #1 ($object) must be of type object, {s} given", .{val.valueName()});
            defer self.allocator.free(msg);
            try self.setPendingException("TypeError", msg);
            return error.RuntimeError;
        }
    }

    // clone with: each property assigned to the clone after __clone ran,
    // with the running scope's rules (MutationAction.reinit lets a readonly
    // property be written again). true when an exception was dispatched to a
    // handler at or above base_frame; one left pending is an error
    pub fn applyCloneWith(self: *VM, clone_obj: *PhpObject, props: *PhpArray, base_frame: usize) RuntimeError!bool {
        arrayRetain(props);
        defer self.arrayRelease(props);
        clone_obj.refcount +%= 1;
        defer self.objRelease(clone_obj);
        try self.openReinitWindow(clone_obj);
        defer self.closeReinitWindow();
        var dispatched = false;
        var i: usize = 0;
        while (i < props.entries.items.len) : (i += 1) {
            const entry = props.entries.items[i];
            // a reference only the array holds is its value; one shared
            // with anything else can't be assigned
            if (entry.ref) |cell| if (cellOf(cell).binders > 1) {
                if (try self.throwBuiltinException("Error", "Cannot assign by reference when cloning with updated properties")) return true;
                return error.RuntimeError;
            };
            const prop_name = switch (entry.key) {
                .string => |k| k.bytes(),
                .int => |n| (try self.transientFormatted(.{ .int = n })).bytes(),
            };
            var val = try self.preparePropertyStore(entry.value);
            const val_pin: ?*PhpObject = if (val == .object) val.object else null;
            if (val_pin) |pin| pin.refcount +%= 1;
            defer if (val_pin) |pin| self.objRelease(pin);
            const gate = try self.propertyWriteGate(clone_obj, prop_name, val, .reinit, base_frame);
            switch (gate.step) {
                .dispatched => {
                    dispatched = true;
                    break;
                },
                .stored => continue,
                .proceed => {},
            }
            if (try self.propertyWriteStore(gate.obj, prop_name, &val, gate.vr, .reinit, base_frame) == .dispatched) {
                dispatched = true;
                break;
            }
        }
        return dispatched;
    }

    fn openReinitWindow(self: *VM, obj: *PhpObject) !void {
        try self.reinit_windows.append(self.allocator, .{ .obj = obj });
    }

    fn closeReinitWindow(self: *VM) void {
        var window = self.reinit_windows.pop() orelse return;
        window.written.deinit(self.allocator);
    }

    // a readonly property of a clone that __clone (or clone()'s properties)
    // may still write once
    fn readonlyReinitable(self: *VM, obj: *PhpObject, name: []const u8) bool {
        var i = self.reinit_windows.items.len;
        while (i > 0) {
            i -= 1;
            const window = &self.reinit_windows.items[i];
            if (window.obj == obj) return !window.written.contains(name);
        }
        return false;
    }

    fn inReinitWindow(self: *VM, obj: *PhpObject) bool {
        for (self.reinit_windows.items) |window| if (window.obj == obj) return true;
        return false;
    }

    fn consumeReinit(self: *VM, obj: *PhpObject, name: []const u8) void {
        var i = self.reinit_windows.items.len;
        while (i > 0) {
            i -= 1;
            const window = &self.reinit_windows.items[i];
            if (window.obj != obj) continue;
            window.written.put(self.allocator, name, {}) catch {};
            return;
        }
    }

    pub fn setUncloneable(self: *VM, class_name: []const u8) !void {
        const msg = try std.fmt.allocPrint(self.allocator, "Trying to clone an uncloneable object of class {s}", .{class_name});
        defer self.allocator.free(msg);
        try self.setPendingException("Error", msg);
    }

    pub fn throwUncloneable(self: *VM, class_name: []const u8) !bool {
        const msg = try std.fmt.allocPrint(self.allocator, "Trying to clone an uncloneable object of class {s}", .{class_name});
        defer self.allocator.free(msg);
        return self.throwBuiltinException("Error", msg);
    }

    pub fn throwBuiltinException(self: *VM, class_name: []const u8, message: []const u8) !bool {
        return self.throwBuiltinExceptionAt(class_name, message, null);
    }

    // the declaration-site operands of class-like opcodes: start line, end
    // line, doc comment constant; the file is the executing script
    fn readDeclSite(self: *VM) DeclSite {
        const start_line = self.readU32();
        const end_line = self.readU32();
        const doc_idx = self.readU16();
        return .{
            .file = if (self.frame_count > 0 and self.currentFrame().script_path.len > 0) self.currentFrame().script_path else self.file_path,
            .start_line = start_line,
            .end_line = end_line,
            .doc_comment = if (doc_idx == 0xffff) "" else self.currentChunk().constants.items[doc_idx].string.bytes(),
        };
    }

    pub fn declSite(self: *VM, name: []const u8) ?DeclSite {
        if (self.ic.?.trait_sites.get(name)) |site| return site;
        const cls = self.classes.get(name) orelse return null;
        return .{ .file = cls.file_path, .start_line = cls.start_line, .end_line = cls.end_line, .doc_comment = cls.doc_comment };
    }

    pub const SourcePosition = struct { file: []const u8, line: i64 };

    // the file and line the executing frame is at
    pub fn currentSourcePosition(self: *VM) SourcePosition {
        if (self.ic) |ic| if (ic.arg_check_site) |site| return site;
        if (self.frame_count == 0) return .{ .file = self.file_path, .line = 0 };
        // an initializer (a constant expression: "\x00const...", attribute
        // arguments, deferred defaults) runs for the code that needed its
        // value, which php reports
        var fi = self.frame_count - 1;
        while (fi > 0) : (fi -= 1) {
            const func = self.frames[fi].func orelse break;
            if (func.name.len == 0 or func.name[0] != 0) break;
            // a class constant or property default runs as php's constant
            // expression with a scope, whose own file and line php reports
            // (EG(filename_override))
            if (isScopedConstExpr(func.name) and !isBareConstantInitializer(func)) break;
        }
        const frame = &self.frames[fi];
        const ip = frame.ip;
        const line: i64 = if (self.sourceLocation(frame.chunk, if (ip > 0) ip - 1 else 0)) |loc| @intCast(loc.line) else 0;
        return .{ .file = self.frameFile(fi), .line = line };
    }
    pub const SourcePositionMessage = struct { message: []const u8, at: SourcePosition, trace: bool = true };

    // the file loader could not compile an included file: remembered until the
    // include opcode raises it
    pub fn recordIncludeParseError(self: *VM, message: []const u8, file: []const u8, line: i64) void {
        self.dropIncludeError(&self.ic.?.include_parse_error);
        self.ic.?.include_parse_error = self.ownedPositionMessage(message, file, line);
    }

    pub fn recordIncludeCompileError(self: *VM, message: []const u8, file: []const u8, line: i64, trace: bool) void {
        self.dropIncludeError(&self.ic.?.include_compile_error);
        self.ic.?.include_compile_error = self.ownedPositionMessage(message, file, line);
        if (self.ic.?.include_compile_error) |*e| e.trace = trace;
    }

    fn ownedPositionMessage(self: *VM, message: []const u8, file: []const u8, line: i64) ?SourcePositionMessage {
        const msg = self.allocator.dupe(u8, message) catch return null;
        const path = self.allocator.dupe(u8, file) catch {
            self.allocator.free(msg);
            return null;
        };
        return .{ .message = msg, .at = .{ .file = path, .line = line } };
    }

    fn dropIncludeError(self: *VM, slot: *?SourcePositionMessage) void {
        const record = slot.* orelse return;
        self.allocator.free(record.message);
        self.allocator.free(record.at.file);
        slot.* = null;
    }

    // what php throws when an append finds the next index taken
    pub fn throwNextElementOccupied(self: *VM) !bool {
        return self.throwBuiltinException("Error", "Cannot add element to the array as the next element is already occupied");
    }

    // php's E_ERROR from inside the engine: the script ends past any
    // try/catch, reported as "Fatal error: <message>"
    // a ClassDef hook the class or its nearest ancestor defines
    pub fn classHook(self: *VM, class_name: []const u8, comptime field: []const u8) @FieldType(ClassDef, field) {
        var name: ?[]const u8 = class_name;
        while (name) |n| {
            const def = self.classes.get(n) orelse return null;
            if (@field(def, field)) |hook| return hook;
            name = def.parent;
        }
        return null;
    }

    pub fn raiseFatal(self: *VM, message: []const u8) RuntimeError {
        try self.setPendingException("Error", message);
        self.uncatchable_fatal = true;
        return error.RuntimeError;
    }

    // a compile-time fatal ends the script where php reports it: in the file
    // being compiled, past any try/catch
    pub fn raiseCompileFatal(self: *VM, message: []const u8, at: SourcePosition) RuntimeError {
        try self.setPendingException("CompileError", message);
        if (self.pending_exception) |exc| if (exc == .object) {
            try exc.object.setCopiedString(self.allocator, "file", at.file);
            try exc.object.set(self.allocator, "line", .{ .int = at.line });
        };
        self.uncatchable_fatal = true;
        return error.RuntimeError;
    }

    // `at` places the exception somewhere other than the throwing frame, the
    // way a ParseError from an included file reports that file and line
    pub fn throwBuiltinExceptionAt(self: *VM, class_name: []const u8, message: []const u8, at: ?SourcePosition) !bool {
        // a lookup that cannot fail (a class constant, a static property, a
        // method) leaves an autoloader's exception pending; php raises that
        // one, never the miss the lookup then reports
        if (self.takePending()) |pending| {
            defer self.stackRelease(pending);
            if (pending == .object) return self.throwObject(pending.object);
        }
        return self.throwObject(try self.newBuiltinException(class_name, message, at));
    }

    // a message the engine formatted: php writes the class names in it with
    // %s, so an anonymous class's stops at its NUL
    fn engineMessage(self: *VM, message: []const u8) !Value.String {
        if (try class_names.stripAnonymous(self.allocator, message)) |shown| return Value.String.adopt(self.allocator, shown);
        return Value.String.create(self.allocator, message);
    }

    fn newBuiltinException(self: *VM, class_name: []const u8, message: []const u8, at: ?SourcePosition) !*PhpObject {
        const obj = try self.allocUserObject(class_name);
        try self.initObjectProperties(obj, class_name);
        const owned_message = try self.engineMessage(message);
        defer owned_message.release();
        try obj.set(self.allocator, "message", .{ .string = owned_message });
        try obj.set(self.allocator, "code", .{ .int = 0 });
        if (at) |pos| {
            try obj.setCopiedString(self.allocator, "file", pos.file);
            try obj.set(self.allocator, "line", .{ .int = pos.line });
        }
        return obj;
    }

    // lands in this loop's nearest catch; false leaves it pending for an
    // outer loop
    fn throwObject(self: *VM, obj: *PhpObject) bool {
        if (self.handler_count <= self.handler_floor) {
            self.raise(.{ .object = obj });
            return false;
        }

        const handler = self.exception_handlers[self.handler_count - 1];

        // handler belongs to an outer runLoop - propagate up
        if (handler.frame_count <= self.run_base_frame and self.run_base_frame > 0) {
            self.raise(.{ .object = obj });
            return false;
        }

        self.enterHandler(handler, .{ .object = obj }, .borrowed);
        return true;
    }

    // enters an exception handler: unwinds the frames and operands above it
    // and pushes the exception for its catch
    fn enterHandler(self: *VM, handler: ExceptionHandler, exc: Value, comptime ownership: enum { owned, borrowed }) void {
        self.chainHeldExceptions(exc, handler.frame_count, handler.sp);
        // initializers the exception left
        while (self.initializer_scopes.items.len > 0 and self.initializer_scopes.items[self.initializer_scopes.items.len - 1].handlers >= self.handler_count) {
            _ = self.initializer_scopes.pop();
        }
        self.handler_count -= 1;
        while (self.frame_count > handler.frame_count) {
            self.frame_count -= 1;
            self.deinitFrameSlot(self.frame_count);
        }
        self.discardArgTransport(handler.sp);
        // a handler pushed while a caught exception was still on the stack
        // sits above slots the catch has since popped: nothing owns them
        if (handler.sp > self.sp) @memset(self.stack[self.sp..handler.sp], .null);
        self.sp = handler.sp;
        self.error_silenced_depth = handler.silenced_depth;
        var thrown = exc;
        if (ownership == .borrowed) stackRetain(thrown);
        // what the unwound frames held is destroyed before the catch runs;
        // a destructor's exception replaces the one caught, with it as its
        // previous
        if (self.hasPendingReleases()) {
            self.pending_exception = thrown;
            if (self.draining_destructors) self.drainNested() else {
                self.drainPendingDestruct();
                // the releases may fill the collector's root buffer
                self.collectCyclesIfNeeded();
            }
            self.drain_raised = false;
            thrown = self.takePending() orelse thrown;
        }
        self.pushTransfer(thrown);
        self.currentFrame().ip = handler.catch_ip;
    }

    // an exception unwinding to `frame_count` frames and `sp` operands takes
    // the exceptions finally blocks above that point held as its previous,
    // innermost first
    fn chainHeldExceptions(self: *VM, exc: Value, frame_count: usize, sp: usize) void {
        var i = self.held_exceptions.items.len;
        while (i > 0) {
            i -= 1;
            const held = self.held_exceptions.items[i];
            const in_place = held.frame < self.frame_count and held.slot < self.sp and self.stack[held.slot] == .object and self.stack[held.slot].object == held.exception;
            const unwound = held.frame >= frame_count or (frame_count > 0 and held.frame == frame_count - 1 and held.slot >= sp);
            if (in_place and !unwound) continue;
            _ = self.held_exceptions.orderedRemove(i);
            if (in_place and exc == .object and !self.isUnwindMarker(.{ .object = held.exception })) _ = self.chainPrevious(exc.object, held.exception) catch {};
        }
    }

    // the exception a finally block holds at `slot` of frame `frame` is gone
    fn releaseHeldAt(self: *VM, frame: usize, slot: usize) void {
        var i = self.held_exceptions.items.len;
        while (i > 0) {
            i -= 1;
            const held = self.held_exceptions.items[i];
            if (held.frame >= frame and held.slot >= slot) _ = self.held_exceptions.orderedRemove(i);
        }
    }

    fn dispatchPendingException(self: *VM, base_frame: usize) bool {
        if (self.uncatchable_fatal) return false;
        const exc = self.pending_exception orelse return false;
        if (self.handler_count <= self.handler_floor) return false;
        const handler = self.exception_handlers[self.handler_count - 1];
        if (handler.frame_count <= base_frame and base_frame > 0) return false;
        self.pending_exception = null;
        self.enterHandler(handler, exc, .owned);
        return true;
    }

    // runs a generator to its next yield. a generator delegating with yield
    // from doesn't run itself: as in php's generator tree, the innermost
    // delegate runs, its yields become the current value of every generator
    // on the way to it, its return value resumes its parent, and its
    // exception is thrown into its parent at the yield from. the walk is a
    // loop over that path, so a long chain of delegations takes no native
    // stack per level
    pub fn resumeGenerator(self: *VM, gen: *Generator, sent_value: Value) RuntimeError!void {
        if (gen.state == .completed) return;
        if (generatorRoot(gen).state == .running) {
            try self.setPendingException("Error", "Cannot resume an already running generator");
            return error.RuntimeError;
        }
        gen.resumes +|= 1;
        gen.at_first_yield = false;
        // the path lives on the stack until a chain outgrows it
        var inline_path: [16]*Generator = undefined;
        var path: std.ArrayListUnmanaged(*Generator) = .initBuffer(&inline_path);
        defer if (path.items.ptr != &inline_path) path.deinit(self.allocator);
        path.appendAssumeCapacity(gen);
        defer for (path.items[1..]) |delegate| {
            delegate.delegator = null;
        };
        var sent = sent_value;
        while (true) {
            var leaf = path.items[path.items.len - 1];
            while (leaf.delegate) |delegate| {
                if (delegate != .gen) break;
                const inner = delegate.gen;
                // throw() on an outer generator is thrown into the innermost
                // one, so try/catch around `yield from` works php-style
                if (leaf.pending_throw) |ex| {
                    leaf.pending_throw = null;
                    inner.pending_throw = ex;
                }
                if (path.items.len == path.capacity and path.items.ptr == &inline_path) {
                    var grown = try std.ArrayListUnmanaged(*Generator).initCapacity(self.allocator, 2 * path.capacity);
                    grown.appendSliceAssumeCapacity(path.items);
                    path = grown;
                }
                try path.append(self.allocator, inner);
                inner.delegator = leaf;
                leaf = inner;
            }

            var step = leaf.state != .completed;
            leaf.delegate_pending = false;
            if (step and leaf.delegate != null) {
                // php's zend_generator_get_next_delegated_value
                if (try self.nextDelegatedValue(leaf)) step = false else sent = .null;
            }
            if (step) self.resumeGeneratorWithValue(leaf, sent) catch |err| {
                if (path.items.len == 1 or self.pending_exception == null or self.exit_requested or self.fiber_suspend_pending) return err;
                // the delegate's exception leaves it and is thrown into its
                // parent where the parent waits in yield from
                const ex = self.pending_exception.?;
                self.pending_exception = null;
                _ = path.pop();
                leaf.delegator = null;
                const parent = path.items[path.items.len - 1];
                parent.delegate = null;
                self.genRelease(leaf);
                parent.pending_throw = ex;
                sent = .null;
                continue;
            };

            if (leaf.state == .suspended) {
                // a yield from that has just taken a delegate: its first
                // value comes next (a generator delegate that already has
                // one keeps it, php's ZEND_GENERATOR_DO_INIT)
                if (leaf.delegate_pending) if (leaf.delegate) |delegate| {
                    if (delegate != .gen or delegate.gen.state == .created) {
                        sent = .null;
                        continue;
                    }
                    leaf.delegate_pending = false;
                    const inner_root = generatorRoot(delegate.gen);
                    self.setGeneratorCurrent(leaf, inner_root.current_key, inner_root.current_value, false);
                };
                var i = path.items.len - 1;
                while (i > 0) : (i -= 1) {
                    const child = path.items[i];
                    self.setGeneratorCurrent(path.items[i - 1], child.current_key, child.current_value, false);
                }
                return;
            }
            if (path.items.len == 1) return;
            // the delegate finished: its return value is what yield from
            // gives its parent, which runs on. one that was aborted has none,
            // and its parent gets php's ClosedGeneratorException instead
            _ = path.pop();
            leaf.delegator = null;
            const parent = path.items[path.items.len - 1];
            const ret_val = leaf.return_value;
            const returned = leaf.has_return;
            parent.delegate = null;
            if (returned) retainValue(ret_val);
            defer if (returned) self.releaseValue(ret_val);
            self.genRelease(leaf);
            if (!returned) parent.pending_closed_delegate = true;
            sent = if (returned) ret_val else .null;
        }
    }

    // php's zend_generator_get_next_delegated_value: the next value of the
    // array or iterator a generator delegates to, as its current one. false
    // when there is none, the delegation over; an exception the iterator
    // throws ends it too and is thrown into the generator at its yield from
    fn nextDelegatedValue(self: *VM, gen: *Generator) RuntimeError!bool {
        const delegate = &(gen.delegate orelse return false);
        switch (delegate.*) {
            .gen => return false,
            .array => |*state| {
                while (state.index < state.arr.entries.items.len) {
                    const entry = state.arr.entries.items[state.index];
                    state.index += 1;
                    self.setGeneratorCurrent(gen, switch (entry.key) {
                        .int => |i| .{ .int = i },
                        .string => |str| .{ .string = str },
                    }, if (entry.ref) |ref| ref.* else entry.value, false);
                    return true;
                }
            },
            .iterator => |*state| iterate: {
                const it = state.obj;
                if (state.index > 0) {
                    _ = self.callMethod(it, "next", &.{}) catch break :iterate;
                }
                state.index += 1;
                const valid = self.callMethod(it, "valid", &.{}) catch break :iterate;
                if (!valid.isTruthy()) break :iterate;
                const value = self.callMethod(it, "current", &.{}) catch break :iterate;
                retainValue(value);
                defer self.releaseValue(value);
                const key = self.callMethod(it, "key", &.{}) catch break :iterate;
                retainValue(key);
                defer self.releaseValue(key);
                self.setGeneratorCurrent(gen, key, value, false);
                return true;
            },
        }
        self.dropGeneratorDelegate(gen);
        if (self.pending_exception) |ex| {
            self.pending_exception = null;
            if (gen.pending_throw) |old| self.stackRelease(old);
            gen.pending_throw = ex;
        }
        return false;
    }

    // the Iterator or Generator a Traversable object is iterated through:
    // itself, or what an IteratorAggregate's getIterator() returns (again for
    // an aggregate that returns another). the result holds a reference
    fn traversableIterator(self: *VM, obj: *PhpObject) RuntimeError!Value {
        var cur: Value = .{ .object = obj };
        retainValue(cur);
        var steps: usize = 0;
        while (cur == .object and !self.isInstanceOf(cur.object.class_name, "Iterator")) : (steps += 1) {
            const aggregate = cur.object;
            defer self.releaseValue(.{ .object = aggregate });
            const next = try self.callMethod(aggregate, "getIterator", &.{});
            const traversable = (next == .object and self.isInstanceOf(next.object.class_name, "Traversable") and next.object != aggregate) or next == .generator;
            if (!traversable or steps > 64) {
                const msg = try std.fmt.allocPrint(self.allocator, "Objects returned by {s}::getIterator() must be traversable or implement interface Iterator", .{aggregate.class_name});
                defer self.allocator.free(msg);
                try self.setPendingException("Exception", msg);
                return error.RuntimeError;
            }
            retainValue(next);
            cur = next;
        }
        return cur;
    }

    // a generator stops delegating: what it delegated to loses its reference
    pub fn dropGeneratorDelegate(self: *VM, gen: *Generator) void {
        const delegate = gen.delegate orelse return;
        gen.delegate = null;
        switch (delegate) {
            .gen => |inner| self.genRelease(inner),
            .array => |state| self.arrayRelease(state.arr),
            .iterator => |state| self.releaseValue(.{ .object = state.obj }),
        }
    }

    // php's zend_generator_get_current: the generator a delegation chain
    // runs, the innermost one still running. one whose delegate finished is
    // its own root until it is resumed and takes the delegate's result
    pub fn generatorRoot(gen: *Generator) *Generator {
        var g = gen;
        while (g.delegate) |delegate| {
            if (delegate != .gen or delegate.gen.state == .completed) break;
            g = delegate.gen;
        }
        return g;
    }

    // php's zend_generator_update_current, as reading a generator's current
    // state runs it: one whose delegate was aborted without returning gets
    // php's ClosedGeneratorException at its yield from, and runs on
    pub fn updateGeneratorCurrent(self: *VM, gen: *Generator) RuntimeError!void {
        if (gen.state == .completed or self.pending_exception != null) return;
        const root = generatorRoot(gen);
        const delegate = root.delegate orelse return;
        if (delegate != .gen or delegate.gen.state != .completed) return;
        if (delegate.gen.has_return) {
            // the delegate's last value is this one's until it resumes
            self.setGeneratorCurrent(root, delegate.gen.current_key, delegate.gen.current_value, false);
            return;
        }
        root.delegate = null;
        self.genRelease(delegate.gen);
        root.pending_closed_delegate = true;
        try self.resumeGenerator(gen, .null);
    }

    // php's zend_generator_ensure_initialized: a generator a method or
    // foreach touches first runs to its first yield
    pub fn ensureGeneratorInitialized(self: *VM, gen: *Generator) RuntimeError!void {
        if (gen.has_value or gen.state == .completed or gen.delegate != null) return;
        try self.resumeGenerator(gen, .null);
        gen.at_first_yield = true;
    }

    const GeneratorMethod = enum { current, key, next, rewind, send, throw, getReturn, valid, __debugInfo };

    // a native method of Generator or Fiber while it runs: traces show it,
    // and the code it runs reads as called by an internal function
    fn enterEngineMethod(self: *VM, record: *NativeCall, label: []const u8, args: []const Value, instance: bool) void {
        const outer = self.native_call;
        const from_native = if (outer) |o| o.depth == self.frame_count or (o.depth + 1 == self.frame_count and self.frames[self.frame_count - 1].native) else false;
        record.* = .{ .label = label, .args = args, .depth = self.frame_count, .instance = instance, .outer = outer, .from_native = from_native };
        self.native_call = record;
    }

    fn argumentCountError(self: *VM, label: []const u8, min: u16, max: u16, given: usize) RuntimeError {
        var buf: [256]u8 = undefined;
        const arity: @import("natives.zig").Arity = .{ .min = min, .max = max };
        try self.setPendingException("ArgumentCountError", arity.describe(&buf, label, given));
        return error.RuntimeError;
    }

    // the methods of php's Generator class (zend_generators.c). the value
    // returned is borrowed from the generator
    pub fn generatorMethod(self: *VM, gen: *Generator, name: []const u8, args: []const Value) RuntimeError!Value {
        const method = inline for (comptime std.enums.values(GeneratorMethod)) |m| {
            if (std.ascii.eqlIgnoreCase(name, @tagName(m))) break m;
        } else {
            const msg = try std.fmt.allocPrint(self.allocator, "Call to undefined method Generator::{s}()", .{name});
            defer self.allocator.free(msg);
            try self.setPendingException("Error", msg);
            return error.RuntimeError;
        };
        const label = switch (method) {
            inline else => |m| "Generator::" ++ @tagName(m),
        };
        var record: NativeCall = undefined;
        self.enterEngineMethod(&record, label, args, true);
        defer self.native_call = record.outer;
        const arity: u16 = if (method == .send or method == .throw) 1 else 0;
        if (args.len != arity) return self.argumentCountError(label, arity, arity, args.len);
        switch (method) {
            .current, .key => {
                try self.ensureGeneratorInitialized(gen);
                try self.updateGeneratorCurrent(gen);
                const root = generatorRoot(gen);
                if (gen.state == .completed) return .null;
                return if (method == .current) root.current_value else root.current_key;
            },
            .valid => {
                try self.ensureGeneratorInitialized(gen);
                try self.updateGeneratorCurrent(gen);
                return .{ .bool = gen.state != .completed };
            },
            .next => {
                try self.ensureGeneratorInitialized(gen);
                try self.resumeGenerator(gen, .null);
                return .null;
            },
            .rewind => {
                try self.rewindGenerator(gen);
                return .null;
            },
            .send => {
                try self.ensureGeneratorInitialized(gen);
                if (gen.state == .completed) return .null;
                try self.updateGeneratorCurrent(gen);
                try self.resumeGenerator(gen, args[0]);
                if (gen.state == .completed) return .null;
                return generatorRoot(gen).current_value;
            },
            .throw => {
                const ex = args[0];
                if (ex != .object or !self.isInstanceOf(ex.object.class_name, "Throwable")) {
                    const msg = try std.fmt.allocPrint(self.allocator, "Generator::throw(): Argument #1 ($exception) must be of type Throwable, {s} given", .{valueTypeName(ex)});
                    defer self.allocator.free(msg);
                    try self.setPendingException("TypeError", msg);
                    return error.RuntimeError;
                }
                try self.ensureGeneratorInitialized(gen);
                if (gen.state == .completed) {
                    // a closed generator throws it where throw() was called
                    self.raise(ex);
                    return error.RuntimeError;
                }
                const root = generatorRoot(gen);
                if (root.state == .running) {
                    try self.setPendingException("Error", "Cannot resume an already running generator");
                    return error.RuntimeError;
                }
                // the exception reaches the generator at its yield; one
                // delegating to an array or iterator stops doing so
                if (root.delegate) |delegate| if (delegate != .gen) self.dropGeneratorDelegate(root);
                stackRetain(ex);
                if (root.pending_throw) |old| self.stackRelease(old);
                root.pending_throw = ex;
                try self.resumeGenerator(gen, .null);
                if (gen.state == .completed) return .null;
                return generatorRoot(gen).current_value;
            },
            .getReturn => {
                try self.ensureGeneratorInitialized(gen);
                if (self.pending_exception != null) return error.RuntimeError;
                if (!gen.has_return) {
                    try self.setPendingException("Exception", "Cannot get return value of a generator that hasn't returned");
                    return error.RuntimeError;
                }
                return gen.return_value;
            },
            .__debugInfo => {
                const arr = try self.allocArray();
                try arr.set(self.allocator, .{ .string = Value.String.borrowed("function") }, .{ .string = Value.String.borrowed(try self.generatorFunctionName(gen)) });
                return .{ .array = arr };
            },
        }
    }

    // the function a generator runs as php names it in its debug info:
    // Class::method, a closure's {closure:...}, or the function
    pub fn generatorFunctionName(self: *VM, gen: *const Generator) ![]const u8 {
        return self.funcDisplayName(gen.func);
    }

    fn releaseGeneratorCurrent(self: *VM, gen: *Generator) void {
        self.releaseValue(gen.current_value);
        self.releaseValue(gen.current_key);
        gen.current_value = .null;
        gen.current_key = .null;
        gen.current_ref = null;
    }

    fn keepGeneratorExtraArgs(self: *VM, gen: *Generator, args: []const Value) RuntimeError!void {
        for (args) |arg| {
            retainValue(arg);
            try gen.extra_args.append(self.allocator, arg);
        }
    }

    // php's zend_generator_rewind
    pub fn rewindGenerator(self: *VM, gen: *Generator) RuntimeError!void {
        try self.ensureGeneratorInitialized(gen);
        if (!gen.at_first_yield) {
            try self.setPendingException("Exception", "Cannot rewind a generator that was already run");
            return error.RuntimeError;
        }
    }

    fn resumeGeneratorWithValue(self: *VM, gen: *Generator, sent_value: Value) RuntimeError!void {
        if (gen.state == .completed) return;

        gen.state = .running;
        const saved_sp = self.sp;
        const return_frame = self.frame_count;
        const saved_handler_count = self.handler_count;
        const prev_floor = self.handler_floor;
        self.handler_floor = self.handler_count;

        // restore saved stack from previous suspension. the saved slots hold
        // the references the operand stack had when it suspended
        for (gen.stack.items) |v| self.pushTransfer(v);
        gen.stack.clearRetainingCapacity();
        gen.base_sp = saved_sp;

        // the frame takes over the saved locals and their references until
        // the next yield (saveFrameLocalsToGenerator) or unwind moves them back
        var gen_locals: []Value = &.{};
        if (gen.locals.items.len > 0) {
            gen_locals = try self.allocator.alloc(Value, gen.locals.items.len);
            @memcpy(gen_locals, gen.locals.items);
            gen.locals.clearRetainingCapacity();
        } else if (gen.ip == 0) {
            // first resume - allocate locals from initial vars
            gen_locals = try self.allocLocals(gen.func, &gen.vars);
        }
        genRetain(gen);
        try self.ensureCallRoom();
        self.frames[self.frame_count] = .{
            .chunk = &gen.func.chunk,
            .ip = gen.ip,
            .vars = gen.vars,
            .locals = gen_locals,
            .func = gen.func,
            .generator = gen,
            .ref_slots = gen.ref_slots,
            .ref_owner = gen.ref_owner,
            .called_class = gen.called_class,
        };
        gen.ref_slots = .{};
        gen.ref_owner = 0;
        self.markArgsUnsaved();
        self.frame_count += 1;
        self.retainFrameObjects(self.frame_count - 1);
        if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;

        try self.restoreGeneratorHandlers(gen);

        if (gen.ip > 0) {
            self.push(sent_value);
        }

        if (gen.pending_closed_delegate) {
            gen.pending_closed_delegate = false;
            // made here, so its trace starts in the generator's frame
            try self.setPendingException("ClosedGeneratorException", "Generator yielded from aborted, no return value available");
            gen.pending_throw = self.pending_exception;
            self.pending_exception = null;
        }
        if (gen.pending_throw) |ex| {
            gen.pending_throw = null;
            self.setPendingOwned(ex);
            // try to dispatch within the generator's frame; if no handler, the exception
            // will propagate when runUntilFrame catches the eventual error
            if (self.dispatchPendingException(return_frame)) {
                // handler found - runLoop will continue from catch block
            } else {
                // no handler - generator completes with the exception pending
                gen.state = .completed;
                self.handler_count = saved_handler_count;
                while (self.frame_count > return_frame) {
                    self.frame_count -= 1;
                    self.deinitFrameSlot(self.frame_count);
                }
                self.clearArgStackFrom(saved_sp);
                self.sp = saved_sp;
                self.handler_floor = prev_floor;
                return error.RuntimeError;
            }
        }

        self.runUntilFrame(return_frame) catch |err| {
            self.handler_floor = prev_floor;
            if (gen.state == .suspended) {
                self.clearArgStackFrom(saved_sp);
                self.sp = saved_sp;
                return;
            }
            if (gen.state == .completed) {
                self.clearArgStackFrom(saved_sp);
                self.sp = saved_sp;
                return;
            }
            gen.state = .completed;
            self.handler_count = saved_handler_count;
            while (self.frame_count > return_frame) {
                self.frame_count -= 1;
                self.deinitFrameSlot(self.frame_count);
            }
            self.clearArgStackFrom(saved_sp);
            self.sp = saved_sp;
            if (self.pending_exception != null) {
                return error.RuntimeError;
            }
            return err;
        };
        self.handler_floor = prev_floor;
        if (gen.state == .running) {
            gen.state = .completed;
            self.releaseGeneratorVars(gen);
        }
        self.clearArgStackFrom(saved_sp);
        self.sp = saved_sp;
    }

    fn saveGeneratorStack(self: *VM, gen: *Generator) !void {
        gen.stack.clearRetainingCapacity();
        if (self.sp > gen.base_sp) {
            try gen.stack.appendSlice(self.allocator, self.stack[gen.base_sp..self.sp]);
        }
    }

    // the reference cell bound to a local slot, in a function or the script frame
    pub fn slotRefCell(self: *VM, frame: *CallFrame, slot: u16) ?*Value {
        if (frame.ref_slots.count() == 0) return null;
        const names = if (frame.func) |func| func.slot_names else self.global_slot_names;
        if (slot >= names.len or names[slot].len == 0) return null;
        return frame.ref_slots.get(names[slot]);
    }

    fn slotName(self: *VM, frame: *CallFrame, slot: u16) []const u8 {
        const names = if (frame.func) |func| func.slot_names else self.global_slot_names;
        return if (slot < names.len) names[slot] else "";
    }

    // separate a referenced variable's array before an in-place write. the
    // array is shared by every alias of its reference set (the cell, each
    // registered mirror, each bound frame slot) and mutates in place for
    // them; it separates only when the refcount exceeds the alias count,
    // meaning a value copy also holds it. the clone's reference moves into
    // the cell, every mirror follows through propagation, and this frame's
    // own binding (slot + vars mirror, one owner) takes its own reference
    fn separateReferencedArray(self: *VM, frame: *CallFrame, name: []const u8, cell: *Value, arr: *PhpArray) RuntimeError!?*PhpArray {
        if (arr.refcount - arr.byref_pins <= self.referenceAliasCount(cell)) return null;
        const clone = try self.shallowCloneCow(arr);
        const sv = Value{ .array = clone };
        self.setCell(cell, sv);
        try self.propagateCellWrite(cell, sv);
        if (isSuperglobal(name) and self.globals_cells.get(name) == cell) return clone;
        retainValue(sv);
        const names = if (frame.func) |func| func.slot_names else self.global_slot_names;
        var slot: ?usize = null;
        for (names, 0..) |candidate, si| {
            if (std.mem.eql(u8, candidate, name)) {
                slot = si;
                break;
            }
        }
        if (frame.vars.getPtr(name)) |vp| {
            self.releaseValue(vp.*);
            vp.* = sv;
        } else if (slot) |si| {
            if (si < frame.locals.len) self.releaseValue(frame.locals[si]);
        }
        if (slot) |si| {
            if (si < frame.locals.len) frame.locals[si] = sv;
        }
        return clone;
    }

    // a name just bound to a reference cell mirrors the cell's value. the
    // mirror owns one reference, shared by the slot and its vars entry, and
    // drops the one it held before
    fn mirrorBoundName(self: *VM, frame: *CallFrame, name: []const u8, bound: Value) RuntimeError!void {
        var slot: ?usize = null;
        if (frame.func) |func| for (func.slot_names, 0..) |sn, si| {
            if (std.mem.eql(u8, sn, name)) {
                if (si < frame.locals.len) slot = si;
                break;
            }
        };
        const names_in_slots = slot != null and frame.func.?.locals_only and frame.vars.count() == 0;
        const mirror_vars = (name.len == 0 or name[0] != 0) and !names_in_slots;
        if (!mirror_vars and slot == null) return;
        // a var, so the slot store below cannot alias it
        var old: Value = .null;
        if (mirror_vars) {
            if (frame.vars.get(name)) |held| old = held else if (slot) |si| old = frame.locals[si];
        } else if (slot) |si| old = frame.locals[si];
        retainValue(bound);
        if (mirror_vars) try self.putFrameVar(&frame.vars, name, bound);
        if (slot) |si| frame.locals[si] = bound;
        self.releaseValue(old);
    }

    // a read of a variable that holds nothing: php warns "Undefined variable",
    // except for $this outside an object (an Error) and an argument the callee
    // takes by reference, which creates the variable
    fn undefinedVariableRead(self: *VM, name: []const u8) RuntimeError!void {
        // the compiler's own locals start out empty by design
        for ([_][]const u8{ "$__closure_context", "$__closure_scope", "$__closure_defclass", "$__ret_ref" }) |internal| {
            if (std.mem.eql(u8, name, internal)) return;
        }
        if (std.mem.eql(u8, name, "$this")) {
            try self.setPendingException("Error", "Using $this when not in object context");
            return error.RuntimeError;
        }
        if (self.nextArgIsByRef()) return;
        const msg = try std.fmt.allocPrint(self.allocator, "Undefined variable {s}", .{name});
        defer self.allocator.free(msg);
        try self.emitWarning(msg);
    }

    // the read is the argument an arg_variable right after it passes by
    // reference
    fn nextArgIsByRef(self: *VM) bool {
        const frame = self.currentFrame();
        const code = frame.chunk.code.items;
        if (frame.ip >= code.len or code[frame.ip] != @intFromEnum(OpCode.arg_variable)) return false;
        const field = frame.ip + 3;
        if (field + 2 >= code.len) return false;
        const delta = (@as(u16, code[field]) << 8) | code[field + 1];
        // the value isn't on the stack yet
        return self.argNeedsCapture(frame.chunk, field, delta, code[field + 2], 0);
    }

    // a local's value for a write that builds on it ($x[] = 1): one that holds
    // nothing is null, without a warning
    fn loadLocalSlot(self: *VM, frame: *CallFrame, slot: u16, ref_cell: ?*Value) Value {
        if (ref_cell) |cell| return cell.*;
        const value = if (frame.func == null) self.getLocalGlobal(slot, frame) else if (slot < frame.locals.len) frame.locals[slot] else Value.undef;
        return if (value == .undef) .null else value;
    }

    fn getLocalGlobal(self: *VM, slot: u16, frame: *CallFrame) Value {
        if (slot < self.global_slot_names.len and self.global_slot_names[slot].len > 0) {
            if (frame.ref_slots.count() > 0) {
                if (frame.ref_slots.get(self.global_slot_names[slot])) |cell| {
                    return cell.*;
                }
            }
        }
        if (slot < frame.locals.len) {
            const val = frame.locals[slot];
            if (val != .null and val != .undef) return val;
            if (slot < self.global_slot_names.len and self.global_slot_names[slot].len > 0) {
                if (frame.vars.get(self.global_slot_names[slot])) |v| {
                    frame.locals[slot] = v;
                    return v;
                }
            }
            return val;
        }
        return .undef;
    }

    // store a value back into a local slot (function or global frame),
    // mirroring set_local's destinations: the ref cell if bound, frame.vars by
    // name, and the locals array. used by the COW separation sites to rebind a
    // variable to its freshly-separated array
    // the slot takes the reference `val` carries; the value it held before is
    // released once (vars entry and local slot share one reference)
    fn storeLocalSlot(self: *VM, frame: *CallFrame, slot: u16, val: Value) !void {
        if (frame.func) |func| {
            var released_old = false;
            if (slot < func.slot_names.len) {
                const name = func.slot_names[slot];
                if (name.len > 0) {
                    if (frame.ref_slots.get(name)) |cell| self.setCell(cell, val);
                    const old = try frame.vars.fetchPut(self.allocator, name, val);
                    if (old) |kv| {
                        self.releaseValue(kv.value);
                        released_old = true;
                    }
                }
            }
            if (slot < frame.locals.len) {
                if (!released_old) self.releaseValue(frame.locals[slot]);
                frame.locals[slot] = val;
            }
        } else {
            if (slot < frame.locals.len) {
                self.releaseValue(frame.locals[slot]);
                frame.locals[slot] = val;
            }
            try self.setLocalGlobal(slot, val, frame);
        }
        try self.syncIncludeLocal(frame, slot, val);
    }

    // assign one owned reference to a named variable of `frame`, the way
    // set_local / set_var_var do: a slot and its vars mirror share the one
    // reference, a bound reference cell takes its own and propagates
    pub fn setVariableByName(self: *VM, frame: *CallFrame, name: []const u8, val: Value) RuntimeError!void {
        const slot_names = if (frame.func) |func| func.slot_names else frame.slot_names;
        for (slot_names, 0..) |slot_name, si| {
            if (!std.mem.eql(u8, slot_name, name)) continue;
            if (si < frame.locals.len) {
                const slot: u16 = @intCast(si);
                if (frame.func != null) {
                    if (frame.ref_slots.get(name)) |cell| try self.propagateCellWrite(cell, val);
                    try self.storeLocalSlot(frame, slot, val);
                } else if (frame.include_parent != null) {
                    if (frame.ref_slots.get(name)) |cell| {
                        self.setCell(cell, val);
                        try self.propagateCellWrite(cell, val);
                    }
                    if (try self.fetchPutFrameVar(&frame.vars, name, val)) |old| {
                        self.releaseValue(old.value);
                    } else self.releaseValue(frame.locals[slot]);
                    frame.locals[slot] = val;
                    try self.syncIncludeLocal(frame, slot, val);
                } else {
                    self.releaseValue(frame.locals[slot]);
                    frame.locals[slot] = val;
                    try self.setLocalGlobal(slot, val, frame);
                }
                return;
            }
            break;
        }
        if (frame.ref_slots.get(name)) |cell| {
            self.setCell(cell, val);
            try self.propagateCellWrite(cell, val);
        }
        const old = try self.fetchPutFrameVar(&frame.vars, name, val);
        if (old) |kv| self.releaseValue(kv.value);
        try self.syncIncludeVar(frame, name, val);
    }

    // an include frame runs with no function, but its variables are global
    // only when the chain of includes started at the script frame
    fn frameInGlobalScope(self: *const VM, frame: *const CallFrame) bool {
        var current = frame;
        while (current.include_parent) |parent_idx| current = &self.frames[parent_idx];
        return current.func == null;
    }

    // what set_local does with the value on top of the stack: the slot, its
    // vars mirror, a bound reference cell, the globals, an including scope
    fn assignLocal(self: *VM, frame: *CallFrame, slot: u16, peeked_in: Value) RuntimeError!void {
        var peeked = peeked_in;
        if (frame.ref_slots.count() != 0) peeked = try self.checkTypedSlotWrite(frame, slot, peeked);
        // copyValue clones arrays and retains objects (Stage 1) - the local
        // slot is a durable holder and needs its own ref
        const val = try self.copyValue(peeked);
        if (slot < frame.locals.len) {
            // overwrite-release: the slot is a mirror that owns its value
            // even when a reference cell is bound to it. named locals and
            // frame.vars are two views of one owning binding; copyValue
            // retained once, release once here
            const old_lv = frame.locals[slot];
            self.releaseValue(old_lv);
            frame.locals[slot] = val;
        }
        if (frame.func) |func| {
            if (slot < func.slot_names.len) {
                const name = func.slot_names[slot];
                if (name.len > 0) {
                    if (frame.ref_slots.get(name)) |cell| {
                        self.setCell(cell, val);
                        try self.propagateCellWrite(cell, val);
                    }
                    // a locals-only frame keeps names only in its slots until
                    // something by-name (extract, $$name) starts a mirror
                    if (!func.locals_only or frame.vars.count() > 0) try self.putFrameVar(&frame.vars, name, val);
                }
            }
        } else {
            try self.setLocalGlobal(slot, val, frame);
        }
        try self.syncIncludeLocal(frame, slot, val);
    }

    // a write to a variable bound to a reference that typed properties hold
    // is checked against them, and coerced, before any view of the variable
    // changes. the coerced value replaces the operand on top of the stack,
    // which is the assignment's result
    fn checkTypedSlotWrite(self: *VM, frame: *CallFrame, slot: u16, val: Value) RuntimeError!Value {
        const cell = self.slotRefCell(frame, slot) orelse return val;
        if (!cellOf(cell).typed) return val;
        const checked = try self.verifyRefAssignable(cell, val);
        if (!Value.identical(checked, val) or @intFromEnum(checked) != @intFromEnum(val)) {
            if (self.sp > 0 and Value.identical(self.stack[self.sp - 1], val)) self.replaceOwned(&self.stack[self.sp - 1], checked);
        }
        return checked;
    }

    // checkTypedSlotWrite for a variable written by name
    fn checkTypedNameWrite(self: *VM, frame: *CallFrame, name: []const u8) RuntimeError!void {
        if (frame.ref_slots.count() == 0) return;
        const cell = frame.ref_slots.get(name) orelse return;
        if (!cellOf(cell).typed) return;
        const top = &self.stack[self.sp - 1];
        const checked = try self.verifyRefAssignable(cell, top.*);
        if (@intFromEnum(checked) != @intFromEnum(top.*) or !Value.identical(checked, top.*)) self.replaceOwned(top, checked);
    }

    // `$local .= value`: grows the string in place when the variable is its
    // only holder, otherwise builds a new one; either way the result is
    // assigned the way set_local assigns and left on the stack
    // an object operand of `.=` as its string, a new reference the caller
    // releases; null for anything else
    fn objectConcatOperand(self: *VM, v: Value) RuntimeError!?Value.String {
        if (v != .object) return null;
        return try Value.String.create(self.stringAllocator(), try self.objectToString(v.object));
    }

    fn concatAssignLocal(self: *VM, frame: *CallFrame, slot: u16, append_val: Value) RuntimeError!void {
        var current = try self.fusedRead(frame, slot);
        const current_text = try self.objectConcatOperand(current);
        defer if (current_text) |t| t.release();
        if (current_text) |t| current = .{ .string = t };
        var suffix_buf: [128]u8 = undefined;
        var suffix_allocator: std.heap.BufferFirstAllocator = .init(&suffix_buf, self.allocator);
        const temporary_allocator = suffix_allocator.allocator();
        var suffix: std.ArrayListUnmanaged(u8) = .empty;
        defer suffix.deinit(temporary_allocator);
        if (append_val == .string) {
            try suffix.appendSlice(temporary_allocator, append_val.string.bytes());
        } else if (append_val == .object) {
            try suffix.appendSlice(temporary_allocator, try self.objectToString(append_val.object));
        } else try append_val.format(&suffix, temporary_allocator);
        if (current == .string and current_text == null and self.localCell(frame, slot) == null) {
            if (current.string.owner) |owner| {
                if (owner.refcount == 1 and current.string.ptr == owner.bytes.ptr) {
                    const length = std.math.add(usize, current.string.len, suffix.items.len) catch return error.OutOfMemory;
                    if (length > owner.bytes.len) {
                        const growth = std.math.add(usize, owner.bytes.len / 2, 16) catch return error.OutOfMemory;
                        const capacity = @max(length, std.math.add(usize, owner.bytes.len, growth) catch length);
                        owner.bytes = try owner.allocator.realloc(owner.bytes, capacity);
                    }
                    @memcpy(owner.bytes[current.string.len..length], suffix.items);
                    owner.utf8_valid = false;
                    self.push(.{ .string = .{ .ptr = owner.bytes.ptr, .len = length, .owner = owner } });
                    return self.assignLocal(frame, slot, self.peek());
                }
            }
        }
        var buffer: std.ArrayListUnmanaged(u8) = .empty;
        errdefer buffer.deinit(self.stringAllocator());
        if (current == .string) {
            try buffer.appendSlice(self.stringAllocator(), current.string.bytes());
        } else if (current != .null) try current.format(&buffer, self.stringAllocator());
        try buffer.appendSlice(self.stringAllocator(), suffix.items);
        self.pushTransfer(.{ .string = try Value.String.adopt(self.stringAllocator(), try buffer.toOwnedSlice(self.stringAllocator())) });
        return self.assignLocal(frame, slot, self.peek());
    }

    // the reference cell bound to a local, if any
    fn localCell(self: *VM, frame: *CallFrame, slot: u16) ?*Value {
        _ = self;
        const names = if (frame.func) |func| func.slot_names else frame.slot_names;
        if (slot >= names.len or names[slot].len == 0 or frame.ref_slots.count() == 0) return null;
        return frame.ref_slots.get(names[slot]);
    }

    // a fused local op may touch the slots directly only when the frame's
    // variables live nowhere else: no reference cells, no named mirror, not
    // the global scope
    fn plainLocals(frame: *const CallFrame) bool {
        return frame.func != null and frame.ref_slots.count() == 0 and frame.vars.count() == 0;
    }

    // a local as get_local reads it
    // a local's value for an operation that reads it ($x++, $x .= y, $a < $b):
    // one that holds nothing warns and reads as null
    fn fusedRead(self: *VM, frame: *CallFrame, slot: u16) RuntimeError!Value {
        const value = blk: {
            if (frame.func) |func| {
                if (slot < func.slot_names.len and func.slot_names[slot].len > 0) {
                    if (frame.ref_slots.get(func.slot_names[slot])) |cell| return cell.*;
                }
                break :blk if (slot < frame.locals.len) frame.locals[slot] else Value.undef;
            }
            break :blk self.getLocalGlobal(slot, frame);
        };
        if (value != .undef) return value;
        try self.undefinedVariableRead(self.slotName(frame, slot));
        return .null;
    }

    // `$x++;` / `$x--;` as the unfused get_local, inc_value, set_local, pop
    // true when a thrown TypeError was caught
    fn fusedStep(self: *VM, frame: *CallFrame, slot: u16, up: bool) RuntimeError!bool {
        const v = try self.fusedRead(frame, slot);
        VM.stackRetain(v);
        const stepped = self.stepValue(v, up) catch |err| {
            self.stackRelease(v);
            return err;
        };
        self.stackRelease(v);
        const result = stepped orelse return true;
        self.push(result);
        if (result == .string and result.string.owner != null) self.releaseValue(result);
        try self.assignLocal(frame, slot, self.peek());
        _ = self.pop();
        return false;
    }

    // php's ++ and --, with the warning for operands they leave alone and the
    // TypeError for ones they cannot step. null when that TypeError was caught
    pub fn stepValue(self: *VM, v: Value, up: bool) RuntimeError!?Value {
        const verb = if (up) "increment" else "decrement";
        switch (v) {
            .null => if (!up) {
                self.emitWarning("Decrement on type null has no effect, this will change in the next major version of PHP") catch return if (try self.resumeRaised()) null else unreachable;
                return .null;
            },
            .bool => {
                const msg = if (up) "Increment on type bool has no effect, this will change in the next major version of PHP" else "Decrement on type bool has no effect, this will change in the next major version of PHP";
                self.emitWarning(msg) catch return if (try self.resumeRaised()) null else unreachable;
                return v;
            },
            .string => |str| {
                const numeric = str.len > 0 and Value.isNumericString(str.bytes());
                if (up) {
                    // a perl-style string increment, "" included
                    if (!numeric) self.raiseError(E_DEPRECATED, "Increment on non-numeric string is deprecated, use str_increment() instead") catch return if (try self.resumeRaised()) null else unreachable;
                } else if (str.len == 0) {
                    self.raiseError(E_DEPRECATED, "Decrement on empty string is deprecated as non-numeric") catch return if (try self.resumeRaised()) null else unreachable;
                    return .{ .int = -1 };
                } else if (!numeric) {
                    self.raiseError(E_DEPRECATED, "Decrement on non-numeric string has no effect and is deprecated") catch return if (try self.resumeRaised()) null else unreachable;
                    // callers release a stepped string once they have stored
                    // it, so the unchanged one is handed back with its own count
                    VM.retainValue(v);
                    return v;
                }
            },
            .array, .resource => return self.throwStepError(verb, Value.typeName(v)),
            .object => |obj| {
                const overloaded = self.objectBinop(if (up) .add else .sub, v, .{ .int = 1 }) catch return if (try self.resumeRaised()) null else unreachable;
                if (overloaded) |r| return r;
                return self.throwStepError(verb, obj.class_name);
            },
            .int => |i| if (i == @as(i64, if (up) std.math.maxInt(i64) else std.math.minInt(i64))) {
                if (self.ic) |ic| ic.step_overflow = .{ .up = up, .frame = self.frame_count, .ip = self.currentFrame().ip };
            },
            else => {},
        }
        return if (up) try Value.phpInc(v, self.allocator) else Value.phpDec(v);
    }

    // the overflowing ++/-- whose result the running write stores: the write
    // is the instruction right after inc_value/dec_value (past a swap), or
    // the fused inc_local itself
    fn takeStepOverflow(self: *VM) ?bool {
        const ic = self.ic orelse return null;
        const rec = ic.step_overflow;
        ic.step_overflow = .{};
        const up = rec.up orelse return null;
        if (rec.frame != self.frame_count) return null;
        const frame = self.currentFrame();
        if (frame.ip == rec.ip) return up;
        const code = frame.chunk.code.items;
        var at = rec.ip;
        if (at < code.len and code[at] == @intFromEnum(OpCode.swap)) at += 1;
        if (at >= code.len) return null;
        const next: OpCode = @enumFromInt(code[at]);
        return if (at + next.width() == frame.ip) up else null;
    }

    fn throwIncdecRef(self: *VM, src: TypeSource, up: bool) RuntimeError {
        const msg = std.fmt.allocPrint(self.allocator, "Cannot {s} a reference held by property {s}::${s} of type {s} past its {s} value", .{ if (up) "increment" else "decrement", src.class, src.prop, try self.propertyTypeText(src.type_str, src.class), if (up) "maximal" else "minimal" }) catch return error.RuntimeError;
        defer self.allocator.free(msg);
        try self.setPendingException("TypeError", msg);
        return error.RuntimeError;
    }

    fn throwStepError(self: *VM, verb: []const u8, type_name: []const u8) RuntimeError!?Value {
        const msg = try std.fmt.allocPrint(self.allocator, "Cannot {s} {s}", .{ verb, type_name });
        defer self.allocator.free(msg);
        if (try self.throwBuiltinException("TypeError", msg)) return null;
        return error.RuntimeError;
    }

    const FusedArith = struct { op: NativeBinop, src: u16, dst: u16, base_frame: usize };

    // `$dst op= $src;` as the unfused loads, arithmetic, set_local and pop.
    // true when an exception was dispatched
    fn fusedArith(self: *VM, frame: *CallFrame, f: FusedArith) RuntimeError!bool {
        // php reads the right operand before the variable it assigns to
        const b = try self.fusedRead(frame, f.src);
        const a = try self.fusedRead(frame, f.dst);
        if (f.op == .add and a == .array and b == .array) {
            self.push(.{ .array = try self.arrayUnion(a.array, b.array) });
        } else {
            const handlers_before = self.handler_count;
            const overloaded = self.objectBinop(f.op, a, b) catch {
                if (self.resumeAfterThrow(f.base_frame, handlers_before)) return true;
                return error.RuntimeError;
            };
            if (overloaded) |r| {
                self.push(r);
            } else {
                const unsupported = switch (f.op) {
                    .add => try self.checkArithOperands(a, b, "+"),
                    .sub => try self.checkArithOperands(a, b, "-"),
                    else => try self.checkArithOperands(a, b, "*"),
                };
                if (unsupported) return true;
                self.push(switch (f.op) {
                    .add => Value.add(a, b),
                    .sub => Value.subtract(a, b),
                    else => Value.multiply(a, b),
                });
            }
        }
        try self.assignLocal(frame, f.dst, self.peek());
        _ = self.pop();
        return false;
    }

    fn setLocalGlobal(self: *VM, slot: u16, val: Value, frame: *CallFrame) !void {
        if (slot < self.global_slot_names.len) try self.syncGlobalName(frame, self.global_slot_names[slot], val);
        self.global_vars_dirty = true;
    }

    // a global-scope variable's other views: a bound reference cell, the
    // named mirror, $GLOBALS, and the cell `global $name` binds in functions
    fn syncGlobalName(self: *VM, frame: *CallFrame, name: []const u8, val: Value) !void {
        if (name.len == 0) return;
        if (frame.ref_slots.count() > 0) {
            if (frame.ref_slots.get(name)) |cell| {
                self.setCell(cell, val);
                try self.propagateCellWrite(cell, val);
            }
        }
        try self.putFrameVar(&frame.vars, name, val);
        if (!self.frameInGlobalScope(frame)) return;
        // $GLOBALS is a live view of top-frame variables. mirror writes
        // back so $GLOBALS[$key] picks up the new value
        if (self.globals_array) |ga| {
            if (name.len > 1 and name[0] == '$') {
                // $GLOBALS is a NON-OWNING live view: the same logical
                // variable is reachable via frame.vars AND this mirror,
                // so the mirror must NOT contribute to the array's COW
                // refcount (else every global-scope array write sees
                // refcount>1 and spuriously separates - which breaks
                // destruct timing + recursion-marker identity). set()
                // retains, so undo it; don't release the prior entry
                // (the variable-slot overwrite owns that release). the
                // cycle GC compensates by treating globals_array's own
                // entries as roots, not scanned references
                try ga.set(self.allocator, .{ .string = Value.String.borrowed(name[1..]) }, val);
            }
        }
        // keep the shared global-cell (used by `global $name` inside
        // functions) in sync with the top-frame write
        if (self.globals_cells.get(name)) |cell| {
            self.setCell(cell, val);
        }
    }

    // bring every view of the top script slots the fast loop wrote up to date
    pub fn flushTopWrites(self: *VM) void {
        const ic = self.ic orelse return;
        if (!ic.top_dirty_any) return;
        ic.top_dirty_any = false;
        const frame = &self.frames[0];
        var it = ic.top_dirty.iterator(.{});
        while (it.next()) |slot| {
            if (slot < frame.locals.len and slot < self.top_slot_names.len) {
                self.syncGlobalName(frame, self.top_slot_names[slot], frame.locals[slot]) catch {};
            }
        }
        ic.top_dirty.unsetAll();
        self.global_vars_dirty = true;
    }

    // propagate a write to $GLOBALS[$key] into every frame that has `global $key`
    // declared (including the top frame). PHP models $GLOBALS as a live view of
    // the global table, so a write must be visible to every active `global`
    // binding, not just the top-level script frame.
    fn mirrorGlobalsWrite(self: *VM, key: []const u8, val: Value) RuntimeError!void {
        const dollar_name = try self.internVarName(key);
        if (isSuperglobal(dollar_name)) {
            try self.putRequestVar(dollar_name, val);
            return;
        }

        // top frame: vars + locals (slot lookup via top_slot_names — must
        // not use global_slot_names because it's overridden inside require)
        if (self.frame_count > 0) try self.putGlobalVar(dollar_name, val);

        // a global that is a reference: the write goes through it to every
        // other name for the same storage
        if (self.frame_count > 0) if (self.frames[0].ref_slots.get(dollar_name)) |cell| {
            // the cell's own mirror in $GLOBALS writes back here: once is enough
            if (self.globals_cells.get(dollar_name) != cell and !sameReferent(cell.*, val)) {
                self.setCell(cell, val);
                try self.propagateCellWrite(cell, val);
            }
        };

        // shared global cell - so `global $key` inside any function picks
        // up writes done through $GLOBALS at the top level
        if (self.globals_cells.get(dollar_name)) |cell| {
            self.setCell(cell, val);
        }

        // any function frame with an active `global $key` declaration
        for (self.global_vars.items) |entry| {
            if (!std.mem.eql(u8, entry.var_name, dollar_name)) continue;
            if (entry.frame_depth == 0 or entry.frame_depth > self.frame_count) continue;
            const frame = &self.frames[entry.frame_depth - 1];
            if (frame == &self.frames[0]) continue;
            retainValue(val);
            const old = try frame.vars.fetchPut(self.allocator, dollar_name, val);
            if (old) |kv| self.releaseValue(kv.value);
            if (frame.func) |func| {
                for (func.slot_names, 0..) |sn, i| {
                    if (std.mem.eql(u8, sn, dollar_name)) {
                        if (i < frame.locals.len) frame.locals[i] = val;
                        break;
                    }
                }
            }
        }
    }

    fn syncGlobalLocalsToVars(self: *VM) !void {
        if (!self.global_vars_dirty) return;
        self.global_vars_dirty = false;
        const frame = &self.frames[0];
        for (self.top_slot_names, 0..) |name, i| {
            // a variable that holds nothing has no entry: it isn't defined
            if (name.len > 0 and i < frame.locals.len and frame.locals[i] != .undef) {
                try self.putFrameVar(&frame.vars, name, frame.locals[i]);
            }
        }
    }

    fn writebackGlobals(self: *VM) !void {
        var i: usize = 0;
        while (i < self.global_vars.items.len) {
            const entry = self.global_vars.items[i];
            if (entry.frame_depth == self.frame_count) {
                const val = try self.copyValue(self.currentFrame().vars.get(entry.var_name) orelse .null);
                try self.putGlobalVarOwned(entry.var_name, val);
                for (self.top_slot_names, 0..) |sn, si| {
                    if (std.mem.eql(u8, sn, entry.var_name)) {
                        if (si < self.frames[0].locals.len) self.frames[0].locals[si] = val;
                        break;
                    }
                }
                _ = self.global_vars.swapRemove(i);
            } else {
                i += 1;
            }
        }
    }

    // a value's string form for use right away: the bytes last until the next
    // statement boundary
    // pops a name operand, keeping its reference in `hold` for the caller to
    // release once the bytes are no longer used
    fn popHeldName(self: *VM, hold: *Value) RuntimeError![]const u8 {
        hold.* = self.popTransfer();
        return self.valueToString(hold.*);
    }

    fn valueToString(self: *VM, v: Value) RuntimeError![]const u8 {
        if (v == .string) return v.string.bytes();
        if (v == .object) return self.objectToString(v.object);
        if (v == .array) try self.emitWarning("Array to string conversion");
        return (try self.transientFormatted(v)).bytes();
    }

    // an object's string form for use right away: the bytes last until the
    // next statement boundary
    pub fn objectToString(self: *VM, obj: *PhpObject) RuntimeError![]const u8 {
        return self.transientOwned(try self.objectString(obj)).bytes();
    }

    // what an object's __toString returns, as a reference the caller owns
    pub fn objectString(self: *VM, obj: *PhpObject) RuntimeError!Value.String {
        const method_name = self.resolveMethod(obj.class_name, "__toString") catch {
            // PHP: 'Object of class X could not be converted to string'.
            // throw a catchable Error so user code wrapping the access in
            // try/catch can recover; non-catching code falls through to a
            // runtime error like any other uncaught exception
            const msg = try std.fmt.allocPrint(self.allocator, "Object of class {s} could not be converted to string", .{obj.class_name});
            defer self.allocator.free(msg);
            try self.setPendingException("Error", msg);
            return error.RuntimeError;
        };
        if (self.functions.get(method_name)) |func| {
            var new_vars = self.acquireFrameVars();
            try new_vars.put(self.allocator, "$this", .{ .object = obj });
            try self.ensureCallRoom();
            self.frames[self.frame_count] = .{ .chunk = &func.chunk, .ip = 0, .vars = new_vars, .locals = try self.allocLocals(func, &new_vars), .func = func };
            self.frames[self.frame_count].entry_sp = self.sp;
            self.saveFrameArgs(0);
            self.setFrameArgCount(0);
            self.frame_count += 1;
            self.retainFrameObjects(self.frame_count - 1);
            if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;
            try self.runUntilFrame(self.frame_count - 1);
            return self.ownedString(self.popTransfer());
        }
        if (self.native_fns.get(method_name)) |native| {
            const prev_this = self.currentFrame().vars.get("$this");
            try self.putFrameVar(&self.currentFrame().vars, "$this", .{ .object = obj });
            defer {
                if (prev_this) |pt| {
                    self.putFrameVar(&self.currentFrame().vars, "$this", pt) catch {};
                } else {
                    _ = self.currentFrame().vars.remove("$this");
                }
            }
            var ctx = self.makeContext(null);
            return self.ownedString(try self.invokeNative(native, &ctx, .{ .args = &.{}, .label = method_name, .instance = true }));
        }
        return Value.String.borrowed("Object");
    }

    // an owned value as an owned string: a string is handed over, anything
    // else is formatted and released
    fn ownedString(self: *VM, v: Value) RuntimeError!Value.String {
        if (v == .string) return v.string;
        defer self.stackRelease(v);
        var buf = std.ArrayListUnmanaged(u8).empty;
        errdefer buf.deinit(self.allocator);
        try v.format(&buf, self.allocator);
        return Value.String.adopt(self.allocator, try buf.toOwnedSlice(self.allocator));
    }

    // gives up an owned string's reference to the statement-boundary drain:
    // the bytes stay valid until then, and whatever stores the string first
    // keeps it alive
    pub fn transientOwned(self: *VM, str: Value.String) Value.String {
        if (str.releaseDeferred()) |owner| self.queueStringRelease(owner);
        return str;
    }

    // a copy of bytes as a transient
    pub fn transientBytes(self: *VM, bytes: []const u8) RuntimeError!Value.String {
        return self.transientOwned(try Value.String.create(self.allocator, bytes));
    }

    pub fn mapPharAlias(self: *VM, alias: []const u8, path: []const u8) RuntimeError!void {
        const owned_path = try self.allocator.dupe(u8, path);
        errdefer self.allocator.free(owned_path);
        const gop = try self.phar_aliases.getOrPut(self.allocator, alias);
        if (gop.found_existing) {
            self.allocator.free(gop.value_ptr.*);
        } else {
            gop.key_ptr.* = self.allocator.dupe(u8, alias) catch |err| {
                self.phar_aliases.removeByPtr(gop.key_ptr);
                return err;
            };
        }
        gop.value_ptr.* = owned_path;
    }

    fn clearStreamWrappers(self: *VM) void {
        @import("../stdlib/filesystem.zig").resetStreamState();
        for (self.stream_wrappers.keys(), self.stream_wrappers.values()) |k, v| {
            self.allocator.free(k);
            if (v.class) |c| self.allocator.free(c);
        }
        self.stream_wrappers.clearRetainingCapacity();
        self.stream_wrappers_ready = false;
        for (self.stream_filters_user.keys(), self.stream_filters_user.values()) |k, v| {
            self.allocator.free(k);
            self.allocator.free(v);
        }
        self.stream_filters_user.clearRetainingCapacity();
    }

    fn clearPharAliases(self: *VM) void {
        var it = self.phar_aliases.iterator();
        while (it.next()) |e| {
            self.allocator.free(e.key_ptr.*);
            self.allocator.free(e.value_ptr.*);
        }
        self.phar_aliases.clearRetainingCapacity();
    }

    // a null-terminated copy for a C call, valid until the next statement
    // boundary
    pub fn transientZ(self: *VM, bytes: []const u8) RuntimeError![:0]const u8 {
        const buf = try self.allocator.allocSentinel(u8, bytes.len, 0);
        @memcpy(buf, bytes);
        const str = self.transientOwned(try Value.String.adopt(self.allocator, buf.ptr[0 .. bytes.len + 1]));
        return str.bytes()[0..bytes.len :0];
    }

    // bytes the caller owns, handed over as a transient
    pub fn transientAdopted(self: *VM, bytes: []u8) RuntimeError!Value.String {
        return self.transientOwned(try Value.String.adopt(self.allocator, bytes));
    }

    pub fn transientFormatted(self: *VM, v: Value) RuntimeError!Value.String {
        var buf = std.ArrayListUnmanaged(u8).empty;
        errdefer buf.deinit(self.allocator);
        try v.format(&buf, self.allocator);
        return self.transientOwned(try Value.String.adopt(self.allocator, try buf.toOwnedSlice(self.allocator)));
    }

    // opcode handlers (extracted from runLoop for readability)

    fn handleClassDecl(self: *VM) RuntimeError!void {
        const class_modifiers = self.readByte();
        const name_idx = self.readU16();
        const class_name = self.currentChunk().constants.items[name_idx].string.bytes();
        defer inheritance.dropTraitDeferred(self, class_name);
        if (!class_names.isAnonymous(class_name)) try self.refuseRedeclaration(class_name);
        // PHP reserves the type keywords as class names
        {
            const reserved = [_][]const u8{ "int", "float", "bool", "string", "true", "false", "null", "void", "iterable", "object", "mixed", "never", "self", "parent" };
            for (reserved) |r| {
                if (std.ascii.eqlIgnoreCase(class_name, r)) {
                    const msg = try std.fmt.allocPrint(self.allocator, "Cannot use \"{s}\" as a class name as it is reserved", .{class_name});
                    try self.strings.append(self.allocator, msg);
                    self.error_msg = msg;
                    return error.RuntimeError;
                }
            }
        }
        const start_line = self.readU32();
        const end_line = self.readU32();
        const doc_idx = self.readU16();
        const method_count = self.readU16();

        var def = ClassDef{ .name = class_name, .is_internal = false };
        // a declaration that fails before the class is registered frees it
        var registered = false;
        errdefer if (!registered) def.deinit(self.allocator);
        def.is_abstract = (class_modifiers & 1) != 0;
        def.is_final = (class_modifiers & 2) != 0;
        def.is_readonly = (class_modifiers & 4) != 0;
        // prefer the executing frame's script_path so classes declared in
        // required files report the right file via Reflection. fall back to
        // the VM's top-level file_path for the main script
        def.file_path = blk: {
            if (self.frame_count > 0) {
                const sp = self.currentFrame().script_path;
                if (sp.len > 0) break :blk sp;
            }
            break :blk self.file_path;
        };
        def.start_line = start_line;
        def.end_line = end_line;
        if (doc_idx != 0xffff) def.doc_comment = self.currentChunk().constants.items[doc_idx].string.bytes();

        for (0..method_count) |_| {
            const mi = self.readMethodInfo();
            try def.addMethod(self.allocator, mi[1]);
        }

        const prop_count = self.readU16();
        const prop_names = try self.allocator.alloc([]const u8, prop_count);
        const prop_has_default = try self.allocator.alloc(u8, prop_count);
        const prop_vis = try self.allocator.alloc(ClassDef.Visibility, prop_count);
        const prop_set_vis = try self.allocator.alloc(ClassDef.Visibility, prop_count);
        const prop_has_set_vis = try self.allocator.alloc(bool, prop_count);
        const prop_readonly = try self.allocator.alloc(bool, prop_count);
        const prop_virtual = try self.allocator.alloc(bool, prop_count);
        defer self.allocator.free(prop_virtual);
        const prop_final = try self.allocator.alloc(bool, prop_count);
        const prop_promoted = try self.allocator.alloc(bool, prop_count);
        const prop_type = try self.allocator.alloc([]const u8, prop_count);
        const prop_doc = try self.allocator.alloc([]const u8, prop_count);
        const prop_origin = try self.allocator.alloc([]const u8, prop_count);
        defer self.allocator.free(prop_origin);
        const prop_hooked = try self.allocator.alloc(bool, prop_count);
        defer self.allocator.free(prop_hooked);

        defer self.allocator.free(prop_names);
        defer self.allocator.free(prop_has_default);
        defer self.allocator.free(prop_vis);
        defer self.allocator.free(prop_set_vis);
        defer self.allocator.free(prop_has_set_vis);
        defer self.allocator.free(prop_readonly);
        defer self.allocator.free(prop_final);
        defer self.allocator.free(prop_promoted);
        defer self.allocator.free(prop_type);
        defer self.allocator.free(prop_doc);

        for (0..prop_count) |pi| {
            const pname_idx = self.readU16();
            prop_names[pi] = self.currentChunk().constants.items[pname_idx].string.bytes();
            const default_flags = self.readByte();
            prop_has_default[pi] = default_flags & 1;
            prop_virtual[pi] = (default_flags & 2) != 0;

            const vis_byte = self.readByte();

            prop_vis[pi] = @enumFromInt(vis_byte & 0x03);
            prop_readonly[pi] = (vis_byte & 0x04) != 0;

            const has_asymm = (vis_byte & 0x20) != 0;
            prop_has_set_vis[pi] = has_asymm;

            prop_set_vis[pi] = if (has_asymm)
                @enumFromInt((vis_byte >> 3) & 0x03)
            else
                prop_vis[pi];

            prop_promoted[pi] = (vis_byte & 0x40) != 0;
            prop_final[pi] = (vis_byte & 0x80) != 0;

            const type_idx = self.readU16();
            prop_type[pi] = if (type_idx == 0xffff)
                ""
            else
                self.currentChunk().constants.items[type_idx].string.bytes();

            const doc_idx_p = self.readU16();
            prop_doc[pi] = if (doc_idx_p == 0xffff)
                ""
            else
                self.currentChunk().constants.items[doc_idx_p].string.bytes();
            prop_origin[pi] = if ((default_flags & 4) != 0) self.currentChunk().constants.items[self.readU16()].string.bytes() else "";
            prop_hooked[pi] = (default_flags & 8) != 0;
        }

        const static_prop_count = self.readU16();
        const sprop_names = try self.allocator.alloc([]const u8, static_prop_count);
        const sprop_has_default = try self.allocator.alloc(u8, static_prop_count);
        const sprop_is_const = try self.allocator.alloc(u8, static_prop_count);
        const sprop_visibility = try self.allocator.alloc(u8, static_prop_count);
        const sprop_type = try self.allocator.alloc([]const u8, static_prop_count);
        const sprop_doc = try self.allocator.alloc([]const u8, static_prop_count);

        defer self.allocator.free(sprop_names);
        defer self.allocator.free(sprop_has_default);
        defer self.allocator.free(sprop_is_const);
        defer self.allocator.free(sprop_visibility);
        defer self.allocator.free(sprop_type);
        defer self.allocator.free(sprop_doc);

        for (0..static_prop_count) |pi| {
            const pname_idx = self.readU16();
            sprop_names[pi] = self.currentChunk().constants.items[pname_idx].string.bytes();
            sprop_has_default[pi] = self.readByte();
            sprop_visibility[pi] = self.readByte();
            sprop_is_const[pi] = self.readByte();

            const t_idx = self.readU16();
            sprop_type[pi] = if (t_idx == 0xffff)
                ""
            else
                self.currentChunk().constants.items[t_idx].string.bytes();

            const sd_idx = self.readU16();
            sprop_doc[pi] = if (sd_idx == 0xffff)
                ""
            else
                self.currentChunk().constants.items[sd_idx].string.bytes();
        }

        const sdefaults = try self.popDefaultsAlloc(sprop_has_default);
        defer self.allocator.free(sdefaults);

        const defaults = try self.popDefaultsAlloc(prop_has_default);
        defer self.allocator.free(defaults);

        var dj: usize = 0;
        for (0..prop_count) |pi| {
            const default_val = if (prop_has_default[pi] == 1) blk: {
                const v = defaults[dj];
                dj += 1;
                break :blk v;
            } else Value{ .null = {} };

            // The ClassDef owns this default, so retain arrays/objects here.
            retainValue(default_val);

            const effective_readonly = prop_readonly[pi] or def.is_readonly;
            // PHP 8.5 gives public readonly properties implicit protected(set),
            // including promoted properties and properties of readonly classes.
            if (effective_readonly and !prop_has_set_vis[pi] and prop_vis[pi] == .public) {
                prop_set_vis[pi] = .protected;
                prop_has_set_vis[pi] = true;
            }
            // PHP 8.4 implicitly finalizes only asymmetric private(set).
            // Symmetric private private(set) and private readonly are not final.
            const reflection_final =
                prop_final[pi] or
                (prop_has_set_vis[pi] and
                    prop_set_vis[pi] == .private and
                    prop_vis[pi] != .private);

            try def.properties.append(self.allocator, .{
                .name = prop_names[pi],
                .default = default_val,
                .has_default = prop_has_default[pi] == 1,
                .visibility = prop_vis[pi],
                .set_visibility = prop_set_vis[pi],
                .has_set_visibility = prop_has_set_vis[pi],
                .is_readonly = effective_readonly,
                .is_final = reflection_final,
                .is_promoted = prop_promoted[pi],
                .is_virtual = prop_virtual[pi],
                .is_hooked = prop_hooked[pi],
                .trait_origin = prop_origin[pi],
                .type_str = prop_type[pi],
                .doc_comment = prop_doc[pi],
            });
        }

        var sj: usize = 0;
        for (0..static_prop_count) |pi| {
            // a typed static property without a default starts uninitialized
            const default_val = if (sprop_has_default[pi] == 1) blk: {
                const v = sdefaults[sj];
                sj += 1;
                break :blk v;
            } else if (sprop_type[pi].len > 0 and sprop_is_const[pi] != 1) Value.undef else Value{ .null = {} };
            // copyValue: an array/object default is owned by the ClassDef -
            // it must be refcounted (else an array default sits at refcount 0
            // and the first get_static_prop+push+pop releases it)
            const vis_byte = sprop_visibility[pi] & 0x03;
            if (sprop_is_const[pi] == 1) {
                if (!def.constants.contains(sprop_names[pi])) try def.constant_order.append(self.allocator, sprop_names[pi]);
                try def.constants.put(self.allocator, sprop_names[pi], try self.copyDefault(default_val));
                if (sprop_type[pi].len > 0) try def.constant_types.put(self.allocator, sprop_names[pi], sprop_type[pi]);
                if (vis_byte != 0) try def.const_visibility.put(self.allocator, sprop_names[pi], @enumFromInt(vis_byte));
                try def.constant_docs.put(self.allocator, sprop_names[pi], sprop_doc[pi]);
                if ((sprop_visibility[pi] & 0x10) != 0) {
                    try def.const_final.put(self.allocator, sprop_names[pi], {});
                }
            } else {
                try def.static_props.put(self.allocator, sprop_names[pi], try self.copyDefault(default_val));
                if (sprop_type[pi].len > 0) try def.static_prop_types.put(self.allocator, sprop_names[pi], sprop_type[pi]);
                if (sprop_doc[pi].len > 0) try def.static_prop_docs.put(self.allocator, sprop_names[pi], sprop_doc[pi]);
                if ((sprop_visibility[pi] & 0x80) != 0) try def.static_prop_final.put(self.allocator, sprop_names[pi], {});
                if (vis_byte != 0) try def.static_prop_visibility.put(self.allocator, sprop_names[pi], @enumFromInt(vis_byte));
                // bit 5 marks an explicit set visibility, held in bits 3-4
                if ((sprop_visibility[pi] & 0x20) != 0) try def.static_prop_set_visibility.put(self.allocator, sprop_names[pi], @enumFromInt((sprop_visibility[pi] >> 3) & 0x03));
            }
        }

        const parent_idx = self.readU16();
        if (parent_idx != 0xffff) {
            const written_parent = self.currentChunk().constants.items[parent_idx].string.bytes();
            const parent_name = self.declaredClassName(written_parent);
            def.parent = parent_name;
            if (self.traits.contains(parent_name) or self.interfaces.contains(parent_name)) {
                return self.traitRuleFatal("Class {s} cannot extend {s} {s}", .{ class_name, if (self.traits.contains(parent_name)) "trait" else "interface", parent_name });
            }
            if (self.classes.get(parent_name)) |parent_cls| {
                if (parent_cls.is_enum) return self.traitRuleFatal("Class {s} cannot extend enum {s}", .{ class_name, parent_cls.name });
                if (parent_cls.is_final) {
                    const msg = try std.fmt.allocPrint(self.allocator, "Class {s} cannot extend final class {s}", .{ class_name, parent_name });
                    try self.strings.append(self.allocator, msg);
                    self.error_msg = msg;
                    return error.RuntimeError;
                }
                if (parent_cls.is_readonly and !def.is_readonly) {
                    const msg = try std.fmt.allocPrint(self.allocator, "Non-readonly class {s} cannot extend readonly class {s}", .{ class_name, parent_name });
                    try self.strings.append(self.allocator, msg);
                    self.error_msg = msg;
                    return error.RuntimeError;
                }
                if (def.is_readonly and !parent_cls.is_readonly) {
                    const msg = try std.fmt.allocPrint(self.allocator, "Readonly class {s} cannot extend non-readonly class {s}", .{ class_name, parent_name });
                    try self.strings.append(self.allocator, msg);
                    self.error_msg = msg;
                    return error.RuntimeError;
                }
                // a final method's override is refused by the inheritance
                // checks, at the overriding method's line
            }
        }

        const iface_count = self.readByte();
        for (0..iface_count) |_| {
            const iname_idx = self.readU16();
            const iface = self.declaredClassName(self.currentChunk().constants.items[iname_idx].string.bytes());
            if (!self.interfaces.contains(iface) and (self.traits.contains(iface) or self.classes.contains(iface))) {
                return self.traitRuleFatal("{s} cannot implement {s} - it is not an interface", .{ class_name, iface });
            }
            try def.interfaces.append(self.allocator, iface);
        }
        try self.checkDeclaredInterfaces(&def, class_name);
        try self.checkInterfacesImplemented(&def, class_name);

        const trait_count = self.readByte();
        var trait_names: [64][]const u8 = undefined;
        for (0..trait_count) |ti| {
            trait_names[ti] = self.currentChunk().constants.items[self.readU16()].string.bytes();
        }

        const rules = try self.readTraitRules();
        defer rules.deinit(self.allocator);

        self.trait_constant_sources.clearRetainingCapacity();
        // checks a class declared before left waiting (a default it never installed)
        self.trait_property_checks.clearRetainingCapacity();
        for (trait_names[0..trait_count]) |trait_name| try self.warnDeprecatedTraitUse(trait_name, class_name);
        try self.bindClassTraits(&def, class_name, trait_names[0..trait_count], rules);
        for (trait_names[0..trait_count]) |trait_name| try def.used_traits.append(self.allocator, self.declaredClassName(trait_name));

        const class_attrs = try self.readAttributeDefs();
        for (class_attrs) |a| try def.attributes.append(self.allocator, a);
        if (class_attrs.len > 0) self.allocator.free(class_attrs);

        const method_attr_count = self.readByte();
        for (0..method_attr_count) |_| {
            const ma_name_idx = self.readU16();
            const ma_name = self.currentChunk().constants.items[ma_name_idx].string.bytes();
            const ma_attrs = try self.readAttributeDefs();
            try def.method_attributes.put(self.allocator, ma_name, ma_attrs);
        }

        const prop_attr_count = self.readByte();
        for (0..prop_attr_count) |_| {
            const pa_name_idx = self.readU16();
            const pa_name = self.currentChunk().constants.items[pa_name_idx].string.bytes();
            const pa_attrs = try self.readAttributeDefs();
            try def.property_attributes.put(self.allocator, pa_name, pa_attrs);
        }

        const const_attr_count = self.readByte();
        for (0..const_attr_count) |_| {
            const ca_name_idx = self.readU16();
            const ca_name = self.currentChunk().constants.items[ca_name_idx].string.bytes();
            const ca_attrs = try self.readAttributeDefs();
            try def.constant_attributes.put(self.allocator, ca_name, ca_attrs);
            if (try self.deprecationOf(ca_attrs)) |suffix| {
                try def.deprecated_constants.put(self.allocator, ca_name, suffix);
                self.has_deprecated_constants = true;
            }
        }

        const param_attr_method_count = self.readByte();
        for (0..param_attr_method_count) |_| {
            const pam_name_idx = self.readU16();
            const pam_method = self.currentChunk().constants.items[pam_name_idx].string.bytes();
            const pam_param_count = self.readByte();
            for (0..pam_param_count) |_| {
                const pap_name_idx = self.readU16();
                const pap_name = self.currentChunk().constants.items[pap_name_idx].string.bytes();
                const pap_attrs = try self.readAttributeDefs();
                var key_buf: [256]u8 = undefined;
                const key = std.fmt.bufPrint(&key_buf, "{s}:{s}", .{ pam_method, pap_name }) catch continue;
                const owned_key = try self.allocator.dupe(u8, key);
                try def.param_attributes.put(self.allocator, owned_key, pap_attrs);
            }
        }

        // zend_do_link_class: the class is visible, unlinked, to the
        // variance checks of classes its parent's loading declares
        try self.linking.append(self.allocator, .{ .name = class_name, .def = &def });
        const linking_index = self.linking.items.len - 1;
        defer self.linking.shrinkRetainingCapacity(linking_index);
        if (def.parent) |parent_name| {
            if (!self.classes.contains(parent_name)) {
                // an unlinked class isn't a parent yet, and isn't autoloaded
                const unlinked = self.linkingClass(parent_name) != null;
                if (!unlinked) self.tryAutoload(parent_name) catch |err| return self.unrecoverableLoadFailure(linking_index, err);
                if (!self.classes.contains(parent_name) and class_modifiers & 0x80 == 0) {
                    if (self.pending_exception != null) return self.unrecoverableLoadFailure(linking_index, error.RuntimeError);
                    const msg = try std.fmt.allocPrint(self.allocator, "Class \"{s}\" not found", .{parent_name});
                    defer self.allocator.free(msg);
                    try self.setPendingException("Error", msg);
                    return self.unrecoverableLoadFailure(linking_index, error.RuntimeError);
                }
            }

            var current_parent: ?[]const u8 = parent_name;
            while (current_parent) |parent_class_name| {
                const parent_cls = self.classes.get(parent_class_name) orelse break;

                // a property stays static or non static, readonly or not,
                // through inheritance (php's do_inherit_property)
                for (parent_cls.properties.items) |parent_prop| {
                    if (parent_prop.visibility == .private or !def.static_props.contains(parent_prop.name)) continue;
                    const msg = try std.fmt.allocPrint(self.allocator, "Cannot redeclare non static {s}::${s} as static {s}::${s}", .{ parent_class_name, parent_prop.name, class_name, parent_prop.name });
                    defer self.allocator.free(msg);
                    return self.raiseFatal(msg);
                }
                for (parent_cls.static_props.keys()) |sname| {
                    if ((parent_cls.static_prop_visibility.get(sname) orelse .public) == .private) continue;
                    for (def.properties.items) |child_prop| {
                        if (!std.mem.eql(u8, child_prop.name, sname)) continue;
                        const msg = try std.fmt.allocPrint(self.allocator, "Cannot redeclare static {s}::${s} as non static {s}::${s}", .{ parent_class_name, sname, class_name, sname });
                        defer self.allocator.free(msg);
                        return self.raiseFatal(msg);
                    }
                }
                // a static property redeclared narrower than the parent's
                for (parent_cls.static_props.keys()) |static_name| {
                    const parent_vis = parent_cls.static_prop_visibility.get(static_name) orelse .public;
                    if (parent_vis == .private) continue;
                    if (!def.static_props.contains(static_name)) continue;
                    const child_vis = def.static_prop_visibility.get(static_name) orelse .public;
                    if (@intFromEnum(child_vis) > @intFromEnum(parent_vis)) {
                        self.setErrorMsg("Access level to {s}::${s} must be {s} (as in class {s}){s}", .{ class_name, static_name, @tagName(parent_vis), parent_class_name, if (parent_vis == .public) "" else " or weaker" });
                        return error.RuntimeError;
                    }
                }
                for (parent_cls.properties.items) |parent_prop| {
                    for (def.properties.items) |child_prop| {
                        if (!std.mem.eql(u8, parent_prop.name, child_prop.name)) continue;
                        if (parent_prop.is_final) {
                            self.setErrorMsg("Cannot override final property {s}::${s}", .{ parent_class_name, parent_prop.name });
                            return error.RuntimeError;
                        }
                        // Private properties are separate declarations, not overrides.
                        if (parent_prop.visibility == .private) continue;
                        // an abstract hooked property may be met by a readonly one
                        const parent_abstract = blk: {
                            var hbuf: [256]u8 = undefined;
                            for ([_][]const u8{ "$hook_get", "$hook_set" }) |suffix| {
                                const hook = std.fmt.bufPrint(&hbuf, "{s}{s}", .{ parent_prop.name, suffix }) catch continue;
                                if (parent_cls.methods.get(hook)) |m| if (m.is_abstract) break :blk true;
                            }
                            break :blk false;
                        };
                        if (child_prop.is_readonly != parent_prop.is_readonly and !parent_prop.readonly_undeclared and !parent_abstract) {
                            const msg = try std.fmt.allocPrint(self.allocator, "Cannot redeclare {s} property {s}::${s} as {s} {s}::${s}", .{
                                if (parent_prop.is_readonly) "readonly" else "non-readonly", parent_class_name, parent_prop.name,
                                if (child_prop.is_readonly) "readonly" else "non-readonly", class_name, parent_prop.name,
                            });
                            defer self.allocator.free(msg);
                            return self.raiseFatal(msg);
                        }
                        if (@intFromEnum(child_prop.visibility) > @intFromEnum(parent_prop.visibility)) {
                            self.setErrorMsg("Access level to {s}::${s} must be {s} (as in class {s}){s}", .{ class_name, child_prop.name, @tagName(parent_prop.visibility), parent_class_name, if (parent_prop.visibility == .public) "" else " or weaker" });
                            return error.RuntimeError;
                        }
                        // A virtual get-only property imposes no write contract.
                        const setter = try std.fmt.allocPrint(self.allocator, "{s}$hook_set", .{parent_prop.name});
                        defer self.allocator.free(setter);
                        if (parent_prop.is_virtual and !parent_cls.methods.contains(setter)) continue;
                        if (@intFromEnum(child_prop.set_visibility) > @intFromEnum(parent_prop.set_visibility)) {
                            if (parent_prop.set_visibility == .public) {
                                self.setErrorMsg("Set access level of {s}::${s} must be omitted (as in class {s})", .{ class_name, child_prop.name, parent_class_name });
                            } else {
                                self.setErrorMsg("Set access level of {s}::${s} must be {s}(set) (as in class {s}) or weaker", .{ class_name, child_prop.name, @tagName(parent_prop.set_visibility), parent_class_name });
                            }
                            return error.RuntimeError;
                        }
                    }
                }

                current_parent = parent_cls.parent;
            }
        }

        try self.verifyHookedProperties(&def, class_name);
        for (def.properties.items) |prop| {
            if (!prop.is_virtual or !prop.has_set_visibility or prop.set_visibility == prop.visibility) continue;
            const setter = try std.fmt.allocPrint(self.allocator, "{s}$hook_set", .{prop.name});
            defer self.allocator.free(setter);
            if (!def.methods.contains(setter)) {
                self.setErrorMsg("Read-only virtual property {s}::${s} must not specify asymmetric visibility", .{ class_name, prop.name });
                return error.RuntimeError;
            }
            const getter = try std.fmt.allocPrint(self.allocator, "{s}$hook_get", .{prop.name});
            defer self.allocator.free(getter);
            if (!def.methods.contains(getter)) {
                self.setErrorMsg("Write-only virtual property {s}::${s} must not specify asymmetric visibility", .{ class_name, prop.name });
                return error.RuntimeError;
            }
        }

        // a non-abstract class cannot declare any abstract methods directly.
        // PHP fatals here: 'Class X declares abstract method Y() and must
        // therefore be declared abstract'
        if (!def.is_abstract) {
            var di = def.methods.iterator();
            while (di.next()) |e| {
                // an abstract hook is verifyAbstractClass's, and so is an
                // abstract method a trait gave
                if (e.value_ptr.is_abstract and std.mem.indexOf(u8, e.key_ptr.*, "$hook_") == null and !self.isTraitBoundMethod(class_name, e.key_ptr.*)) {
                    const msg = if (class_names.isAnonymous(class_name))
                        try std.fmt.allocPrint(self.allocator, "Anonymous class method {s}() must not be abstract", .{e.key_ptr.*})
                    else
                        try std.fmt.allocPrint(self.allocator, "Class {s} declares abstract method {s}() and must therefore be declared abstract", .{ class_name, e.key_ptr.* });
                    try self.strings.append(self.allocator, msg);
                    self.error_msg = msg;
                    return error.RuntimeError;
                }
            }
        }

        // php adds Stringable to a class that declares __toString, itself or
        // through a trait
        if (def.methods.contains("__toString") and !self.classImplements(&def, "Stringable")) {
            try def.interfaces.append(self.allocator, "Stringable");
        }
        const deferred = try inheritance.checkClass(self, class_name, &def);
        defer if (deferred) |d| inheritance.discardDeferred(self, d);

        // unless this class is itself abstract, every abstract method inherited
        // from the parent chain (and required by any implemented interface)
        // must be implemented by a non-abstract method
        if (!def.is_abstract) try self.verifyAbstractClass(class_name, &def);

        // composer's autoloader uses `include` (not require_once), so a class
        // file can be re-executed multiple times during a single autoload chain;
        // each re-execution rebuilds slot_layout and the class def. built after
        // the declaration checks so a rejected class leaves nothing behind
        def.slot_layout = try self.buildSlotLayout(&def);

        // anonymous classes have a stable structure and are re-executed every
        // time the call site runs. their existing instances point at the old
        // slot_layout, so freeing it (as we do for regular re-registration)
        // would invalidate live objects. keep the first registration.
        if (class_names.isAnonymous(class_name) and self.classes.contains(class_name)) {
            def.deinit(self.allocator);
            return;
        }

        // put has the most complete state (e.g. parent slots merged), so we
        // let it win - but we must free the prior def or its slot_layout and
        // owned tables leak
        if (self.classes.fetchRemove(class_name)) |old| {
            var old_def = old.value;
            old_def.deinit(self.allocator);
        }
        if (def.has_prop_hooks) self.any_prop_hooks = true;
        // mark the methods that redeclare an ancestor's private one
        var own_mit = def.methods.valueIterator();
        while (own_mit.next()) |info| if (info.visibility == .private) {
            def.hides_methods = true;
            break;
        };
        if (def.parent) |parent_name| if (self.classes.getPtr(parent_name)) |parent_def| if (parent_def.hides_methods) {
            def.hides_methods = true;
            var mit = def.methods.iterator();
            while (mit.next()) |me| {
                const inherited = self.findMethodInfo(parent_name, me.key_ptr.*) orelse continue;
                if (inherited.info.visibility == .private or inherited.info.changed) me.value_ptr.changed = true;
            }
        };
        try self.classes.put(self.allocator, class_name, def);
        registered = true;
        // a class with obligations, or one whose parent still has some,
        // loads the delayed classes (seeing it registered) before it is done
        const parent_nearly: ?NearlyLinked = if (def.parent) |parent_name| self.nearlyLinked(parent_name) else null;
        if (deferred != null or parent_nearly != null) {
            try self.nearly_linked.append(self.allocator, .{ .name = class_name, .deferred = deferred });
            defer _ = self.nearly_linked.pop();
            try self.loadDelayedClasses(class_name);
            // a nearly linked parent's checks run first (php's dependency
            // obligation), then its own
            if (parent_nearly) |parent| if (parent.deferred) |pd| try inheritance.resolveObligationsOf(pd);
            if (deferred) |d| try inheritance.resolveObligationsOf(d);
        }
        // a parent's constants still waiting are evaluated on this class's
        // first use too
        if (def.parent) |parent_name| if (self.classes.getPtr(parent_name)) |parent_def| if (parent_def.lazy_constants) {
            if (self.classes.getPtr(class_name)) |own| self.markLazyConstants(own);
        };

        try self.checkOverrides(class_name, &def);

        // zend_implement_serializable: every class that implements Serializable,
        // itself or through a parent, unless explicitly abstract or serializing
        // with __serialize and __unserialize
        if (!def.is_abstract and !class_names.isAnonymous(class_name) and
            self.isInstanceOf(class_name, "Serializable") and
            (!self.hasMethod(class_name, "__serialize") or !self.hasMethod(class_name, "__unserialize")))
        {
            const msg = try std.fmt.allocPrint(self.allocator, "{s} implements the Serializable interface, which is deprecated. Implement __serialize() and __unserialize() instead (or in addition, if support for old PHP versions is necessary)", .{class_name});
            defer self.allocator.free(msg);
            try self.raiseErrorAt(E_DEPRECATED, msg, .{ .file = def.file_path, .line = def.start_line });
        }
    }

    fn hasOverrideAttribute(attrs: []const AttributeDef) bool {
        for (attrs) |attr| {
            const name = if (attr.name.len > 0 and attr.name[0] == '\\') attr.name[1..] else attr.name;
            if (std.ascii.eqlIgnoreCase(name, "Override")) return true;
        }
        return false;
    }

    // the attributes of a method a class has, its own or a trait's
    fn ownMethodAttributes(self: *VM, class_name: []const u8, def: *const ClassDef, method: []const u8) ?[]const AttributeDef {
        if (def.method_attributes.get(method)) |attrs| return attrs;
        var key_buf: [512]u8 = undefined;
        const func = self.functions.get(class_names.memberKey(&key_buf, class_name, method)) orelse return null;
        const sep = std.mem.indexOf(u8, func.trait_origin, "::") orelse return null;
        const trait = self.classes.get(func.trait_origin[0..sep]) orelse return null;
        return trait.method_attributes.get(func.trait_origin[sep + 2 ..]);
    }

    // zend_inheritance_check_override: a method or property marked
    // #[\Override] that nothing it inherits declares is a compile error at
    // the method's line. an ancestor or interface zphp hasn't loaded yet
    // counts as declaring it, since it can't be ruled out
    fn checkOverrides(self: *VM, class_name: []const u8, def: *const ClassDef) RuntimeError!void {
        var mit = def.methods.iterator();
        while (mit.next()) |entry| {
            const method = entry.key_ptr.*;
            if (std.mem.indexOf(u8, method, "$hook_") != null) continue;
            const attrs = self.ownMethodAttributes(class_name, def, method) orelse continue;
            if (!hasOverrideAttribute(attrs)) continue;
            if (try self.overridesInherited(def, method)) continue;
            var key_buf: [512]u8 = undefined;
            const func = self.functions.get(class_names.memberKey(&key_buf, class_name, method));
            const msg = try std.fmt.allocPrint(self.allocator, "{s}::{s}() has #[\\Override] attribute, but no matching parent method exists", .{ class_names.display(class_name), method });
            defer self.allocator.free(msg);
            const at: SourcePosition = if (func) |f| .{ .file = if (f.file_path.len > 0) f.file_path else def.file_path, .line = f.start_line } else .{ .file = def.file_path, .line = def.start_line };
            return self.raiseCompileFatal(msg, at);
        }
        var pit = def.property_attributes.iterator();
        while (pit.next()) |entry| {
            if (!hasOverrideAttribute(entry.value_ptr.*)) continue;
            if (self.inheritsProperty(def, entry.key_ptr.*)) continue;
            const msg = try std.fmt.allocPrint(self.allocator, "{s}::${s} has #[\\Override] attribute, but no matching parent property exists", .{ class_names.display(class_name), entry.key_ptr.* });
            defer self.allocator.free(msg);
            return self.raiseCompileFatal(msg, .{ .file = def.file_path, .line = def.start_line });
        }
    }

    // whether a method the class declares meets one it inherits, as
    // do_inheritance_check_on_method resets ZEND_ACC_OVERRIDE: a parent's
    // method unless it is private (and not abstract), a constructor only when
    // it is abstract or an interface's, any interface's, and a trait's
    // abstract one
    fn overridesInherited(self: *VM, def: *const ClassDef, method: []const u8) RuntimeError!bool {
        const ctor = std.ascii.eqlIgnoreCase(method, "__construct");
        var key_buf: [512]u8 = undefined;
        var current = def.parent;
        parents: while (current) |pn| {
            const cls = self.classes.get(pn) orelse return true;
            if (cls.methods.get(method)) |info| {
                if (ctor) {
                    if (info.is_abstract) return true;
                    break :parents;
                }
                if (info.visibility == .private and !info.is_abstract) break :parents;
                return true;
            }
            if (!ctor and self.native_fns.contains(class_names.memberKey(&key_buf, pn, method))) return true;
            current = cls.parent;
        }
        var seen: std.ArrayListUnmanaged([]const u8) = .empty;
        defer seen.deinit(self.allocator);
        var owner: ?*const ClassDef = def;
        while (owner) |cls| {
            for (cls.interfaces.items) |iface| try self.collectInterface(&seen, iface);
            owner = if (cls.parent) |p| self.classes.getPtr(p) else null;
        }
        for (seen.items) |iface| {
            const idef = self.interfaces.get(iface) orelse return true;
            for (idef.methods.items) |m| if (std.ascii.eqlIgnoreCase(m, method)) return true;
        }
        for (def.used_traits.items) |trait| {
            for (try self.traitTable(trait)) |tm| if (tm.is_abstract and std.ascii.eqlIgnoreCase(tm.name, method)) return true;
        }
        return false;
    }

    // a property redeclared over a parent's that isn't private, or one an
    // interface declares
    fn inheritsProperty(self: *VM, def: *const ClassDef, name: []const u8) bool {
        var current = def.parent;
        while (current) |pn| {
            const cls = self.classes.get(pn) orelse return true;
            for (cls.properties.items) |prop| if (std.mem.eql(u8, prop.name, name) and prop.visibility != .private) return true;
            if (cls.static_props.contains(name) and (cls.static_prop_visibility.get(name) orelse .public) != .private) return true;
            current = cls.parent;
        }
        var owner: ?*const ClassDef = def;
        while (owner) |cls| {
            for (cls.interfaces.items) |iface| {
                const idef = self.classes.get(iface) orelse return true;
                for (idef.properties.items) |prop| if (std.mem.eql(u8, prop.name, name)) return true;
            }
            owner = if (cls.parent) |p| self.classes.getPtr(p) else null;
        }
        return false;
    }

    fn handleEnumDecl(self: *VM) RuntimeError!void {
        const name_idx = self.readU16();
        const enum_name = self.currentChunk().constants.items[name_idx].string.bytes();
        try self.refuseRedeclaration(enum_name);
        const site = self.readDeclSite();
        const backed_type_byte = self.readByte();
        const case_count = self.readByte();

        var def = ClassDef{ .name = enum_name, .is_enum = true, .is_internal = false, .file_path = site.file, .start_line = site.start_line, .end_line = site.end_line, .doc_comment = site.doc_comment };
        def.backed_type = @enumFromInt(backed_type_byte);
        // a case's name (and a backed case's value) is a public readonly
        // property, and an enum takes no other
        def.no_dynamic_properties = true;
        // php declares them without the protected(set) user readonly
        // properties imply
        try def.properties.append(self.allocator, .{ .name = "name", .default = .null, .is_readonly = true, .has_set_visibility = true, .type_str = "string" });
        if (def.backed_type != .none) try def.properties.append(self.allocator, .{ .name = "value", .default = .null, .is_readonly = true, .has_set_visibility = true, .type_str = if (def.backed_type == .int_type) "int" else "string" });

        const case_names = try self.allocator.alloc([]const u8, case_count);
        defer self.allocator.free(case_names);
        const case_has_value = try self.allocator.alloc(u8, case_count);
        defer self.allocator.free(case_has_value);
        for (0..case_count) |ci| {
            case_names[ci] = self.currentChunk().constants.items[self.readU16()].string.bytes();
            case_has_value[ci] = self.readByte();
            const doc_idx = self.readU16();
            if (doc_idx != 0xffff) try def.constant_docs.put(self.allocator, case_names[ci], self.currentChunk().constants.items[doc_idx].string.bytes());
        }

        var case_values = try self.allocator.alloc(Value, case_count);
        defer self.allocator.free(case_values);
        var value_count: usize = 0;
        for (case_has_value) |has_value| if (has_value == 1) {
            value_count += 1;
        };
        var value_idx = value_count;
        while (value_idx > 0) {
            value_idx -= 1;
            case_values[value_idx] = self.pop();
        }

        var vj: usize = 0;
        for (0..case_count) |ci| {
            // the case takes its handle on first access (enumCase)
            const case_obj = try self.allocObjectShell();
            case_obj.* = .{ .class_name = enum_name, .enum_case = true };
            try case_obj.set(self.allocator, "name", .{ .string = Value.String.borrowed(case_names[ci]) });
            if (case_has_value[ci] == 1) {
                try case_obj.set(self.allocator, "value", case_values[vj]);
                vj += 1;
            }
            objRetain(case_obj);
            try def.constants.put(self.allocator, case_names[ci], .{ .object = case_obj });
            try def.constant_order.append(self.allocator, case_names[ci]);
            try def.case_order.append(self.allocator, case_names[ci]);
        }

        const method_count = self.readU16();
        for (0..method_count) |_| {
            const mi = self.readMethodInfo();
            try def.addMethod(self.allocator, mi[1]);
        }
        // php adds an enum's own methods as it links the enum, refusing one
        // the enum declared itself
        const builtins: []const []const u8 = if (def.backed_type != .none) &.{ "cases", "from", "tryfrom" } else &.{"cases"};
        for (builtins) |builtin| if (def.methods.contains(builtin)) {
            const msg = try std.fmt.allocPrint(self.allocator, "Cannot redeclare {s}::{s}()", .{ enum_name, builtin });
            defer self.allocator.free(msg);
            return self.raiseCompileFatal(msg, .{ .file = site.file, .line = site.start_line });
        };

        const iface_count = self.readByte();
        for (0..iface_count) |_| {
            try def.interfaces.append(self.allocator, self.declaredClassName(self.currentChunk().constants.items[self.readU16()].string.bytes()));
        }
        // every enum implements UnitEnum; backed enums also implement
        // BackedEnum, after the ones it lists (zend_enum_add_interfaces)
        try def.interfaces.append(self.allocator, "UnitEnum");
        if (backed_type_byte != 0) try def.interfaces.append(self.allocator, "BackedEnum");

        const enum_trait_count = self.readByte();
        var enum_trait_names: [16][]const u8 = undefined;
        for (0..enum_trait_count) |ti| {
            enum_trait_names[ti] = self.currentChunk().constants.items[self.readU16()].string.bytes();
        }
        self.trait_constant_sources.clearRetainingCapacity();
        for (enum_trait_names[0..enum_trait_count]) |trait_name| try self.warnDeprecatedTraitUse(trait_name, enum_name);
        try self.bindClassTraits(&def, enum_name, enum_trait_names[0..enum_trait_count], .{});
        try self.checkDeclaredInterfaces(&def, enum_name);
        try self.checkInterfacesImplemented(&def, enum_name);

        const enum_attrs = try self.readAttributeDefs();
        for (enum_attrs) |a| try def.attributes.append(self.allocator, a);
        if (enum_attrs.len > 0) self.allocator.free(enum_attrs);

        const enum_method_attr_count = self.readByte();
        for (0..enum_method_attr_count) |_| {
            const ma_name_idx = self.readU16();
            const ma_name = self.currentChunk().constants.items[ma_name_idx].string.bytes();
            const ma_attrs = try self.readAttributeDefs();
            try def.method_attributes.put(self.allocator, ma_name, ma_attrs);
        }

        // case attributes - stored as constant_attributes so
        // ReflectionClassConstant::getAttributes finds them
        const enum_case_attr_count = self.readByte();
        for (0..enum_case_attr_count) |_| {
            const ca_name_idx = self.readU16();
            const ca_name = self.currentChunk().constants.items[ca_name_idx].string.bytes();
            const ca_attrs = try self.readAttributeDefs();
            try def.constant_attributes.put(self.allocator, ca_name, ca_attrs);
            if (try self.deprecationOf(ca_attrs)) |suffix| {
                try def.deprecated_constants.put(self.allocator, ca_name, suffix);
                self.has_deprecated_constants = true;
            }
        }

        // enum constant names (const decls, not cases)
        const enum_const_count = self.readByte();
        for (0..enum_const_count) |_| {
            const ec_name_idx = self.readU16();
            const ec_name = self.currentChunk().constants.items[ec_name_idx].string.bytes();
            const doc_idx = self.readU16();
            if (doc_idx != 0xffff) try def.constant_docs.put(self.allocator, ec_name, self.currentChunk().constants.items[doc_idx].string.bytes());
            const const_flags = self.readByte();
            const type_idx = self.readU16();
            const vis = const_flags & 0x03;
            if (vis != 0) try def.const_visibility.put(self.allocator, ec_name, @enumFromInt(vis));
            if (const_flags & 0x10 != 0) try def.const_final.put(self.allocator, ec_name, {});
            if (type_idx != 0xffff) try def.constant_types.put(self.allocator, ec_name, self.currentChunk().constants.items[type_idx].string.bytes());
            if (!def.constants.contains(ec_name)) {
                try def.constant_order.append(self.allocator, ec_name);
                try def.constants.put(self.allocator, ec_name, .null);
            }
        }

        try self.registerEnumMethods(enum_name, backed_type_byte);
        if (try inheritance.checkClass(self, enum_name, &def)) |d| try inheritance.resolveDeferred(self, d);
        try self.verifyAbstractClass(enum_name, &def);
        // zend_verify_enum: a trait may have brought what an enum can't have
        for (def.properties.items) |prop| {
            if (std.mem.eql(u8, prop.name, "name") or (def.backed_type != .none and std.mem.eql(u8, prop.name, "value"))) continue;
            const msg = try std.fmt.allocPrint(self.allocator, "Enum {s} cannot include properties", .{enum_name});
            defer self.allocator.free(msg);
            return self.raiseCompileFatal(msg, .{ .file = site.file, .line = site.start_line });
        }
        if (def.static_props.count() > 0) {
            const msg = try std.fmt.allocPrint(self.allocator, "Enum {s} cannot include properties", .{enum_name});
            defer self.allocator.free(msg);
            return self.raiseCompileFatal(msg, .{ .file = site.file, .line = site.start_line });
        }
        for ([_][]const u8{ "__construct", "__destruct", "__clone", "__get", "__set", "__unset", "__isset", "__toString", "__debugInfo", "__serialize", "__unserialize", "__sleep", "__wakeup", "__set_state" }) |magic| {
            if (!def.methods.contains(magic)) continue;
            const msg = try std.fmt.allocPrint(self.allocator, "Enum {s} cannot include magic method {s}", .{ enum_name, magic });
            defer self.allocator.free(msg);
            return self.raiseCompileFatal(msg, .{ .file = site.file, .line = site.start_line });
        }
        if (self.classImplements(&def, "Serializable")) {
            const deprecation = try std.fmt.allocPrint(self.allocator, "{s} implements the Serializable interface, which is deprecated. Implement __serialize() and __unserialize() instead (or in addition, if support for old PHP versions is necessary)", .{enum_name});
            defer self.allocator.free(deprecation);
            try self.raiseErrorAt(E_DEPRECATED, deprecation, .{ .file = site.file, .line = site.start_line });
            const msg = try std.fmt.allocPrint(self.allocator, "Enum {s} cannot implement the Serializable interface", .{enum_name});
            defer self.allocator.free(msg);
            return self.raiseCompileFatal(msg, .{ .file = site.file, .line = site.start_line });
        }
        try self.checkOverrides(enum_name, &def);
        try self.classes.put(self.allocator, enum_name, def);
        if (backed_type_byte != 0) if (self.classes.getPtr(enum_name)) |registered| {
            registered.enum_table_pending = true;
            self.markLazyConstants(registered);
        };
    }

    fn readAttrValue(self: *VM) Value {
        const tag = self.readByte();
        return switch (tag) {
            0x00 => .null,
            0x01 => blk: {
                var bytes: [8]u8 = undefined;
                for (&bytes) |*b| b.* = self.readByte();
                break :blk .{ .int = @bitCast(bytes) };
            },
            0x02 => blk: {
                var bytes: [8]u8 = undefined;
                for (&bytes) |*b| b.* = self.readByte();
                break :blk .{ .float = @bitCast(bytes) };
            },
            0x03 => .{ .bool = true },
            0x04 => .{ .bool = false },
            0x05 => blk: {
                const idx = self.readU16();
                break :blk .{ .string = self.currentChunk().constants.items[idx].string };
            },
            0x06 => blk: {
                const len = self.readU16();
                const arr = self.allocArray() catch break :blk .null;
                for (0..len) |_| {
                    const v = self.readAttrValue();
                    arr.append(self.allocator, v) catch {};
                }
                break :blk .{ .array = arr };
            },
            0x07 => blk: { // associative array
                const len = self.readU16();
                const arr = self.allocArray() catch break :blk .null;
                for (0..len) |_| {
                    const key_type = self.readByte();
                    const key: PhpArray.Key = if (key_type == 0x01) k: {
                        const kidx = self.readU16();
                        break :k .{ .string = self.currentChunk().constants.items[kidx].string };
                    } else k: {
                        var bytes: [8]u8 = undefined;
                        for (&bytes) |*b| b.* = self.readByte();
                        break :k .{ .int = @bitCast(bytes) };
                    };
                    const v = self.readAttrValue();
                    arr.set(self.allocator, key, v) catch {};
                }
                break :blk .{ .array = arr };
            },
            else => .null,
        };
    }

    fn readAttributeDefs(self: *VM) RuntimeError![]const AttributeDef {
        const count = self.readByte();
        if (count == 0) return &.{};
        const attrs = try self.allocator.alloc(AttributeDef, count);
        for (0..count) |i| {
            const name_idx = self.readU16();
            const name = self.currentChunk().constants.items[name_idx].string.bytes();
            const arg_count = self.readU32();
            if (arg_count > 0) {
                const args = try self.allocator.alloc(Value, arg_count);
                const names = try self.allocator.alloc(?[]const u8, arg_count);
                for (0..arg_count) |ai| {
                    const named_flag = self.readByte();
                    if (named_flag == 1) {
                        const an_idx = self.readU16();
                        names[ai] = self.currentChunk().constants.items[an_idx].string.bytes();
                    } else {
                        names[ai] = null;
                    }
                    // php evaluates attribute arguments when reflection asks for
                    // them; one that cannot be resolved yet stays deferred and
                    // ReflectionAttribute resolves it (or raises) then
                    const quiet = self.resolving_quietly;
                    self.resolving_quietly = true;
                    defer self.resolving_quietly = quiet;
                    const raw = self.readAttrValue();
                    args[ai] = self.resolveDefault(raw) catch |err| blk: {
                        if (err != error.RuntimeError) return err;
                        break :blk raw;
                    };
                }
                attrs[i] = .{ .name = name, .args = args, .arg_names = names };
            } else {
                attrs[i] = .{ .name = name };
            }
        }
        return attrs;
    }

    fn readMethodInfo(self: *VM) struct { []const u8, ClassDef.MethodInfo } {
        const mname_idx = self.readU16();
        const method_name = self.currentChunk().constants.items[mname_idx].string.bytes();
        const arity = self.readByte();
        const is_static = self.readByte() == 1;
        const vis: ClassDef.Visibility = @enumFromInt(self.readByte());
        const flags = self.readByte();
        return .{ method_name, .{
            .name = method_name,
            .arity = arity,
            .is_static = is_static,
            .visibility = vis,
            .is_abstract = (flags & 1) != 0,
            .is_final = (flags & 2) != 0,
        } };
    }

    fn popDefaults(self: *VM, comptime max: usize, has_default: []const u8) [max]Value {
        var values: [max]Value = undefined;
        var count: usize = 0;
        for (has_default) |hd| {
            if (hd == 1) count += 1;
        }
        var i: usize = count;
        while (i > 0) {
            i -= 1;
            values[i] = self.pop();
        }
        return values;
    }

    fn popDefaultsAlloc(self: *VM, has_default: []const u8) RuntimeError![]Value {
        var count: usize = 0;
        for (has_default) |hd| {
            if (hd == 1) count += 1;
        }
        const values = try self.allocator.alloc(Value, count);
        var i = count;
        while (i > 0) {
            i -= 1;
            values[i] = self.pop();
        }
        return values;
    }

    fn registerEnumMethods(self: *VM, enum_name: []const u8, backed_type_byte: u8) !void {
        // idempotent: serve-mode reset re-runs registerStdlibClasses to re-seed
        // the class table (which freeClassState cleared), but native_fns
        // survives reset - so don't re-register methods that are already there
        var probe: [128]u8 = undefined;
        const probe_key = std.fmt.bufPrint(&probe, "{s}::cases", .{enum_name}) catch return;
        if (self.native_fns.contains(probe_key)) return;
        const cases_name = try std.fmt.allocPrint(self.allocator, "{s}::cases", .{enum_name});
        try self.persistent_strings.append(self.allocator, cases_name);
        try self.native_fns.put(self.allocator, cases_name, enums.enumCases);

        if (backed_type_byte != 0) {
            const from_name = try std.fmt.allocPrint(self.allocator, "{s}::from", .{enum_name});
            try self.persistent_strings.append(self.allocator, from_name);
            try self.native_fns.put(self.allocator, from_name, enums.enumFrom);

            const try_from_name = try std.fmt.allocPrint(self.allocator, "{s}::tryFrom", .{enum_name});
            try self.persistent_strings.append(self.allocator, try_from_name);
            try self.native_fns.put(self.allocator, try_from_name, enums.enumTryFrom);
        }
    }

    const InsteadofRule = struct { method: []const u8, preferred: []const u8, excluded: [16][]const u8, excluded_count: u8 };
    // alias "" changes only the modifiers: bits 0-1 a visibility (1
    // protected, 2 private, 3 public), bit 2 final
    const AliasRule = struct { method: []const u8, trait: []const u8, alias: []const u8, modifiers: u8 = 0 };
    // a declaration's insteadof and as rules (emitTraitRules); the names are
    // chunk constants
    pub const TraitRules = struct {
        aliases: []AliasRule = &.{},
        insteadofs: []InsteadofRule = &.{},

        pub fn deinit(self: TraitRules, allocator: Allocator) void {
            allocator.free(self.aliases);
            allocator.free(self.insteadofs);
        }
    };

    fn readTraitRules(self: *VM) !TraitRules {
        var aliases = std.ArrayListUnmanaged(AliasRule).empty;
        errdefer aliases.deinit(self.allocator);
        var insteadofs = std.ArrayListUnmanaged(InsteadofRule).empty;
        errdefer insteadofs.deinit(self.allocator);
        const count = self.readByte();
        for (0..count) |_| {
            const method_name = self.currentChunk().constants.items[self.readU16()].string.bytes();
            const rule_trait = self.currentChunk().constants.items[self.readU16()].string.bytes();
            if (self.readByte() == 1) {
                var rule = InsteadofRule{ .method = method_name, .preferred = rule_trait, .excluded = undefined, .excluded_count = self.readByte() };
                for (0..rule.excluded_count) |ei| rule.excluded[ei] = self.currentChunk().constants.items[self.readU16()].string.bytes();
                try insteadofs.append(self.allocator, rule);
            } else {
                const alias_name = self.currentChunk().constants.items[self.readU16()].string.bytes();
                try aliases.append(self.allocator, .{ .method = method_name, .trait = rule_trait, .alias = alias_name, .modifiers = self.readByte() });
            }
        }
        return .{ .aliases = try aliases.toOwnedSlice(self.allocator), .insteadofs = try insteadofs.toOwnedSlice(self.allocator) };
    }

    // a trait's own methods (name -> func) in declaration order, resolved
    // once and cached: the full scan of self.functions was applyTrait's whole
    // cost. the cache persists across requests (stable bytecode in serve mode)
    fn traitMethods(self: *VM, trait_name: []const u8) ![]const TraitMethodEntry {
        if (self.trait_method_cache.get(trait_name)) |cached| return cached;
        var list: std.ArrayListUnmanaged(TraitMethodEntry) = .empty;
        if (self.method_names_by_class.get(trait_name)) |names| {
            for (names.items) |fn_name| {
                const entry = self.functions.getEntry(fn_name) orelse continue;
                if (fn_name.len <= trait_name.len + 2) continue;
                const method = entry.key_ptr.*[trait_name.len + 2 ..];
                const seen = for (list.items) |e| {
                    if (std.mem.eql(u8, e.name, method)) break true;
                } else false;
                if (seen) continue;
                try list.append(self.allocator, .{ .name = method, .func = entry.value_ptr.* });
            }
        }
        std.sort.pdq(TraitMethodEntry, list.items, {}, struct {
            fn before(_: void, a: TraitMethodEntry, b: TraitMethodEntry) bool {
                if (a.func.start_line != b.func.start_line) return a.func.start_line < b.func.start_line;
                return @intFromPtr(a.func) < @intFromPtr(b.func);
            }
        }.before);
        const owned = try list.toOwnedSlice(self.allocator);
        // key by the persistent trait_name (a chunk constant) so the entry
        // outlives any per-request table churn
        try self.trait_method_cache.put(self.allocator, trait_name, owned);
        return owned;
    }

    // a method a trait gives (zend_function as a trait's function_table
    // holds it): its code, the name it is bound as, its modifiers after the
    // `as` rules, and the trait or class whose table it came from
    pub const TraitMethod = struct {
        name: []const u8,
        func: *const ObjFunction,
        visibility: ClassDef.Visibility,
        is_static: bool,
        is_final: bool,
        is_abstract: bool,
        scope: []const u8,
        // declared by the class (or trait) being composed
        own: bool = false,
    };

    // a class or trait being composed: its function table while php's
    // zend_do_bind_traits runs (own methods first, then trait ones)
    const TraitComposer = struct {
        owner: []const u8,
        // the class whose parents an abstract trait method may be met by;
        // null when a trait is composed
        def: ?*const ClassDef,
        entries: std.ArrayListUnmanaged(TraitMethod) = .empty,
        index: class_names.MethodMap(usize) = .{},

        fn deinit(c: *TraitComposer, allocator: Allocator) void {
            c.entries.deinit(allocator);
            c.index.deinit(allocator);
        }

        fn append(c: *TraitComposer, allocator: Allocator, m: TraitMethod) !void {
            try c.index.put(allocator, m.name, c.entries.items.len);
            try c.entries.append(allocator, m);
        }
    };

    fn traitMethodOf(trait_name: []const u8, name: []const u8, func: *const ObjFunction) TraitMethod {
        return .{
            .name = name,
            .func = func,
            .visibility = @enumFromInt(func.method_visibility),
            .is_static = func.is_static,
            .is_final = func.is_final,
            .is_abstract = func.is_abstract,
            .scope = trait_name,
        };
    }

    // a trait's function table once its own `use` is bound, as php links a
    // trait: its own methods, then those of the traits it uses, every one
    // scoped to it. cached until a trait is declared again
    fn traitTable(self: *VM, trait_name: []const u8) RuntimeError![]const TraitMethod {
        if (self.trait_tables.get(trait_name)) |cached| return cached;
        var comp: TraitComposer = .{ .owner = trait_name, .def = null };
        defer comp.deinit(self.allocator);
        for (try self.traitMethods(trait_name)) |tm| {
            var m = traitMethodOf(trait_name, tm.name, tm.func);
            m.own = true;
            try comp.append(self.allocator, m);
        }
        if (self.trait_uses.get(trait_name)) |subs| {
            const traits = try self.resolveUsedTraits(trait_name, subs);
            defer self.allocator.free(traits);
            try self.composeTraitMethods(&comp, traits, self.trait_rules.get(trait_name) orelse .{});
        }
        const table = try self.allocator.alloc(TraitMethod, comp.entries.items.len);
        for (comp.entries.items, table) |m, *out| {
            out.* = m;
            out.scope = trait_name;
            out.own = false;
        }
        try self.trait_tables.put(self.allocator, trait_name, table);
        return table;
    }

    fn clearTraitTables(self: *VM) void {
        var it = self.trait_tables.valueIterator();
        while (it.next()) |t| self.allocator.free(t.*);
        self.trait_tables.clearRetainingCapacity();
        for (self.trait_tables_retired.items) |t| self.allocator.free(t);
        self.trait_tables_retired.clearRetainingCapacity();
    }

    // the traits a `use` names, loaded, by their declared names; a trait
    // named twice is used once (null in its later places)
    fn resolveUsedTraits(self: *VM, user: []const u8, written: []const []const u8) RuntimeError![]?[]const u8 {
        const traits = try self.allocator.alloc(?[]const u8, written.len);
        errdefer self.allocator.free(traits);
        for (written, traits, 0..) |w, *out, i| {
            if (!self.traits.contains(w)) {
                try self.tryAutoload(w);
                if (self.pending_exception != null) return error.RuntimeError;
            }
            if (!self.traits.contains(w)) {
                const msg = if (self.classes.contains(w) or self.interfaces.contains(w))
                    try std.fmt.allocPrint(self.allocator, "{s} cannot use {s} - it is not a trait", .{ user, self.declaredClassName(w) })
                else
                    try std.fmt.allocPrint(self.allocator, "Trait \"{s}\" not found", .{w});
                defer self.allocator.free(msg);
                try self.setPendingException("Error", msg);
                return error.RuntimeError;
            }
            const name = self.traits.getKey(w) orelse w;
            out.* = name;
            for (traits[0..i]) |earlier| if (earlier) |e| if (e.ptr == name.ptr) {
                out.* = null;
                break;
            };
        }
        return traits;
    }

    fn traitTableHas(table: []const TraitMethod, name: []const u8) bool {
        for (table) |m| if (std.ascii.eqlIgnoreCase(m.name, name)) return true;
        return false;
    }

    // zend_check_trait_usage, after the class table lookup php makes for a
    // trait an `as` or `insteadof` rule names (no autoloading)
    fn ruleTraitIndex(self: *VM, owner: []const u8, traits: []const ?[]const u8, written: []const u8) RuntimeError!usize {
        const bare = if (written.len > 0 and written[0] == '\\') written[1..] else written;
        const name = self.traits.getKey(bare) orelse {
            const msg = if (self.classes.contains(bare) or self.interfaces.contains(bare))
                try std.fmt.allocPrint(self.allocator, "Class {s} is not a trait, Only traits may be used in 'as' and 'insteadof' statements", .{self.declaredClassName(bare)})
            else
                try std.fmt.allocPrint(self.allocator, "Could not find trait {s}", .{bare});
            defer self.allocator.free(msg);
            return self.raiseFatal(msg);
        };
        for (traits, 0..) |t, i| if (t) |tn| if (tn.ptr == name.ptr) return i;
        const msg = try std.fmt.allocPrint(self.allocator, "Required Trait {s} wasn't added to {s}", .{ name, owner });
        defer self.allocator.free(msg);
        return self.raiseFatal(msg);
    }

    // the interface_gets_implemented handlers of php's internal interfaces,
    // run for every interface a class gets, its parents' included
    // zend_do_implement_interfaces: what a class or enum lists must be
    // interfaces, each named once
    fn checkDeclaredInterfaces(self: *VM, def: *const ClassDef, class_name: []const u8) RuntimeError!void {
        const kind = if (def.is_enum) "Enum" else "Class";
        for (def.interfaces.items, 0..) |iface, i| {
            if (!self.interfaces.contains(iface) and (self.traits.contains(iface) or self.classes.contains(iface)))
                return self.traitRuleFatal("{s} cannot implement {s} - it is not an interface", .{ class_name, iface });
            for (def.interfaces.items[0..i]) |earlier| if (std.ascii.eqlIgnoreCase(earlier, iface)) {
                const msg = try std.fmt.allocPrint(self.allocator, "{s} {s} cannot implement previously implemented interface {s}", .{ kind, class_name, self.declaredClassName(iface) });
                defer self.allocator.free(msg);
                return self.raiseCompileFatal(msg, .{ .file = def.file_path, .line = def.start_line });
            };
        }
    }

    fn checkInterfacesImplemented(self: *VM, def: *const ClassDef, class_name: []const u8) RuntimeError!void {
        var all: std.ArrayListUnmanaged([]const u8) = .empty;
        defer all.deinit(self.allocator);
        var current: ?*const ClassDef = def;
        while (current) |cls| {
            for (cls.interfaces.items) |iface| try self.collectInterface(&all, iface);
            current = if (cls.parent) |p| self.classes.getPtr(p) else null;
        }
        const has = struct {
            fn f(list: []const []const u8, name: []const u8) bool {
                for (list) |item| if (std.ascii.eqlIgnoreCase(item, name)) return true;
                return false;
            }
        }.f;
        const kind = if (def.is_enum) "Enum" else "Class";
        for (all.items) |iface| {
            if (std.ascii.eqlIgnoreCase(iface, "Traversable")) {
                if (def.is_abstract or has(all.items, "Iterator") or has(all.items, "IteratorAggregate")) continue;
                const msg = try std.fmt.allocPrint(self.allocator, "{s} {s} must implement interface Traversable as part of either Iterator or IteratorAggregate", .{ kind, class_name });
                defer self.allocator.free(msg);
                // E_CORE_ERROR: reported with no source position
                return self.raiseCompileFatal(msg, .{ .file = "Unknown", .line = 0 });
            }
            if ((std.ascii.eqlIgnoreCase(iface, "Iterator") and has(all.items, "IteratorAggregate")) or
                (std.ascii.eqlIgnoreCase(iface, "IteratorAggregate") and has(all.items, "Iterator")))
                return self.traitRuleFatal("Class {s} cannot implement both Iterator and IteratorAggregate at the same time", .{class_name});
            if (std.ascii.eqlIgnoreCase(iface, "Throwable") and !self.extendsClass(def, "Exception") and !self.extendsClass(def, "Error")) {
                if (def.is_enum) return self.traitRuleFatal("Enum {s} cannot implement interface Throwable", .{class_name});
                return self.traitRuleFatal("{s} {s} cannot implement interface Throwable, extend Exception or Error instead", .{ kind, class_name });
            }
            // zend_implement_unit_enum and zend_implement_backed_enum
            if (std.ascii.eqlIgnoreCase(iface, "UnitEnum") or std.ascii.eqlIgnoreCase(iface, "BackedEnum")) {
                if (!def.is_enum) return self.traitRuleFatal("Non-enum class {s} cannot implement interface {s}", .{ class_name, self.declaredClassName(iface) });
                if (def.backed_type == .none and std.ascii.eqlIgnoreCase(iface, "BackedEnum")) return self.traitRuleFatal("Non-backed enum {s} cannot implement interface BackedEnum", .{class_name});
            }
            if (std.ascii.eqlIgnoreCase(iface, "DateTimeInterface") and !self.extendsClass(def, "DateTime") and !self.extendsClass(def, "DateTimeImmutable"))
                return self.traitRuleFatal("DateTimeInterface can't be implemented by user classes", .{});
        }
    }

    fn collectInterface(self: *VM, all: *std.ArrayListUnmanaged([]const u8), name: []const u8) !void {
        for (all.items) |seen| if (std.ascii.eqlIgnoreCase(seen, name)) return;
        try all.append(self.allocator, name);
        const idef = self.interfaces.get(name) orelse return;
        for (idef.parents.items) |p| try self.collectInterface(all, p);
        if (idef.parent) |p| try self.collectInterface(all, p);
    }

    // whether a class being declared extends the named class
    fn extendsClass(self: *VM, def: *const ClassDef, ancestor: []const u8) bool {
        var parent = def.parent;
        while (parent) |p| {
            if (std.ascii.eqlIgnoreCase(p, ancestor)) return true;
            parent = if (self.classes.getPtr(p)) |cls| cls.parent else null;
        }
        return false;
    }

    fn traitRuleFatal(self: *VM, comptime fmt: []const u8, args: anytype) RuntimeError {
        const msg = try std.fmt.allocPrint(self.allocator, fmt, args);
        defer self.allocator.free(msg);
        return self.raiseFatal(msg);
    }

    // zend_traits_init_trait_structures, zend_do_traits_method_binding (the
    // non-abstract methods, then the abstract ones) and
    // zend_traits_copy_functions
    fn composeTraitMethods(self: *VM, comp: *TraitComposer, traits: []const ?[]const u8, rules: TraitRules) RuntimeError!void {
        const tables = try self.allocator.alloc([]const TraitMethod, traits.len);
        defer self.allocator.free(tables);
        for (traits, tables) |t, *table| table.* = if (t) |tn| try self.traitTable(tn) else &.{};

        // the methods each trait's insteadof rules exclude
        const excluded = try self.allocator.alloc(std.ArrayListUnmanaged([]const u8), traits.len);
        for (excluded) |*e| e.* = .empty;
        defer {
            for (excluded) |*e| e.deinit(self.allocator);
            self.allocator.free(excluded);
        }
        for (rules.insteadofs) |rule| {
            const ti = try self.ruleTraitIndex(comp.owner, traits, rule.preferred);
            const trait = traits[ti].?;
            if (!traitTableHas(tables[ti], rule.method)) return self.traitRuleFatal("A precedence rule was defined for {s}::{s} but this method does not exist", .{ trait, rule.method });
            for (rule.excluded[0..rule.excluded_count]) |ex| {
                const ei = try self.ruleTraitIndex(comp.owner, traits, ex);
                for (excluded[ei].items) |m| if (std.ascii.eqlIgnoreCase(m, rule.method))
                    return self.traitRuleFatal("Failed to evaluate a trait precedence ({s}). Method of trait {s} was defined to be excluded multiple times", .{ rule.method, traits[ei].? });
                try excluded[ei].append(self.allocator, rule.method);
                if (ei == ti) return self.traitRuleFatal("Inconsistent insteadof definition. The method {s} is to be used from {s}, but {s} is also on the exclude list", .{ rule.method, trait, trait });
            }
        }

        // the trait each `as` rule applies to
        const alias_traits = try self.allocator.alloc(usize, rules.aliases.len);
        defer self.allocator.free(alias_traits);
        for (rules.aliases, alias_traits) |rule, *at| {
            if (rule.trait.len > 0) {
                at.* = try self.ruleTraitIndex(comp.owner, traits, rule.trait);
                if (!traitTableHas(tables[at.*], rule.method)) return self.traitRuleFatal("An alias was defined for {s}::{s} but this method does not exist", .{ traits[at.*].?, rule.method });
                continue;
            }
            var found: ?usize = null;
            for (traits, tables, 0..) |t, table, i| {
                if (t == null or !traitTableHas(table, rule.method)) continue;
                if (found) |f| return self.traitRuleFatal("An alias was defined for method {s}(), which exists in both {s} and {s}. Use {s}::{s} or {s}::{s} to resolve the ambiguity", .{ rule.method, traits[f].?, t.?, traits[f].?, rule.method, t.?, rule.method });
                found = i;
            }
            at.* = found orelse {
                if (rule.alias.len > 0) return self.traitRuleFatal("An alias ({s}) was defined for method {s}(), but this method does not exist", .{ rule.alias, rule.method });
                return self.traitRuleFatal("The modifiers of the trait method {s}() are changed, but this method does not exist. Error", .{rule.method});
            };
        }

        for ([_]bool{ false, true }) |abstract_pass| {
            for (tables, 0..) |table, ti| {
                for (table) |m| {
                    if (m.is_abstract != abstract_pass) continue;
                    // aliases naming a new method
                    for (rules.aliases, alias_traits) |rule, at| {
                        if (rule.alias.len == 0 or at != ti or !std.ascii.eqlIgnoreCase(rule.method, m.name)) continue;
                        var copy = m;
                        applyAliasModifiers(&copy, rule.modifiers);
                        try self.warnPrivateFinalTraitMethod(m, copy, rule.alias);
                        try self.addComposedMethod(comp, rule.alias, copy);
                    }
                    const is_excluded = for (excluded[ti].items) |ex| {
                        if (std.ascii.eqlIgnoreCase(ex, m.name)) break true;
                    } else false;
                    if (is_excluded) continue;
                    var copy = m;
                    for (rules.aliases, alias_traits) |rule, at| {
                        if (rule.alias.len == 0 and rule.modifiers != 0 and at == ti and std.ascii.eqlIgnoreCase(rule.method, m.name)) applyAliasModifiers(&copy, rule.modifiers);
                    }
                    try self.warnPrivateFinalTraitMethod(m, copy, m.name);
                    try self.addComposedMethod(comp, m.name, copy);
                }
            }
        }
    }

    fn applyAliasModifiers(m: *TraitMethod, modifiers: u8) void {
        switch (modifiers & 3) {
            1 => m.visibility = .protected,
            2 => m.visibility = .private,
            3 => m.visibility = .public,
            else => {},
        }
        if (modifiers & 4 != 0) m.is_final = true;
    }

    // zend_traits_check_private_final_inheritance
    fn warnPrivateFinalTraitMethod(self: *VM, original: TraitMethod, copy: TraitMethod, name: []const u8) RuntimeError!void {
        if (original.is_final or !copy.is_final or copy.visibility != .private or std.ascii.eqlIgnoreCase(name, "__construct")) return;
        try self.raiseErrorAt(128, "Private methods cannot be final as they are never overridden by other classes", self.currentSourcePosition());
    }

    // zend_add_trait_method
    fn addComposedMethod(self: *VM, comp: *TraitComposer, name: []const u8, m: TraitMethod) RuntimeError!void {
        var bound = m;
        bound.name = name;
        if (comp.index.get(name)) |idx| {
            const existing = comp.entries.items[idx];
            if (!existing.own and existing.func == m.func and existing.visibility == m.visibility) return;
            if (m.is_abstract) return self.checkAbstractTraitMethod(comp, existing, existing.own, m);
            if (existing.own) return;
            if (!existing.is_abstract) {
                return self.traitRuleFatal("Trait method {s}::{s} has not been applied as {s}::{s}, because of collision with {s}::{s}", .{ m.scope, m.name, comp.owner, name, existing.scope, existing.name });
            }
            comp.entries.items[idx] = bound;
            return;
        }
        // abstract methods are bound after inheritance: an inherited method
        // meets one as the class's own would
        if (m.is_abstract) if (comp.def) |def| {
            var current = def.parent;
            while (current) |parent_name| {
                const parent = self.classes.getPtr(parent_name) orelse break;
                if (parent.methods.get(name)) |info| {
                    const declared = parent.methods.getKey(name).?;
                    var key_buf: [512]u8 = undefined;
                    const func = self.functions.get(class_names.memberKey(&key_buf, parent.name, declared)) orelse return;
                    const inherited: TraitMethod = .{ .name = declared, .func = func, .visibility = info.visibility, .is_static = info.is_static, .is_final = info.is_final, .is_abstract = info.is_abstract, .scope = parent.name };
                    return self.checkAbstractTraitMethod(comp, inherited, true, m);
                }
                current = parent.parent;
            }
        };
        try comp.append(self.allocator, bound);
    }

    // an abstract trait method's signature must be met by the method that
    // takes its place; `self` in either names the composing class
    fn checkAbstractTraitMethod(self: *VM, comp: *const TraitComposer, existing: TraitMethod, existing_is_class: bool, abstract: TraitMethod) RuntimeError!void {
        const placeholder: ClassDef = .{ .name = comp.owner, .is_internal = false };
        const def: *const ClassDef = comp.def orelse &placeholder;
        try inheritance.checkTraitMethod(self, comp.owner, def, .{
            // a trait method bound before the abstract ones is the class's
            // by then (zend_fixup_trait_method)
            .label = if (existing_is_class) existing.scope else comp.owner,
            .self_scope = if (existing_is_class) existing.scope else comp.owner,
            .name = existing.name,
            .func = existing.func,
            .visibility = existing.visibility,
            .is_static = existing.is_static,
            .is_abstract = existing.is_abstract,
            .is_final = existing.is_final,
        }, .{
            .label = abstract.scope,
            .self_scope = comp.owner,
            .name = abstract.name,
            .func = abstract.func,
            .visibility = abstract.visibility,
            .is_static = abstract.is_static,
            .is_abstract = true,
            .is_final = abstract.is_final,
        });
    }

    // zend_do_bind_traits for a class or enum: its methods from the traits
    // it uses (the class's own win), then their properties and constants
    fn bindClassTraits(self: *VM, def: *ClassDef, class_name: []const u8, written: []const []const u8, rules: TraitRules) RuntimeError!void {
        if (written.len == 0) return;
        // php links the parent first: an abstract trait method may be met
        // by an inherited one
        if (def.parent) |parent_name| if (!self.classes.contains(parent_name)) {
            try self.tryAutoload(parent_name);
            if (self.pending_exception != null) return error.RuntimeError;
        };
        const traits = try self.resolveUsedTraits(class_name, written);
        defer self.allocator.free(traits);

        var comp: TraitComposer = .{ .owner = class_name, .def = def };
        defer comp.deinit(self.allocator);
        var key_buf: [512]u8 = undefined;
        for (def.method_order.items) |name| {
            if (std.mem.indexOf(u8, name, "$hook_") != null) continue;
            const info = def.methods.get(name) orelse continue;
            const func = self.functions.get(class_names.memberKey(&key_buf, class_name, name)) orelse continue;
            try comp.append(self.allocator, .{ .name = name, .func = func, .visibility = info.visibility, .is_static = info.is_static, .is_final = info.is_final, .is_abstract = info.is_abstract, .scope = class_name, .own = true });
        }
        try self.composeTraitMethods(&comp, traits, rules);

        for (comp.entries.items) |m| {
            if (m.own) continue;
            var method_buf: [512]u8 = undefined;
            const class_method = class_names.memberKey(&method_buf, class_name, m.name);
            if (!self.functions.contains(class_method)) {
                const copy = try self.traitMethodCopy(m.func, class_method);
                try self.functions.put(self.allocator, copy.name, copy);
                try self.noteRefParams(copy.name, copy);
                try self.indexFunctionByChunk(copy.name, &copy.chunk);
            }
            try def.addMethod(self.allocator, .{
                .name = m.name,
                .arity = m.func.arity,
                .is_static = m.is_static,
                .is_final = m.is_final,
                .is_abstract = m.is_abstract,
                .visibility = m.visibility,
            });
        }
        var composed: std.ArrayListUnmanaged([]const u8) = .empty;
        defer composed.deinit(self.allocator);
        for (traits) |t| if (t) |tn| try self.applyTraitMembers(def, class_name, tn, &composed);
    }

    // php copies a trait's method into the class using it (scope fixed to
    // the class). the copy shares the code; its own chunk address is what
    // ties a frame running it to this class, and it is named as the class's
    // the copy and its name live as long as the vm: serve mode declares the
    // same classes on every request and gets the same copies back
    fn traitMethodCopy(self: *VM, func: *const ObjFunction, class_method: []const u8) RuntimeError!*ObjFunction {
        if (self.trait_method_copies.get(class_method)) |cached| {
            if (cached.chunk.code.items.ptr == func.chunk.code.items.ptr) {
                if (g_type_info.get(func.name)) |ti| try g_type_info.put(self.allocator, cached.name, ti);
                return cached;
            }
        }
        const name = try self.allocator.dupe(u8, class_method);
        errdefer self.allocator.free(name);
        try self.persistent_strings.append(self.allocator, name);
        const copy = try self.allocator.create(ObjFunction);
        errdefer self.allocator.destroy(copy);
        copy.* = func.*;
        copy.name = name;
        if (func.trait_origin.len == 0) copy.trait_origin = func.name;
        // a stale copy (the class was declared from other code) stays
        // allocated: frames may still run it
        if (try self.trait_method_copies.fetchPut(self.allocator, name, copy)) |old| try self.trait_method_stale.append(self.allocator, old.value);
        if (g_type_info.get(func.name)) |ti| try g_type_info.put(self.allocator, name, ti);
        if (self.chunk_to_result.get(@intFromPtr(&func.chunk))) |result| try self.chunk_to_result.put(self.allocator, @intFromPtr(&copy.chunk), result);
        return copy;
    }

    fn isTraitBoundMethod(self: *VM, class_name: []const u8, method: []const u8) bool {
        var key_buf: [512]u8 = undefined;
        const func = self.functions.get(class_names.memberKey(&key_buf, class_name, method)) orelse return false;
        return func.trait_origin.len > 0;
    }

    // a trait's properties, static properties and constants, those of the
    // traits it uses first
    // composed: the traits whose members are the class's already
    fn applyTraitMembers(self: *VM, def: *ClassDef, class_name: []const u8, trait_name: []const u8, composed: *std.ArrayListUnmanaged([]const u8)) !void {
        if (self.trait_uses.get(trait_name)) |subs| {
            for (subs) |sub| {
                const sub_name = self.traits.getKey(sub) orelse continue;
                try self.applyTraitMembers(def, class_name, sub_name, composed);
            }
        }
        defer composed.append(self.allocator, trait_name) catch {};

        // zend_do_traits_property_binding: a property the class already has
        // (its own or an earlier trait's) must be declared the same way
        if (self.trait_props.get(trait_name)) |props| {
            for (props) |prop| {
                var inlined = false;
                const colliding: ?ClassDef.PropertyDef = for (def.properties.items) |existing| {
                    if (!std.mem.eql(u8, existing.name, prop.name)) continue;
                    // the compiler composed this trait's property already, and
                    // those of traits composed after this one
                    if (std.ascii.eqlIgnoreCase(existing.trait_origin, trait_name)) {
                        inlined = true;
                        continue;
                    }
                    if (existing.trait_origin.len > 0) {
                        const earlier = for (composed.items) |c| {
                            if (std.ascii.eqlIgnoreCase(c, existing.trait_origin)) break true;
                        } else false;
                        if (!earlier) continue;
                    }
                    break existing;
                } else null;
                if (colliding) |existing| {
                    try self.checkTraitProperty(def, class_name, trait_name, existing, prop);
                    continue;
                }
                if (def.static_props.contains(prop.name)) return self.traitPropertyConflict(class_name, class_name, trait_name, prop.name, false);
                if (def.is_readonly and !prop.is_readonly) return self.traitRuleFatal("Readonly class {s} cannot use trait with a non-readonly property {s}::${s}", .{ class_name, trait_name, prop.name });
                if (inlined) continue;
                try def.properties.append(self.allocator, prop);
                try def.trait_property_origins.put(self.allocator, prop.name, trait_name);
            }
        }

        if (self.trait_static_props.get(trait_name)) |sprops| {
            for (sprops) |sp| {
                for (def.properties.items) |existing| {
                    if (!std.mem.eql(u8, existing.name, sp.name)) continue;
                    return self.traitPropertyConflict(class_name, if (existing.trait_origin.len > 0) existing.trait_origin else class_name, trait_name, sp.name, false);
                }
                if (def.static_props.contains(sp.name)) {
                    const own_vis: u8 = @intFromEnum(def.static_prop_visibility.get(sp.name) orelse .public);
                    const own_type = def.static_prop_types.get(sp.name) orelse "";
                    if (own_vis != (sp.flags & 3) or !try self.sameConstantType(own_type, class_name, sp.type_str, class_name))
                        return self.traitPropertyConflict(class_name, class_name, trait_name, sp.name, false);
                }
                if (!def.static_props.contains(sp.name)) {
                    // each using class gets its own copy of the trait's static
                    // property - deep-clone so array values are not shared
                    try def.static_props.put(self.allocator, sp.name, try self.copyDefault(sp.value));
                }
            }
        }

        if (self.trait_constants.get(trait_name)) |consts| {
            for (consts) |c| {
                if (def.constants.contains(c.name)) {
                    try self.checkTraitConstant(def, class_name, trait_name, c);
                    continue;
                }
                try self.trait_constant_sources.put(self.allocator, c.name, trait_name);
                {
                    try def.constant_order.append(self.allocator, c.name);
                    // each using class gets its own refcounted copy
                    try def.constants.put(self.allocator, c.name, try self.copyDefault(c.value));
                    try def.constant_docs.put(self.allocator, c.name, c.doc_comment);
                    const vis = c.flags & 0x03;
                    if (vis != 0) try def.const_visibility.put(self.allocator, c.name, @enumFromInt(vis));
                    if (c.flags & 0x10 != 0) try def.const_final.put(self.allocator, c.name, {});
                    if (c.type_str.len > 0) try def.constant_types.put(self.allocator, c.name, c.type_str);
                }
            }
        }
    }

    fn traitPropertyConflict(self: *VM, class_name: []const u8, first: []const u8, trait_name: []const u8, name: []const u8, hooked: bool) RuntimeError {
        if (hooked) return self.traitRuleFatal("{s} and {s} define the same hooked property (${s}) in the composition of {s}. Conflict resolution between hooked properties is currently not supported. Class was composed", .{ first, trait_name, name, class_name });
        return self.traitRuleFatal("{s} and {s} define the same property (${s}) in the composition of {s}. However, the definition differs and is considered incompatible. Class was composed", .{ first, trait_name, name, class_name });
    }

    fn propertyHasHooks(self: *VM, def: *const ClassDef, prop: ClassDef.PropertyDef) bool {
        if (prop.trait_origin.len > 0) return prop.is_hooked;
        var buf: [256]u8 = undefined;
        const getter = std.fmt.bufPrint(&buf, "{s}$hook_get", .{prop.name}) catch return false;
        if (def.methods.contains(getter)) return true;
        const setter = std.fmt.bufPrint(&buf, "{s}$hook_set", .{prop.name}) catch return false;
        _ = self;
        return def.methods.contains(setter);
    }

    // a trait property against the one the class already has: the same
    // visibility, readonly, type and default. a class's own default is
    // installed after the declaration, so that comparison waits for it
    fn checkTraitProperty(self: *VM, def: *ClassDef, class_name: []const u8, trait_name: []const u8, existing: ClassDef.PropertyDef, prop: ClassDef.PropertyDef) RuntimeError!void {
        const first = if (existing.trait_origin.len > 0) existing.trait_origin else class_name;
        if (self.propertyHasHooks(def, existing) or prop.is_hooked) return self.traitPropertyConflict(class_name, first, trait_name, prop.name, true);
        const compatible = existing.visibility == prop.visibility and existing.is_readonly == prop.is_readonly and
            try self.sameConstantType(existing.type_str, class_name, prop.type_str, class_name);
        if (!compatible) return self.traitPropertyConflict(class_name, first, trait_name, prop.name, false);
        if (existing.trait_origin.len == 0 and existing.has_default) {
            try self.trait_property_checks.append(self.allocator, .{ .class = class_name, .name = prop.name, .trait = trait_name, .value = prop.default });
            return;
        }
        if (!traitDefaultsIdentical(existing, prop)) return self.traitPropertyConflict(class_name, first, trait_name, prop.name, false);
    }

    // an untyped property without a default is null, a typed one uninitialized
    fn traitDefaultsIdentical(a: ClassDef.PropertyDef, b: ClassDef.PropertyDef) bool {
        const a_undef = !a.has_default and a.type_str.len > 0;
        const b_undef = !b.has_default and b.type_str.len > 0;
        if (a_undef or b_undef) return a_undef == b_undef;
        return Value.identical(if (a.has_default) a.default else .null, if (b.has_default) b.default else .null);
    }

    // php's do_trait_constant_check: a trait constant the class (or an
    // earlier trait) also has must agree in visibility, final, type and
    // value. the class's own value is set after its declaration, so that
    // comparison waits for it (`trait_constant_checks`)
    fn checkTraitConstant(self: *VM, def: *ClassDef, class_name: []const u8, trait_name: []const u8, c: TraitStaticProp) RuntimeError!void {
        if (def.is_enum) for (def.case_order.items) |case_name| if (std.mem.eql(u8, case_name, c.name)) {
            const trait = self.declaredClassName(trait_name);
            const msg = try std.fmt.allocPrint(self.allocator, "Cannot use trait {s}, because {s}::{s} conflicts with enum case {s}::{s}", .{ trait, trait, c.name, class_name, c.name });
            defer self.allocator.free(msg);
            return self.raiseCompileFatal(msg, .{ .file = def.file_path, .line = def.start_line });
        };
        const first = self.trait_constant_sources.get(c.name) orelse class_name;
        const vis_mismatch = (c.flags & 0x03) != @intFromEnum(def.const_visibility.get(c.name) orelse .public);
        const final_mismatch = (c.flags & 0x10 != 0) != def.const_final.contains(c.name);
        const own_type = def.constant_types.get(c.name) orelse "";
        const type_mismatch = !try self.sameConstantType(own_type, class_name, c.type_str, trait_name);
        if (vis_mismatch or final_mismatch or type_mismatch) return self.traitConstantConflict(def, class_name, trait_name, first, c.name);
        if (first.ptr == class_name.ptr) {
            try self.trait_constant_checks.append(self.allocator, .{ .class = class_name, .name = c.name, .trait = trait_name, .value = c.value });
        } else if (!Value.identical(def.constants.get(c.name) orelse .null, c.value)) {
            return self.traitConstantConflict(def, class_name, trait_name, first, c.name);
        }
    }

    // php composes a trait's own `use` when the trait is declared: a
    // constant it declares must agree with one a trait it uses declares
    fn checkTraitConstantsOfUsedTraits(self: *VM, trait_name: []const u8) RuntimeError!void {
        const subs = self.trait_uses.get(trait_name) orelse return;
        const own = self.trait_constants.get(trait_name) orelse return;
        for (subs) |sub| {
            const sub_name = self.traits.getKey(sub) orelse continue;
            const theirs = self.trait_constants.get(sub_name) orelse continue;
            for (theirs) |c| for (own) |o| {
                if (!std.mem.eql(u8, c.name, o.name)) continue;
                if ((c.flags & 0x13) == (o.flags & 0x13) and
                    try self.sameConstantType(o.type_str, trait_name, c.type_str, trait_name) and
                    Value.identical(o.value, c.value)) continue;
                return self.traitRuleFatal("{s} and {s} define the same constant ({s}) in the composition of {s}. However, the definition differs and is considered incompatible. Class was composed", .{ trait_name, sub_name, c.name, trait_name });
            };
        }
    }

    fn sameConstantType(self: *VM, a: []const u8, a_scope: []const u8, b: []const u8, b_scope: []const u8) RuntimeError!bool {
        if (a.len == 0 or b.len == 0) return a.len == b.len;
        const ta = php_types.parse(self.allocator, a, a_scope, null) catch return error.OutOfMemory;
        defer ta.deinit(self.allocator);
        const tb = php_types.parse(self.allocator, b, b_scope, null) catch return error.OutOfMemory;
        defer tb.deinit(self.allocator);
        const fa = php_types.format(self.allocator, ta) catch return error.OutOfMemory;
        defer self.allocator.free(fa);
        const fb = php_types.format(self.allocator, tb) catch return error.OutOfMemory;
        defer self.allocator.free(fb);
        return std.ascii.eqlIgnoreCase(fa, fb);
    }

    fn traitConstantConflict(self: *VM, def: *const ClassDef, class_name: []const u8, trait_name: []const u8, first: []const u8, name: []const u8) RuntimeError {
        const msg = try std.fmt.allocPrint(self.allocator, "{s} and {s} define the same constant ({s}) in the composition of {s}. However, the definition differs and is considered incompatible. Class was composed", .{ first, trait_name, name, class_name });
        defer self.allocator.free(msg);
        return self.raiseCompileFatal(msg, .{ .file = def.file_path, .line = def.start_line });
    }

    // a class constant's value is set: what a trait it uses declared for the
    // same name must be identical
    fn settleTraitPropertyChecks(self: *VM, class_name: []const u8, prop_name: []const u8, value: Value) RuntimeError!void {
        var i: usize = 0;
        while (i < self.trait_property_checks.items.len) {
            const check = self.trait_property_checks.items[i];
            if (!std.mem.eql(u8, check.class, class_name) or !std.mem.eql(u8, check.name, prop_name)) {
                i += 1;
                continue;
            }
            _ = self.trait_property_checks.orderedRemove(i);
            if (!Value.identical(value, check.value)) return self.traitPropertyConflict(class_name, class_name, check.trait, prop_name, false);
        }
    }

    fn settleTraitConstantChecks(self: *VM, class_name: []const u8, const_name: []const u8, value: Value) RuntimeError!void {
        var i: usize = 0;
        while (i < self.trait_constant_checks.items.len) {
            const check = self.trait_constant_checks.items[i];
            if (!std.mem.eql(u8, check.class, class_name) or !std.mem.eql(u8, check.name, const_name)) {
                i += 1;
                continue;
            }
            _ = self.trait_constant_checks.orderedRemove(i);
            if (!Value.identical(value, check.value)) {
                const def = self.classes.getPtr(class_name) orelse return;
                return self.traitConstantConflict(def, class_name, check.trait, class_name, const_name);
            }
        }
    }

    // closure and frame helpers

    // closure_new: the compiled closure named on top becomes a Closure
    // object. its scope belongs to the instance, not to a particular use
    // capture, so even a static closure without captures records it
    fn newClosureFromTop(self: *VM) !void {
        const compile_name = self.peek().string.bytes();
        const func = self.functions.get(compile_name) orelse return error.RuntimeError;
        const instance = try self.newClosureInstance(compile_name, func);
        self.stack[self.sp - 1] = instance;
        const name = instance.object.closureName().?;
        const lexical_class = self.currentDefiningClass();
        const this_val = self.getLocalByName("$this");
        const scope = if (lexical_class != null)
            self.currentFrame().called_class orelse
                (if (this_val == .object) this_val.object.class_name else lexical_class)
        else
            null;
        if (scope) |class_name| {
            try self.captures.append(self.allocator, .{
                .closure_name = name,
                .var_name = "$__closure_scope",
                .value = .{ .string = Value.String.borrowed(class_name) },
            });
            self.capture_index.getPtr(name).?.len += 1;
        }
        if (lexical_class) |class_name| {
            try self.captures.append(self.allocator, .{
                .closure_name = name,
                .var_name = "$__closure_defclass",
                .value = .{ .string = Value.String.borrowed(class_name) },
            });
            self.capture_index.getPtr(name).?.len += 1;
        }
    }

    // a Closure made from a callable (php's zend_create_fake_closure): the
    // object comes with no reference taken, like allocObject's
    pub fn newFakeClosure(self: *VM, callable: Value, called_class: ?[]const u8) !*PhpObject {
        // php's fake closure holds the object and the function, not an array:
        // a private pair, uncounted, so the cycle collector counts what php's does
        if (callable == .array and callable.array.entries.items.len == 2)
            return self.newFakeMethodClosure(callable.array.entries.items[0].value, callable.array.entries.items[1].value, called_class);
        const target = callable;
        const state = try self.allocator.create(FakeClosure);
        errdefer self.allocator.destroy(state);
        state.* = .{ .callable = target, .called_class = called_class };
        const obj = try self.allocObject(.{
            .class_name = "Closure",
            .native = .{ .kind = .fake_closure, .ptr = @intFromPtr(state) },
        });
        retainValue(target);
        return obj;
    }

    // a Closure of a method: on an object, or a class for a static one
    pub fn newFakeMethodClosure(self: *VM, target: Value, method: Value, called_class: ?[]const u8) !*PhpObject {
        const pair = try self.allocArray();
        try pair.append(self.allocator, target);
        try pair.append(self.allocator, method);
        pair.uncounted = true;
        const state = try self.allocator.create(FakeClosure);
        errdefer self.allocator.destroy(state);
        state.* = .{ .callable = .{ .array = pair }, .called_class = called_class };
        const obj = try self.allocObject(.{
            .class_name = "Closure",
            .native = .{ .kind = .fake_closure, .ptr = @intFromPtr(state) },
        });
        pair.retain();
        return obj;
    }

    fn allocClosureInstanceName(self: *VM, compile_name: []const u8) ![]const u8 {
        var i = self.free_closure_names.items.len;
        while (i > 0) {
            i -= 1;
            if (std.mem.eql(u8, self.free_closure_names.items[i].compile_name, compile_name)) {
                return self.free_closure_names.swapRemove(i).name;
            }
        }
        const id = self.closure_instance_count;
        self.closure_instance_count += 1;
        const name = try std.fmt.allocPrint(self.allocator, "{s}_{d}", .{ compile_name, id });
        try self.strings.append(self.allocator, name);
        return name;
    }

    // a closure instance is a Closure object naming its instance: the vm
    // keys the instance's function, captures and statics by that name. the
    // object comes with the one reference the caller takes; captures
    // appended by the following closure_bind ops extend the registered range
    fn newClosureInstance(self: *VM, compile_name: []const u8, func: *const ObjFunction) !Value {
        const name = try self.allocClosureInstanceName(compile_name);
        const gop = try self.functions.getOrPut(self.allocator, name);
        if (!gop.found_existing) self.live_closure_instances += 1;
        gop.value_ptr.* = func;
        try self.indexFunctionByChunk(name, &func.chunk);
        const obj = try self.allocObject(.{
            .class_name = "Closure",
            .native = .{ .kind = .closure, .ptr = @intFromPtr(name.ptr), .aux = name.len, .extra = @intFromPtr(func) },
        });
        obj.refcount = 1;
        try self.capture_index.put(self.allocator, name, .{
            .start = @intCast(self.captures.items.len),
            .len = 0,
            .has_refs = false,
            .object = obj,
        });
        return .{ .object = obj };
    }

    // a closure instance for a function this vm knows, with captures given
    // up front the way closure_use adds them one call at a time; a closure
    // that arrived from another thread is rebuilt through here
    pub fn bindClosureInstance(self: *VM, compile_name: []const u8, names: []const []const u8, values: []const Value) !Value {
        const func = self.functions.get(compile_name) orelse return error.RuntimeError;
        const instance = try self.newClosureInstance(compile_name, func);
        const name = instance.object.closureName().?;
        for (names, values) |var_name, val| {
            const kept = try self.internName(var_name);
            retainValue(val);
            try self.captures.append(self.allocator, .{ .closure_name = name, .var_name = kept, .value = val });
            self.capture_index.getPtr(name).?.len += 1;
        }
        return instance;
    }

    // a property keeps the name bytes it is given, so a name taken from an
    // array key must outlive the array it came from
    pub fn propertyNameFromKey(self: *VM, key: PhpArray.Key) ![]const u8 {
        return switch (key) {
            .string => |s| self.internName(s.bytes()),
            .int => |i| {
                var buf: [24]u8 = undefined;
                return self.internName(std.fmt.bufPrint(&buf, "{d}", .{i}) catch unreachable);
            },
        };
    }

    // zend_nan_coerced_to_type_warning, for a NAN made a bool
    pub inline fn warnNanToBool(self: *VM, v: Value) RuntimeError!void {
        if (v == .float and std.math.isNan(v.float)) try self.emitWarning("unexpected NAN value was coerced to bool");
    }

    pub fn castToObject(self: *VM, v: Value) !Value {
        if (v == .object) return v;
        if (v == .float and std.math.isNan(v.float)) try self.emitWarning("unexpected NAN value was coerced to object");
        const obj = try self.allocUserObject("stdClass");
        switch (v) {
            .array => |arr| for (arr.entries.items) |entry| {
                try obj.set(self.allocator, try self.propertyNameFromKey(entry.key), entry.value);
            },
            .null => {},
            else => try obj.set(self.allocator, "scalar", v),
        }
        return .{ .object = obj };
    }

    pub fn castToArray(self: *VM, v: Value) !Value {
        if (v == .array) return v;
        if (v == .float and std.math.isNan(v.float)) try self.emitWarning("unexpected NAN value was coerced to array");
        const arr = try self.allocArray();
        switch (v) {
            // php converts a closure as it does a scalar: an array holding it
            .object => |o| if (std.mem.eql(u8, o.class_name, "Closure")) try arr.append(self.allocator, v) else try self.copyPropertiesToArray(o.storage(), arr),
            .null => {},
            else => try arr.append(self.allocator, v),
        }
        return .{ .array = arr };
    }

    fn copyPropertiesToArray(self: *VM, obj: *PhpObject, arr: *PhpArray) !void {
        if (try object_properties.table(self, obj, .array_cast)) |built| {
            defer object_properties.releaseBuilt(self, built);
            for (built.entries.items) |entry| try arr.set(self.allocator, entry.key, if (entry.ref) |ref| ref.* else entry.value);
            return;
        }
        var listing: object_properties.Listing = .{};
        defer listing.deinit(self.allocator);
        try object_properties.appendOwn(self, obj, .array_cast, &listing, self.allocator);
        for (listing.items.items) |prop| try self.setPropertyKey(arr, prop);
    }

    // php's (array) key for a property: the bare name when public, else the
    // name mangled with its visibility. a declared name is class metadata and
    // its mangled form is interned; an object's own names are copied
    fn setPropertyKey(self: *VM, arr: *PhpArray, prop: object_properties.Property) !void {
        const name = prop.key.name;
        if (prop.visibility == .public) {
            if (prop.declared) return arr.set(self.allocator, .{ .string = Value.String.borrowed(name) }, prop.value);
            return arr.setCopiedKey(self.allocator, name, prop.value);
        }
        var mangled: std.ArrayListUnmanaged(u8) = .empty;
        defer mangled.deinit(self.allocator);
        if (prop.visibility == .protected) try mangled.print(self.allocator, "\x00*\x00{s}", .{name}) else try mangled.print(self.allocator, "\x00{s}\x00{s}", .{ prop.declaring, name });
        if (prop.declared) return arr.set(self.allocator, .{ .string = Value.String.borrowed(try self.internName(mangled.items)) }, prop.value);
        try arr.setCopiedKey(self.allocator, mangled.items, prop.value);
    }

    // a directive's runtime value; the previous runtime value is freed
    // zend.assertions: 1 runs assert() calls, 0 skips them, -1 is php's
    // "compiled out", which zphp also does at run time
    pub fn assertionsMode(self: *VM) i64 {
        const text = self.ini_settings.get("zend.assertions") orelse return 1;
        return @import("memory.zig").parseQuantity(text).value;
    }

    pub fn setIni(self: *VM, name: []const u8, value: []const u8) ![]const u8 {
        const key = try self.internName(name);
        const gop = try self.ic.?.ini_values.getOrPut(self.allocator, key);
        const owned = self.allocator.dupe(u8, value) catch |err| {
            if (!gop.found_existing) self.ic.?.ini_values.removeByPtr(gop.key_ptr);
            return err;
        };
        try self.ini_settings.put(self.allocator, key, owned);
        if (gop.found_existing) self.allocator.free(gop.value_ptr.*);
        gop.value_ptr.* = owned;
        return owned;
    }

    // back to the file's value, or to the built-in default when the file has none
    pub fn restoreIni(self: *VM, name: []const u8) !void {
        _ = self.ini_settings.remove(name);
        if (self.ic.?.ini_values.fetchRemove(name)) |kv| self.allocator.free(kv.value);
        if (@import("../ini_config.zig").get(name)) |configured| try self.ini_settings.put(self.allocator, try self.internName(name), configured);
    }

    fn freeIniValues(self: *VM, ic_ptr: *InlineCache) void {
        var values = ic_ptr.ini_values.valueIterator();
        while (values.next()) |value| self.allocator.free(value.*);
        ic_ptr.ini_values.clearRetainingCapacity();
    }

    // "$name" for a variable a frame's vars map will borrow, interned
    pub fn internVarName(self: *VM, name: []const u8) ![]const u8 {
        const dollar = try std.fmt.allocPrint(self.allocator, "${s}", .{name});
        defer self.allocator.free(dollar);
        return self.internName(dollar);
    }

    // request-lifetime bytes for a name that recurs across calls, kept once
    pub fn internName(self: *VM, name: []const u8) ![]const u8 {
        if (self.interned_names.getKey(name)) |kept| return kept;
        const kept = try self.allocator.dupe(u8, name);
        errdefer self.allocator.free(kept);
        try self.strings.append(self.allocator, kept);
        try self.interned_names.put(self.allocator, kept, {});
        return kept;
    }

    // a variable of the frame below the current one: what a native sees as
    // its caller's scope
    pub fn callerVar(self: *VM, name: []const u8) ?Value {
        if (self.frame_count < 2) return null;
        return self.frameVariable(&self.frames[self.frame_count - 2], name);
    }

    // a frame's variable by name, null when it holds nothing: reference cells
    // win, then the slot, then the map
    // the element at key (appended when null) becomes a reference to the
    // variable, which turns into a reference first if it isn't one
    // `$o[$k] = &$var` on an ArrayObject or ArrayIterator without its own
    // offsetGet binds the element of the storage array (read_dimension for
    // BP_VAR_W); null with an exception pending when the offset is refused
    fn splRefTarget(self: *VM, arr_val: Value, key_val: Value) RuntimeError!?@import("../stdlib/spl.zig").RefTarget {
        if (arr_val != .object or !try self.splOwnOffsetGet(arr_val.object)) return null;
        var ctx = self.makeContext(null);
        return @import("../stdlib/spl.zig").arrayStorageRefTarget(&ctx, arr_val.object, key_val) catch |err| {
            if (self.pending_exception != null) return null;
            return err;
        };
    }

    fn bindArrayElementRef(self: *VM, arr_val: Value, key_opt: ?PhpArray.Key, var_name: []const u8) RuntimeError!Value {
        const cell = try self.getOrCreateVarCell(self.currentFrame(), var_name);
        if (arr_val == .array) {
            const arr_ptr = arr_val.array;
            const key: PhpArray.Key = if (key_opt) |k| k else .{ .int = if (arr_ptr.has_int_keys) arr_ptr.next_int_key else 0 };
            // the element becomes a mirror of the cell
            if (key_opt != null) try self.arraySetOwned(arr_ptr, key, cell.*) else try arr_ptr.append(self.allocator, cell.*);
            if (arr_ptr.getPtr(key)) |ep| self.setEntryRef(ep, cell);
            try self.array_ref_bindings.append(self.allocator, .{ .cell = cell, .array = arr_ptr, .key = key });
            try self.regRefArray(try self.persistentRefOwner(), cell, arr_ptr, key);
            self.array_ref_active = true;
        }
        return cell.*;
    }

    fn frameSlot(self: *VM, frame: *const CallFrame, name: []const u8) ?u16 {
        const slot_names = if (frame.slot_names.len > 0) frame.slot_names else if (frame.func) |f| f.slot_names else self.global_slot_names;
        for (slot_names, 0..) |sn, si| {
            if (std.mem.eql(u8, sn, name)) return if (si < frame.locals.len) @intCast(si) else null;
        }
        return null;
    }

    pub fn frameVariable(self: *VM, frame: *CallFrame, name: []const u8) ?Value {
        if (frame.ref_slots.get(name)) |cell| return cell.*;
        const slot_names = if (frame.slot_names.len > 0) frame.slot_names else if (frame.func) |f| f.slot_names else self.global_slot_names;
        for (slot_names, 0..) |sn, si| {
            if (!std.mem.eql(u8, sn, name)) continue;
            if (si < frame.locals.len and frame.locals[si] != .undef) return frame.locals[si];
            break;
        }
        return frame.vars.get(name);
    }

    // foreach over a Traversable runs through an iterator php keeps as an
    // object of its own, taking a handle for the loop; it sits in the loop's
    // position slot, so the handle goes back when the slot is released
    fn pushIteratorMarker(self: *VM) RuntimeError!void {
        const marker = try self.allocObject(.{ .class_name = "InternalIterator" });
        self.push(.{ .object = marker });
    }

    const new_reservation = "\x00new";

    // the handle new_reserve set aside, from the placeholder `depth` slots
    // under the top; the placeholder gives it up, so releasing it frees nothing
    fn takeReservedHandle(self: *VM, depth: usize) u32 {
        if (self.sp < depth + 1) return 0;
        const slot = self.stack[self.sp - depth - 1];
        if (slot != .object or slot.object.class_name.ptr != new_reservation.ptr) return 0;
        const handle = slot.object.id;
        slot.object.id = 0;
        return handle;
    }

    fn releaseGeneratorClosure(self: *VM, gen: *Generator) void {
        const closure = gen.closure orelse return;
        gen.closure = null;
        self.objRelease(closure);
    }

    // a closure's generator keeps the Closure object alive, as php's does
    fn keepGeneratorClosure(self: *VM, gen: *Generator, name: []const u8) void {
        const range = self.capture_index.get(name) orelse return;
        const closure = range.object orelse return;
        objRetain(closure);
        gen.closure = closure;
    }

    const HeldOperands = struct { values: [17]Value = undefined, len: usize = 0 };

    // the top `count` operands, counted until releaseHeld: a call that pops
    // its receiver and arguments before running php code keeps them alive
    fn holdCallOperands(self: *VM, count: usize) HeldOperands {
        var held: HeldOperands = .{};
        held.len = @min(count, held.values.len);
        for (0..held.len) |i| {
            held.values[i] = self.stack[self.sp - held.len + i];
            retainValue(held.values[i]);
        }
        return held;
    }

    fn releaseHeld(self: *VM, held: HeldOperands) void {
        for (held.values[0..held.len]) |value| self.releaseValue(value);
    }

    // php's FE_FREE drops the iterated value, then the iterator
    // a live by-reference foreach keeps the index of the next element and
    // how much of the array's removal log it has applied in its position slot
    fn liveIterState(next: usize, seen: usize) i64 {
        return @intCast((@as(u64, @intCast(seen)) << 32) | @as(u64, @intCast(next)));
    }

    // php's FE_FETCH_RW over a HashTable iterator: finds the loop's place in
    // the array the variable holds now (its own, a copy made of it while the
    // loop ran, or a new one, where it starts over), pushes the next key and
    // value and moves past them. false when the loop is done
    fn liveIterStep(self: *VM, current: Value) bool {
        if (current != .array) return false;
        const arr = current.array;
        const stored: usize = @intCast(self.stack[self.sp - 2].int);
        const state: u64 = @intCast(self.stack[self.sp - 1].int);
        var next: usize = @intCast(state & 0xffffffff);
        var seen: usize = @intCast(state >> 32);
        // an array reused at the same address has no log of its own
        if (@intFromPtr(arr) != stored or arr.iter_log == null) {
            const copied = if (arr.iter_log) |log| if (log.copied_from) |from| @intFromPtr(from) == stored else false else false;
            const log = arr.iterLog() orelse return false;
            log.loops += 1;
            if (!copied) {
                // zend_hash_iterator_pos_ex on another array: its internal
                // pointer
                next = @min(arr.cursor, arr.entries.items.len);
                seen = log.removed.items.len;
            }
            self.stack[self.sp - 2] = .{ .int = @intCast(@intFromPtr(arr)) };
        }
        const log = arr.iter_log.?;
        // an entry removed before the loop's place moved the rest back
        if (seen < log.removed.items.len) {
            for (log.removed.items[seen..]) |idx| {
                if (idx < next) next -= 1;
            }
            seen = log.removed.items.len;
        }
        if (next >= arr.entries.items.len) {
            self.stack[self.sp - 1] = .{ .int = liveIterState(next, seen) };
            return false;
        }
        const entry = arr.entries.items[next];
        self.stack[self.sp - 1] = .{ .int = liveIterState(next + 1, seen) };
        self.push(switch (entry.key) {
            .int => |i| .{ .int = i },
            .string => |s| .{ .string = s },
        });
        self.push(if (entry.ref) |cell| cell.* else entry.value);
        return true;
    }

    fn endForeach(self: *VM) void {
        const position = self.stack[self.sp - 1];
        self.stack[self.sp - 1] = .null;
        _ = self.pop();
        _ = self.pop();
        if (position == .object and self.hasPendingReleases()) self.drainPendingDestruct();
        self.stackRelease(position);
    }

    // the Closure object of a closure instance
    pub fn closureObject(self: *VM, name: []const u8) ?*PhpObject {
        const range = self.capture_index.get(name) orelse return null;
        return range.object;
    }

    // a frame running a closure holds its Closure object, as php's call
    // frame does
    pub fn retainClosureByName(self: *VM, name: []const u8) void {
        const range = self.capture_index.getPtr(name) orelse return;
        if (range.object) |obj| objRetain(obj);
    }

    pub fn releaseClosureByName(self: *VM, name: []const u8) void {
        const range = self.capture_index.getPtr(name) orelse return;
        const obj = range.object orelse return;
        self.objRelease(obj);
    }

    // a Closure object is being freed: release what its instance captured
    // (into the caller's release log, so they go before the object's own
    // handle, as php frees a closure's bound object and statics first),
    // forget its function alias and statics, recycle the name
    fn releaseClosureInstance(self: *VM, obj: *PhpObject) void {
        const name = obj.closureName() orelse return;
        obj.native = .{};
        if (self.heap_teardown) return;
        if (self.capture_index.fetchRemove(name)) |removed| {
            const range = removed.value;
            for (0..range.len) |i| {
                const capture = &self.captures.items[range.start + i];
                self.releaseValue(capture.value);
                capture.value = .null;
                const old_cell = capture.ref_cell;
                capture.ref_cell = null;
                if (old_cell) |cell| self.unbindCell(cell);
            }
            if (range.ref_owner != 0) if (self.ref_index) |ri| ri.releaseOwner(self.allocator, range.ref_owner);
            self.captures_dead += range.len;
            if (range.has_statics) self.purgeClosureStatics(name);
            if (self.functions.fetchRemove(name)) |fn_entry| {
                self.live_closure_instances -|= 1;
                if (self.chunk_to_func_names.getPtr(@intFromPtr(&fn_entry.value.chunk))) |names| {
                    for (names.items, 0..) |existing, idx| if (existing.ptr == name.ptr) {
                        _ = names.swapRemove(idx);
                        break;
                    };
                }
            }
            if (std.mem.lastIndexOfScalar(u8, name, '_')) |separator| {
                self.free_closure_names.append(self.allocator, .{ .compile_name = name[0..separator], .name = name }) catch {};
            }
            self.compactCapturesIfNeeded();
        }
    }

    fn purgeClosureStatics(self: *VM, name: []const u8) void {
        var dead_keys: std.ArrayListUnmanaged([]const u8) = .empty;
        defer dead_keys.deinit(self.allocator);
        var it = self.statics_cells.iterator();
        while (it.next()) |entry| {
            const key = entry.key_ptr.*;
            if (key.len > name.len + 2 and std.mem.startsWith(u8, key, name) and key[name.len] == ':' and key[name.len + 1] == ':') {
                dead_keys.append(self.allocator, key) catch return;
            }
        }
        for (dead_keys.items) |key| {
            if (self.statics_cells.fetchRemove(key)) |cell_entry| {
                self.unbindCell(cell_entry.value);
            }
            _ = self.statics.remove(key);
        }
    }

    // dead ranges leave holes in self.captures; rebuild it from the live
    // ranges once the holes dominate so a closure-heavy loop stays bounded
    fn compactCapturesIfNeeded(self: *VM) void {
        if (self.captures_dead < 64 or self.captures_dead * 2 < self.captures.items.len) return;
        var compacted: std.ArrayListUnmanaged(CaptureEntry) = .empty;
        compacted.ensureTotalCapacity(self.allocator, self.captures.items.len - self.captures_dead) catch return;
        var live = self.capture_index.iterator();
        while (live.next()) |entry| {
            const old = entry.value_ptr.*;
            const start: u32 = @intCast(compacted.items.len);
            compacted.appendSlice(self.allocator, self.captures.items[old.start .. old.start + old.len]) catch return;
            entry.value_ptr.start = start;
        }
        self.captures.deinit(self.allocator);
        self.captures = compacted;
        self.captures_dead = 0;
    }

    // request teardown: every capture goes away with the request, so release
    // what the ranges hold before the heap bulk-free destroys the containers
    // those values point at
    fn teardownCaptures(self: *VM) void {
        if (platform.getenv("ZPHP_HEAP_STATS") != null) {
            var it = self.capture_index.iterator();
            while (it.next()) |entry| if (entry.value_ptr.object) |owner| {
                const compile_name = self.getOrigClosureName(entry.key_ptr.*);
                const loc_file = if (self.functions.get(compile_name)) |f| f.file_path else "?";
                const loc_line = if (self.functions.get(compile_name)) |f| f.start_line else 0;
                std.debug.print("heap: closure {s} at {s}:{d} still referenced at teardown (refcount {d}, {d} captures:", .{ entry.key_ptr.*, loc_file, loc_line, owner.refcount, entry.value_ptr.len });
                const range = entry.value_ptr.*;
                for (self.captures.items[range.start .. range.start + range.len]) |cap| std.debug.print(" {s}", .{cap.var_name});
                std.debug.print(")\n", .{});
            };
        }
        var ranges = self.capture_index.valueIterator();
        while (ranges.next()) |range| {
            // the object outlives its instance now: it names nothing
            if (range.object) |obj| obj.native = .{};
            for (0..range.len) |i| {
                const capture = &self.captures.items[range.start + i];
                self.releaseValue(capture.value);
                capture.value = .null;
                const old_cell = capture.ref_cell;
                capture.ref_cell = null;
                if (old_cell) |cell| self.unbindCell(cell);
            }
        }
        self.capture_index.clearRetainingCapacity();
        self.captures.clearRetainingCapacity();
        self.captures_dead = 0;
        self.free_closure_names.clearRetainingCapacity();
    }

    // a new closure instance without the reference it was created with, for
    // a native to return as its result (natives' results are borrowed)
    pub fn disownedClosure(self: *VM, value: Value) Value {
        _ = self;
        if (value == .object) value.object.refcount -= 1;
        return value;
    }

    const CallableCheck = union(enum) { ok, failed: callables.Failure };

    // a first-class callable's target, resolved as a dynamic call would be.
    // `Class::method(...)` of an instance method from inside an instance of
    // that class is bound to $this (rewritten in pair), as php does; names
    // relative to the scope (self, parent, static) are resolved when called
    fn callableClosureCheck(self: *VM, callable: Value, pair: *?*PhpArray, function: *?[]const u8, forwarded: *?[]const u8) RuntimeError!CallableCheck {
        if (callable == .string and std.mem.indexOf(u8, callable.string.bytes(), "::") == null) {
            const raw = callable.string.bytes();
            const name = if (raw.len > 0 and raw[0] == '\\') raw[1..] else raw;
            function.* = self.canonicalFunctionName(name) orelse self.resolveFunctionName(name) orelse
                return .{ .failed = .{ .function_not_found = name } };
            return .ok;
        }
        if (callable == .array and callable.array.entries.items.len == 2) {
            const target = callable.array.entries.items[0].value;
            const method = callable.array.entries.items[1].value;
            if (target == .string and method == .string) {
                var class = target.string.bytes();
                var named = callable;
                // self::, parent:: and static:: name classes of the scope the
                // closure is made in
                const relative = std.ascii.eqlIgnoreCase(class, "self") or std.ascii.eqlIgnoreCase(class, "parent") or std.ascii.eqlIgnoreCase(class, "static");
                if (relative) {
                    const this = self.scopeThis();
                    const resolved: ?[]const u8 = if (std.ascii.eqlIgnoreCase(class, "static"))
                        (if (self.frame_count > 0) self.currentFrame().called_class else null) orelse (if (this) |t| t.class_name else null) orelse self.currentDefiningClass()
                    else
                        self.intentClassName(class);
                    // self:: and parent:: forward the called class, which a
                    // static method's static:: names
                    if (!std.ascii.eqlIgnoreCase(class, "static")) {
                        const called = (if (self.frame_count > 0) self.currentFrame().called_class else null) orelse (if (this) |t| t.class_name else null);
                        if (called) |c| if (resolved) |r| if (!std.ascii.eqlIgnoreCase(c, r) and self.isInstanceOf(c, r)) {
                            forwarded.* = c;
                        };
                    }
                    class = resolved orelse return .{ .failed = .{ .no_scope = class } };
                    const rewritten = try self.allocArray();
                    try rewritten.append(self.allocator, .{ .string = Value.String.borrowed(class) });
                    try rewritten.append(self.allocator, method);
                    pair.* = rewritten;
                    named = .{ .array = rewritten };
                }
                switch (try callables.resolveDynamic(self, named)) {
                    .callee => return .ok,
                    .failure => |failure| {
                        if (failure == .non_static) if (self.scopeThis()) |this| if (self.isInstanceOf(this.class_name, class)) {
                            const bound = try self.allocArray();
                            try bound.append(self.allocator, .{ .object = this });
                            try bound.append(self.allocator, method);
                            pair.* = bound;
                            return .ok;
                        };
                        return .{ .failed = failure };
                    },
                }
            }
        }
        return switch (try callables.resolveDynamic(self, callable)) {
            .callee => .ok,
            .failure => |failure| .{ .failed = failure },
        };
    }

    // a copy of a closure instance bound to new_this, scope (the class it
    // runs in, php's func.common.scope) and called (what static:: names):
    // the captures are shared, by-reference ones still bound to their cells,
    // and the static variables are copied with their current values, as
    // zend_create_closure does
    pub fn copyClosureInstance(self: *VM, closure_name: []const u8, new_this: Value, scope: ?[]const u8, called: ?[]const u8) !Value {
        const func = self.functions.get(closure_name) orelse return .null;
        const instance = try self.newClosureInstance(self.getOrigClosureName(closure_name), func);
        const new_name = instance.object.closureName().?;
        const new_start: u32 = @intCast(self.captures.items.len);
        var has_refs = false;
        if (self.capture_index.get(closure_name)) |cr| {
            var i: usize = 0;
            while (i < cr.len) : (i += 1) {
                // self.captures may move as it grows: index, never hold a slice
                const cap = self.captures.items[cr.start + i];
                if (std.mem.eql(u8, cap.var_name, "$this") or
                    std.mem.eql(u8, cap.var_name, "$__closure_scope") or
                    std.mem.eql(u8, cap.var_name, "$__closure_defclass")) continue;
                var new_cap = CaptureEntry{ .closure_name = new_name, .var_name = cap.var_name, .value = cap.value, .ref_cell = cap.ref_cell };
                if (new_cap.ref_cell) |cell| {
                    new_cap.value = cell.*;
                    self.bindCell(cell);
                    has_refs = true;
                }
                // the copy holds its own reference
                retainValue(new_cap.value);
                try self.captures.append(self.allocator, new_cap);
                if (new_cap.ref_cell) |cell| try self.regRefCapture(self.capture_index.getPtr(new_name).?, cell, new_cap.var_name);
            }
        }
        if (new_this == .object) {
            retainValue(new_this);
            try self.captures.append(self.allocator, .{ .closure_name = new_name, .var_name = "$this", .value = new_this });
        }
        if (called) |class_name| try self.captures.append(self.allocator, .{
            .closure_name = new_name,
            .var_name = "$__closure_scope",
            .value = .{ .string = Value.String.borrowed(class_name) },
        });
        if (scope) |class_name| try self.captures.append(self.allocator, .{
            .closure_name = new_name,
            .var_name = "$__closure_defclass",
            .value = .{ .string = Value.String.borrowed(class_name) },
        });
        const range = self.capture_index.getPtr(new_name).?;
        range.start = new_start;
        range.len = @intCast(self.captures.items.len - new_start);
        range.has_refs = has_refs;
        try self.copyClosureStatics(closure_name, new_name, func);
        return instance;
    }

    fn copyClosureStatics(self: *VM, from: []const u8, to: []const u8, func: *const ObjFunction) !void {
        for (func.static_vars) |sv| {
            var from_buf: [256]u8 = undefined;
            const from_key = class_names.memberKey(&from_buf, from, sv.name);
            const value = if (self.statics_cells.get(from_key)) |cell| cell.* else if (self.statics.get(from_key)) |v| v else continue;
            var to_buf: [256]u8 = undefined;
            const to_key = try self.internName(class_names.memberKey(&to_buf, to, sv.name));
            const cell = try self.newRefCell();
            self.setCell(cell, try self.copyValue(value));
            try self.bindRefSlot(&self.statics_cells, to_key, cell);
            if (self.capture_index.getPtr(to)) |range| range.has_statics = true;
        }
    }

    // a static closure, a closure using $this, a method's closure: how a
    // binding of new_this and scope would break it, in php's words
    // (zend_valid_closure_binding); null when the binding is valid
    pub fn closureBindingRefusal(self: *VM, closure: *PhpObject, new_this: Value, scope: ?[]const u8) RuntimeError!?[]const u8 {
        if (closure.closureName()) |name| {
            const func = self.functions.get(name) orelse return null;
            if (new_this == .object) {
                if (func.is_static) return try self.allocator.dupe(u8, "Cannot bind an instance to a static closure, this will be an error in PHP 9");
            } else if (self.closureThisByName(name) == .object and closureUsesThis(func)) {
                return try self.allocator.dupe(u8, "Cannot unbind $this of closure using $this, this will be an error in PHP 9");
            }
            return self.internalScopeRefusal(scope, self.closureDefClassByName(name));
        }
        const target = self.fakeClosureTarget(closure);
        if (new_this == .object) {
            if (target.is_static) return try self.allocator.dupe(u8, "Cannot bind an instance to a static closure, this will be an error in PHP 9");
            if (target.scope) |class| if (!self.isInstanceOf(new_this.object.class_name, class)) {
                return try std.fmt.allocPrint(self.allocator, "Cannot bind method {s}::{s}() to object of class {s}, this will be an error in PHP 9", .{ class, target.method, new_this.object.class_name });
            };
        } else if (target.scope != null and !target.is_static) {
            return try self.allocator.dupe(u8, "Cannot unbind $this of method, this will be an error in PHP 9");
        }
        if (try self.internalScopeRefusal(scope, target.scope)) |msg| return msg;
        if (!sameClass(scope, target.scope)) {
            return try self.allocator.dupe(u8, if (target.scope == null)
                "Cannot rebind scope of closure created from function, this will be an error in PHP 9"
            else
                "Cannot rebind scope of closure created from method, this will be an error in PHP 9");
        }
        return null;
    }

    fn internalScopeRefusal(self: *VM, scope: ?[]const u8, current: ?[]const u8) RuntimeError!?[]const u8 {
        const class = scope orelse return null;
        if (sameClass(scope, current)) return null;
        const def = self.classes.get(class) orelse return null;
        if (!def.is_internal) return null;
        return try std.fmt.allocPrint(self.allocator, "Cannot bind closure to scope of internal class {s}, this will be an error in PHP 9", .{self.declaredClassName(class)});
    }

    fn sameClass(a: ?[]const u8, b: ?[]const u8) bool {
        if (a == null or b == null) return a == null and b == null;
        return std.ascii.eqlIgnoreCase(a.?, b.?);
    }

    // php's ZEND_ACC_USES_THIS: the closure's body reads $this. every
    // closure has a $this slot, so the body's reads of it decide
    fn closureUsesThis(func: *const ObjFunction) bool {
        var this_slot: ?u16 = null;
        for (func.slot_names, 0..) |slot, i| if (std.mem.eql(u8, slot, "$this")) {
            this_slot = @intCast(i);
        };
        const code = func.chunk.code.items;
        var ip: usize = 0;
        while (ip < code.len) {
            const op: OpCode = @enumFromInt(code[ip]);
            switch (op) {
                .get_local, .get_local_quiet => if (this_slot) |slot| {
                    if (std.mem.readInt(u16, code[ip + 1 ..][0..2], .big) == slot) return true;
                },
                .get_var, .get_var_quiet => {
                    const name = func.chunk.constants.items[std.mem.readInt(u16, code[ip + 1 ..][0..2], .big)];
                    if (name == .string and std.mem.eql(u8, name.string.bytes(), "$this")) return true;
                },
                else => {},
            }
            ip += op.width();
        }
        return false;
    }

    pub const FakeClosureTarget = struct {
        // the declaring class of a method, null for a function
        scope: ?[]const u8 = null,
        method: []const u8 = "",
        is_static: bool = false,
    };

    // what a Closure made from a callable (first-class callable syntax,
    // fromCallable) calls: its function's scope and staticness
    pub fn fakeClosureTarget(self: *VM, closure: *PhpObject) FakeClosureTarget {
        const callable = closure.fakeCallable();
        var class: []const u8 = "";
        var method: []const u8 = "";
        switch (callable) {
            .string => |s| {
                const text = s.bytes();
                const sep = std.mem.indexOf(u8, text, "::") orelse return .{};
                class = text[0..sep];
                method = text[sep + 2 ..];
            },
            .array => |arr| {
                if (arr.entries.items.len != 2) return .{};
                const target = arr.entries.items[0].value;
                const m = arr.entries.items[1].value;
                if (m != .string) return .{};
                method = m.string.bytes();
                class = switch (target) {
                    .object => |o| o.class_name,
                    .string => |cs| cs.bytes(),
                    else => return .{},
                };
            },
            else => return .{},
        }
        const vis = self.findMethodVisibility(class, method);
        const declaring = if (vis.defining_class.len > 0) vis.defining_class else class;
        const info: ?ClassDef.MethodInfo = if (self.classes.get(declaring)) |cls| cls.methods.get(method) else null;
        return .{
            .scope = self.declaredClassName(declaring),
            .method = if (info) |i| i.name else method,
            .is_static = if (info) |i| i.is_static else false,
        };
    }

    // a function frame's local by name; one that holds nothing reads as null
    fn getLocalByName(self: *VM, name: []const u8) Value {
        const frame = self.currentFrame();
        if (frame.func) |func| {
            for (func.slot_names, 0..) |sn, si| {
                if (std.mem.eql(u8, sn, name)) {
                    if (si < frame.locals.len and frame.locals[si] != .undef) return frame.locals[si];
                    break;
                }
            }
        }
        return .null;
    }

    // the running frame has no value under the name: a slot that holds
    // nothing, or no slot and no variable at all
    fn localHoldsNothing(self: *VM, name: []const u8) bool {
        const frame = self.currentFrame();
        if (frame.vars.contains(name)) return false;
        const names = if (frame.func) |func| func.slot_names else self.global_slot_names;
        for (names, 0..) |sn, si| {
            if (!std.mem.eql(u8, sn, name)) continue;
            return si >= frame.locals.len or frame.locals[si] == .undef;
        }
        return true;
    }

    fn saveFrameLocalsToGenerator(self: *VM, gen: *Generator) void {
        const frame = self.currentFrame();
        gen.locals.clearRetainingCapacity();
        if (frame.locals.len > 0) {
            gen.locals.appendSlice(self.allocator, frame.locals) catch {};
            self.allocator.free(frame.locals);
            self.currentFrame().locals = &.{};
        }
        // the references its variables are bound to (an element, a property)
        // stay registered while it waits: the frame's owner of those
        // bindings goes with the generator and comes back when it resumes
        const f = self.currentFrame();
        self.deinitRefSlots(&f.ref_slots);
        f.ref_slots = .{};
        if (f.ref_owner != 0 and gen.ref_owner != f.ref_owner) self.releaseGeneratorBindings(gen);
        gen.ref_owner = f.ref_owner;
        f.ref_owner = 0;
    }

    fn releaseGeneratorBindings(self: *VM, gen: *Generator) void {
        if (gen.ref_owner == 0) return;
        if (self.ref_index) |ri| ri.releaseOwner(self.allocator, gen.ref_owner);
        self.releaseBoundArgSources(gen.ref_owner);
        gen.ref_owner = 0;
    }

    fn saveGeneratorHandlers(self: *VM, gen: *Generator) RuntimeError!void {
        const count = self.handler_count - self.handler_floor;
        gen.saved_handlers.clearRetainingCapacity();
        try gen.saved_handlers.ensureTotalCapacity(self.allocator, count);
        gen.handler_count = count;
        for (0..count) |i| {
            const h = self.exception_handlers[self.handler_floor + i];
            gen.saved_handlers.appendAssumeCapacity(.{
                .catch_ip = h.catch_ip,
                .sp_offset = h.sp -| gen.base_sp,
                .chunk = h.chunk,
            });
        }
        self.handler_count = self.handler_floor;
    }

    fn restoreGeneratorHandlers(self: *VM, gen: *Generator) RuntimeError!void {
        try self.ensureHandlerRoom(gen.handler_count);
        for (0..gen.handler_count) |i| {
            const h = gen.saved_handlers.items[i];
            self.exception_handlers[self.handler_count] = .{
                .catch_ip = h.catch_ip,
                .frame_count = self.frame_count,
                .sp = gen.base_sp + h.sp_offset,
                .chunk = h.chunk,
                .silenced_depth = self.error_silenced_depth,
            };
            self.handler_count += 1;
        }
    }

    fn callClosureLocalsOnly(self: *VM, func: *const ObjFunction, name: []const u8, arg_count: u32) RuntimeError!void {
        const ac: usize = arg_count;
        const lc: usize = func.local_count;

        // look this closure's captures up by name once (a contiguous range +
        // a has_refs flag) instead of scanning the whole global captures list
        // twice per call - self.captures accumulates across every closure the
        // program ever made, so the old O(total_captures) scans were the
        // dominant warm-Laravel frame (closure-heavy pipeline/middleware)
        const cap_range = self.getCaptureRange(name);

        // by-ref captures can't use the locals-only fast path (fastLoop's
        // set_local doesn't update ref_slots) - fall to the slow vars+refs path
        if (cap_range != null and cap_range.?.has_refs) {
            {
                // fall through to non-locals path via callNamedFunction's slow path
                var new_vars = self.acquireFrameVars();
                var closure_refs: std.StringHashMapUnmanaged(*Value) = .{};
                try self.bindClosures(&new_vars, &closure_refs, name);
                const bind_count = @min(ac, func.arity);
                for (0..bind_count) |i| {
                    try new_vars.put(self.allocator, func.params[i], try self.bindFrameArg(self.stack[self.sp - ac + i]));
                }
                self.saveFrameArgs(arg_count);
                self.dropN(ac);
                try self.fillDefaults(&new_vars, func, bind_count);
                const inherit_cc = self.closureScopeByName(name) orelse self.callerCalledClass();
                try self.ensureCallRoom();
                self.frames[self.frame_count] = .{ .chunk = &func.chunk, .ip = 0, .vars = new_vars, .locals = try self.allocLocals(func, &new_vars), .func = func, .ref_slots = closure_refs, .called_class = inherit_cc, .call_name = name };
                self.frames[self.frame_count].entry_sp = self.sp;
                self.setFrameArgCount(arg_count);
                self.frame_count += 1;
                self.retainFrameObjects(self.frame_count - 1);
                if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;
                return;
            }
        }

        const ic = self.ic.?;
        const base = ic.locals_sp;

        const locals = if (base + lc <= ic.locals_cap) blk: {
            const s = ic.locals_buf[base .. base + lc];
            @memset(s, .undef);
            ic.locals_sp = base + lc;
            break :blk s;
        } else blk: {
            const s = try self.allocator.alloc(Value, lc);
            @memset(s, .undef);
            break :blk s;
        };

        const bind_count = @min(ac, func.arity);
        for (0..bind_count) |i| {
            locals[i] = try self.bindFrameArg(self.stack[self.sp - ac + i]);
        }
        if (try self.fillDefaultLocals(func, locals, bind_count, 0)) return;
        self.saveFrameArgs(arg_count);
        self.dropN(ac);

        // bind captures directly to locals using slot_names - iterate only
        // this closure's contiguous capture range (no whole-list scan / name cmp)
        if (cap_range) |range| {
            for (self.captures.items[range.start .. range.start + range.len]) |cap| {
                for (func.slot_names, 0..) |sn, si| {
                    if (sn.len == cap.var_name.len and std.mem.eql(u8, sn, cap.var_name)) {
                        locals[si] = try self.copyCapturedValue(cap.value);
                        break;
                    }
                }
            }
        }

        try self.ensureCallRoom();
        self.frames[self.frame_count] = .{ .chunk = &func.chunk, .ip = 0, .vars = .{}, .locals = locals, .func = func, .called_class = self.closureScopeByName(name) orelse self.callerCalledClass(), .call_name = name };
        self.frames[self.frame_count].entry_sp = self.sp;
        // the frame names its closure itself; one left pending would be taken
        // by the next frame executeFunction builds
        self.pending_call_name = null;
        self.pending_called_class = null;
        self.setFrameArgCount(arg_count);
        self.frame_count += 1;
        self.retainFrameObjects(self.frame_count - 1);
        if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;
        try self.fastLoop();
    }

    // a locals-only method: $this in slot 0, the arguments after it, run in
    // the fast loop. the object and arguments are on the stack under the call
    fn enterMethodLocalsOnly(self: *VM, func: *const ObjFunction, obj: *PhpObject, arg_count: u32) RuntimeError!void {
        const ac: usize = arg_count;
        const lc: usize = func.local_count;
        const ic = self.ic.?;
        const lbase = ic.locals_sp;
        const locals = if (lbase + lc <= ic.locals_cap) blk: {
            const s = ic.locals_buf[lbase .. lbase + lc];
            @memset(s, .undef);
            ic.locals_sp = lbase + lc;
            break :blk s;
        } else blk: {
            const s = try self.allocator.alloc(Value, lc);
            @memset(s, .undef);
            break :blk s;
        };
        // a static method reached through an instance has no $this slot
        const first: usize = if (func.is_static) 0 else 1;
        if (!func.is_static) locals[0] = .{ .object = obj };
        for (0..@min(ac, func.arity)) |i| {
            locals[i + first] = try self.bindFrameArg(self.stack[self.sp - ac + i]);
        }
        if (try self.fillDefaultLocals(func, locals, @min(ac, func.arity), first)) return;
        self.saveFrameArgs(arg_count);
        self.dropN(ac + 1);
        try self.ensureCallRoom();
        self.frames[self.frame_count] = .{ .chunk = &func.chunk, .ip = 0, .vars = .{}, .locals = locals, .func = func, .called_class = if (func.is_static) obj.class_name else null };
        self.setFrameArgCount(arg_count);
        self.frames[self.frame_count].entry_sp = self.sp;
        self.frame_count += 1;
        self.retainFrameObjects(self.frame_count - 1);
        if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;
        try self.fastLoop();
    }

    fn callLocalsOnly(self: *VM, func: *const ObjFunction, arg_count: u32) RuntimeError!void {
        const ac: usize = arg_count;
        const lc: usize = func.local_count;
        const ic = self.ic.?;
        const base = ic.locals_sp;

        const locals = if (base + lc <= ic.locals_cap) blk: {
            const s = ic.locals_buf[base .. base + lc];
            @memset(s, .undef);
            ic.locals_sp = base + lc;
            break :blk s;
        } else blk: {
            const s = try self.allocator.alloc(Value, lc);
            @memset(s, .undef);
            break :blk s;
        };

        const bind_count = @min(ac, func.arity);
        for (0..bind_count) |i| {
            locals[i] = try self.bindFrameArg(self.stack[self.sp - ac + i]);
        }
        if (try self.fillDefaultLocals(func, locals, bind_count, 0)) return;
        self.saveFrameArgs(arg_count);
        self.dropN(ac);
        try self.ensureCallRoom();
        self.frames[self.frame_count] = .{ .chunk = &func.chunk, .ip = 0, .vars = .{}, .locals = locals, .func = func, .called_class = self.currentFrame().called_class };
        self.frames[self.frame_count].entry_sp = self.sp;
        self.setFrameArgCount(arg_count);
        self.frame_count += 1;
        self.retainFrameObjects(self.frame_count - 1);
        if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;
        try self.fastLoop();
    }

    // hand the current frame back to the fast loop at a statement end, unless
    // this statement end is known to bail straight back. true when the frame
    // runLoop was driving has returned
    fn resumeFastLoop(self: *VM, base_frame: usize) RuntimeError!bool {
        const ic = self.ic.?;
        const chunk = self.currentChunk();
        const ip = self.currentFrame().ip;
        const site = @intFromPtr(chunk) ^ ip;
        const slot = &ic.fast_stalls[@as(u8, @truncate(site *% 0x9E3779B97F4A7C15 >> 56))];
        if (slot.* == site) return false;
        const fc = self.frame_count;
        try self.fastLoop();
        if (self.frame_count == fc and self.currentFrame().ip == ip and self.currentChunk() == chunk) slot.* = site;
        return self.frame_count <= base_frame;
    }

    // compiled as a separate object (src/runtime/fast_loop.zig) so LLVM
    // optimizes it independently of runLoop
    fn fastLoop(self: *VM) RuntimeError!void {
        const code = zphp_fast_loop(@ptrCast(self));
        self.flushTopWrites();
        return switch (code) {
            0 => {},
            1 => error.RuntimeError,
            2 => error.OutOfMemory,
            else => unreachable,
        };
    }

    fn executeFunctionLocalsOnly(self: *VM, func: *const ObjFunction, args: []const Value) RuntimeError!Value {
        try self.ensureCallRoom();
        const base_frame = self.frame_count;
        const lc: usize = func.local_count;
        const ic = self.ic.?;
        const lbase = ic.locals_sp;

        const locals = if (lbase + lc <= ic.locals_cap) blk: {
            const s = ic.locals_buf[lbase .. lbase + lc];
            @memset(s, .undef);
            ic.locals_sp = lbase + lc;
            break :blk s;
        } else blk: {
            const s = try self.allocator.alloc(Value, lc);
            @memset(s, .undef);
            break :blk s;
        };

        const bind_count = @min(args.len, func.arity);
        for (0..bind_count) |i| {
            locals[i] = try self.bindFrameArg(args[i]);
        }
        try self.fillDefaultLocalsForCaller(func, locals, bind_count, 0);
        const base_handler = self.handler_count;
        const prev_floor = self.handler_floor;
        self.handler_floor = self.handler_count;
        try self.ensureCallRoom();
        self.frames[self.frame_count] = .{ .chunk = &func.chunk, .ip = 0, .vars = .{}, .locals = locals, .func = func, .call_name = self.pending_call_name, .called_class = self.pending_called_class };
        self.frames[self.frame_count].entry_sp = self.sp;
        self.consumePendingArgCount();
        self.saveFrameArgsSlice(args);
        self.pending_call_name = null;
        self.pending_called_class = null;
        self.frame_count += 1;
        self.retainFrameObjects(self.frame_count - 1);
        if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;
        self.runUntilFrame(base_frame) catch |err| {
            self.handler_count = base_handler;
            self.handler_floor = prev_floor;
            self.unwindFailedCall(base_frame);
            return err;
        };
        self.handler_count = base_handler;
        self.handler_floor = prev_floor;
        return self.pop();
    }

    pub fn acquireFrameVars(self: *VM) std.StringHashMapUnmanaged(Value) {
        if (self.vars_pool.pop()) |hm| return hm;
        return .{};
    }

    // is the local slot bound to a reference cell? a ref-bound slot writes
    // through a shared cell, so overwrite-release must not run on it
    fn slotIsRefBound(self: *VM, frame: *CallFrame, slot: u16) bool {
        if (frame.ref_slots.count() == 0) return false;
        const snames = if (frame.func) |f| f.slot_names else self.global_slot_names;
        if (slot >= snames.len or snames[slot].len == 0) return false;
        return frame.ref_slots.contains(snames[slot]);
    }

    // release every object reference a frame holds (Stage 1), INCLUDING $this
    // and parameters. under the move model the call site transfers the
    // operand-stack retain of the receiver/args into the callee bindings, and
    // this teardown release is what consumes them. when `vars` is populated it
    // is the authoritative store and the named `locals` slots merely mirror it
    // (release via vars, skip the mirror to avoid a double-release). when
    // `vars` is empty (locals_only fast frames) `locals` is the sole storage,
    // so release named slots from there. unnamed local slots (compiler
    // temporaries) are released from `locals` either way
    // a named local and its vars entry share one reference: frames created
    // on the slow path copy vars into locals, and a slow-path set_local on a
    // locals-only frame mirrors just that slot into vars. release each name
    // once, through whichever side holds it
    fn releaseFrameObjects(self: *VM, idx: usize) void {
        const frame = &self.frames[idx];
        if (frame.call_name) |name| self.releaseClosureByName(name);
        const snames = if (frame.func) |f| f.slot_names else frame.slot_names;
        const vars_populated = frame.vars.count() > 0;
        if (vars_populated) {
            var it = frame.vars.iterator();
            while (it.next()) |entry| {
                self.releaseValue(entry.value_ptr.*);
                if (self.debug_gc_verify) self.gcRecordFrameRelease(frame, entry.key_ptr.*, entry.value_ptr.*);
            }
        }
        for (frame.locals, 0..) |lv, i| {
            if (vars_populated and i < snames.len and snames[i].len > 0 and frame.vars.contains(snames[i])) continue;
            self.releaseValue(lv);
            if (self.debug_gc_verify) self.gcRecordFrameRelease(frame, if (i < snames.len) snames[i] else "<unnamed slot>", lv);
        }
    }

    fn gcRecordFrameRelease(self: *VM, frame: *const CallFrame, name: []const u8, v: Value) void {
        if (v != .array or v.array.refcount != 0) return;
        if (self.gc_zero_sites.getPtr(v.array)) |site| {
            site.binding = name;
            site.binding_func = if (frame.func) |f| f.name else frame.script_path;
        }
    }

    // EXACT mirror of releaseFrameObjects (Stage 1). called once per frame
    // right after the frame is pushed and populated. every object a frame
    // holds - $this, parameters, closure captures, seeded locals - is bound
    // RAW at the call sites (no per-site refcount logic); this one pass
    // retains them all, and releaseFrameObjects at teardown releases them all.
    // the two are the only frame-refcount choke points - making the bind
    // sites refcount-free is what eliminates the over-release hole class.
    // generator frames are skipped (their vars are owned by the Generator,
    // and deinitFrameSlot likewise skips releaseFrameObjects for them).
    // a generator owns its vars (they outlive each resume; retainFrameObjects
    // skips generator frames) - so the generator itself holds those object
    // references. retain them when the generator is created; the end-of-
    // request shutdown sweep destructs whatever is still live (Stage 1)
    fn retainVarsObjects(vars: *std.StringHashMapUnmanaged(Value)) void {
        var it = vars.valueIterator();
        while (it.next()) |v| retainValue(v.*);
    }

    pub fn retainFrameObjects(self: *VM, idx: usize) void {
        const frame = &self.frames[idx];
        if (frame.generator != null) return;
        if (frame.call_name) |name| self.retainClosureByName(name);
        self.markOwnedArrayArgs(idx, frame) catch {};
        const snames = if (frame.func) |f| f.slot_names else frame.slot_names;
        const vars_populated = frame.vars.count() > 0;
        if (vars_populated) {
            var it = frame.vars.iterator();
            while (it.next()) |entry| {
                var owned = false;
                if (entry.value_ptr.* == .array) if (frame.func) |func| {
                    for (func.params, 0..) |param, i| {
                        if (std.mem.eql(u8, entry.key_ptr.*, param)) {
                            owned = (frame.owned_array_args[i / 64] & (@as(u64, 1) << @intCast(i % 64))) != 0;
                            break;
                        }
                    }
                };
                if (!owned) retainValue(entry.value_ptr.*);
            }
        }
        for (frame.locals, 0..) |lv, i| {
            if (vars_populated and i < snames.len and snames[i].len > 0) continue;
            retainValue(lv);
        }
    }

    // a frame's named view starts empty; the first by-name write takes a map
    // from the pool so frames that release theirs there keep it balanced
    pub fn putFrameVar(self: *VM, vars: *std.StringHashMapUnmanaged(Value), name: []const u8, val: Value) !void {
        if (vars.capacity() == 0) {
            if (self.vars_pool.pop()) |pooled| vars.* = pooled;
        }
        try vars.put(self.allocator, name, val);
    }

    // put that hands back the entry it replaced, taking a pooled map as
    // putFrameVar does
    fn fetchPutFrameVar(self: *VM, vars: *std.StringHashMapUnmanaged(Value), name: []const u8, val: Value) !?std.StringHashMapUnmanaged(Value).KV {
        if (vars.capacity() == 0) {
            if (self.vars_pool.pop()) |pooled| vars.* = pooled;
        }
        return vars.fetchPut(self.allocator, name, val);
    }

    pub fn releaseFrameVars(self: *VM, hm: *std.StringHashMapUnmanaged(Value)) void {
        if (hm.capacity() == 0) return;
        // cap the pool: hashmaps that grew very large should be freed rather
        // than held forever. typical frame.vars has 1-5 entries; anything
        // beyond a moderate cap is likely a `extract()` or `compact()` user
        // and not worth retaining
        if (hm.capacity() > 256 or self.vars_pool.items.len >= 64) {
            hm.deinit(self.allocator);
            return;
        }
        hm.clearRetainingCapacity();
        self.vars_pool.append(self.allocator, hm.*) catch {
            hm.deinit(self.allocator);
            return;
        };
    }

    fn allocLocals(self: *VM, func: *const ObjFunction, vars: *const std.StringHashMapUnmanaged(Value)) ![]Value {
        if (func.local_count == 0) return &.{};
        // fast path: pull from the IC's pre-allocated locals stack. mmap/munmap
        // for every function call dominates the profile under recursive-call
        // workloads (deep method-call delegation chains); the IC pool
        // turns it into a pointer bump. freeLocals already recognizes pool
        // slices and pops the sp without freeing.
        // generators/fibers suspend with the locals pointer captured; the
        // pool's LIFO discipline doesn't survive a suspension, so those
        // routes must allocate on the heap
        const lc = func.local_count;
        var locals: []Value = undefined;
        if (self.ic != null and !func.is_generator) {
            const ic = self.ic.?;
            const base = ic.locals_sp;
            if (base + lc <= ic.locals_cap) {
                locals = ic.locals_buf[base .. base + lc];
                ic.locals_sp = base + lc;
            } else {
                locals = try self.allocator.alloc(Value, lc);
            }
        } else {
            locals = try self.allocator.alloc(Value, lc);
        }
        @memset(locals, .undef);
        for (func.slot_names, 0..) |name, i| {
            if (name.len > 0) {
                if (vars.get(name)) |val| {
                    locals[i] = val;
                }
            }
        }
        return locals;
    }

    fn unsetIncludeVar(self: *VM, frame_idx: usize, name: []const u8) void {
        const frame = &self.frames[frame_idx];
        const had_var = frame.vars.contains(name);
        if (frame.vars.get(name)) |existing| self.releaseValue(existing);
        _ = frame.vars.remove(name);
        if (frame.ref_slots.get(name)) |cell| {
            self.unbindRefSlot(&frame.ref_slots, name);
            self.revertUncapturedCell(cell);
        }
        const slot_names = if (frame.func) |func| func.slot_names else frame.slot_names;
        for (slot_names, 0..) |slot_name, slot| {
            if (std.mem.eql(u8, slot_name, name) and slot < frame.locals.len) {
                if (!had_var) self.releaseValue(frame.locals[slot]);
                frame.locals[slot] = .null;
                break;
            }
        }
        if (frame.include_parent) |parent_idx| self.unsetIncludeVar(parent_idx, name);
    }

    fn syncIncludeLocal(self: *VM, frame: *CallFrame, slot: u16, value: Value) RuntimeError!void {
        if (slot >= frame.slot_names.len) return;
        try self.syncIncludeVar(frame, frame.slot_names[slot], value);
    }

    fn syncIncludeVar(self: *VM, frame: *CallFrame, name: []const u8, value: Value) RuntimeError!void {
        const parent_idx = frame.include_parent orelse return;
        if (name.len == 0) return;
        const parent = &self.frames[parent_idx];
        if (parent.ref_slots.get(name)) |cell| {
            self.setCell(cell, value);
            try self.propagateCellWrite(cell, value);
        }
        const parent_sn = if (parent.func) |func| func.slot_names else parent.slot_names;
        var matching_slot: ?usize = null;
        for (parent_sn, 0..) |parent_name, parent_slot| {
            if (std.mem.eql(u8, parent_name, name) and parent_slot < parent.locals.len) {
                matching_slot = parent_slot;
                break;
            }
        }
        const vars_owned_values = parent.vars.count() > 0;
        retainValue(value);
        if (try parent.vars.fetchPut(self.allocator, name, value)) |old| {
            self.releaseValue(old.value);
        } else if (!vars_owned_values) {
            if (matching_slot) |parent_slot| self.releaseValue(parent.locals[parent_slot]);
        }
        if (matching_slot) |parent_slot| parent.locals[parent_slot] = value;
        if (parent.include_parent != null) try self.syncIncludeVar(parent, name, value);
    }

    fn mergeIncludeScope(self: *VM, include_frame_idx: usize, caller_idx: usize, include_slot_names: []const []const u8) RuntimeError!void {
        const include_frame = &self.frames[include_frame_idx];
        const caller = &self.frames[caller_idx];
        const caller_sn = if (caller.func) |func| func.slot_names else caller.slot_names;
        for (include_slot_names, 0..) |name, si| {
            if (name.len == 0 or si >= include_frame.locals.len) continue;
            const include_cell = include_frame.ref_slots.get(name);
            const stored = include_frame.vars.get(name);
            if (include_cell == null and stored == null) {
                if (caller.ref_slots.get(name)) |cell| {
                    self.unbindRefSlot(&caller.ref_slots, name);
                    self.revertUncapturedCell(cell);
                }
                // a slot and its vars entry are one owning binding: release once
                const removed = caller.vars.fetchRemove(name);
                for (caller_sn, 0..) |caller_name, ci| {
                    if (std.mem.eql(u8, caller_name, name) and ci < caller.locals.len) {
                        if (removed == null) self.releaseValue(caller.locals[ci]);
                        caller.locals[ci] = .null;
                        break;
                    }
                }
                if (removed) |old| self.releaseValue(old.value);
                continue;
            }

            const value = if (include_cell) |cell| cell.* else stored.?;
            if (include_cell) |cell| {
                try self.bindRefSlot(&caller.ref_slots, name, cell);
                if (include_frame.ref_owner != 0) {
                    const owner = try self.ensureRefOwner(caller);
                    try (try self.refIndex()).transferCell(self.allocator, include_frame.ref_owner, owner, cell);
                }
            } else if (caller.ref_slots.get(name)) |cell| {
                self.setCell(cell, value);
                try self.propagateCellWrite(cell, value);
            }

            var caller_slot: ?usize = null;
            for (caller_sn, 0..) |caller_name, ci| {
                if (std.mem.eql(u8, caller_name, name)) {
                    caller_slot = ci;
                    break;
                }
            }
            retainValue(value);
            const old_var = try caller.vars.fetchPut(self.allocator, name, value);
            if (caller_slot) |ci| {
                if (ci < caller.locals.len) {
                    if (old_var == null) self.releaseValue(caller.locals[ci]);
                    caller.locals[ci] = value;
                }
            }
            if (old_var) |old| self.releaseValue(old.value);
        }

        var iter_vars = include_frame.vars.iterator();
        while (iter_vars.next()) |entry| {
            const name = entry.key_ptr.*;
            if (name.len == 0) continue;
            var is_slot_backed = false;
            for (include_slot_names) |slot_name| {
                if (std.mem.eql(u8, slot_name, name)) {
                    is_slot_backed = true;
                    break;
                }
            }
            if (is_slot_backed) continue;
            const value = if (include_frame.ref_slots.get(name)) |cell| cell.* else entry.value_ptr.*;
            if (include_frame.ref_slots.get(name)) |cell| {
                try self.bindRefSlot(&caller.ref_slots, name, cell);
                if (include_frame.ref_owner != 0) {
                    const owner = try self.ensureRefOwner(caller);
                    try (try self.refIndex()).transferCell(self.allocator, include_frame.ref_owner, owner, cell);
                }
            } else if (caller.ref_slots.get(name)) |cell| {
                self.setCell(cell, value);
                try self.propagateCellWrite(cell, value);
            }
            retainValue(value);
            const replaced = try caller.vars.fetchPut(self.allocator, name, value);
            if (replaced) |old| self.releaseValue(old.value);
            for (caller_sn, 0..) |slot_name, i| {
                if (std.mem.eql(u8, slot_name, name) and i < caller.locals.len) {
                    if (replaced == null) self.releaseValue(caller.locals[i]);
                    caller.locals[i] = value;
                    break;
                }
            }
        }
    }

    fn popFrame(self: *VM) !void {
        try self.writebackStatics();
        try self.writebackRefs();
        self.frame_count -= 1;
        self.restoreFrameArgsSp();
        // prune exception handlers that belonged to the popped frame
        while (self.handler_count > self.handler_floor and
            self.exception_handlers[self.handler_count - 1].frame_count > self.frame_count)
        {
            self.handler_count -= 1;
        }
        // if this pop returns to the require-merge depth, leave the slot
        // intact so the require handler can read its vars/locals before
        // doing its own deinit. otherwise PHP's "include leaks top-level
        // vars even after explicit return" semantics is silently dropped
        if (self.require_merge_depth != 0 and self.frame_count + 1 == self.require_merge_depth) {
            return;
        }
        self.deinitFrameSlot(self.frame_count);
    }

    pub fn deinitFrameSlot(self: *VM, idx: usize) void {
        if (self.held_exceptions.items.len > 0) self.releaseHeldAt(idx, 0);
        self.forgetFrameArgs(idx);
        const frame_generator = self.frames[idx].generator;
        self.deinitRefSlots(&self.frames[idx].ref_slots);
        self.unregFrameBindings(&self.frames[idx]);
        // when the frame belongs to a generator, its vars hashmap is owned by
        // the Generator and will be freed during freeHeapItems. freeing it
        // here too causes a double-free during VM cleanup
        if (self.frames[idx].generator == null) {
            // release the frame's object references before the var storage is
            // pooled/freed - this is what makes function-scope objects and
            // constructor objects fire __destruct at frame exit (Stage 1)
            self.releaseFrameObjects(idx);
            self.releaseFrameVars(&self.frames[idx].vars);
        }
        // the frame may have grown the generator's vars map: the generator
        // keeps the one in use
        if (frame_generator) |gen| gen.vars = self.frames[idx].vars;
        if (self.frames[idx].locals.len > 0) {
            if (frame_generator) |gen| {
                gen.locals.clearRetainingCapacity();
                gen.locals.appendSlice(self.allocator, self.frames[idx].locals) catch {};
            }
            self.freeLocals(self.frames[idx].locals);
            self.frames[idx].locals = &.{};
        }
        self.frames[idx].ref_slots = .{};
        self.frames[idx].vars = .{};
        self.frames[idx].generator = null;
        if (frame_generator) |gen| self.genRelease(gen);
    }

    pub fn freeLocals(self: *VM, locals: []Value) void {
        if (self.ic) |ic| {
            const lptr = @intFromPtr(locals.ptr);
            const sptr = @intFromPtr(ic.locals_buf);
            if (lptr >= sptr and lptr < sptr + ic.locals_cap * @sizeOf(Value)) {
                ic.locals_sp -= locals.len;
                return;
            }
        }
        self.allocator.free(locals);
    }

    fn cleanupFiberFrames(self: *VM, fiber: *Fiber) void {
        for (fiber.saved_frames.items) |*f| {
            // Stage 2 finer fiber lifetime: release every value the saved
            // frame holds before freeing the metadata. mirrors
            // releaseFrameObjects but operates on Fiber.SavedFrame (which
            // shares the same shape as CallFrame for vars/locals/slot_names)
            const snames = if (f.func) |fn_| fn_.slot_names else &[_][]const u8{};
            if (f.generator == null) if (f.call_name) |name| self.releaseClosureByName(name);
            const vars_populated = f.vars.count() > 0;
            if (vars_populated) {
                var vit = f.vars.valueIterator();
                while (vit.next()) |v| self.releaseValue(v.*);
            }
            for (f.locals, 0..) |lv, i| {
                if (vars_populated and i < snames.len and snames[i].len > 0 and f.vars.contains(snames[i])) continue;
                self.releaseValue(lv);
            }
            f.vars.deinit(self.allocator);
            self.deinitRefSlots(&f.ref_slots);
            self.unregFrameBindings(f);
            if (f.locals.len > 0) self.freeLocals(f.locals);
        }
        fiber.saved_frames.clearRetainingCapacity();
        if (self.hasPendingReleases()) self.drainPendingDestruct();
    }

    // the reverse of propagateCellWrite for object/static props: when $obj->prop
    // (or Class::$static) is written DIRECTLY - not through a reference - update
    // any ref cell that a `$r = &$obj->prop` bound to it, so $r observes the new
    // value. PHP keeps the prop and the reference as one storage; zphp keeps two
    // views (the prop slot + the cell) and syncs them in both directions
    fn syncObjPropRefs(self: *VM, obj: *PhpObject, prop_name: []const u8, val: Value) void {
        if (!self.obj_ref_active) return;
        const ri = self.ref_index orelse return;
        const cells = ri.prop_rev.get(.{ .object = obj, .class_name = "", .prop_name = prop_name }) orelse return;
        for (cells.items) |cell| {
            self.setCell(cell, val);
            self.propagateCellWrite(cell, val) catch {};
        }
    }

    // a static property write: the declared type, then any typed
    // properties sharing a reference with it. the value on top of the stack
    // is checked and replaced by its coerced form. true when the TypeError
    // was caught
    fn checkStaticPropWrite(self: *VM, cls: *ClassDef, class_name: []const u8, prop_name: []const u8) RuntimeError!bool {
        const top = &self.stack[self.sp - 1];
        var val = top.*;
        if (cls.static_prop_types.get(prop_name)) |t| if (t.len > 0) {
            const decl = self.staticPropDeclaringClass(class_name, prop_name) orelse class_name;
            if (try self.checkPropertyType(&val, t, decl, prop_name)) return true;
        };
        if (self.obj_ref_active) val = try self.checkTypedStaticPropWrite(class_name, prop_name, val);
        if (@intFromEnum(val) != @intFromEnum(top.*) or !Value.identical(val, top.*)) self.replaceOwned(top, val);
        return false;
    }

    // `$o->p = &...` (zend_assign_to_property_reference): a typed property
    // checks the referenced value first, then the property leaves any
    // reference it held and joins the cell. the cell's bindings the running
    // frame made to reach its source outlive the frame now that a property
    // holds the reference
    fn bindPropToCell(self: *VM, obj: *PhpObject, prop_name: []const u8, cell: *Value) RuntimeError!void {
        const vr = self.findPropertyVisibility(obj.class_name, prop_name);
        if (vr.declared and vr.type_str.len > 0) try self.verifyPropAssignableByRef(vr, prop_name, cell);
        self.detachPropRefs(obj, prop_name, cell);
        const scope: ?[]const u8 = if (vr.declared) vr.defining_class else null;
        const old = obj.getForScope(prop_name, scope);
        obj.clearUnset(self.allocator, prop_name);
        try obj.setForScope(self.allocator, prop_name, cell.*, scope);
        self.releaseValue(old);
        const ri = try self.refIndex();
        const persistent = try self.persistentRefOwner();
        const frame = self.currentFrame();
        if (frame.ref_owner != 0) try ri.transferCell(self.allocator, frame.ref_owner, persistent, cell);
        try self.regRefObject(persistent, cell, obj, prop_name);
        self.obj_ref_active = true;
    }

    // the reference cell a property shares, made for it (holding its value)
    // when it shares none: unserialize's R: turning a property into a
    // reference. scope is the declaring class of a private property
    pub fn propertyReferenceCell(self: *VM, obj: *PhpObject, name: []const u8, scope: ?[]const u8) RuntimeError!*Value {
        const index = try self.refIndex();
        if (index.prop_rev.get(.{ .object = obj, .class_name = "", .prop_name = name })) |cells| {
            if (cells.items.len > 0) return cells.items[0];
        }
        const fresh = try self.newRefCell();
        self.setCell(fresh, obj.getForScope(name, scope));
        try self.regRefObject(try self.persistentRefOwner(), fresh, obj, name);
        self.obj_ref_active = true;
        return fresh;
    }

    // a property joining a reference set, as `$o->p = &$r` makes it
    pub fn bindPropertyToCell(self: *VM, obj: *PhpObject, name: []const u8, cell: *Value) RuntimeError!void {
        return self.bindPropToCell(obj, name, cell);
    }

    // whether a typed property takes val without coercion, as unserialize
    // checks it (zend_verify_prop_assignable_by_ref, strict)
    pub fn unserializedPropertyFits(self: *VM, val: Value, type_str: []const u8, decl_class: []const u8) RuntimeError!bool {
        return (try self.verifyDeclaredType(val, type_str, decl_class, true)) != null;
    }

    // a fresh reference cell holding val
    pub fn newReferenceCell(self: *VM, val: Value) RuntimeError!*Value {
        const cell = try self.newRefCell();
        self.setCell(cell, val);
        return cell;
    }

    // `C::$p = &...`: the static property leaves the reference it held and
    // joins the cell, checked against its type as a property is
    fn bindStaticPropToCell(self: *VM, class_name: []const u8, prop_name: []const u8, cell: *Value) RuntimeError!void {
        const decl = self.staticPropDeclaringClass(class_name, prop_name) orelse class_name;
        if (self.classes.getPtr(decl)) |cls| if (cls.static_prop_types.get(prop_name)) |t| if (t.len > 0) {
            try self.verifyPropAssignableByRef(.{ .visibility = .public, .defining_class = decl, .type_str = t }, prop_name, cell);
        };
        const ri = try self.refIndex();
        while (ri.prop_rev.get(.{ .object = null, .class_name = class_name, .prop_name = prop_name })) |cells| {
            var victim: ?*Value = null;
            for (cells.items) |c| if (c != cell) {
                victim = c;
                break;
            };
            ri.removeTargetAllOwners(self.allocator, victim orelse break, .{ .static = .{ .class_name = class_name, .prop_name = prop_name } });
        }
        if (self.getStaticPropPtr(class_name, prop_name)) |slot| {
            retainValue(cell.*);
            self.releaseValue(slot.*);
            slot.* = cell.*;
        }
        const persistent = try self.persistentRefOwner();
        const frame = self.currentFrame();
        if (frame.ref_owner != 0) try ri.transferCell(self.allocator, frame.ref_owner, persistent, cell);
        try self.regRefStatic(persistent, cell, class_name, prop_name);
        self.obj_ref_active = true;
    }

    // the property stops sharing whatever reference it held before
    fn detachPropRefs(self: *VM, obj: *PhpObject, prop_name: []const u8, keep: ?*Value) void {
        const ri = self.ref_index orelse return;
        while (true) {
            const cells = ri.prop_rev.get(.{ .object = obj, .class_name = "", .prop_name = prop_name }) orelse return;
            var victim: ?*Value = null;
            for (cells.items) |c| if (c != keep) {
                victim = c;
                break;
            };
            const c = victim orelse return;
            ri.removeTargetAllOwners(self.allocator, c, .{ .object = .{ .object = obj, .prop_name = prop_name } });
        }
    }

    // zend_verify_prop_assignable_by_ref: a reference other typed properties
    // hold must already fit, since coercing it would change their value; a
    // plain one is coerced in place
    fn verifyPropAssignableByRef(self: *VM, vr_in: VisResult, prop_name: []const u8, cell: *Value) RuntimeError!void {
        var vr = vr_in;
        vr.type_str = try self.propertyTypeText(vr.type_str, vr.defining_class);
        const strict = self.currentStrictTypes();
        const val = cell.*;
        var buf: [8]TypeSource = undefined;
        const sources = self.refTypeSources(cell, &buf);
        if (sources.len > 0) {
            const result = self.typeAssignable(val, vr.type_str, vr.defining_class, strict);
            if (result > 0) return;
            if (result < 0) {
                if (try self.weakScalarHint(php_types.shape(vr.type_str).mask, val) != null) {
                    const first = sources[0];
                    const msg = try std.fmt.allocPrint(self.allocator, "Reference with value of type {s} held by property {s}::${s} of type {s} is not compatible with property {s}::${s} of type {s}", .{ Value.typeName(val), first.class, first.prop, try self.propertyTypeText(first.type_str, first.class), vr.defining_class, prop_name, vr.type_str });
                    defer self.allocator.free(msg);
                    try self.setPendingException("TypeError", msg);
                    return error.RuntimeError;
                }
            }
        } else if (try self.propertyTypeAccepts(val, vr.type_str, vr.defining_class, strict)) |coerced| {
            if (@intFromEnum(coerced) != @intFromEnum(val) or !Value.identical(coerced, val)) {
                self.setCell(cell, coerced);
                try self.propagateCellWrite(cell, coerced);
            }
            return;
        }
        const msg = try std.fmt.allocPrint(self.allocator, "Cannot assign {s} to property {s}::${s} of type {s}", .{ valueTypeName(val), vr.defining_class, prop_name, vr.type_str });
        defer self.allocator.free(msg);
        try self.setPendingException("TypeError", msg);
        return error.RuntimeError;
    }

    // a reference to an uninitialized typed property makes it null when its
    // type takes null, and is an Error otherwise
    // (zend_handle_fetch_obj_flags / zend_throw_access_uninit_prop_by_ref_error)
    fn initializeForReference(self: *VM, obj: *PhpObject, prop_name: []const u8) RuntimeError!void {
        if (obj.rawForScope(prop_name, null) != .undef) return;
        const decl = self.propertyDeclaration(obj.class_name, prop_name);
        if (php_types.shape(decl.type_str).mask & php_types.NULL != 0) return obj.set(self.allocator, prop_name, .null);
        const msg = try std.fmt.allocPrint(self.allocator, "Cannot access uninitialized non-nullable property {s}::${s} by reference", .{ decl.defining_class, prop_name });
        defer self.allocator.free(msg);
        try self.setPendingException("Error", msg);
        return error.RuntimeError;
    }

    // what __get returns for a typed property that was unset must fit the
    // property's type, coerced as __get's file allows
    // (zend_verify_prop_assignable_by_ref_ex in the magic get context)
    fn checkMagicGetResult(self: *VM, obj: *PhpObject, vr: VisResult, prop_name: []const u8, result: Value) RuntimeError!Value {
        const strict = blk: {
            const key = self.resolveMethod(obj.class_name, "__get") catch break :blk false;
            break :blk if (self.functions.get(key)) |f| f.strict_types else false;
        };
        if (try self.propertyTypeAccepts(result, vr.type_str, vr.defining_class, strict)) |accepted| return accepted;
        const msg = try std.fmt.allocPrint(self.allocator, "Value of type {s} returned from {s}::__get() must be compatible with unset property {s}::${s} of type {s}", .{ Value.typeName(result), vr.defining_class, vr.defining_class, prop_name, try self.propertyTypeText(vr.type_str, vr.defining_class) });
        defer self.allocator.free(msg);
        self.releaseValue(result);
        try self.setPendingException("TypeError", msg);
        return error.RuntimeError;
    }

    // a property holding a reference that typed properties are bound to
    // takes only what each of them accepts (zend_assign_to_typed_ref)
    fn checkTypedPropWrite(self: *VM, obj: *PhpObject, prop_name: []const u8, val: Value) RuntimeError!Value {
        const ri = self.ref_index orelse return val;
        const cells = ri.prop_rev.get(.{ .object = obj, .class_name = "", .prop_name = prop_name }) orelse return val;
        var v = val;
        for (cells.items) |cell| {
            if (cellOf(cell).typed) v = try self.verifyRefAssignable(cell, v);
        }
        return v;
    }

    // zend_pre_incdec_property_zval: a property holding a typed reference
    // steps the reference, so an int stepped past its range is the
    // reference's error rather than the property's
    fn checkTypedPropStep(self: *VM, obj: *PhpObject, prop_name: []const u8, val: Value) RuntimeError!Value {
        const ri = self.ref_index orelse return val;
        const cells = ri.prop_rev.get(.{ .object = obj, .class_name = "", .prop_name = prop_name }) orelse return val;
        for (cells.items) |cell| {
            if (!cellOf(cell).typed) continue;
            const ic = self.ic orelse return val;
            if (ic.step_overflow.up == null) return val;
            return self.verifyRefAssignable(cell, val);
        }
        return val;
    }

    fn checkTypedStaticPropWrite(self: *VM, class_name: []const u8, prop_name: []const u8, val: Value) RuntimeError!Value {
        const ri = self.ref_index orelse return val;
        const cells = ri.prop_rev.get(.{ .object = null, .class_name = class_name, .prop_name = prop_name }) orelse return val;
        var v = val;
        for (cells.items) |cell| {
            if (cellOf(cell).typed) v = try self.verifyRefAssignable(cell, v);
        }
        return v;
    }

    fn syncStaticPropRefs(self: *VM, class_name: []const u8, prop_name: []const u8, val: Value) void {
        if (!self.obj_ref_active) return;
        const ri = self.ref_index orelse return;
        const cells = ri.prop_rev.get(.{ .object = null, .class_name = class_name, .prop_name = prop_name }) orelse return;
        for (cells.items) |cell| {
            self.setCell(cell, val);
            self.propagateCellWrite(cell, val) catch {};
        }
    }

    // get the ref cell for $var, making $var a reference if it isn't one yet
    // (seed the cell from $var's current value, sharing any array pointer). the
    // source-of-truth for `$arr[$k] = &$var` and `$arr[] = &$var`
    fn getOrCreateVarCell(self: *VM, frame: *CallFrame, var_name: []const u8) RuntimeError!*Value {
        if (isSuperglobal(var_name)) return self.superglobalCell(var_name);
        if (frame.ref_slots.get(var_name)) |existing| return existing;
        const cell = try self.newRefCell();
        var seed: Value = .null;
        const sn = if (frame.func) |fn_| fn_.slot_names else self.global_slot_names;
        var found_slot = false;
        for (sn, 0..) |s, si| {
            if (std.mem.eql(u8, s, var_name) and si < frame.locals.len) {
                // a reference to a variable that holds nothing creates it as null
                if (frame.locals[si] == .undef) {
                    frame.locals[si] = frame.vars.get(var_name) orelse .null;
                }
                seed = frame.locals[si];
                found_slot = true;
                break;
            }
        }
        if (!found_slot) {
            if (frame.vars.get(var_name)) |v| seed = v;
        }
        self.setCell(cell, seed);

        try self.bindRefSlot(&frame.ref_slots, var_name, cell);
        return cell;
    }

    // a DIRECT write `$arr[$k] = X` to an element that is a php reference must
    // go through the shared cell (so every other name for that storage - the
    // bound $v, clone-shared entries - observes X), not clobber entry.value in
    // isolation. returns true if the element was a reference and the write was
    // routed; the caller then skips its own set + overwrite-release (the
    // propagate below does the retaining store + releases the old value)
    fn writeArrayElemRef(self: *VM, arr: *PhpArray, key: PhpArray.Key, val: Value) !bool {
        if (!self.array_ref_active) return false;
        const ep = arr.getPtr(key) orelse return false;
        const cell = ep.ref orelse return false;
        // the element is the last holder, so the reference is just its value
        if (cellOf(cell).binders == 1) {
            ep.ref = null;
            self.unbindCell(cell);
            return false;
        }
        const stored = if (cellOf(cell).typed) try self.verifyRefAssignable(cell, val) else val;
        self.setCell(cell, stored);
        try self.propagateCellWrite(cell, stored);
        return true;
    }

    // a reference cell owns the value it holds: every write retains the new
    // value and releases the previous one. mirrors (variable slots, array
    // elements, properties, captures) own their own references independently
    // a write through a reference from native code: the cell and every
    // storage that mirrors it
    pub fn writeReference(self: *VM, cell: *Value, val: Value) RuntimeError!void {
        self.setCell(cell, val);
        self.propagateCellWrite(cell, val) catch return error.RuntimeError;
    }

    pub fn setCell(self: *VM, cell: *Value, val: Value) void {
        // Native request consumers share the canonical binding too. The map
        // remains an owning mirror, including when the value is replaced.
        for (superglobal_names) |name| {
            if (self.globals_cells.get(name) == cell) {
                if (self.globals_array) |ga| {
                    if (ga.getPtr(.{ .string = Value.String.borrowed(name[1..]) })) |entry| entry.value = val;
                }
                if (self.request_vars.getPtr(name)) |vp| {
                    retainValue(val);
                    self.releaseValue(vp.*);
                    vp.* = val;
                }
            }
        }
        retainValue(val);
        self.releaseValue(cell.*);
        cell.* = val;
    }

    fn propagateCellWrite(self: *VM, cell: *Value, val: Value) !void {
        // O(1): the cell-keyed registry holds exactly this cell's mirror targets
        // (kept in lock-step with the legacy lists by write-through at creation +
        // removeTarget at teardown/unset). a cell can have several targets - a
        // referenced element that survived a `$d = $c` clone binds the entry in
        // BOTH arrays - so apply every one. slice captured once (an inner set's
        // destructor could mutate the map; matches the legacy scan's semantics)
        const ri = self.ref_index orelse return;
        const list = ri.fwd.getPtr(cell) orelse return;
        const items = list.items;
        for (items) |target| {
            switch (target) {
                .array => |t| try self.arraySetOwned(t.array, t.key, val),
                .object => |t| try t.object.set(self.allocator, t.prop_name, val),
                .static => |t| {
                    try self.writeStaticProp(t.class_name, t.prop_name, val);
                },
                .capture => |t| self.writeCaptureMirror(t.closure, t.var_name, val),
            }
        }
    }

    // sync a closure's by-ref capture mirror with a write through its cell.
    // the mirror owns a reference so the value outlives the frame that
    // created the reference (see closure_bind_ref)
    fn writeCaptureMirror(self: *VM, closure: *PhpObject, var_name: []const u8, val: Value) void {
        const name = closure.closureName() orelse return;
        const range = self.capture_index.getPtr(name) orelse return;
        for (self.captures.items[range.start .. range.start + range.len]) |*entry| {
            if (entry.ref_cell == null or !std.mem.eql(u8, entry.var_name, var_name)) continue;
            retainValue(val);
            self.releaseValue(entry.value);
            entry.value = val;
            return;
        }
    }

    fn regRefCapture(self: *VM, range: *CaptureRange, cell: *Value, var_name: []const u8) RuntimeError!void {
        const owner = range.object orelse return;
        if (range.ref_owner == 0) range.ref_owner = (try self.refIndex()).createOwner();
        try (try self.refIndex()).addOwned(self.allocator, range.ref_owner, cell, .{ .capture = .{ .closure = owner, .var_name = var_name } });
    }

    fn writebackRefs(self: *VM) !void {
        // array/object .set are retaining store choke points that do NOT release
        // the overwritten old value (no VM access there). capture+release it
        // here, mirroring array_set_local. without this, writing the cell's
        // current value back over an identical (or any) element re-retains
        // without dropping the old hold - a +1 leak that later makes cowSeparate
        // split a sole-owned referenced array
        const ri = self.ref_index orelse return;
        const bindings = ri.ownerBindings(self.currentFrame().ref_owner) orelse return;
        for (bindings) |binding| switch (binding.target) {
            .array => |target| try self.arraySetOwned(target.array, target.key, binding.cell.*),
            .object => |target| try target.object.set(self.allocator, target.prop_name, binding.cell.*),
            .static => |target| try self.writeStaticProp(target.class_name, target.prop_name, binding.cell.*),
            .capture => |target| self.writeCaptureMirror(target.closure, target.var_name, binding.cell.*),
        };
    }

    // static props are durable holders: every write retains the new value and
    // releases the one it replaces
    fn putStaticProp(self: *VM, cls: *ClassDef, prop_name: []const u8, val: Value) !void {
        retainValue(val);
        const old = try cls.static_props.fetchPut(self.allocator, prop_name, val);
        if (old) |kv| self.releaseValue(kv.value);
    }

    // a static property write from outside the vm's opcodes (reflection)
    pub fn setStaticPropValue(self: *VM, class_name: []const u8, prop_name: []const u8, val: Value) RuntimeError!void {
        try self.resolveClassDefaults(class_name);
        try self.writeStaticProp(class_name, prop_name, val);
        self.syncStaticPropRefs(class_name, prop_name, val);
    }

    pub fn staticPropertyValue(self: *VM, class_name: []const u8, prop_name: []const u8) RuntimeError!?Value {
        try self.resolveClassDefaults(class_name);
        return self.getStaticProp(class_name, prop_name);
    }

    fn writeStaticProp(self: *VM, class_name: []const u8, prop_name: []const u8, val: Value) !void {
        if (self.classes.getPtr(class_name)) |cls| {
            if (cls.static_props.contains(prop_name)) {
                try self.putStaticProp(cls, prop_name, val);
                return;
            }
            var parent: ?[]const u8 = cls.parent;
            while (parent) |p| {
                if (self.classes.getPtr(p)) |pcls| {
                    if (pcls.static_props.contains(prop_name)) {
                        try self.putStaticProp(pcls, prop_name, val);
                        return;
                    }
                    parent = pcls.parent;
                } else break;
            }
            try self.putStaticProp(cls, prop_name, val);
        }
    }

    fn scanCallerVarNames(self: *VM, ac: usize) [16]?[]const u8 {
        var arg_vars: [16]?[]const u8 = @splat(null);
        const chunk = self.currentChunk();
        const ip = self.currentFrame().ip;
        if (ip < 4) return arg_vars;
        // scan backwards from just before the call instruction
        // each arg is a single value-producing instruction
        var scan_end = ip - 4; // points to call opcode
        var idx: usize = ac;
        while (idx > 0 and scan_end >= 3) {
            idx -= 1;
            const op = chunk.code.items[scan_end - 3];
            if (op == @intFromEnum(OpCode.get_var)) {
                const hi = chunk.code.items[scan_end - 2];
                const lo = chunk.code.items[scan_end - 1];
                const ci = (@as(u16, hi) << 8) | lo;
                if (ci < chunk.constants.items.len) {
                    arg_vars[idx] = chunk.constants.items[ci].string;
                }
                scan_end -= 3;
            } else if (op == @intFromEnum(OpCode.get_local)) {
                const hi = chunk.code.items[scan_end - 2];
                const lo = chunk.code.items[scan_end - 1];
                const slot = (@as(u16, hi) << 8) | lo;
                const sn = if (self.currentFrame().func) |func| func.slot_names else self.global_slot_names;
                if (slot < sn.len) {
                    arg_vars[idx] = sn[slot];
                }
                scan_end -= 3;
            } else if (op == @intFromEnum(OpCode.constant)) {
                scan_end -= 3;
            } else if (scan_end >= 1 and (chunk.code.items[scan_end - 1] == @intFromEnum(OpCode.op_null) or
                chunk.code.items[scan_end - 1] == @intFromEnum(OpCode.op_true) or
                chunk.code.items[scan_end - 1] == @intFromEnum(OpCode.op_false)))
            {
                scan_end -= 1;
            } else {
                break;
            }
        }
        return arg_vars;
    }

    fn resolveCallerVar(self: *VM, var_name: []const u8, is_local: bool, slot: u16) Value {
        if (!is_local and isSuperglobal(var_name)) return if (self.globals_cells.get(var_name)) |cell| cell.* else .null;
        const frame = self.currentFrame();
        if (is_local and slot < frame.locals.len) {
            return frame.locals[slot];
        }
        if (frame.ref_slots.get(var_name)) |cell| return cell.*;
        return frame.vars.get(var_name) orelse .null;
    }

    // argument guards. a guard names the call opcode it feeds and the position
    // it fills; the callee's signature decides whether the fetch that follows
    // must record lvalue provenance (by reference, or not resolvable without
    // side effects) or may run as a plain read. resolution never executes PHP
    // and never autoloads: an unregistered callee simply captures
    pub fn argNeedsCapture(self: *VM, chunk: *const Chunk, field: usize, delta: u16, pos: u8, operands: usize) bool {
        return self.resolveArgIntent(chunk, field, delta, pos, operands, false);
    }

    // a temporary sent where the callee might take a reference matters only
    // to a registered callee, so a name no by-reference callee goes by
    // settles it. a variable can't skip resolving: a callee autoloaded or
    // declared by the call itself still takes it by reference
    fn tempArgNeedsCheck(self: *VM, chunk: *const Chunk, field: usize, delta: u16, pos: u8) bool {
        return self.resolveArgIntent(chunk, field, delta, pos, 1, true);
    }

    fn resolveArgIntent(self: *VM, chunk: *const Chunk, field: usize, delta: u16, pos: u8, operands: usize, temporary: bool) bool {
        if (self.argCaptureCached(chunk, field, delta, pos, operands)) |cached| return cached;
        const code = chunk.code.items;
        const call_ip = field + delta;
        if (call_ip >= code.len) return true;
        const args_base = self.argsBase(pos, operands) orelse return true;
        const slots = guardSlots(code, call_ip);
        const guard = self.guardIdentity(slots, args_base);
        const by_value = (temporary and self.callSiteNamesNoRef(chunk, call_ip)) or (self.callSiteByValue(chunk, call_ip, pos, args_base) orelse false);
        if (self.ic) |ic| if (guard) |g| {
            const chunk_key = @intFromPtr(chunk);
            ic.intent[InlineCache.intentIndex(chunk_key, field)] = .{ .key = field, .chunk_key = chunk_key, .guard = g, .generation = self.registryGeneration(), .slots = slots, .capture = !by_value };
        };
        return !by_value;
    }

    // the cached answer for a guard site, or null when the site must resolve
    pub inline fn argCaptureCached(self: *VM, chunk: *const Chunk, field: usize, delta: u16, pos: u8, operands: usize) ?bool {
        if (delta == 0) return true;
        const ic = self.ic orelse return null;
        const chunk_key = @intFromPtr(chunk);
        const e = &ic.intent[InlineCache.intentIndex(chunk_key, field)];
        if (e.key != field or e.chunk_key != chunk_key or e.generation != self.registryGeneration()) return null;
        const args_base = self.argsBase(pos, operands) orelse return true;
        const guard = self.guardIdentity(e.slots, args_base) orelse return null;
        if (e.guard != guard) return null;
        return e.capture;
    }

    // how many stack slots below the arguments identify the callee: the
    // receiver or callable (1), a receiver plus a name (2), or the calling
    // class for static:: dispatch (3)
    fn guardSlots(code: []const u8, call_ip: usize) u8 {
        const call_op = std.enums.fromInt(OpCode, code[call_ip]) orelse return 0;
        return switch (call_op) {
            .method_call, .method_call_spread, .static_call_dynamic, .new_obj_dynamic, .call_indirect, .static_call_dyn_method => 1,
            .method_call_dynamic, .method_call_dynamic_spread, .static_call_dyn_both, .static_call_dyn_both_spread => 2,
            .static_call, .static_call_spread => 3,
            else => 0,
        };
    }

    inline fn guardIdentity(self: *VM, slots: u8, args_base: usize) ?usize {
        if (slots < 3 and args_base < slots) return null;
        return switch (slots) {
            0 => 0,
            1 => valueIdentity(self.stack[args_base - 1]),
            2 => blk: {
                const a = valueIdentity(self.stack[args_base - 2]) orelse break :blk null;
                const b = valueIdentity(self.stack[args_base - 1]) orelse break :blk null;
                break :blk a ^ (b *% 0x9E3779B97F4A7C15);
            },
            else => if (self.currentFrame().called_class) |cc| @intFromPtr(cc.ptr) else 0,
        };
    }

    inline fn registryGeneration(self: *VM) usize {
        return self.functions.count() - @min(self.live_closure_instances, self.functions.count()) + self.native_fns.count() + self.classes.count();
    }

    // stack index of the first argument slot (or of the spread array)
    inline fn argsBase(self: *VM, pos: u8, operands: usize) ?usize {
        const region: usize = switch (pos) {
            arg_pos_spread => 1,
            arg_pos_named => 2,
            else => pos,
        };
        if (self.sp < operands + region) return null;
        return self.sp - operands - region;
    }

    const arg_pos_spread: u8 = 0xFF;
    const arg_pos_named: u8 = 0xFE;

    fn callOpU16(code: []const u8, at: usize) u16 {
        return (@as(u16, code[at]) << 8) | code[at + 1];
    }

    inline fn valueIdentity(value: Value) ?usize {
        return switch (value) {
            // a closure by its function (set when made), else its instance
            .object => |o| if (o.native.kind != .closure) @intFromPtr(o.class_name.ptr) else if (o.native.extra != 0) o.native.extra else o.native.ptr,
            .string => |s| @intFromPtr(s.bytes().ptr),
            .array => null,
            else => 0,
        };
    }

    // true when the callee takes `pos` by value, false when by reference,
    // null when the callee cannot be resolved without side effects
    fn callSiteByValue(self: *VM, chunk: *const Chunk, call_ip: usize, pos: u8, args_base: usize) ?bool {
        const code = chunk.code.items;
        const consts = chunk.constants.items;
        const call_op = std.enums.fromInt(OpCode, code[call_ip]) orelse return null;
        return switch (call_op) {
            .call, .call_spread => self.functionByValue(consts[callOpU16(code, call_ip + 1)].string.bytes(), pos),
            .call_indirect => self.callableByValue(self.stack[args_base - 1], pos),
            .method_call, .method_call_spread => self.methodByValue(self.stack[args_base - 1], consts[callOpU16(code, call_ip + 1)].string.bytes(), pos),
            .method_call_dynamic, .method_call_dynamic_spread => blk: {
                const name = self.stack[args_base - 1];
                if (name != .string) break :blk null;
                break :blk self.methodByValue(self.stack[args_base - 2], name.string.bytes(), pos);
            },
            .static_call, .static_call_spread => self.staticByValue(consts[callOpU16(code, call_ip + 1)].string.bytes(), consts[callOpU16(code, call_ip + 3)].string.bytes(), pos),
            .static_call_dynamic => self.classValueStaticByValue(self.stack[args_base - 1], consts[callOpU16(code, call_ip + 1)].string.bytes(), pos),
            .static_call_dyn_method => blk: {
                const method = self.stack[args_base - 1];
                if (method != .string) break :blk null;
                break :blk self.staticByValue(consts[callOpU16(code, call_ip + 1)].string.bytes(), method.string.bytes(), pos);
            },
            .static_call_dyn_both, .static_call_dyn_both_spread => blk: {
                const method = self.stack[args_base - 1];
                if (method != .string) break :blk null;
                break :blk self.classValueStaticByValue(self.stack[args_base - 2], method.string.bytes(), pos);
            },
            .new_obj => self.constructorByValue(consts[callOpU16(code, call_ip + 1)].string.bytes(), pos),
            .new_obj_dynamic => blk: {
                const class_val = self.stack[args_base - 1];
                break :blk switch (class_val) {
                    .string => |s| self.constructorByValue(s.bytes(), pos),
                    .object => |o| self.constructorByValue(o.class_name, pos),
                    else => null,
                };
            },
            else => null,
        };
    }

    // the registered name of the callee a call site will call, as far as it
    // can be known before the call: a function, or "Class::method"
    fn argCalleeName(self: *VM, chunk: *const Chunk, call_ip: usize, args_base: usize) ?[]const u8 {
        const code = chunk.code.items;
        const consts = chunk.constants.items;
        if (call_ip >= code.len) return null;
        const call_op = std.enums.fromInt(OpCode, code[call_ip]) orelse return null;
        switch (call_op) {
            .call, .call_spread => {
                const raw = consts[callOpU16(code, call_ip + 1)].string.bytes();
                const name = if (raw.len > 0 and raw[0] == '\\') raw[1..] else raw;
                if (self.functions.getKey(name)) |key| return key;
                if (self.native_fns.getKey(name)) |key| return key;
                const sep = std.mem.lastIndexOfScalar(u8, name, '\\') orelse return null;
                if (self.functions.getKey(name[sep + 1 ..])) |key| return key;
                return self.native_fns.getKey(name[sep + 1 ..]);
            },
            .method_call, .method_call_spread => {
                const receiver = self.stack[args_base - 1];
                if (receiver != .object) return null;
                return self.resolveMethod(receiver.object.class_name, consts[callOpU16(code, call_ip + 1)].string.bytes()) catch null;
            },
            .static_call, .static_call_spread => {
                const class_name = self.intentClassName(consts[callOpU16(code, call_ip + 1)].string.bytes()) orelse return null;
                return self.resolveMethod(class_name, consts[callOpU16(code, call_ip + 3)].string.bytes()) catch null;
            },
            .new_obj => {
                const class_name = self.intentClassName(consts[callOpU16(code, call_ip + 1)].string.bytes()) orelse return null;
                return self.resolveMethod(class_name, "__construct") catch null;
            },
            else => return null,
        }
    }

    // zend_cannot_pass_by_reference's message for argument pos of a callee
    pub fn cannotPassByReference(self: *VM, callee: []const u8, pos: u8) ![]u8 {
        var param: []const u8 = "";
        var shown: []const u8 = callee;
        if (self.functions.get(callee)) |func| {
            shown = try self.funcDisplayName(func);
            if (func.params.len > 0) param = func.params[@min(pos, func.params.len - 1)];
            if (param.len > 0 and param[0] == '$') param = param[1..];
        } else {
            var lower_buf: [256]u8 = undefined;
            if (callee.len <= lower_buf.len) {
                const signatures = @import("../stdlib/native_params_generated.zig").map;
                const sig = signatures.get(callee) orelse signatures.get(std.ascii.lowerString(&lower_buf, callee));
                if (sig) |sg| if (sg.params.len > 0) {
                    param = sg.params[@min(pos, sg.params.len - 1)].name;
                };
            }
        }
        if (param.len == 0) return std.fmt.allocPrint(self.allocator, "{s}(): Argument #{d} could not be passed by reference", .{ shown, @as(usize, pos) + 1 });
        return std.fmt.allocPrint(self.allocator, "{s}(): Argument #{d} (${s}) could not be passed by reference", .{ shown, @as(usize, pos) + 1, param });
    }

    // whether the call that just returned to the instruction at ip was to
    // a function returning by reference that returned no variable
    fn returnedRefValueHere(self: *VM, ip: usize) bool {
        const at = self.return_ref_value_at orelse return false;
        if (self.frame_count == 0 or at.frame != self.frame_count - 1 or at.ip != ip) return false;
        self.return_ref_value_at = null;
        return true;
    }

    // the same storage: a returned reference's value and the value pushed
    fn sameReferent(a: Value, b: Value) bool {
        return switch (a) {
            .array => |x| b == .array and b.array == x,
            .object => |x| b == .object and b.object == x,
            .string => |x| b == .string and b.string.bytes().ptr == x.bytes().ptr,
            .int => |x| b == .int and b.int == x,
            .float => |x| b == .float and b.float == x,
            .bool => |x| b == .bool and b.bool == x,
            .null => b == .null,
            else => false,
        };
    }

    fn funcByValue(func: *const ObjFunction, pos: u8) bool {
        if (pos >= arg_pos_named) return std.mem.indexOfScalar(bool, func.ref_params, true) == null;
        if (pos < func.ref_params.len) return !func.ref_params[pos];
        return !(func.is_variadic and func.ref_params.len > 0 and func.ref_params[func.ref_params.len - 1]);
    }

    fn nativeByValue(name: []const u8, pos: u8) bool {
        if (pos >= arg_pos_named) return !byref_args.hasByRefParams(name);
        return !byref_args.isByRef(name, pos);
    }

    fn resolvedByValue(self: *VM, full: []const u8, pos: u8) ?bool {
        if (self.functions.get(full)) |func| return funcByValue(func, pos);
        if (self.native_fns.contains(full)) return !byref_args.hasByRefParams(full) or nativeByValue(full, pos);
        return null;
    }

    fn functionByValue(self: *VM, raw_name: []const u8, pos: u8) ?bool {
        const name = if (raw_name.len > 0 and raw_name[0] == '\\') raw_name[1..] else raw_name;
        if (self.resolvedByValue(name, pos)) |v| return v;
        if (std.mem.lastIndexOfScalar(u8, name, '\\')) |sep| {
            if (self.resolvedByValue(name[sep + 1 ..], pos)) |v| return v;
        }
        return null;
    }

    fn classMethodByValue(self: *VM, class_name: []const u8, method: []const u8, pos: u8, magic: []const u8) ?bool {
        var buf: [512]u8 = undefined;
        if (self.classes.get(class_name) == null) {
            const full = class_names.memberKey(&buf, class_name, method);
            if (self.native_fns.contains(full)) return nativeByValue(full, pos);
            return null;
        }
        const full = self.resolveMethod(class_name, method) catch {
            return if (self.hasMethod(class_name, magic)) true else null;
        };
        return self.resolvedByValue(full, pos);
    }

    fn methodByValue(self: *VM, receiver: Value, method: []const u8, pos: u8) ?bool {
        if (receiver != .object) return null;
        if (receiver.object.lazy != null) return null;
        // a closure's __invoke takes the closure's own parameters
        if (std.mem.eql(u8, receiver.object.class_name, "Closure") and std.ascii.eqlIgnoreCase(method, "__invoke")) return self.callableByValue(receiver, pos);
        return self.classMethodByValue(receiver.object.class_name, method, pos, "__call");
    }

    fn intentClassName(self: *VM, raw_class: []const u8) ?[]const u8 {
        if (std.mem.eql(u8, raw_class, "static")) return self.currentFrame().called_class orelse self.currentDefiningClass();
        if (std.mem.eql(u8, raw_class, "self")) return self.currentDefiningClass();
        if (std.mem.eql(u8, raw_class, "parent")) {
            const defining = self.currentDefiningClass() orelse return null;
            const cls = self.classes.get(defining) orelse return null;
            return cls.parent;
        }
        return if (raw_class.len > 0 and raw_class[0] == '\\') raw_class[1..] else raw_class;
    }

    fn staticByValue(self: *VM, raw_class: []const u8, method: []const u8, pos: u8) ?bool {
        const class_name = self.intentClassName(raw_class) orelse return null;
        return self.classMethodByValue(class_name, method, pos, "__callStatic");
    }

    fn classValueStaticByValue(self: *VM, class_val: Value, method: []const u8, pos: u8) ?bool {
        return switch (class_val) {
            .string => |s| self.staticByValue(s.bytes(), method, pos),
            .object => |o| self.classMethodByValue(o.class_name, method, pos, "__call"),
            else => null,
        };
    }

    fn constructorByValue(self: *VM, raw_class: []const u8, pos: u8) ?bool {
        const class_name = self.intentClassName(raw_class) orelse return null;
        if (self.classes.get(class_name) == null) return null;
        const full = self.resolveMethod(class_name, "__construct") catch return true;
        return self.resolvedByValue(full, pos);
    }

    fn callableByValue(self: *VM, callable: Value, pos: u8) ?bool {
        switch (callable) {
            .string => |s| {
                const bytes = s.bytes();
                if (std.mem.indexOf(u8, bytes, "::")) |sep| return self.staticByValue(bytes[0..sep], bytes[sep + 2 ..], pos);
                return self.functionByValue(bytes, pos);
            },
            .object => |o| {
                if (o.closureName()) |name| return self.functionByValue(name, pos);
                if (o.fakeClosure()) |state| return self.callableByValue(state.callable, pos);
                return self.methodByValue(callable, "__invoke", pos);
            },
            .array => |a| {
                if (a.entries.items.len != 2) return null;
                const target = a.entries.items[0].value;
                const method = a.entries.items[1].value;
                if (method != .string) return null;
                return switch (target) {
                    .object => self.methodByValue(target, method.string.bytes(), pos),
                    .string => |s| self.staticByValue(s.bytes(), method.string.bytes(), pos),
                    else => null,
                };
            },
            else => return null,
        }
    }

    const CallFamilyScope = struct { base: usize, count: usize, frame: usize };

    // a native callback's own calls run at this frame depth; keep the
    // enclosing call's output destinations across them. every call family
    // opcode enters at its start and leaves on every exit path
    fn enterCallFamily(self: *VM, op: OpCode) RuntimeError!CallFamilyScope {
        const ic = self.ic.?;
        const scope: CallFamilyScope = .{ .base = ic.saved_sources.items.len, .count = ic.active_arg_count, .frame = ic.active_frame };
        if (scope.count > 0) try ic.saved_sources.appendSlice(self.allocator, ic.active_args[0..scope.count]);
        ic.active_arg_count = 0;
        const code = self.currentChunk().code.items;
        const ip = self.currentFrame().ip;
        const ac: usize = switch (op) {
            .call, .method_call, .new_obj, .static_call_dyn_method => code[ip + 2],
            .call_indirect, .method_call_dynamic, .static_call_dyn_both => code[ip],
            .static_call => code[ip + 4],
            else => 0,
        };
        self.captureArgSources(ac);
        return scope;
    }

    fn leaveCallFamily(self: *VM, scope: CallFamilyScope) void {
        const ic = self.ic.?;
        self.clearActiveArgSources();
        if (scope.count > 0) {
            @memcpy(ic.active_args[0..scope.count], ic.saved_sources.items[scope.base .. scope.base + scope.count]);
            ic.saved_sources.shrinkRetainingCapacity(scope.base);
        }
        ic.active_arg_count = scope.count;
        ic.active_frame = scope.frame;
    }

    fn isCallFamilyOp(op: OpCode) bool {
        return switch (op) {
            .call, .call_spread, .call_indirect, .call_indirect_spread, .new_obj, .method_call, .method_call_spread, .method_call_dynamic, .static_call, .static_call_spread, .static_call_dyn_method, .static_call_dyn_both, .static_call_dyn_both_spread, .new_obj_dynamic => true,
            else => false,
        };
    }

    // Provenance is an owning transport, independent of the evaluated value.
    // the array a by-reference argument's container becomes when it holds
    // nothing, stored where the container came from
    fn vivifyArgContainer(self: *VM, base: RefSource) RuntimeError!Value {
        const fresh: Value = .{ .array = try self.allocArray() };
        switch (base) {
            .simple => |name| {
                if (isSuperglobal(name)) {
                    const cell = try self.superglobalCell(name);
                    self.setCell(cell, fresh);
                    try self.propagateCellWrite(cell, fresh);
                } else {
                    retainValue(fresh);
                    try self.setVariableByName(self.currentFrame(), try self.internName(name), fresh);
                }
            },
            .cell => |c| {
                self.setCell(c.value, fresh);
                try self.propagateCellWrite(c.value, fresh);
            },
            .none => {},
        }
        return fresh;
    }

    // the array a by-reference argument writes into, separated from the
    // copies that share it and stored back where it came from
    fn separateArgContainer(self: *VM, base: RefSource, arr: *PhpArray) RuntimeError!*PhpArray {
        switch (base) {
            .simple => |name| {
                const frame = self.currentFrame();
                if (isSuperglobal(name)) return arr;
                if (frame.ref_slots.get(name)) |cell| return (try self.separateReferencedArray(frame, name, cell, arr)) orelse arr;
                const sep = try self.cowSeparate(arr);
                if (sep != arr) try self.setVariableByName(frame, try self.internName(name), .{ .array = sep });
                return sep;
            },
            .cell => |c| {
                if (arr.refcount - arr.byref_pins <= self.referenceAliasCount(c.value)) return arr;
                const clone = try self.shallowCloneCow(arr);
                const value: Value = .{ .array = clone };
                self.setCell(c.value, value);
                try self.propagateCellWrite(c.value, value);
                return clone;
            },
            .none => return arr,
        }
    }

    fn captureDimensionCell(self: *VM, slot: usize, array: *PhpArray, key: Value, base: RefSource) RuntimeError!void {
        const ak = Value.toArrayKey(key);
        if (!array.contains(ak)) try self.arraySetOwned(array, ak, .null);
        const entry = array.getPtr(ak).?;
        const cell = entry.ref orelse blk: {
            const fresh = try self.newRefCell();
            self.setCell(fresh, entry.value);
            self.setEntryRef(entry, fresh);
            break :blk fresh;
        };
        try self.regRefArray(try self.persistentRefOwner(), cell, array, ak);
        self.array_ref_active = true;
        self.setArgSource(slot, .{ .cell = .{ .value = cell, .denial = switch (base) {
            .cell => |c| c.denial,
            else => null,
        } } });
    }

    fn checkArgCell(self: *VM, denial: ?[]const u8) RuntimeError!void {
        if (denial) |text| {
            const floor = self.handler_floor;
            self.handler_floor = self.handler_count;
            defer self.handler_floor = floor;
            _ = try self.throwBuiltinException("Error", text);
            return error.RuntimeError;
        }
    }

    fn capturePropertyCell(self: *VM, slot: usize, obj: *PhpObject, name: []const u8) RuntimeError!void {
        const vr = self.findPropertyVisibility(obj.class_name, name);
        var denial: ?[]const u8 = null;
        if (vr.set_visibility != vr.visibility and !self.propVisible(vr, name, vr.set_visibility)) {
            const ro: []const u8 = if (vr.is_readonly and vr.set_visibility == .protected) " readonly" else "";
            denial = if (self.currentDefiningClass()) |sc|
                try std.fmt.allocPrint(self.allocator, "Cannot indirectly modify {s}(set){s} property {s}::${s} from scope {s}", .{ @tagName(vr.set_visibility), ro, vr.defining_class, name, sc })
            else
                try std.fmt.allocPrint(self.allocator, "Cannot indirectly modify {s}(set){s} property {s}::${s} from global scope", .{ @tagName(vr.set_visibility), ro, vr.defining_class, name });
        } else if (vr.is_readonly) {
            denial = try std.fmt.allocPrint(self.allocator, "Cannot indirectly modify readonly property {s}::${s}", .{ vr.defining_class, name });
        }
        // the denial rides along with the argument's source until a write
        // raises it, so it is interned rather than owned by one copy
        if (denial) |text| {
            defer self.allocator.free(text);
            denial = try self.internName(text);
        }
        const index = try self.refIndex();
        const cell = cell: {
            if (index.prop_rev.get(.{ .object = obj, .class_name = "", .prop_name = name })) |cells| {
                if (cells.items.len > 0) break :cell cells.items[0];
            }
            const fresh = try self.newRefCell();
            self.setCell(fresh, self.stack[slot]);
            break :cell fresh;
        };
        // The property target is weak; receiver reclamation detaches it. The
        // argument owns the cell, never the temporary receiver.
        try self.regRefObject(try self.persistentRefOwner(), cell, obj, name);
        self.obj_ref_active = true;
        self.setArgSource(slot, .{ .cell = .{ .value = cell, .denial = denial } });
    }

    fn retainArgSource(self: *VM, source: RefSource) RefSource {
        if (source == .cell) self.bindCell(source.cell.value);
        return source;
    }

    fn releaseArgSource(self: *VM, source: *RefSource) void {
        if (source.* == .none) return;
        const old = source.*;
        source.* = .none;
        switch (old) {
            .cell => |c| {
                // A speculative argument reference with only its storage and
                // final transport holder left must not turn a value read into
                // a persistent array-element alias.
                if (cellOf(c.value).binders == 2) {
                    if (self.ref_index) |ri| {
                        if (ri.fwd.get(c.value)) |targets| {
                            if (targets.items.len == 1) {
                                const target = targets.items[0];
                                if (target == .array) {
                                    if (target.array.array.getPtr(target.array.key)) |entry| {
                                        if (entry.ref == c.value) self.setEntryRef(entry, null);
                                    }
                                    ri.removeTargetAllOwners(self.allocator, c.value, target);
                                } else if (target == .object) {
                                    ri.removeTargetAllOwners(self.allocator, c.value, target);
                                }
                            }
                        }
                    }
                }
                self.unbindCell(c.value);
            },
            .simple, .none => {},
        }
    }

    fn discardArgTransport(self: *VM, floor: usize) void {
        if (floor < self.sp) for (self.stack[floor..self.sp]) |v| {
            if (v == .array) self.clearArgArraySources(v.array);
        };
        self.clearArgStackFrom(floor);
        // the operands an exception unwinds go with their references, as
        // php frees a frame's live temporaries
        if (floor < self.sp) for (self.stack[floor..self.sp]) |v| switch (v) {
            .string, .object, .resource, .generator, .fiber => self.stackRelease(v),
            .array => if (v.array.refcount == 0) self.queueArrayRelease(v.array),
            else => {},
        };
    }

    // Most operand-stack operations carry no lvalue provenance. Keep that
    // check inline without pulling source release/ref-index work into hot loops.
    pub inline fn clearArgStackFrom(self: *VM, floor: usize) void {
        if (floor >= self.arg_source_end) return;
        self.clearArgStackFromSlow(floor);
    }

    // fastLoop pops without visiting the transport, so a slot above sp may
    // still carry provenance from an earlier call; drop it before reuse
    fn releaseStaleArgSource(self: *VM, slot: usize) void {
        const ic = self.ic orelse return;
        if (ic.arg_stack[slot] != .none) self.releaseArgSource(&ic.arg_stack[slot]);
    }

    fn clearArgStackFromSlow(self: *VM, floor: usize) void {
        if (self.ic) |ic| {
            const end = @min(self.sp, self.arg_source_end);
            if (floor < end) for (ic.arg_stack[floor..end]) |*source| {
                if (source.* != .none) self.releaseArgSource(source);
            };
            if (self.sp >= self.arg_source_end and floor < self.arg_source_end) self.arg_source_end = floor;
        }
    }

    pub fn setArgSource(self: *VM, slot: usize, source: RefSource) void {
        const ic = self.ic orelse return;
        if (source == .none and slot >= self.arg_source_end) return;
        const owned = self.retainArgSource(source);
        if (ic.arg_stack[slot] != .none) self.releaseArgSource(&ic.arg_stack[slot]);
        ic.arg_stack[slot] = owned;
        if (source != .none) self.arg_source_end = @max(self.arg_source_end, slot + 1);
    }

    fn clearActiveArgSources(self: *VM) void {
        if (self.ic) |ic| {
            for (ic.active_args[0..ic.active_arg_count]) |*source| self.releaseArgSource(source);
            ic.active_arg_count = 0;
        }
    }

    fn clearArgArraySources(self: *VM, array: ?*PhpArray) void {
        const ic = self.ic orelse return;
        var i: usize = 0;
        while (i < ic.arg_arrays.items.len) {
            if (array == null or ic.arg_arrays.items[i].array == array.?) {
                var entry = ic.arg_arrays.swapRemove(i);
                self.releaseArgSource(&entry.source);
                if (entry.key == .string) self.releaseValue(.{ .string = entry.key.string });
            } else i += 1;
        }
    }

    fn recordArgArraySource(self: *VM, array: *PhpArray, key: PhpArray.Key, source: RefSource) !void {
        const ic = self.ic orelse return;
        for (ic.arg_arrays.items) |*entry| {
            if (entry.array == array and entry.key.eql(key)) {
                const owned = self.retainArgSource(source);
                self.releaseArgSource(&entry.source);
                entry.source = owned;
                return;
            }
        }
        const owned_key: PhpArray.Key = switch (key) {
            .string => |v| blk: {
                v.retain();
                break :blk .{ .string = v };
            },
            else => key,
        };
        errdefer if (owned_key == .string) self.releaseValue(.{ .string = owned_key.string });
        var owned = self.retainArgSource(source);
        errdefer self.releaseArgSource(&owned);
        try ic.arg_arrays.append(self.allocator, .{ .array = array, .key = owned_key, .source = owned });
    }

    fn releaseBoundArgSources(self: *VM, owner: ?RefIndex.OwnerId) void {
        const ic = self.ic orelse return;
        var i: usize = 0;
        while (i < ic.bound_arg_sources.items.len) {
            if (owner == null or ic.bound_arg_sources.items[i].owner == owner.?) {
                var entry = ic.bound_arg_sources.swapRemove(i);
                self.releaseArgSource(&entry.source);
            } else i += 1;
        }
    }

    fn argRefOwner(self: *VM, func: *const ObjFunction) RuntimeError!RefIndex.OwnerId {
        // A nonzero frame owner disables fastLoop local writes. Do not mark
        // by-value method/constructor frames as reference-bound.
        if (std.mem.indexOfScalar(bool, func.ref_params, true) == null) return 0;
        return (try self.refIndex()).createOwner();
    }

    fn bindOwnedRefParams(self: *VM, ac: usize, func: *const ObjFunction, vars: *std.StringHashMapUnmanaged(Value), refs: *std.StringHashMapUnmanaged(*Value), owner: RefIndex.OwnerId) !void {
        // By-value calls need neither an owning snapshot nor binding storage.
        const ref_count = @min(ac, func.ref_params.len);
        if (std.mem.indexOfScalar(bool, func.ref_params[0..ref_count], true) == null) return;
        var source_buf: [256]RefSource = undefined;
        const live_sources = self.callerArgSources(ac);
        const source_count = @min(live_sources.len, source_buf.len);
        @memcpy(source_buf[0..source_count], live_sources[0..source_count]);
        const sources = source_buf[0..source_count];
        const saved_active_count = self.ic.?.active_arg_count;
        var saved_active: [256]RefSource = undefined;
        @memcpy(saved_active[0..saved_active_count], self.ic.?.active_args[0..saved_active_count]);
        for (self.ic.?.active_args[0..self.ic.?.active_arg_count]) |*source| source.* = self.retainArgSource(source.*);
        defer {
            self.clearActiveArgSources();
            @memcpy(self.ic.?.active_args[0..saved_active_count], saved_active[0..saved_active_count]);
            self.ic.?.active_arg_count = saved_active_count;
        }
        errdefer self.releaseBoundArgSources(owner);
        for (0..@min(@min(ac, func.ref_params.len), sources.len)) |i| {
            if (!func.ref_params[i] or sources[i] == .none) continue;
            var source = self.retainArgSource(sources[i]);
            errdefer self.releaseArgSource(&source);
            try self.ic.?.bound_arg_sources.append(self.allocator, .{ .owner = owner, .source = source });
            self.releaseArgSource(&self.ic.?.active_args[i]);
            self.ic.?.active_args[i] = self.retainArgSource(source);
        }
        // Keep binding names alive with the owner, not the transient active buffer.
        const active_count = self.ic.?.active_arg_count;
        var active: [256]RefSource = undefined;
        @memcpy(active[0..active_count], self.ic.?.active_args[0..active_count]);
        var position: usize = 0;
        for (0..@min(@min(ac, func.ref_params.len), sources.len)) |i| {
            if (!func.ref_params[i] or sources[i] == .none) continue;
            while (self.ic.?.bound_arg_sources.items[position].owner != owner) position += 1;
            self.ic.?.active_args[i] = self.ic.?.bound_arg_sources.items[position].source;
            position += 1;
        }
        defer {
            @memcpy(self.ic.?.active_args[0..active_count], active[0..active_count]);
            self.ic.?.active_arg_count = active_count;
        }
        try self.bindRefParams(ac, func, vars, refs, owner);
    }

    // provenance of the call being bound, valid until the next capture. a
    // consumer that binds while argument sources may change copies it first
    fn callerArgSources(self: *VM, ac: usize) []const RefSource {
        const ic = self.ic orelse return &.{};
        if (ic.active_frame != self.frame_count and !self.inNativeMethodFrame()) return &.{};
        return ic.active_args[0..@min(ac, ic.active_arg_count)];
    }

    // a native method runs in the temporary frame that holds its $this, one
    // above the frame its arguments were captured in
    pub fn inNativeMethodFrame(self: *VM) bool {
        const ic = self.ic orelse return false;
        return ic.active_frame + 1 == self.frame_count and self.frames[self.frame_count - 1].native;
    }

    fn captureArgSources(self: *VM, ac: usize) void {
        const ic = self.ic orelse return;
        self.clearActiveArgSources();
        ic.active_frame = self.frame_count;
        if (ac <= self.sp) {
            const floor = self.sp - ac;
            const end = @min(self.sp, self.arg_source_end);
            if (end <= floor) return;
            var count = @min(end - floor, 256);
            while (count > 0 and ic.arg_stack[floor + count - 1] == .none) count -= 1;
            ic.active_arg_count = count;
            for (0..count) |i| ic.active_args[i] = self.retainArgSource(ic.arg_stack[floor + i]);
        }
    }

    fn argArraySource(self: *VM, arr: *PhpArray, key: PhpArray.Key) RefSource {
        const ic = self.ic orelse return .none;
        for (ic.arg_arrays.items) |entry| {
            if (entry.array == arr and entry.key.eql(key)) return entry.source;
        }
        return .none;
    }

    // a call's arguments copied off the operand stack before they are
    // dropped: into buf, or the heap when the call passes more
    fn copyStackArgs(self: *VM, buf: []Value, values: []const Value) RuntimeError![]Value {
        const out = if (values.len <= buf.len) buf[0..values.len] else try self.allocator.alloc(Value, values.len);
        @memcpy(out, values);
        return out;
    }

    fn freeStackArgs(self: *VM, args: []Value, buf: []Value) void {
        if (args.ptr != buf.ptr) self.allocator.free(args);
    }

    fn pushArgEntry(self: *VM, arr: *PhpArray, entry: PhpArray.Entry) void {
        self.push(if (entry.ref) |ref| ref.* else entry.value);
        var source = self.argArraySource(arr, entry.key);
        // a reference element of an unpacked array binds a by-reference
        // parameter to what it references
        if (source == .none) if (entry.ref) |ref| {
            source = .{ .cell = .{ .value = ref } };
        };
        self.setArgSource(self.sp - 1, source);
    }

    // an unpacked argument list can hold more values than a frame's headroom
    fn pushArgEntries(self: *VM, arr: *PhpArray, entries: []const PhpArray.Entry) RuntimeError!void {
        try self.ensureStackSlots(entries.len);
        // and func_get_args keeps them (saveFrameArgs does not grow its room)
        _ = self.fgaRoomFor(entries.len);
        for (entries) |entry| self.pushArgEntry(arr, entry);
    }

    // Binding runs below call setup, not in the dispatch loop. Queue an
    // exception without unwinding caller frames underneath the binding code.
    fn checkPropertyReferenceBinding(self: *VM, obj: *PhpObject, name: []const u8) RuntimeError!void {
        const floor = self.handler_floor;
        self.handler_floor = self.handler_count;
        defer self.handler_floor = floor;
        _ = try self.checkPropertyMutation(obj, name, .indirect);
    }

    fn bindRefParams(
        self: *VM,
        ac: usize,
        func: *const ObjFunction,
        new_vars: *std.StringHashMapUnmanaged(Value),
        refs: *std.StringHashMapUnmanaged(*Value),
        owner: RefIndex.OwnerId,
    ) !void {
        _ = owner;
        if (func.ref_params.len == 0) return;
        // reference flags are per-position; only bind passed reference params.
        // destinations come from evaluated argument transport, not bytecode
        const ref_window = @min(ac, func.ref_params.len);
        var any_ref = false;
        for (0..ref_window) |ri| {
            if (func.ref_params[ri]) {
                any_ref = true;
                break;
            }
        }
        if (!any_ref) return;
        var source_buf: [256]RefSource = undefined;
        const live_sources = self.callerArgSources(ac);
        const source_count = @min(live_sources.len, source_buf.len);
        @memcpy(source_buf[0..source_count], live_sources[0..source_count]);
        const arg_sources = source_buf[0..source_count];
        for (arg_sources, 0..) |source, ri| {
            if (ri >= ref_window or !func.ref_params[ri]) continue;
            if (source == .cell) try self.checkArgCell(source.cell.denial);
        }
        for (arg_sources, 0..) |source, ri| {
            if (ri >= ref_window or !func.ref_params[ri]) continue;
            switch (source) {
                .cell => |c| {
                    if (c.value.* == .array and c.value.array.refcount > 1) {
                        const separated = try self.shallowCloneCow(c.value.array);
                        self.setCell(c.value, .{ .array = separated });
                        try self.propagateCellWrite(c.value, c.value.*);
                    }
                    try new_vars.put(self.allocator, func.params[ri], c.value.*);
                    try self.bindRefSlot(refs, func.params[ri], c.value);
                },
                .simple => |caller_var| {
                    if (isSuperglobal(caller_var)) {
                        const cell = try self.superglobalCell(caller_var);
                        if (cell.* == .array) _ = try self.separateReferencedArray(self.currentFrame(), caller_var, cell, cell.array);
                        try new_vars.put(self.allocator, func.params[ri], cell.*);
                        try self.bindRefSlot(refs, func.params[ri], cell);
                        continue;
                    }
                    if (self.currentFrame().ref_slots.get(caller_var)) |existing_cell| {
                        self.setCell(existing_cell, new_vars.get(func.params[ri]) orelse .null);
                        try self.bindRefSlot(refs, func.params[ri], existing_cell);
                    } else {
                        var bound = new_vars.get(func.params[ri]) orelse .null;
                        // a PHP reference is never COW-shared with a non-reference:
                        // binding the ref to a COW-shared array must give it a
                        // private copy, else an in-place mutation through the ref
                        // (unset/array_shift/array_splice) corrupts another COW
                        // holder (`$reader = $shared; f($shared)` would drop the
                        // unset key from $reader too). clone via shallowCloneCow,
                        // NOT cowSeparate: cowSeparate decrements the original, but
                        // here the param view isn't counted yet (retainFrameObjects
                        // runs later) and the original stays owned by the caller's
                        // slot + the other COW holders, which keep the source value
                        if (bound == .array and bound.array.refcount > 1) {
                            const fresh = try self.shallowCloneCow(bound.array);
                            bound = .{ .array = fresh };
                            try new_vars.put(self.allocator, func.params[ri], bound);
                        }
                        const cell = try self.newRefCell();
                        self.setCell(cell, bound);
                        // the ref cell is a durable holder - retain its array value, or the
                        // callee param slot's release at frame teardown frees the array the
                        // cell (and the caller's ref binding) still points at (Stage 2)

                        try self.bindRefSlot(&self.currentFrame().ref_slots, caller_var, cell);
                        try self.bindRefSlot(refs, func.params[ri], cell);
                    }
                },
                .none => {},
            }
        }
    }

    fn writebackStatics(self: *VM) !void {
        var i: usize = 0;
        while (i < self.static_vars.items.len) {
            const entry = self.static_vars.items[i];
            if (entry.frame_depth == self.frame_count) {
                // save current value back to statics table
                const val = self.currentFrame().vars.get(entry.var_name) orelse .null;
                try self.setStaticVar(entry.var_name, val);
                _ = self.static_vars.swapRemove(i);
            } else {
                i += 1;
            }
        }
    }

    fn getStaticVar(self: *VM, var_name: []const u8) Value {
        // key is the function name we're currently in + "::" + var name
        // find current function name from the chunk pointer
        const func_name = self.currentFuncName() orelse "__main__";
        var key_buf: [256]u8 = undefined;
        const key = class_names.memberKey(&key_buf, func_name, var_name);
        // need to look up with a runtime key - use the statics table
        return self.statics.get(key) orelse .null;
    }

    fn setStaticVar(self: *VM, var_name: []const u8, val: Value) !void {
        const func_name = self.currentFuncName() orelse "__main__";
        var key_buf: [256]u8 = undefined;
        const lookup = class_names.memberKey(&key_buf, func_name, var_name);
        if (self.statics.getEntry(lookup)) |entry| {
            entry.value_ptr.* = val;
        } else {
            const key = try std.fmt.allocPrint(self.allocator, "{s}::{s}", .{ func_name, var_name });
            try self.statics.put(self.allocator, key, val);
        }
    }

    fn currentFuncName(self: *VM) ?[]const u8 {
        // prefer the per-frame call_name so closure instances (which share an
        // ObjFunction) are distinguished for static-var ownership
        if (self.frame_count > 0) {
            if (self.frames[self.frame_count - 1].call_name) |n| return n;
            // a class's copy of a trait method has statics of its own
            if (self.frames[self.frame_count - 1].func) |f| if (f.trait_origin.len > 0) return f.name;
        }
        const chunk_ptr = self.currentChunk();
        var it = self.functions.iterator();
        while (it.next()) |entry| {
            if (entry.value_ptr.*.chunk.code.items.ptr == chunk_ptr.code.items.ptr) {
                return entry.key_ptr.*;
            }
        }
        return null;
    }

    pub fn delayAutoload(self: *VM, name: []const u8) !void {
        for (self.delayed_autoloads.items) |d| if (std.ascii.eqlIgnoreCase(d, name)) return;
        try self.delayed_autoloads.append(self.allocator, try self.internName(name));
    }

    // load_delayed_classes: each in the order the checks met them; one that
    // throws ends everything
    pub fn loadDelayedClasses(self: *VM, class_name: []const u8) RuntimeError!void {
        while (self.delayed_autoloads.items.len > 0) {
            const name = self.delayed_autoloads.orderedRemove(0);
            self.tryAutoload(name) catch |err| {
                if (self.uncatchable_fatal) return err;
                const exc = self.takePending() orelse return err;
                defer self.stackRelease(exc);
                const prefix = try std.fmt.allocPrint(self.allocator, "During inheritance of {s}, while autoloading {s}", .{ class_name, name });
                defer self.allocator.free(prefix);
                return self.uncaughtExceptionFatal(prefix, exc);
            };
        }
    }

    fn nearlyLinked(self: *VM, name: []const u8) ?NearlyLinked {
        for (self.nearly_linked.items) |n| if (std.ascii.eqlIgnoreCase(n.name, name)) return n;
        return null;
    }

    // a class whose declaration is linking it (its parent loading)
    pub fn linkingClass(self: *VM, name: []const u8) ?*Linking {
        var i = self.linking.items.len;
        while (i > 0) {
            i -= 1;
            if (std.ascii.eqlIgnoreCase(self.linking.items[i].name, name)) return &self.linking.items[i];
        }
        return null;
    }

    // check_unrecoverable_load_failure: a class a variance check already
    // relied on while it was unlinked can't be dropped with an exception
    fn unrecoverableLoadFailure(self: *VM, index: usize, err: RuntimeError) RuntimeError {
        if (index >= self.linking.items.len or !self.linking.items[index].used) return err;
        if (self.uncatchable_fatal) return err;
        const exc = self.takePending() orelse return err;
        defer self.stackRelease(exc);
        const prefix = try std.fmt.allocPrint(self.allocator, "During inheritance of {s} with variance dependencies", .{self.linking.items[index].name});
        defer self.allocator.free(prefix);
        return self.uncaughtExceptionFatal(prefix, exc);
    }

    // zend_exception_uncaught_error: "<prefix>: Uncaught <the exception as
    // a string>" as a fatal error
    pub fn uncaughtExceptionFatal(self: *VM, prefix: []const u8, exc: Value) RuntimeError {
        const text: []const u8 = if (exc == .object) (self.objectToString(exc.object) catch "") else "";
        const msg = try std.fmt.allocPrint(self.allocator, "{s}: Uncaught {s}", .{ prefix, text });
        defer self.allocator.free(msg);
        self.discardPending();
        return self.raiseFatal(msg);
    }

    pub fn tryAutoload(self: *VM, raw_class_name: []const u8) RuntimeError!void {
        const class_name = if (raw_class_name.len > 0 and raw_class_name[0] == '\\') raw_class_name[1..] else raw_class_name;
        if (self.classes.contains(class_name)) return;
        if (self.interfaces.contains(class_name)) return;
        if (self.traits.contains(class_name)) return;
        // php never re-enters the autoloaders for a class it is already
        // autoloading, so a cycle (a class file that class_exists() an alias
        // whose file aliases back to it) ends at the class in progress instead
        // of recursing until unrelated autoloads start failing
        const ic = self.ic.?;
        for (ic.autoloading.items) |pending| {
            if (std.ascii.eqlIgnoreCase(pending, class_name)) return;
        }
        // a backstop against runaway chains of distinct classes, far above any
        // real hierarchy
        if (self.autoload_depth >= 250) return;
        self.autoload_depth += 1;
        defer self.autoload_depth -= 1;
        try ic.autoloading.append(self.allocator, class_name);
        defer _ = ic.autoloading.pop();

        // spl_perform_autoload: an autoloader may add or remove autoloaders
        // while the walk goes on
        var i: usize = 0;
        while (i < self.autoload_callbacks.items.len) {
            const callback = self.autoload_callbacks.items[i];
            retainValue(callback);
            defer self.releaseValue(callback);
            if (callback == .string) {
                _ = try self.callByName(callback.string.bytes(), &.{.{ .string = Value.String.borrowed(class_name) }});
            } else {
                var ctx = self.makeContext(null);
                _ = try ctx.invokeCallable(callback, &.{.{ .string = Value.String.borrowed(class_name) }});
            }
            if (self.classes.contains(class_name) or self.interfaces.contains(class_name) or self.traits.contains(class_name)) return;
            // php's hash position moves to the next bucket; one the
            // autoloader removed leaves a hole that the step passes over too
            i += 1;
        }
    }

    // a comparison php fails with an Error (Value.compare leaves the reason
    // in the per-thread hooks): raised once the comparison has returned
    fn raiseCompareFailure(self: *VM) RuntimeError!void {
        const hooks = value_mod.hooks();
        const failure = hooks.compare_failure;
        if (failure == .none) return;
        hooks.compare_failure = .none;
        try self.setPendingException("Error", switch (failure) {
            .nesting => "Nesting level too deep - recursive dependency?",
            .stack => "Maximum call stack size reached during object comparison",
            .none => unreachable,
        });
        return error.RuntimeError;
    }

    fn identicalArrays(self: *VM, a: Value, b: Value) RuntimeError!bool {
        value_mod.hooks().compare_failure = .none;
        const same = Value.identical(a, b);
        try self.raiseCompareFailure();
        return same;
    }

    // mirror of looseEqualWithStringable for ordered comparisons
    pub fn compareWithStringable(self: *VM, a: Value, b: Value) RuntimeError!i64 {
        value_mod.hooks().compare_failure = .none;
        const order = try self.compareWithStringableInner(a, b);
        try self.raiseCompareFailure();
        return order;
    }

    // zend_compare's object cases zphp's Value.compare can't decide: an
    // enum case is comparable only with itself, and an object against a
    // scalar is cast (zend_std_compare_objects), where a failed cast to a
    // number is a notice and 1
    fn compareObjectOperands(self: *VM, a: Value, b: Value) RuntimeError!?i64 {
        if (a == .object and b == .object) {
            if (a.object == b.object) return 0;
            if (self.isEnumObject(a.object) or self.isEnumObject(b.object)) return 1;
            return null;
        }
        const object_lhs = a == .object;
        if (!object_lhs and b != .object) return null;
        const obj = if (object_lhs) a.object else b.object;
        const other = if (object_lhs) b else a;
        const sign: i64 = if (object_lhs) 1 else -1;
        switch (other) {
            .null, .undef => return sign,
            .bool => {
                const casted: Value = .{ .bool = (Value{ .object = obj }).isTruthy() };
                return if (object_lhs) Value.compare(casted, other) else Value.compare(other, casted);
            },
            .int, .float => {
                if (obj.native.kind != .none) return null;
                const msg = try std.fmt.allocPrint(self.allocator, "Object of class {s} could not be converted to {s}", .{ obj.class_name, if (other == .int) "int" else "float" });
                defer self.allocator.free(msg);
                try self.raiseError(8, msg);
                const casted: Value = if (other == .int) .{ .int = 1 } else .{ .float = 1.0 };
                return if (object_lhs) Value.compare(casted, other) else Value.compare(other, casted);
            },
            .array => return if (obj.native.kind != .none) null else sign,
            .string => return if (obj.native.kind != .none or self.hasMethod(obj.class_name, "__toString")) null else sign,
            else => return null,
        }
    }

    fn isEnumObject(_: *VM, obj: *PhpObject) bool {
        return obj.enum_case;
    }

    fn compareWithStringableInner(self: *VM, a: Value, b: Value) RuntimeError!i64 {
        if (try self.objectBinop(.compare, a, b)) |r| return r.int;
        if (try self.compareObjectOperands(a, b)) |order| return order;
        if (a == .object and b == .string) {
            if (self.hasMethod(a.object.class_name, "__toString")) {
                const s = try self.callMethod(a.object, "__toString", &.{});
                if (s == .string) return Value.compare(s, b);
            }
        } else if (b == .object and a == .string) {
            if (self.hasMethod(b.object.class_name, "__toString")) {
                const s = try self.callMethod(b.object, "__toString", &.{});
                if (s == .string) return Value.compare(a, s);
            }
        }
        return Value.compare(a, b);
    }

    // PHP's == between an object with __toString and a scalar string runs
    // __toString and compares as strings. Value.equal can't reach into the VM
    // to call methods, so this wrapper does that coercion before delegating
    pub fn looseEqualWithStringable(self: *VM, a: Value, b: Value) RuntimeError!bool {
        value_mod.hooks().compare_failure = .none;
        const same = try self.looseEqualWithStringableInner(a, b);
        try self.raiseCompareFailure();
        return same;
    }

    fn looseEqualWithStringableInner(self: *VM, a: Value, b: Value) RuntimeError!bool {
        if (try self.objectBinop(.compare, a, b)) |r| return r.int == 0;
        if (try self.compareObjectOperands(a, b)) |order| return order == 0;
        if (a == .object and b == .string) {
            if (self.hasMethod(a.object.class_name, "__toString")) {
                const s = try self.callMethod(a.object, "__toString", &.{});
                if (s == .string) return Value.equal(s, b);
            }
        } else if (b == .object and a == .string) {
            if (self.hasMethod(b.object.class_name, "__toString")) {
                const s = try self.callMethod(b.object, "__toString", &.{});
                if (s == .string) return Value.equal(a, s);
            }
        }
        return Value.equal(a, b);
    }

    // the spelling a class, interface, or trait was declared with, for a name
    // written in any case. a name nothing declares (yet) comes back unchanged
    pub fn declaredClassName(self: *VM, name: []const u8) []const u8 {
        return self.classes.getKey(name) orelse self.interfaces.getKey(name) orelse self.traits.getKey(name) orelse name;
    }

    pub fn isInstanceOf(self: *VM, raw_obj_class: []const u8, raw_target: []const u8) bool {
        if (self.isInstanceOfNamed(raw_obj_class, raw_target)) return true;
        // a class_alias() name is the class it names
        const written_target = if (raw_target.len > 0 and raw_target[0] == '\\') raw_target[1..] else raw_target;
        const canonical = self.classes.aliasTarget(written_target) orelse self.interfaces.aliasTarget(written_target) orelse return false;
        return self.isInstanceOfNamed(raw_obj_class, canonical);
    }

    fn isInstanceOfNamed(self: *VM, raw_obj_class: []const u8, raw_target: []const u8) bool {
        // PHP normalizes leading-backslash equivalence for class names
        const obj_class = if (raw_obj_class.len > 0 and raw_obj_class[0] == '\\') raw_obj_class[1..] else raw_obj_class;
        const target_class = if (raw_target.len > 0 and raw_target[0] == '\\') raw_target[1..] else raw_target;
        if (std.ascii.eqlIgnoreCase(target_class, "Stringable") and self.hasMethod(obj_class, "__toString")) return true;
        var current = obj_class;
        while (true) {
            if (std.ascii.eqlIgnoreCase(current, target_class)) return true;
            // built-in exception hierarchy (always checked, even for registered classes)
            if (builtinExceptionParent(current)) |builtin_parent| {
                if (std.ascii.eqlIgnoreCase(target_class, "Throwable") or
                    std.ascii.eqlIgnoreCase(target_class, "Exception") or
                    std.ascii.eqlIgnoreCase(target_class, "Error"))
                {
                    var bp = builtin_parent;
                    while (true) {
                        if (std.ascii.eqlIgnoreCase(bp, target_class)) return true;
                        bp = builtinExceptionParent(bp) orelse break;
                    }
                }
            }
            if (self.classes.get(current)) |cls| {
                for (cls.interfaces.items) |iface| {
                    if (self.implementsInterface(iface, target_class)) return true;
                }
                if (cls.parent) |p| {
                    current = p;
                    continue;
                }
            }
            return false;
        }
    }

    fn builtinExceptionParent(class_name: []const u8) ?[]const u8 {
        if (std.ascii.eqlIgnoreCase(class_name, "Exception") or std.ascii.eqlIgnoreCase(class_name, "Error")) return "Throwable";
        const date_exception_children = [_][]const u8{
            "DateInvalidTimeZoneException",       "DateInvalidOperationException",
            "DateMalformedStringException",       "DateMalformedIntervalStringException",
            "DateMalformedPeriodStringException",
        };
        for (date_exception_children) |name| {
            if (std.ascii.eqlIgnoreCase(class_name, name)) return "DateException";
        }
        if (std.ascii.eqlIgnoreCase(class_name, "DateException")) return "Exception";
        const date_error_children = [_][]const u8{
            "DateObjectError", "DateRangeError",
        };
        for (date_error_children) |name| {
            if (std.ascii.eqlIgnoreCase(class_name, name)) return "DateError";
        }
        if (std.ascii.eqlIgnoreCase(class_name, "DateError")) return "Error";
        if (std.ascii.eqlIgnoreCase(class_name, "SodiumException")) return "Exception";
        const exception_children = [_][]const u8{
            "RuntimeException",       "LogicException",           "InvalidArgumentException",
            "BadMethodCallException", "BadFunctionCallException", "OutOfRangeException",
            "OverflowException",      "UnderflowException",       "LengthException",
            "DomainException",        "RangeException",           "UnexpectedValueException",
            "JsonException",          "PDOException",             "ClosedGeneratorException",
        };
        for (exception_children) |name| {
            if (std.ascii.eqlIgnoreCase(class_name, name)) return "Exception";
        }
        const error_children = [_][]const u8{
            "TypeError",           "ValueError",          "ArithmeticError",
            "DivisionByZeroError", "UnhandledMatchError", "FiberError",
            "ParseError",          "CompileError",
        };
        for (error_children) |name| {
            if (std.ascii.eqlIgnoreCase(class_name, name)) return "Error";
        }
        return null;
    }

    fn checkConstVisibility(self: *VM, class_name: []const u8, const_name: []const u8) RuntimeError!bool {
        var current: ?[]const u8 = class_name;
        var declaring: []const u8 = class_name;
        var vis: ClassDef.Visibility = .public;
        while (current) |cn| {
            if (self.classes.get(cn)) |cls| {
                if (cls.const_visibility.get(const_name)) |v| {
                    declaring = cn;
                    vis = v;
                    break;
                }
                if (cls.constants.contains(const_name)) {
                    declaring = cn;
                    vis = .public;
                    break;
                }
                current = cls.parent;
            } else break;
        }
        if (vis == .public) return true;
        if (self.checkVisibility(declaring, vis)) return true;
        const msg = try std.fmt.allocPrint(self.allocator, "Cannot access {s} const {s}::{s}", .{ @tagName(vis), declaring, const_name });
        defer self.allocator.free(msg);
        _ = try self.throwBuiltinException("Error", msg);
        return false;
    }

    fn visScopeSuffix(self: *VM) []const u8 {
        // php's "from global scope" / "from scope X" suffix for visibility
        // errors (zend_bad_method_call): X is the executing scope
        const caller = if (self.frame_count > 0)
            self.currentDefiningClass() orelse self.frames[self.frame_count - 1].called_class
        else
            null;
        if (caller) |c| {
            const s = std.fmt.allocPrint(self.allocator, " from scope {s}", .{c}) catch return " from global scope";
            defer self.allocator.free(s);
            return self.internName(s) catch " from global scope";
        }
        return " from global scope";
    }

    // php's zend_check_protected(zend_get_function_root_class(fbc), scope):
    // a protected method overriding an ancestor's is callable from wherever
    // the topmost ancestor declaring it is
    fn protectedRootVisible(self: *VM, defining: []const u8, method: []const u8, vis: ClassDef.Visibility) bool {
        if (vis != .protected) return false;
        var root = defining;
        var current = if (self.classes.getPtr(defining)) |d| d.parent else null;
        while (current) |name| {
            const cls = self.classes.getPtr(name) orelse break;
            if (cls.methods.get(method)) |info| {
                if (info.visibility == .private) break;
                root = cls.name;
            }
            current = cls.parent;
        }
        if (root.ptr == defining.ptr) return false;
        return self.checkVisibility(root, vis);
    }

    // php checks a protected property against the class that first declared
    // it (property_info->prototype->ce with is_protected_compatible_scope),
    // so classes under a common declaring ancestor reach each other's
    pub fn propVisible(self: *VM, vr: VisResult, name: []const u8, vis: ClassDef.Visibility) bool {
        if (self.checkVisibility(vr.defining_class, vis)) return true;
        if (vis != .protected) return false;
        const root = self.propertyRootClass(vr.defining_class, name) orelse return false;
        return self.checkVisibility(root, vis);
    }

    // the topmost ancestor whose declaration of the property the given
    // class's overrides (a private one starts a new chain), or null
    fn propertyRootClass(self: *VM, defining: []const u8, name: []const u8) ?[]const u8 {
        var root: ?[]const u8 = null;
        var current = if (self.classes.getPtr(defining)) |d| d.parent else null;
        while (current) |cn| {
            const cls = self.classes.getPtr(cn) orelse break;
            for (cls.properties.items) |p| {
                if (!std.mem.eql(u8, p.name, name)) continue;
                if (p.visibility == .private) return root;
                root = cls.name;
                break;
            }
            current = cls.parent;
        }
        return root;
    }

    pub fn checkVisibility(self: *VM, target_class: []const u8, vis: ClassDef.Visibility) bool {
        if (vis == .public) return true;
        // a running closure sees what its scope sees, never what the class
        // it was called through or bound $this to does
        if (self.frame_count > 0) {
            const top = &self.frames[self.frame_count - 1];
            if (top.func) |func| if (std.mem.startsWith(u8, func.name, "__closure_")) {
                const scope = self.closureDefClassForFrame(top) orelse return false;
                if (vis == .private) return std.mem.eql(u8, scope, target_class);
                return self.isInstanceOf(scope, target_class) or self.isInstanceOf(target_class, scope);
            };
        }
        if (vis == .private) {
            // for private, check defining class first so parent::__construct()
            // can access its own private properties
            const defining = self.currentDefiningClass();
            if (defining) |dc| {
                if (std.mem.eql(u8, dc, target_class)) return true;
            }
            const caller_class = self.currentFrame().called_class orelse defining orelse return false;
            return std.mem.eql(u8, caller_class, target_class);
        }
        // protected: caller must be same class or in inheritance chain
        const caller_class = self.currentFrame().called_class orelse self.currentDefiningClass() orelse return false;
        return self.isInstanceOf(caller_class, target_class) or self.isInstanceOf(target_class, caller_class);
    }

    // a `??` read of a property that isn't there for the scope, as php's
    // read_property with BP_VAR_IS: __isset decides (unless it is running
    // for this property), then __get gives the value. with only __get and it
    // already running, an inaccessible property is an access error
    fn coalesceMagic(self: *VM, obj: *PhpObject, name: []const u8, inaccessible: bool) RuntimeError!Value {
        if (self.hasMethod(obj.class_name, "__isset")) {
            if (!self.magicGuarded(obj, name, .isset)) {
                const present = try self.callMagicProperty(obj, .isset, name, .null);
                if (!present.isTruthy()) return .null;
            }
            if (self.magicApplies(obj, name, .get)) return self.callMagicGet(obj, name);
            return .null;
        }
        if (self.hasMethod(obj.class_name, "__get")) {
            if (!self.magicGuarded(obj, name, .get)) return self.callMagicGet(obj, name);
            if (inaccessible) {
                if (try self.accessDeniedMessage(obj, name)) |msg| {
                    defer self.allocator.free(msg);
                    try self.setPendingException("Error", msg);
                    return error.RuntimeError;
                }
            }
        }
        return .null;
    }

    // an access the magic methods don't take: a property the scope can't
    // reach, or a name no property can have, is an Error. true when it was
    // raised and dispatched
    fn propertyAccessDenied(self: *VM, obj: *PhpObject, name: []const u8) RuntimeError!bool {
        const msg = try self.accessDeniedMessage(obj, name) orelse return false;
        defer self.allocator.free(msg);
        if (try self.throwBuiltinException("Error", msg)) return true;
        return error.RuntimeError;
    }

    fn accessDeniedMessage(self: *VM, obj: *PhpObject, name: []const u8) RuntimeError!?[]u8 {
        if (badPropertyName(name)) return try self.allocator.dupe(u8, bad_property_name_message);
        const vr = self.findPropertyVisibility(obj.class_name, name);
        if (!vr.declared or self.propVisible(vr, name, vr.visibility)) return null;
        return try std.fmt.allocPrint(self.allocator, "Cannot access {s} property {s}::${s}", .{ @tagName(vr.visibility), obj.class_name, name });
    }

    fn shouldCallMagicUnset(self: *VM, obj: *PhpObject, name: []const u8) bool {
        if (!self.magicApplies(obj, name, .unset)) return false;
        const vr = self.findPropertyVisibility(obj.class_name, name);
        return obj.isUnset(name) or !self.propVisible(vr, name, vr.visibility) or
            (obj.getSlotIndex(name) == null and !obj.properties.contains(name));
    }

    // Property write, reference and dimension handlers share a set-scope gate.
    // Object interiors are
    // reads of the property, not mutations of its storage (callers skip this
    // gate when a dimension operation resolves to an object).
    // reinit is clone-with's write: a readonly property may be written again
    // by a scope its set visibility allows
    const MutationAction = enum { write, indirect, unset, reinit };

    const PropWriteStep = enum { proceed, stored, dispatched };
    const PropWriteGate = struct { step: PropWriteStep, obj: *PhpObject = undefined, vr: VisResult = undefined };

    // what a property write does before the store: lazy initialization, the
    // set-scope gate, and property hooks. stored: a set hook took the value.
    // dispatched: an exception was raised and dispatched, and the run loop
    // continues at its handler
    fn propertyWriteGate(self: *VM, obj_in: *PhpObject, prop_name: []const u8, val: Value, action: MutationAction, base_frame: usize) RuntimeError!PropWriteGate {
        // zend_std_write_property runs a set hook or __set before a lazy
        // object is initialized: only a write to its storage initializes it
        const lazy_deferred = obj_in.lazy != null and
            ((self.hasPropHook(obj_in.class_name, prop_name, .set) and !self.inPropHook(obj_in, prop_name)) or
                self.lazyMagicFirst(obj_in, prop_name, .set));
        if (!lazy_deferred) self.triggerLazyAccess(obj_in, prop_name) catch {
            if (self.pending_exception != null and self.dispatchPendingException(base_frame)) return .{ .step = .dispatched };
            return error.RuntimeError;
        };
        const obj = obj_in.storage();

        // the set-scope gate runs before hooks and __set, but only an
        // asymmetric or readonly declaration can ever deny a write
        const vr = self.findPropertyVisibility(obj.class_name, prop_name);
        if (vr.is_readonly or vr.set_visibility != vr.visibility) {
            if (!(obj.isUnset(prop_name) and self.magicApplies(obj, prop_name, .set))) {
                if (try self.checkPropertyMutationVis(obj, prop_name, action, vr)) return .{ .step = .dispatched };
            }
        }

        // property hooks: dispatch to the set hook if present (and not
        // recursing). an exception thrown inside the hook dispatches back into
        // the caller's try/catch instead of bubbling out of runLoop
        if (self.hasPropHook(obj.class_name, prop_name, .set) and !self.inPropHook(obj, prop_name)) {
            const hook_result = self.callPropHook(obj, prop_name, .set, val) catch {
                if (self.pending_exception != null and self.dispatchPendingException(base_frame)) return .{ .step = .dispatched };
                return error.RuntimeError;
            };
            if (hook_result != null) return .{ .step = .stored, .obj = obj, .vr = vr };
        } else if (self.hasPropHook(obj.class_name, prop_name, .get) and !self.inPropHook(obj, prop_name)) {
            // get hook exists but no set hook. PHP allows the write when the
            // property is "backed" (a default was declared, in which case
            // there's storage to write to). purely virtual properties with no
            // default are read-only
            // a hooked property is backed when a hook uses $this->prop
            const backed = blk: {
                var current: ?[]const u8 = obj.class_name;
                while (current) |cn| {
                    if (self.classes.get(cn)) |cls_def| {
                        for (cls_def.properties.items) |p| {
                            if (std.mem.eql(u8, p.name, prop_name)) break :blk !p.is_virtual or p.has_default;
                        }
                        current = cls_def.parent;
                    } else break;
                }
                break :blk false;
            };
            if (!backed) {
                const msg = std.fmt.allocPrint(self.allocator, "Property {s}::${s} is read-only", .{ obj.class_name, prop_name }) catch return error.RuntimeError;
                defer self.allocator.free(msg);
                if (try self.throwBuiltinException("Error", msg)) return .{ .step = .dispatched };
                return error.RuntimeError;
            }
            // fall through to the regular slot/property write
        }
        return .{ .step = .proceed, .obj = obj, .vr = vr };
    }

    const PropWriteOutcome = enum { written, magic, dispatched };

    pub fn classDeclaresProperty(self: *VM, class_name: []const u8, name: []const u8) bool {
        var current: ?[]const u8 = class_name;
        while (current) |cn| {
            const cls = self.classes.getPtr(cn) orelse return false;
            for (cls.properties.items) |prop| if (std.mem.eql(u8, prop.name, name)) return true;
            current = cls.parent;
        }
        return false;
    }

    pub const DynamicPropertyRule = enum { allowed, deprecated, forbidden };

    // what php does when a write creates a property no class in the object's
    // chain declares: a readonly class (or one that forbids it) refuses,
    // stdClass or #[\AllowDynamicProperties] in the chain allows it, and
    // anything else is deprecated (php 8.2)
    pub const StaticAsInstance = enum { none, noticed, denied };

    // zend_get_property_offset for a name whose nearest declaration in the
    // object's chain is a static property: one the scope can see is no
    // instance property, so php notices (unless silent) and goes on with a
    // dynamic one; a protected or private one it can't see is php's access
    // error (raised unless silent), and an ancestor's private one is just a
    // dynamic name. silent is php's: the class has the magic method the
    // access would fall back to, or the access is isset/`??`
    fn staticAsInstance(self: *VM, obj: *const PhpObject, name: []const u8, silent: bool) RuntimeError!StaticAsInstance {
        var current: ?[]const u8 = obj.class_name;
        const cls = while (current) |cn| {
            const c = self.classes.getPtr(cn) orelse return .none;
            if (c.static_props.count() > 0 and c.static_props.contains(name)) break c;
            for (c.properties.items) |prop| if (std.mem.eql(u8, prop.name, name)) return .none;
            current = c.parent;
        } else return .none;
        const declaring = cls.name;
        const vis = cls.static_prop_visibility.get(name) orelse .public;
        const scope = self.currentDefiningClass();
        const visible = switch (vis) {
            .public => true,
            .private => if (scope) |sc| std.ascii.eqlIgnoreCase(sc, declaring) else false,
            .protected => if (scope) |sc| self.isInstanceOf(sc, declaring) or self.isInstanceOf(declaring, sc) else false,
        };
        // zend_get_parent_private_property: the scope's own private static
        // of the name, on an object of a subclass, is the one meant
        const scope_private = if (!visible) if (scope) |sc| blk: {
            const scls = self.classes.getPtr(sc) orelse break :blk false;
            break :blk (scls.static_prop_visibility.get(name) orelse .public) == .private and scls.static_props.contains(name) and self.isInstanceOf(obj.class_name, sc);
        } else false else false;
        if (!visible and !scope_private) {
            // a private static of an ancestor is not this class's: dynamic
            if (vis == .private and !std.ascii.eqlIgnoreCase(declaring, obj.class_name)) return .none;
            if (!silent) {
                const msg = try std.fmt.allocPrint(self.allocator, "Cannot access {s} property {s}::${s}", .{ @tagName(vis), obj.class_name, name });
                defer self.allocator.free(msg);
                // dispatched to a handler, or uncaught
                if (!try self.throwBuiltinException("Error", msg)) return error.RuntimeError;
            }
            return .denied;
        }
        if (!silent) {
            const msg = try std.fmt.allocPrint(self.allocator, "Accessing static property {s}::${s} as non static", .{ obj.class_name, name });
            defer self.allocator.free(msg);
            try self.raiseError(8, msg);
        }
        return .noticed;
    }

    pub fn dynamicPropertyRule(self: *VM, obj: *const PhpObject) DynamicPropertyRule {
        var current: ?[]const u8 = obj.class_name;
        while (current) |cn| {
            if (std.ascii.eqlIgnoreCase(cn, "stdClass")) return .allowed;
            const cls = self.classes.getPtr(cn) orelse return .allowed;
            if (cls.is_readonly or cls.no_dynamic_properties) return .forbidden;
            for (cls.attributes.items) |attr| {
                const attr_name = if (attr.name.len > 0 and attr.name[0] == '\\') attr.name[1..] else attr.name;
                if (std.ascii.eqlIgnoreCase(attr_name, "AllowDynamicProperties")) return .allowed;
            }
            current = cls.parent;
        }
        return .deprecated;
    }

    // raises what dynamicPropertyRule asks for, from the run loop. returns
    // true when an exception was raised and dispatched
    fn checkDynamicProperty(self: *VM, obj: *PhpObject, name: []const u8) RuntimeError!bool {
        const kind = self.staticAsInstance(obj, name, false) catch {
            _ = try self.resumeRaised();
            return true;
        };
        if (kind == .denied) return true;
        return self.checkDynamicPropertyRule(obj, name);
    }

    fn checkDynamicPropertyRule(self: *VM, obj: *PhpObject, name: []const u8) RuntimeError!bool {
        switch (self.dynamicPropertyRule(obj)) {
            .allowed => return false,
            .forbidden => {
                const msg = try std.fmt.allocPrint(self.allocator, "Cannot create dynamic property {s}::${s}", .{ obj.class_name, name });
                defer self.allocator.free(msg);
                if (try self.throwBuiltinException("Error", msg)) return true;
                return error.RuntimeError;
            },
            .deprecated => {
                const msg = try std.fmt.allocPrint(self.allocator, "Creation of dynamic property {s}::${s} is deprecated", .{ obj.class_name, name });
                defer self.allocator.free(msg);
                self.raiseError(E_DEPRECATED, msg) catch {
                    _ = try self.resumeRaised();
                    return true;
                };
                return false;
            },
        }
    }

    // the store of a property write that passed its gate: __set for a missing
    // or inaccessible property, else the visibility, readonly, and type checks
    // and the write itself. val may be coerced to the declared type
    fn propertyWriteStore(self: *VM, obj: *PhpObject, prop_name: []const u8, val: *Value, vr: VisResult, action: MutationAction, base_frame: usize) RuntimeError!PropWriteOutcome {
        // a readonly property is written again only through a reinit window
        // (__clone, clone()'s properties), whatever the action
        _ = action;
        if (!vr.declared) {
            const silent = self.hasMethod(obj.class_name, "__set");
            const kind = self.staticAsInstance(obj, prop_name, silent) catch {
                _ = try self.resumeRaised();
                return .dispatched;
            };
            if (kind == .denied) {
                // raised already, or __set is guarded: raise it now
                if (!silent or !self.magicApplies(obj, prop_name, .set)) {
                    if (silent) _ = self.staticAsInstance(obj, prop_name, false) catch {
                        _ = try self.resumeRaised();
                        return .dispatched;
                    };
                    return .dispatched;
                }
                _ = (implicit_call: { const handlers_before = self.handler_count; break :implicit_call self.callMagicProperty(obj, .set, prop_name, val.*) catch { if (self.resumeAfterThrow(base_frame, handlers_before)) return .dispatched; return error.RuntimeError; }; });
                return .magic;
            }
        }
        const has_prop = !obj.isUnset(prop_name) and (obj.properties.contains(prop_name) or (obj.slots != null and obj.getSlotIndexForScope(prop_name, vr.defining_class) != null));
        if (!has_prop and self.magicApplies(obj, prop_name, .set)) {
            _ = (implicit_call: { const handlers_before = self.handler_count; break :implicit_call self.callMagicProperty(obj, .set, prop_name, val.*) catch { if (self.resumeAfterThrow(base_frame, handlers_before)) return .dispatched; return error.RuntimeError; }; });
            return .magic;
        }
        if (!self.propVisible(vr, prop_name, vr.visibility)) {
            if (self.magicApplies(obj, prop_name, .set)) {
                _ = (implicit_call: { const handlers_before = self.handler_count; break :implicit_call self.callMagicProperty(obj, .set, prop_name, val.*) catch { if (self.resumeAfterThrow(base_frame, handlers_before)) return .dispatched; return error.RuntimeError; }; });
                return .magic;
            }
            const msg = try std.fmt.allocPrint(self.allocator, "Cannot access {s} property {s}::${s}", .{
                @tagName(vr.visibility), obj.class_name, prop_name,
            });
            defer self.allocator.free(msg);
            if (try self.throwBuiltinException("Error", msg)) return .dispatched;
            return error.RuntimeError;
        }
        const sp_scope: ?[]const u8 = vr.defining_class;
        const reinit = vr.is_readonly and self.reinit_windows.items.len > 0 and self.readonlyReinitable(obj, prop_name);
        if (vr.is_readonly and !reinit) {
            const existing = obj.getForScope(prop_name, sp_scope);
            if (existing != .null) {
                const msg = try std.fmt.allocPrint(self.allocator, "Cannot modify readonly property {s}::${s}", .{
                    vr.defining_class, prop_name,
                });
                defer self.allocator.free(msg);
                if (try self.throwBuiltinException("Error", msg)) return .dispatched;
                return error.RuntimeError;
            }
        }
        if (!has_prop and !vr.declared) {
            if (badPropertyName(prop_name)) {
                if (try self.throwBuiltinException("Error", bad_property_name_message)) return .dispatched;
                return error.RuntimeError;
            }
            if (try self.checkDynamicPropertyRule(obj, prop_name)) return .dispatched;
        }
        // typed property: coerce/enforce the declared type before storing
        // (matches PHP weak/strict mode)
        if (obj.ref_mirrored and val.* == .float) val.* = try self.checkTypedPropStep(obj, prop_name, val.*);
        if (vr.type_str.len > 0) {
            if (try self.checkPropertyType(val, vr.type_str, vr.defining_class, prop_name)) return .dispatched;
        }
        if (obj.ref_mirrored) val.* = try self.checkTypedPropWrite(obj, prop_name, val.*);
        // overwrite-release: drop the object the property previously held
        // before the new value lands (Stage 1)
        try obj.setForScope(self.allocator, prop_name, val.*, sp_scope);
        self.syncObjPropRefs(obj, prop_name, val.*);
        if (reinit) self.consumeReinit(obj, prop_name);
        return .written;
    }

    fn checkPropertyMutation(self: *VM, obj: *PhpObject, name: []const u8, action: MutationAction) RuntimeError!bool {
        return self.checkPropertyMutationVis(obj, name, action, self.findPropertyVisibility(obj.class_name, name));
    }

    // DatePeriod's virtual properties have handlers of their own
    // (date_period_write_property and friends) that refuse every change
    fn datePeriodField(vr: VisResult, name: []const u8) bool {
        if (!std.mem.eql(u8, vr.defining_class, "DatePeriod")) return false;
        for ([_][]const u8{ "start", "current", "end", "interval", "recurrences", "include_start_date", "include_end_date" }) |f| {
            if (std.mem.eql(u8, name, f)) return true;
        }
        return false;
    }

    fn checkPropertyMutationVis(self: *VM, obj: *PhpObject, name: []const u8, action: MutationAction, vr: VisResult) RuntimeError!bool {
        var msg: ?[]const u8 = null;
        if (datePeriodField(vr, name)) {
            msg = if (action == .unset)
                try std.fmt.allocPrint(self.allocator, "Cannot unset {s}::${s}", .{ self.declaredClassName(obj.class_name), name })
            else
                try std.fmt.allocPrint(self.allocator, "Cannot modify readonly property DatePeriod::${s}", .{name});
        } else if (action == .write and vr.is_readonly and obj.rawForScope(name, vr.defining_class) != .undef and !obj.isUnset(name) and !(self.reinit_windows.items.len > 0 and self.readonlyReinitable(obj, name))) {
            // zend_std_write_property: an initialized readonly property is
            // refused before its set visibility is
            msg = try std.fmt.allocPrint(self.allocator, "Cannot modify readonly property {s}::${s}", .{ vr.defining_class, name });
        } else if (action == .unset and vr.is_readonly and self.reinit_windows.items.len > 0 and self.readonlyReinitable(obj, name)) {
            // __clone may unset a readonly property once
            self.consumeReinit(obj, name);
        } else if (action == .unset and vr.is_readonly and obj.rawForScope(name, vr.defining_class) != .undef) {
            msg = try std.fmt.allocPrint(self.allocator, "Cannot unset readonly property {s}::${s}", .{ vr.defining_class, name });
        } else if (action == .indirect and vr.is_readonly and self.propVisible(vr, name, vr.visibility)) {
            // zend_std_read_property for writing: a readonly property is never
            // modified in place, whatever the scope
            msg = try std.fmt.allocPrint(self.allocator, "Cannot indirectly modify readonly property {s}::${s}", .{ vr.defining_class, name });
        } else if (vr.set_visibility != vr.visibility and !self.propVisible(vr, name, vr.set_visibility)) {
            const verb: []const u8 = switch (action) {
                .write => "modify",
                .indirect => "indirectly modify",
                .unset => "unset",
                .reinit => "modify",
            };
            const ro: []const u8 = if (vr.is_readonly and vr.set_visibility == .protected) " readonly" else "";
            const scope = self.currentDefiningClass();
            msg = if (scope) |sc|
                try std.fmt.allocPrint(self.allocator, "Cannot {s} {s}(set){s} property {s}::${s} from scope {s}", .{ verb, @tagName(vr.set_visibility), ro, vr.defining_class, name, sc })
            else
                try std.fmt.allocPrint(self.allocator, "Cannot {s} {s}(set){s} property {s}::${s} from global scope", .{ verb, @tagName(vr.set_visibility), ro, vr.defining_class, name });
        } else if (action == .indirect and !self.propVisible(vr, name, vr.visibility)) {
            msg = try std.fmt.allocPrint(self.allocator, "Cannot access {s} property {s}::${s}", .{ @tagName(vr.visibility), obj.class_name, name });
        } else if (action == .indirect and vr.is_readonly) {
            msg = try std.fmt.allocPrint(self.allocator, "Cannot indirectly modify readonly property {s}::${s}", .{ vr.defining_class, name });
        }
        if (msg) |text| {
            defer self.allocator.free(text);
            if (try self.throwBuiltinException("Error", text)) return true;
            return error.RuntimeError;
        }
        return false;
    }

    // declared is false for a name no class declares, or one only an
    // ancestor declares private where the running scope can't see it
    pub const VisResult = struct { visibility: ClassDef.Visibility, defining_class: []const u8, is_readonly: bool = false, set_visibility: ClassDef.Visibility = .public, type_str: []const u8 = "", declared: bool = true, changed: bool = false };

    pub fn findPropertyVisibility(self: *VM, class_name: []const u8, prop_name: []const u8) VisResult {
        // PHP rule for private properties: each declaring class gets its own
        // slot. When `$this->prop` is read from inside a method of class S,
        // S's own private declaration of `prop` (if any) is preferred. the
        // scope is the METHOD's declaring class (currentDefiningClass), NOT
        // the dynamic called_class - parent::__construct() running on a
        // child object must see the parent's privates, not the child's.
        // we only consult scope when looking for a private prop - the
        // non-private hierarchy walk below is independent of scope. a scope's
        // private can only apply when the chain declares a private of that name
        const scope = if (self.chainDeclaresPrivateProp(class_name, prop_name)) self.currentDefiningClass() else null;
        if (scope) |sc| {
            // the scope's private prop only lives on this object if the object's
            // class IS the scope or descends from it. without this guard, code
            // running inside C::method() that reads $unrelated->p would wrongly
            // pick up C's private $p (wrong type/visibility) for an object whose
            // class has nothing to do with C - e.g. Command::__construct reading
            // an AsCommand attribute's public ?string $help resolved to
            // Command's private string $help and falsely threw "uninitialized"
            if (self.isInstanceOf(class_name, sc)) {
                if (self.classes.get(sc)) |scls| {
                    for (scls.properties.items) |prop| {
                        if (std.mem.eql(u8, prop.name, prop_name) and prop.visibility == .private) {
                            return .{ .visibility = prop.visibility, .defining_class = sc, .is_readonly = prop.is_readonly, .set_visibility = if (prop.is_readonly and !prop.has_set_visibility and prop.visibility == .public) .protected else prop.set_visibility, .type_str = prop.type_str };
                        }
                    }
                }
            }
        }
        const declared = self.propertyDeclaration(class_name, prop_name);
        // an ancestor's private property is invisible everywhere but in that
        // ancestor: php treats the name as undeclared, so a write makes a
        // dynamic property beside it (zend_get_property_offset)
        if (declared.visibility == .private and !std.mem.eql(u8, declared.defining_class, class_name)) {
            const in_scope = if (scope) |sc| std.mem.eql(u8, sc, declared.defining_class) else false;
            if (!in_scope) return .{ .visibility = .public, .defining_class = class_name, .declared = false };
        }
        return declared;
    }

    // the declaration a property name resolves to in a class chain, nearest
    // first, regardless of who is asking
    pub fn propertyDeclaration(self: *VM, class_name: []const u8, prop_name: []const u8) VisResult {
        var current: ?[]const u8 = class_name;
        while (current) |cn| {
            if (self.classes.get(cn)) |cls| {
                for (cls.properties.items) |prop| {
                    if (std.mem.eql(u8, prop.name, prop_name)) return .{ .visibility = prop.visibility, .defining_class = cn, .is_readonly = prop.is_readonly, .set_visibility = if (prop.is_readonly and !prop.has_set_visibility and prop.visibility == .public) .protected else prop.set_visibility, .type_str = prop.type_str };
                }
                current = cls.parent;
            } else break;
        }
        return .{ .visibility = .public, .defining_class = class_name, .declared = false };
    }

    fn chainDeclaresPrivateProp(self: *VM, class_name: []const u8, prop_name: []const u8) bool {
        var current: ?[]const u8 = if (class_name.len > 0 and class_name[0] == '\\') class_name[1..] else class_name;
        while (current) |cn| {
            const cls = self.classes.get(cn) orelse return false;
            for (cls.properties.items) |prop| {
                if (prop.visibility == .private and std.mem.eql(u8, prop.name, prop_name)) return true;
            }
            current = cls.parent;
        }
        return false;
    }

    // zend_get_parent_private_method: when the executing scope declares a
    // private method of that name and the object is an instance of it, a
    // call through the object runs the scope's method, not the subclass's.
    // the method's registered "Class::method", or null
    fn scopePrivateMethod(self: *VM, class_name: []const u8, method_name: []const u8, found_in: []const u8) ?[]const u8 {
        const scope = self.currentDefiningClass() orelse return null;
        if (std.ascii.eqlIgnoreCase(scope, found_in)) return null;
        const entry = self.classes.getEntry(scope) orelse return null;
        const info = entry.value_ptr.methods.get(method_name) orelse return null;
        if (info.visibility != .private) return null;
        if (!self.isInstanceOf(class_name, scope)) return null;
        return self.resolveMethod(entry.key_ptr.*, method_name) catch null;
    }

    pub fn findMethodVisibility(self: *VM, class_name: []const u8, method_name: []const u8) VisResult {
        var current: ?[]const u8 = class_name;
        while (current) |cn| {
            if (self.classes.getEntry(cn)) |entry| {
                const cls = entry.value_ptr;
                if (cls.methods.get(method_name)) |info| return .{ .visibility = info.visibility, .defining_class = entry.key_ptr.*, .changed = info.changed };
                current = cls.parent;
            } else break;
        }
        return .{ .visibility = .public, .defining_class = class_name };
    }

    fn implementsInterface(self: *VM, iface_name: []const u8, target: []const u8) bool {
        if (std.ascii.eqlIgnoreCase(iface_name, target)) return true;
        if (self.interfaces.get(iface_name)) |idef| {
            // walk every extended interface (PHP allows multi-extension)
            for (idef.parents.items) |p| {
                if (self.implementsInterface(p, target)) return true;
            }
            // legacy single-parent field for older code paths that haven't been
            // converted to push into 'parents' yet
            if (idef.parent) |p| {
                var seen_in_parents = false;
                for (idef.parents.items) |pp| if (std.ascii.eqlIgnoreCase(pp, p)) {
                    seen_in_parents = true;
                    break;
                };
                if (!seen_in_parents and self.implementsInterface(p, target)) return true;
            }
            return false;
        }
        // not registered as an interface - try autoload then fall back to
        // walking a class's implemented-interface list (for class-as-iface refs)
        // instanceof never throws, so an autoloader's exception goes nowhere
        if (!self.classes.contains(iface_name)) {
            self.tryAutoload(iface_name) catch self.discardPending();
        }
        if (self.interfaces.get(iface_name)) |idef| {
            for (idef.parents.items) |p| if (self.implementsInterface(p, target)) return true;
            if (idef.parent) |p| if (self.implementsInterface(p, target)) return true;
        } else if (self.classes.get(iface_name)) |cls| {
            for (cls.interfaces.items) |parent_iface| {
                if (self.implementsInterface(parent_iface, target)) return true;
            }
        }
        return false;
    }

    fn closureScopeForFrame(self: *VM, frame: *const CallFrame) ?[]const u8 {
        // fast path: only closure frames can return a scope, and a frame is
        // only a closure when its func.name has the __closure_ prefix. this
        // lets the common case (regular method/function frame) return null
        // in O(1) instead of iterating self.functions (can grow large in
        // framework-heavy workloads). for closure frames we still iterate,
        // but those are far less frequent than method calls
        const compile_name = if (frame.func) |fn_| fn_.name else "";
        if (!std.mem.startsWith(u8, compile_name, "__closure_")) return null;
        // the runtime instance name (e.g. "__closure_5_3") is in call_name;
        // capture_index is keyed by instance name
        if (frame.call_name) |inst_name| {
            if (self.capture_index.get(inst_name)) |cr| {
                const caps = self.captures.items[cr.start .. cr.start + cr.len];
                for (caps) |cap| {
                    if (std.mem.eql(u8, cap.var_name, "$__closure_scope") and cap.value == .string)
                        return cap.value.string.bytes();
                }
                return null;
            }
        }
        // fallback - look up compile-time names registered for this chunk
        // (handles older paths that don't set call_name)
        if (self.chunk_to_func_names.get(@intFromPtr(frame.chunk))) |names| {
            for (names.items) |name| {
                if (!std.mem.startsWith(u8, name, "__closure_")) continue;
                if (self.capture_index.get(name)) |cr| {
                    const caps = self.captures.items[cr.start .. cr.start + cr.len];
                    for (caps) |cap| {
                        if (std.mem.eql(u8, cap.var_name, "$__closure_scope") and cap.value == .string)
                            return cap.value.string.bytes();
                    }
                }
            }
        }
        return null;
    }

    pub fn closureScopeByName(self: *VM, name: []const u8) ?[]const u8 {
        if (self.capture_index.get(name)) |cr| {
            const caps = self.captures.items[cr.start .. cr.start + cr.len];
            for (caps) |cap| {
                if (std.mem.eql(u8, cap.var_name, "$__closure_scope") and cap.value == .string)
                    return cap.value.string.bytes();
            }
        }
        return null;
    }

    fn closureDefClassForFrame(self: *VM, frame: *const CallFrame) ?[]const u8 {
        const compile_name = if (frame.func) |fn_| fn_.name else "";
        if (!std.mem.startsWith(u8, compile_name, "__closure_")) return null;
        // the instance's own captures decide: a bind that cleared the scope
        // must not borrow one from another instance of the same closure
        if (frame.call_name) |inst_name| {
            if (self.capture_index.get(inst_name)) |cr| {
                const caps = self.captures.items[cr.start .. cr.start + cr.len];
                for (caps) |cap| {
                    if (std.mem.eql(u8, cap.var_name, "$__closure_defclass") and cap.value == .string)
                        return cap.value.string.bytes();
                }
                return null;
            }
        }
        if (self.chunk_to_func_names.get(@intFromPtr(frame.chunk))) |names| {
            for (names.items) |name| {
                if (!std.mem.startsWith(u8, name, "__closure_")) continue;
                if (self.capture_index.get(name)) |cr| {
                    const caps = self.captures.items[cr.start .. cr.start + cr.len];
                    for (caps) |cap| {
                        if (std.mem.eql(u8, cap.var_name, "$__closure_defclass") and cap.value == .string)
                            return cap.value.string.bytes();
                    }
                }
            }
        }
        return null;
    }

    pub fn closureDefClassByName(self: *VM, name: []const u8) ?[]const u8 {
        if (self.capture_index.get(name)) |cr| {
            const caps = self.captures.items[cr.start .. cr.start + cr.len];
            for (caps) |cap| {
                if (std.mem.eql(u8, cap.var_name, "$__closure_defclass") and cap.value == .string)
                    return cap.value.string.bytes();
            }
        }
        return null;
    }

    pub fn closureThisByName(self: *VM, name: []const u8) Value {
        if (self.capture_index.get(name)) |cr| {
            const caps = self.captures.items[cr.start .. cr.start + cr.len];
            for (caps) |cap| {
                if (std.mem.eql(u8, cap.var_name, "$this")) return cap.value;
            }
        }
        return .null;
    }

    // the current frame evaluates a constant expression (an initializer),
    // where php names classes as the expression wrote them
    fn inInitializer(self: *VM) bool {
        const scopes = self.initializer_scopes.items;
        return scopes.len > 0 and scopes[scopes.len - 1].frame + 1 == self.frame_count;
    }

    fn parentResolvingClass(self: *VM) ?[]const u8 {
        // a class's constant expression, evaluated in the declaring frame
        if (self.initializer_scopes.items.len > 0) {
            const scope = self.initializer_scopes.items[self.initializer_scopes.items.len - 1];
            if (scope.frame + 1 == self.frame_count) return scope.class;
        }
        // a closure's parent:: is its declaring class's parent, wherever it
        // is called from
        if (self.frame_count > 0) {
            const top = &self.frames[self.frame_count - 1];
            if (self.closureDefClassForFrame(top)) |defining| return defining;
            if (self.closureScopeForFrame(top)) |scope| return scope;
        }
        // otherwise like currentDefiningClass, with called_class as the
        // disambiguator for a trait method shared by several classes
        var fi: usize = self.frame_count;
        while (fi > 0) {
            fi -= 1;
            const frame = &self.frames[fi];
            const frame_chunk_ptr = frame.chunk;
            var best: ?[]const u8 = null;
            const disambig: ?[]const u8 = blk: {
                if (frame.func != null and frame.locals.len > 0 and frame.locals[0] == .object)
                    break :blk frame.locals[0].object.class_name;
                const this_val = frame.vars.get("$this") orelse break :blk frame.called_class;
                if (this_val == .object) break :blk this_val.object.class_name;
                break :blk frame.called_class;
            };
            if (self.chunk_to_func_names.get(@intFromPtr(frame_chunk_ptr))) |names| {
                for (names.items) |name| {
                    if (std.mem.indexOf(u8, name, "::")) |sep| {
                        const class_part = name[0..sep];
                        if (self.traits.contains(class_part)) {
                            if (best == null) best = class_part;
                            continue;
                        }
                        if (disambig) |tc| {
                            if (std.mem.eql(u8, class_part, tc))
                                return class_part;
                            if (self.isInstanceOf(tc, class_part)) {
                                if (best) |b| {
                                    if (self.traits.contains(b)) {
                                        best = class_part;
                                    } else if (self.isInstanceOf(b, class_part)) {
                                        best = class_part;
                                    } else if (!self.isInstanceOf(tc, b)) {
                                        best = class_part;
                                    }
                                } else best = class_part;
                            } else if (best == null) {
                                best = class_part;
                            }
                        } else {
                            return class_part;
                        }
                    }
                }
            }
            if (best) |b| return b;
        }
        return null;
    }

    pub fn currentDefiningClass(self: *VM) ?[]const u8 {
        // a class's constant expression, evaluated in the declaring frame
        if (self.initializer_scopes.items.len > 0) {
            const scope = self.initializer_scopes.items[self.initializer_scopes.items.len - 1];
            if (scope.frame + 1 == self.frame_count) return scope.class;
        }
        // bound closure scope takes priority over frame walk
        if (self.frame_count > 0) {
            if (self.closureDefClassForFrame(&self.frames[self.frame_count - 1])) |scope|
                return scope;
            // fall back to $__closure_scope for closures created before the
            if (self.closureScopeForFrame(&self.frames[self.frame_count - 1])) |scope|
                return scope;
        }
        // Includes/native bridge frames can inherit scope, but a PHP function
        // is a lexical boundary: never grant its caller's private access.
        var fi: usize = self.frame_count;
        while (fi > 0) {
            fi -= 1;
            const frame = &self.frames[fi];
            const frame_chunk_ptr = frame.chunk;
            var best: ?[]const u8 = null;
            // when a trait method chunk is shared by multiple classes, use $this
            // to disambiguate which class is actually executing
            const this_class: ?[]const u8 = blk: {
                if (frame.func != null and frame.locals.len > 0 and frame.locals[0] == .object)
                    break :blk frame.locals[0].object.class_name;
                const this_val = frame.vars.get("$this") orelse break :blk null;
                if (this_val == .object) break :blk this_val.object.class_name;
                break :blk null;
            };
            if (self.chunk_to_func_names.get(@intFromPtr(frame_chunk_ptr))) |names| {
                for (names.items) |name| {
                    if (std.mem.indexOf(u8, name, "::")) |sep| {
                        const class_part = name[0..sep];
                        if (self.traits.contains(class_part)) {
                            if (best == null) best = class_part;
                            continue;
                        }
                        if (this_class) |tc| {
                            if (std.mem.eql(u8, class_part, tc))
                                return class_part;
                            if (self.isInstanceOf(tc, class_part)) {
                                if (best) |b| {
                                    // always prefer a non-trait class over a trait
                                    if (self.traits.contains(b)) {
                                        best = class_part;
                                    } else if (self.isInstanceOf(b, class_part)) {
                                        best = class_part;
                                    }
                                } else best = class_part;
                            } else if (best == null) {
                                best = class_part;
                            }
                        } else {
                            return class_part;
                        }
                    }
                }
            }
            if (best) |b| return b;
            if (frame.func != null) return null;
        }
        return null;
    }

    pub fn triggerLazyProperty(self: *VM, obj: *PhpObject, name: []const u8, scope: ?[]const u8) RuntimeError!void {
        if (obj.isLazySlot(name, scope)) try self.triggerLazyInit(obj);
    }

    // resolving the scope walks frames, so skip it for the common eager object
    fn triggerLazyAccess(self: *VM, obj: *PhpObject, name: []const u8) RuntimeError!void {
        if (obj.lazy == null) return;
        // a hooked property's hook runs first; only what it reads or writes
        // of the object initializes it. a backed one without a get hook is
        // read from its storage, which initializes the object
        if (self.propertyHooked(obj.class_name, name) and !self.inPropHook(obj, name) and
            (self.hasRealGetHook(obj.class_name, name) or self.propertyIsVirtual(obj.class_name, name))) return;
        try self.triggerLazyProperty(obj, name, self.currentDefiningClass());
    }

    pub fn triggerLazyInit(self: *VM, obj: *PhpObject) RuntimeError!void {
        const state = obj.lazy orelse return;
        if (state.initializer == .null or state.running) return;
        obj.refcount +%= 1;
        defer self.releaseValue(.{ .object = obj });
        // Retained snapshots force COW for arrays changed by the initializer.
        const slots = obj.slots orelse return;
        const saved = try self.allocator.dupe(Value, slots);
        defer self.allocator.free(saved);
        for (saved) |v| retainValue(v);
        defer for (saved) |v| self.releaseValue(v);
        var props: std.StringArrayHashMapUnmanaged(Value) = .{};
        defer props.deinit(self.allocator);
        defer freeOwnedKeys(self.allocator, &props);
        defer for (props.values()) |v| self.releaseValue(v);
        for (obj.properties.keys(), obj.properties.values()) |name, v| {
            const kept = try self.allocator.dupe(u8, name);
            props.putNoClobber(self.allocator, kept, v) catch |err| {
                self.allocator.free(kept);
                return err;
            };
            retainValue(v);
        }
        var unset: std.StringHashMapUnmanaged(void) = .{};
        defer unset.deinit(self.allocator);
        defer freeOwnedKeys(self.allocator, &unset);
        var unset_names = obj.unset_slots.keyIterator();
        while (unset_names.next()) |name| {
            const kept = try self.allocator.dupe(u8, name.*);
            unset.putNoClobber(self.allocator, kept, {}) catch |err| {
                self.allocator.free(kept);
                return err;
            };
        }
        state.running = true;
        defer state.running = false;
        var ctx = self.makeContext(null);
        // a failed ghost initializer's changes are reverted
        // (zend_lazy_object_revert_init); a proxy keeps what its factory did,
        // its properties still lazy but listed with what it wrote
        errdefer if (state.proxy) record: {
            const written = state.written orelse (self.allocator.alloc(bool, state.pending.len) catch break :record);
            if (state.written == null) {
                @memset(written, false);
                state.written = written;
            }
            for (slots, saved, 0..) |slot, v, i| {
                if (i < written.len and !Value.identical(v, slot)) written[i] = true;
            }
        } else {
            for (slots, saved, 0..) |*slot, v, i| {
                if (self.ref_index) |ri| {
                    if (obj.slot_layout) |layout| {
                        if (ri.prop_rev.contains(.{ .object = obj, .class_name = "", .prop_name = layout.names[i] })) continue;
                    }
                }
                self.releaseValue(slot.*);
                retainValue(v);
                slot.* = v;
            }
            for (obj.properties.values()) |v| self.releaseValue(v);
            obj.clearProperties(self.allocator);
            for (props.keys(), props.values()) |name, v| {
                retainValue(v);
                obj.putProperty(self.allocator, name, v) catch self.releaseValue(v);
            }
            var restored = unset.keyIterator();
            while (restored.next()) |name| obj.markUnset(self.allocator, name.*) catch {};
        };
        if (state.proxy) {
            const result = try ctx.invokeCallable(state.initializer, &.{.{ .object = obj }});
            if (result != .object) {
                const kind: []const u8 = switch (result) {
                    .null => "null",
                    .int => "int",
                    .bool => "bool",
                    .float => "float",
                    .string => "string",
                    .array => "array",
                    else => "object",
                };
                const msg = try std.fmt.allocPrint(self.allocator, "Lazy proxy factory must return an instance of a class compatible with {s}, {s} returned", .{ obj.class_name, kind });
                defer self.allocator.free(msg);
                try self.setPendingException("TypeError", msg);
                return error.RuntimeError;
            }
            const backing = result.object;
            if (backing == obj or backing.lazyInitializer() != .null or backing.backingValue() != .null) {
                try self.setPendingException("Error", "Lazy proxy factory must return a non-lazy object");
                return error.RuntimeError;
            }
            if (!self.isInstanceOf(obj.class_name, backing.class_name) or
                (if (obj.slots) |v| v.len else 0) != (if (backing.slots) |v| v.len else 0) or
                (self.hasMethod(obj.class_name, "__clone") and (!self.hasMethod(backing.class_name, "__clone") or !std.mem.eql(u8, try self.resolveMethod(obj.class_name, "__clone"), try self.resolveMethod(backing.class_name, "__clone")))) or
                (self.hasMethod(obj.class_name, "__destruct") and (!self.hasMethod(backing.class_name, "__destruct") or !std.mem.eql(u8, try self.resolveMethod(obj.class_name, "__destruct"), try self.resolveMethod(backing.class_name, "__destruct")))))
            {
                const msg = try std.fmt.allocPrint(self.allocator, "The real instance class {s} is not compatible with the proxy class {s}. The proxy must be a instance of the same class as the real instance, or a sub-class with no additional properties, and no overrides of the __destructor or __clone methods.", .{ backing.class_name, obj.class_name });
                defer self.allocator.free(msg);
                try self.setPendingException("TypeError", msg);
                return error.RuntimeError;
            }
            retainValue(result);
            state.backing = backing;
            const initializer = state.initializer;
            state.initializer = .null;
            self.releaseValue(initializer);
            return;
        }
        const result = try ctx.invokeCallable(state.initializer, &.{.{ .object = obj }});
        if (result != .null) {
            try self.setPendingException("TypeError", "Lazy object initializer must return NULL or no value");
            return error.RuntimeError;
        }
        const initializer = state.initializer;
        state.initializer = .null;
        self.releaseValue(initializer);
        if (self.hasPendingReleases()) self.drainPendingDestruct();
    }

    pub fn propHookName(self: *VM, prop_name: []const u8, kind: enum { get, set }) RuntimeError![]const u8 {
        const suffix = switch (kind) {
            .get => "$hook_get",
            .set => "$hook_set",
        };
        var buf: [256]u8 = undefined;
        if (std.fmt.bufPrint(&buf, "{s}{s}", .{ prop_name, suffix })) |name| return self.internName(name) else |_| {}
        const name = try std.fmt.allocPrint(self.allocator, "{s}{s}", .{ prop_name, suffix });
        defer self.allocator.free(name);
        return self.internName(name);
    }

    // Adopt the returned source binding, never manufacture storage on a virtual
    // property. Keep it alive across nested execution and preserve its mirrors.
    fn takeHookReturnCell(self: *VM) RuntimeError!?*Value {
        const cell = self.last_return_ref orelse return null;
        self.bindCell(cell);
        if (self.last_return_ref_owner != 0) {
            const ri = try self.refIndex();
            try ri.transferCell(self.allocator, self.last_return_ref_owner, try self.persistentRefOwner(), cell);
            ri.releaseOwner(self.allocator, self.last_return_ref_owner);
            self.last_return_ref_owner = 0;
        }
        self.setReturnRef(null);
        return cell;
    }

    fn prepareHookArray(self: *VM, cell: *Value) RuntimeError!Value {
        if (cell.* == .array and cell.array.refcount - cell.array.byref_pins > self.referenceAliasCount(cell)) {
            const clone = try self.shallowCloneCow(cell.array);
            self.setCell(cell, .{ .array = clone });
            try self.propagateCellWrite(cell, cell.*);
        }
        return cell.*;
    }

    // zend_assign_to_property_reference on a property __get answers for: the
    // write fetch reads it through __get (php's notice for a by-value
    // result), and there is no slot to bind. false when the property has one
    fn overloadedReferenceTarget(self: *VM, obj: *PhpObject, prop_name: []const u8) RuntimeError!bool {
        if (!self.overloadedForWrite(obj, prop_name)) return false;
        obj.refcount +%= 1;
        defer self.releaseValue(.{ .object = obj });
        self.setReturnRef(null);
        // borrowed, as callMethod results are
        const result = try self.callMagicGet(obj, prop_name);
        const by_ref = self.last_return_ref != null;
        self.setReturnRef(null);
        if (!by_ref and result != .object) {
            const msg = try std.fmt.allocPrint(self.allocator, "Indirect modification of overloaded property {s}::${s} has no effect", .{ obj.class_name, prop_name });
            defer self.allocator.free(msg);
            try self.raiseError(8, msg);
        }
        return true;
    }

    // zend_std_get_property_ptr_ptr has no slot to hand out and leaves a
    // write fetch to __get: the property isn't there or isn't visible here
    fn overloadedForWrite(self: *VM, obj: *PhpObject, prop_name: []const u8) bool {
        if (self.splArrayAsProps(obj) or !self.magicApplies(obj, prop_name, .get)) return false;
        const vr = self.findPropertyVisibility(obj.class_name, prop_name);
        const slot_present = obj.slots != null and obj.getSlotIndexForScope(prop_name, vr.defining_class) != null;
        const present = !obj.isUnset(prop_name) and (slot_present or obj.properties.contains(prop_name));
        return !present or (vr.declared and !self.propVisible(vr, prop_name, vr.visibility));
    }

    fn magicGetReturnsRef(self: *VM, obj: *PhpObject) RuntimeError!bool {
        const full_name = self.resolveMethod(obj.class_name, "__get") catch return false;
        const func = self.functions.get(full_name) orelse return false;
        return func.returns_ref;
    }

    fn propGetReturnsRef(self: *VM, obj: *PhpObject, prop_name: []const u8) RuntimeError!bool {
        const name = try self.propHookName(prop_name, .get);
        const full_name = try self.resolveMethod(obj.class_name, name);
        const func = self.functions.get(full_name) orelse return false;
        return func.returns_ref;
    }

    // whether an access to the property reaches its storage instead of its
    // hooks: inside the property's own hook (php's zend_is_in_hook, whatever
    // the object), or for reflection's raw access
    pub fn inPropHook(self: *VM, obj: *PhpObject, prop_name: []const u8) bool {
        if (self.frame_count > 0) if (self.currentFrame().func) |func| {
            if (std.mem.lastIndexOf(u8, func.name, "::")) |sep| {
                const method = func.name[sep + 2 ..];
                // zend_should_call_hook: only for the object the hook runs on
                // (or the instance of the lazy proxy it runs on)
                if (method.len > prop_name.len and std.mem.startsWith(u8, method, prop_name) and
                    (std.mem.eql(u8, method[prop_name.len..], "$hook_get") or std.mem.eql(u8, method[prop_name.len..], "$hook_set")))
                {
                    const this = self.currentThis() orelse return true;
                    if (this != .object) return true;
                    if (this.object == obj or this.object.storage() == obj) return true;
                }
            }
        };
        const obj_id = @intFromPtr(obj);
        for (self.prop_hook_guard.items) |g| {
            if (g.obj_ptr == obj_id and std.mem.eql(u8, g.prop_name, prop_name)) return true;
        }
        return false;
    }

    pub fn callPropHook(self: *VM, obj: *PhpObject, prop_name: []const u8, kind: enum { get, set }, value: Value) RuntimeError!?Value {
        if (self.inPropHook(obj, prop_name)) return null;
        if (!self.hasPropHook(obj.class_name, prop_name, if (kind == .get) .get else .set)) return null;
        const hook_name = try self.propHookName(prop_name, if (kind == .get) .get else .set);
        if (kind == .get and self.isWriteOnlyVirtual(obj.class_name, prop_name)) {
            const msg = try std.fmt.allocPrint(self.allocator, "Property {s}::${s} is write-only", .{ obj.class_name, prop_name });
            defer self.allocator.free(msg);
            try self.setPendingException("Error", msg);
            return error.RuntimeError;
        }
        const args: []const Value = if (kind == .set) &.{value} else &.{};
        return try self.callMethod(obj, hook_name, args);
    }

    pub fn hasPropHook(self: *VM, class_name: []const u8, prop_name: []const u8, kind: enum { get, set }) bool {
        if (!self.any_prop_hooks) return false;
        // fast path: if no class in this hierarchy declares any property hook,
        // the per-access bufPrint + hasMethod lookup is pure overhead. walking
        // the (usually 1-3 deep) parent chain of bool checks is far cheaper and
        // skips it for the overwhelming majority of classes. on hook-heavy
        // workloads this short-circuit costs a couple hashmap gets before the
        // existing cache + lookup runs
        {
            var current = class_name;
            const has_any = while (true) {
                if (self.classes.get(current)) |cls| {
                    if (cls.has_prop_hooks) break true;
                    if (cls.parent) |p| {
                        current = p;
                        continue;
                    }
                }
                break false;
            };
            if (!has_any) return false;
        }
        const kind_bit: u2 = switch (kind) {
            .get => 1,
            .set => 2,
        };
        const fn_count = self.functions.count() + self.native_fns.count();
        const cls_count = self.classes.count();
        if (self.has_hook_cache_fn_count == fn_count and
            self.has_hook_cache_cls_count == cls_count and
            self.has_hook_cache_kind == kind_bit and
            self.has_hook_cache_class.len == class_name.len and
            self.has_hook_cache_prop.len == prop_name.len and
            std.mem.eql(u8, self.has_hook_cache_class, class_name) and
            std.mem.eql(u8, self.has_hook_cache_prop, prop_name))
        {
            return self.has_hook_cache_result;
        }
        const suffix = switch (kind) {
            .get => "$hook_get",
            .set => "$hook_set",
        };
        var buf: [256]u8 = undefined;
        const hook_name = std.fmt.bufPrint(&buf, "{s}{s}", .{ prop_name, suffix }) catch return false;
        var result = if (self.classes.getPtr(class_name)) |cls| self.resolvePropertyHook(cls, hook_name) != null else false;
        // a virtual property with only a set hook is write-only: a read goes
        // to callPropHook, which refuses it as php's read_property does
        if (!result and kind == .get) result = self.isWriteOnlyVirtual(class_name, prop_name);
        self.has_hook_cache_class = class_name;
        self.has_hook_cache_prop = prop_name;
        self.has_hook_cache_kind = kind_bit;
        self.has_hook_cache_result = result;
        self.has_hook_cache_fn_count = fn_count;
        self.has_hook_cache_cls_count = cls_count;
        return result;
    }

    // the nearest declaration of a property in the class chain
    pub fn nearestPropertyDef(self: *VM, class_name: []const u8, prop_name: []const u8) ?*const ClassDef.PropertyDef {
        var current: ?[]const u8 = class_name;
        while (current) |cn| {
            const cls = self.classes.getPtr(cn) orelse return null;
            for (cls.properties.items) |*p| if (std.mem.eql(u8, p.name, prop_name)) return p;
            current = cls.parent;
        }
        return null;
    }

    // a get hook the class chain declares for the property
    pub fn hasRealGetHook(self: *VM, class_name: []const u8, prop_name: []const u8) bool {
        const cls = self.classes.getPtr(class_name) orelse return false;
        var buf: [256]u8 = undefined;
        const getter = std.fmt.bufPrint(&buf, "{s}$hook_get", .{prop_name}) catch return false;
        return self.resolvePropertyHook(cls, getter) != null;
    }

    // a virtual property with a set hook and no get hook
    fn isWriteOnlyVirtual(self: *VM, class_name: []const u8, prop_name: []const u8) bool {
        if (!self.propertyIsVirtual(class_name, prop_name)) return false;
        const cls = self.classes.getPtr(class_name) orelse return false;
        var buf: [256]u8 = undefined;
        const getter = std.fmt.bufPrint(&buf, "{s}$hook_get", .{prop_name}) catch return false;
        if (self.resolvePropertyHook(cls, getter) != null) return false;
        var buf2: [256]u8 = undefined;
        const setter = std.fmt.bufPrint(&buf2, "{s}$hook_set", .{prop_name}) catch return false;
        return self.resolvePropertyHook(cls, setter) != null;
    }

    // php's ZEND_ACC_VIRTUAL after inheritance: a property is backed when
    // any class in the chain declares it with storage
    pub fn propertyIsVirtual(self: *VM, class_name: []const u8, prop_name: []const u8) bool {
        var found = false;
        var current: ?[]const u8 = class_name;
        while (current) |cn| {
            const cls = self.classes.getPtr(cn) orelse break;
            for (cls.properties.items) |*p| if (std.mem.eql(u8, p.name, prop_name)) {
                if (found and p.visibility == .private) break;
                if (!p.is_virtual) return false;
                found = true;
                break;
            };
            current = cls.parent;
        }
        return found;
    }

    // zend_verify_hooked_property for the hooked properties a class
    // declares, once inheritance tells whether each has storage
    fn verifyHookedProperties(self: *VM, def: *const ClassDef, class_name: []const u8) RuntimeError!void {
        if (!def.has_prop_hooks) return;
        for (def.properties.items) |prop| {
            if (prop.trait_origin.len > 0) continue;
            var key_buf: [512]u8 = undefined;
            var hook_buf: [256]u8 = undefined;
            const getter = std.fmt.bufPrint(&hook_buf, "{s}$hook_get", .{prop.name}) catch continue;
            const get_info = def.methods.get(getter);
            var set_buf: [256]u8 = undefined;
            const setter = std.fmt.bufPrint(&set_buf, "{s}$hook_set", .{prop.name}) catch continue;
            const set_info = def.methods.get(setter);
            if (get_info == null and set_info == null) continue;
            // storage a parent gives it
            var inherited_backed = false;
            var current = def.parent;
            while (current) |pn| {
                const pc = self.classes.getPtr(pn) orelse break;
                for (pc.properties.items) |pp| if (std.mem.eql(u8, pp.name, prop.name) and pp.visibility != .private and !pp.is_virtual) {
                    inherited_backed = true;
                };
                current = pc.parent;
            }
            const virtual = prop.is_virtual and !inherited_backed;
            if (virtual and prop.has_default) return self.traitRuleFatal("Cannot specify default value for virtual hooked property {s}::${s}", .{ class_name, prop.name });
            if (!virtual and set_info != null and get_info != null) {
                const get_fn = self.functions.get(class_names.memberKey(&key_buf, class_name, getter)) orelse continue;
                if (get_fn.returns_ref) return self.traitRuleFatal("Get hook of backed property {s}::{s} with set hook may not return by reference", .{ class_name, prop.name });
            }
        }
    }

    // a property with a hook of either kind, for unset's refusal
    fn propertyHooked(self: *VM, class_name: []const u8, prop_name: []const u8) bool {
        return self.hasPropHook(class_name, prop_name, .get) or self.hasPropHook(class_name, prop_name, .set);
    }

    pub fn ensureClassHierarchyLoaded(self: *VM, class_name: []const u8) void {
        var current = class_name;
        var depth: usize = 0;
        while (depth < 64) : (depth += 1) {
            const cls = self.classes.get(current) orelse return;
            const parent = cls.parent orelse return;
            if (!self.classes.contains(parent)) self.tryAutoload(parent) catch return;
            current = parent;
        }
    }

    // An ordinary redeclaration supplies storage implementations for abstract
    // hooks, but retains concrete hooks inherited from its ancestors.
    pub fn resolvePropertyHook(self: *VM, start: *const ClassDef, method: []const u8) ?struct { declaring: []const u8, info: ClassDef.MethodInfo } {
        const split = std.mem.indexOf(u8, method, "$hook_") orelse return null;
        const prop_name = method[0..split];
        var backed_replacement = false;
        var cls = start;
        while (true) {
            if (cls.methods.get(method)) |info| {
                if (info.is_abstract and backed_replacement) return null;
                return .{ .declaring = cls.name, .info = info };
            }
            for (cls.properties.items) |prop| {
                if (std.mem.eql(u8, prop.name, prop_name) and !prop.is_virtual) backed_replacement = true;
            }
            cls = self.classes.getPtr(cls.parent orelse return null) orelse return null;
        }
    }

    pub fn hasMethod(self: *VM, class_name: []const u8, method_name: []const u8) bool {
        self.ensureClassHierarchyLoaded(class_name);
        // single-entry cache. verify content (callers pass stack-local slices
        // whose pointer address gets reused). bufPrint into a 256-byte stack
        // buffer was a noticeable fraction of release-mode samples on
        // assertion-heavy workloads
        const fn_count = self.functions.count() + self.native_fns.count();
        const cls_count = self.classes.count();
        if (self.has_method_cache_fn_count == fn_count and
            self.has_method_cache_cls_count == cls_count and
            self.has_method_cache_class.len == class_name.len and
            self.has_method_cache_method.len == method_name.len and
            std.mem.eql(u8, self.has_method_cache_class, class_name) and
            std.mem.eql(u8, self.has_method_cache_method, method_name))
        {
            return self.has_method_cache_result;
        }
        var current = class_name;
        var buf: [256]u8 = undefined;
        const result = while (true) {
            const full = class_names.memberKey(&buf, current, method_name);
            if (self.functions.get(full) != null or self.native_fns.get(full) != null) break true;
            if (self.classes.getEntry(current)) |entry| {
                const cls = entry.value_ptr;
                // methods are registered under the declared spellings of the
                // class and the method
                current = entry.key_ptr.*;
                if (cls.methods.getKey(method_name)) |declared| if (!std.mem.eql(u8, declared, method_name) or !std.mem.eql(u8, full[0..current.len], current)) {
                    const canonical = class_names.memberKey(&buf, current, declared);
                    if (self.functions.get(canonical) != null or self.native_fns.get(canonical) != null) break true;
                };
                if (cls.parent) |p| {
                    current = p;
                    continue;
                }
            }
            break false;
        };
        if (class_name.len > self.has_method_cache_class_storage.len or method_name.len > self.has_method_cache_method_storage.len) {
            self.has_method_cache_fn_count = std.math.maxInt(usize);
            return result;
        }
        @memcpy(self.has_method_cache_class_storage[0..class_name.len], class_name);
        @memcpy(self.has_method_cache_method_storage[0..method_name.len], method_name);
        self.has_method_cache_class = self.has_method_cache_class_storage[0..class_name.len];
        self.has_method_cache_method = self.has_method_cache_method_storage[0..method_name.len];
        self.has_method_cache_result = result;
        self.has_method_cache_fn_count = fn_count;
        self.has_method_cache_cls_count = cls_count;
        return result;
    }

    const MethodKey = struct {
        class: []const u8,
        method: []const u8,

        const Context = struct {
            pub fn hash(_: Context, key: MethodKey) u64 {
                var h = std.hash.Wyhash.init(0);
                h.update(key.class);
                h.update(&.{0});
                h.update(key.method);
                return h.final();
            }

            pub fn eql(_: Context, a: MethodKey, b: MethodKey) bool {
                return std.mem.eql(u8, a.class, b.class) and std.mem.eql(u8, a.method, b.method);
            }
        };

        fn bytes(key: MethodKey) []const u8 {
            return key.class.ptr[0 .. key.class.len + key.method.len];
        }
    };

    fn offsetGetReturnsRef(self: *VM, obj: *PhpObject) bool {
        const full_name = self.resolveMethod(obj.class_name, "offsetGet") catch return false;
        const func = self.functions.get(full_name) orelse return false;
        return func.returns_ref;
    }

    // pushes what offsetGet returned for a nested write: the value itself
    // when the write reaches it, else a copy the write can't leak through.
    // null when the notice raised an exception that was dispatched
    fn pushOverloadedElement(self: *VM, obj: *PhpObject, result: Value) RuntimeError!?void {
        const writable = self.overloadedElementWritable(obj, result) catch {
            _ = try self.resumeRaised();
            return null;
        };
        if (!writable and result == .array) {
            self.pushCallResult(.{ .array = try self.shallowCloneCow(result.array) });
        } else self.pushCallResult(result);
    }

    // php's zend_fetch_dimension_address on an ArrayAccess object: what
    // offsetGet returned is written into only when it is a reference or an
    // object; anything else draws the notice and the write lands on a
    // temporary copy. false when the caller's write has no effect
    fn overloadedElementWritable(self: *VM, obj: *PhpObject, result: Value) RuntimeError!bool {
        if (result == .object) return true;
        if (try self.splOwnOffsetGet(obj)) return true;
        if (self.offsetGetReturnsRef(obj)) return true;
        const msg = try std.fmt.allocPrint(self.allocator, "Indirect modification of overloaded element of {s} has no effect", .{obj.class_name});
        defer self.allocator.free(msg);
        try self.raiseError(8, msg);
        return false;
    }

    // functions and classes are only ever added within a request, so a count
    // change is exactly when a cached resolution may have gone stale
    // the element a nested write goes into: offsetGet, or for ArrayObject and
    // ArrayIterator's own offsetGet php's write fetch, which doesn't warn
    // about a missing key
    fn offsetGetForWrite(self: *VM, obj: *PhpObject, key: Value) RuntimeError!Value {
        if (try self.splOwnOffsetGet(obj)) {
            var ctx = self.makeContext(null);
            return @import("../stdlib/spl.zig").arrayStorageFetch(&ctx, obj, key);
        }
        return self.callMethod(obj, "offsetGet", &.{key});
    }

    // whether $obj[...] reaches ArrayObject's or ArrayIterator's own offsetGet
    fn splOwnOffsetGet(self: *VM, obj: *PhpObject) RuntimeError!bool {
        return self.splOwnMethod(obj, "offsetGet");
    }

    fn splOwnMagic(self: *VM, obj: *PhpObject, kind: MagicKind) RuntimeError!bool {
        return switch (kind) {
            .get => self.splOwnMethod(obj, "__get"),
            .set => self.splOwnMethod(obj, "__set"),
            .isset => self.splOwnMethod(obj, "__isset"),
            .unset => self.splOwnMethod(obj, "__unset"),
        };
    }

    // whether the method an object runs is ArrayObject's or ArrayIterator's
    // own, not a subclass's (spl_array's fptr_offset_* being unset)
    fn splOwnMethod(self: *VM, obj: *PhpObject, comptime name: []const u8) RuntimeError!bool {
        const method = self.resolveMethod(obj.class_name, name) catch return false;
        return std.mem.eql(u8, method, "ArrayObject::" ++ name) or std.mem.eql(u8, method, "ArrayIterator::" ++ name);
    }

    pub fn resolveMethod(self: *VM, class_name: []const u8, method_name: []const u8) RuntimeError![]const u8 {
        const ic = self.ic.?;
        const key: MethodKey = .{ .class = class_name, .method = method_name };
        self.syncResolvedMethods(ic);
        if (ic.resolved_methods.get(key)) |hit| return hit;
        self.ensureClassHierarchyLoaded(class_name);
        const result = try self.resolveMethodSlow(class_name, method_name);
        self.syncResolvedMethods(ic);
        self.rememberResolvedMethod(ic, key, result);
        return result;
    }

    fn syncResolvedMethods(self: *VM, ic: *InlineCache) void {
        const fn_count = self.functions.count() + self.native_fns.count();
        const cls_count = self.classes.count();
        if (ic.resolved_methods_fn_count == fn_count and ic.resolved_methods_cls_count == cls_count) return;
        self.clearResolvedMethods(ic);
        ic.resolved_methods_fn_count = fn_count;
        ic.resolved_methods_cls_count = cls_count;
    }

    fn rememberResolvedMethod(self: *VM, ic: *InlineCache, key: MethodKey, result: []const u8) void {
        const buf = self.allocator.alloc(u8, key.class.len + key.method.len) catch return;
        @memcpy(buf[0..key.class.len], key.class);
        @memcpy(buf[key.class.len..], key.method);
        const owned: MethodKey = .{ .class = buf[0..key.class.len], .method = buf[key.class.len..] };
        ic.resolved_methods.put(self.allocator, owned, result) catch self.allocator.free(buf);
    }

    fn clearResolvedMethods(self: *VM, ic: *InlineCache) void {
        var it = ic.resolved_methods.keyIterator();
        while (it.next()) |key| self.allocator.free(key.bytes());
        ic.resolved_methods.clearRetainingCapacity();
    }

    fn resolveMethodSlow(self: *VM, class_name: []const u8, method_name: []const u8) RuntimeError![]const u8 {
        var current = class_name;
        var buf: [256]u8 = undefined;
        var tried_autoload = false;
        while (true) {
            // methods are registered under the declared spelling of the class
            current = self.classes.getKey(current) orelse current;
            const full = class_names.memberKey(&buf, current, method_name);
            if (self.functions.getEntry(full)) |entry| return entry.key_ptr.*;
            if (self.native_fns.getKey(full)) |key| return key;
            if (self.classes.get(current)) |cls| {
                if (cls.methods.getKey(method_name)) |declared| {
                    const canonical = class_names.memberKey(&buf, current, declared);
                    if (self.functions.getEntry(canonical)) |entry| return entry.key_ptr.*;
                    if (self.native_fns.getKey(canonical)) |key| return key;
                }
                if (cls.parent) |p| {
                    current = p;
                    continue;
                }
            } else if (!tried_autoload and self.autoload_callbacks.items.len > 0) {
                tried_autoload = true;
                try self.tryAutoload(current);
                continue;
            }
            return error.RuntimeError;
        }
    }

    pub fn buildSlotLayout(self: *VM, def: *const ClassDef) RuntimeError!?*PhpObject.SlotLayout {
        // collect all properties walking parent chain (parent first). private
        // slots from each declaring class get their OWN entry (PHP keeps
        // parent's `private $foo` and child's `private $foo` separate); only
        // public/protected slots merge by name so a child override patches
        // the parent's default
        var all_names: std.ArrayListUnmanaged([]const u8) = .empty;
        var all_defaults: std.ArrayListUnmanaged(Value) = .empty;
        var all_decl: std.ArrayListUnmanaged([]const u8) = .empty;
        var all_priv: std.ArrayListUnmanaged(bool) = .empty;
        defer all_names.deinit(self.allocator);
        defer all_defaults.deinit(self.allocator);
        defer all_decl.deinit(self.allocator);
        defer all_priv.deinit(self.allocator);

        var walk_name = def.parent;
        while (walk_name) |pname| {
            const pcls = self.classes.get(pname) orelse break;
            if (pcls.slot_layout) |pl| {
                for (0..pl.names.len) |i| {
                    try all_names.append(self.allocator, pl.names[i]);
                    try all_defaults.append(self.allocator, pl.defaults[i]);
                    try all_decl.append(self.allocator, pl.declaring_classes[i]);
                    try all_priv.append(self.allocator, pl.is_private[i]);
                }
                break;
            }
            walk_name = pcls.parent;
        }

        for (def.properties.items) |prop| {
            const is_priv = prop.visibility == .private;
            var found = false;
            if (!is_priv) {
                // public/protected: merge with same-name parent slot (override the default)
                for (all_names.items, 0..) |n, i| {
                    if (all_priv.items[i]) continue;
                    if (std.mem.eql(u8, n, prop.name)) {
                        all_defaults.items[i] = slotDefault(def, prop);
                        // a public/protected child overrides any visibility:
                        // record the child as the new declaring class
                        all_decl.items[i] = def.name;
                        found = true;
                        break;
                    }
                }
            }
            // a virtual property has no storage, unless a parent declares it
            // with storage (php keeps the parent's slot)
            if (!found and prop.is_virtual) continue;
            if (!found) {
                try all_names.append(self.allocator, prop.name);
                try all_defaults.append(self.allocator, slotDefault(def, prop));
                try all_decl.append(self.allocator, def.name);
                try all_priv.append(self.allocator, is_priv);
            }
        }

        if (all_names.items.len == 0) return null;

        const layout = self.allocator.create(PhpObject.SlotLayout) catch return error.RuntimeError;
        const names = self.allocator.alloc([]const u8, all_names.items.len) catch return error.RuntimeError;
        const defaults = self.allocator.alloc(Value, all_defaults.items.len) catch return error.RuntimeError;
        const decl = self.allocator.alloc([]const u8, all_decl.items.len) catch return error.RuntimeError;
        const priv = self.allocator.alloc(bool, all_priv.items.len) catch return error.RuntimeError;
        @memcpy(names, all_names.items);
        @memcpy(defaults, all_defaults.items);
        @memcpy(decl, all_decl.items);
        @memcpy(priv, all_priv.items);
        layout.* = .{ .names = names, .defaults = defaults, .declaring_classes = decl, .is_private = priv, .throwable = self.definesThrowable(def), .defaults_ready = self.ancestorDefaultsReady(def) };
        return layout;
    }

    // what a new object's slot holds: a typed property a user class declares
    // without a default starts uninitialized (php's IS_UNDEF with
    // IS_PROP_UNINIT), anything else its default
    fn slotDefault(def: *const ClassDef, prop: ClassDef.PropertyDef) Value {
        if (!def.is_internal and prop.type_str.len > 0 and (!prop.has_default or prop.is_promoted)) return .undef;
        return prop.default;
    }

    pub fn initObjectProperties(self: *VM, obj: *PhpObject, class_name: []const u8) RuntimeError!void {
        if (try self.initPropertyDefaults(obj, class_name)) try self.stampThrowable(obj);
    }

    // returns whether the class is throwable, so the caller stamps it once
    fn initPropertyDefaults(self: *VM, obj: *PhpObject, class_name: []const u8) RuntimeError!bool {
        // a class without properties has no layout to mark
        if (self.lazy_constant_classes > 0) try self.updateClassConstants(class_name);
        const cls = self.classes.get(class_name) orelse return false;
        if (cls.slot_layout) |layout| {
            if (!layout.defaults_ready) try self.resolveClassDefaults(class_name);
            const slots = self.allocator.alloc(Value, layout.names.len) catch return error.RuntimeError;
            for (layout.defaults, 0..) |def_val, i| {
                slots[i] = try self.copyDefault(def_val);
            }
            obj.slots = slots;
            obj.slot_layout = layout;
            try self.initBuiltinAncestorDefaults(obj, cls.parent);
            return layout.throwable;
        }
        // fallback for classes without slot layout
        if (cls.parent) |parent| _ = try self.initPropertyDefaults(obj, parent);
        for (cls.properties.items) |prop| {
            try obj.set(self.allocator, prop.name, try self.copyDefault(prop.default));
        }
        return self.isThrowableClass(class_name);
    }

    // a built-in ancestor without a layout (DateInterval, DatePeriod) keeps
    // its declared properties out of a subclass's slots, after the subclass's
    // own, as php's property handlers list them; they are set here, root first
    fn initBuiltinAncestorDefaults(self: *VM, obj: *PhpObject, first: ?[]const u8) RuntimeError!void {
        const name = first orelse return;
        const cls = self.classes.get(name) orelse return;
        if (cls.slot_layout != null) return;
        try self.initBuiltinAncestorDefaults(obj, cls.parent);
        for (cls.properties.items) |prop| {
            if (obj.getSlotIndex(prop.name) != null or obj.properties.contains(prop.name)) continue;
            try obj.set(self.allocator, prop.name, try self.copyDefault(prop.default));
        }
    }

    fn ancestorDefaultsReady(self: *VM, def: *const ClassDef) bool {
        var name = def.parent;
        while (name) |n| {
            const cls = self.classes.get(n) orelse return true;
            if (cls.defaults_pending) return false;
            name = cls.parent;
        }
        return true;
    }

    // php evaluates property defaults, static and instance, that read other
    // classes or global constants when the class is first used, so such a
    // default may name a class that extends this one. runs the hidden
    // initializers root first, then copies the resolved inherited defaults
    // into this class's layout
    pub fn resolveClassDefaults(self: *VM, class_name: []const u8) RuntimeError!void {
        try self.updateClassConstants(class_name);
        const cls = self.classes.getPtr(class_name) orelse return;
        const layout = cls.slot_layout;
        if (layout) |l| {
            if (l.defaults_ready) return;
            l.defaults_ready = true;
        }
        errdefer if (layout) |l| {
            l.defaults_ready = false;
        };
        if (cls.parent) |parent| try self.resolveClassDefaults(parent);
        try self.runDeferredDefaults(class_name);
        if (layout) |l| self.inheritLayoutDefaults(class_name, l);
    }

    fn runDeferredDefaults(self: *VM, class_name: []const u8) RuntimeError!void {
        const cls = self.classes.getPtr(class_name) orelse return;
        if (!cls.defaults_pending) return;
        cls.defaults_pending = false;
        self.ic.?.pending_defaults -= 1;
        const name = try bytecode.propDefaultsInitializerName(self.allocator, class_name);
        defer self.allocator.free(name);
        const floor = self.handler_floor;
        self.handler_floor = self.handler_count;
        defer self.handler_floor = floor;
        const instantiating = self.frame_count;
        self.bare_default_failed = false;
        _ = self.callByName(name, &.{}) catch |err| {
            // a default that only names a global constant is resolved at the
            // instantiation (zval_update_constant_ex); any other expression
            // is php's constant expression
            if (self.pending_exception) |exc| if (exc == .object) try (if (self.bare_default_failed) self.stampThrowableBelow(exc.object, instantiating) else self.stampConstExprThrowable(exc.object, instantiating));
            // php evaluates the defaults again on the next attempt
            if (self.classes.getPtr(class_name)) |retry| if (!retry.defaults_pending) {
                retry.defaults_pending = true;
                self.ic.?.pending_defaults += 1;
            };
            return err;
        };
    }

    // a static read: autoloading the class on a miss, null when nothing
    // declares the property
    fn readStaticProp(self: *VM, class_name: []const u8, prop_name: []const u8) RuntimeError!?Value {
        if (try self.staticPropValue(class_name, prop_name)) |val| return val;
        // the lookup autoloads and keeps an autoloader's exception pending
        if (self.pending_exception != null) return error.RuntimeError;
        if (self.classes.contains(class_name) or self.interfaces.contains(class_name)) return null;
        try self.tryAutoload(class_name);
        return self.staticPropValue(class_name, prop_name);
    }

    // a static read: the value, or php's error for a missing class or
    // property. a quiet read (isset, ??, empty) finds a missing property null,
    // but a missing class is an error there too
    fn pushStaticProp(self: *VM, class_name: []const u8, prop_name: []const u8, quiet: bool) RuntimeError!void {
        if (try self.readStaticProp(class_name, prop_name)) |val| {
            if (try self.staticPropDenial(class_name, prop_name, .read)) |msg| {
                defer self.allocator.free(msg);
                // isset() and ?? treat a property out of scope as missing
                if (quiet) return self.push(.null);
                try self.setPendingException("Error", msg);
                return error.RuntimeError;
            }
            if (val == .null) if (self.getStaticPropRaw(class_name, prop_name)) |raw| if (raw == .undef) {
                if (quiet) return self.push(.null);
                const msg = try std.fmt.allocPrint(self.allocator, "Typed static property {s}::${s} must not be accessed before initialization", .{ self.staticPropDeclaringClass(class_name, prop_name) orelse class_name, prop_name });
                defer self.allocator.free(msg);
                try self.setPendingException("Error", msg);
                return error.RuntimeError;
            };
            return self.push(val);
        }
        if (quiet and (self.classes.contains(class_name) or self.interfaces.contains(class_name))) return self.push(.null);
        return self.undeclaredStaticProp(class_name, prop_name);
    }

    // the class that declares a static property a write names, loading the
    // named class first; php refuses to create one. the write must be allowed
    // by the property's visibility and set visibility
    fn staticPropTarget(self: *VM, class_name: []const u8, prop_name: []const u8, access: StaticAccess) RuntimeError!*ClassDef {
        if (!self.classes.contains(class_name)) try self.tryAutoload(class_name);
        var current: ?[]const u8 = class_name;
        while (current) |name| {
            const cls = self.classes.getPtr(name) orelse break;
            if (cls.static_props.contains(prop_name)) {
                if (access == .declare) return cls;
                if (try self.staticPropDenial(class_name, prop_name, access)) |msg| {
                    defer self.allocator.free(msg);
                    try self.setPendingException("Error", msg);
                    return error.RuntimeError;
                }
                // the check may have autoloaded classes and moved this one
                return self.classes.getPtr(name) orelse self.undeclaredStaticProp(class_name, prop_name);
            }
            current = cls.parent;
        }
        return self.undeclaredStaticProp(class_name, prop_name);
    }

    // declare installs a declared default, which no scope rule applies to
    const StaticAccess = enum { read, write, indirect, declare };

    // the error php raises for a static property access the current scope
    // may not make, or null when it may. any access needs the declaring
    // class's visibility (reported against the class as written); a write
    // also needs its set visibility (reported against the declaring class).
    // the caller owns the message
    fn staticPropDenial(self: *VM, class_name: []const u8, prop_name: []const u8, access: StaticAccess) RuntimeError!?[]u8 {
        var current: ?[]const u8 = class_name;
        const entry = while (current) |name| {
            const e = self.classes.getEntry(name) orelse return null;
            if (e.value_ptr.static_props.contains(prop_name)) break e;
            current = e.value_ptr.parent;
        } else return null;
        // read everything up front: a visibility check can autoload an
        // interface, and a class the autoloader declares can move the entry
        const declaring = entry.key_ptr.*;
        const vis = entry.value_ptr.static_prop_visibility.get(prop_name) orelse .public;
        const explicit_set_vis = entry.value_ptr.static_prop_set_visibility.get(prop_name);
        if (!self.checkVisibility(declaring, vis)) {
            return try std.fmt.allocPrint(self.allocator, "Cannot access {s} property {s}::${s}", .{ @tagName(vis), self.declaredClassName(class_name), prop_name });
        }
        if (access == .read) return null;
        const set_vis = explicit_set_vis orelse return null;
        if (self.checkVisibility(declaring, set_vis)) return null;
        const verb: []const u8 = if (access == .indirect) "indirectly modify" else "modify";
        if (self.currentDefiningClass()) |scope| {
            return try std.fmt.allocPrint(self.allocator, "Cannot {s} {s}(set) property {s}::${s} from scope {s}", .{ verb, @tagName(set_vis), declaring, prop_name, scope });
        }
        return try std.fmt.allocPrint(self.allocator, "Cannot {s} {s}(set) property {s}::${s} from global scope", .{ verb, @tagName(set_vis), declaring, prop_name });
    }

    fn undeclaredStaticProp(self: *VM, class_name: []const u8, prop_name: []const u8) RuntimeError {
        const msg = if (self.classes.contains(class_name) or self.interfaces.contains(class_name))
            try std.fmt.allocPrint(self.allocator, "Access to undeclared static property {s}::${s}", .{ class_name, prop_name })
        else
            try self.classNotFoundMessage(class_name);
        defer self.allocator.free(msg);
        try self.setPendingException("Error", msg);
        return error.RuntimeError;
    }

    // a static read autoloads the class, so its deferred defaults can only be
    // resolved after the lookup; the value is read again once they have run
    fn staticPropValue(self: *VM, class_name: []const u8, prop_name: []const u8) RuntimeError!?Value {
        const found = self.getStaticProp(class_name, prop_name);
        if (self.ic.?.pending_defaults == 0) return found;
        try self.resolveClassDefaults(class_name);
        return self.getStaticProp(class_name, prop_name);
    }

    // a static property read or write uses the class, which resolves its
    // deferred defaults first
    pub inline fn resolveStaticDefaults(self: *VM, class_name: []const u8) RuntimeError!void {
        if (self.ic.?.pending_defaults == 0 and self.lazy_constant_classes == 0) return;
        try self.resolveClassDefaults(class_name);
    }

    fn inheritLayoutDefaults(self: *VM, class_name: []const u8, layout: *PhpObject.SlotLayout) void {
        for (layout.names, layout.declaring_classes, 0..) |name, declaring, i| {
            if (std.mem.eql(u8, declaring, class_name)) continue;
            const source = (self.classes.get(declaring) orelse continue).slot_layout orelse continue;
            for (source.names, source.declaring_classes, source.defaults) |sn, sd, value| {
                if (std.mem.eql(u8, sn, name) and std.mem.eql(u8, sd, declaring)) {
                    layout.defaults[i] = value;
                    break;
                }
            }
        }
    }

    // a class being declared is not registered yet, so its chain starts at the parent
    fn definesThrowable(self: *VM, def: *const ClassDef) bool {
        if (std.mem.eql(u8, def.name, "Exception") or std.mem.eql(u8, def.name, "Error")) return true;
        return if (def.parent) |parent| self.isThrowableClass(parent) else false;
    }

    // every throwable extends Exception or Error
    fn isThrowableClass(self: *VM, class_name: []const u8) bool {
        var name: ?[]const u8 = class_name;
        var depth: usize = 0;
        while (name) |n| : (depth += 1) {
            if (depth > 256) return false;
            if (std.mem.eql(u8, n, "Exception") or std.mem.eql(u8, n, "Error")) return true;
            const cls = self.classes.get(n) orelse return false;
            name = cls.parent;
        }
        return false;
    }

    // php fixes an exception's origin when the object is created, before any
    // constructor runs
    fn stampThrowable(self: *VM, obj: *PhpObject) RuntimeError!void {
        return self.stampThrowableBelow(obj, self.frame_count);
    }

    // an initializer that only reads a global constant: php resolves that
    // one without zend_ast_evaluate (zval_update_constant_ex), so with no
    // file or line of its own
    fn isBareConstantInitializer(f: *const ObjFunction) bool {
        const code = f.chunk.code.items;
        var i: usize = 0;
        if (code.len > 3 and code[0] == @intFromEnum(OpCode.enter_class_scope)) i = 3;
        if (i + 3 >= code.len or code[i] != @intFromEnum(OpCode.get_var)) return false;
        const next = code[i + 3];
        return next == @intFromEnum(OpCode.leave_class_scope) or next == @intFromEnum(OpCode.return_val);
    }

    // a property defaults initializer reading a default that is only a
    // global constant: [get_var][set_prop_default], right after the class
    // scope opened or the previous default was stored
    fn bareDefaultRunning(frame: *const CallFrame) bool {
        const func = frame.func orelse return false;
        if (!std.mem.startsWith(u8, func.name, "\x00propdefaults\x00")) return false;
        const code = frame.chunk.code.items;
        const ip = frame.ip;
        if (ip < 3 or ip >= code.len) return false;
        const next = code[ip];
        if (next != @intFromEnum(OpCode.set_prop_default) and next != @intFromEnum(OpCode.set_static_prop_default)) return false;
        if (code[ip - 3] != @intFromEnum(OpCode.get_var)) return false;
        if (ip - 3 == 3 and code[0] == @intFromEnum(OpCode.enter_class_scope)) return true;
        return ip >= 4 and code[ip - 4] == @intFromEnum(OpCode.pop);
    }

    fn isScopedConstExpr(name: []const u8) bool {
        return std.mem.startsWith(u8, name, "\x00const\x00") or std.mem.startsWith(u8, name, "\x00propdefaults\x00");
    }

    // an exception thrown while a class constant or property default was
    // evaluated keeps the expression's file and line; its trace starts
    // with php's "[constant expression]" frame at the code that needed the
    // value (zend_fetch_debug_backtrace under EG(filename_override)), unless
    // that is the same place
    fn stampConstExprThrowable(self: *VM, obj: *PhpObject, top: usize) RuntimeError!void {
        const trace = try self.traceBelow(top);
        if (top > 0) if (self.framePosition(top - 1)) |site| {
            const file = obj.get("file");
            const line = obj.get("line");
            const same = file == .string and std.mem.eql(u8, file.string.bytes(), site.file) and line == .int and line.int == site.line;
            if (!same) {
                const entry = try self.allocArray();
                try entry.set(self.allocator, .{ .string = Value.String.borrowed("file") }, .{ .string = Value.String.borrowed(site.file) });
                try entry.set(self.allocator, .{ .string = Value.String.borrowed("line") }, .{ .int = site.line });
                try entry.set(self.allocator, .{ .string = Value.String.borrowed("function") }, .{ .string = Value.String.borrowed("[constant expression]") });
                const full = try self.allocArray();
                try full.append(self.allocator, .{ .array = entry });
                for (trace.entries.items) |e| try full.append(self.allocator, e.value);
                self.releaseUnheldArray(trace);
                self.dropExceptionTraceArgs(full);
                try obj.setForScope(self.allocator, "trace", .{ .array = full }, self.exceptionTraceScope(obj));
                return;
            }
        };
        self.dropExceptionTraceArgs(trace);
        try obj.setForScope(self.allocator, "trace", .{ .array = trace }, self.exceptionTraceScope(obj));
    }

    fn stampThrowableBelow(self: *VM, obj: *PhpObject, top: usize) RuntimeError!void {
        const at: SourcePosition = if (top > 0) self.framePosition(top - 1) orelse .{ .file = self.frameFile(top - 1), .line = 0 } else .{ .file = self.file_path, .line = 0 };
        try obj.set(self.allocator, "file", .{ .string = Value.String.borrowed(at.file) });
        try obj.set(self.allocator, "line", .{ .int = at.line });
        const trace = try self.traceBelow(top);
        self.dropExceptionTraceArgs(trace);
        try obj.setForScope(self.allocator, "trace", .{ .array = trace }, self.exceptionTraceScope(obj));
    }

    // copy a template value (a property/static default) into a fresh owner.
    // a default array is a compile-time TEMPLATE held by the slot layout, whose
    // reference is not part of the COW refcount - so it must be deep-cloned, not
    // COW-shared. sharing it would let an instance's first-write separation
    // decrement the template to refcount 0 and free it while the layout still
    // points at it (use-after-free). other value kinds copy normally
    fn copyDefault(self: *VM, val: Value) RuntimeError!Value {
        if (val == .array) {
            const c = try self.cloneArray(val.array);
            arrayRetain(c);
            return .{ .array = c };
        }
        return self.copyValue(val);
    }

    fn arrayUnion(self: *VM, a: *PhpArray, b: *PhpArray) RuntimeError!*PhpArray {
        const result = try self.cloneArray(a);
        for (b.entries.items) |entry| {
            var found = false;
            for (result.entries.items) |existing| {
                if (PhpArray.Key.eql(existing.key, entry.key)) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                // the result owns a new reference to b's value - retain it, else
                // freeing result later over-releases an object/array still held
                // by b (e.g. `$local += self::$staticCache` then unset $local
                // would destruct the cache's shared objects)
                retainValue(entry.value);
                if (entry.key == .string) entry.key.string.retain();
                try result.entries.append(self.allocator, entry);
                switch (entry.key) {
                    .string => |str| result.string_index.put(self.allocator, str.bytes(), result.entries.items.len - 1) catch return error.RuntimeError,
                    .int => |i| result.noteIntKey(i),
                }
            }
        }
        return result;
    }

    // shallow copy-on-write clone: duplicates only the top-level entries list
    // + string_index. nested arrays/objects are SHARED with the source (each
    // element reference retained), so a deeper write separates again at that
    // level. born at refcount 0 - cowSeparate sets it to the writer's 1
    // after cloning a ref-containing array, the clone's referenced entries
    // share the original's cells (PHP preserves is_ref across array copy). bind
    // each cloned ref entry into the vm-level registry so propagateCellWrite
    // reaches the clone too - this is what makes `$d = $c; $d[$k] = X` write the
    // shared storage when $c[$k] is a reference
    // unset($arr[$k]) on a referenced element breaks the reference: drop every
    // binding for (array, key) from the vm-level and frame-level registries so
    // a later write through the (still-live) cell can't resurrect the entry
    fn unbindArrayElemRef(self: *VM, arr: *PhpArray, key: PhpArray.Key) void {
        if (!self.array_ref_active) return;
        const nk = PhpArray.normalizeKey(key);
        var i: usize = 0;
        while (i < self.array_ref_bindings.items.len) {
            const b = self.array_ref_bindings.items[i];
            if (b.array == arr and PhpArray.normalizeKey(b.key).eql(nk)) {
                if (self.ref_index) |ri| ri.removeTargetAllOwners(self.allocator, b.cell, .{ .array = .{ .array = b.array, .key = b.key } });
                _ = self.array_ref_bindings.swapRemove(i);
            } else i += 1;
        }
        if (self.ref_index) |ri| {
            var matches: std.ArrayListUnmanaged(RefIndex.OwnedBinding) = .empty;
            defer matches.deinit(self.allocator);
            var it = ri.fwd.iterator();
            while (it.next()) |entry| for (entry.value_ptr.items) |target| {
                if (target == .array and target.array.array == arr and PhpArray.normalizeKey(target.array.key).eql(nk)) {
                    matches.append(self.allocator, .{ .cell = entry.key_ptr.*, .target = target }) catch return;
                }
            };
            for (matches.items) |binding| ri.removeTargetAllOwners(self.allocator, binding.cell, binding.target);
        }
    }

    // php copies the value of a reference only the source element holds, so
    // the copy is a plain element (a reference to the array itself stays one)
    fn carriedRef(ref: ?*Value, src: *PhpArray) ?*Value {
        const cell = ref orelse return null;
        if (cellOf(cell).binders > 1) return cell;
        if (cell.* == .array and cell.array == src) return cell;
        return null;
    }

    fn registerCloneRefs(self: *VM, copy: *PhpArray) RuntimeError!void {
        if (!self.array_ref_active) return;
        for (copy.entries.items) |entry| {
            if (entry.ref) |cell| {
                self.array_ref_bindings.append(self.allocator, .{ .cell = cell, .array = copy, .key = entry.key }) catch return error.RuntimeError;
                self.regRefArray(self.persistentRefOwner() catch return error.RuntimeError, cell, copy, entry.key) catch return error.RuntimeError;
            }
        }
    }

    fn shallowCloneCow(self: *VM, src: *PhpArray) RuntimeError!*PhpArray {
        const copy = self.allocArray() catch return error.RuntimeError;
        copy.* = .{ .next_int_key = src.next_int_key, .has_int_keys = src.has_int_keys, .cursor = src.cursor };
        copy.entries.ensureTotalCapacity(self.allocator, src.entries.items.len) catch return error.RuntimeError;
        for (src.entries.items, 0..) |entry, i| {
            if (entry.key == .string) entry.key.string.retain();
            const ref = carriedRef(entry.ref, src);
            copy.entries.appendAssumeCapacity(.{ .key = entry.key, .value = entry.value, .ref = ref });
            if (ref) |cell| self.bindCell(cell);
            retainValue(entry.value);
            if (entry.key == .string) {
                copy.string_index.put(self.allocator, entry.key.string.bytes(), i) catch return error.RuntimeError;
            }
        }
        try self.registerCloneRefs(copy);
        // zend_array_dup copies the iterators of a live by-reference loop:
        // the copy keeps the removals the loop hasn't seen yet
        if (src.iter_log) |log| if (log.loops > 0) if (copy.iterLog()) |copy_log| {
            copy_log.copied_from = src;
            copy_log.removed.appendSlice(std.heap.c_allocator, log.removed.items) catch {};
        };
        return copy;
    }

    // a native that renumbers or moves an array's elements in place drops the
    // bindings of its referenced elements first (they name elements by key)
    // and registers them again under the new keys afterwards
    pub fn detachArrayRefs(self: *VM, arr: *PhpArray) void {
        if (!self.array_ref_active) return;
        for (arr.entries.items) |entry| if (entry.ref != null) self.unbindArrayElemRef(arr, entry.key);
    }

    pub fn attachArrayRefs(self: *VM, arr: *PhpArray) RuntimeError!void {
        try self.registerCloneRefs(arr);
    }

    // adds src's element to dst under key (the next index when null) the way
    // php's array functions copy one: a reference another name still holds
    // stays a reference (`Z_ISREF_P(entry) && Z_REFCOUNT_P(entry) == 1` is
    // unwrapped), anything else is copied by value
    pub fn arrayAddCarried(self: *VM, dst: *PhpArray, key: ?PhpArray.Key, entry: PhpArray.Entry, src: *PhpArray) RuntimeError!void {
        return self.arrayAddEntry(dst, key, entry, carriedRef(entry.ref, src));
    }

    // adds the element to dst keeping `keep` (its reference, or null) as
    // the new element's reference
    pub fn arrayAddEntry(self: *VM, dst: *PhpArray, key: ?PhpArray.Key, entry: PhpArray.Entry, keep: ?*Value) RuntimeError!void {
        const value = if (entry.ref) |cell| cell.* else entry.value;
        if (key) |k| {
            dst.set(self.allocator, k, value) catch return error.RuntimeError;
        } else {
            const before = dst.entries.items.len;
            dst.append(self.allocator, value) catch return error.RuntimeError;
            // append refuses past the largest index
            if (dst.entries.items.len == before) return;
        }
        const carried = keep;
        const ep = if (key) |k| dst.getPtr(k) orelse return else &dst.entries.items[dst.entries.items.len - 1];
        // an element this replaced may have been a reference
        if (ep.ref != carried) {
            if (ep.ref != null) self.unbindArrayElemRef(dst, ep.key);
            self.setEntryRef(ep, carried);
        }
        const cell = carried orelse return;
        if (self.array_ref_active) {
            self.array_ref_bindings.append(self.allocator, .{ .cell = cell, .array = dst, .key = ep.key }) catch return error.RuntimeError;
            self.regRefArray(self.persistentRefOwner() catch return error.RuntimeError, cell, dst, ep.key) catch return error.RuntimeError;
        }
    }

    // src's entries where keep is set, in order, carrying references as
    // zend_array_dup does. inherit_next keeps src's next free index and
    // internal pointer, as php's dup-then-delete results do; otherwise the
    // next index follows the kept keys, as a freshly built array's does
    pub fn copyKeptEntries(self: *VM, src: *PhpArray, keep: []const bool, inherit_next: bool) RuntimeError!*PhpArray {
        // a callback may have changed src since keep was sized
        const items = src.entries.items[0..@min(src.entries.items.len, keep.len)];
        var kept: usize = 0;
        var strings: usize = 0;
        for (items, keep[0..items.len]) |entry, k| if (k) {
            kept += 1;
            if (entry.key == .string) strings += 1;
        };
        const copy = self.allocArray() catch return error.RuntimeError;
        if (inherit_next) copy.* = .{ .next_int_key = src.next_int_key, .has_int_keys = src.has_int_keys };
        copy.entries.ensureTotalCapacity(self.allocator, kept) catch return error.RuntimeError;
        copy.reserveStringIndex(self.allocator, strings) catch return error.RuntimeError;
        var cursor_set = false;
        for (items, keep[0..items.len], 0..) |entry, k, i| {
            if (!k) continue;
            if (inherit_next and !cursor_set and i >= src.cursor) {
                copy.cursor = copy.entries.items.len;
                cursor_set = true;
            }
            if (entry.key == .string) entry.key.string.retain();
            const ref = carriedRef(entry.ref, src);
            const value = if (entry.ref) |cell| cell.* else entry.value;
            copy.entries.appendAssumeCapacity(.{ .key = entry.key, .value = value, .ref = ref });
            if (ref) |cell| self.bindCell(cell);
            retainValue(value);
            switch (entry.key) {
                .string => |s| copy.string_index.putAssumeCapacity(s.bytes(), copy.entries.items.len - 1),
                .int => |n| if (!inherit_next) copy.noteIntKey(n),
            }
        }
        if (inherit_next and !cursor_set) copy.cursor = copy.entries.items.len;
        try self.registerCloneRefs(copy);
        return copy;
    }

    // copy-on-write separation. if `arr` is shared (refcount > 1), return an
    // unshared shallow clone the caller can mutate in place; the caller MUST
    // store the result back into the owning slot/property/element. the original
    // loses the writer's reference (refcount-1, never reaches 0 here since it
    // was > 1). sole owners pass through untouched - the common case, ~free.
    // this is what makes copyValue/transferArg able to share arrays instead of
    // deep-cloning: the clone is deferred to the first in-place write
    pub fn cowSeparate(self: *VM, arr: *PhpArray) RuntimeError!*PhpArray {
        // $GLOBALS is a live view of the global symbol table - it is a durable
        // VM root (extra retain) AND held by frame.vars['$GLOBALS'], so its
        // refcount is always >1. it must NEVER be separated: a write to
        // $GLOBALS['x'] must land in the canonical array, not a private copy
        if (self.globals_array) |ga| {
            if (arr == ga) return arr;
        }
        if (arr.refcount <= 1) return arr;
        // the clone starts with one reference for the slot that will take it;
        // storing it into that slot releases the original through the normal
        // overwrite-release path
        const clone = try self.shallowCloneCow(arr);
        clone.refcount = 1;
        return clone;
    }

    pub fn cloneArray(self: *VM, src: *PhpArray) RuntimeError!*PhpArray {
        // shallow fast path: when the source has no nested arrays we can
        // copy without any cycle tracking. covers the overwhelming majority
        // of php arrays. cloneArrayDeep only runs when at least one entry
        // is an array, where cycles become possible.
        var has_nested = false;
        for (src.entries.items) |entry| {
            if (entry.ref != null) return try self.shallowCloneCow(src);
            if (entry.value == .array) {
                has_nested = true;
                break;
            }
        }
        if (!has_nested) return try self.cloneArrayFlat(src);
        var visited: std.AutoHashMapUnmanaged(*PhpArray, *PhpArray) = .{};
        defer visited.deinit(self.allocator);
        return try self.cloneArrayInner(src, &visited);
    }

    fn cloneArrayFlat(self: *VM, src: *PhpArray) RuntimeError!*PhpArray {
        const copy = self.allocArray() catch return error.RuntimeError;
        copy.* = .{ .next_int_key = src.next_int_key, .has_int_keys = src.has_int_keys, .cursor = src.cursor };
        copy.entries.ensureTotalCapacity(self.allocator, src.entries.items.len) catch return error.RuntimeError;
        for (src.entries.items, 0..) |entry, i| {
            if (entry.key == .string) entry.key.string.retain();
            const ref = carriedRef(entry.ref, src);
            copy.entries.appendAssumeCapacity(.{ .key = entry.key, .value = entry.value, .ref = ref });
            if (ref) |cell| self.bindCell(cell);
            // The clone owns every heap value copied into its entries.
            retainValue(entry.value);
            if (entry.key == .string) {
                copy.string_index.put(self.allocator, entry.key.string.bytes(), i) catch return error.RuntimeError;
            }
        }
        try self.registerCloneRefs(copy);
        return copy;
    }

    fn cloneArrayInner(
        self: *VM,
        src: *PhpArray,
        visited: *std.AutoHashMapUnmanaged(*PhpArray, *PhpArray),
    ) RuntimeError!*PhpArray {
        if (visited.get(src)) |existing| return existing;
        const copy = self.allocArray() catch return error.RuntimeError;
        copy.* = .{ .next_int_key = src.next_int_key, .has_int_keys = src.has_int_keys, .cursor = src.cursor };
        visited.put(self.allocator, src, copy) catch return error.RuntimeError;
        copy.entries.ensureTotalCapacity(self.allocator, src.entries.items.len) catch return error.RuntimeError;
        for (src.entries.items, 0..) |entry, i| {
            const cloned_value: Value = if (entry.value == .array) blk: {
                // a nested array is itself deep-cloned; the parent clone holds
                // the nested clone as one reference - retain it
                const nested = try self.cloneArrayInner(entry.value.array, visited);
                arrayRetain(nested);
                break :blk Value{ .array = nested };
            } else entry.value;
            // every copied non-array heap value is a new reference from the clone
            if (cloned_value != .array) retainValue(cloned_value);
            if (entry.key == .string) entry.key.string.retain();
            const ref = carriedRef(entry.ref, src);
            copy.entries.appendAssumeCapacity(.{ .key = entry.key, .value = cloned_value, .ref = ref });
            if (ref) |cell| self.bindCell(cell);
            if (entry.key == .string) {
                copy.string_index.put(self.allocator, entry.key.string.bytes(), i) catch return error.RuntimeError;
            }
        }
        try self.registerCloneRefs(copy);
        return copy;
    }

    pub fn copyValue(self: *VM, val: Value) RuntimeError!Value {
        // object/gen/fiber handles copy with retain. arrays now use copy-on-
        // write: share the underlying PhpArray (retain) and defer the actual
        // copy to the first in-place mutation, which separates via cowSeparate
        // at the lvalue site. self is unused on the share path but kept so this
        // stays a *VM method (called as self.copyValue everywhere)
        if (val == .array and val.array.weak) {
            const copy = try self.shallowCloneCow(val.array);
            arrayRetain(copy);
            return .{ .array = copy };
        }
        if (val == .string) {
            val.string.retain();
            return val;
        }
        if (val == .object or val == .resource) {
            objRetain(if (val == .object) val.object else val.resource);
            return val;
        }
        if (val == .generator) {
            genRetain(val.generator);
            return val;
        }
        if (val == .fiber) {
            fiberRetain(val.fiber);
            return val;
        }
        if (val != .array) return val;
        // COW: share the array (retain) instead of deep-cloning; the first
        // in-place write through any lvalue site separates it (cowSeparate)
        arrayRetain(val.array);
        return val;
    }

    // transfer an operand-stack value into a callee binding ($this, a
    // parameter, a variadic rest element) under the Stage 1 move model:
    // arrays are cloned (PHP value semantics), but an object is MOVED - the
    // caller's operand-stack retain transfers into the binding, so NO new
    // retain is taken here. the matching release is the callee frame teardown
    // (releaseFrameObjects / fast_loop return). this is copyValue minus the
    // object retain - it keeps call cleanup able to raw-drop the stack slots
    fn cloneArrayValue(self: *VM, val: Value) RuntimeError!Value {
        if (val != .array) return val;
        return .{ .array = try self.cloneArray(val.array) };
    }

    pub fn bindFrameArg(_: *VM, val: Value) RuntimeError!Value {
        return val;
    }

    fn markOwnedArrayArgs(self: *VM, frame_idx: usize, frame: *CallFrame) RuntimeError!void {
        const func = frame.func orelse return;
        // arguments living only in slots have no named entry to own
        if (frame.vars.count() == 0) return;
        const count = if (self.ic) |ic| blk: {
            const raw = ic.arg_counts[frame_idx];
            break :blk if (raw == unknown_arg_count) func.arity else @min(@as(usize, raw), func.arity);
        } else func.arity;
        for (func.params[0..@min(count, func.params.len)], 0..) |param, i| {
            const val = frame.vars.get(param) orelse continue;
            if (val != .array) continue;
            arrayRetain(val.array);
            frame.owned_array_args[i / 64] |= @as(u64, 1) << @intCast(i % 64);
        }
    }

    fn copyCapturedValue(self: *VM, val: Value) RuntimeError!Value {
        return self.cloneArrayValue(val);
    }

    // a clone's property: its own copy of an array, and its own reference to
    // anything counted
    fn copyObjectCloneValue(self: *VM, val: Value) RuntimeError!Value {
        if (val == .array) return self.cloneArrayValue(val);
        return self.copyValue(val);
    }

    fn preparePropertyStore(self: *VM, val: Value) RuntimeError!Value {
        if (val == .array and val.array.refcount == 0) return val;
        return self.cloneArrayValue(val);
    }

    pub fn makeContext(self: *VM, call_name: ?[]const u8) NativeContext {
        return .{ .allocator = self.allocator, .arrays = &self.arrays, .strings = &self.strings, .vm = self, .call_name = call_name };
    }

    // invoke a native, keeping its OBJECT arguments retained for the
    // duration of the call. the call-site dispatch copies the args into a
    // buffer and dropN's them off the operand stack BEFORE running the
    // native, so a temporary object arg (e.g. `iterator_apply(new
    // ArrayIterator(...), ...)`) sits at refcount 0 while the native runs;
    // a native that invokes a user callback then triggers a drain that
    // destructs the still-needed argument. objects only: the operand stack
    // does not own arrays and a refcount-0 array arg is never queued, so it
    // cannot be freed mid-native - retaining arrays here would instead
    // QUEUE them (releaseValue queues at 0) and free live data (Stage 2)
    fn invokeNative(self: *VM, native: Native, ctx: *NativeContext, call: NativeInvocation) RuntimeError!Value {
        const input_args = call.args;
        // named arguments placed for this call, past its parameters
        const named = self.native_named_args;
        self.native_named_args = null;
        ctx.named_args = named;
        if (named) |extras| arrayRetain(extras);
        defer if (named) |extras| {
            arrayUnpin(extras);
            if (extras.refcount == 0) self.queueArrayRelease(extras);
        };
        // the arguments live until the call returns, as on php's call stack,
        // even when the native runs php code that frees what it can
        for (input_args) |arg| retainValue(arg);
        defer for (input_args) |arg| self.releaseValue(arg);
        const name = call.name;
        // the call is on the native stack while it runs, so a trace made
        // inside it shows it and user code it calls back is called by an
        // internal function. call_user_func(_array) stays off it, and so do
        // strlen and count unless their argument count is wrong: php compiles
        // them to plain calls or opcodes
        const outer = self.native_call;
        defer self.native_call = outer;
        var record: NativeCall = undefined;
        const label = call.label orelse name orelse "";
        const admitted = native.arity.admits(input_args.len);
        if (!isUserCallForwarder(name) and (!admitted or !isFrameOutNative(label))) {
            // eval is a language construct to php: its frame lists no arguments
            const shown_args = if (std.mem.eql(u8, label, "eval")) &[_]Value{} else input_args;
            const from_native = if (outer) |o| o.depth == self.frame_count or (o.depth + 1 == self.frame_count and self.frames[self.frame_count - 1].native) else false;
            record = .{ .label = label, .args = shown_args, .depth = self.frame_count, .instance = call.instance, .outer = outer, .from_native = from_native };
            self.native_call = &record;
        }
        if (native.deprecated) |suffix| try self.warnDeprecatedNative(name orelse label, suffix);
        if (native.no_discard) |reason| try self.warnDiscardedNative(label, reason, outer, call.instance);
        if (!admitted) {
            var buf: [256]u8 = undefined;
            try self.setPendingException("ArgumentCountError", native.arity.describe(&buf, label, input_args.len));
            return error.RuntimeError;
        }
        var args_buf: [16]Value = undefined;
        var separated_args: ?[]Value = null;
        defer if (separated_args) |copy| self.freeStackArgs(copy, &args_buf);
        var native_args = input_args;
        // only a call whose arguments recorded provenance can bind an output
        // position; by-value sites skip the name lookup entirely
        const sources = self.callerArgSources(input_args.len);
        if (name) |n| if (sources.len > 0 and byref_args.hasByRefParams(n)) {
            for (sources, 0..) |source, i| {
                if (source != .cell or !byref_args.isByRef(n, i)) continue;
                // array_multisort's variadic integers are flags, not outputs
                const base = if (std.mem.lastIndexOfScalar(u8, n, '\\')) |pos| n[pos + 1 ..] else n;
                if (std.ascii.eqlIgnoreCase(base, "array_multisort") and input_args[i] != .array) continue;
                try self.checkArgCell(source.cell.denial);
            }
            if (sources.len > 0 and sources[0] != .none and input_args[0] == .array and input_args[0].array.refcount > 1 and byref_args.arg0IsByRef(n)) {
                const separated: Value = .{ .array = try self.shallowCloneCow(input_args[0].array) };
                const copy = try self.copyStackArgs(&args_buf, input_args);
                copy[0] = separated;
                separated_args = copy;
                native_args = copy;
                ctx.setCallerVar(0, native_args.len, separated);
            }
        };
        for (native_args) |a| stackRetain(a);
        defer for (native_args) |a| self.stackRelease(a);
        // an array argument with no durable owner (a literal, a call result)
        // was queued when its stack slot was consumed; a callback the native
        // runs would drain and free it mid-iteration. pin it for the call and
        // re-queue it afterwards if it is still unowned. a by-reference first
        // argument is an alias of the caller's variable, not a value copy
        const byref_arg0 = native_args.len > 0 and native_args[0] == .array and name != null and byref_args.arg0IsByRef(name.?);
        for (native_args) |a| if (a == .array) arrayRetain(a.array);
        if (byref_arg0) native_args[0].array.byref_pins +|= 1;
        defer {
            if (byref_arg0) native_args[0].array.byref_pins -|= 1;
            for (native_args) |a| if (a == .array) {
                arrayUnpin(a.array);
                if (a.array.refcount == 0) self.queueArrayRelease(a.array);
            };
        }
        // scalar parameters take their coerced values, in order, up to the
        // first callable or array parameter, which are checked next;
        // resolving a callable may autoload, which runs php
        const checked_kinds = native.callbacks | native.arrays;
        const called_by_native = self.forwarding_depth == self.frame_count or if (outer) |o| o.depth == self.frame_count else false;
        const first_checked: usize = if (checked_kinds == 0) native_args.len else @min(native_args.len, @ctz(checked_kinds));
        if (native.scalars.positions != 0) if (name) |n| {
            if (try self.scalarArgsNeedCoercion(native.scalars, native_args)) {
                if (separated_args == null) {
                    const copy = try self.copyStackArgs(&args_buf, native_args);
                    separated_args = copy;
                    native_args = copy;
                }
                try self.coerceScalarArgs(n, label, native.scalars, separated_args.?, 0, first_checked, called_by_native);
            }
        };
        if (native.callbacks != 0 or native.arrays != 0) if (name) |n| try self.checkCallbackArgs(n, label, native.callbacks, native.arrays, native_args);
        if (native.scalars.positions != 0 and first_checked < native_args.len) if (name) |n| {
            if (separated_args) |copy| try self.coerceScalarArgs(n, label, native.scalars, copy, first_checked, copy.len, called_by_native);
        };
        // an object php can't make a string of, given for a string parameter
        if (native.strings != 0) if (name) |n| for (native_args, 0..) |arg, i| {
            if (arg == .object and i < 31 and native.strings & (@as(u32, 1) << @intCast(i)) != 0) try self.refuseObjectForString(n, label, i, arg.object);
        };
        // zend_forbid_dynamic_call, after the arguments are parsed
        if (call.dynamic) if (name) |n| if (forbidsDynamicCall(n)) {
            const msg = try std.fmt.allocPrint(self.allocator, "Cannot call {s}() dynamically", .{n});
            defer self.allocator.free(msg);
            try self.setPendingException("Error", msg);
            return error.RuntimeError;
        };
        const outer_forwarding = self.forwarding_depth;
        defer self.forwarding_depth = outer_forwarding;
        // a native call_user_func makes is called by it; a user function it
        // calls resets this for what it calls in turn by adding a frame
        self.forwarding_depth = if (isUserCallForwarder(name)) self.frame_count else std.math.maxInt(usize);
        const result = try native.call(ctx, native_args);
        if (self.ic) |ic| if (ic.ref_write_refused) {
            ic.ref_write_refused = false;
            if (self.pending_exception != null) {
                self.releaseValue(result.value);
                return error.RuntimeError;
            }
        };
        return result.value;
    }

    pub fn refuseRefWrite(self: *VM) void {
        if (self.ic) |ic| ic.ref_write_refused = true;
    }

    pub fn bindClosures(self: *VM, vars: *std.StringHashMapUnmanaged(Value), ref_slots: ?*std.StringHashMapUnmanaged(*Value), name: []const u8) !void {
        if (self.getCaptureRange(name)) |cr| {
            const caps = self.captures.items[cr.start .. cr.start + cr.len];
            for (caps) |cap| {
                if (std.mem.eql(u8, cap.var_name, "$__closure_scope")) continue;
                if (std.mem.eql(u8, cap.var_name, "$__closure_defclass")) continue;
                if (cap.ref_cell) |cell| {
                    if (ref_slots) |rs| try self.bindRefSlot(rs, cap.var_name, cell);
                } else {
                    try vars.put(self.allocator, cap.var_name, try self.copyCapturedValue(cap.value));
                }
            }
        }

        if (self.frame_count > 0) {
            const orig_name = self.getOrigClosureName(name);
            if (self.functions.get(orig_name)) |func| {
                if (func.is_arrow) {
                    const parent = &self.frames[self.frame_count - 1];
                    var it = parent.vars.iterator();
                    while (it.next()) |entry| {
                        if (!vars.contains(entry.key_ptr.*)) {
                            try vars.put(self.allocator, entry.key_ptr.*, try self.copyCapturedValue(entry.value_ptr.*));
                        }
                    }
                }
            }
        }
    }

    pub fn getOrigClosureName(self: *VM, name: []const u8) []const u8 {
        _ = self;
        if (!std.mem.startsWith(u8, name, "__closure_")) return name;
        // runtime instance names have format __closure_N_M, compile name is __closure_N
        const after_prefix = name["__closure_".len..];
        if (std.mem.lastIndexOf(u8, after_prefix, "_")) |last_us| {
            return name[0 .. "__closure_".len + last_us];
        }
        return name;
    }

    fn bindArgs(self: *VM, vars: *std.StringHashMapUnmanaged(Value), func: *const ObjFunction, args: []const Value) !void {
        if (func.is_variadic and func.arity > 0) {
            const fixed: usize = func.arity - 1;
            const bind_fixed = @min(args.len, fixed);
            for (0..bind_fixed) |i| {
                try vars.put(self.allocator, func.params[i], try self.bindFrameArg(args[i]));
            }
            for (bind_fixed..fixed) |i| {
                if (i < func.defaults.len) try vars.put(self.allocator, func.params[i], try self.resolveParamDefault(func, i));
            }
            const rest = try self.allocArray();
            for (bind_fixed..args.len) |i| {
                try rest.append(self.allocator, try self.bindFrameArg(args[i]));
            }
            if (self.pending_named_extras) |extras| {
                self.pending_named_extras = null;
                for (extras.entries.items) |entry| try rest.set(self.allocator, entry.key, try self.bindFrameArg(entry.value));
            }
            try vars.put(self.allocator, func.params[fixed], .{ .array = rest });
            return;
        }
        for (0..args.len) |i| {
            try vars.put(self.allocator, func.params[i], try self.bindFrameArg(args[i]));
        }
        try self.fillDefaults(vars, func, args.len);
    }

    // a parameter's default, resolved when a call leaves the argument out; an
    // error it raises is located at the function, as php locates it
    pub fn resolveParamDefault(self: *VM, func: *const ObjFunction, index: usize) !Value {
        const ic = self.ic.?;
        const saved = ic.default_site;
        ic.default_site = func;
        defer ic.default_site = saved;
        const raw = func.defaults[index];
        if (raw == .string) if (bytecode.paramDefaultInitializerParts(raw.string.bytes())) |pd| {
            const value = try self.evaluateParamDefault(func, pd.name);
            return self.checkEvaluatedDefault(func, index, value);
        };
        const value = try self.resolveDefault(raw);
        // a default php could not fold is checked against the parameter's
        // type once evaluated (RECV_INIT)
        if (raw == .string and raw.string.len > 0 and raw.string.bytes()[0] == 0) return self.checkEvaluatedDefault(func, index, value);
        return value;
    }

    pub const DefaultHold = struct { value: Value, depth: usize };

    // resolveParamDefault for a call's own defaults: a value an initializer
    // returned is held until releaseDefaultHolds, as the stack holds an
    // argument until the frame has taken it
    pub fn resolveParamDefaultHeld(self: *VM, func: *const ObjFunction, index: usize) !Value {
        const value = try self.resolveParamDefault(func, index);
        const raw = func.defaults[index];
        if (raw == .string and bytecode.paramDefaultInitializerParts(raw.string.bytes()) != null) {
            retainValue(value);
            try self.default_holds.append(self.allocator, .{ .value = value, .depth = self.frame_count });
        }
        return value;
    }

    // the holds of the defaults evaluated at this depth go back to pending
    // releases, as an argument's do when the call drops the stack slots
    pub fn releaseDefaultHolds(self: *VM) void {
        while (self.default_holds.items.len > 0) {
            const hold = self.default_holds.items[self.default_holds.items.len - 1];
            if (hold.depth != self.frame_count) break;
            _ = self.default_holds.pop();
            switch (hold.value) {
                .array => |arr| {
                    arr.refcount -|= 1;
                    if (arr.refcount == 0) self.queueArrayRelease(arr);
                },
                else => self.stackRelease(hold.value),
            }
        }
    }

    // a default compiled to an initializer, run in the function's class scope
    // (RECV_INIT evaluating its constant expression)
    fn evaluateParamDefault(self: *VM, func: *const ObjFunction, name: []const u8) RuntimeError!Value {
        if (self.resolving_quietly) return error.RuntimeError;
        const floor = self.handler_floor;
        self.handler_floor = self.handler_count;
        defer self.handler_floor = floor;
        const scope = self.functionScope(func.name) orelse "";
        // the call's result is borrowed; the frame's local owns the default
        return self.callByName(name, &.{.{ .string = Value.String.borrowed(scope) }});
    }

    fn checkEvaluatedDefault(self: *VM, func: *const ObjFunction, index: usize, value: Value) RuntimeError!Value {
        const ti = self.typeInfoFor(func.name) orelse return value;
        if (index >= ti.param_types.len or ti.param_types[index].len == 0) return value;
        const type_str = ti.param_types[index];
        if (try self.verifyDeclaredType(value, type_str, self.functionScope(func.name), func.strict_types)) |accepted| return accepted;
        var cs_file: []const u8 = self.file_path;
        var cs_line: u32 = 0;
        if (self.frame_count >= 1) {
            const caller = &self.frames[self.frame_count - 1];
            if (caller.script_path.len > 0) cs_file = caller.script_path else if (caller.func) |cf| if (cf.file_path.len > 0) {
                cs_file = cf.file_path;
            };
            const cip: usize = if (caller.ip > 0) caller.ip - 1 else 0;
            if (self.sourceLocation(caller.chunk, cip)) |loc| cs_line = loc.line;
        }
        const raw_param = if (index < func.params.len) func.params[index] else "";
        const param_name = if (raw_param.len > 0 and raw_param[0] == '$') raw_param[1..] else raw_param;
        const msg = try std.fmt.allocPrint(self.allocator, "{s}(): Argument #{d} (${s}) must be of type {s}, {s} given, called in {s} on line {d}", .{ try self.callableDisplayName(func.name, func), index + 1, param_name, try self.resolvedTypeText(type_str, self.functionScope(func.name)), valueTypeName(value), cs_file, cs_line });
        defer self.allocator.free(msg);
        const at: ?SourcePosition = if (func.file_path.len > 0) SourcePosition{ .file = func.file_path, .line = func.start_line } else null;
        const exc = try self.newBuiltinException("TypeError", msg, at);
        try self.prependCallToTrace(exc, func, &.{});
        self.raise(.{ .object = exc });
        return error.RuntimeError;
    }

    // the defaults of the parameters a call left out, into a frame's locals
    // from slot `offset`. when one raises, the locals are given back, since
    // the frame is never entered, and the error lands in this loop's nearest
    // catch as a type check's does: true means it did and the call is over
    fn fillDefaultLocals(self: *VM, func: *const ObjFunction, locals: []Value, bound: usize, offset: usize) RuntimeError!bool {
        const ic = self.ic.?;
        const saved_args = ic.default_args;
        ic.default_args = locals[offset..][0..bound];
        defer ic.default_args = saved_args;
        defer self.releaseDefaultHolds();
        for (bound..func.arity) |i| {
            if (i >= func.defaults.len) continue;
            locals[i + offset] = self.resolveParamDefaultHeld(func, i) catch |err| {
                self.freeLocals(locals);
                const pending = self.pending_exception orelse return err;
                if (pending != .object) return err;
                self.pending_exception = null;
                defer self.stackRelease(pending);
                if (self.throwObject(pending.object)) return true;
                return error.RuntimeError;
            };
        }
        return false;
    }

    // as fillDefaultLocals, for a call made on behalf of a native: the error
    // stays pending for the native's caller
    fn fillDefaultLocalsForCaller(self: *VM, func: *const ObjFunction, locals: []Value, bound: usize, offset: usize) RuntimeError!void {
        const ic = self.ic.?;
        const saved_args = ic.default_args;
        ic.default_args = locals[offset..][0..bound];
        defer ic.default_args = saved_args;
        defer self.releaseDefaultHolds();
        for (bound..func.arity) |i| {
            if (i >= func.defaults.len) continue;
            locals[i + offset] = self.resolveParamDefaultHeld(func, i) catch |err| {
                self.freeLocals(locals);
                return err;
            };
        }
    }

    fn unresolvedDefault(self: *VM, comptime fmt: []const u8, args: anytype) RuntimeError!Value {
        if (self.resolving_quietly) return error.RuntimeError;
        self.bare_default_failed = true;
        const msg = try std.fmt.allocPrint(self.allocator, fmt, args);
        defer self.allocator.free(msg);
        const site = self.ic.?.default_site;
        const at: ?SourcePosition = if (site) |func| .{ .file = func.file_path, .line = func.start_line } else null;
        const exc = try self.newBuiltinException("Error", msg, at);
        // php evaluates the default in the callee's frame (RECV_INIT)
        if (site) |func| try self.prependCallToTrace(exc, func, self.ic.?.default_args);
        self.raise(.{ .object = exc });
        return error.RuntimeError;
    }

    pub fn resolveDefault(self: *VM, val: Value) !Value {
        if (val.isEmptyArrayDefault()) {
            const arr = try self.allocArray();
            return .{ .array = arr };
        }
        if (val == .array) {
            const arr = try self.allocArray();
            for (val.array.entries.items) |entry| {
                // entries may themselves be deferred sentinels (constant refs,
                // class constants, nested arrays) - resolve key and value
                var key = entry.key;
                if (key == .string and key.string.len > 4 and
                    key.string.bytes()[0] == 0 and key.string.bytes()[1] == 'C' and
                    key.string.bytes()[2] == 'C' and key.string.bytes()[3] == 0)
                {
                    key = Value.toArrayKey(try self.resolveDefault(.{ .string = key.string }));
                }
                try arr.set(self.allocator, key, try self.resolveDefault(entry.value));
            }
            return .{ .array = arr };
        }
        if (val == .string) {
            const managed = val.string;
            const s = managed.bytes();
            if (s.len > 4 and s[0] == 0 and s[1] == 'C' and s[2] == 'C' and s[3] == 0) {
                const rest = s[4..];
                if (std.mem.lastIndexOfScalar(u8, rest, 0)) |sep| {
                    const class_name = rest[0..sep];
                    const const_name = rest[sep + 1 ..];
                    if (class_name.len == 0) {
                        if (self.php_constants.get(const_name)) |v| return v;
                        // PHP namespace fallback: a bare constant default in a
                        // namespaced function ($x = PHP_INT_MAX inside namespace
                        // Foo) is stored qualified (Foo\PHP_INT_MAX) but must fall
                        // back to the global constant - mirrors the constant opcode
                        if (std.mem.lastIndexOfScalar(u8, const_name, '\\')) |nsep| {
                            if (self.php_constants.get(const_name[nsep + 1 ..])) |v| return v;
                        }
                        return self.unresolvedDefault("Undefined constant \"{s}\"", .{const_name});
                    }
                    // Name::class, resolved while compiling
                    if (std.mem.eql(u8, const_name, "class") and !std.ascii.eqlIgnoreCase(class_name, "self") and
                        !std.ascii.eqlIgnoreCase(class_name, "parent") and !std.ascii.eqlIgnoreCase(class_name, "static"))
                        return .{ .string = Value.String.borrowed(class_name) };
                    if (self.getClassConstant(class_name, const_name)) |v| return v;
                    if (self.pending_exception != null) return error.RuntimeError;
                    // fall back to class constants (ClassName::CONST_NAME)
                    var buf: [512]u8 = undefined;
                    if (std.fmt.bufPrint(&buf, "{s}::{s}", .{ class_name, const_name })) |full| {
                        if (self.php_constants.get(full)) |v| return v;
                    } else |_| {}
                    if (!self.classes.contains(class_name) and !self.interfaces.contains(class_name)) {
                        return self.unresolvedDefault("Class \"{s}\" not found", .{class_name});
                    }
                    return self.unresolvedDefault("Undefined constant {s}::{s}", .{ class_name, const_name });
                }
            }
            // deferred new-expression default: "\x00NW\x00<8 byte ptr>"
            if (bytecode.newDefaultPtr(s)) |nd| {
                if (self.resolving_quietly) return error.RuntimeError;
                return self.instantiateForDefault(nd);
            }
            // deferred compound const-expression default: "\x00DX\x00<8 byte ptr>"
            if (bytecode.deferredExprPtr(s)) |de| {
                return self.resolveDeferredExpr(de);
            }
        }
        return val;
    }

    // an attribute's argument as stored: a value, a deferred default, or
    // the initializer of an expression, run in the scope class ("" for none)
    pub fn attributeArgumentValue(self: *VM, stored: Value, scope: []const u8) RuntimeError!Value {
        if (stored == .string) {
            if (bytecode.attrArgumentInitializerName(stored.string.bytes())) |name| return self.evaluateAttributeArgument(name, scope);
        }
        return self.resolveDefault(stored);
    }

    fn evaluateAttributeArgument(self: *VM, name: []const u8, scope: []const u8) RuntimeError!Value {
        const floor = self.handler_floor;
        self.handler_floor = self.handler_count;
        defer self.handler_floor = floor;
        const evaluating = self.frame_count;
        const value = self.callByName(name, &.{.{ .string = Value.String.borrowed(scope) }}) catch |err| {
            // the expression belongs to the reflection call, not a frame of its own
            if (self.pending_exception) |exc| if (exc == .object) try self.stampThrowableBelow(exc.object, evaluating);
            return err;
        };
        return value;
    }

    fn resolveDeferredExpr(self: *VM, de: *const bytecode.DeferredExpr) RuntimeError!Value {
        const lhs = try self.resolveDefault(de.lhs);
        if (de.op == .neg) {
            return switch (lhs) {
                .int => |v| Value{ .int = -%v },
                .float => |v| Value{ .float = -v },
                else => Value{ .int = -%Value.toInt(lhs) },
            };
        }
        if (de.op == .bnot) return Value{ .int = ~Value.toInt(lhs) };
        if (de.op == .not) return Value{ .bool = !lhs.isTruthy() };
        const rhs = try self.resolveDefault(de.rhs);
        return switch (de.op) {
            .bor => Value{ .int = Value.toInt(lhs) | Value.toInt(rhs) },
            .band => Value{ .int = Value.toInt(lhs) & Value.toInt(rhs) },
            .bxor => Value{ .int = Value.toInt(lhs) ^ Value.toInt(rhs) },
            .shl => blk: {
                const sh = Value.toInt(rhs);
                if (sh < 0 or sh >= 64) break :blk Value{ .int = 0 };
                break :blk Value{ .int = Value.toInt(lhs) << @intCast(sh) };
            },
            .shr => blk: {
                const sh = Value.toInt(rhs);
                if (sh < 0 or sh >= 64) break :blk Value{ .int = 0 };
                break :blk Value{ .int = Value.toInt(lhs) >> @intCast(sh) };
            },
            .add => Value.add(lhs, rhs),
            .sub => Value.subtract(lhs, rhs),
            .mul => Value.multiply(lhs, rhs),
            .div => Value.divide(lhs, rhs),
            .mod => Value.modulo(lhs, rhs),
            .pow => Value.power(lhs, rhs),
            .concat => blk: {
                const ls = (try self.coerceToStringValue(lhs)).string.bytes();
                const rs = (try self.coerceToStringValue(rhs)).string.bytes();
                const joined = try self.allocator.alloc(u8, ls.len + rs.len);
                @memcpy(joined[0..ls.len], ls);
                @memcpy(joined[ls.len..], rs);
                break :blk Value{ .string = try self.transientAdopted(joined) };
            },
            .neg, .bnot, .not => unreachable,
        };
    }

    fn instantiateForDefault(self: *VM, nd: *const bytecode.NewDefault) RuntimeError!Value {
        var class_name = nd.class_name;
        if (std.mem.eql(u8, class_name, "self") or std.mem.eql(u8, class_name, "static")) {
            if (self.currentDefiningClass()) |dc| class_name = dc;
        } else if (std.mem.eql(u8, class_name, "parent")) {
            if (self.parentResolvingClass()) |dc| {
                if (self.classes.get(dc)) |cls| {
                    if (cls.parent) |p| class_name = p;
                }
            }
        }
        if (!self.classes.contains(class_name)) {
            try self.tryAutoload(class_name);
        }
        if (!self.classes.contains(class_name)) {
            const msg = try self.classNotFoundMessage(class_name);
            try self.strings.append(self.allocator, msg);
            self.error_msg = msg;
            return error.RuntimeError;
        }
        const stable_class_name = try self.stableClassName(class_name);
        const obj = try self.allocObject(.{ .class_name = stable_class_name });
        try self.initObjectProperties(obj, class_name);

        var resolved_args: [16]Value = undefined;
        const n_args = @min(nd.args.len, resolved_args.len);
        for (0..n_args) |i| resolved_args[i] = try self.resolveDefault(nd.args[i]);

        if (self.resolveMethod(class_name, "__construct") catch null) |_| {
            _ = try self.callMethod(obj, "__construct", resolved_args[0..n_args]);
        }
        return .{ .object = obj };
    }

    fn fillDefaults(self: *VM, vars: *std.StringHashMapUnmanaged(Value), func: *const ObjFunction, arg_count: usize) !void {
        if (arg_count >= func.arity) return;
        defer self.releaseDefaultHolds();
        for (arg_count..func.arity) |i| {
            if (i < func.defaults.len) {
                try vars.put(self.allocator, func.params[i], try self.resolveParamDefaultHeld(func, i));
            } else {
                try vars.put(self.allocator, func.params[i], .null);
            }
        }
    }

    fn executeFunction(self: *VM, func: *const ObjFunction, vars: std.StringHashMapUnmanaged(Value)) RuntimeError!Value {
        try self.ensureCallRoom();
        const base_frame = self.frame_count;
        const base_handler = self.handler_count;
        const prev_floor = self.handler_floor;
        self.handler_floor = self.handler_count;
        try self.ensureCallRoom();
        self.frames[self.frame_count] = .{ .chunk = &func.chunk, .ip = 0, .vars = vars, .locals = try self.allocLocals(func, &vars), .func = func, .call_name = self.pending_call_name, .called_class = self.pending_called_class };
        self.frames[self.frame_count].entry_sp = self.sp;
        self.consumePendingArgCount();
        // the arguments are the new frame's alone: a call its body makes
        // must not take them for its own
        if (self.pending_invoke_args) |pia| self.saveFrameArgsSlice(pia) else self.markArgsUnsaved();
        self.pending_invoke_args = null;
        self.pending_call_name = null;
        self.pending_called_class = null;
        self.frame_count += 1;
        self.retainFrameObjects(self.frame_count - 1);
        if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;
        self.runUntilFrame(base_frame) catch |err| {
            self.handler_count = base_handler;
            self.handler_floor = prev_floor;
            self.unwindFailedCall(base_frame);
            return err;
        };
        self.handler_count = base_handler;
        self.handler_floor = prev_floor;
        return self.pop();
    }

    pub fn executeFunctionWithRefs(self: *VM, func: *const ObjFunction, vars: std.StringHashMapUnmanaged(Value), ref_slots: std.StringHashMapUnmanaged(*Value)) RuntimeError!Value {
        try self.ensureCallRoom();
        const base_frame = self.frame_count;
        const base_handler = self.handler_count;
        const prev_floor = self.handler_floor;
        self.handler_floor = self.handler_count;
        try self.ensureCallRoom();
        self.frames[self.frame_count] = .{ .chunk = &func.chunk, .ip = 0, .vars = vars, .locals = try self.allocLocals(func, &vars), .func = func, .ref_slots = ref_slots, .call_name = self.pending_call_name, .called_class = self.pending_called_class };
        self.frames[self.frame_count].entry_sp = self.sp;
        self.consumePendingArgCount();
        if (self.pending_invoke_args) |pia| self.saveFrameArgsSlice(pia);
        self.pending_invoke_args = null;
        self.pending_call_name = null;
        self.pending_called_class = null;
        self.frame_count += 1;
        self.retainFrameObjects(self.frame_count - 1);
        if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;
        self.runUntilFrame(base_frame) catch |err| {
            self.handler_count = base_handler;
            self.handler_floor = prev_floor;
            self.unwindFailedCall(base_frame);
            return err;
        };
        self.handler_count = base_handler;
        self.handler_floor = prev_floor;
        return self.pop();
    }

    // the name a variable variable's scalar value gives: ${10} is $10,
    // ${true} is $1
    fn varVarText(v: Value, buf: *[32]u8) []const u8 {
        return switch (v) {
            .string => |str| str.bytes(),
            .int => |i| std.fmt.bufPrint(buf, "{d}", .{i}) catch "",
            .bool => |b| if (b) "1" else "",
            else => "",
        };
    }

    fn varVarName(raw_name: []const u8, buf: *[256]u8) []const u8 {
        if (raw_name.len > 0 and raw_name[0] == '$') return raw_name;
        if (raw_name.len + 1 > buf.len) return raw_name;
        buf[0] = '$';
        @memcpy(buf[1 .. 1 + raw_name.len], raw_name);
        return buf[0 .. 1 + raw_name.len];
    }

    pub noinline fn valueTypeName(val: Value) []const u8 {
        return val.valueName();
    }

    pub fn tryWeakCoerce(self: *VM, val: Value, type_str: []const u8) RuntimeError!?Value {
        var t = type_str;
        if (t.len > 0 and t[0] == '?') t = t[1..];
        for (t) |c| if (c == '&' or c == '(' or c == ')') return null;
        // unions: try each member in PHP's priority order, returning the first
        // that coerces successfully without lossy conversion. PHP's rule is to
        // pick the type the value already matches; failing that, scalar values
        // prefer int > float > string > bool (and the converse for non-scalars)
        if (std.mem.indexOfScalar(u8, t, '|') != null) {
            return try self.tryWeakCoerceUnion(val, t);
        }
        return try self.tryWeakCoerceSingle(val, t);
    }

    fn numericStringFitsInt(s: []const u8) bool {
        const trimmed = std.mem.trim(u8, s, " \t\n\r\x0b\x0c");
        if (std.fmt.parseInt(i64, trimmed, 10)) |_| return true else |_| {}
        return Value.floatFitsInt(std.fmt.parseFloat(f64, trimmed) catch return false);
    }

    fn tryWeakCoerceSingle(self: *VM, val: Value, t: []const u8) RuntimeError!?Value {
        if (std.mem.eql(u8, t, "int") or std.mem.eql(u8, t, "integer")) {
            return switch (val) {
                .bool => |b| Value{ .int = if (b) @as(i64, 1) else 0 },
                .float => |f| if (Value.floatFitsInt(f)) Value{ .int = @as(i64, @intFromFloat(f)) } else null,
                .string => |s| if (Value.isNumericString(s.bytes()) and numericStringFitsInt(s.bytes())) Value{ .int = Value.toInt(val) } else null,
                else => null,
            };
        }
        if (std.mem.eql(u8, t, "float") or std.mem.eql(u8, t, "double")) {
            return switch (val) {
                .int => |i| Value{ .float = @floatFromInt(i) },
                .bool => |b| Value{ .float = if (b) @as(f64, 1) else 0 },
                .string => |s| if (Value.isNumericString(s.bytes())) Value{ .float = Value.toFloat(val) } else null,
                else => null,
            };
        }
        if (std.mem.eql(u8, t, "bool") or std.mem.eql(u8, t, "boolean")) {
            return switch (val) {
                .int => |i| Value{ .bool = i != 0 },
                .float => |f| Value{ .bool = f != 0 },
                .string => |s| Value{ .bool = !(s.len == 0 or (s.len == 1 and s.bytes()[0] == '0')) },
                .null => Value{ .bool = false },
                else => null,
            };
        }
        if (std.mem.eql(u8, t, "string")) {
            return switch (val) {
                .int, .float, .bool => try self.coerceToStringValue(val),
                else => null,
            };
        }
        return null;
    }

    // a scalar's string form as a transient: a slot that keeps it takes a
    // reference, anything else reads it before the next statement boundary
    fn coerceToStringValue(self: *VM, val: Value) RuntimeError!Value {
        return .{ .string = try self.transientFormatted(val) };
    }

    // PHP weak-mode union resolution. for a value V against `int|float|string|bool`,
    // PHP checks types in this order: int, float, string, bool. the first type
    // V already matches wins; otherwise the first coercible match wins. when
    // multiple coercions could succeed (e.g. "5" against int|float), int wins
    // since it appears first in the priority order
    fn tryWeakCoerceUnion(self: *VM, val: Value, t: []const u8) RuntimeError!?Value {
        const priority = [_][]const u8{ "int", "float", "string", "bool" };

        // first pass: exact match (no coercion)
        var iter = std.mem.tokenizeScalar(u8, t, '|');
        while (iter.next()) |member| {
            const m = std.mem.trim(u8, member, " \t");
            if (self.checkSingleType(val, m)) return val;
        }

        // second pass: scalar coercion in priority order, but only for types
        // listed in the union
        for (priority) |p| {
            var iter2 = std.mem.tokenizeScalar(u8, t, '|');
            while (iter2.next()) |member| {
                const m = std.mem.trim(u8, member, " \t");
                const canonical: []const u8 = if (std.mem.eql(u8, m, "integer")) "int" else if (std.mem.eql(u8, m, "double")) "float" else if (std.mem.eql(u8, m, "boolean")) "bool" else m;
                if (!std.mem.eql(u8, canonical, p)) continue;
                if (try self.tryWeakCoerceSingle(val, canonical)) |coerced| return coerced;
            }
        }
        return null;
    }

    // mirror native is_callable: validates that a value can actually be
    // invoked (function name resolves, [obj,method] exists, __invoke on
    // object, etc.). used by the 'callable' parameter-type check to
    // surface TypeError at the call site instead of an undefined-function
    // fatal inside the callee
    // php's is_callable, judged from the current scope: a class may use its
    // own private and protected methods, a method it cannot reach is still
    // callable through __call/__callStatic, and a non-static method named
    // through its class is callable only with a compatible $this in scope
    pub fn isValueCallable(self: *VM, val: Value) bool {
        switch (val) {
            .string => |str| {
                const raw = str.bytes();
                const name = if (raw.len > 0 and raw[0] == '\\') raw[1..] else raw;
                if (std.mem.indexOf(u8, name, "::")) |sep| return self.isMethodCallable(.null, name[0..sep], name[sep + 2 ..]);
                return self.functionExists(name);
            },
            .object => |obj| return std.mem.eql(u8, obj.class_name, "Closure") or self.hasMethod(obj.class_name, "__invoke"),
            .array => |arr| {
                if (arr.entries.items.len != 2) return false;
                const target = arr.entries.items[0].value;
                const method_val = arr.entries.items[1].value;
                if (method_val != .string) return false;
                const class_name = switch (target) {
                    .object => |obj| obj.class_name,
                    .string => |cs| if (cs.len > 0 and cs.bytes()[0] == '\\') cs.bytes()[1..] else cs.bytes(),
                    else => return false,
                };
                return self.isMethodCallable(target, class_name, method_val.string.bytes());
            },
            else => return false,
        }
    }

    // target is the object in [$obj, 'm'], or null for a class-named callable
    fn isMethodCallable(self: *VM, target: Value, class_name: []const u8, method: []const u8) bool {
        const this = if (target == .object) target.object else self.scopeThis();
        const has_instance = if (this) |t| self.isInstanceOf(t.class_name, class_name) else false;
        const magic: []const u8 = if (has_instance) "__call" else "__callStatic";
        if (!self.hasMethod(class_name, method)) return self.hasMethod(class_name, magic);
        const vis = self.findMethodVisibility(class_name, method);
        if (!self.checkVisibility(vis.defining_class, vis.visibility)) return self.hasMethod(class_name, magic);
        if (has_instance) return true;
        const cdef = self.classes.getPtr(vis.defining_class) orelse return true;
        const info = cdef.methods.get(method) orelse return true;
        return info.is_static;
    }

    // $this of the running frame, whether it lives in the vars map or a slot
    pub fn scopeThis(self: *VM) ?*PhpObject {
        if (self.frame_count == 0) return null;
        const frame = self.currentFrame();
        if (frame.vars.get("$this")) |v| return if (v == .object) v.object else null;
        const func = frame.func orelse return null;
        for (func.slot_names, 0..) |name, i| {
            if (!std.mem.eql(u8, name, "$this")) continue;
            if (i < frame.locals.len and frame.locals[i] == .object) return frame.locals[i].object;
            return null;
        }
        return null;
    }

    noinline fn checkSingleType(self: *VM, val: Value, type_name: []const u8) bool {
        if (std.mem.eql(u8, type_name, "mixed")) return true;
        if (std.mem.eql(u8, type_name, "void")) return val == .null;
        if (std.mem.eql(u8, type_name, "int") or std.mem.eql(u8, type_name, "integer")) return val == .int;
        if (std.mem.eql(u8, type_name, "float") or std.mem.eql(u8, type_name, "double")) return val == .float or val == .int;
        if (std.mem.eql(u8, type_name, "bool") or std.mem.eql(u8, type_name, "boolean")) return val == .bool or val == .int;
        if (std.mem.eql(u8, type_name, "string")) {
            if (val == .string) return true;
            if (val == .object and self.hasMethod(val.object.class_name, "__toString")) return true;
            return false;
        }
        if (std.mem.eql(u8, type_name, "array")) return val == .array;
        if (std.mem.eql(u8, type_name, "callable")) return self.isValueCallable(val);
        if (std.mem.eql(u8, type_name, "null")) return val == .null;
        if (std.mem.eql(u8, type_name, "false")) return val == .bool and !val.bool;
        if (std.mem.eql(u8, type_name, "true")) return val == .bool and val.bool;
        if (std.mem.eql(u8, type_name, "object")) return val == .object;
        if (std.mem.eql(u8, type_name, "iterable")) {
            if (val == .array or val == .generator) return true;
            if (val == .object) {
                if (self.hasMethod(val.object.class_name, "getIterator")) return true;
                if (self.isInstanceOf(val.object.class_name, "Iterator")) return true;
                if (self.isInstanceOf(val.object.class_name, "IteratorAggregate")) return true;
                if (self.isInstanceOf(val.object.class_name, "Traversable")) return true;
            }
            return false;
        }
        if (std.mem.eql(u8, type_name, "self") or std.mem.eql(u8, type_name, "static") or std.mem.eql(u8, type_name, "parent")) return val == .object;
        if (std.mem.eql(u8, type_name, "Traversable") or std.mem.eql(u8, type_name, "Iterator") or std.mem.eql(u8, type_name, "IteratorAggregate")) {
            return val == .object or val == .array or val == .generator;
        }
        if (std.mem.eql(u8, type_name, "Generator")) return val == .generator;
        if (std.mem.eql(u8, type_name, "Fiber")) return val == .fiber;
        if (std.mem.eql(u8, type_name, "Closure")) {
            return val == .object and std.mem.eql(u8, val.object.class_name, "Closure");
        }
        if (val == .object) {
            // a leading backslash in a type name (e.g. `\DOMNode`) is a fully-qualified
            // marker carried over from the source; class names in the registry never
            // include it. strip it before the instanceof walk
            const stripped = if (type_name.len > 0 and type_name[0] == '\\') type_name[1..] else type_name;
            return self.isInstanceOf(val.object.class_name, stripped);
        }
        return false;
    }

    pub noinline fn checkTypeMatch(self: *VM, val: Value, type_str: []const u8) bool {
        if (type_str.len == 0) return true;
        if (type_str[0] == '?') {
            if (val == .null) return true;
            return self.checkTypeMatch(val, type_str[1..]);
        }
        // top-level union: split on '|' respecting parens
        var depth: i32 = 0;
        var start: usize = 0;
        for (type_str, 0..) |c, i| {
            if (c == '(') depth += 1 else if (c == ')') depth -= 1 else if (c == '|' and depth == 0) {
                if (self.checkIntersection(val, type_str[start..i])) return true;
                start = i + 1;
            }
        }
        return self.checkIntersection(val, type_str[start..]);
    }

    noinline fn checkIntersection(self: *VM, val: Value, expr: []const u8) bool {
        if (expr.len == 0) return true;
        var s = expr;
        if (s.len >= 2 and s[0] == '(' and s[s.len - 1] == ')') s = s[1 .. s.len - 1];
        var depth: i32 = 0;
        var start: usize = 0;
        for (s, 0..) |c, i| {
            if (c == '(') depth += 1 else if (c == ')') depth -= 1 else if (c == '&' and depth == 0) {
                if (!self.checkSingleType(val, s[start..i])) return false;
                start = i + 1;
            }
        }
        return self.checkSingleType(val, s[start..]);
    }

    fn declaredParamTypes(self: *VM, name: []const u8) []const []const u8 {
        return (self.typeInfoFor(name) orelse return &.{}).param_types;
    }

    // a closure instance (__closure_N_M) carries the types its compiled
    // function (__closure_N) declared
    pub fn typeInfoFor(self: *VM, name: []const u8) ?TypeInfo {
        if (g_type_info.get(name)) |ti| return ti;
        if (!std.mem.startsWith(u8, name, "__closure_")) return null;
        const func = self.functions.get(name) orelse return null;
        if (func.name.ptr == name.ptr and func.name.len == name.len) return null;
        return g_type_info.get(func.name);
    }

    // an argument that already has its declared scalar type passes without
    // coercion; everything else needs checkParamTypes
    pub inline fn declaredScalarHolds(type_str: []const u8, v: Value) bool {
        if (type_str.len == 0) return true;
        const tag: []const u8 = switch (v) {
            .int => "int",
            .float => "float",
            .string => "string",
            .bool => "bool",
            .array => "array",
            else => return std.mem.eql(u8, type_str, "mixed"),
        };
        return std.mem.eql(u8, type_str, tag) or std.mem.eql(u8, type_str, "mixed");
    }

    pub noinline fn checkParamTypes(self: *VM, name: []const u8, arg_count: u32) RuntimeError!bool {
        if (g_type_info.count() == 0) return false;
        const ac: usize = arg_count;
        // runs before the callee frame is pushed, so the caller is the top frame
        const internal = self.invoking_closure or self.calledFromNative();
        const exc = (try self.enforceArgTypes(name, self.stack[self.sp - ac .. self.sp], .{ .strict = !internal and self.topFrameStrict(), .internal = internal, .stack_owned = true })) orelse return false;
        self.dropN(ac);
        if (self.throwObject(exc)) return true;
        return error.RuntimeError;
    }

    fn isUserCallForwarder(name: ?[]const u8) bool {
        const n = name orelse return false;
        return std.ascii.eqlIgnoreCase(n, "call_user_func") or std.ascii.eqlIgnoreCase(n, "call_user_func_array");
    }

    // a call the engine makes on its own (an uncaught throwable's __toString,
    // the exception handler, shutdown functions): what it calls reads as
    // called by an internal function, and the call itself shows in no trace.
    // the caller links it in as native_call for the duration
    pub fn engineCall(self: *const VM) NativeCall {
        return .{ .label = "", .args = &.{}, .depth = self.frame_count, .instance = false, .outer = self.native_call };
    }

    // php's end of an uncaught throwable: the stack unwinds to the main frame
    // and the exception handler, when one is set, receives it. the throwable
    // is no longer pending unless the handler threw one of its own
    pub fn dispatchUncaught(self: *VM) void {
        self.unwindToMain();
        // a fatal error is not a throwable the handler may see
        if (self.uncatchable_fatal) return;
        const exc = self.pending_exception orelse return;
        const handler = self.user_exception_handler orelse return;
        // php's zend_user_exception_handler: while it runs the handler sits
        // on the handler stack, so restore_exception_handler() inside it
        // reaches the handlers below; afterwards, unless something was
        // installed, whatever is on top of the stack is installed again
        self.exception_handler_stack.append(self.allocator, handler) catch return;
        self.user_exception_handler = null;
        self.pending_exception = null;
        defer self.stackRelease(exc);
        retainValue(handler);
        defer self.releaseValue(handler);
        var engine = self.engineCall();
        self.native_call = &engine;
        defer self.native_call = engine.outer;
        var ctx = self.makeContext(null);
        _ = ctx.invokeCallable(handler, &.{exc}) catch {};
        if (self.user_exception_handler == null) {
            if (self.exception_handler_stack.pop()) |top| self.user_exception_handler = top;
        }
    }

    // an uncaught throwable ends everything but the main frame, above which
    // the report, the exception handler and shutdown functions run
    fn unwindToMain(self: *VM) void {
        if (self.pending_exception) |exc| self.chainHeldExceptions(exc, 0, 0);
        while (self.frame_count > 1) {
            self.frame_count -= 1;
            self.deinitFrameSlot(self.frame_count);
        }
        self.handler_count = 0;
        self.handler_floor = 0;
        self.error_silenced_depth = 0;
        // what the unwound frames and operands held is destroyed before the
        // exception is reported, as php frees them while it propagates; a
        // destructor's exception goes on with it as its previous
        if (self.frame_count > 0) {
            self.discardArgTransport(0);
            self.sp = 0;
        }
        if (self.pending_exception != null and self.hasPendingReleases() and !self.draining_destructors) {
            self.drainPendingDestruct();
            self.drain_raised = false;
        }
    }

    // true while a native runs with no user frame pushed since it started
    fn calledFromNative(self: *const VM) bool {
        const call = self.native_call orelse return false;
        return call.depth == self.frame_count;
    }

    pub fn topFrameStrict(self: *VM) bool {
        if (self.frame_count >= 1) {
            if (self.frames[self.frame_count - 1].func) |cf| return cf.strict_types;
        }
        return self.script_strict_types;
    }

    // a call's arguments against the callee's declared parameter types, with
    // php's weak-mode coercion applied in place unless the caller is strict.
    // returns the TypeError to raise when an argument does not fit; variadic
    // arguments take the variadic parameter's type
    const ArgCaller = struct {
        strict: bool,
        // an internal function calling back into user code: never strict,
        // and php names no call site in the message
        internal: bool = false,
        // the arguments are operand-stack slots, which own a reference a
        // coerced replacement must give back
        stack_owned: bool = false,
    };

    // replacement is transient or unowned; an operand-stack slot keeps a
    // reference of its own and gives back the one the old value held
    fn replaceArg(self: *VM, slot: *Value, replacement: Value, caller: ArgCaller) void {
        if (caller.stack_owned) {
            stackRetain(replacement);
            self.stackRelease(slot.*);
        }
        slot.* = replacement;
    }

    // the same for a slot that always owns its value, like a return value in
    // transit
    fn replaceOwned(self: *VM, slot: *Value, replacement: Value) void {
        stackRetain(replacement);
        self.stackRelease(slot.*);
        slot.* = replacement;
    }

    fn enforceArgTypes(self: *VM, name: []const u8, args: []Value, caller: ArgCaller) RuntimeError!?*PhpObject {
        const strict = caller.strict;
        const ti = self.typeInfoFor(name) orelse return null;
        if (ti.param_types.len == 0) return null;
        const func = self.functions.get(name);
        const variadic = if (func) |f| f.is_variadic else false;
        for (args, 0..) |*slot, i| {
            const type_index = if (i < ti.param_types.len) i else if (variadic) ti.param_types.len - 1 else break;
            const type_str = ti.param_types[type_index];
            if (type_str.len == 0) continue;
            const val = slot.*;
            // zend_verify_arg_type, which runs in the callee
            const ic = self.ic.?;
            const saved_site = ic.arg_check_site;
            if (func) |f| if (f.file_path.len > 0) {
                ic.arg_check_site = .{ .file = f.file_path, .line = f.start_line };
            };
            const checked = self.verifyDeclaredType(val, type_str, self.functionScope(name), strict);
            ic.arg_check_site = saved_site;
            if (try checked) |accepted| {
                if (@intFromEnum(accepted) != @intFromEnum(val) or !Value.identical(accepted, val)) self.replaceArg(slot, accepted, caller);
                continue;
            }
            return try self.argTypeError(name, func, .{ .args = args, .index = i, .type_str = type_str, .variadic = variadic and type_index == ti.param_types.len - 1, .internal_caller = caller.internal });
        }
        return null;
    }

    // the class a method's self and parent name: the part of its registered
    // name before "::". functions and closures have none here
    fn functionScope(self: *VM, name: []const u8) ?[]const u8 {
        const sep = std.mem.indexOf(u8, name, "::") orelse return null;
        // a trait method's self is the class using it, not known here
        if (self.traits.contains(name[0..sep])) return null;
        return name[0..sep];
    }

    // zend_check_type: the value as a parameter or return value of the
    // declared type takes it, or null when the type refuses it
    fn verifyDeclaredType(self: *VM, val: Value, type_str: []const u8, scope: ?[]const u8, strict: bool) RuntimeError!?Value {
        const shape = php_types.shape(type_str);
        if (self.typeHoldsExactly(val, type_str, shape, scope orelse "")) return val;
        if (self.representationHolds(val, type_str, shape, scope)) return val;
        if (shape.mask & php_types.CALLABLE != 0) {
            // zend_is_callable for a user parameter: a "Class::method" or
            // array callable resolves against the scope, with php's
            // deprecations for self, parent and static
            const by_name = switch (val) {
                .string => |s| std.mem.indexOf(u8, s.bytes(), "::") != null,
                .array => true,
                else => false,
            };
            if (by_name) {
                const resolved = try callables.resolveCallback(self, val, .{});
                if (self.pending_exception != null) return error.RuntimeError;
                if (resolved == .callee) return val;
            } else if (self.isValueCallable(val)) return val;
        }
        if (strict) {
            if (shape.mask & php_types.DOUBLE == 0 or val != .int) return null;
        } else if (val == .null) return null;
        return try self.weakScalarHint(shape.mask, val);
    }

    // values zphp represents differently from php that a declared type
    // still takes: a self/parent/static whose class isn't known here takes
    // any object, and the spl iterator types take the arrays some built-ins
    // hand back in place of their iterators
    fn representationHolds(self: *VM, val: Value, type_str: []const u8, shape: php_types.Shape, scope: ?[]const u8) bool {
        _ = self;
        if (!shape.classes and shape.mask & php_types.STATIC == 0) return false;
        var body = std.mem.trim(u8, type_str, " ");
        if (body.len > 0 and body[0] == '?') body = body[1..];
        var it = std.mem.splitScalar(u8, body, '|');
        while (it.next()) |raw| {
            const member = std.mem.trim(u8, raw, " ()");
            const bare = if (member.len > 0 and member[0] == '\\') member[1..] else member;
            switch (val) {
                .array => if (std.ascii.eqlIgnoreCase(bare, "Traversable") or std.ascii.eqlIgnoreCase(bare, "Iterator") or std.ascii.eqlIgnoreCase(bare, "IteratorAggregate")) return true,
                .object, .generator => {
                    if (std.ascii.eqlIgnoreCase(bare, "static")) return true;
                    if (scope == null and (std.ascii.eqlIgnoreCase(bare, "self") or std.ascii.eqlIgnoreCase(bare, "parent"))) return true;
                },
                else => {},
            }
        }
        return false;
    }

    const ArgTypeFailure = struct {
        args: []const Value,
        index: usize,
        type_str: []const u8,
        variadic: bool,
        internal_caller: bool,
    };

    fn argTypeError(self: *VM, name: []const u8, func: ?*const ObjFunction, failure: ArgTypeFailure) RuntimeError!*PhpObject {
        const i = failure.index;
        const val = failure.args[i];
        // php names the parameter, except for arguments gathered by a variadic
        const param_name = if (failure.variadic) "" else if (func) |f| (if (i < f.params.len) f.params[i] else "") else "";
        // php suffixes the message with the call site: ", called in <file> on
        // line N"; the caller is the current top frame
        var cs_file: []const u8 = self.file_path;
        var cs_line: u32 = 0;
        if (self.frame_count >= 1) {
            const caller = &self.frames[self.frame_count - 1];
            if (caller.script_path.len > 0) cs_file = caller.script_path else if (caller.func) |cf| if (cf.file_path.len > 0) {
                cs_file = cf.file_path;
            };
            const cip: usize = if (caller.ip > 0) caller.ip - 1 else 0;
            if (self.sourceLocation(caller.chunk, cip)) |loc| cs_line = loc.line;
        }
        const shown = try self.callableDisplayName(name, func);
        const type_shown = try self.resolvedTypeText(failure.type_str, self.functionScope(name));
        const site = if (failure.internal_caller) "" else std.fmt.allocPrint(self.allocator, ", called in {s} on line {d}", .{ cs_file, cs_line }) catch return error.RuntimeError;
        defer if (!failure.internal_caller) self.allocator.free(site);
        const msg = if (param_name.len > 0)
            std.fmt.allocPrint(self.allocator, "{s}(): Argument #{d} ({s}) must be of type {s}, {s} given{s}", .{ shown, i + 1, param_name, type_shown, valueTypeName(val), site }) catch return error.RuntimeError
        else
            std.fmt.allocPrint(self.allocator, "{s}(): Argument #{d} must be of type {s}, {s} given{s}", .{ shown, i + 1, type_shown, valueTypeName(val), site }) catch return error.RuntimeError;
        defer self.allocator.free(msg);
        // php raises it inside the callee, at its declaration
        const at: ?SourcePosition = if (func) |f| if (f.file_path.len > 0) SourcePosition{ .file = f.file_path, .line = f.start_line } else null else null;
        const exc = try self.newBuiltinException("TypeError", msg, at);
        if (func) |f| try self.prependCallToTrace(exc, f, failure.args);
        return exc;
    }

    // when a value already satisfies a single scalar declared type but isn't
    // exactly that type, return the coerced value (PHP non-strict semantics).
    // returns null when no coercion applies - union/class/nullable-null/
    // already-exact-type values are left untouched
    fn coerceToDeclaredScalar(self: *VM, val: Value, type_str: []const u8) RuntimeError!?Value {
        var t = type_str;
        if (t.len > 0 and t[0] == '?') t = t[1..];
        // single type only - skip unions and intersections
        for (t) |c| if (c == '|' or c == '&' or c == '(' or c == ')') return null;
        if (val == .null) return null;
        const is_int = std.mem.eql(u8, t, "int") or std.mem.eql(u8, t, "integer");
        const is_float = std.mem.eql(u8, t, "float") or std.mem.eql(u8, t, "double");
        const is_bool = std.mem.eql(u8, t, "bool") or std.mem.eql(u8, t, "boolean");
        const is_string = std.mem.eql(u8, t, "string");
        if (!is_int and !is_float and !is_bool and !is_string) return null;
        // already exactly the declared type - nothing to do
        if (is_int and val == .int) return null;
        if (is_float and val == .float) return null;
        if (is_bool and val == .bool) return null;
        if (is_string and val == .string) return null;
        return try self.tryWeakCoerceSingle(val, t);
    }

    noinline fn checkReturnType(self: *VM, val: *Value) RuntimeError!bool {
        if (g_type_info.count() == 0) return false;
        const frame = &self.frames[self.frame_count - 1];
        const func_name = if (frame.func) |f| f.name else return false;
        const ti = self.typeInfoFor(func_name) orelse return false;
        if (ti.return_type.len == 0) return false;
        // the function's own strict_types decides (ZEND_RET_USES_STRICT_TYPES)
        const fn_strict = if (frame.func) |f| f.strict_types else self.script_strict_types;
        const accepted = if (std.mem.eql(u8, ti.return_type, "void")) (if (val.* == .null) val.* else null) else try self.verifyDeclaredType(val.*, ti.return_type, self.functionScope(func_name), fn_strict);
        if (accepted == null) {
            const shown = if (frame.func) |f| (if (f.display_name.len > 0) f.display_name else func_name) else func_name;
            const msg = std.fmt.allocPrint(self.allocator, "{s}(): Return value must be of type {s}, {s} returned", .{ shown, try self.resolvedTypeText(ti.return_type, self.functionScope(func_name)), valueTypeName(val.*) }) catch return error.RuntimeError;
            defer self.allocator.free(msg);
            // raised inside the function, as php's VERIFY_RETURN_TYPE is
            if (try self.throwBuiltinException("TypeError", msg)) return true;
            self.setErrorMsg("{s}", .{msg});
            return error.RuntimeError;
        }
        if (@intFromEnum(accepted.?) != @intFromEnum(val.*) or !Value.identical(accepted.?, val.*)) self.replaceOwned(val, accepted.?);
        return false;
    }

    // a typed function reached its end without returning
    noinline fn throwImplicitReturn(self: *VM) RuntimeError!bool {
        const frame = &self.frames[self.frame_count - 1];
        const func = frame.func orelse return false;
        const ti = self.typeInfoFor(func.name) orelse return false;
        if (ti.return_type.len == 0) return false;
        const shown = if (func.display_name.len > 0) func.display_name else try self.callableDisplayName(func.name, func);
        const msg = if (std.ascii.eqlIgnoreCase(ti.return_type, "never"))
            try std.fmt.allocPrint(self.allocator, "{s}(): never-returning function must not implicitly return", .{shown})
        else
            try std.fmt.allocPrint(self.allocator, "{s}(): Return value must be of type {s}, none returned", .{ shown, try self.resolvedTypeText(ti.return_type, self.functionScope(func.name)) });
        defer self.allocator.free(msg);
        if (try self.throwBuiltinException("TypeError", msg)) return true;
        return error.RuntimeError;
    }

    fn typeStrAllowsString(_: *VM, type_str: []const u8) bool {
        var s = type_str;
        if (s.len > 0 and s[0] == '?') s = s[1..];
        return std.mem.eql(u8, s, "string");
    }

    // true when a declared property type cannot legitimately hold null. typed-
    // property write coercion rejects null for such a type, so a null slot
    // value can only mean the property is still uninitialized. union types are
    // treated conservatively (skipped) - they might admit null
    pub fn typedPropForbidsNull(_: *VM, type_str: []const u8) bool {
        if (type_str.len == 0) return false; // untyped
        if (type_str[0] == '?') return false; // ?T
        if (std.mem.indexOfScalar(u8, type_str, '|') != null) return false; // union
        if (std.mem.eql(u8, type_str, "mixed")) return false;
        if (std.mem.eql(u8, type_str, "null")) return false;
        return true;
    }

    // enforce a typed property's declared type on write. mirrors checkParamTypes:
    // non-strict weak-coerces a compatible scalar, strict rejects a mismatch.
    // returns true if a TypeError was thrown+dispatched (caller should continue)
    pub noinline fn checkPropertyType(self: *VM, val: *Value, type_str: []const u8, class_name: []const u8, prop_name: []const u8) RuntimeError!bool {
        if (type_str.len == 0) return false;
        // fast path: the value's tag already exactly matches a simple scalar
        // declared type - no coercion, no checkTypeMatch parse needed
        switch (val.*) {
            .int => if (std.mem.eql(u8, type_str, "int")) return false,
            .float => if (std.mem.eql(u8, type_str, "float")) return false,
            .string => if (std.mem.eql(u8, type_str, "string")) return false,
            .bool => if (std.mem.eql(u8, type_str, "bool")) return false,
            else => {},
        }
        // an int stepped past its range (zend_incdec_typed_prop) is refused
        // before any coercion
        const step_up: ?bool = if (val.* == .float and php_types.shape(type_str).mask & php_types.DOUBLE == 0) self.takeStepOverflow() else null;
        // the assigning file's strict_types determines the mode
        // (i_zend_verify_property_type)
        if (step_up == null) if (try self.propertyTypeAccepts(val.*, type_str, class_name, self.currentStrictTypes())) |accepted| {
            val.* = accepted;
            return false;
        };
        const shown = try self.propertyTypeText(type_str, class_name);
        const msg = if (step_up) |up|
            std.fmt.allocPrint(self.allocator, "Cannot {s} property {s}::${s} of type {s} past its {s} value", .{ if (up) "increment" else "decrement", class_name, prop_name, shown, if (up) "maximal" else "minimal" }) catch return error.RuntimeError
        else
            std.fmt.allocPrint(self.allocator, "Cannot assign {s} to property {s}::${s} of type {s}", .{ valueTypeName(val.*), class_name, prop_name, shown }) catch return error.RuntimeError;
        defer self.allocator.free(msg);
        if (try self.throwBuiltinException("TypeError", msg)) return true;
        self.setErrorMsg("{s}", .{msg});
        return error.RuntimeError;
    }

    // a declared type as php prints it in errors (zend_type_to_string_resolved):
    // self and parent name the classes they stand for
    // and the members print in php's order (zend_type_to_string)
    pub fn resolvedTypeText(self: *VM, type_str: []const u8, decl_class: ?[]const u8) RuntimeError![]const u8 {
        const plain = for (type_str, 0..) |c, i| {
            if (c == '|' or c == '?' or c == '&' or c == '(') break false;
            const rest = type_str[i..];
            if (std.ascii.startsWithIgnoreCase(rest, "self") or std.ascii.startsWithIgnoreCase(rest, "parent") or std.ascii.startsWithIgnoreCase(rest, "iterable")) break false;
        } else true;
        if (plain) return type_str;
        const parent = if (decl_class) |dc| (if (self.classes.get(dc)) |c| c.parent else null) else null;
        const t = php_types.parse(self.allocator, type_str, decl_class, parent) catch return error.OutOfMemory;
        defer t.deinit(self.allocator);
        const text = php_types.format(self.allocator, t) catch return error.OutOfMemory;
        defer self.allocator.free(text);
        return self.internName(text);
    }

    // a property's type in errors (zend_type_to_string): a named class's
    // self was resolved when it compiled, an anonymous class's was not
    pub fn propertyTypeText(self: *VM, type_str: []const u8, decl_class: []const u8) RuntimeError![]const u8 {
        return self.resolvedTypeText(type_str, if (class_names.isAnonymous(decl_class)) null else decl_class);
    }

    // php's is_numeric_str_function: a whole numeric string (surrounding
    // whitespace allowed) read as an int, or as a float when it has a
    // fraction or exponent or overflows
    const NumericStr = union(enum) { none, int: i64, float: f64 };

    fn numericStr(s: []const u8) NumericStr {
        if (!Value.isNumericString(s)) return .none;
        const t = std.mem.trim(u8, s, " \t\n\r\x0b\x0c");
        integral: {
            for (t, 0..) |c, i| {
                if ((c == '-' or c == '+') and i == 0) continue;
                if (c < '0' or c > '9') break :integral;
            }
            const n = std.fmt.parseInt(i64, t, 10) catch break :integral;
            return .{ .int = n };
        }
        return .{ .float = Value.toFloat(.{ .string = Value.String.borrowed(t) }) };
    }

    // zendi_try_get_long's diagnostics for the operands of a bitwise
    // operator or %: a float, or a float string, past the int range warns,
    // one with a fraction is deprecated
    fn warnIntOperands(self: *VM, a: Value, b: Value) RuntimeError!void {
        try self.warnIntOperand(a);
        try self.warnIntOperand(b);
    }

    fn warnIntOperand(self: *VM, v: Value) RuntimeError!void {
        const f: f64, const text: ?[]const u8 = switch (v) {
            .float => |f| .{ f, null },
            .string => |str| switch (numericStr(str.bytes())) {
                .float => |f| .{ f, str.bytes() },
                else => return,
            },
            else => return,
        };
        if (!(f >= -9.2233720368547758e18 and f < 9.2233720368547758e18)) {
            var tmp: [64]u8 = undefined;
            const m = if (text) |t|
                try std.fmt.allocPrint(self.allocator, "The float-string \"{s}\" is not representable as an int, cast occurred", .{t})
            else
                try std.fmt.allocPrint(self.allocator, "The float {s} is not representable as an int, cast occurred", .{formatted_print.gcvt(f, -1, '.', 'E', &tmp)});
            defer self.allocator.free(m);
            return self.emitWarning(m);
        }
        if (f != @trunc(f)) try self.warnLossyIntConversion(f, text);
    }

    // zend_incompatible_double_to_long_error / _string_to_long_error
    fn warnLossyIntConversion(self: *VM, f: f64, from_string: ?[]const u8) RuntimeError!void {
        const msg = if (from_string) |s|
            try std.fmt.allocPrint(self.allocator, "Implicit conversion from float-string \"{s}\" to int loses precision", .{s})
        else blk: {
            var buf: [64]u8 = undefined;
            break :blk try std.fmt.allocPrint(self.allocator, "Implicit conversion from float {s} to int loses precision", .{formatted_print.gcvt(f, -1, '.', 'E', &buf)});
        };
        defer self.allocator.free(msg);
        try self.raiseError(E_DEPRECATED, msg);
    }

    // zend_parse_arg_long_weak for a user-declared type (no null)
    fn weakLong(self: *VM, val: Value) RuntimeError!?i64 {
        switch (val) {
            .float => |f| {
                if (std.math.isNan(f) or !Value.floatFitsInt(f)) return null;
                if (f != @trunc(f)) try self.warnLossyIntConversion(f, null);
                return @intFromFloat(@trunc(f));
            },
            .string => |s| switch (numericStr(s.bytes())) {
                .none => return null,
                .int => |i| return i,
                .float => |f| {
                    if (std.math.isNan(f) or !Value.floatFitsInt(f)) return null;
                    if (f != @trunc(f)) try self.warnLossyIntConversion(f, s.bytes());
                    return @intFromFloat(@trunc(f));
                },
            },
            .bool => |b| return @intFromBool(b),
            else => return null,
        }
    }

    // zend_verify_weak_scalar_type_hint: int, then float, then string, then bool
    pub fn weakScalarHint(self: *VM, mask: u32, val: Value) RuntimeError!?Value {
        if (mask & php_types.LONG != 0) {
            if (mask & php_types.DOUBLE != 0 and val == .string) {
                switch (numericStr(val.string.bytes())) {
                    .int => |i| return .{ .int = i },
                    .float => |f| return .{ .float = f },
                    .none => {},
                }
            } else if (try self.weakLong(val)) |i| return .{ .int = i };
        }
        if (mask & php_types.DOUBLE != 0) switch (val) {
            .int => |i| return .{ .float = @floatFromInt(i) },
            .string => |s| switch (numericStr(s.bytes())) {
                .int => |i| return .{ .float = @floatFromInt(i) },
                .float => |f| return .{ .float = f },
                .none => {},
            },
            .bool => |b| return .{ .float = if (b) 1.0 else 0.0 },
            else => {},
        };
        if (mask & php_types.STRING != 0) switch (val) {
            .int, .float, .bool => {
                if (val == .float and std.math.isNan(val.float)) try self.emitWarning("unexpected NAN value was coerced to string");
                return try self.coerceToStringValue(val);
            },
            .object => |obj| if (self.hasMethod(obj.class_name, "__toString")) {
                return .{ .string = self.transientOwned(try self.objectString(obj)) };
            },
            else => {},
        };
        if (mask & php_types.BOOL == php_types.BOOL) switch (val) {
            .int, .float, .string => {
                if (val == .float and std.math.isNan(val.float)) try self.emitWarning("unexpected NAN value was coerced to bool");
                return .{ .bool = val.isTruthy() };
            },
            else => {},
        };
        return null;
    }

    // ZEND_TYPE_CONTAINS_CODE plus the class part of a declared type: the
    // value fits without any coercion. self and parent name the declaring
    // class and its parent
    fn typeHoldsExactly(self: *VM, val: Value, type_str: []const u8, shape: php_types.Shape, decl_class: []const u8) bool {
        const bit: u32 = switch (val) {
            .null, .undef => php_types.NULL,
            .bool => |b| if (b) php_types.TRUE else php_types.FALSE,
            .int => php_types.LONG,
            .float => php_types.DOUBLE,
            .string => php_types.STRING,
            .array => php_types.ARRAY,
            .resource => php_types.RESOURCE,
            .object, .generator, .fiber => php_types.OBJECT,
        };
        if (shape.mask & bit != 0) return true;
        if (val == .null and shape.mask & php_types.VOID != 0) return true;
        if (!shape.classes) return false;
        const class_name: []const u8 = switch (val) {
            .object => |obj| obj.class_name,
            .generator => "Generator",
            .fiber => "Fiber",
            else => return false,
        };
        var body = std.mem.trim(u8, type_str, " ");
        if (body.len > 0 and body[0] == '?') body = body[1..];
        var it = std.mem.splitScalar(u8, body, '|');
        while (it.next()) |raw| {
            var member = std.mem.trim(u8, raw, " ");
            if (member.len > 1 and member[0] == '(') member = member[1 .. member.len - 1];
            var all = true;
            var parts = std.mem.splitScalar(u8, member, '&');
            while (parts.next()) |part_raw| {
                const part = std.mem.trim(u8, part_raw, " ");
                const bare = if (part.len > 0 and part[0] == '\\') part[1..] else part;
                const target = if (std.ascii.eqlIgnoreCase(bare, "self"))
                    decl_class
                else if (std.ascii.eqlIgnoreCase(bare, "parent"))
                    (if (self.classes.get(decl_class)) |c| c.parent orelse bare else bare)
                else if (std.ascii.eqlIgnoreCase(bare, "iterable"))
                    "Traversable"
                else
                    bare;
                if (!php_types.shape(target).classes) {
                    all = false;
                    break;
                }
                const instance = switch (val) {
                    // zphp's generators are not objects of a class
                    .generator => std.ascii.eqlIgnoreCase(target, "Generator") or std.ascii.eqlIgnoreCase(target, "Traversable") or std.ascii.eqlIgnoreCase(target, "Iterator"),
                    .fiber => std.ascii.eqlIgnoreCase(target, "Fiber"),
                    else => self.isInstanceOf(class_name, target),
                };
                if (!instance) {
                    all = false;
                    break;
                }
            }
            if (all) return true;
        }
        return false;
    }

    // i_zend_check_property_type: the value as the property would store it,
    // or null when the type refuses it
    pub fn propertyTypeAccepts(self: *VM, val: Value, type_str: []const u8, decl_class: []const u8, strict: bool) RuntimeError!?Value {
        const shape = php_types.shape(type_str);
        if (self.typeHoldsExactly(val, type_str, shape, decl_class)) return val;
        if (self.representationHolds(val, type_str, shape, decl_class)) return val;
        if (strict) {
            if (shape.mask & php_types.DOUBLE == 0 or val != .int) return null;
        } else if (val == .null) return null;
        return try self.weakScalarHint(shape.mask, val);
    }

    // i_zend_verify_type_assignable_zval: 1 fits, 0 refused, -1 may fit
    // after coercion
    fn typeAssignable(self: *VM, val: Value, type_str: []const u8, decl_class: []const u8, strict: bool) i2 {
        const shape = php_types.shape(type_str);
        if (self.typeHoldsExactly(val, type_str, shape, decl_class)) return 1;
        if (strict) return if (shape.mask & php_types.DOUBLE != 0 and val == .int) -1 else 0;
        if (val == .null) return 0;
        if (shape.mask & (php_types.LONG | php_types.DOUBLE | php_types.STRING) == 0 and shape.mask & php_types.BOOL != php_types.BOOL) return 0;
        return -1;
    }

    pub fn currentStrictTypes(self: *VM) bool {
        if (self.frame_count >= 1) {
            if (self.frames[self.frame_count - 1].func) |f| return f.strict_types;
        }
        return self.script_strict_types;
    }

    // a typed property a reference is bound to (php's ZEND_REF_HAS_TYPE_SOURCES)
    pub const TypeSource = struct { class: []const u8, prop: []const u8, type_str: []const u8 };

    fn staticPropDeclaringClass(self: *VM, class_name: []const u8, prop_name: []const u8) ?[]const u8 {
        var current: ?[]const u8 = class_name;
        while (current) |cn| {
            const entry = self.classes.getEntry(cn) orelse return null;
            if (entry.value_ptr.static_props.contains(prop_name)) return entry.key_ptr.*;
            current = entry.value_ptr.parent;
        }
        return null;
    }

    fn propertySource(self: *VM, target: BindingTarget) ?TypeSource {
        switch (target) {
            .object => |t| {
                const decl = self.propertyDeclaration(t.object.class_name, t.prop_name);
                if (!decl.declared or decl.type_str.len == 0) return null;
                return .{ .class = decl.defining_class, .prop = t.prop_name, .type_str = decl.type_str };
            },
            .static => |t| {
                const cn = self.staticPropDeclaringClass(t.class_name, t.prop_name) orelse return null;
                const cls = self.classes.getPtr(cn) orelse return null;
                const ts = cls.static_prop_types.get(t.prop_name) orelse return null;
                if (ts.len == 0) return null;
                return .{ .class = cn, .prop = t.prop_name, .type_str = ts };
            },
            else => return null,
        }
    }

    // the typed properties a reference cell is bound to, in binding order.
    // a cell marked typed whose sources are all gone loses the mark
    pub fn refTypeSources(self: *VM, cell: *Value, buf: []TypeSource) []TypeSource {
        const rc = cellOf(cell);
        if (!rc.typed) return buf[0..0];
        var n: usize = 0;
        if (self.ref_index) |ri| if (ri.fwd.getPtr(cell)) |list| {
            for (list.items) |target| {
                if (n == buf.len) break;
                const src = self.propertySource(target) orelse continue;
                var dup = false;
                for (buf[0..n]) |seen| {
                    if (std.mem.eql(u8, seen.class, src.class) and std.mem.eql(u8, seen.prop, src.prop)) dup = true;
                }
                if (dup) continue;
                buf[n] = src;
                n += 1;
            }
        };
        if (n == 0) rc.typed = false;
        return buf[0..n];
    }

    fn markTypedSource(self: *VM, cell: *Value, target: BindingTarget) void {
        if (self.propertySource(target) != null) cellOf(cell).typed = true;
    }

    fn throwRefTypeError(self: *VM, src: TypeSource, val: Value) RuntimeError {
        const msg = std.fmt.allocPrint(self.allocator, "Cannot assign {s} to reference held by property {s}::${s} of type {s}", .{ valueTypeName(val), src.class, src.prop, try self.propertyTypeText(src.type_str, src.class) }) catch return error.RuntimeError;
        defer self.allocator.free(msg);
        try self.setPendingException("TypeError", msg);
        return error.RuntimeError;
    }

    fn throwConflictingCoercion(self: *VM, a: TypeSource, b: TypeSource, val: Value) RuntimeError {
        const msg = std.fmt.allocPrint(self.allocator, "Cannot assign {s} to reference held by property {s}::${s} of type {s} and property {s}::${s} of type {s}, as this would result in an inconsistent type conversion", .{ valueTypeName(val), a.class, a.prop, try self.propertyTypeText(a.type_str, a.class), b.class, b.prop, try self.propertyTypeText(b.type_str, b.class) }) catch return error.RuntimeError;
        defer self.allocator.free(msg);
        try self.setPendingException("TypeError", msg);
        return error.RuntimeError;
    }

    // zend_verify_ref_assignable_zval: the value must fit every typed
    // property the reference is bound to and coerce to the same value for
    // each. returns the value to store; raises the TypeError as pending
    pub noinline fn verifyRefAssignable(self: *VM, cell: *Value, val: Value) RuntimeError!Value {
        var buf: [8]TypeSource = undefined;
        const sources = self.refTypeSources(cell, &buf);
        if (sources.len == 0) return val;
        // an int stepped past its range (zend_incdec_typed_ref)
        if (val == .float) if (self.takeStepOverflow()) |up| {
            for (sources) |src| {
                if (php_types.shape(src.type_str).mask & php_types.DOUBLE == 0) return self.throwIncdecRef(src, up);
            }
            return val;
        };
        const strict = self.currentStrictTypes();
        var first: ?TypeSource = null;
        var coerced: ?Value = null;
        for (sources) |src| {
            const result = self.typeAssignable(val, src.type_str, src.class, strict);
            if (result == 0) return self.throwRefTypeError(src, val);
            if (result < 0) {
                const c = (try self.weakScalarHint(php_types.shape(src.type_str).mask, val)) orelse return self.throwRefTypeError(src, val);
                if (first == null) {
                    first = src;
                    coerced = c;
                } else if (coerced) |prev| {
                    if (!Value.identical(prev, c)) return self.throwConflictingCoercion(first.?, src, val);
                } else return self.throwConflictingCoercion(first.?, src, val);
            } else if (first == null) {
                first = src;
            } else if (coerced != null) return self.throwConflictingCoercion(first.?, src, val);
        }
        return coerced orelse val;
    }

    fn isAncestor(self: *VM, ancestor: []const u8, descendant: []const u8) bool {
        if (std.mem.eql(u8, ancestor, descendant)) return true;
        var current: ?[]const u8 = descendant;
        while (current) |name| {
            const cls = self.classes.get(name) orelse return false;
            current = cls.parent;
            if (current) |p| {
                if (std.mem.eql(u8, p, ancestor)) return true;
            }
        }
        return false;
    }

    // zend_forbid_dynamic_call's users: functions that read or write the
    // calling scope
    fn forbidsDynamicCall(name: []const u8) bool {
        for ([_][]const u8{ "extract", "compact", "get_defined_vars", "func_get_args", "func_get_arg", "func_num_args" }) |f| {
            if (std.ascii.eqlIgnoreCase(name, f)) return true;
        }
        return false;
    }

    // natives PHP opcode-compiles (strlen, count, sizeof) - PHP never frames
    // these into an exception stack trace, so neither should zphp
    fn isFrameOutNative(name: []const u8) bool {
        return std.mem.eql(u8, name, "strlen") or
            std.mem.eql(u8, name, "count") or
            std.mem.eql(u8, name, "sizeof");
    }

    fn callStaticFunction(self: *VM, name: []const u8, arg_count: u32, class_name: []const u8) RuntimeError!void {
        const fc_before = self.frame_count;
        const prev_cc = self.currentFrame().called_class;
        // set called_class on current frame so both native fns and localsOnly
        // paths can inherit it (localsOnly executes inline and won't be caught
        // by the post-call fixup below)
        self.currentFrame().called_class = class_name;
        defer self.frames[fc_before - 1].called_class = prev_cc;
        const outer_called = self.static_native_outer_called;
        self.static_native_outer_called = prev_cc;
        defer self.static_native_outer_called = outer_called;
        try self.callNamedFunction(name, arg_count);
        // the callee's frame, not the top one: a callee that already ran in
        // the fast loop may have pushed frames of its own above it
        if (self.frame_count > fc_before)
            self.frames[fc_before].called_class = class_name
        else
            self.tagNewGenerator(class_name);
    }

    // a generator a call just made runs with the class the call named
    fn tagNewGenerator(self: *VM, class_name: []const u8) void {
        if (self.sp == 0) return;
        const top = self.stack[self.sp - 1];
        if (top == .generator and top.generator.state == .created and top.generator.called_class == null) top.generator.called_class = class_name;
    }

    fn callStaticUserFunction(self: *VM, func: *const ObjFunction, name: []const u8, arg_count: u32, class_name: []const u8) RuntimeError!void {
        const fc_before = self.frame_count;
        const prev_cc = self.currentFrame().called_class;
        self.currentFrame().called_class = class_name;
        defer self.frames[fc_before - 1].called_class = prev_cc;
        self.captureArgSources(arg_count);
        try self.enterUserFunction(func, name, arg_count, null);
        // the callee's frame, not the top one: a callee that already ran in
        // the fast loop may have pushed frames of its own above it
        if (self.frame_count > fc_before)
            self.frames[fc_before].called_class = class_name
        else
            self.tagNewGenerator(class_name);
    }

    // the function a Closure made from a function's name calls
    fn fakeClosureFunction(v: Value) ?[]const u8 {
        if (v != .object) return null;
        const callable = v.object.fakeCallable();
        if (callable != .string or std.mem.indexOf(u8, callable.string.bytes(), "::") != null) return null;
        return callable.string.bytes();
    }

    // a call by name with named arguments (an argument array with string
    // keys): each lands on its parameter, defaults fill the gaps, and names
    // no parameter has fall into a variadic. an exception raised on the way
    // is dispatched before this returns
    fn callWithNamedArgs(self: *VM, name: []const u8, arr: *PhpArray, base_frame: usize) RuntimeError!void {
        if (self.functions.get(name)) |func| {
            const bound = (try callables.bindNamed(self, name, func, arr)) orelse {
                if (self.dispatchPendingException(base_frame)) return;
                return error.RuntimeError;
            };
            defer bound.deinit(self.allocator);
            for (bound.args(), bound.origins[0..bound.count]) |v, origin| {
                self.push(v);
                self.setArgSource(self.sp - 1, if (origin) |ei| self.argArraySource(arr, arr.entries.items[ei].key) else .none);
            }
            self.callNamedFunctionV(name, @intCast(bound.count), bound.extras) catch {
                if (self.pending_exception != null and self.dispatchPendingException(base_frame)) return;
                return error.RuntimeError;
            };
        } else if (native_params.get(name)) |signature| {
            const params = signature.params;
            var resolved: [256]Value = undefined;
            var resolved_sources: [256]RefSource = undefined;
            const placed = try self.placeNativeNamedArgs(arr, params, &resolved, &resolved_sources, natives_mod.acceptsNamedExtras(name));
            if (placed.problem) |problem| {
                if (try self.throwNamedArgProblem(name, params, problem)) return;
                return error.RuntimeError;
            }
            const pos = placed.count;
            for (0..pos) |i| {
                self.push(resolved[i]);
                self.setArgSource(self.sp - 1, resolved_sources[i]);
            }
            self.callNamedFunction(name, @intCast(pos)) catch {
                if (self.pending_exception != null and self.dispatchPendingException(base_frame)) return;
                return error.RuntimeError;
            };
        } else {
            try self.pushArgEntries(arr, arr.entries.items);
            self.callNamedFunction(name, @intCast(arr.entries.items.len)) catch {
                if (self.pending_exception != null and self.dispatchPendingException(base_frame)) return;
                return error.RuntimeError;
            };
        }
    }

    fn callNamedFunction(self: *VM, raw_name: []const u8, arg_count: u32) RuntimeError!void {
        return self.callNamedFunctionV(raw_name, arg_count, null);
    }

    // named_extras: PHP 8.1 lets named arguments that match no declared
    // parameter fall into a variadic param keyed by their name. when set, its
    // entries are merged into the variadic rest array
    fn callNamedFunctionV(self: *VM, raw_name: []const u8, arg_count: u32, named_extras: ?*PhpArray) RuntimeError!void {
        const dynamic = self.pending_dynamic_call;
        self.pending_dynamic_call = false;
        self.captureArgSources(arg_count);
        // PHP normalizes leading-backslash on function callable strings
        const name = if (raw_name.len > 0 and raw_name[0] == '\\') raw_name[1..] else raw_name;
        if (self.dbg_profile_enabled) {
            const e = self.profile_calls.getOrPut(self.allocator, name) catch null;
            if (e) |ee| {
                if (!ee.found_existing) ee.value_ptr.* = 0;
                ee.value_ptr.* += 1;
                // bail after a budget so we can profile long-running scripts
            }
        }
        if (self.native_fns.get(name)) |native| {
            var args: [64]Value = undefined;
            const ac: usize = arg_count;
            const args_s = try self.copyStackArgs(&args, self.stack[self.sp - ac ..][0..ac]);
            defer self.freeStackArgs(args_s, &args);
            self.dropN(ac);
            const pre_handler_count = self.handler_count;
            var ctx = self.makeContext(name);
            const result = self.invokeNative(native, &ctx, .{ .args = args_s, .name = name, .dynamic = dynamic }) catch {
                if (self.pending_exception) |exc| {
                    self.pending_exception = null;
                    if (self.handler_count > self.handler_floor and !self.uncatchable_fatal) {
                        const handler = self.exception_handlers[self.handler_count - 1];
                        self.enterHandler(handler, exc, .owned);
                        return;
                    }
                    self.pending_exception = exc;
                } else if (self.handler_count < pre_handler_count) {
                    // throwBuiltinException already claimed a handler during the
                    // native (decremented handler_count, set ip to catch_ip, pushed
                    // exc on stack). just resume so the catch block runs
                    return;
                }
                return error.RuntimeError;
            };
            self.pushNativeResult(result);
        } else if (self.functions.get(name)) |func| {
            return self.enterUserFunction(func, name, arg_count, named_extras);
        } else {
            if (self.resolveFunctionName(name)) |registered| {
                self.pending_dynamic_call = dynamic;
                return self.callNamedFunctionV(registered, arg_count, named_extras);
            }
            const msg = std.fmt.allocPrint(self.allocator, "Call to undefined function {s}()", .{name}) catch "Call to undefined function";
            defer self.allocator.free(msg);
            if (try self.throwBuiltinException("Error", msg)) return;
            self.setErrorMsg("Fatal error: Uncaught Error: {s}\n", .{msg});
            return error.RuntimeError;
        }
    }

    // the body of a call to a user function already resolved by name
    fn enterUserFunction(self: *VM, func: *const ObjFunction, name: []const u8, arg_count: u32, named_extras: ?*PhpArray) RuntimeError!void {
        const ac: usize = arg_count;
        if (ac < func.required_params) {
            if (try self.throwTooFewArgs(name, ac, func, self.stack[self.sp - ac .. self.sp])) return;
            return error.RuntimeError;
        }
        if (func.has_param_types) {
            if (try self.checkParamTypes(name, arg_count)) return;
        }
        if (func.locals_only) {
            // callLocalsOnly takes the frame's call name from here; no other
            // path consumes it, and a stale one would be released by the next
            // frame executeFunction builds
            if (self.captures.items.len == 0 or !self.hasCaptures(name)) {
                self.pending_call_name = name;
                return self.callLocalsOnly(func, arg_count);
            }
            if (std.mem.startsWith(u8, name, "__closure_"))
                return self.callClosureLocalsOnly(func, name, arg_count);
        }
        var new_vars = self.acquireFrameVars();
        var closure_refs: std.StringHashMapUnmanaged(*Value) = .{};
        try self.bindClosures(&new_vars, &closure_refs, name);
        if (func.is_variadic) {
            const fixed: usize = func.arity - 1;
            for (0..@min(ac, fixed)) |i| {
                try new_vars.put(self.allocator, func.params[i], try self.bindFrameArg(self.stack[self.sp - ac + i]));
            }
            for (@min(ac, fixed)..fixed) |i| {
                if (i < func.defaults.len) try new_vars.put(self.allocator, func.params[i], try self.resolveParamDefault(func, i));
            }
            const rest_arr = try self.allocArray();
            if (ac > fixed) {
                for (fixed..ac) |i| {
                    try rest_arr.append(self.allocator, try self.bindFrameArg(self.stack[self.sp - ac + i]));
                }
            }
            // named arguments matching no fixed parameter land in the
            // variadic, keyed by name (PHP 8.1)
            if (named_extras) |extras| {
                for (extras.entries.items) |entry| {
                    try rest_arr.set(self.allocator, entry.key, try self.bindFrameArg(entry.value));
                }
            }
            try new_vars.put(self.allocator, func.params[fixed], .{ .array = rest_arr });
        } else {
            const bind_count = @min(ac, func.arity);
            for (0..bind_count) |i| {
                // for ref params, share the caller's value (especially the
                // array/object pointer) so mutations through the param
                // surface back. copyValue would deep-clone the array and
                // sever the ref relationship
                const is_ref = i < func.ref_params.len and func.ref_params[i];
                const slot_val = if (is_ref) self.stack[self.sp - ac + i] else try self.bindFrameArg(self.stack[self.sp - ac + i]);
                try new_vars.put(self.allocator, func.params[i], slot_val);
            }
        }
        self.saveFrameArgs(arg_count);
        var extra_args: [16]Value = undefined;
        const extra_count: usize = if (func.is_generator and !func.is_variadic and ac > func.arity) @min(ac - func.arity, extra_args.len) else 0;
        for (0..extra_count) |i| {
            extra_args[i] = self.stack[self.sp - ac + func.arity + i];
            retainValue(extra_args[i]);
        }
        defer for (extra_args[0..extra_count]) |v| self.releaseValue(v);
        self.dropN(ac);
        if (!func.is_variadic) {
            try self.fillDefaults(&new_vars, func, @min(ac, func.arity));
        }
        var callee_refs = closure_refs;
        const callee_owner = (try self.refIndex()).createOwner();
        self.bindOwnedRefParams(ac, func, &new_vars, &callee_refs, callee_owner) catch |err| {
            new_vars.deinit(self.allocator);
            self.deinitRefSlots(&callee_refs);
            if (self.ref_index) |ri| ri.releaseOwner(self.allocator, callee_owner);
            return err;
        };

        if (func.is_generator) {
            // by-ref params: ref_slots on the generator so subsequent
            // function calls inside the body see the cells; array/object
            // bindings aren't represented on Generator yet
            if (self.ref_index) |ri| ri.releaseOwner(self.allocator, callee_owner);
            const gen = try self.allocGenerator(.{ .func = func, .vars = new_vars, .ref_slots = callee_refs });
            retainVarsObjects(&gen.vars);
            if (extra_count > 0) try self.keepGeneratorExtraArgs(gen, extra_args[0..extra_count]);
            self.keepGeneratorClosure(gen, name);
            self.push(.{ .generator = gen });
        } else {
            if (!self.hasCallRoom(1) and !(try self.growCallRoom(1))) {
                new_vars.deinit(self.allocator);
                self.deinitRefSlots(&callee_refs);
                if (self.ref_index) |ri| ri.releaseOwner(self.allocator, callee_owner);
                const msg = std.fmt.allocPrint(self.allocator, "Maximum function nesting level of {d} reached, aborting in {s}()", .{ max_frames, name }) catch "Maximum function nesting level reached";
                defer self.allocator.free(msg);
                if (try self.throwBuiltinException("Error", msg)) return;
                self.setErrorMsg("{s}", .{msg});
                return error.RuntimeError;
            }
            const inherit_cc = if (std.mem.startsWith(u8, name, "__closure_"))
                self.closureScopeByName(name) orelse self.callerCalledClass()
            else
                null;
            try self.ensureCallRoom();
            self.frames[self.frame_count] = .{ .chunk = &func.chunk, .ip = 0, .vars = new_vars, .locals = try self.allocLocals(func, &new_vars), .func = func, .ref_slots = callee_refs, .ref_owner = callee_owner, .called_class = inherit_cc, .call_name = name };
            self.frames[self.frame_count].entry_sp = self.sp;
            self.setFrameArgCount(arg_count);
            self.frame_count += 1;
            self.retainFrameObjects(self.frame_count - 1);
            if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;
        }
    }

    pub fn dumpProfilePublic(self: *VM) void {
        const Entry = struct { name: []const u8, count: u64 };
        var list = std.ArrayListUnmanaged(Entry).empty;
        defer list.deinit(self.allocator);
        var it = self.profile_calls.iterator();
        while (it.next()) |e| {
            list.append(self.allocator, .{ .name = e.key_ptr.*, .count = e.value_ptr.* }) catch return;
        }
        std.sort.heap(Entry, list.items, {}, struct {
            fn lt(_: void, x: Entry, y: Entry) bool {
                return x.count > y.count;
            }
        }.lt);
        const sfe = std.Io.File.stderr();
        _ = sfe.write("[profile] top callees:\n") catch {};
        const n = @min(list.items.len, 30);
        for (list.items[0..n]) |e| {
            const m = std.fmt.allocPrint(self.allocator, "  {d: >12} {s}\n", .{ e.count, e.name }) catch return;
            _ = sfe.write(m) catch {};
            self.allocator.free(m);
        }
    }

    pub const NamedArgProblem = union(enum) {
        unknown: []const u8,
        overwrites: []const u8,
        variadic_named,
        not_passed: usize,
        default_unknown: usize,
    };
    pub const NativeNamedArgs = struct { count: usize = 0, problem: ?NamedArgProblem = null };

    // natives declare no parameter list; native_params supplies it, so a named
    // argument lands in its position and a skipped optional parameter gets
    // its default, with php's errors for everything else
    // scratch room for placing a call's named and positional arguments in
    // parameter order: the buffers, or the heap for a call passing more
    const ArgSlots = struct { values: []Value, sources: []RefSource, assigned: []bool };

    fn argSlots(self: *VM, values_buf: *[256]Value, sources_buf: *[256]RefSource, assigned_buf: *[256]bool, count: usize) RuntimeError!ArgSlots {
        const slots: ArgSlots = if (count <= values_buf.len) .{
            .values = values_buf[0..count],
            .sources = sources_buf[0..count],
            .assigned = assigned_buf[0..count],
        } else blk: {
            const values = try self.allocator.alloc(Value, count);
            errdefer self.allocator.free(values);
            const sources = try self.allocator.alloc(RefSource, count);
            errdefer self.allocator.free(sources);
            break :blk .{ .values = values, .sources = sources, .assigned = try self.allocator.alloc(bool, count) };
        };
        @memset(slots.values, .null);
        @memset(slots.sources, .none);
        @memset(slots.assigned, false);
        return slots;
    }

    fn freeArgSlots(self: *VM, slots: ArgSlots, values_buf: *[256]Value) void {
        if (slots.values.ptr == values_buf) return;
        self.allocator.free(slots.values);
        self.allocator.free(slots.sources);
        self.allocator.free(slots.assigned);
    }

    // named arguments a native accepting them collected, dropped when the
    // call doesn't happen
    pub fn discardNativeNamedArgs(self: *VM) void {
        const extras = self.native_named_args orelse return;
        self.native_named_args = null;
        if (extras.refcount == 0) self.queueArrayRelease(extras);
    }

    // accept_extras: names no parameter has go to native_named_args, for a
    // native that passes them on (call_user_func)
    pub fn placeNativeNamedArgs(self: *VM, arr: *PhpArray, params: []const native_params.Param, resolved: *[256]Value, sources: *[256]RefSource, accept_extras: bool) RuntimeError!NativeNamedArgs {
        @memset(resolved, .null);
        @memset(sources, .none);
        var assigned: [256]bool = @splat(false);
        var positional: usize = 0;
        var count: usize = 0;
        entries: for (arr.entries.items) |entry| {
            const index = switch (entry.key) {
                .int => blk: {
                    defer positional += 1;
                    break :blk positional;
                },
                .string => |k| blk: {
                    const name = k.bytes();
                    for (params, 0..) |p, pi| if (!p.variadic and std.mem.eql(u8, p.name, name)) {
                        if (assigned[pi]) return .{ .problem = .{ .overwrites = name } };
                        break :blk pi;
                    };
                    for (params) |p| if (p.variadic) {
                        if (!accept_extras) return .{ .problem = .variadic_named };
                        if (self.native_named_args == null) self.native_named_args = try self.allocArray();
                        try self.native_named_args.?.set(self.allocator, entry.key, entry.value);
                        continue :entries;
                    };
                    return .{ .problem = .{ .unknown = name } };
                },
            };
            if (index >= resolved.len) return error.RuntimeError;
            resolved[index] = entry.value;
            sources[index] = self.argArraySource(arr, entry.key);
            assigned[index] = true;
            count = @max(count, index + 1);
        }
        for (0..@min(count, params.len)) |i| {
            if (assigned[i]) continue;
            switch (params[i].default) {
                .required => return .{ .problem = .{ .not_passed = i } },
                .unknown => return .{ .problem = .{ .default_unknown = i } },
                else => |d| resolved[i] = try self.nativeDefault(d),
            }
        }
        return .{ .count = count };
    }

    pub fn nativeDefault(self: *VM, d: native_params.Default) RuntimeError!Value {
        return switch (d) {
            .required, .unknown, .null => .null,
            .bool => |b| .{ .bool = b },
            .int => |i| .{ .int = i },
            .float => |f| .{ .float = f },
            .string => |bytes| .{ .string = Value.String.borrowed(bytes) },
            .empty_array => blk: {
                const arr = try self.allocArray();
                break :blk .{ .array = arr };
            },
            .class_constant => |c| blk: {
                if (self.getClassConstant(c.class, c.name)) |v| break :blk v;
                var buf: [256]u8 = undefined;
                const full = class_names.memberKey(&buf, c.class, c.name);
                break :blk self.php_constants.get(full) orelse .null;
            },
        };
    }

    pub fn throwNamedArgProblem(self: *VM, func_name: []const u8, params: []const native_params.Param, problem: NamedArgProblem) RuntimeError!bool {
        self.discardNativeNamedArgs();
        const class: []const u8, const msg = try self.namedArgProblemMessage(func_name, params, problem);
        defer self.allocator.free(msg);
        return self.throwBuiltinException(class, msg);
    }

    // the exception class and message php raises for a misplaced named
    // argument; the caller frees the message
    pub fn namedArgProblemMessage(self: *VM, func_name: []const u8, params: []const native_params.Param, problem: NamedArgProblem) RuntimeError!struct { []const u8, []const u8 } {
        const class: []const u8, const msg = switch (problem) {
            .unknown => |name| .{ "Error", try std.fmt.allocPrint(self.allocator, "Unknown named parameter ${s}", .{name}) },
            .overwrites => |name| .{ "Error", try std.fmt.allocPrint(self.allocator, "Named parameter ${s} overwrites previous argument", .{name}) },
            .variadic_named => .{ "ArgumentCountError", try std.fmt.allocPrint(self.allocator, "{s}() does not accept unknown named parameters", .{func_name}) },
            .not_passed => |i| .{ "ArgumentCountError", try std.fmt.allocPrint(self.allocator, "{s}(): Argument #{d} (${s}) not passed", .{ func_name, i + 1, params[i].name }) },
            .default_unknown => |i| .{ "ArgumentCountError", try std.fmt.allocPrint(self.allocator, "{s}(): Argument #{d} (${s}) must be passed explicitly, because the default value is not known", .{ func_name, i + 1, params[i].name }) },
        };
        return .{ class, msg };
    }

    pub fn callMethod(self: *VM, obj: *PhpObject, method_name: []const u8, args: []const Value) RuntimeError!Value {
        return self.callMethodAs(obj, method_name, null, args);
    }

    // calls a method on obj. registered ("Class::method") names the method
    // already resolved, which a callable naming a class (["$this",
    // "Parent::m"]) picks instead of the object's own override
    pub fn callMethodAs(self: *VM, obj: *PhpObject, method_name: []const u8, registered: ?[]const u8, args: []const Value) RuntimeError!Value {
        // A native callback may execute calls at the same VM frame depth.
        // Restore the enclosing call's output-argument destinations afterwards.
        const saved_sources_count = self.ic.?.active_arg_count;
        var saved_sources: [256]RefSource = undefined;
        @memcpy(saved_sources[0..saved_sources_count], self.ic.?.active_args[0..saved_sources_count]);
        const saved_source_frame = self.ic.?.active_frame;
        for (self.ic.?.active_args[0..self.ic.?.active_arg_count]) |*source| source.* = self.retainArgSource(source.*);
        defer {
            self.clearActiveArgSources();
            @memcpy(self.ic.?.active_args[0..saved_sources_count], saved_sources[0..saved_sources_count]);
            self.ic.?.active_arg_count = saved_sources_count;
            self.ic.?.active_frame = saved_source_frame;
        }

        try self.ensureCallRoom();
        const full_name = registered orelse self.resolveMethod(obj.class_name, method_name) catch {
            // the spl iterators pass a method they lack to the iterator they wrap
            if (spl_iterator_classes.forwardFor(self, obj, method_name)) |target| {
                if (self.hasMethod(target.class_name, method_name)) return self.callMethod(target, method_name, args);
            }
            return error.RuntimeError;
        };
        if (self.dbg_profile_enabled) {
            const e = self.profile_calls.getOrPut(self.allocator, full_name) catch null;
            if (e) |ee| {
                if (!ee.found_existing) ee.value_ptr.* = 0;
                ee.value_ptr.* += 1;
            }
        }
        if (self.native_fns.get(full_name)) |native| {
            var tmp_vars: std.StringHashMapUnmanaged(Value) = .{};
            try tmp_vars.put(self.allocator, "$this", .{ .object = obj });
            try self.ensureCallRoom();
            self.frames[self.frame_count] = .{ .chunk = self.currentChunk(), .ip = self.currentFrame().ip, .vars = tmp_vars, .native = true };
            self.frame_count += 1;
            self.retainFrameObjects(self.frame_count - 1);
            if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;
            const saved_fc = self.frame_count;
            var ctx = self.makeContext(null);
            // throwBuiltinException can dispatch in-place and the native
            // returns error.RuntimeError to unwind. detect that and let
            // the caller resume from the dispatched handler frame
            const result = self.invokeNative(native, &ctx, .{ .args = args, .name = full_name, .instance = true }) catch |native_err| {
                if (self.frame_count < saved_fc) return .null;
                return native_err;
            };
            if (self.frame_count >= saved_fc) {
                self.frame_count -= 1;
                self.deinitFrameSlot(self.frame_count);
            }
            return self.borrowCallResult(result);
        } else if (self.functions.get(full_name)) |func| {
            if (args.len < func.required_params) return self.raiseTooFewArgs(full_name, args, func);
            var checked_buf: [16]Value = undefined;
            const checked = try self.checkedArgs(full_name, func, args, &checked_buf);
            defer if (checked.ptr != &checked_buf and checked.ptr != args.ptr) self.allocator.free(checked);
            var new_vars = self.acquireFrameVars();
            try new_vars.put(self.allocator, "$this", .{ .object = obj });
            try self.bindClosures(&new_vars, null, full_name);
            const trimmed = if (func.is_variadic) checked else checked[0..@min(checked.len, func.arity)];
            try self.bindArgs(&new_vars, func, trimmed);
            if (func.is_generator) {
                const gen = try self.allocGenerator(.{ .func = func, .vars = new_vars, .called_class = obj.class_name });
                retainVarsObjects(&gen.vars);
                return .{ .generator = gen };
            }
            // LSB: static::class inside this method must resolve to the object's
            // runtime class (e.g. reflection-instantiated SchedulePauseCommand
            // running an inherited Command::__construct that reads its own
            // #[AsCommand] via new ReflectionClass(static::class))
            self.pending_called_class = obj.class_name;
            // func_get_args() sees every argument, past the declared ones too
            if (self.ic) |ic| ic.pending_arg_count = @intCast(@min(checked.len, unknown_arg_count - 1));
            const saved_invoke_args = self.pending_invoke_args;
            self.pending_invoke_args = checked;
            defer self.pending_invoke_args = saved_invoke_args;
            return self.executeFunction(func, new_vars);
        } else return error.RuntimeError;
    }

    // php's ZEND_ACC_USE_GUARDS: a class with a property magic method or
    // __debugInfo, or one implementing JsonSerializable, keeps a recursion
    // flag per kind of walk (var_dump, var_export, json_encode) where other
    // objects share one (value.Recursion)
    pub fn usesRecursionGuards(self: *VM, obj: *PhpObject) bool {
        const class = obj.class_name;
        return self.hasMethod(class, "__get") or self.hasMethod(class, "__set") or
            self.hasMethod(class, "__isset") or self.hasMethod(class, "__unset") or
            self.hasMethod(class, "__debugInfo") or self.isInstanceOf(class, "JsonSerializable");
    }

    pub const MagicKind = enum { get, set, isset, unset };
    pub const MagicGuard = struct { obj: usize, name: []const u8, kind: MagicKind };

    // a guard set on a lazy proxy covers its instance too: the access the
    // proxy's magic method makes is forwarded there with the same guard
    pub fn magicGuarded(self: *VM, obj: *PhpObject, name: []const u8, kind: MagicKind) bool {
        for (self.magic_guards.items) |guard| {
            if (guard.kind != kind or !std.mem.eql(u8, guard.name, name)) continue;
            if (guard.obj == @intFromPtr(obj)) return true;
            const holder: *PhpObject = @ptrFromInt(guard.obj);
            if (holder.lazy) |state| if (state.backing == obj) return true;
        }
        return false;
    }

    // php runs a lazy object's property magic method on the lazy object
    // itself, before initializing it, for a name its class doesn't declare;
    // only the access that magic method makes initializes it. an
    // initialized proxy forwards instead while its instance's own magic
    // method runs for the name (php's GH-21478)
    fn lazyMagicFirst(self: *VM, obj: *PhpObject, name: []const u8, kind: MagicKind) bool {
        const state = obj.lazy orelse return false;
        if (state.running) return false;
        if (state.initializer == .null and state.backing == null) return false;
        if (obj.getSlotIndexForScope(name, self.currentDefiningClass()) != null) return false;
        if (!self.magicApplies(obj, name, kind)) return false;
        if (state.backing) |instance| if (self.magicGuarded(instance, name, kind)) return false;
        return true;
    }

    // the class has the magic method and it isn't already running for this
    // object and property: inside __get, reading the same property reads the
    // property itself (with its warnings) instead of calling __get again
    pub fn magicApplies(self: *VM, obj: *PhpObject, name: []const u8, kind: MagicKind) bool {
        const method = switch (kind) {
            .get => "__get",
            .set => "__set",
            .isset => "__isset",
            .unset => "__unset",
        };
        if (self.splArrayAsProps(obj)) return true;
        return self.hasMethod(obj.class_name, method) and !self.magicGuarded(obj, name, kind);
    }

    fn isSplArray(self: *VM, obj: *PhpObject) bool {
        return self.isInstanceOf(obj.class_name, "ArrayObject") or self.isInstanceOf(obj.class_name, "ArrayIterator");
    }

    // ArrayObject::ARRAY_AS_PROPS: a property that isn't there is an
    // element of the storage, past any magic method
    fn splArrayAsProps(self: *VM, obj: *PhpObject) bool {
        if (!self.isSplArray(obj)) return false;
        const flags = obj.get("__flags");
        return flags == .int and flags.int & 2 != 0;
    }

    // spl_array's read, write, has and unset property handlers for a
    // property that isn't there: the dimension handlers, which reach a
    // subclass's offsetGet() and the rest
    fn splPropertyAsDimension(self: *VM, obj: *PhpObject, kind: MagicKind, name: Value, value: Value) RuntimeError!Value {
        return switch (kind) {
            .get => self.callMethod(obj, "offsetGet", &.{name}),
            .set => self.callMethod(obj, "offsetSet", &.{ name, value }),
            .unset => self.callMethod(obj, "offsetUnset", &.{name}),
            .isset => blk: {
                if (try self.splOwnMethod(obj, "offsetExists")) {
                    var ctx = self.makeContext(null);
                    break :blk .{ .bool = try @import("../stdlib/spl.zig").arrayStorageIsset(&ctx, obj, name) };
                }
                const r = try self.callMethod(obj, "offsetExists", &.{name});
                break :blk .{ .bool = r.isTruthy() };
            },
        };
    }

    // runs __get, __set, __isset or __unset for a property under its guard.
    // the method gets its own copy of the name: the caller's may be a
    // temporary, and __get may return it
    pub fn callMagicProperty(self: *VM, obj: *PhpObject, kind: MagicKind, name: []const u8, value: Value) RuntimeError!Value {
        const owned = try Value.String.create(self.allocator, name);
        defer self.stackRelease(.{ .string = owned });
        if (self.isSplArray(obj)) {
            if (self.splArrayAsProps(obj)) return self.splPropertyAsDimension(obj, kind, .{ .string = owned }, value);
            // php's std handlers behind ArrayObject's own: a property the
            // scope can't see is an access error
            if (kind != .isset and try self.splOwnMagic(obj, kind)) {
                if (try self.accessDeniedMessage(obj, name)) |msg| {
                    defer self.allocator.free(msg);
                    try self.setPendingException("Error", msg);
                    return error.RuntimeError;
                }
            }
        }
        try self.magic_guards.append(self.allocator, .{ .obj = @intFromPtr(obj), .name = owned.bytes(), .kind = kind });
        defer self.dropMagicGuard(owned.bytes());
        const name_value: Value = .{ .string = owned };
        return switch (kind) {
            .get => self.callMethod(obj, "__get", &.{name_value}),
            .set => self.callMethod(obj, "__set", &.{ name_value, value }),
            .isset => self.callMethod(obj, "__isset", &.{name_value}),
            .unset => self.callMethod(obj, "__unset", &.{name_value}),
        };
    }

    fn dropMagicGuard(self: *VM, name: []const u8) void {
        var i: usize = self.magic_guards.items.len;
        while (i > 0) {
            i -= 1;
            if (self.magic_guards.items[i].name.ptr == name.ptr) {
                _ = self.magic_guards.orderedRemove(i);
                return;
            }
        }
    }

    fn callMagicGet(self: *VM, obj: *PhpObject, prop_name: []const u8) RuntimeError!Value {
        return self.callMagicProperty(obj, .get, prop_name, .null) catch |err| {
            if (err == error.RuntimeError) return error.RuntimeError;
            return .null;
        };
    }

    // php's zend_bad_property_name: a property name can't start with a nul
    // byte (that is how mangled private and protected names begin)
    pub fn badPropertyName(name: []const u8) bool {
        return name.len > 0 and name[0] == 0;
    }

    pub const bad_property_name_message = "Cannot access property starting with \"\\0\"";

    fn removeCallGuard(self: *VM, obj_id: usize, method_name: []const u8) void {
        var i: usize = self.magic_call_guard.items.len;
        while (i > 0) {
            i -= 1;
            if (self.magic_call_guard.items[i].obj_ptr == obj_id and std.mem.eql(u8, self.magic_call_guard.items[i].method_name, method_name)) {
                _ = self.magic_call_guard.swapRemove(i);
                return;
            }
        }
    }

    pub const ShutdownCallback = struct { callable: Value, args: []Value };

    // php's php_call_shutdown_functions: the callbacks run in registration
    // order, including ones registered while they run, with the arguments
    // given at registration. one that fails (an uncaught exception, left
    // pending for the caller to report, exit(), a fatal error) ends the
    // shutdown stage, as php's bailout does
    pub fn runShutdownCallbacks(self: *VM) !void {
        var engine = self.engineCall();
        self.native_call = &engine;
        defer self.native_call = engine.outer;
        defer self.releaseCallbackRegistries();
        var i: usize = 0;
        while (i < self.shutdown_callbacks.items.len) : (i += 1) {
            // the list can grow while the callback runs
            const cb = self.shutdown_callbacks.items[i];
            var ctx = self.makeContext(null);
            _ = ctx.invokeCallable(cb.callable, cb.args) catch |err| {
                // a user exception handler takes an uncaught exception, and
                // the next callback runs
                if (self.pending_exception != null and self.user_exception_handler != null and !self.uncatchable_fatal) {
                    self.dispatchUncaught();
                    if (self.pending_exception == null and !self.exit_requested) continue;
                }
                return err;
            };
        }
    }

    pub fn releaseCallbackRegistries(self: *VM) void {
        for (self.shutdown_callbacks.items) |cb| {
            self.releaseValue(cb.callable);
            for (cb.args) |v| self.releaseValue(v);
            self.allocator.free(cb.args);
        }
        self.shutdown_callbacks.clearRetainingCapacity();
        self.releaseTickFunctions();
        for (self.autoload_callbacks.items) |cb| self.releaseValue(cb);
        self.autoload_callbacks.clearRetainingCapacity();
        if (self.spl_autoload_extensions) |exts| self.allocator.free(exts);
        self.spl_autoload_extensions = null;
        if (self.user_error_handler) |h| self.releaseValue(h);
        self.user_error_handler = null;
        for (self.error_handler_stack.items) |entry| self.releaseValue(entry.handler);
        self.error_handler_stack.clearRetainingCapacity();
        if (self.user_exception_handler) |h| self.releaseValue(h);
        self.user_exception_handler = null;
        for (self.exception_handler_stack.items) |entry| if (entry) |h| self.releaseValue(h);
        self.exception_handler_stack.clearRetainingCapacity();
        var ini_it = self.ini_callbacks.valueIterator();
        while (ini_it.next()) |cb| self.releaseValue(cb.*);
        self.ini_callbacks.clearRetainingCapacity();
        @import("../stdlib/pcntl.zig").releaseHandlers(self);
    }

    // php raises a missing argument inside the callee: the error is at its
    // declaration and the trace starts with the callee and the arguments it
    // received. true when a handler took it
    fn throwTooFewArgs(self: *VM, name: []const u8, ac: usize, func: *const ObjFunction, args: []const Value) RuntimeError!bool {
        const msg = try self.formatTooFewArgs(name, ac, func);
        defer self.allocator.free(msg);
        const label = try self.callableDisplayName(name, func);
        var record: NativeCall = undefined;
        self.enterEngineMethod(&record, label, args, !func.is_static and std.mem.indexOf(u8, label, "::") != null);
        defer self.native_call = record.outer;
        if (try self.throwBuiltinExceptionAt("ArgumentCountError", msg, .{ .file = func.file_path, .line = func.start_line })) return true;
        self.setErrorMsg("Fatal error: Uncaught ArgumentCountError: {s}\n", .{msg});
        return false;
    }

    // shared formatter for ArgumentCountError messages: matches PHP's
    // 'Too few arguments to function X(), N passed in <file> on line N and
    // exactly|at least M expected'. caller location is the current top frame
    fn formatTooFewArgs(self: *VM, name: []const u8, ac: usize, func: *const ObjFunction) ![]const u8 {
        var caller_file: []const u8 = self.file_path;
        var caller_line: u32 = 0;
        if (self.frame_count >= 1) {
            const caller = &self.frames[self.frame_count - 1];
            if (caller.script_path.len > 0) caller_file = caller.script_path else if (caller.func) |cf| if (cf.file_path.len > 0) {
                caller_file = cf.file_path;
            };
            const cip: usize = if (caller.ip > 0) caller.ip - 1 else 0;
            if (self.sourceLocation(caller.chunk, cip)) |loc| caller_line = loc.line;
        }
        const modifier: []const u8 = if (func.required_params == func.arity) "exactly" else "at least";
        const shown = try self.callableDisplayName(name, func);
        return std.fmt.allocPrint(self.allocator, "Too few arguments to function {s}(), {d} passed in {s} on line {d} and {s} {d} expected", .{ shown, ac, caller_file, caller_line, modifier, func.required_params });
    }

    // too few arguments for a call made from native code (call_user_func and
    // the like): the ArgumentCountError goes pending for the caller's handlers
    fn raiseTooFewArgs(self: *VM, name: []const u8, args: []const Value, func: *const ObjFunction) RuntimeError {
        const ac = args.len;
        const display = try self.callableDisplayName(name, func);
        // php names the calling file and line only for a call from php code;
        // call_user_func compiles to one, a callback from array_map doesn't
        const caller = self.native_caller;
        const from_native = caller.name != null and caller.frames == self.frame_count;
        const from_php = !from_native or
            std.mem.eql(u8, caller.name.?, "call_user_func") or std.mem.eql(u8, caller.name.?, "call_user_func_array");
        const msg = if (from_php) try self.formatTooFewArgs(display, ac, func) else blk: {
            const modifier: []const u8 = if (func.required_params == func.arity) "exactly" else "at least";
            break :blk try std.fmt.allocPrint(self.allocator, "Too few arguments to function {s}(), {d} passed and {s} {d} expected", .{ display, ac, modifier, func.required_params });
        };
        defer self.allocator.free(msg);
        var record: NativeCall = undefined;
        self.enterEngineMethod(&record, display, args, !func.is_static and std.mem.indexOf(u8, display, "::") != null);
        defer self.native_call = record.outer;
        self.raise(.{ .object = try self.newBuiltinException("ArgumentCountError", msg, .{ .file = func.file_path, .line = func.start_line }) });
        return error.RuntimeError;
    }

    // `$f(...)` for anything but a plain function name, resolved as php's
    // dynamic call resolves it. null when an exception it raised was
    // dispatched to a handler the caller resumes at
    fn invokeDynamic(self: *VM, callable: Value, args: []const Value, base_frame: usize) RuntimeError!?Value {
        const resolution = callables.resolveDynamic(self, callable) catch {
            if (self.pending_exception != null and self.dispatchPendingException(base_frame)) return null;
            return error.RuntimeError;
        };
        switch (resolution) {
            .failure => |failure| {
                if (try callables.throwDynamicFailure(self, failure)) return null;
                return error.RuntimeError;
            },
            .callee => |callee| {
                const handlers_before = self.handler_count;
                return callables.invoke(self, callee, args) catch {
                    if (self.resumeAfterThrow(base_frame, handlers_before)) return null;
                    return error.RuntimeError;
                };
            },
        }
    }

    // an argument array of positional values followed by named ones
    pub fn argArray(self: *VM, positional: []const Value, named: ?*PhpArray) RuntimeError!*PhpArray {
        const arr = try self.allocArray();
        for (positional) |v| try arr.append(self.allocator, v);
        if (named) |n| for (n.entries.items) |entry| try arr.set(self.allocator, entry.key, entry.value);
        return arr;
    }

    // invokeDynamic for an argument array with named entries
    fn invokeDynamicArgArray(self: *VM, callable: Value, arr: *PhpArray, base_frame: usize) RuntimeError!?Value {
        const resolution = callables.resolveDynamic(self, callable) catch {
            if (self.pending_exception != null and self.dispatchPendingException(base_frame)) return null;
            return error.RuntimeError;
        };
        switch (resolution) {
            .failure => |failure| {
                if (try callables.throwDynamicFailure(self, failure)) return null;
                return error.RuntimeError;
            },
            .callee => |callee| {
                const handlers_before = self.handler_count;
                return callables.invokeArgArray(self, callee, arr) catch {
                    if (self.resumeAfterThrow(base_frame, handlers_before)) return null;
                    return error.RuntimeError;
                };
            },
        }
    }

    pub fn callValueCallable(self: *VM, callable: Value, args: []const Value) RuntimeError!Value {
        return callables.invoke(self, try self.callbackCallee(callable), args);
    }

    // what a callback calls when an internal function runs it. its callable
    // parameter was checked on the way in, so a method the running scope can
    // no longer see (a private method registered as a shutdown function) is
    // still the one it named; anything else php reports as an invalid callback
    pub fn callbackCallee(self: *VM, callable: Value) RuntimeError!callables.Callee {
        switch (try callables.resolveCallback(self, callable, .{ .deprecations = false })) {
            .callee => |callee| return callee,
            .failure => |failure| {
                if (failure == .inaccessible) return failure.inaccessible.direct;
                var buf: std.ArrayListUnmanaged(u8) = .empty;
                defer buf.deinit(self.allocator);
                try buf.appendSlice(self.allocator, "Invalid callback ");
                try callables.writeName(callable, &buf, self.allocator);
                try buf.appendSlice(self.allocator, ", ");
                try callables.writeReason(failure, &buf, self.allocator);
                try self.setPendingException("Error", buf.items);
                return error.RuntimeError;
            },
        }
    }

    // #[\NoDiscard] on a native: php warns at the call when the statement
    // throws the result away, before the function runs. a native that calls
    // it back (array_map) uses the result; a method native runs on a frame of
    // its own above the caller
    // zend_deprecated_function for an internal function or method
    fn warnDeprecatedNative(self: *VM, name: []const u8, suffix: []const u8) RuntimeError!void {
        const kind: []const u8 = if (std.mem.indexOf(u8, name, "::") != null) "Method" else "Function";
        const msg = try std.fmt.allocPrint(self.allocator, "{s} {s}() is deprecated{s}", .{ kind, name, suffix });
        defer self.allocator.free(msg);
        try self.raiseError(E_DEPRECATED, msg);
        if (self.pending_exception != null) return error.RuntimeError;
    }

    fn warnDiscardedNative(self: *VM, name: []const u8, reason: []const u8, outer: ?*const NativeCall, method: bool) RuntimeError!void {
        if (self.frame_count == 0) return;
        const own_frames: usize = @intFromBool(method);
        if (outer) |o| if (o.depth + own_frames == self.frame_count) return;
        const frame = self.currentFrame();
        const code = frame.chunk.code.items;
        if (frame.ip >= code.len or code[frame.ip] != @intFromEnum(OpCode.pop_boundary)) return;
        const kind: []const u8 = if (std.mem.indexOf(u8, name, "::") != null) "method" else "function";
        const msg = try std.fmt.allocPrint(self.allocator, "The return value of {s} {s}() should either be used or intentionally ignored by casting it as (void), {s}", .{ kind, name, reason });
        defer self.allocator.free(msg);
        const line: i64 = if (self.sourceLocation(frame.chunk, if (frame.ip > 0) frame.ip - 1 else 0)) |loc| @intCast(loc.line) else 0;
        try self.raiseErrorAt(E_WARNING, msg, .{ .file = self.frameFile(self.frame_count - 1), .line = line });
    }

    fn scalarArgFits(kind: natives_mod.ScalarParams.Kind, nullable: bool, arg: Value) bool {
        return switch (arg) {
            .null => nullable,
            .int => kind == .int or kind == .float,
            .float => kind == .float,
            .bool => kind == .bool,
            .string => kind == .string,
            else => false,
        };
    }

    fn scalarArgsNeedCoercion(self: *VM, scalars: natives_mod.ScalarParams, args: []const Value) RuntimeError!bool {
        _ = self;
        for (args, 0..) |arg, i| {
            if (!scalars.has(i)) continue;
            if (!scalarArgFits(scalars.kind(i), scalars.isNullable(i), arg)) return true;
        }
        return false;
    }

    // zend_parse_arg_{long,double,bool,str}_slow for a function's scalar
    // parameters in [from, to): an argument of another type is coerced in
    // weak mode (null deprecated) or refused with php's TypeError. a
    // replacement is transient; the slot gives back the reference the
    // original held for the call
    fn coerceScalarArgs(self: *VM, name: []const u8, label: []const u8, scalars: natives_mod.ScalarParams, args: []Value, from: usize, to: usize, called_by_native: bool) RuntimeError!void {
        const signature = native_params.get(name) orelse return;
        // an internal function calling another is never strict
        const strict = !called_by_native and self.topFrameStrict();
        var i = from;
        while (i < to) : (i += 1) {
            if (!scalars.has(i)) continue;
            const kind = scalars.kind(i);
            const nullable = scalars.isNullable(i);
            const arg = args[i];
            if (scalarArgFits(kind, nullable, arg)) continue;
            const param = signature.params[i];
            const replacement: ?Value = if (arg == .null or arg == .undef) blk: {
                if (strict) break :blk null;
                const msg = try std.fmt.allocPrint(self.allocator, "{s}(): Passing null to parameter #{d} (${s}) of type {s} is deprecated", .{ label, i + 1, param.name, param.type });
                defer self.allocator.free(msg);
                try self.raiseError(E_DEPRECATED, msg);
                if (self.pending_exception != null) return error.RuntimeError;
                break :blk switch (kind) {
                    .int => Value{ .int = 0 },
                    .float => Value{ .float = 0 },
                    .bool => Value{ .bool = false },
                    .string => Value{ .string = Value.String.borrowed("") },
                };
            } else if (strict)
                null
            else switch (kind) {
                .int => try self.weakScalarHint(php_types.LONG, arg),
                .float => try self.weakScalarHint(php_types.DOUBLE, arg),
                .bool => try self.weakScalarHint(php_types.BOOL, arg),
                .string => try self.weakScalarHint(php_types.STRING, arg),
            };
            if (self.pending_exception != null) return error.RuntimeError;
            const value = replacement orelse {
                const msg = try std.fmt.allocPrint(self.allocator, "{s}(): Argument #{d} (${s}) must be of type {s}, {s} given", .{ label, i + 1, param.name, param.type, valueTypeName(arg) });
                defer self.allocator.free(msg);
                try self.setPendingException("TypeError", msg);
                return error.RuntimeError;
            };
            stackRetain(value);
            self.stackRelease(args[i]);
            args[i] = value;
        }
    }

    // a native's `callable` and `array` parameters, checked in order as php's
    // argument parsing does before the function runs. a scalar parameter
    // before them that the argument cannot fit stops the checks: the native
    // reports that one itself
    fn checkCallbackArgs(self: *VM, name: []const u8, label: []const u8, callbacks: u32, arrays: u32, args: []const Value) RuntimeError!void {
        const signature = native_params.get(name) orelse return;
        if (signature.params.len == 0) return;
        for (args, 0..) |arg, i| {
            const param = signature.params[@min(i, signature.params.len - 1)];
            const is_callback = i < 32 and callbacks & (@as(u32, 1) << @intCast(i)) != 0;
            const is_array = if (i >= 31) (arrays & natives_mod.variadic_array_bit) != 0 else (arrays & (@as(u32, 1) << @intCast(i))) != 0;
            if (is_array) {
                if (arg == .array) continue;
                const shown = valueTypeName(arg);
                const msg = if (param.variadic)
                    try std.fmt.allocPrint(self.allocator, "{s}(): Argument #{d} must be of type array, {s} given", .{ label, i + 1, shown })
                else
                    try std.fmt.allocPrint(self.allocator, "{s}(): Argument #{d} (${s}) must be of type array, {s} given", .{ label, i + 1, param.name, shown });
                defer self.allocator.free(msg);
                try self.setPendingException("TypeError", msg);
                return error.RuntimeError;
            }
            if (!is_callback) {
                if (scalarParamRefuses(self, param.type, arg)) return;
                continue;
            }
            const nullable = param.type.len > 0 and param.type[0] == '?';
            if (nullable and arg == .null) continue;
            const resolved = callables.resolveCallback(self, arg, .{}) catch |err| {
                // an error handler threw from the check's deprecation. zpp
                // lets that exception go; call_user_func and
                // call_user_func_array are php's ZEND_INIT_USER_CALL, which
                // has no reason to give, so its TypeError says "(null)" and
                // takes the exception as its previous
                if (!std.mem.eql(u8, label, "call_user_func") and !std.mem.eql(u8, label, "call_user_func_array")) return err;
                const thrown = self.takePending() orelse return err;
                defer self.stackRelease(thrown);
                const msg = try std.fmt.allocPrint(self.allocator, "{s}(): Argument #{d} (${s}) must be a valid callback{s}, (null)", .{ label, i + 1, param.name, if (nullable) " or null" else "" });
                defer self.allocator.free(msg);
                try self.setPendingException("TypeError", msg);
                if (thrown == .object) if (self.pending_exception) |raised| if (raised == .object) {
                    _ = try self.chainPrevious(raised.object, thrown.object);
                };
                return error.RuntimeError;
            };
            switch (resolved) {
                .callee => continue,
                .failure => |failure| {
                    var buf: std.ArrayListUnmanaged(u8) = .empty;
                    defer buf.deinit(self.allocator);
                    try buf.print(self.allocator, "{s}(): Argument #{d} (${s}) must be a valid callback{s}, ", .{ label, i + 1, param.name, if (nullable) " or null" else "" });
                    try callables.writeReason(failure, &buf, self.allocator);
                    try self.setPendingException("TypeError", buf.items);
                    return error.RuntimeError;
                },
            }
        }
    }

    fn refuseObjectForString(self: *VM, name: []const u8, label: []const u8, i: usize, obj: *PhpObject) RuntimeError!void {
        if (obj.native.kind != .none and obj.native.kind != .closure and obj.native.kind != .fake_closure) return;
        if (self.hasMethod(obj.class_name, "__toString")) return;
        const signature = native_params.get(name) orelse return;
        if (i >= signature.params.len) return;
        const param = signature.params[i];
        const msg = try std.fmt.allocPrint(self.allocator, "{s}(): Argument #{d} (${s}) must be of type {s}, {s} given", .{ label, i + 1, param.name, param.type, class_names.display(obj.class_name) });
        defer self.allocator.free(msg);
        try self.setPendingException("TypeError", msg);
        return error.RuntimeError;
    }

    // an argument a scalar parameter can never take, whatever the mode
    fn scalarParamRefuses(self: *VM, param_type: []const u8, arg: Value) bool {
        const t = if (param_type.len > 0 and param_type[0] == '?') param_type[1..] else param_type;
        const scalar = std.mem.eql(u8, t, "string") or std.mem.eql(u8, t, "int") or std.mem.eql(u8, t, "float") or std.mem.eql(u8, t, "bool");
        if (!scalar) return false;
        return switch (arg) {
            .array, .resource => true,
            .object => |o| !std.mem.eql(u8, t, "string") or !self.hasMethod(o.class_name, "__toString"),
            else => false,
        };
    }

    pub fn callByName(self: *VM, raw_name: []const u8, args: []const Value) RuntimeError!Value {
        return self.callByNameAs(raw_name, args, null);
    }

    // called_class is what static:: names in a static method the call reaches
    // through a subclass (call_user_func(['Child', 'inheritedStatic']))
    pub fn callByNameAs(self: *VM, raw_name: []const u8, args: []const Value, called_class: ?[]const u8) RuntimeError!Value {
        // A native callback may execute calls at the same VM frame depth.
        // Restore the enclosing call's output-argument destinations afterwards.
        const saved_sources_count = self.ic.?.active_arg_count;
        var saved_sources: [256]RefSource = undefined;
        @memcpy(saved_sources[0..saved_sources_count], self.ic.?.active_args[0..saved_sources_count]);
        const saved_source_frame = self.ic.?.active_frame;
        for (self.ic.?.active_args[0..self.ic.?.active_arg_count]) |*source| source.* = self.retainArgSource(source.*);
        defer {
            self.clearActiveArgSources();
            @memcpy(self.ic.?.active_args[0..saved_sources_count], saved_sources[0..saved_sources_count]);
            self.ic.?.active_arg_count = saved_sources_count;
            self.ic.?.active_frame = saved_source_frame;
        }

        // PHP normalizes leading-backslash on function callable strings:
        // call_user_func('\App\f') and call_user_func('App\f') are equivalent
        const name = if (raw_name.len > 0 and raw_name[0] == '\\') raw_name[1..] else raw_name;
        if (self.native_fns.get(name)) |native| {
            // pass the resolved name as call_name so natives that key off it
            // (enum cases/from/tryFrom read the 'Class::method' prefix, rand vs
            // mt_rand distinguish by name) work when dispatched indirectly via
            // call_user_func / first-class-callable / array callable
            var ctx = self.makeContext(name);
            const result = try self.invokeNative(native, &ctx, .{ .args = args, .name = name, .dynamic = true });
            return self.borrowCallResult(result);
        } else if (self.functions.get(name)) |func| {
            if (args.len < func.required_params) return self.raiseTooFewArgs(name, args, func);
            var checked_buf: [16]Value = undefined;
            const checked = try self.checkedArgs(name, func, args, &checked_buf);
            defer if (checked.ptr != &checked_buf and checked.ptr != args.ptr) self.allocator.free(checked);
            return self.callUserFunction(name, func, checked, called_class);
        } else if (self.functionNamedIgnoringCase(name)) |registered| {
            return self.callByNameAs(registered, args, called_class);
        } else if (self.staticMethodNamed(name)) |registered| {
            return self.callByNameAs(registered, args, called_class);
        } else return error.RuntimeError;
    }

    // the registered method a "Class::method" string reaches when its class or
    // method is spelled in another case than the declaration
    pub fn staticMethodNamed(self: *VM, name: []const u8) ?[]const u8 {
        const sep = std.mem.indexOf(u8, name, "::") orelse return null;
        // a miss leaves an autoloader's exception pending for the caller to raise
        const resolved = self.resolveMethod(self.declaredClassName(name[0..sep]), name[sep + 2 ..]) catch return null;
        if (std.mem.eql(u8, resolved, name)) return null;
        return resolved;
    }

    // the arguments a native passes to a user function, after the callee's
    // parameter types: coerced in weak mode (calls from internal functions
    // are never strict), or a pending TypeError
    fn checkedArgs(self: *VM, name: []const u8, func: *const ObjFunction, args: []const Value, buf: *[16]Value) RuntimeError![]const Value {
        if (!func.has_param_types or g_type_info.count() == 0) return args;
        const copy = if (args.len <= buf.len) buf[0..args.len] else try self.allocator.alloc(Value, args.len);
        @memcpy(copy, args);
        const internal = self.calledFromNative();
        const exc = (self.enforceArgTypes(name, copy, .{ .strict = if (internal) false else self.topFrameStrict(), .internal = internal }) catch |err| {
            if (copy.ptr != buf) self.allocator.free(copy);
            return err;
        }) orelse return copy;
        if (copy.ptr != buf) self.allocator.free(copy);
        self.raise(.{ .object = exc });
        return error.RuntimeError;
    }

    fn callUserFunction(self: *VM, name: []const u8, func: *const ObjFunction, args: []const Value, called_class: ?[]const u8) RuntimeError!Value {
        // a generator function called back (call_user_func, array_map)
        // returns its generator without running the body
        if (func.is_generator) {
            var new_vars = self.acquireFrameVars();
            var closure_refs: std.StringHashMapUnmanaged(*Value) = .{};
            try self.bindClosures(&new_vars, &closure_refs, name);
            try self.bindArgs(&new_vars, func, if (func.is_variadic) args else args[0..@min(args.len, func.arity)]);
            const gen = try self.allocGenerator(.{ .func = func, .vars = new_vars, .ref_slots = closure_refs, .called_class = called_class });
            retainVarsObjects(&gen.vars);
            if (!func.is_variadic and args.len > func.arity) try self.keepGeneratorExtraArgs(gen, args[func.arity..]);
            self.keepGeneratorClosure(gen, name);
            return .{ .generator = gen };
        }
        {
            if (self.ic) |ic| ic.pending_arg_count = @intCast(@min(args.len, unknown_arg_count - 1));
            self.pending_call_name = name;
            self.pending_called_class = called_class orelse self.closureScopeByName(name);
            const saved_pia_outer = self.pending_invoke_args;
            self.pending_invoke_args = args;
            defer self.pending_invoke_args = saved_pia_outer;
            if (func.locals_only) {
                if (self.captures.items.len == 0)
                    return self.executeFunctionLocalsOnly(func, args);
                if (std.mem.startsWith(u8, name, "__closure_")) {
                    if (!self.hasCaptures(name))
                        return self.executeFunctionLocalsOnly(func, args);
                    if (!self.closureHasRefCaptures(name))
                        return self.executeClosureLocalsOnly(func, name, args);
                } else {
                    if (!self.hasCaptures(name))
                        return self.executeFunctionLocalsOnly(func, args);
                }
            }
            var new_vars = self.acquireFrameVars();
            var closure_refs: std.StringHashMapUnmanaged(*Value) = .{};
            try self.bindClosures(&new_vars, &closure_refs, name);
            const trimmed = if (func.is_variadic) args else args[0..@min(args.len, func.arity)];
            try self.bindArgs(&new_vars, func, trimmed);
            if (closure_refs.count() > 0) {
                return self.executeFunctionWithRefs(func, new_vars, closure_refs);
            }
            return self.executeFunction(func, new_vars);
        }
    }

    fn closureHasRefCaptures(self: *VM, name: []const u8) bool {
        if (self.capture_index.get(name)) |range| return range.has_refs;
        return false;
    }

    fn hasCaptures(self: *VM, name: []const u8) bool {
        return self.capture_index.contains(name);
    }

    pub fn getCaptureRange(self: *VM, name: []const u8) ?CaptureRange {
        return self.capture_index.get(name);
    }

    // a closure invoked with no frame on the stack (a shutdown callback after
    // a serve request) has no caller scope to inherit
    fn callerCalledClass(self: *VM) ?[]const u8 {
        if (self.frame_count == 0) return null;
        return self.currentFrame().called_class;
    }

    fn executeClosureLocalsOnly(self: *VM, func: *const ObjFunction, name: []const u8, args: []const Value) RuntimeError!Value {
        const base_frame = self.frame_count;
        const lc: usize = func.local_count;
        const ic = self.ic.?;
        const lbase = ic.locals_sp;

        const locals = if (lbase + lc <= ic.locals_cap) blk: {
            const s = ic.locals_buf[lbase .. lbase + lc];
            @memset(s, .undef);
            ic.locals_sp = lbase + lc;
            break :blk s;
        } else blk: {
            const s = try self.allocator.alloc(Value, lc);
            @memset(s, .undef);
            break :blk s;
        };

        const bind_count = @min(args.len, func.arity);
        for (0..bind_count) |i| {
            locals[i] = try self.bindFrameArg(args[i]);
        }
        try self.fillDefaultLocalsForCaller(func, locals, bind_count, 0);
        // bind captures (no ref cells here - ref captures take the slow path)
        if (self.getCaptureRange(name)) |cr| {
            const caps = self.captures.items[cr.start .. cr.start + cr.len];
            for (caps) |cap| {
                for (func.slot_names, 0..) |sn, si| {
                    if (sn.len == cap.var_name.len and std.mem.eql(u8, sn, cap.var_name)) {
                        locals[si] = try self.copyCapturedValue(cap.value);
                        break;
                    }
                }
            }
        }
        const base_handler = self.handler_count;
        const prev_floor = self.handler_floor;
        self.handler_floor = self.handler_count;
        try self.ensureCallRoom();
        self.frames[self.frame_count] = .{ .chunk = &func.chunk, .ip = 0, .vars = .{}, .locals = locals, .func = func, .called_class = self.closureScopeByName(name) orelse self.callerCalledClass(), .call_name = name };
        self.frames[self.frame_count].entry_sp = self.sp;
        // the frame names its closure itself; one left pending would be taken
        // by the next frame executeFunction builds
        self.pending_call_name = null;
        self.pending_called_class = null;
        self.consumePendingArgCount();
        self.saveFrameArgsSlice(args);
        self.frame_count += 1;
        self.retainFrameObjects(self.frame_count - 1);
        if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;
        // with too little native stack left, runUntilFrame raises php's Error
        if (!stack_limit.overflowed()) self.fastLoop() catch |err| {
            self.handler_count = base_handler;
            self.handler_floor = prev_floor;
            self.unwindFailedCall(base_frame);
            return err;
        };
        if (self.frame_count > base_frame) {
            self.runUntilFrame(base_frame) catch |err| {
                self.handler_count = base_handler;
                self.handler_floor = prev_floor;
                self.unwindFailedCall(base_frame);
                return err;
            };
        }
        self.handler_count = base_handler;
        self.handler_floor = prev_floor;
        return self.pop();
    }

    // ref-propagating method dispatch. mirrors callByNameRef but resolves
    // through the class's method table. needed for callables like
    // [$obj, 'method'] or [Class::class, 'method'] when the target declares
    // by-ref params - without writeback, array_walk + an object-method
    // callback can't mutate the array entries
    pub fn callMethodRef(self: *VM, obj: *PhpObject, method_name: []const u8, args: []Value) RuntimeError!Value {
        return self.callMethodRefAs(obj, method_name, null, args);
    }

    pub fn callMethodRefAs(self: *VM, obj: *PhpObject, method_name: []const u8, registered: ?[]const u8, args: []Value) RuntimeError!Value {
        const full_name = registered orelse self.resolveMethod(obj.class_name, method_name) catch return error.RuntimeError;
        if (self.functions.get(full_name)) |func| {
            if (func.ref_params.len == 0) {
                return self.callMethodAs(obj, method_name, registered, args);
            }
            const bind_count = @min(args.len, func.arity);
            var new_vars = self.acquireFrameVars();
            try new_vars.put(self.allocator, "$this", .{ .object = obj });
            var ref_slots: std.StringHashMapUnmanaged(*Value) = .{};
            try self.bindClosures(&new_vars, &ref_slots, full_name);

            var cells: [16]?*Value = @splat(null);
            defer for (cells) |maybe| {
                if (maybe) |cell| self.unbindCell(cell);
            };
            for (0..bind_count) |i| {
                try new_vars.put(self.allocator, func.params[i], try self.bindFrameArg(args[i]));
                if (i < func.ref_params.len and func.ref_params[i] and i < 16) {
                    const cell = try self.newRefCell();
                    self.setCell(cell, args[i]);

                    try self.bindRefSlot(&ref_slots, func.params[i], cell);
                    self.bindCell(cell);
                    cells[i] = cell;
                }
            }
            try self.fillDefaults(&new_vars, func, bind_count);

            const result = try self.executeFunctionWithRefs(func, new_vars, ref_slots);

            for (0..bind_count) |i| {
                if (cells[i]) |cell| args[i] = cell.*;
            }
            return result;
        }
        return self.callMethodAs(obj, method_name, registered, args);
    }

    pub fn callByNameRef(self: *VM, raw_name: []const u8, args: []Value) RuntimeError!Value {
        return self.callByNameRefAs(raw_name, args, null);
    }

    pub fn callByNameRefAs(self: *VM, raw_name: []const u8, args: []Value, called_class: ?[]const u8) RuntimeError!Value {
        const name = if (raw_name.len > 0 and raw_name[0] == '\\') raw_name[1..] else raw_name;
        if (self.functions.get(name)) |func| {
            if (func.ref_params.len == 0) {
                return self.callByNameAs(name, args, called_class);
            }
            if (args.len < func.required_params) return self.raiseTooFewArgs(name, args, func);
            // a variadic parameter collects what the fixed ones leave
            const fixed: usize = if (func.is_variadic) func.arity - 1 else func.arity;
            const bind_count = @min(args.len, fixed);
            var new_vars = self.acquireFrameVars();
            var ref_slots: std.StringHashMapUnmanaged(*Value) = .{};
            try self.bindClosures(&new_vars, &ref_slots, name);

            var cells: [16]?*Value = @splat(null);
            defer for (cells) |maybe| {
                if (maybe) |cell| self.unbindCell(cell);
            };
            for (0..bind_count) |i| {
                try new_vars.put(self.allocator, func.params[i], try self.bindFrameArg(args[i]));
                if (i < func.ref_params.len and func.ref_params[i] and i < 16) {
                    const cell = try self.newRefCell();
                    self.setCell(cell, args[i]);

                    try self.bindRefSlot(&ref_slots, func.params[i], cell);
                    self.bindCell(cell);
                    cells[i] = cell;
                }
            }
            if (func.is_variadic) {
                for (bind_count..fixed) |i| {
                    if (i < func.defaults.len) try new_vars.put(self.allocator, func.params[i], try self.resolveParamDefault(func, i));
                }
                const rest_arr = try self.allocArray();
                for (args[bind_count..]) |arg| try rest_arr.append(self.allocator, try self.bindFrameArg(arg));
                try new_vars.put(self.allocator, func.params[fixed], .{ .array = rest_arr });
            } else {
                try self.fillDefaults(&new_vars, func, bind_count);
            }

            self.pending_call_name = name;
            self.pending_called_class = called_class orelse self.closureScopeByName(name);
            const result = try self.executeFunctionWithRefs(func, new_vars, ref_slots);

            for (0..bind_count) |i| {
                if (cells[i]) |cell| {
                    args[i] = cell.*;
                }
            }
            return result;
        }
        const saved_ref_args = self.pending_ref_args;
        self.pending_ref_args = args;
        defer self.pending_ref_args = saved_ref_args;
        return self.callByNameAs(name, args, called_class);
    }

    // fibers

    fn executeFiber(self: *VM, fiber: *Fiber, base_frame: usize, base_sp: usize, base_handler: usize) RuntimeError!Value {
        const prev_fiber = self.current_fiber;
        const prev_floor = self.handler_floor;
        self.current_fiber = fiber;
        self.handler_floor = base_handler;
        const prev_blocked = self.fiber_switch_blocked;
        self.fiber_switch_blocked = 0;
        defer self.fiber_switch_blocked = prev_blocked;

        self.runUntilFrame(base_frame) catch |err| {
            self.current_fiber = prev_fiber;
            self.handler_floor = prev_floor;
            if (self.fiber_suspend_pending) {
                self.fiber_suspend_pending = false;
                try self.saveFiberState(fiber, base_frame, base_sp, base_handler);
                fiber.state = .suspended;
                const result = self.fiber_suspend_value;
                self.fiber_suspend_value = .null;
                self.releaseValue(fiber.suspend_value);
                fiber.suspend_value = result;
                return result;
            }
            fiber.state = .terminated;
            // clean up any frames left on the stack
            while (self.frame_count > base_frame) {
                self.frame_count -= 1;
                self.deinitFrameSlot(self.frame_count);
            }
            self.clearArgStackFrom(base_sp);
            self.sp = base_sp;
            self.handler_count = base_handler;
            return err;
        };

        self.current_fiber = prev_fiber;
        self.handler_floor = prev_floor;
        fiber.state = .terminated;
        if (self.sp > base_sp) {
            fiber.return_value = self.popTransfer();
            if (fiber.return_value == .array) retainValue(fiber.return_value);
        }
        self.clearArgStackFrom(base_sp);
        self.sp = base_sp;
        return .null;
    }

    const FiberMethod = enum { start, @"resume", throw, getReturn, isStarted, isSuspended, isRunning, isTerminated, __construct };

    // the instance methods of php's Fiber class (zend_fibers.c). the value
    // returned is borrowed from the fiber
    pub fn fiberMethod(self: *VM, fiber: *Fiber, name: []const u8, args: []const Value) RuntimeError!Value {
        const method = inline for (comptime std.enums.values(FiberMethod)) |m| {
            if (std.ascii.eqlIgnoreCase(name, @tagName(m))) break m;
        } else {
            const msg = try std.fmt.allocPrint(self.allocator, "Call to undefined method Fiber::{s}()", .{name});
            defer self.allocator.free(msg);
            try self.setPendingException("Error", msg);
            return error.RuntimeError;
        };
        const label = switch (method) {
            inline else => |m| "Fiber::" ++ @tagName(m),
        };
        var record: NativeCall = undefined;
        self.enterEngineMethod(&record, label, args, true);
        defer self.native_call = record.outer;
        const unbounded = @import("natives.zig").Arity.unbounded;
        const min: u16, const max: u16 = switch (method) {
            .start => .{ 0, unbounded },
            .@"resume" => .{ 0, 1 },
            .throw, .__construct => .{ 1, 1 },
            else => .{ 0, 0 },
        };
        if (args.len < min or (max != unbounded and args.len > max)) return self.argumentCountError(label, min, max, args.len);
        switch (method) {
            .start => {
                if (fiber.state != .created) return self.fiberError("Cannot start a fiber that has already been started");
                // php allocates the fiber's stack here: fiber.stack_size
                // must leave a page and its guard page
                if (self.ini_settings.get("fiber.stack_size")) |configured| {
                    const minimum = 2 * std.heap.pageSize();
                    const size = @import("memory.zig").parseQuantity(configured).value;
                    if (size >= 0 and size < minimum) {
                        const msg = try std.fmt.allocPrint(self.allocator, "Fiber stack size is too small, it needs to be at least {d} bytes", .{minimum});
                        defer self.allocator.free(msg);
                        try self.setPendingException("Exception", msg);
                        return error.RuntimeError;
                    }
                }
                return self.startFiber(fiber, args);
            },
            .@"resume", .throw => {
                const value: Value = if (args.len > 0) args[0] else .null;
                if (method == .throw and (value != .object or !self.isInstanceOf(value.object.class_name, "Throwable"))) {
                    const msg = try std.fmt.allocPrint(self.allocator, "Fiber::throw(): Argument #1 ($exception) must be of type Throwable, {s} given", .{valueTypeName(value)});
                    defer self.allocator.free(msg);
                    try self.setPendingException("TypeError", msg);
                    return error.RuntimeError;
                }
                if (fiber.state != .suspended) return self.fiberError("Cannot resume a fiber that is not suspended");
                return self.resumeFiber(fiber, value, method == .throw);
            },
            .getReturn => {
                const reason = switch (fiber.state) {
                    .terminated => if (fiber.threw) "The fiber threw an exception" else return fiber.return_value,
                    .created => "The fiber has not been started",
                    else => "The fiber has not returned",
                };
                const msg = try std.fmt.allocPrint(self.allocator, "Cannot get fiber return value: {s}", .{reason});
                defer self.allocator.free(msg);
                return self.fiberError(msg);
            },
            .isStarted => return .{ .bool = fiber.state != .created },
            .isSuspended => return .{ .bool = fiber.state == .suspended },
            .isRunning => return .{ .bool = fiber.state == .running },
            .isTerminated => return .{ .bool = fiber.state == .terminated },
            .__construct => return self.fiberError("Cannot call constructor twice"),
        }
    }

    // php's zend_fiber_object_destroy: a suspended fiber that is destroyed
    // is resumed with php's graceful exit, which no catch takes, so its
    // finally blocks run; Fiber::suspend() in one is an error. an exception
    // it throws reaches the code that destroyed it, with one in flight as
    // its previous
    pub fn destroyFiber(self: *VM, fiber: *Fiber) void {
        if (fiber.state != .suspended) return;
        const marker = self.unwindMarker() catch return;
        const in_flight = self.takePending();
        defer self.settleDrainException(in_flight);
        fiber.destroyed = true;
        // the engine resumes it: its frames read as called from an internal
        // function
        var engine = self.engineCall();
        self.native_call = &engine;
        defer self.native_call = engine.outer;
        _ = self.resumeFiber(fiber, .{ .object = marker }, true) catch {};
        if (self.pending_exception) |ex| if (self.isUnwindMarker(ex)) {
            self.discardPending();
            fiber.threw = false;
        };
    }

    fn fiberError(self: *VM, msg: []const u8) RuntimeError {
        try self.setPendingException("FiberError", msg);
        return error.RuntimeError;
    }

    // Fiber::start(): the callable's frame becomes the fiber's first, and
    // runs until it suspends or ends
    fn startFiber(self: *VM, fiber: *Fiber, args: []const Value) RuntimeError!Value {
        self.releaseValue(fiber.suspend_value);
        fiber.suspend_value = .null;
        fiber.state = .running;
        const fb = self.frame_count;
        const sb = self.sp;
        const hb = self.handler_count;
        // an argument error belongs to the caller of start(), never to a
        // handler the engine would enter in place
        const prev_floor = self.handler_floor;
        self.handler_floor = hb;
        const prev_fiber = self.current_fiber;
        self.current_fiber = fiber;
        defer self.current_fiber = prev_fiber;
        defer self.handler_floor = prev_floor;
        const pushed = self.pushFiberEntryFrame(fiber, args) catch |err| {
            fiber.state = .terminated;
            fiber.threw = self.pending_exception != null;
            return err;
        };
        if (!pushed or self.frame_count == fb) {
            // a callable that ran to its end at once (an internal function)
            fiber.state = .terminated;
            if (pushed and self.sp > sb) {
                self.releaseValue(fiber.return_value);
                fiber.return_value = self.pop();
                retainValue(fiber.return_value);
            }
            self.clearArgStackFrom(sb);
            self.sp = sb;
            return .null;
        }
        return self.runFiber(fiber, fb, sb, hb);
    }

    // Fiber::resume() and Fiber::throw(): the fiber's frames go back on the
    // stack, and the suspended Fiber::suspend() returns the value or throws
    fn resumeFiber(self: *VM, fiber: *Fiber, value: Value, throw: bool) RuntimeError!Value {
        self.releaseValue(fiber.suspend_value);
        fiber.suspend_value = .null;
        fiber.state = .running;
        const fb = self.frame_count;
        const sb = self.sp;
        const hb = self.handler_count;
        try self.restoreFiberState(fiber, fb, sb);
        if (!throw) {
            self.push(value);
            return self.runFiber(fiber, fb, sb, hb);
        }
        self.push(.null);
        const prev_fiber = self.current_fiber;
        const prev_floor = self.handler_floor;
        self.current_fiber = fiber;
        self.handler_floor = hb;
        self.raise(value);
        const dispatched = self.dispatchPendingException(fb);
        self.current_fiber = prev_fiber;
        self.handler_floor = prev_floor;
        if (!dispatched) {
            fiber.state = .terminated;
            fiber.threw = true;
            while (self.frame_count > fb) {
                self.frame_count -= 1;
                self.deinitFrameSlot(self.frame_count);
            }
            self.clearArgStackFrom(sb);
            self.sp = sb;
            self.handler_count = hb;
            return error.RuntimeError;
        }
        return self.runFiber(fiber, fb, sb, hb);
    }

    fn runFiber(self: *VM, fiber: *Fiber, fb: usize, sb: usize, hb: usize) RuntimeError!Value {
        // each fiber has its own error_reporting, as php's fiber vm state:
        // an @ outside doesn't reach in, nor one inside out
        const outer_silence = self.error_silenced_depth;
        const outer_level = self.error_reporting_level;
        self.error_silenced_depth = fiber.saved_silence;
        if (fiber.saved_level) |level| self.error_reporting_level = level;
        defer {
            if (fiber.state == .suspended) {
                fiber.saved_silence = self.error_silenced_depth;
                fiber.saved_level = self.error_reporting_level;
            }
            self.error_silenced_depth = outer_silence;
            self.error_reporting_level = outer_level;
        }
        _ = self.executeFiber(fiber, fb, sb, hb) catch |err| {
            if (fiber.state == .terminated and self.pending_exception != null) fiber.threw = true;
            return err;
        };
        return fiber.suspend_value;
    }

    // pushes the frame of the fiber's callable with its arguments, as the
    // fiber's first frame. false when the callable is not user code and ran
    // to its end instead
    fn pushFiberEntryFrame(self: *VM, fiber: *Fiber, args: []const Value) RuntimeError!bool {
        const callable = fiber.callable;
        const fiber_fn: ?[]const u8 = if (callable.closureName()) |closure| closure else if (callable == .string) callable.string.bytes() else null;
        if (fiber_fn) |fn_name| {
            for (args) |arg| self.push(arg);
            try self.callNamedFunction(fn_name, @intCast(args.len));
            return true;
        }
        const resolution = try callables.resolveCallback(self, callable, .{ .deprecations = false });
        const callee = switch (resolution) {
            .callee => |c| c,
            .failure => {
                var ctx = self.makeContext(null);
                _ = try ctx.invokeCallable(callable, args);
                return false;
            },
        };
        const target: ?struct { name: []const u8, this: ?*PhpObject, called_class: ?[]const u8 } = switch (callee) {
            .function => |name| if (self.functions.get(name) != null) .{ .name = name, .this = null, .called_class = null } else null,
            .invoke => |obj| .{ .name = try self.resolveMethod(obj.class_name, "__invoke"), .this = obj, .called_class = obj.class_name },
            .method => |m| .{ .name = m.registered orelse try self.resolveMethod(m.object.class_name, m.name), .this = m.object, .called_class = m.object.class_name },
            .static_method => |m| .{ .name = m.registered, .this = null, .called_class = m.called_class },
            else => null,
        };
        const t = target orelse {
            _ = try callables.invoke(self, callee, args);
            return false;
        };
        const func = self.functions.get(t.name) orelse {
            _ = try callables.invoke(self, callee, args);
            return false;
        };
        if (t.this == null) {
            for (args) |arg| self.push(arg);
            try self.callNamedFunction(t.name, @intCast(args.len));
            if (t.called_class) |cc| self.frames[self.frame_count - 1].called_class = cc;
            return true;
        }
        if (args.len < func.required_params) return self.raiseTooFewArgs(t.name, args, func);
        var checked_buf: [16]Value = undefined;
        const checked = try self.checkedArgs(t.name, func, args, &checked_buf);
        defer if (checked.ptr != &checked_buf and checked.ptr != args.ptr) self.allocator.free(checked);
        var vars = self.acquireFrameVars();
        try vars.put(self.allocator, "$this", .{ .object = t.this.? });
        try self.bindClosures(&vars, null, t.name);
        try self.bindArgs(&vars, func, if (func.is_variadic) checked else checked[0..@min(checked.len, func.arity)]);
        try self.ensureCallRoom();
        self.frames[self.frame_count] = .{ .chunk = &func.chunk, .ip = 0, .vars = vars, .locals = try self.allocLocals(func, &vars), .func = func, .called_class = t.called_class };
        self.frames[self.frame_count].entry_sp = self.sp;
        if (self.ic) |ic| ic.arg_counts[self.frame_count] = @intCast(@min(args.len, unknown_arg_count - 1));
        self.saveFrameArgsSlice(args);
        self.frame_count += 1;
        self.retainFrameObjects(self.frame_count - 1);
        if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;
        return true;
    }

    fn saveFiberState(self: *VM, fiber: *Fiber, base_frame: usize, base_sp: usize, base_handler: usize) !void {
        self.cleanupFiberFrames(fiber);
        fiber.saved_frames.clearRetainingCapacity();
        fiber.saved_stack.clearRetainingCapacity();
        fiber.saved_handlers.clearRetainingCapacity();

        // save frames (move ownership of vars/ref_bindings/locals to fiber)
        for (self.frames[base_frame..self.frame_count]) |*frame| {
            try fiber.saved_frames.append(self.allocator, .{
                .chunk = frame.chunk,
                .ip = frame.ip,
                .vars = frame.vars,
                .locals = frame.locals,
                .func = frame.func,
                .called_class = frame.called_class,
                .generator = frame.generator,
                .ref_slots = frame.ref_slots,
                .ref_owner = frame.ref_owner,
                .call_name = frame.call_name,
            });
            // null out the source's owned data so VM cleanup can't double-free
            frame.vars = .{};
            frame.ref_slots = .{};
            frame.ref_owner = 0;
            frame.locals = &.{};
        }
        self.frame_count = base_frame;

        for (self.stack[base_sp..self.sp]) |val| {
            try fiber.saved_stack.append(self.allocator, val);
        }
        self.clearArgStackFrom(base_sp);
        self.sp = base_sp;

        // save exception handlers as relative offsets
        for (self.exception_handlers[base_handler..self.handler_count]) |h| {
            try fiber.saved_handlers.append(self.allocator, .{
                .catch_ip = h.catch_ip,
                .frame_count_offset = h.frame_count - base_frame,
                .sp_offset = h.sp - base_sp,
                .chunk = h.chunk,
            });
        }
        self.handler_count = base_handler;
    }

    fn restoreFiberState(self: *VM, fiber: *Fiber, base_frame: usize, base_sp: usize) RuntimeError!void {
        try self.ensureCallRoomFor(fiber.saved_frames.items.len + 1);
        try self.ensureStackSlots(fiber.saved_stack.items.len);
        try self.ensureHandlerRoom(fiber.saved_handlers.items.len);
        // restore frames (move ownership back to VM)
        for (fiber.saved_frames.items, 0..) |*frame, i| {
            self.frames[base_frame + i] = .{
                .chunk = frame.chunk,
                .ip = frame.ip,
                .vars = frame.vars,
                .locals = frame.locals,
                .func = frame.func,
                .called_class = frame.called_class,
                .generator = frame.generator,
                .ref_slots = frame.ref_slots,
                .ref_owner = frame.ref_owner,
                .call_name = frame.call_name,
            };
            // null out source to avoid double-free if cleanupFiberFrames runs later
            frame.vars = .{};
            frame.ref_slots = .{};
            frame.ref_owner = 0;
            frame.locals = &.{};
        }
        self.frame_count = base_frame + fiber.saved_frames.items.len;
        fiber.saved_frames.clearRetainingCapacity();

        for (fiber.saved_stack.items) |val| {
            self.stack[self.sp] = val;
            self.sp += 1;
        }
        fiber.saved_stack.clearRetainingCapacity();

        // restore exception handlers with absolute values
        for (fiber.saved_handlers.items) |h| {
            self.exception_handlers[self.handler_count] = .{
                .catch_ip = h.catch_ip,
                .frame_count = base_frame + h.frame_count_offset,
                .sp = base_sp + h.sp_offset,
                .chunk = h.chunk,
                .silenced_depth = self.error_silenced_depth,
            };
            self.handler_count += 1;
        }
        fiber.saved_handlers.clearRetainingCapacity();
    }

    inline fn readByte(self: *VM) u8 {
        const frame = &self.frames[self.frame_count - 1];
        const byte = frame.chunk.code.items[frame.ip];
        frame.ip += 1;
        return byte;
    }

    inline fn readU16(self: *VM) u16 {
        const hi: u16 = self.readByte();
        const lo: u16 = self.readByte();
        return (hi << 8) | lo;
    }

    fn readU32(self: *VM) u32 {
        const b0: u32 = self.readByte();
        const b1: u32 = self.readByte();
        const b2: u32 = self.readByte();
        const b3: u32 = self.readByte();
        return (b0 << 24) | (b1 << 16) | (b2 << 8) | b3;
    }

    pub fn currentChunk(self: *const VM) *const Chunk {
        return self.frames[self.frame_count - 1].chunk;
    }

    pub fn currentFrame(self: *VM) *CallFrame {
        return &self.frames[self.frame_count - 1];
    }

    // an arg_counts entry for a frame whose argument count isn't known
    pub const unknown_arg_count: u32 = std.math.maxInt(u32);

    fn setFrameArgCount(self: *VM, ac: u32) void {
        if (self.ic) |ic| ic.arg_counts[self.frame_count] = ac;
    }

    fn consumePendingArgCount(self: *VM) void {
        if (self.ic) |ic| {
            ic.arg_counts[self.frame_count] = ic.pending_arg_count;
            ic.pending_arg_count = unknown_arg_count;
        }
    }

    pub fn getFrameArgCount(self: *VM) ?u32 {
        const ic = self.ic orelse return null;
        const ac = ic.arg_counts[self.frame_count - 1];
        if (ac == unknown_arg_count) return null;
        return ac;
    }

    // how deep calls may go: frames, and operand stack slots beside them
    pub const max_frames: usize = 1 << 18;
    const max_stack_slots: usize = 1 << 21;
    // operand slots a single frame may use; the region past what is committed
    // faults, so a frame that outgrows this stops instead of overwriting
    const stack_headroom: usize = 1 << 14;
    // func_get_args room every frame keeps; a call passing more grows it
    // beforehand (fgaRoomFor)
    const fga_headroom: usize = 256;
    const max_handlers: usize = 1 << 20;

    fn reserveCallRegions(self: *VM) RuntimeError!void {
        const ic = self.ic.?;
        self.frame_room = Region(CallFrame).reserve(max_frames) catch return error.OutOfMemory;
        self.frames = self.frame_room.items;
        self.stack_room = Region(Value).reserve(max_stack_slots) catch return error.OutOfMemory;
        self.stack = self.stack_room.items;
        ic.arg_stack_room = Region(RefSource).reserve(max_stack_slots) catch return error.OutOfMemory;
        ic.arg_stack = ic.arg_stack_room.items;
        ic.sp_save_room = Region(usize).reserve(max_frames) catch return error.OutOfMemory;
        ic.sp_save = ic.sp_save_room.items;
        ic.arg_counts_room = Region(u32).reserve(max_frames) catch return error.OutOfMemory;
        ic.arg_counts = ic.arg_counts_room.items;
        ic.fga_offsets_room = Region(u32).reserve(max_frames) catch return error.OutOfMemory;
        ic.fga_offsets = ic.fga_offsets_room.items;
        ic.fga_room = Region(Value).reserve(max_stack_slots) catch return error.OutOfMemory;
        ic.fga_buf = ic.fga_room.items;
        self.handler_room = Region(ExceptionHandler).reserve(max_handlers) catch return error.OutOfMemory;
        self.exception_handlers = self.handler_room.items;
        _ = self.handler_room.ensure(256) catch return error.OutOfMemory;
        if (!try self.growCallRoom(64)) return error.OutOfMemory;
    }

    // room for `count` more try blocks entered
    pub fn ensureHandlerRoom(self: *VM, count: usize) RuntimeError!void {
        const want = self.handler_count + count;
        if (want <= self.handler_room.committed) return;
        const target = growTarget(want, self.handler_room.committed, max_handlers);
        const before = self.callRegionBytes();
        if (want <= max_handlers and (self.handler_room.ensure(target) catch return error.OutOfMemory)) return self.chargeRegionGrowth(before);
        self.setErrorMsg("Fatal error: Maximum nesting of {d} try blocks reached\n", .{max_handlers});
        return error.RuntimeError;
    }

    // room to push one more frame and run it: checked before every frame push
    pub inline fn ensureCallRoom(self: *VM) RuntimeError!void {
        return self.ensureCallRoomFor(1);
    }

    pub fn ensureCallRoomFor(self: *VM, frames: usize) RuntimeError!void {
        if (self.hasCallRoom(frames)) return;
        if (try self.growCallRoom(frames)) return;
        const name = if (self.frame_count > 0) if (self.currentFrame().func) |f| f.name else "{main}" else "{main}";
        self.setErrorMsg("Fatal error: Maximum function nesting level of {d} reached, aborting in {s}()\n", .{ max_frames, name });
        return error.RuntimeError;
    }

    pub inline fn hasCallRoom(self: *VM, frames: usize) bool {
        return self.hasCallRoomAt(self.sp, frames);
    }

    // for the fast loop, which keeps sp in a local
    pub inline fn hasCallRoomAt(self: *VM, sp: usize, frames: usize) bool {
        const ic = self.ic.?;
        return self.frame_count + frames < self.frame_room.committed and
            sp + stack_headroom <= self.stack_room.committed and
            ic.fga_sp + fga_headroom * frames <= ic.fga_room.committed;
    }

    // room for `count` operand slots on top of the current ones, beyond the
    // headroom every frame keeps
    fn ensureStackSlots(self: *VM, count: usize) RuntimeError!void {
        const want = self.sp + count + stack_headroom;
        if (want <= self.stack_room.committed) return;
        const target = growTarget(want, self.stack_room.committed, max_stack_slots);
        const before = self.callRegionBytes();
        if (want <= max_stack_slots and
            (self.stack_room.ensure(target) catch return error.OutOfMemory) and
            (self.ic.?.arg_stack_room.ensureFilled(target, .none) catch return error.OutOfMemory)) return self.chargeRegionGrowth(before);
        self.setErrorMsg("Fatal error: Maximum function nesting level of {d} reached\n", .{max_frames});
        return error.RuntimeError;
    }

    // committed bytes of the call-depth regions, which count toward memory
    // use as php's VM stack does
    fn callRegionBytes(self: *VM) usize {
        const ic = self.ic.?;
        return self.frame_room.committed * @sizeOf(CallFrame) +
            self.stack_room.committed * @sizeOf(Value) +
            self.handler_room.committed * @sizeOf(ExceptionHandler) +
            ic.arg_stack_room.committed * @sizeOf(RefSource) +
            ic.sp_save_room.committed * @sizeOf(usize) +
            ic.arg_counts_room.committed * @sizeOf(u32) +
            ic.fga_offsets_room.committed * @sizeOf(u32) +
            ic.fga_room.committed * @sizeOf(Value);
    }

    fn chargeRegionGrowth(self: *VM, before: usize) RuntimeError!void {
        const after = self.callRegionBytes();
        const account = self.memory orelse return;
        if (after > before and !account.chargeExternal(after - before)) return error.OutOfMemory;
    }

    // a region grows only when it is short, and then by doubling
    fn growTarget(want: usize, committed: usize, cap: usize) usize {
        if (want <= committed) return committed;
        return @min(cap, @max(want, committed * 2));
    }

    // commits in doubling steps; false when a limit would be crossed
    fn growCallRoom(self: *VM, frames: usize) RuntimeError!bool {
        const ic = self.ic.?;
        const want_frames = self.frame_count + frames + 1;
        const want_slots = self.sp + stack_headroom;
        const want_fga = ic.fga_sp + fga_headroom * frames;
        if (want_frames > max_frames or want_slots > max_stack_slots or want_fga > max_stack_slots) return false;
        const before = self.callRegionBytes();
        const frame_target = growTarget(want_frames, self.frame_room.committed, max_frames);
        const slot_target = growTarget(want_slots, self.stack_room.committed, max_stack_slots);
        const fga_target = growTarget(want_fga, ic.fga_room.committed, max_stack_slots);
        const ok = (self.frame_room.ensure(frame_target) catch return error.OutOfMemory) and
            (ic.sp_save_room.ensure(frame_target) catch return error.OutOfMemory) and
            (ic.arg_counts_room.ensureFilled(frame_target, unknown_arg_count) catch return error.OutOfMemory) and
            (ic.fga_offsets_room.ensureFilled(frame_target, 0) catch return error.OutOfMemory) and
            (self.stack_room.ensure(slot_target) catch return error.OutOfMemory) and
            (ic.arg_stack_room.ensureFilled(slot_target, .none) catch return error.OutOfMemory) and
            (ic.fga_room.ensureFilled(fga_target, .null) catch return error.OutOfMemory);
        try self.chargeRegionGrowth(before);
        return ok;
    }

    // the offset a frame whose arguments were not saved records, so no one
    // reads another call's values in their place
    const fga_unsaved = std.math.maxInt(u32);

    pub fn markArgsUnsaved(self: *VM) void {
        const ic = self.ic orelse return;
        if (self.frame_count < ic.fga_offsets_room.committed) ic.fga_offsets[self.frame_count] = fga_unsaved;
    }

    // whether func_get_args can keep `count` more arguments, growing its
    // buffer when a call passes more than the headroom
    fn fgaRoomFor(self: *VM, count: usize) bool {
        const ic = self.ic.?;
        const want = @as(usize, ic.fga_sp) + count;
        if (want <= ic.fga_room.committed) return true;
        if (want > max_stack_slots) return false;
        const before = self.callRegionBytes();
        const grown = ic.fga_room.ensureFilled(growTarget(want, ic.fga_room.committed, max_stack_slots), .null) catch return false;
        if (!grown) return false;
        self.chargeRegionGrowth(before) catch return false;
        return true;
    }

    pub fn saveFrameArgs(self: *VM, arg_count: u32) void {
        const ic = self.ic orelse return;
        if (self.frame_count >= ic.fga_offsets_room.committed) return;
        const ac: usize = arg_count;
        if (ac == 0) {
            ic.fga_offsets[self.frame_count] = ic.fga_sp;
            return;
        }
        const sp = ic.fga_sp;
        if (sp + ac > ic.fga_room.committed) {
            ic.fga_offsets[self.frame_count] = fga_unsaved;
            return;
        }
        ic.fga_offsets[self.frame_count] = sp;
        for (0..ac) |i| {
            ic.fga_buf[sp + i] = self.stack[self.sp - ac + i];
        }
        ic.fga_sp = @intCast(sp + ac);
    }

    // saveFrameArgs equivalent for callers that have args in a slice (not on
    // the value stack). without this, native-driven invocations (e.g. PDO
    // sqliteCreateFunction callbacks, sort comparators) leave fga_buf with
    // stale entries from whatever last touched that frame slot, and
    // func_get_args returns the previous call's args
    pub fn saveFrameArgsSlice(self: *VM, args: []const Value) void {
        const ic = self.ic orelse return;
        if (self.frame_count >= ic.fga_offsets_room.committed) return;
        const ac: usize = args.len;
        if (ac == 0) {
            ic.fga_offsets[self.frame_count] = ic.fga_sp;
            return;
        }
        const sp = ic.fga_sp;
        if (!self.fgaRoomFor(ac)) {
            ic.fga_offsets[self.frame_count] = fga_unsaved;
            return;
        }
        ic.fga_offsets[self.frame_count] = sp;
        for (0..ac) |i| ic.fga_buf[sp + i] = args[i];
        ic.fga_sp = @intCast(sp + ac);
    }

    // a slot being torn down gives back its saved arguments, so a frame
    // unwound by an exception leaves nothing behind for the next frame there
    fn forgetFrameArgs(self: *VM, idx: usize) void {
        const ic = self.ic orelse return;
        if (idx >= ic.fga_offsets_room.committed) return;
        const offset = ic.fga_offsets[idx];
        if (offset == fga_unsaved) return;
        if (offset < ic.fga_sp) ic.fga_sp = offset;
        ic.fga_offsets[idx] = fga_unsaved;
    }

    pub fn restoreFrameArgsSp(self: *VM) void {
        const ic = self.ic orelse return;
        const offset = ic.fga_offsets[self.frame_count];
        // a frame that saved nothing moved nothing
        if (offset != fga_unsaved) ic.fga_sp = offset;
    }

    pub fn getFrameArgs(self: *VM) ?[]const Value {
        const ic = self.ic orelse return null;
        const fc = self.frame_count - 1;
        const ac_raw = ic.arg_counts[fc];
        if (ac_raw == unknown_arg_count) return null;
        const ac: usize = ac_raw;
        if (fc >= ic.fga_offsets_room.committed or ic.fga_offsets[fc] == fga_unsaved) return null;
        const offset: usize = ic.fga_offsets[fc];
        if (offset + ac > ic.fga_room.committed) return null;
        return ic.fga_buf[offset .. offset + ac];
    }

    fn binaryOp(self: *VM, op: *const fn (Value, Value) Value) void {
        const b = self.pop();
        const a = self.pop();
        self.push(op(a, b));
    }

    // an internal call's result; php frees the call's arguments and the
    // object it was called on as it returns, so what they held goes now
    fn pushNativeResult(self: *VM, value: Value) void {
        if (value == .string and value.string.owner != null and value.string.owner.?.refcount > 0) {
            self.pushTransfer(value);
        } else self.push(value);
        if (self.hasPendingReleases()) self.drainPendingDestruct();
    }

    // call results borrow storage until the next release drain. Other holders
    // may still own the same value, so its refcount does not identify ownership.
    fn pushCallResult(self: *VM, value: Value) void {
        self.push(value);
    }

    fn borrowCallResult(self: *VM, value: Value) Value {
        if (value == .string) self.releaseValue(value);
        return value;
    }

    inline fn pushTransfer(self: *VM, value: Value) void {
        if (value == .string) {
            if (value.string.owner) |owner| self.removePendingStringRelease(owner);
        }
        if (self.sp < self.arg_source_end) self.releaseStaleArgSource(self.sp);
        self.stack[self.sp] = value;
        self.sp += 1;
    }

    inline fn push(self: *VM, value: Value) void {
        // a variable that holds nothing is read as null; the marker itself
        // never becomes a value
        if (@import("builtin").mode == .debug) std.debug.assert(value != .undef);
        if (value == .string) {
            if (value.string.owner) |owner| self.removePendingStringRelease(owner);
        }
        // operand-stack slots refcount objects (Stage 1) but NOT arrays.
        // an array is a value type with exactly one durable owner; the stack
        // holds a transient borrow, not ownership. counting transient
        // push/pop would let an array whose container has not (yet) retained
        // it cycle 0->1->0 and be freed while still live. arrays are freed
        // only when their durable container releases them (refcounting Stage 2)
        stackRetain(value);
        if (self.sp < self.arg_source_end) self.releaseStaleArgSource(self.sp);
        self.stack[self.sp] = value;
        self.sp += 1;
    }

    fn pop(self: *VM) Value {
        self.clearArgStackFrom(self.sp - 1);
        self.sp -= 1;
        const v = self.stack[self.sp];
        self.stackRelease(v);
        return v;
    }

    fn popTransfer(self: *VM) Value {
        self.clearArgStackFrom(self.sp - 1);
        self.sp -= 1;
        return self.stack[self.sp];
    }

    // drop the top n operand-stack slots, releasing each. used by call
    // cleanup to release the receiver + arguments the caller pushed - the
    // callee retained its own copies via retainFrameObjects, so the caller's
    // stack copies must be released here (objects only - see push)
    pub fn dropN(self: *VM, n: usize) void {
        var k: usize = 0;
        while (k < n) : (k += 1) {
            self.clearArgStackFrom(self.sp - 1);
            self.sp -= 1;
            self.stackRelease(self.stack[self.sp]);
        }
    }

    inline fn peek(self: *const VM) Value {
        return self.stack[self.sp - 1];
    }

    // object refcounting (Stage 1) - see .handoff/refcounting.md

    // an object handle was copied into a new reference
    pub fn objRetain(obj: *PhpObject) void {
        obj.refcount +%= 1;
        @import("value.zig").traceObjRc(obj, "retain");
    }

    // is this object the exception currently propagating through the VM?
    fn pendingExceptionIs(self: *const VM, obj: *PhpObject) bool {
        if (self.pending_exception) |pe| {
            return pe == .object and pe.object == obj;
        }
        return false;
    }

    // an object reference was dropped. at zero the object is unreachable, but
    // __destruct is NOT run inline: the just-dropped handle is usually still
    // live in the caller's hands (pop() returns the value it released, an
    // overwrite still has the old value in a local). the object is queued and
    // drainPendingDestruct runs the destructor at the next safe point. if the
    // object is retained again before the drain it is rescued - the drain
    // re-checks refcount, so a transient dip to 0 never mis-fires __destruct
    // a container made for a result that will not be returned (a decoder that
    // failed half way): nothing references it, so it goes to the drain
    pub fn discardOrphan(self: *VM, v: Value) void {
        switch (v) {
            .array => |arr| if (arr.refcount == 0) self.queueArrayRelease(arr),
            .object => |obj| if (obj.refcount == 0 and !obj.destructed) self.pending_destruct.append(self.allocator, obj) catch {},
            else => {},
        }
    }

    pub fn objRelease(self: *VM, obj: *PhpObject) void {
        if (obj.refcount == 0) {
            // a garbage peer dropping its edge to this object
            if (obj.gc_internal_refs > 0) obj.gc_internal_refs -= 1;
            return;
        }
        obj.refcount -= 1;
        @import("value.zig").traceObjRc(obj, "release");
        if (obj.refcount != 0) {
            // refcount went down but not to 0: object might be part of an
            // unreachable cycle (a -> b -> a where both still see each other).
            // each possible root occupies one candidate slot.
            if (!obj.destructed and !obj.cycle_queued) {
                self.cycle_candidates.append(self.allocator, obj) catch return;
                obj.cycle_queued = true;
            }
            return;
        }
        if (obj.destructed) return;
        self.pending_destruct.append(self.allocator, obj) catch {};
        if (self.release_log) |log| log.append(self.allocator, .{ .object = obj }) catch {};
    }

    // run __destruct for every queued object still at refcount 0. called at
    // statement boundaries and at run end. reentrancy-guarded: a destructor
    // runs a nested runLoop whose own drains are absorbed into this outer
    // pass, which keeps consuming as destructors queue further objects
    // php frees what a dying object or array held before the next queued
    // value, depth first: an object's destructor, then everything its
    // properties held, then its handle. what a destruction drops is logged
    // and destroyed right away; past this depth it waits in the queues
    const max_release_depth = 2000;

    pub const ReleasedItem = union(enum) { object: *PhpObject, array: *PhpArray };

    fn destroyDropped(self: *VM, items: []const ReleasedItem, deferred_stack_arrays: *std.ArrayListUnmanaged(*PhpArray)) void {
        self.release_depth += 1;
        defer self.release_depth -= 1;
        for (items) |item| switch (item) {
            .object => |obj| self.destroyReleasedObject(obj, deferred_stack_arrays),
            .array => |arr| self.destroyReleasedArray(arr, deferred_stack_arrays),
        };
    }

    // runs a user __destruct as the body of the gc's destructor fiber (php's
    // gc_call_destructors_in_fiber). a destructor that suspends keeps that
    // fiber, resumable through Fiber::getCurrent(), and the next destructor
    // gets a new one. false when the destructor is not user code
    fn callDestructorInGcFiber(self: *VM, obj: *PhpObject) bool {
        const full_name = self.resolveMethod(obj.class_name, "__destruct") catch return false;
        const func = self.functions.get(full_name) orelse return false;
        const fiber = self.gc_dtor_fiber orelse blk: {
            const created = self.free_fibers.pop() orelse created: {
                const fresh = self.allocator.create(Fiber) catch return false;
                self.fibers.append(self.allocator, fresh) catch {
                    self.allocator.destroy(fresh);
                    return false;
                };
                break :created fresh;
            };
            created.* = .{ .handle = self.allocHandle() catch return false };
            // the vm's own reference
            fiberRetain(created);
            self.gc_dtor_fiber = created;
            break :blk created;
        };
        var vars = self.acquireFrameVars();
        vars.put(self.allocator, "$this", .{ .object = obj }) catch return false;
        self.ensureCallRoom() catch return false;
        const base_frame = self.frame_count;
        const base_sp = self.sp;
        const base_handler = self.handler_count;
        const locals = self.allocLocals(func, &vars) catch return false;
        self.frames[self.frame_count] = .{ .chunk = &func.chunk, .ip = 0, .vars = vars, .locals = locals, .func = func, .called_class = obj.class_name };
        self.frames[self.frame_count].entry_sp = self.sp;
        self.markArgsUnsaved();
        self.frame_count += 1;
        self.retainFrameObjects(self.frame_count - 1);
        if (self.frame_count > self.frame_high_water) self.frame_high_water = self.frame_count;
        fiber.state = .running;
        // what the destructor releases is destructed as usual, not in this
        // fiber, which is busy
        const prev_in_fiber = self.gc_dtors_in_fiber;
        self.gc_dtors_in_fiber = false;
        // php's gc_destructor_fiber calls it; an exception it throws goes on
        // to the code that ran the collection, with one in flight as its
        // previous
        var record: NativeCall = undefined;
        self.enterEngineMethod(&record, "gc_destructor_fiber", &.{}, false);
        record.depth = base_frame;
        record.from_native = true;
        const in_flight = self.takePending();
        _ = self.executeFiber(fiber, base_frame, base_sp, base_handler) catch Value.null;
        self.native_call = record.outer;
        self.settleDrainException(in_flight);
        self.gc_dtors_in_fiber = prev_in_fiber;
        if (fiber.state == .suspended) {
            // the destructor holds this fiber now; the application may
            // keep it or let it go
            self.gc_dtor_fiber = null;
            self.fiberRelease(fiber);
        } else {
            fiber.state = .created;
        }
        return true;
    }

    // a garbage object's destructor, called before any garbage is freed:
    // inside a fiber in php's gc destructor fiber
    fn callGarbageDestructor(self: *VM, obj: *PhpObject) void {
        if (self.current_fiber != null) {
            if (self.callDestructorInGcFiber(obj)) return;
        }
        self.fiber_switch_blocked += 1;
        defer self.fiber_switch_blocked -= 1;
        const in_flight = self.takePending();
        _ = self.callMethod(obj, "__destruct", &.{}) catch {};
        self.settleDrainException(in_flight);
    }

    // after a destructor or a finally block a drain ran: its exception stays
    // pending for the releasing code, with the one that was in flight
    // before as its previous; with none, that one is in flight again
    fn settleDrainException(self: *VM, in_flight: ?Value) void {
        if (self.pending_exception) |ex| {
            if (self.exit_requested or self.isUnwindMarker(ex)) {
                if (in_flight) |previous| self.stackRelease(previous);
                return;
            }
            self.drain_raised = true;
            if (in_flight) |previous| {
                if (ex == .object and previous == .object and !self.isUnwindMarker(previous)) _ = self.chainPrevious(ex.object, previous.object) catch {};
                self.stackRelease(previous);
            }
        } else if (in_flight) |previous| self.setPendingOwned(previous);
    }

    // a drain left an exception for the code that released the value
    inline fn drainRaised(self: *VM) bool {
        if (!self.drain_raised) return false;
        self.drain_raised = false;
        return self.pending_exception != null;
    }

    fn destroyReleasedObject(self: *VM, obj: *PhpObject, deferred_stack_arrays: *std.ArrayListUnmanaged(*PhpArray)) void {
        if (obj.refcount != 0 or obj.destructed) return;
        // the in-flight exception is a VM-level root: while it
        // propagates it lives in self.pending_exception, not on the
        // stack or in a var, so refcounting cannot see it - never
        // destruct it here
        if (self.pendingExceptionIs(obj)) return;
        // a `global $x` cell (globals_cells) is a VM-level root the
        // refcount cannot see - the cell holds its value via a raw
        // cell.* write with no retain. an object reachable from a
        // global is alive for the whole request; never destruct it
        if (self.valueInGlobalsCell(.{ .object = obj })) return;
        if (self.debug_gc_verify) self.gcVerifyDestructing(obj);
        obj.destructed = true;
        var dropped: std.ArrayListUnmanaged(ReleasedItem) = .empty;
        defer dropped.deinit(self.allocator);
        const outer_log = self.release_log;
        if (self.release_depth < max_release_depth) self.release_log = &dropped;
        defer self.release_log = outer_log;
        if (obj.ownsDestructor() and !obj.destructor_called and self.hasMethod(obj.class_name, "__destruct")) destruct: {
            if (self.gc_dtors_in_fiber) {
                if (self.callDestructorInGcFiber(obj)) break :destruct;
            }
            self.fiber_switch_blocked += 1;
            defer self.fiber_switch_blocked -= 1;
            // an exception in flight waits while the destructor runs, and
            // becomes the previous of one the destructor throws
            const in_flight = self.takePending();
            const refused = self.destructorRefused(obj) catch true;
            if (!refused) _ = self.callMethod(obj, "__destruct", &.{}) catch {};
            self.settleDrainException(in_flight);
        }
        // a destructor that kept the object alive (stored $this, or a
        // suspended fiber holds its frame) revived it: it lives on with its
        // properties and is freed, with no second destructor call, when it
        // is released or collected again
        if (obj.refcount != 0) {
            obj.destructed = false;
            obj.destructor_called = true;
            if (obj.gc_internal_refs > 0) {
                obj.refcount += obj.gc_internal_refs;
                obj.gc_internal_refs = 0;
                self.gc_revived += 1;
                if (!obj.cycle_queued) {
                    self.cycle_candidates.append(self.allocator, obj) catch {};
                    obj.cycle_queued = true;
                }
            }
            return;
        }
        obj.gc_internal_refs = 0;
        // PHP's WeakMap drops entries whose key object is unreachable.
        // walk registered WeakMaps and remove entries keyed by this
        // now-destructed object so iteration / count / offsetGet see
        // the entry as gone (Stage 2)
        self.weakmapsOnObjectDestruct(obj);
        self.forgetWeakReferences(obj);
        // collapse the object tree: release the objects this object's
        // property slots held. runs after __destruct (PHP tears
        // properties down after)
        if (obj.resource and obj.native.kind == .stream) @import("../stdlib/streams.zig").destroyed(self, obj);
        const reusable = self.releaseNativeState(obj);
        self.releaseObjectProperties(obj);
        self.release_log = outer_log;
        self.destroyDropped(dropped.items, deferred_stack_arrays);
        // closures it held go before it
        self.drainPendingStringReleases();
        self.freeHandle(obj);
        if (!self.serve_mode and !self.debug_no_pool and reusable) {
            self.released_objects.append(self.allocator, obj) catch {};
        }
    }

    // a generator nothing references: php's dtor_obj runs its pending
    // finally blocks, then free_obj releases what its frame held (its $this
    // and locals go before its own handle)
    fn destroyReleasedGenerator(self: *VM, gen: *Generator, deferred_stack_arrays: *std.ArrayListUnmanaged(*PhpArray)) void {
        // rescued if re-retained between queue and drain
        if (gen.refcount != 0 or gen.pooled) return;
        // the generator it delegates to goes first, if this one held it last
        if (gen.state != .completed and gen.state != .running) if (gen.delegate) |delegate| if (delegate == .gen) {
            gen.delegate = null;
            const inner = delegate.gen;
            self.genRelease(inner);
            if (inner.refcount == 0) self.destroyReleasedGenerator(inner, deferred_stack_arrays);
        };
        // closeGenerator early-returns on .completed; releaseGeneratorVars
        // is idempotent. closing a suspended gen may queue more work
        self.closeGenerator(gen, self.frame_count) catch {};
        if (gen.refcount != 0) return;
        gen.state = .completed;
        var dropped: std.ArrayListUnmanaged(ReleasedItem) = .empty;
        defer dropped.deinit(self.allocator);
        const outer_log = self.release_log;
        if (self.release_depth < max_release_depth) self.release_log = &dropped;
        self.releaseGeneratorVars(gen);
        self.releaseGeneratorCurrent(gen);
        self.releaseValue(gen.return_value);
        gen.return_value = .null;
        self.releaseGeneratorClosure(gen);
        self.release_log = outer_log;
        self.destroyDropped(dropped.items, deferred_stack_arrays);
        self.drainPendingStringReleases();
        if (gen.handle != 0) {
            self.free_handles.append(self.allocator, gen.handle) catch {};
            gen.handle = 0;
        }
        if (!self.serve_mode) {
            gen.deinit(self.allocator);
            gen.pooled = true;
            self.free_generators.append(self.allocator, gen) catch {};
        }
    }

    fn destroyReleasedArray(self: *VM, arr: *PhpArray, deferred_stack_arrays: *std.ArrayListUnmanaged(*PhpArray)) void {
        if (arr.refcount != 0 or arr.elements_released) return;
        // a global `global $x` cell is a root the refcount cannot
        // see (raw cell.* write, no retain) - never free an array
        // reachable from one
        if (self.valueInGlobalsCell(.{ .array = arr })) return;
        // Operand-stack array slots are non-counted roots. A returned
        // array can reach refcount zero while it waits for later call
        // arguments to be evaluated, so keep its elements alive until
        // the slot is consumed or a durable holder retains it.
        var stack_root = false;
        for (self.stack[0..self.sp]) |value| {
            if (value == .array and value.array == arr) {
                stack_root = true;
                break;
            }
        }
        if (stack_root) {
            self.stat_deferred_stack += 1;
            deferred_stack_arrays.append(self.allocator, arr) catch {};
            return;
        }
        if (self.debug_gc_verify and self.arrayHasLiveContainerOwner(arr)) {
            self.stat_deferred_container += 1;
            self.gcReportContainerOwner(arr);
            @panic("array reached zero with a live container owner");
        }
        // mark before walking so a cyclic array (a self-reference
        // reachable through unserialize R:N) is not re-queued
        arr.elements_released = true;
        var dropped: std.ArrayListUnmanaged(ReleasedItem) = .empty;
        defer dropped.deinit(self.allocator);
        const outer_log = self.release_log;
        if (self.release_depth < max_release_depth) self.release_log = &dropped;
        self.releaseArrayElements(arr);
        self.release_log = outer_log;
        self.destroyDropped(dropped.items, deferred_stack_arrays);
        if (!self.serve_mode) self.released_arrays.append(self.allocator, arr) catch {};
    }

    pub fn drainPendingDestruct(self: *VM) void {
        if (@import("value.zig").hooks().trace_obj) |obj| self.gcCheckTraced(obj);
        if (self.draining_destructors or self.heap_teardown) return;
        self.draining_destructors = true;
        var deferred_stack_arrays: std.ArrayListUnmanaged(*PhpArray) = .empty;
        defer deferred_stack_arrays.deinit(self.allocator);
        defer {
            self.draining_destructors = false;
            self.pending_destruct.clearRetainingCapacity();
            self.destruct_cursor = 0;
            self.pending_array_release.clearRetainingCapacity();
            for (deferred_stack_arrays.items) |arr| self.queueArrayRelease(arr);
            self.array_release_cursor = 0;
            self.drainPendingStringReleases();
            self.pending_gen_release.clearRetainingCapacity();
            self.gen_release_cursor = 0;
            self.pending_fiber_release.clearRetainingCapacity();
            self.fiber_release_cursor = 0;
            for (self.released_arrays.items) |arr| {
                if (arr.cycle_queued) {
                    for (self.cycle_array_candidates.items, 0..) |candidate, i| {
                        if (candidate == arr) {
                            _ = self.cycle_array_candidates.swapRemove(i);
                            break;
                        }
                    }
                    arr.cycle_queued = false;
                }
                self.clearArgArraySources(arr);
                arr.deinit(self.allocator);
                arr.pooled = true;
                self.free_arrays.append(self.allocator, arr) catch {};
            }
            self.released_arrays.clearRetainingCapacity();
            for (self.released_objects.items) |obj| {
                if (obj.cycle_queued) {
                    for (self.cycle_candidates.items, 0..) |candidate, i| {
                        if (candidate == obj) {
                            _ = self.cycle_candidates.swapRemove(i);
                            break;
                        }
                    }
                    obj.cycle_queued = false;
                }
                obj.deinit(self.allocator);
                obj.pooled = true;
                self.free_objects.append(self.allocator, obj) catch {};
            }
            self.released_objects.clearRetainingCapacity();
        }
        self.drainQueues(&deferred_stack_arrays);
    }

    // a pass over what was queued since the drain running now reached it,
    // for an exception unwinding inside a destructor or a destroyed
    // generator: php frees the unwound frames' values before the catch
    fn drainNested(self: *VM) void {
        var deferred_stack_arrays: std.ArrayListUnmanaged(*PhpArray) = .empty;
        defer deferred_stack_arrays.deinit(self.allocator);
        self.drainQueues(&deferred_stack_arrays);
        for (deferred_stack_arrays.items) |arr| self.queueArrayRelease(arr);
    }

    fn drainQueues(self: *VM, deferred_stack_arrays: *std.ArrayListUnmanaged(*PhpArray)) void {
        // the queues feed each other - a destructed object releases its
        // array-valued properties; a released array releases its object
        // elements; a closed generator releases its locals (more queues).
        // consume all four until none has unprocessed items
        while (self.destruct_cursor < self.pending_destruct.items.len or
            self.array_release_cursor < self.pending_array_release.items.len or
            self.gen_release_cursor < self.pending_gen_release.items.len or
            self.fiber_release_cursor < self.pending_fiber_release.items.len or
            self.pending_string_release.items.len > 0)
        {
            self.drainPendingStringReleases();
            while (self.destruct_cursor < self.pending_destruct.items.len) {
                const obj = self.pending_destruct.items[self.destruct_cursor];
                self.destruct_cursor += 1;
                self.destroyReleasedObject(obj, deferred_stack_arrays);
            }
            while (self.array_release_cursor < self.pending_array_release.items.len) {
                const arr = self.pending_array_release.items[self.array_release_cursor];
                self.array_release_cursor += 1;
                arr.release_queued = false;
                self.destroyReleasedArray(arr, deferred_stack_arrays);
            }
            while (self.gen_release_cursor < self.pending_gen_release.items.len) {
                const gen = self.pending_gen_release.items[self.gen_release_cursor];
                self.gen_release_cursor += 1;
                // rescued if re-retained between queue and drain
                self.destroyReleasedGenerator(gen, deferred_stack_arrays);
            }
            while (self.fiber_release_cursor < self.pending_fiber_release.items.len) {
                const fiber = self.pending_fiber_release.items[self.fiber_release_cursor];
                self.fiber_release_cursor += 1;
                if (fiber.refcount != 0 or fiber.pooled) continue;
                if (fiber.state == .suspended) {
                    fiber.refcount += 1;
                    self.destroyFiber(fiber);
                    fiber.refcount -= 1;
                    if (fiber.refcount != 0) continue;
                }
                self.cleanupFiberFrames(fiber);
                for (fiber.saved_stack.items) |value| self.stackRelease(value);
                self.releaseValue(fiber.callable);
                self.releaseValue(fiber.suspend_value);
                self.releaseValue(fiber.return_value);
                if (fiber.handle != 0) {
                    self.free_handles.append(self.allocator, fiber.handle) catch {};
                    fiber.handle = 0;
                }
                fiber.deinit(self.allocator);
                if (!self.serve_mode) {
                    fiber.pooled = true;
                    self.free_fibers.append(self.allocator, fiber) catch {};
                }
            }
        }
    }

    fn arrayHasLiveContainerOwner(self: *VM, target: *PhpArray) bool {
        for (self.arrays.items) |arr| {
            if (arr == target or arr.elements_released or arr.pooled) continue;
            for (arr.entries.items) |entry| {
                const value = if (entry.ref) |cell| cell.* else entry.value;
                if (value == .array and value.array == target) return true;
            }
        }
        for (self.objects.items) |obj| {
            if (obj.destructed) continue;
            if (obj.slots) |slots| for (slots) |value| {
                if (value == .array and value.array == target) return true;
            };
            var pit = obj.properties.iterator();
            while (pit.next()) |entry| {
                if (entry.value_ptr.* == .array and entry.value_ptr.array == target) return true;
            }
        }
        return false;
    }

    // cycle collector: PHP-style trial-decrement to find unreachable object
    // cycles (a->b->a where neither is reachable from any var but both pin
    // each other via refcount). returns the number of objects collected.
    //
    // algorithm:
    // 1. BFS from each candidate root through .object / .array refs, building
    //    a visited set. on first visit init scratch_rc = refcount
    // 2. for every visited node, walk its child refs. each (parent->child)
    //    edge decrements child.scratch_rc (counts internal refs)
    // 3. any visited node with scratch_rc > 0 still has external refs - it
    //    AND everything reachable from it is alive; restore them
    // 4. remaining nodes (scratch_rc == 0) are unreachable cycles - destruct
    //    + free
    pub fn collectCycles(self: *VM) usize {
        self.dropUnreachableWeakMapEntries();
        var rerun = false;
        var collected = self.collectCyclesPass(&rerun, true);
        // destructors ran for garbage that was left out: php collects what
        // is still garbage in a second run, once
        if (rerun) {
            var again = false;
            collected += self.collectCyclesPass(&again, false);
        }
        return collected;
    }

    // php's gc treats a WeakMap entry as an edge from its key to its value
    // (zend_weakmap_get_gc): a key reachable only through its own value is
    // garbage. each entry whose value can reach its key is tried by trial
    // deletion over what the value reaches, the map's own hold on the value
    // counted as internal; one with nothing outside holding it is removed,
    // and refcounting (or the cycle pass that follows) frees what it held
    fn dropUnreachableWeakMapEntries(self: *VM) void {
        if (self.draining_destructors or self.collecting_cycles) return;
        var dead: std.ArrayListUnmanaged(struct { map: *PhpObject, key: *PhpObject }) = .empty;
        defer dead.deinit(self.allocator);
        var dtors: std.ArrayListUnmanaged(*PhpObject) = .empty;
        defer dtors.deinit(self.allocator);
        {
            self.collecting_cycles = true;
            defer self.collecting_cycles = false;
            for (self.weakmaps.items) |wm| {
                if (wm.destructed) continue;
                const data_v = wm.get("__data");
                const keys_v = wm.get("__keys");
                if (data_v != .array or keys_v != .array) continue;
                for (keys_v.array.entries.items) |entry| {
                    if (entry.value != .object) continue;
                    const key = entry.value.object;
                    const value = data_v.array.get(.{ .int = @intCast(@intFromPtr(key)) });
                    if (value != .object and value != .array) continue;
                    if (self.weakMapEntryUnreachable(key, value, &dtors)) dead.append(self.allocator, .{ .map = wm, .key = key }) catch return;
                }
            }
        }
        // as php's gc does, the garbage's destructors run first, while all of
        // it is intact
        for (dtors.items) |obj| {
            if (obj.destructed or obj.destructor_called) continue;
            obj.destructor_called = true;
            objRetain(obj);
            self.callGarbageDestructor(obj);
            self.objRelease(obj);
        }
        for (dead.items) |d| {
            const data_v = d.map.get("__data");
            const keys_v = d.map.get("__keys");
            if (keys_v == .array) {
                for (keys_v.array.entries.items, 0..) |e, j| {
                    if (e.value == .object and e.value.object == d.key) {
                        _ = keys_v.array.entries.orderedRemove(j);
                        break;
                    }
                }
            }
            if (data_v == .array) self.arrayRemoveOwned(data_v.array, .{ .int = @intCast(@intFromPtr(d.key)) });
        }
        if (dead.items.len > 0) self.drainPendingDestruct();
    }

    fn weakMapEntryUnreachable(self: *VM, key: *PhpObject, value: Value, dtors: *std.ArrayListUnmanaged(*PhpObject)) bool {
        var visited_objs = std.AutoArrayHashMapUnmanaged(*PhpObject, void){};
        defer visited_objs.deinit(self.allocator);
        var visited_arrs = std.AutoArrayHashMapUnmanaged(*PhpArray, void){};
        defer visited_arrs.deinit(self.allocator);
        defer {
            self.cycle_gens.deinit(self.allocator);
            self.cycle_gens = .{};
            self.cycle_fibers.deinit(self.allocator);
            self.cycle_fibers = .{};
        }
        for (self.ref_cells.items) |cell| cell.visited = false;
        self.cycleVisitChild(value, &visited_objs, &visited_arrs);
        if (!visited_objs.contains(key)) return false;
        var oi = visited_objs.iterator();
        while (oi.next()) |kv| self.cycleDecrementChildren(kv.key_ptr.*, &visited_objs, &visited_arrs);
        var ai = visited_arrs.iterator();
        while (ai.next()) |kv| self.cycleDecrementChildrenArr(kv.key_ptr.*, &visited_objs, &visited_arrs);
        for (self.ref_cells.items) |cell| {
            if (cell.visited) self.cycleDecChild(cell.value, &visited_objs, &visited_arrs);
        }
        for (self.cycle_gens.keys()) |g| _ = self.cycleGeneratorEdges(g, .decrement, &visited_objs, &visited_arrs);
        for (self.cycle_fibers.keys()) |f| _ = self.cycleFiberEdges(f, .decrement, &visited_objs, &visited_arrs);
        // the map holds the value
        self.cycleDecChild(value, &visited_objs, &visited_arrs);
        if (self.globals_array) |ga| {
            for (ga.entries.items) |e| switch (e.value) {
                .object => |o| if (visited_objs.contains(o)) {
                    o.scratch_rc += 1;
                },
                .array => |a| if (visited_arrs.contains(a)) {
                    a.scratch_rc += 1;
                },
                else => {},
            };
        }
        self.cyclePropagateAlive(&visited_objs, &visited_arrs);
        // the value must be garbage too: a value held elsewhere keeps its
        // key alive through it
        const value_dead = switch (value) {
            .object => |o| o.scratch_rc == 0,
            .array => |a| a.scratch_rc == 0,
            else => false,
        };
        if (key.scratch_rc != 0 or !value_dead) return false;
        // the key's destructor first, then the rest of the garbage in the
        // order it was reached
        self.queueGarbageDestructor(key, dtors);
        for (visited_objs.keys()) |obj| {
            if (obj != key and obj.scratch_rc == 0) self.queueGarbageDestructor(obj, dtors);
        }
        return true;
    }

    fn queueGarbageDestructor(self: *VM, obj: *PhpObject, dtors: *std.ArrayListUnmanaged(*PhpObject)) void {
        if (obj.destructed or obj.destructor_called or !obj.ownsDestructor()) return;
        if (!self.hasMethod(obj.class_name, "__destruct")) return;
        for (dtors.items) |queued| if (queued == obj) return;
        dtors.append(self.allocator, obj) catch {};
    }

    fn collectCyclesPass(self: *VM, rerun_needed: *bool, first: bool) usize {
        if (self.draining_destructors or self.collecting_cycles) return 0;
        self.collecting_cycles = true;
        defer self.collecting_cycles = false;
        if (self.cycle_candidates.items.len == 0 and self.cycle_array_candidates.items.len == 0 and self.capture_index.count() == 0 and self.cycle_gen_candidates.items.len == 0 and self.cycle_fiber_candidates.items.len == 0) return 0;
        self.gc_runs += 1;
        // drain any pending normal destructs first so the candidate set
        // doesn't include objects that are about to be released anyway
        self.drainPendingDestruct();

        var visited_objs = std.AutoArrayHashMapUnmanaged(*PhpObject, void){};
        defer visited_objs.deinit(self.allocator);
        var visited_arrs = std.AutoArrayHashMapUnmanaged(*PhpArray, void){};
        defer visited_arrs.deinit(self.allocator);

        defer {
            self.cycle_gens.deinit(self.allocator);
            self.cycle_gens = .{};
            self.cycle_fibers.deinit(self.allocator);
            self.cycle_fibers = .{};
        }
        for (self.ref_cells.items) |cell| cell.visited = false;

        // every closure is a possible root: a captured variable is an edge
        // the candidate list never sees being dropped
        var closure_ranges = self.capture_index.valueIterator();
        while (closure_ranges.next()) |range| {
            if (range.object) |obj| self.cycleVisit(obj, &visited_objs, &visited_arrs);
        }

        // pass 1: BFS from candidates, init scratch_rc on first visit
        for (self.cycle_candidates.items) |c| {
            if (c.destructed) continue;
            self.cycleVisit(c, &visited_objs, &visited_arrs);
        }
        for (self.cycle_array_candidates.items) |c| {
            if (c.elements_released) continue;
            self.cycleVisitArr(c, &visited_objs, &visited_arrs);
        }
        for (self.cycle_gen_candidates.items) |g| {
            if (g.pooled or g.refcount == 0) continue;
            self.cycleVisitChild(.{ .generator = g }, &visited_objs, &visited_arrs);
        }
        for (self.cycle_fiber_candidates.items) |f| {
            if (f.pooled or f.refcount == 0) continue;
            self.cycleVisitChild(.{ .fiber = f }, &visited_objs, &visited_arrs);
        }

        // pass 2: walk every visited node, decrement child scratch_rc for
        // each internal edge
        var oi = visited_objs.iterator();
        while (oi.next()) |kv| self.cycleDecrementChildren(kv.key_ptr.*, &visited_objs, &visited_arrs);
        var ai = visited_arrs.iterator();
        while (ai.next()) |kv| self.cycleDecrementChildrenArr(kv.key_ptr.*, &visited_objs, &visited_arrs);

        for (self.ref_cells.items) |cell| {
            if (cell.visited) self.cycleDecChild(cell.value, &visited_objs, &visited_arrs);
        }
        for (self.cycle_gens.keys()) |g| _ = self.cycleGeneratorEdges(g, .decrement, &visited_objs, &visited_arrs);
        for (self.cycle_fibers.keys()) |f| _ = self.cycleFiberEdges(f, .decrement, &visited_objs, &visited_arrs);

        // the $GLOBALS mirror is a NON-OWNING live view (setLocalGlobal undoes
        // its retain), so a global var's refcount is short by one - the external
        // reference from the $GLOBALS root. restore it here so global roots and
        // their subgraphs count as externally-referenced and are never collected
        if (self.globals_array) |ga| {
            for (ga.entries.items) |entry| {
                switch (entry.value) {
                    .object => |o| if (visited_objs.contains(o)) {
                        o.scratch_rc += 1;
                    },
                    .array => |a| if (visited_arrs.contains(a)) {
                        a.scratch_rc += 1;
                    },
                    else => {},
                }
            }
        }

        // pass 3: nodes with scratch_rc > 0 have external refs - mark alive
        // and propagate aliveness through their subgraph. simplest: walk
        // again from alive roots, re-incrementing scratch_rc to original.
        // a negative count means an edge the refcount never saw; only an
        // exact zero is garbage, anything else is a live root
        self.cyclePropagateAlive(&visited_objs, &visited_arrs);

        // php's gc runs the destructors of garbage that has one first and
        // leaves it, and what only it reaches, out of this run: a generator
        // not finished (its finally blocks, then its variables go, as php's
        // zend_generator_dtor_storage closes it) and a suspended fiber. a
        // second run then collects what is still garbage
        var pending_gens: std.ArrayListUnmanaged(*Generator) = .empty;
        defer pending_gens.deinit(self.allocator);
        for (self.cycle_gens.keys(), self.cycle_gens.values()) |g, *scratch| {
            if (scratch.* != 0 or g.refcount == 0 or g.state == .completed or g.state == .running) continue;
            pending_gens.append(self.allocator, g) catch continue;
            scratch.* = 1;
        }
        var pending_fibers: std.ArrayListUnmanaged(*Fiber) = .empty;
        defer pending_fibers.deinit(self.allocator);
        for (self.cycle_fibers.keys(), self.cycle_fibers.values()) |f, *scratch| {
            if (scratch.* != 0 or f.refcount == 0 or f.state != .suspended) continue;
            pending_fibers.append(self.allocator, f) catch continue;
            scratch.* = 1;
        }
        if (pending_gens.items.len > 0 or pending_fibers.items.len > 0) self.cyclePropagateAlive(&visited_objs, &visited_arrs);

        if (self.debug_gc_verify) self.gcVerifyCollected(&visited_objs, &visited_arrs);

        // pass 4: collect the unreachable ones. queue them for normal
        // destruct pipeline so __destruct runs and properties release cleanly
        var collected: usize = 0;
        // the destructors first, while the garbage is intact; one whose
        // generator ends up unreferenced has freed it
        for (pending_gens.items) |g| {
            g.refcount += 1;
            self.closeGenerator(g, self.frame_count) catch {};
            self.releaseGeneratorVars(g);
            g.state = .completed;
            g.refcount -= 1;
            if (g.refcount == 0) {
                self.pending_gen_release.append(self.allocator, g) catch {};
                collected += 1;
            } else if (!g.cycle_queued) {
                g.cycle_queued = true;
                self.cycle_gen_candidates.append(self.allocator, g) catch {
                    g.cycle_queued = false;
                };
            }
        }
        for (pending_fibers.items) |f| {
            f.refcount += 1;
            self.destroyFiber(f);
            f.refcount -= 1;
            if (f.refcount == 0) {
                self.pending_fiber_release.append(self.allocator, f) catch {};
                collected += 1;
            } else if (!f.cycle_queued) {
                f.cycle_queued = true;
                self.cycle_fiber_candidates.append(self.allocator, f) catch {
                    f.cycle_queued = false;
                };
            }
        }
        // php's gc calls the garbage's destructors while all of it is
        // intact, and frees it in a second run: a destructor may use any of
        // it (a closure the object holds, bug73989). inside a fiber the
        // drain still runs them in the gc destructor fiber as it frees
        var dtor_objs: std.ArrayListUnmanaged(*PhpObject) = .empty;
        defer dtor_objs.deinit(self.allocator);
        if (first and self.current_fiber == null) {
            var dt_it = visited_objs.iterator();
            while (dt_it.next()) |kv| {
                const obj = kv.key_ptr.*;
                if (obj.scratch_rc != 0 or obj.destructed or obj.destructor_called or !obj.ownsDestructor()) continue;
                if (!self.hasMethod(obj.class_name, "__destruct")) continue;
                dtor_objs.append(self.allocator, obj) catch continue;
            }
        }
        for (dtor_objs.items) |obj| {
            if (obj.destructed or obj.destructor_called) continue;
            obj.destructor_called = true;
            objRetain(obj);
            self.callGarbageDestructor(obj);
            self.objRelease(obj);
        }
        const freeing = dtor_objs.items.len == 0;
        var coll_it = visited_objs.iterator();
        while (coll_it.next()) |kv| {
            if (!freeing) break;
            const obj = kv.key_ptr.*;
            if (obj.scratch_rc == 0 and !obj.destructed) {
                // force refcount to 0 so the destruct drain processes it
                // (the cycle's internal refs keep refcount > 0 otherwise)
                obj.gc_internal_refs = obj.refcount;
                obj.refcount = 0;
                self.pending_destruct.append(self.allocator, obj) catch {};
                collected += 1;
            }
        }
        var ca_it = visited_arrs.iterator();
        while (ca_it.next()) |kv| {
            if (!freeing) break;
            const arr = kv.key_ptr.*;
            if (arr.scratch_rc == 0 and !arr.elements_released) {
                arr.refcount = 0;
                self.queueArrayRelease(arr);
                if (!arr.uncounted) collected += 1;
            }
        }
        // a garbage generator that finished, or a fiber that is not
        // suspended, has nothing left to run: what it holds goes
        for (self.cycle_gens.keys(), self.cycle_gens.values()) |g, scratch| {
            if (!freeing) break;
            if (scratch != 0 or g.refcount == 0) continue;
            g.refcount = 0;
            self.pending_gen_release.append(self.allocator, g) catch {};
            collected += 1;
        }
        for (self.cycle_fibers.keys(), self.cycle_fibers.values()) |f, scratch| {
            if (!freeing) break;
            if (scratch != 0 or f.refcount == 0) continue;
            f.refcount = 0;
            self.pending_fiber_release.append(self.allocator, f) catch {};
            collected += 1;
        }
        for (self.cycle_candidates.items) |obj| obj.cycle_queued = false;
        for (self.cycle_array_candidates.items) |arr| arr.cycle_queued = false;
        self.cycle_candidates.clearRetainingCapacity();
        self.cycle_array_candidates.clearRetainingCapacity();
        // what the destructors left is the second run's to free
        if (!freeing) {
            var keep_it = visited_objs.iterator();
            while (keep_it.next()) |kv| {
                const obj = kv.key_ptr.*;
                if (obj.refcount == 0 or obj.destructed or obj.cycle_queued) continue;
                obj.cycle_queued = true;
                self.cycle_candidates.append(self.allocator, obj) catch {
                    obj.cycle_queued = false;
                };
            }
        }
        // generators and fibers whose destructor ran stay candidates for the
        // second run
        const rerun = !freeing or pending_gens.items.len > 0 or pending_fibers.items.len > 0;
        var gi: usize = 0;
        while (gi < self.cycle_gen_candidates.items.len) {
            const g = self.cycle_gen_candidates.items[gi];
            const keep = rerun and std.mem.indexOfScalar(*Generator, pending_gens.items, g) != null and g.refcount > 0;
            if (keep) {
                gi += 1;
            } else {
                g.cycle_queued = false;
                _ = self.cycle_gen_candidates.swapRemove(gi);
            }
        }
        var fi: usize = 0;
        while (fi < self.cycle_fiber_candidates.items.len) {
            const f = self.cycle_fiber_candidates.items[fi];
            const keep = rerun and std.mem.indexOfScalar(*Fiber, pending_fibers.items, f) != null and f.refcount > 0;
            if (keep) {
                fi += 1;
            } else {
                f.cycle_queued = false;
                _ = self.cycle_fiber_candidates.swapRemove(fi);
            }
        }
        // inside a fiber, php calls the garbage's destructors in its gc fiber
        const prev_in_fiber = self.gc_dtors_in_fiber;
        self.gc_dtors_in_fiber = self.current_fiber != null;
        self.drainPendingDestruct();
        self.gc_dtors_in_fiber = prev_in_fiber;
        // php counts what it freed: an object its destructor revived stays
        collected -|= self.gc_revived;
        self.gc_revived = 0;
        self.gc_collected += collected;
        if (self.debug_gc_verify) {
            self.gcVerifyDangling(collected);
            self.gcTraceClass(&visited_objs, &visited_arrs, "after");
        }
        rerun_needed.* = rerun;
        return collected;
    }

    // pass 3 of the collector: nodes with external references are alive,
    // and so is everything they reach
    fn cyclePropagateAlive(self: *VM, vo: anytype, va: anytype) void {
        var changed = true;
        while (changed) {
            changed = false;
            for (self.ref_cells.items) |cell| {
                if (cell.visited and cell.scratch != 0) {
                    if (self.cycleMarkAliveChild(cell.value, vo, va)) changed = true;
                }
            }
            for (self.cycle_gens.keys(), self.cycle_gens.values()) |g, scratch| {
                if (scratch != 0 and self.cycleGeneratorEdges(g, .mark_alive, vo, va)) changed = true;
            }
            for (self.cycle_fibers.keys(), self.cycle_fibers.values()) |f, scratch| {
                if (scratch != 0 and self.cycleFiberEdges(f, .mark_alive, vo, va)) changed = true;
            }
            var it = vo.iterator();
            while (it.next()) |kv| {
                const obj = kv.key_ptr.*;
                if (obj.scratch_rc != 0) {
                    if (self.cycleMarkAlive(obj, vo, va)) changed = true;
                }
            }
            var ait = va.iterator();
            while (ait.next()) |kv| {
                const arr = kv.key_ptr.*;
                if (arr.scratch_rc != 0) {
                    if (self.cycleMarkAliveArr(arr, vo, va)) changed = true;
                }
            }
        }

    }

    const GcTarget = union(enum) { obj: *PhpObject, arr: *PhpArray };

    fn gcTargetMatches(t: GcTarget, v: Value) bool {
        return switch (t) {
            .obj => |o| v == .object and v.object == o,
            .arr => |a| v == .array and v.array == a,
        };
    }

    const GcHolderCount = struct { internal: u32 = 0, external: u32 = 0 };

    threadlocal var gc_verbose: bool = false;

    fn gcNote(counts: *GcHolderCount, in_graph: bool, comptime label: []const u8, args: anytype) void {
        gc_holder_count += 1;
        if (gc_silent) return;
        if (in_graph) {
            counts.internal += 1;
            if (gc_verbose) std.debug.print("      internal holder: " ++ label ++ "\n", args);
        } else {
            counts.external += 1;
            std.debug.print("      external holder: " ++ label ++ "\n", args);
        }
    }

    // ZPHP_GC_VERIFY: before the collector frees a node, scan every holder in
    // the VM and compare with the trial-decrement result
    fn gcVerifyNode(self: *VM, t: GcTarget, vo: anytype, va: anytype) void {
        var c = GcHolderCount{};
        for (self.stack[0..self.sp], 0..) |v, i| if (gcTargetMatches(t, v)) gcNote(&c, false, "stack[{d}]", .{i});
        for (self.frames[0..self.frame_count], 0..) |*fr, i| {
            var vit = fr.vars.iterator();
            while (vit.next()) |e| if (gcTargetMatches(t, e.value_ptr.*)) gcNote(&c, false, "frame{d}.vars.{s}", .{ i, e.key_ptr.* });
            const snames = if (fr.func) |f| f.slot_names else fr.slot_names;
            const vars_populated = fr.vars.count() > 0;
            for (fr.locals, 0..) |lv, li| {
                if (vars_populated and li < snames.len and snames[li].len > 0 and fr.vars.contains(snames[li])) continue;
                if (gcTargetMatches(t, lv)) gcNote(&c, false, "frame{d}.locals[{d}]", .{ i, li });
            }
        }
        for (self.ref_cells.items, 0..) |cell, i| if (gcTargetMatches(t, cell.value)) gcNote(&c, cell.visited, "ref_cell[{d}]", .{i});
        var rv_it = self.request_vars.iterator();
        while (rv_it.next()) |e| if (gcTargetMatches(t, e.value_ptr.*)) gcNote(&c, false, "request_var.{s}", .{e.key_ptr.*});
        var classes = self.classes.iterator();
        while (classes.next()) |ce| {
            var sp_it = ce.value_ptr.*.static_props.iterator();
            while (sp_it.next()) |e| if (gcTargetMatches(t, e.value_ptr.*)) gcNote(&c, false, "static_prop {s}::{s}", .{ ce.key_ptr.*, e.key_ptr.* });
        }
        for (self.captures.items) |entry| if (gcTargetMatches(t, entry.value)) gcNote(&c, false, "capture {s} ${s}", .{ entry.closure_name, entry.var_name });
        for (self.generators.items) |g| {
            if (g.pooled) continue;
            if (gcTargetMatches(t, g.current_value)) gcNote(&c, false, "generator current_value", .{});
            if (gcTargetMatches(t, g.current_key)) gcNote(&c, false, "generator current_key", .{});
            if (gcTargetMatches(t, g.return_value)) gcNote(&c, false, "generator return_value", .{});
            for (g.locals.items) |v| if (gcTargetMatches(t, v)) gcNote(&c, false, "generator local", .{});
            for (g.stack.items) |v| if (gcTargetMatches(t, v)) gcNote(&c, false, "generator stack", .{});
            var gv = g.vars.iterator();
            while (gv.next()) |e| if (gcTargetMatches(t, e.value_ptr.*)) gcNote(&c, false, "generator var {s}", .{e.key_ptr.*});
        }
        for (self.fibers.items) |f| {
            if (f.pooled) continue;
            if (gcTargetMatches(t, f.callable)) gcNote(&c, false, "fiber callable", .{});
            if (gcTargetMatches(t, f.suspend_value)) gcNote(&c, false, "fiber suspend_value", .{});
            if (gcTargetMatches(t, f.return_value)) gcNote(&c, false, "fiber return_value", .{});
            for (f.saved_stack.items) |v| if (gcTargetMatches(t, v)) gcNote(&c, false, "fiber saved_stack", .{});
        }
        for (self.arrays.items) |arr| {
            if (arr.pooled or arr.elements_released or arr.weak) continue;
            const in_graph = va.contains(arr);
            for (arr.entries.items, 0..) |e, i| {
                if (gcTargetMatches(t, e.value)) gcNote(&c, in_graph, "array {*} rc {d} scratch {d} entry[{d}] value", .{ arr, arr.refcount, arr.scratch_rc, i });
            }
        }
        for (self.objects.items) |obj| {
            if (obj.pooled or obj.destructed) continue;
            const in_graph = vo.contains(obj);
            if (obj.slots) |slots| for (slots, 0..) |v, i| {
                if (gcTargetMatches(t, v)) gcNote(&c, in_graph, "object {s}#{d} rc {d} scratch {d} slot[{d}]", .{ obj.class_name, obj.id, obj.refcount, obj.scratch_rc, i });
            };
            var pit = obj.properties.iterator();
            while (pit.next()) |e| if (gcTargetMatches(t, e.value_ptr.*)) gcNote(&c, in_graph, "object {s}#{d} rc {d} scratch {d} prop {s}", .{ obj.class_name, obj.id, obj.refcount, obj.scratch_rc, e.key_ptr.* });
            if (gcTargetMatches(t, obj.backingValue())) gcNote(&c, in_graph, "object {s}#{d} lazy_backing", .{ obj.class_name, obj.id });
            if (gcTargetMatches(t, obj.lazyInitializer())) gcNote(&c, in_graph, "object {s}#{d} lazy_initializer", .{ obj.class_name, obj.id });
            if (gcTargetMatches(t, obj.fakeCallable())) gcNote(&c, in_graph, "object {s}#{d} fake closure", .{ obj.class_name, obj.id });
        }
        const rc: u32 = switch (t) {
            .obj => |o| o.refcount,
            .arr => |a| a.refcount,
        };
        if (!gc_silent and (gc_verbose or c.external > 0 or c.internal != rc)) {
            switch (t) {
                .obj => |o| std.debug.print("    gc-verify object {s}#{d} refcount {d}: internal {d}, external {d}\n", .{ o.class_name, o.id, rc, c.internal, c.external }),
                .arr => |a| std.debug.print("    gc-verify array {*} refcount {d} len {d}: internal {d}, external {d}\n", .{ a, rc, a.entries.items.len, c.internal, c.external }),
            }
        }
    }

    fn gcIsDead(v: Value) bool {
        return switch (v) {
            .object => |o| o.destructed or o.pooled,
            .array => |a| a.elements_released or a.pooled,
            else => false,
        };
    }

    fn gcDeadName(v: Value) []const u8 {
        return switch (v) {
            .object => |o| o.class_name,
            .array => "array",
            else => "?",
        };
    }

    // after a collection: any live holder still pointing at a freed node is a
    // use-after-collect
    fn gcVerifyDangling(self: *VM, collected: usize) void {
        std.debug.print("gc-verify: run {d} collected {d}\n", .{ self.gc_runs, collected });
        for (self.stack[0..self.sp], 0..) |v, i| if (gcIsDead(v)) std.debug.print("    dangling {s} in stack[{d}]\n", .{ gcDeadName(v), i });
        for (self.frames[0..self.frame_count], 0..) |*fr, i| {
            var vit = fr.vars.iterator();
            while (vit.next()) |e| if (gcIsDead(e.value_ptr.*)) std.debug.print("    dangling {s} in frame{d}.vars.{s}\n", .{ gcDeadName(e.value_ptr.*), i, e.key_ptr.* });
            for (fr.locals, 0..) |lv, li| if (gcIsDead(lv)) std.debug.print("    dangling {s} in frame{d}.locals[{d}]\n", .{ gcDeadName(lv), i, li });
        }
        for (self.ref_cells.items, 0..) |cell, i| if (gcIsDead(cell.value)) std.debug.print("    dangling {s} in ref_cell[{d}]\n", .{ gcDeadName(cell.value), i });
        var gc_it = self.globals_cells.iterator();
        while (gc_it.next()) |e| if (gcIsDead(e.value_ptr.*.*)) std.debug.print("    dangling {s} in globals_cell.{s}\n", .{ gcDeadName(e.value_ptr.*.*), e.key_ptr.* });
        var sc_it = self.statics_cells.iterator();
        while (sc_it.next()) |e| if (gcIsDead(e.value_ptr.*.*)) std.debug.print("    dangling {s} in statics_cell.{s}\n", .{ gcDeadName(e.value_ptr.*.*), e.key_ptr.* });
        var classes = self.classes.iterator();
        while (classes.next()) |ce| {
            var sp_it = ce.value_ptr.*.static_props.iterator();
            while (sp_it.next()) |e| if (gcIsDead(e.value_ptr.*)) std.debug.print("    dangling {s} in static_prop {s}::{s}\n", .{ gcDeadName(e.value_ptr.*), ce.key_ptr.*, e.key_ptr.* });
        }
        for (self.captures.items) |entry| if (gcIsDead(entry.value)) std.debug.print("    dangling {s} in capture {s} ${s}\n", .{ gcDeadName(entry.value), entry.closure_name, entry.var_name });
        for (self.arrays.items) |arr| {
            if (arr.pooled or arr.elements_released) continue;
            for (arr.entries.items, 0..) |e, i| {
                if (gcIsDead(e.value)) {
                    std.debug.print("    dangling {s} in array {*} rc {d} weak {} entry[{d}]\n", .{ gcDeadName(e.value), arr, arr.refcount, arr.weak, i });
                    gcDescribeArray(arr);
                }
                if (e.ref) |cell| if (gcIsDead(cell.*)) std.debug.print("    dangling {s} in array {*} entry[{d}] cell\n", .{ gcDeadName(cell.*), arr, i });
            }
        }
        for (self.objects.items) |obj| {
            if (obj.pooled or obj.destructed) continue;
            if (obj.slots) |slots| for (slots, 0..) |v, i| {
                if (gcIsDead(v)) std.debug.print("    dangling {s} in object {s}#{d} rc {d} slot[{d}]\n", .{ gcDeadName(v), obj.class_name, obj.id, obj.refcount, i });
            };
            var pit = obj.properties.iterator();
            while (pit.next()) |e| if (gcIsDead(e.value_ptr.*)) std.debug.print("    dangling {s} in object {s}#{d} rc {d} prop {s}\n", .{ gcDeadName(e.value_ptr.*), obj.class_name, obj.id, obj.refcount, e.key_ptr.* });
        }
    }

    fn gcDescribeArray(arr: *PhpArray) void {
        std.debug.print("      array {*} keys:", .{arr});
        for (arr.entries.items) |e| switch (e.key) {
            .int => |i| std.debug.print(" {d}", .{i}),
            .string => |k| std.debug.print(" '{s}'", .{k.bytes()}),
        };
        std.debug.print("  values:", .{});
        for (arr.entries.items) |e| std.debug.print(" {s}", .{@tagName(e.value)});
        std.debug.print("\n", .{});
    }

    fn gcTraceClass(self: *VM, vo: anytype, va: anytype, when: []const u8) void {
        const class = platform.getenv("ZPHP_GC_TRACE_CLASS") orelse return;
        for (self.objects.items) |obj| {
            if (obj.pooled or !std.mem.eql(u8, obj.class_name, class)) continue;
            std.debug.print("  trace {s} {s}#{d} refcount {d} destructed {} in_graph {} scratch {d}\n", .{ when, obj.class_name, obj.id, obj.refcount, obj.destructed, vo.contains(obj), obj.scratch_rc });
            if (platform.getenv("ZPHP_GC_TRACE_FROM")) |from| {
                const from_run = std.fmt.parseInt(usize, from, 10) catch 0;
                if (self.gc_runs == from_run and std.mem.eql(u8, when, "after")) @import("value.zig").hooks().trace_obj = obj;
                if (self.gc_runs == from_run + 1 and std.mem.eql(u8, when, "before")) @import("value.zig").hooks().trace_obj = null;
            }
            gc_verbose = true;
            self.gcVerifyNode(.{ .obj = obj }, vo, va);
            gc_verbose = false;
            if (platform.getenv("ZPHP_GC_TRACE_DEEP") == null) continue;
            for (self.arrays.items) |arr| {
                if (arr.pooled or arr.elements_released) continue;
                var holds = false;
                for (arr.entries.items) |e| if (e.value == .object and e.value.object == obj) {
                    holds = true;
                };
                if (!holds) continue;
                gcDescribeArray(arr);
                std.debug.print("      holders of that array:\n", .{});
                gc_verbose = true;
                self.gcVerifyNode(.{ .arr = arr }, vo, va);
                gc_verbose = false;
            }
        }
    }

    const GcEmptyObjSet = struct {
        fn contains(_: *const @This(), _: *PhpObject) bool {
            return false;
        }
    };
    const GcEmptyArrSet = struct {
        fn contains(_: *const @This(), _: *PhpArray) bool {
            return false;
        }
    };

    threadlocal var gc_holder_count: u32 = 0;
    threadlocal var gc_silent: bool = false;

    // durable holders can never outnumber the refcount (pins and stack
    // borrows only add); report the first drain where they do
    fn gcCheckTraced(self: *VM, obj: *PhpObject) void {
        if (obj.destructed) return;
        const eo = GcEmptyObjSet{};
        const ea = GcEmptyArrSet{};
        gc_silent = true;
        gc_holder_count = 0;
        self.gcVerifyNode(.{ .obj = obj }, &eo, &ea);
        gc_silent = false;
        if (gc_holder_count > obj.refcount) {
            std.debug.print("== holders {d} exceed refcount {d} for {s}#{d}\n", .{ gc_holder_count, obj.refcount, obj.class_name, obj.id });
            gc_verbose = true;
            self.gcVerifyNode(.{ .obj = obj }, &eo, &ea);
            gc_verbose = false;
            std.debug.dumpCurrentStackTrace(.{});
            @import("value.zig").hooks().trace_obj = null;
        }
    }

    // ZPHP_GC_VERIFY: an object reaching refcount 0 must have no durable holder
    fn gcVerifyDestructing(self: *VM, obj: *PhpObject) void {
        const eo = GcEmptyObjSet{};
        const ea = GcEmptyArrSet{};
        gc_silent = true;
        gc_holder_count = 0;
        self.gcVerifyNode(.{ .obj = obj }, &eo, &ea);
        gc_silent = false;
        if (gc_holder_count == 0) return;
        std.debug.print("== destructing held object {s}#{d} ({d} holders)\n", .{ obj.class_name, obj.id, gc_holder_count });
        gc_verbose = true;
        self.gcVerifyNode(.{ .obj = obj }, &eo, &ea);
        gc_verbose = false;
    }

    // ZPHP_GC_VERIFY: name the container that holds an array the refcount
    // says is unreachable - a store site that bypassed the retain
    const GcZeroSite = struct { binding: []const u8 = "", binding_func: []const u8 = "", func: []const u8, path: []const u8, line: u32, addrs: [24]usize, depth: usize };

    fn gcRecordZeroSite(self: *VM, arr: *PhpArray) void {
        if (self.frame_count == 0) return;
        const f = &self.frames[self.frame_count - 1];
        var line: u32 = 0;
        if (f.ip > 0 and f.ip - 1 < f.chunk.lines.items.len) line = f.chunk.lines.items[f.ip - 1];
        var site = GcZeroSite{ .func = if (f.func) |fd| fd.name else "<top>", .path = f.script_path, .line = line, .addrs = undefined, .depth = 0 };
        const st = std.debug.captureCurrentStackTrace(.{}, &site.addrs);
        site.depth = st.return_addresses.len;
        for (site.addrs[0..site.depth], 0..) |addr, i| {
            if (addr == 0) {
                site.depth = i;
                break;
            }
        }
        self.gc_zero_sites.put(self.allocator, arr, site) catch {};
    }

    fn gcReportContainerOwner(self: *VM, target: *PhpArray) void {
        if (self.stat_deferred_container > 3) return;
        if (self.gc_zero_sites.get(target)) |site| {
            std.debug.print("== reached zero in {s}@{s}:{d} binding {s} in {s}\n", .{ site.func, site.path, site.line, site.binding, site.binding_func });
            var addrs = site.addrs;
            const st: std.debug.StackTrace = .{ .return_addresses = addrs[0..site.depth], .skipped = .none };
            std.debug.dumpStackTrace(&st);
        }
        std.debug.print("== at:", .{});
        var fi: usize = self.frame_count;
        while (fi > 0) {
            fi -= 1;
            const f = &self.frames[fi];
            const fname: []const u8 = if (f.func) |fd| fd.name else "<top>";
            var off: u32 = 0;
            if (f.ip > 0 and f.ip - 1 < f.chunk.lines.items.len) off = f.chunk.lines.items[f.ip - 1];
            std.debug.print(" {s}@{s}:{d}", .{ fname, f.script_path, off });
        }
        std.debug.print("\n", .{});
        for (self.arrays.items) |arr| {
            if (arr == target or arr.elements_released or arr.pooled) continue;
            for (arr.entries.items, 0..) |entry, i| {
                const value = if (entry.ref) |cell| cell.* else entry.value;
                if (value == .array and value.array == target) {
                    std.debug.print("== uncounted container store: array {*} (len {d}) entry[{d}] holds array {*}\n", .{ arr, arr.entries.items.len, i, target });
                    gcDescribeArray(arr);
                }
            }
        }
        for (self.objects.items) |obj| {
            if (obj.destructed or obj.pooled) continue;
            if (obj.slots) |slots| for (slots, 0..) |value, i| {
                if (value == .array and value.array == target) std.debug.print("== uncounted container store: object {s}#{d} slot[{d}] holds array {*}\n", .{ obj.class_name, obj.id, i, target });
            };
            var pit = obj.properties.iterator();
            while (pit.next()) |entry| {
                if (entry.value_ptr.* == .array and entry.value_ptr.array == target) std.debug.print("== uncounted container store: object {s}#{d} prop {s} holds array {*}\n", .{ obj.class_name, obj.id, entry.key_ptr.*, target });
            }
        }
    }

    fn gcVerifyCollected(self: *VM, vo: anytype, va: anytype) void {
        std.debug.print("gc-verify: run {d}, visited {d} objects {d} arrays, candidates {d}/{d}\n", .{ self.gc_runs, vo.count(), va.count(), self.cycle_candidates.items.len, self.cycle_array_candidates.items.len });
        if (platform.getenv("ZPHP_GC_TRACE_ARRAYS") != null) {
            var dbg = va.iterator();
            while (dbg.next()) |kv| {
                const arr = kv.key_ptr.*;
                std.debug.print("  visited array {*} rc {d} scratch {d} len {d}\n", .{ arr, arr.refcount, arr.scratch_rc, arr.entries.items.len });
                for (arr.entries.items) |e| if (e.ref) |cell| std.debug.print("    ref entry: cell {*} holds {s}, mirror {s}\n", .{ cell, @tagName(cell.*), @tagName(e.value) });
                gc_verbose = true;
                self.gcVerifyNode(.{ .arr = arr }, vo, va);
                gc_verbose = false;
            }
        }
        self.gcTraceClass(vo, va, "before");
        var ci = vo.iterator();
        while (ci.next()) |kv| {
            const obj = kv.key_ptr.*;
            if (obj.scratch_rc == 0 and !obj.destructed) std.debug.print("    collect object {s}#{d} rc {d}\n", .{ obj.class_name, obj.id, obj.refcount });
        }
        var cai = va.iterator();
        while (cai.next()) |kv| {
            const arr = kv.key_ptr.*;
            if (arr.scratch_rc == 0 and !arr.elements_released) std.debug.print("    collect array {*} rc {d} len {d}\n", .{ arr, arr.refcount, arr.entries.items.len });
        }
        var oi = vo.iterator();
        while (oi.next()) |kv| {
            const obj = kv.key_ptr.*;
            if (obj.scratch_rc == 0 and !obj.destructed) self.gcVerifyNode(.{ .obj = obj }, vo, va);
        }
        var ai = va.iterator();
        while (ai.next()) |kv| {
            const arr = kv.key_ptr.*;
            if (arr.scratch_rc == 0 and !arr.elements_released) self.gcVerifyNode(.{ .arr = arr }, vo, va);
        }
    }

    inline fn collectCyclesIfNeeded(self: *VM) void {
        if (!self.gc_enabled) return;
        const roots = self.cycle_candidates.items.len + self.cycle_array_candidates.items.len;
        if (roots >= self.gc_threshold) self.collectCyclesAtThreshold();
    }

    const gc_threshold_default: usize = 10001;
    const gc_threshold_step: usize = 10000;
    const gc_threshold_max: usize = 1_000_000_000;

    // a run the root count triggered, then php's gc_adjust_threshold: a run
    // that frees little, or leaves the buffer as full as it found it (its
    // destructors made as many roots again), raises the threshold, so
    // collection can't chase garbage it keeps creating
    noinline fn collectCyclesAtThreshold(self: *VM) void {
        // no run starts inside another or inside the destructor drain
        if (self.draining_destructors or self.collecting_cycles) return;
        const collected = self.collectCycles();
        const roots = self.cycle_candidates.items.len + self.cycle_array_candidates.items.len;
        if (collected < 100 or roots >= self.gc_threshold) {
            self.gc_threshold = @min(self.gc_threshold + gc_threshold_step, gc_threshold_max);
        } else if (self.gc_threshold > gc_threshold_default) {
            self.gc_threshold = @max(self.gc_threshold - gc_threshold_step, gc_threshold_default);
        }
    }

    fn cycleVisit(self: *VM, obj: *PhpObject, vo: anytype, va: anytype) void {
        self.cycleVisitChild(.{ .object = obj }, vo, va);
    }

    fn cycleVisitArr(self: *VM, arr: *PhpArray, vo: anytype, va: anytype) void {
        self.cycleVisitChild(.{ .array = arr }, vo, va);
    }

    fn closureOwnsStatic(name: []const u8, key: []const u8) bool {
        return key.len > name.len + 2 and std.mem.startsWith(u8, key, name) and key[name.len] == ':' and key[name.len + 1] == ':';
    }

    const CycleWork = union(enum) { value: Value, cell: *Value };

    // depth-first walk over an explicit stack: a long chain of objects (a
    // linked list of 300k nodes) would overflow the native stack as recursion.
    // children are pushed reversed, so nodes are reached in the order the
    // recursive walk reached them
    fn cycleVisitChild(self: *VM, v: Value, vo: anytype, va: anytype) void {
        const work = &self.cycle_work;
        const floor = work.items.len;
        defer work.shrinkRetainingCapacity(floor);
        work.append(self.allocator, .{ .value = v }) catch return;
        while (work.items.len > floor) {
            const item = work.pop().?;
            const start = work.items.len;
            switch (item) {
                .cell => |value| {
                    const cell = cellOf(value);
                    if (cell.visited) continue;
                    cell.visited = true;
                    cell.scratch = @intCast(cell.binders);
                    work.append(self.allocator, .{ .value = cell.value }) catch return;
                },
                .value => |val| switch (val) {
                    .object => |obj| {
                        if (vo.contains(obj)) continue;
                        vo.put(self.allocator, obj, {}) catch return;
                        obj.scratch_rc = @intCast(obj.refcount);
                        // a closure's captures and statics are its edges
                        if (obj.closureName()) |name| if (self.capture_index.get(name)) |range| {
                            for (self.captures.items[range.start..][0..range.len]) |capture| {
                                work.append(self.allocator, .{ .value = capture.value }) catch return;
                                if (capture.ref_cell) |cell| work.append(self.allocator, .{ .cell = cell }) catch return;
                            }
                            if (range.has_statics) {
                                var statics = self.statics_cells.iterator();
                                while (statics.next()) |entry| {
                                    if (!closureOwnsStatic(name, entry.key_ptr.*)) continue;
                                    work.append(self.allocator, .{ .cell = entry.value_ptr.* }) catch return;
                                }
                            }
                        };
                        work.append(self.allocator, .{ .value = obj.lazyInitializer() }) catch return;
                        work.append(self.allocator, .{ .value = obj.fakeCallable() }) catch return;
                        work.append(self.allocator, .{ .value = obj.backingValue() }) catch return;
                        if (obj.slots) |slots| for (slots) |slot| {
                            work.append(self.allocator, .{ .value = slot }) catch return;
                        };
                        var pit = obj.properties.iterator();
                        while (pit.next()) |e| work.append(self.allocator, .{ .value = e.value_ptr.* }) catch return;
                    },
                    .array => |arr| {
                        if (va.contains(arr)) continue;
                        va.put(self.allocator, arr, {}) catch return;
                        arr.scratch_rc = @intCast(arr.refcount);
                        if (arr.weak) continue;
                        for (arr.entries.items) |e| {
                            work.append(self.allocator, .{ .value = e.value }) catch return;
                            if (e.ref) |cell| work.append(self.allocator, .{ .cell = cell }) catch return;
                        }
                    },
                    .generator => |g| {
                        if (self.cycle_gens.contains(g) or g.pooled) continue;
                        self.cycle_gens.put(self.allocator, g, @intCast(g.refcount)) catch return;
                        _ = self.cycleGeneratorEdges(g, .{ .visit = work }, vo, va);
                    },
                    .fiber => |f| {
                        if (self.cycle_fibers.contains(f) or f.pooled) continue;
                        self.cycle_fibers.put(self.allocator, f, @intCast(f.refcount)) catch return;
                        _ = self.cycleFiberEdges(f, .{ .visit = work }, vo, va);
                    },
                    else => {},
                },
            }
            std.mem.reverse(CycleWork, work.items[start..]);
        }
    }

    fn cycleDecrementChildren(self: *VM, obj: *PhpObject, vo: anytype, va: anytype) void {
        if (obj.closureName()) |name| if (self.capture_index.get(name)) |range| {
            for (self.captures.items[range.start..][0..range.len]) |capture| {
                self.cycleDecChild(capture.value, vo, va);
                if (capture.ref_cell) |cell| cellOf(cell).scratch -= 1;
            }
            if (range.has_statics) {
                var statics = self.statics_cells.iterator();
                while (statics.next()) |entry| {
                    if (closureOwnsStatic(name, entry.key_ptr.*)) cellOf(entry.value_ptr.*).scratch -= 1;
                }
            }
        };
        self.cycleDecChild(obj.lazyInitializer(), vo, va);
        self.cycleDecChild(obj.fakeCallable(), vo, va);
        self.cycleDecChild(obj.backingValue(), vo, va);
        if (obj.slots) |s| {
            for (s) |v| self.cycleDecChild(v, vo, va);
        }
        var pit = obj.properties.iterator();
        while (pit.next()) |e| self.cycleDecChild(e.value_ptr.*, vo, va);
    }

    // a referenced element carries two counted holders of its value: the
    // entry mirror and the owning cell, and both edges are internal to the
    // graph (the cell is reachable only through the entry once no variable
    // is bound to it, and a bound variable's own slot keeps the external count)
    fn cycleDecrementChildrenArr(self: *VM, arr: *PhpArray, vo: anytype, va: anytype) void {
        if (arr.weak) return;
        for (arr.entries.items) |e| {
            if (e.ref) |cell| {
                cellOf(cell).scratch -= 1;
                self.cycleDecChild(e.value, vo, va);
            } else {
                self.cycleDecChild(e.value, vo, va);
            }
        }
    }

    const CycleEdgeAction = union(enum) {
        visit: *std.ArrayListUnmanaged(CycleWork),
        decrement,
        mark_alive,
    };

    // one edge of the graph: visited, counted off as internal, or marked
    // alive from a live parent. a cell edge is a binding of a reference
    fn cycleEdge(self: *VM, v: Value, comptime counted: bool, action: CycleEdgeAction, vo: anytype, va: anytype) bool {
        switch (action) {
            .visit => |work| work.append(self.allocator, .{ .value = v }) catch {},
            .decrement => if (counted) self.cycleDecChild(v, vo, va),
            .mark_alive => return self.cycleMarkAliveChild(v, vo, va),
        }
        return false;
    }

    fn cycleCellEdge(self: *VM, cell: *Value, action: CycleEdgeAction) bool {
        switch (action) {
            .visit => |work| work.append(self.allocator, .{ .cell = cell }) catch {},
            .decrement => cellOf(cell).scratch -= 1,
            .mark_alive => if (cellOf(cell).scratch == 0) {
                cellOf(cell).scratch = 1;
                return true;
            },
        }
        return false;
    }

    // a frame's variables: the vars map, and the slots it does not mirror
    fn cycleFrameEdges(self: *VM, vars: *const std.StringHashMapUnmanaged(Value), locals: []const Value, func: ?*const ObjFunction, ref_slots: *const std.StringHashMapUnmanaged(*Value), action: CycleEdgeAction, vo: anytype, va: anytype) bool {
        var changed = false;
        var vit = vars.valueIterator();
        while (vit.next()) |v| changed = self.cycleEdge(v.*, true, action, vo, va) or changed;
        const names = if (func) |f| f.slot_names else &[_][]const u8{};
        const vars_populated = vars.count() > 0;
        for (locals, 0..) |v, i| {
            if (vars_populated and i < names.len and names[i].len > 0 and vars.contains(names[i])) continue;
            changed = self.cycleEdge(v, true, action, vo, va) or changed;
        }
        var rit = ref_slots.valueIterator();
        while (rit.next()) |cell| changed = self.cycleCellEdge(cell.*, action) or changed;
        return changed;
    }

    // php's zend_generator_get_gc: what a generator holds, unless it runs
    // (then nothing it holds can be collected)
    fn cycleGeneratorEdges(self: *VM, g: *Generator, action: CycleEdgeAction, vo: anytype, va: anytype) bool {
        var changed = false;
        changed = self.cycleEdge(g.current_value, true, action, vo, va) or changed;
        changed = self.cycleEdge(g.current_key, true, action, vo, va) or changed;
        changed = self.cycleEdge(g.return_value, true, action, vo, va) or changed;
        if (g.closure) |closure| changed = self.cycleEdge(.{ .object = closure }, true, action, vo, va) or changed;
        if (g.state == .running or g.state == .completed) return changed;
        if (g.pending_throw) |ex| changed = self.cycleEdge(ex, true, action, vo, va) or changed;
        if (g.delegate) |delegate| switch (delegate) {
            .gen => |inner| changed = self.cycleEdge(.{ .generator = inner }, true, action, vo, va) or changed,
            .array => |state| changed = self.cycleEdge(.{ .array = state.arr }, true, action, vo, va) or changed,
            .iterator => |state| changed = self.cycleEdge(.{ .object = state.obj }, true, action, vo, va) or changed,
        };
        changed = self.cycleFrameEdges(&g.vars, g.locals.items, g.func, &g.ref_slots, action, vo, va) or changed;
        // the saved operand stack counts what it holds, but no arrays
        for (g.stack.items) |v| {
            if (v == .array) {
                changed = self.cycleEdge(v, false, action, vo, va) or changed;
            } else changed = self.cycleEdge(v, true, action, vo, va) or changed;
        }
        return changed;
    }

    // php's zend_fiber_object_gc: its callable and result, and the frames
    // of a suspended fiber
    fn cycleFiberEdges(self: *VM, f: *Fiber, action: CycleEdgeAction, vo: anytype, va: anytype) bool {
        var changed = false;
        changed = self.cycleEdge(f.callable, true, action, vo, va) or changed;
        changed = self.cycleEdge(f.return_value, true, action, vo, va) or changed;
        if (f.state != .suspended) return changed;
        changed = self.cycleEdge(f.suspend_value, true, action, vo, va) or changed;
        for (f.saved_frames.items) |*frame| {
            changed = self.cycleFrameEdges(&frame.vars, frame.locals, frame.func, &frame.ref_slots, action, vo, va) or changed;
            if (frame.generator) |g| changed = self.cycleEdge(.{ .generator = g }, true, action, vo, va) or changed;
        }
        for (f.saved_stack.items) |v| {
            if (v == .array) {
                changed = self.cycleEdge(v, false, action, vo, va) or changed;
            } else changed = self.cycleEdge(v, true, action, vo, va) or changed;
        }
        return changed;
    }

    fn cycleDecChild(self: *VM, v: Value, vo: anytype, va: anytype) void {
        switch (v) {
            .generator => |g| if (self.cycle_gens.getPtr(g)) |scratch| {
                scratch.* -= 1;
            },
            .fiber => |f| if (self.cycle_fibers.getPtr(f)) |scratch| {
                scratch.* -= 1;
            },
            .object => |o| if (vo.contains(o)) {
                o.scratch_rc -= 1;
            },
            .array => |a| if (va.contains(a)) {
                a.scratch_rc -= 1;
            },
            else => {},
        }
    }

    fn cycleMarkAlive(self: *VM, obj: *PhpObject, vo: anytype, va: anytype) bool {
        var changed = false;
        if (obj.closureName()) |name| if (self.capture_index.get(name)) |range| {
            for (self.captures.items[range.start..][0..range.len]) |capture| {
                if (self.cycleMarkAliveChild(capture.value, vo, va)) changed = true;
                if (capture.ref_cell) |cell| {
                    if (cellOf(cell).scratch == 0) {
                        cellOf(cell).scratch = 1;
                        changed = true;
                    }
                }
            }
            if (range.has_statics) {
                var statics = self.statics_cells.iterator();
                while (statics.next()) |entry| {
                    if (!closureOwnsStatic(name, entry.key_ptr.*)) continue;
                    const cell = cellOf(entry.value_ptr.*);
                    if (cell.scratch == 0) {
                        cell.scratch = 1;
                        changed = true;
                    }
                }
            }
        };
        changed = self.cycleMarkAliveChild(obj.lazyInitializer(), vo, va) or changed;
        changed = self.cycleMarkAliveChild(obj.fakeCallable(), vo, va) or changed;
        changed = self.cycleMarkAliveChild(obj.backingValue(), vo, va) or changed;
        if (obj.slots) |s| {
            for (s) |v| if (self.cycleMarkAliveChild(v, vo, va)) {
                changed = true;
            };
        }
        var pit = obj.properties.iterator();
        while (pit.next()) |e| if (self.cycleMarkAliveChild(e.value_ptr.*, vo, va)) {
            changed = true;
        };
        return changed;
    }

    fn cycleMarkAliveArr(self: *VM, arr: *PhpArray, vo: anytype, va: anytype) bool {
        var changed = false;
        if (arr.weak) return false;
        for (arr.entries.items) |e| {
            if (self.cycleMarkAliveChild(e.value, vo, va)) changed = true;
            if (e.ref) |value| {
                const cell = cellOf(value);
                if (cell.scratch == 0) {
                    cell.scratch = 1;
                    changed = true;
                }
            }
        }
        return changed;
    }

    fn cycleMarkAliveChild(self: *VM, v: Value, vo: anytype, va: anytype) bool {
        switch (v) {
            .generator => |g| if (self.cycle_gens.getPtr(g)) |scratch| {
                if (scratch.* == 0) {
                    scratch.* = 1;
                    return true;
                }
            },
            .fiber => |f| if (self.cycle_fibers.getPtr(f)) |scratch| {
                if (scratch.* == 0) {
                    scratch.* = 1;
                    return true;
                }
            },
            .object => |o| {
                if (vo.contains(o) and o.scratch_rc == 0) {
                    o.scratch_rc = 1;
                    return true;
                }
            },
            .array => |a| {
                if (va.contains(a) and a.scratch_rc == 0) {
                    a.scratch_rc = 1;
                    return true;
                }
            },
            else => {},
        }
        return false;
    }

    // WeakMap weak semantics: when an object becomes unreachable, walk all
    // registered WeakMap instances and drop entries keyed by that object. the
    // key pointer in __data is the (untyped) integer of obj's address; __keys
    // mirrors the same set of object handles for iteration. both get pruned.
    // also prunes the weakmaps registry of any destructed WeakMap instances
    // (a one-shot scan keeps the list small without per-WM lifecycle hooks)
    // php's zend_weakrefs_notify: a freed object's WeakReference now finds
    // nothing, and a freed WeakReference stops naming its target
    fn forgetWeakReferences(self: *VM, dead: *PhpObject) void {
        if (dead.weakly_referenced) {
            dead.weakly_referenced = false;
            if (self.weak_references.fetchRemove(dead)) |entry| entry.value.native.ptr = 0;
        }
        if (dead.native.kind == .weak_reference) {
            if (dead.native.ptr != 0) {
                const target: *PhpObject = @ptrFromInt(dead.native.ptr);
                if (self.weak_references.get(target)) |ref| if (ref == dead) {
                    _ = self.weak_references.remove(target);
                    target.weakly_referenced = false;
                };
            }
            dead.native = .{};
        }
    }

    // the WeakReference php hands out for an object, one per object, borrowed
    pub fn weakReferenceFor(self: *VM, target: *PhpObject) RuntimeError!*PhpObject {
        if (self.weak_references.get(target)) |ref| return ref;
        const ref = try self.allocObject(.{ .class_name = "WeakReference" });
        ref.native = .{ .kind = .weak_reference, .ptr = @intFromPtr(target) };
        try self.weak_references.put(self.allocator, target, ref);
        target.weakly_referenced = true;
        return ref;
    }

    fn weakmapsOnObjectDestruct(self: *VM, dead_obj: *PhpObject) void {
        const target_int: i64 = @intCast(@intFromPtr(dead_obj));
        var i: usize = 0;
        while (i < self.weakmaps.items.len) {
            const wm = self.weakmaps.items[i];
            if (wm.destructed) {
                _ = self.weakmaps.swapRemove(i);
                continue;
            }
            i += 1;
            if (wm == dead_obj) continue;
            const data_v = wm.get("__data");
            if (data_v == .array) {
                self.arrayRemoveOwned(data_v.array, .{ .int = target_int });
            }
            const keys_v = wm.get("__keys");
            if (keys_v == .array) {
                const karr = keys_v.array;
                var j: usize = 0;
                while (j < karr.entries.items.len) {
                    const e = karr.entries.items[j];
                    if (e.value == .object and e.value.object == dead_obj) {
                        _ = karr.entries.orderedRemove(j);
                        continue;
                    }
                    j += 1;
                }
            }
        }
    }

    // is this object/array reachable from a `global $x` cell? globals_cells
    // entries hold their value via a raw cell.* write with no retain, so the
    // refcount does not see them - the drain must check explicitly before
    // destructing/freeing (refcounting Stage 2; mirrors arrayOnStack /
    // pendingExceptionIs - roots refcounting cannot see)
    fn valueInGlobalsCell(self: *const VM, v: Value) bool {
        var it = self.globals_cells.valueIterator();
        while (it.next()) |cell_ptr| {
            const cv = cell_ptr.*.*;
            switch (v) {
                .object => |o| if (cv == .object and cv.object == o) return true,
                .array => |a| if (cv == .array and cv.array == a) return true,
                else => {},
            }
        }
        return false;
    }

    // release the values an unreachable array holds and clear the entries, so
    // object elements reach refcount 0 and get __destruct'd, and nested
    // arrays cascade. clearing prevents any later walk from double-releasing
    fn releaseArrayElements(self: *VM, arr: *PhpArray) void {
        self.clearArgArraySources(arr);
        if (self.ic.?.foreach_pins.count() > 0) {
            if (self.ic.?.foreach_pins.fetchRemove(arr)) |pin| self.stackRelease(pin.value);
        }
        for (arr.entries.items) |*e| {
            if (!arr.weak) self.releaseValue(e.value);
            e.value = .null;
            if (e.ref) |cell| {
                if (self.ref_index) |ri| ri.removeTargetAllOwners(self.allocator, cell, .{ .array = .{ .array = arr, .key = e.key } });
            }
            self.setEntryRef(e, null);
        }
    }

    // a new reference to an array was created
    pub fn arrayRetain(arr: *PhpArray) void {
        arr.refcount +%= 1;
    }

    // undo a transient pin (return_val / fast_loop return). plain decrement,
    // never queues: a pinned array dropping back to 0 is a live stack temp
    // (the operand stack does not own arrays), not unreachable garbage -
    // queuing it would free a return value before the caller clones it
    pub fn arrayUnpin(arr: *PhpArray) void {
        if (arr.refcount > 0) arr.refcount -= 1;
    }

    // an array reference was dropped. at 0 the array is unreachable; queue it
    // so releaseArrayElements runs at the next drain (a transient dip to 0 on
    // the operand stack is rescued - the drain re-checks refcount)
    pub fn arrayRelease(self: *VM, arr: *PhpArray) void {
        if (arr.refcount == 0) return;
        arr.refcount -= 1;
        if (arr.refcount != 0) {
            if (!arr.elements_released and !arr.cycle_queued) {
                self.cycle_array_candidates.append(self.allocator, arr) catch return;
                arr.cycle_queued = true;
            }
            return;
        }
        self.queueArrayRelease(arr);
    }

    // an array at refcount 0 has no durable owner. queue it once; the drain
    // re-checks stack roots and containers before freeing, so queuing a
    // transient borrow that later gets stored is harmless
    // an array nothing holds, built for one use: what it holds goes now, as
    // php frees a temporary the moment it is done with it
    pub fn releaseUnheldArray(self: *VM, arr: *PhpArray) void {
        if (arr.refcount != 0 or arr.elements_released or arr.pooled) return;
        arr.elements_released = true;
        self.releaseArrayElements(arr);
        if (!self.serve_mode) self.released_arrays.append(self.allocator, arr) catch {};
    }

    pub fn queueArrayRelease(self: *VM, arr: *PhpArray) void {
        if (arr.elements_released or arr.pooled) return;
        // queued once already (and rescued since): the queue has it, but a
        // depth-first destruction still has to see it dropped now
        if (arr.release_queued) {
            if (self.release_log) |log| log.append(self.allocator, .{ .array = arr }) catch {};
            return;
        }
        if (self.debug_gc_verify) self.gcRecordZeroSite(arr);
        arr.release_queued = true;
        self.pending_array_release.append(self.allocator, arr) catch {
            arr.release_queued = false;
            return;
        };
        if (self.release_log) |log| log.append(self.allocator, .{ .array = arr }) catch {};
    }

    // zend_exception_set_previous: hang `add` off the end of the exception's
    // previous chain, unless it already leads back into that chain, which
    // would make the chain a loop
    pub fn chainPrevious(self: *VM, exception: *PhpObject, add: *PhpObject) !bool {
        if (exception == add) return false;
        var ex = exception;
        while (true) {
            var ancestor = add.get("previous");
            while (ancestor == .object) : (ancestor = ancestor.object.get("previous")) {
                if (ancestor.object == ex) return false;
            }
            const prev = ex.get("previous");
            if (prev != .object) {
                try ex.set(self.allocator, "previous", .{ .object = add });
                return true;
            }
            ex = prev.object;
            if (ex == add) return false;
        }
    }

    // the statement-boundary gate. every queue triggers it; in-transit values
    // that cross PHP execution (yield_from handoffs, returns) are pinned by
    // their opcodes rather than protected by a narrower gate
    pub inline fn hasPendingReleases(self: *VM) bool {
        return self.pending_destruct.items.len > 0 or
            self.pending_string_release.items.len > 0 or
            self.pending_array_release.items.len > 0 or
            self.pending_gen_release.items.len > 0 or
            self.pending_fiber_release.items.len > 0;
    }

    // release the object references an object's properties hold and clear the
    // slots, so a destructed object's children become unreachable (Stage 1).
    // clearing prevents any later sweep from double-releasing
    fn releaseObjectProperties(self: *VM, obj: *PhpObject) void {
        // detach weak property mirrors before this address can be pooled
        if (obj.ref_mirrored) if (self.ref_index) |ri| {
            while (true) {
                var found: ?RefIndex.OwnedBinding = null;
                var it = ri.fwd.iterator();
                outer: while (it.next()) |entry| {
                    for (entry.value_ptr.items) |target| {
                        if (target == .object and target.object.object == obj) {
                            found = .{ .cell = entry.key_ptr.*, .target = target };
                            break :outer;
                        }
                    }
                }
                const binding = found orelse break;
                ri.removeTargetAllOwners(self.allocator, binding.cell, binding.target);
            }
        };
        if (obj.backingValue() != .null) {
            self.releaseValue(obj.backingValue());
            obj.lazy.?.backing = null;
        }
        if (obj.lazyInitializer() != .null) {
            self.releaseValue(obj.lazyInitializer());
            obj.lazy.?.initializer = .null;
        }
        if (obj.slots) |s| {
            for (s) |*v| {
                switch (v.*) {
                    .string, .object, .array, .generator, .fiber, .resource => {
                        self.releaseValue(v.*);
                        v.* = .null;
                    },
                    else => {},
                }
            }
        }
        var it = obj.properties.iterator();
        while (it.next()) |e| {
            switch (e.value_ptr.*) {
                .string, .object, .array, .generator, .fiber, .resource => {
                    self.releaseValue(e.value_ptr.*);
                    e.value_ptr.* = .null;
                },
                else => {},
            }
        }
    }

    // retain/release a Value - a no-op for scalars. objects and arrays are
    // both refcounted (arrays: refcounting Stage 2)
    // container stores release what they replace through the release hook;
    // these remain the named VM-aware store entry points
    pub fn detachArrayEntryRef(self: *VM, array: *PhpArray, key: PhpArray.Key) void {
        const entry = array.getPtr(key) orelse return;
        const cell = entry.ref orelse return;
        if (self.ref_index) |ri| ri.removeTargetAllOwners(self.allocator, cell, .{ .array = .{ .array = array, .key = entry.key } });
        var i: usize = 0;
        while (i < self.array_ref_bindings.items.len) {
            const binding = self.array_ref_bindings.items[i];
            if (binding.array == array and binding.key.eql(entry.key)) {
                _ = self.array_ref_bindings.swapRemove(i);
            } else i += 1;
        }
        self.setEntryRef(entry, null);
    }

    pub fn arraySetOwned(self: *VM, array: *PhpArray, key: PhpArray.Key, value: Value) !void {
        try array.set(self.allocator, key, value);
        if (array == self.globals_array and key == .string) {
            try self.mirrorGlobalsWrite(key.string.bytes(), value);
        }
    }

    pub fn arrayAppendOwned(self: *VM, array: *PhpArray, value: Value) !void {
        try array.append(self.allocator, value);
    }

    pub fn arrayRemoveOwned(self: *VM, array: *PhpArray, raw_key: PhpArray.Key) void {
        // "3" is the key 3, as for every other array access
        const key = PhpArray.normalizeKey(raw_key);
        if (array == self.globals_array and key == .string) {
            var buf: [256]u8 = undefined;
            const name = varVarName(key.string.bytes(), &buf);
            if (isSuperglobal(name)) {
                self.unsetSuperglobal(name);
                return;
            }
        }
        if (!array.contains(key)) return;
        const old = array.get(key);
        if (array.getPtr(key)) |entry| {
            if (entry.ref) |cell| {
                if (self.ref_index) |ri| ri.removeTargetAllOwners(self.allocator, cell, .{ .array = .{ .array = array, .key = entry.key } });
            }
        }
        array.remove(key);
        self.releaseValue(old);
    }

    pub inline fn retainValue(v: Value) void {
        switch (v) {
            .string => v.string.retain(),
            .object, .resource => |o| objRetain(o),
            .array => arrayRetain(v.array),
            .generator => genRetain(v.generator),
            .fiber => fiberRetain(v.fiber),
            else => {},
        }
    }

    pub fn removePendingStringRelease(self: *VM, owner: *Value.String.Owner) void {
        if (!owner.release_queued) return;
        for (self.pending_string_release.items, 0..) |queued, i| {
            if (queued == owner) {
                _ = self.pending_string_release.swapRemove(i);
                owner.release_queued = false;
                return;
            }
        }
        unreachable;
    }

    fn drainPendingStringReleases(self: *VM) void {
        while (self.pending_string_release.pop()) |owner| {
            owner.release_queued = false;
            if (owner.refcount != 0) continue;
            Value.String.destroyOwner(owner);
        }
    }

    fn queueStringRelease(self: *VM, owner: *Value.String.Owner) void {
        if (owner.release_queued) return;
        owner.release_queued = true;
        self.pending_string_release.append(self.allocator, owner) catch {
            owner.release_queued = false;
            Value.String.destroyOwner(owner);
        };
    }

    pub inline fn releaseValue(self: *VM, v: Value) void {
        switch (v) {
            .string => if (v.string.releaseDeferred()) |owner| self.queueStringRelease(owner),
            .object, .resource => |o| self.objRelease(o),
            .array => self.arrayRelease(v.array),
            .generator => self.genRelease(v.generator),
            .fiber => self.fiberRelease(v.fiber),
            else => {},
        }
    }

    pub fn genRetain(gen: *@import("value.zig").Generator) void {
        gen.refcount +%= 1;
    }

    // Stage 2 finer generator lifetime: queue at refcount=0 instead of
    // closing inline. transient pop-then-store patterns (yield_from popping
    // an inner gen off the stack before storing into delegate.gen) hit
    // refcount=0 briefly; if we closed inline the inner gen would die before
    // the delegate retain registers. the drain re-checks refcount so a rescue
    // re-retain leaves the queued entry as a no-op
    pub fn genRelease(self: *VM, gen: *@import("value.zig").Generator) void {
        if (gen.refcount == 0) return;
        gen.refcount -= 1;
        if (gen.refcount != 0) {
            if (!gen.cycle_queued) {
                gen.cycle_queued = true;
                self.cycle_gen_candidates.append(self.allocator, gen) catch {
                    gen.cycle_queued = false;
                };
            }
            return;
        }
        self.pending_gen_release.append(self.allocator, gen) catch {};
    }

    pub fn fiberRetain(fiber: *@import("value.zig").Fiber) void {
        fiber.refcount +%= 1;
    }

    pub fn fiberRelease(self: *VM, fiber: *@import("value.zig").Fiber) void {
        if (fiber.refcount == 0) return;
        fiber.refcount -= 1;
        if (fiber.refcount != 0) {
            if (!fiber.cycle_queued) {
                fiber.cycle_queued = true;
                self.cycle_fiber_candidates.append(self.allocator, fiber) catch {
                    fiber.cycle_queued = false;
                };
            }
            return;
        }
        self.pending_fiber_release.append(self.allocator, fiber) catch {};
    }

    // retain/release for an OPERAND-STACK slot: objects only. arrays are not
    // owned by the stack (see push) - a stack borrow must not move an array's
    // refcount, or a live array whose container is at baseline 0 would be
    // freed by a transient push/pop. durable containers use retainValue /
    // releaseValue; the operand stack uses these
    pub inline fn stackRetain(v: Value) void {
        switch (v) {
            .string => v.string.retain(),
            .object, .resource => |o| objRetain(o),
            .generator => genRetain(v.generator),
            .fiber => fiberRetain(v.fiber),
            else => {},
        }
    }

    pub inline fn stackRelease(self: *VM, v: Value) void {
        switch (v) {
            .string => if (v.string.releaseDeferred()) |owner| self.queueStringRelease(owner),
            .object, .resource => |o| self.objRelease(o),
            // the stack does not count arrays, but an array leaving the stack
            // with no durable owner is an orphaned temporary (a literal or
            // call result consumed by a native); queue it so the drain frees
            // it unless a root or container still reaches it
            .array => |arr| if (arr.refcount == 0) self.queueArrayRelease(arr),
            .generator => self.genRelease(v.generator),
            .fiber => self.fiberRelease(v.fiber),
            else => {},
        }
    }

    // store a superglobal ($_SERVER, $_ENV, ...) into request_vars. that map
    // is a durable container - it must refcount its array values, or a
    // superglobal sits at refcount 0 and the first read (push/pop) frees it
    pub fn putRequestVar(self: *VM, name: []const u8, value: Value) !void {
        retainValue(value);
        const old = try self.request_vars.fetchPut(self.allocator, name, value);
        if (old) |kv| self.releaseValue(kv.value);
        if (isSuperglobal(name)) {
            const cell = self.globals_cells.get(name) orelse blk: {
                const fresh = try self.newRefCell();
                try self.bindRefSlot(&self.globals_cells, name, fresh);
                break :blk fresh;
            };
            self.setCell(cell, value);
        }
    }

    // store into the global scope's variable table (a durable holder): the
    // vars entry and its slot mirror share one reference. `Owned` takes a
    // reference the caller already holds
    pub fn putGlobalVarOwned(self: *VM, name: []const u8, value: Value) !void {
        if (isSuperglobal(name)) {
            defer self.releaseValue(value);
            try self.putRequestVar(name, value);
            return;
        }
        if (self.frame_count == 0) {
            self.releaseValue(value);
            return;
        }
        const frame = &self.frames[0];
        const old = try frame.vars.fetchPut(self.allocator, name, value);
        const snames = if (frame.func) |f| f.slot_names else frame.slot_names;
        for (snames, 0..) |sn, si| {
            if (std.mem.eql(u8, sn, name)) {
                if (si < frame.locals.len) frame.locals[si] = value;
                break;
            }
        }
        if (old) |kv| self.releaseValue(kv.value);
    }

    pub fn putGlobalVar(self: *VM, name: []const u8, value: Value) !void {
        retainValue(value);
        try self.putGlobalVarOwned(name, value);
    }
};
